-- Name: b2b_phase1_order_visible(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_phase1_order_visible(p_order uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=p_order AND public.b2b_phase1_partner_visible(o.partner_id,false));
$$;


ALTER FUNCTION platform_private.b2b_phase1_order_visible(p_order uuid) OWNER TO postgres;

--
-- Name: b2b_phase1_partner_visible(uuid, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_phase1_partner_visible(p_partner uuid, p_technical boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s record; u uuid:=auth.uid(); BEGIN
 IF u IS NULL OR p_partner IS NULL THEN RETURN false; END IF;
 IF public.is_platform_superadmin(u) THEN RETURN true; END IF;
 IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=u AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN
  RETURN public.is_valid_b2b_partner_user(u,p_partner)
   AND (public.has_role(u,'parceiro_b2b') OR (p_technical AND public.has_role(u,'parceiro_b2b_tecnico')));
 END IF;
 SELECT * INTO s FROM platform_private.b2b_actor_scope(u);
 RETURN s.profile_ok AND s.partner_valid AND s.org_partner=p_partner;
END $$;


ALTER FUNCTION platform_private.b2b_phase1_partner_visible(p_partner uuid, p_technical boolean) OWNER TO postgres;

--
-- Name: b2b_phase1_simulation_visible(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_phase1_simulation_visible(p_sim uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.partner_simulations s WHERE s.id=p_sim AND public.b2b_phase1_partner_visible(s.partner_id,true) AND (NOT public.has_role(auth.uid(),'parceiro_b2b_tecnico') OR s.created_by=auth.uid()));
$$;


ALTER FUNCTION platform_private.b2b_phase1_simulation_visible(p_sim uuid) OWNER TO postgres;

--
-- Name: b2b_provisioning_preflight(uuid, text, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_provisioning_preflight(p_partner uuid, p_role text, p_papel text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid:=auth.uid(); org uuid;
BEGIN
 org:=public.h15_actor_organization();
 IF u IS NULL OR org IS NULL OR NOT platform_private.platform_actor_access_ready(u)
 OR NOT public.has_role(u,'administrador'::public.app_role) THEN
  RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501';
 END IF;
 IF p_role NOT IN ('parceiro_b2b','parceiro_b2b_tecnico') OR p_role IS NULL
 OR p_papel IS DISTINCT FROM (CASE WHEN p_role='parceiro_b2b_tecnico' THEN 'tecnico' ELSE 'gestor' END)
 OR NOT EXISTS(SELECT 1 FROM public.partner_accounts p WHERE p.id=p_partner
   AND p.commercial_owner_organization_id=org AND p.ativo IS TRUE AND p.deleted_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo IS TRUE AND o.status='ativa')
 OR NOT EXISTS(SELECT 1 FROM platform_private.entitlements_for_user(u) e WHERE e.feature_key='catalogo_precos') THEN
  RAISE EXCEPTION 'b2b_provisioning_forbidden' USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('organization_id',org,'partner_id',p_partner,'role',p_role,'papel',p_papel,
 'enabled',false,'reason','b2b_same_tenant_channels_unverified');
END $$;


ALTER FUNCTION platform_private.b2b_provisioning_preflight(p_partner uuid, p_role text, p_papel text) OWNER TO postgres;

--
-- Name: b2b_read_simulations(uuid, uuid, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_read_simulations(p_partner_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_items boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid:=auth.uid(); tech boolean; result jsonb;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 tech:=public.has_role(u,'parceiro_b2b_tecnico');
 IF p_items THEN
  IF p_simulation_id IS NULL OR NOT platform_private.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'scope_denied' USING ERRCODE='42501'; END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN tech THEN to_jsonb(i)-ARRAY['valor_unitario_cheio','subtotal','preco_tabela_snapshot','preco_unitario','desconto_percentual'] ELSE to_jsonb(i) END ORDER BY i.created_at),'[]'::jsonb) INTO result FROM public.partner_simulation_items i WHERE i.simulation_id=p_simulation_id;
 ELSE
  SELECT coalesce(jsonb_agg((CASE WHEN tech THEN to_jsonb(s)-ARRAY['total_cheio'] ELSE to_jsonb(s) END)||jsonb_build_object('items_count',(SELECT count(*) FROM public.partner_simulation_items i WHERE i.simulation_id=s.id)) ORDER BY s.created_at DESC),'[]'::jsonb) INTO result
  FROM public.partner_simulations s WHERE (p_partner_id IS NULL OR s.partner_id=p_partner_id) AND (p_simulation_id IS NULL OR s.id=p_simulation_id)
   AND platform_private.b2b_phase1_simulation_visible(s.id)
   AND (tech OR public.is_platform_superadmin(u) OR public.has_role(u,'administrador') OR public.has_role(u,'gestor_comercial') OR public.has_role(u,'parceiro_b2b'));
 END IF;
 RETURN result;
END $$;


ALTER FUNCTION platform_private.b2b_read_simulations(p_partner_id uuid, p_simulation_id uuid, p_items boolean) OWNER TO postgres;

--
-- Name: b2b_save_technical_simulation(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.b2b_save_technical_simulation(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid:=auth.uid(); p uuid; s uuid; i jsonb; iid uuid; kind text; qty numeric; nm text; cl uuid;
BEGIN
 IF u IS NULL OR NOT public.has_role(u,'parceiro_b2b_tecnico') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF;
 p:=(p_payload->>'partner_id')::uuid;
 IF NOT platform_private.b2b_phase1_partner_visible(p,true) THEN RAISE EXCEPTION 'scope_denied' USING ERRCODE='42501'; END IF;
 IF NOT public._saas_user_has_feature(u,'simulacoes') THEN RAISE EXCEPTION 'feature_not_entitled' USING ERRCODE='42501'; END IF;
 IF coalesce(p_payload->>'status','rascunho') NOT IN ('rascunho','enviada_gestor') THEN RAISE EXCEPTION 'invalid_status'; END IF;
 IF jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array' OR jsonb_array_length(p_payload->'items')=0 THEN RAISE EXCEPTION 'empty_simulation'; END IF;
 cl:=nullif(p_payload->>'cliente_id','')::uuid;
 IF cl IS NOT NULL AND NOT (EXISTS (SELECT 1 FROM public.partner_user_clients puc WHERE puc.cliente_id=cl AND puc.user_id=u AND puc.partner_id=p AND puc.active=true) OR EXISTS (SELECT 1 FROM public.partner_technician_clients ptc WHERE ptc.cliente_id=cl AND ptc.technician_user_id=u AND ptc.partner_id=p AND ptc.active=true)) THEN RAISE EXCEPTION 'client_scope_denied' USING ERRCODE='42501'; END IF;
 INSERT INTO public.partner_simulations(partner_id,created_by,titulo,observacoes,cultura,area_total_ha,objetivo_tecnico,status,total_cheio,valid_until,cliente_id)
 VALUES(p,u,left(p_payload->>'titulo',200),left(p_payload->>'observacoes',4000),left(p_payload->>'cultura',200),(p_payload->>'area_total_ha')::numeric,left(p_payload->>'objetivo_tecnico',2000),'rascunho',0,(p_payload->>'valid_until')::date,cl) RETURNING id INTO s;
 FOR i IN SELECT * FROM jsonb_array_elements(p_payload->'items') LOOP
  iid:=(i->>'item_id')::uuid; kind:=i->>'item_tipo'; qty:=(i->>'quantidade')::numeric;
  IF qty IS NULL OR qty<=0 OR qty::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'invalid_qty'; END IF;
  IF kind='produto' THEN SELECT nome INTO nm FROM public.produtos WHERE id=iid AND ativo AND b2b_enabled;
  ELSIF kind='microrganismo' THEN SELECT nome INTO nm FROM public.microrganismos WHERE id=iid AND ativo AND b2b_enabled;
  ELSE RAISE EXCEPTION 'invalid_item'; END IF;
  IF nm IS NULL THEN RAISE EXCEPTION 'product_unavailable'; END IF;
  IF coalesce(i->>'unidade_medida','hectare') NOT IN ('hectare','litro','dose','unidade') THEN RAISE EXCEPTION 'invalid_unit'; END IF;
  IF i->>'unidade_medida'='unidade' AND coalesce((i->>'volume_ml')::numeric,0)<=0 THEN RAISE EXCEPTION 'invalid_volume'; END IF;
  INSERT INTO public.partner_simulation_items(simulation_id,item_tipo,item_id,nome,quantidade,valor_unitario_cheio,subtotal,unidade_medida,volume_ml,area_ha)
  VALUES(s,kind,iid,nm,qty,0,0,coalesce(i->>'unidade_medida','hectare'),(i->>'volume_ml')::numeric,(i->>'area_ha')::numeric);
 END LOOP;
 IF p_payload->>'status'='enviada_gestor' THEN PERFORM public.send_partner_simulation_to_manager_secure(s); END IF;
 RETURN s;
END $$;


ALTER FUNCTION platform_private.b2b_save_technical_simulation(p_payload jsonb) OWNER TO postgres;

--
-- Name: c1b_catalog_visibility_scope(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c1b_catalog_visibility_scope(p_partner uuid) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_owner uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 v_actor := platform_private.h15_actor_organization();
 IF v_actor IS NULL AND NOT public.is_platform_superadmin(auth.uid()) THEN
  RAISE EXCEPTION 'catalog_actor_unavailable' USING ERRCODE='42501'; END IF;
 IF p_partner IS NULL THEN
  SELECT o.partner_account_id INTO p_partner FROM public.organizations o WHERE o.id=v_actor;
 END IF;
 IF p_partner IS NOT NULL THEN
  SELECT pa.commercial_owner_organization_id INTO v_owner FROM public.partner_accounts pa
   JOIN public.organizations o ON o.id=pa.commercial_owner_organization_id AND o.ativo IS TRUE AND o.status='ativa'
   WHERE pa.id=p_partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'catalog_commercial_owner_unavailable' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_actor IS NULL AND v_owner IS NULL THEN RAISE EXCEPTION 'catalog_scope_unavailable' USING ERRCODE='42501'; END IF;
 RETURN array_remove(ARRAY[v_actor,v_owner],NULL);
END $$;


ALTER FUNCTION platform_private.c1b_catalog_visibility_scope(p_partner uuid) OWNER TO postgres;

--
-- Name: c2_accounting_pending_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_accounting_pending_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 -- While pending, only commercial review/quote, rejection or cancellation are possible: no approval,
 -- credit decision, economics seal, receivable, production, NF or delivery.
 -- INSERT: the canonical create may land in em_analise_comercial, aguardando_cotacao or (insufficient credit)
 -- aguardando_aprovacao_credito; nothing operational/financial may be set at creation.
 IF TG_OP='INSERT' THEN
  IF NEW.c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1' AND (
     NEW.status::text NOT IN ('em_analise_comercial','aguardando_cotacao','aguardando_aprovacao_credito')
     OR NEW.ready_for_production IS TRUE OR NEW.receivable_generated IS TRUE OR NEW.internal_economic_snapshot IS NOT NULL
     OR NEW.credit_approved_at IS NOT NULL OR NEW.approved_at IS NOT NULL) THEN
   RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
 END IF;
 IF OLD.c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1'
    AND NEW.c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1' THEN
  -- aguardando_aprovacao_credito may only stay as is (no hidden credit decision) or leave to cancel/reject.
  IF NOT (NEW.status::text IN ('em_analise_comercial','aguardando_cotacao','cancelado','reprovado')
          OR (NEW.status=OLD.status AND OLD.status::text='aguardando_aprovacao_credito'))
     OR (OLD.status::text='aguardando_aprovacao_credito' AND NEW.status::text IN ('em_analise_comercial','aguardando_cotacao'))
     OR NEW.ready_for_production IS TRUE OR NEW.receivable_generated IS TRUE OR NEW.internal_economic_snapshot IS NOT NULL
     OR NEW.credit_approved_at IS DISTINCT FROM OLD.credit_approved_at OR NEW.approved_at IS DISTINCT FROM OLD.approved_at
     -- review e1e9aa2f: no credit/financial decision field may advance by any privileged path while pending.
     OR NEW.credit_approved_by IS DISTINCT FROM OLD.credit_approved_by OR NEW.credit_approval_notes IS DISTINCT FROM OLD.credit_approval_notes
     OR NEW.approved_by IS DISTINCT FROM OLD.approved_by
     -- review 61b28: the canonical create (same txn, private create ticket) initializes not_required -> pending/not_required;
     -- any other change (e.g. -> approved) is a financial decision and stays denied while pending.
     OR (NEW.financial_approval_status IS DISTINCT FROM OLD.financial_approval_status
         AND NOT (platform_private.has_ticket('c2_external_order_create',NEW.partner_id)
                  AND OLD.financial_approval_status='not_required' AND NEW.financial_approval_status IN ('pending','not_required'))) THEN
   RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2_accounting_pending_guard() OWNER TO postgres;

--
-- Name: c2_accounting_promotion_ok(jsonb, jsonb, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_accounting_promotion_ok(o jsonb, n jsonb, order_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT coalesce(o->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1'
  AND n->>'contract'='C2_EXTERNAL_ORDER_ORIGIN_V1' AND platform_private.b2b_internal_origin_valid(n)
  AND n->>'organization_id'=o->>'organization_id' AND n->>'partner_id'=o->>'partner_id' AND n->>'actor_user_id'=o->>'actor_user_id'
  AND n->>'promoted_from_contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1'
  AND platform_private.has_ticket('c2_accounting_promote',order_id),false)
$$;


ALTER FUNCTION platform_private.c2_accounting_promotion_ok(o jsonb, n jsonb, order_id uuid) OWNER TO postgres;

--
-- Name: c2_attempt_closure_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_attempt_closure_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_key text := btrim(NEW.idempotency_key);
BEGIN
  -- Barreira durável no caminho de ESCRITA: cobre corpos antigos de create ainda em voo
  -- durante o rollout (CREATE OR REPLACE não drena execuções já iniciadas). Mesmo lock
  -- b2b_idem (reentrante para quem já o detém) + recusa se a chave foi fechada.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || NEW.partner_id::text || ':' || v_key, 0));
  IF EXISTS (SELECT 1 FROM platform_private.partner_order_idempotency_closures c
              WHERE c.partner_id = NEW.partner_id AND c.idempotency_key = v_key) THEN
    RAISE EXCEPTION 'idempotency_key_closed';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION platform_private.c2_attempt_closure_guard() OWNER TO postgres;

--
-- Name: c2_attempt_closure_immutable(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_attempt_closure_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION 'C2_ATTEMPT_CLOSURE_IMMUTABLE' USING ERRCODE = '42501';
END;
$$;


ALTER FUNCTION platform_private.c2_attempt_closure_immutable() OWNER TO postgres;

--
-- Name: c2_attempt_dispatch_guard(uuid, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_attempt_dispatch_guard(p_uid uuid, p_partner uuid, p_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
DECLARE org uuid; j platform_private.partner_order_attempt_journal;
BEGIN
 org := platform_private.c2_attempt_scope_lock(p_uid,p_partner);
 SELECT * INTO j FROM platform_private.partner_order_attempt_journal
 WHERE actor_id=p_uid AND organization_id=org AND partner_id=p_partner ORDER BY generation DESC LIMIT 1;
 IF j.idempotency_key IS DISTINCT FROM p_key OR p_key IS NULL THEN
  RAISE EXCEPTION 'C2DJ_REGISTERED_ATTEMPT_REQUIRED' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.c2_attempt_dispatch_guard(p_uid uuid, p_partner uuid, p_key text) OWNER TO postgres;

--
-- Name: c2_attempt_journal_write_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_attempt_journal_write_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
BEGIN
 -- Also fences old function bodies in flight and arbitrary old/downgraded clients.
 IF TG_OP='UPDATE' AND (NEW.partner_id,NEW.idempotency_key,NEW.created_by)
  IS DISTINCT FROM (OLD.partner_id,OLD.idempotency_key,OLD.created_by) THEN
  RAISE EXCEPTION 'C2DJ_IDENTITY_IMMUTABLE' USING ERRCODE='42501'; END IF;
 -- Fail BEFORE any scope lock; this trigger NEVER acquires scope (old body may hold idem).
 IF NOT EXISTS(SELECT 1 FROM platform_private.partner_order_attempt_journal j
  WHERE j.actor_id=auth.uid() AND j.partner_id=NEW.partner_id AND j.idempotency_key=btrim(NEW.idempotency_key)) THEN
  RAISE EXCEPTION 'C2DJ_REGISTERED_ATTEMPT_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:'||NEW.partner_id::text||':'||btrim(NEW.idempotency_key),0));
 PERFORM platform_private.c2_partner_order_attempt_authz(auth.uid(),NEW.partner_id);
 IF NEW.created_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'C2DJ_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.partner_order_attempt_journal j JOIN public.profiles p
  ON p.user_id=j.actor_id AND p.organization_id=j.organization_id AND p.ativo
  WHERE j.actor_id=auth.uid() AND j.partner_id=NEW.partner_id AND j.idempotency_key=btrim(NEW.idempotency_key)) THEN
  RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2_attempt_journal_write_guard() OWNER TO postgres;

--
-- Name: c2_attempt_scope_lock(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_attempt_scope_lock(p_uid uuid, p_partner uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
DECLARE org uuid; fresh uuid;
BEGIN
 IF p_uid IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'C2DJ_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.c2_partner_order_attempt_authz(p_uid,p_partner);
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_uid AND ativo;
 IF org IS NULL THEN RAISE EXCEPTION 'C2DJ_ORG_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('b2b_attempt_scope:'||p_uid::text||':'||org::text||':'||p_partner::text,0));
 PERFORM platform_private.c2_partner_order_attempt_authz(p_uid,p_partner);
 SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=p_uid AND ativo;
 IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 RETURN org;
END $$;


ALTER FUNCTION platform_private.c2_attempt_scope_lock(p_uid uuid, p_partner uuid) OWNER TO postgres;

--
-- Name: c2_close_partner_order_attempt_core(uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_close_partner_order_attempt_core(p_partner_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_idem text;
  v_scope_org uuid; v_current_org uuid;
  v_found boolean; v_order_id uuid; v_numero text;
BEGIN
  -- Autorização canônica ANTES do lock e de revelar qualquer estado.
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  v_scope_org := platform_private.c2_attempt_scope_lock(v_uid,p_partner_id);
  v_idem := NULLIF(btrim(COALESCE(p_idempotency_key,'')),'');
  IF v_idem IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  IF length(v_idem) > 120 THEN RAISE EXCEPTION 'invalid_idempotency_key'; END IF;

  -- MESMO lock do create. Espera limitada (lock_timeout da função): estouro => in_progress,
  -- nunca conclusivo e sem nenhuma escrita.
  BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || p_partner_id::text || ':' || v_idem, 0));
  EXCEPTION WHEN lock_not_available THEN
    RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','in_progress');
  END;

  -- Revalida APÓS a espera: revogação/perfil/parceiro inativo confirmados durante a espera
  -- abortam sem revelar committed e sem gravar closed.
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  SELECT organization_id INTO v_current_org FROM public.profiles WHERE user_id=v_uid AND ativo;
  IF v_current_org IS DISTINCT FROM v_scope_org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;

  SELECT true, i.order_id INTO v_found, v_order_id
    FROM public.partner_order_idempotency i
   WHERE i.partner_id = p_partner_id AND i.idempotency_key = v_idem;
  IF v_found THEN
    SELECT o.numero INTO v_numero FROM public.partner_orders o WHERE o.id = v_order_id;
    RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','committed',
                              'order_id', v_order_id, 'numero', v_numero);
  END IF;

  INSERT INTO platform_private.partner_order_idempotency_closures(partner_id, idempotency_key, closed_by, closed_org)
  VALUES (p_partner_id, v_idem, v_uid,
          (SELECT p.organization_id FROM public.profiles p WHERE p.user_id = v_uid))
  ON CONFLICT (partner_id, idempotency_key) DO NOTHING;
  RETURN jsonb_build_object('contract','C2_ORDER_ATTEMPT_CLOSURE_V1','state','closed');
END;
$$;


ALTER FUNCTION platform_private.c2_close_partner_order_attempt_core(p_partner_id uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: c2_commercial_owner_orders_core(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_commercial_owner_orders_core(p_status text DEFAULT NULL::text, p_partner_id uuid DEFAULT NULL::uuid, p_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_orders jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  -- Organização canônica do ator derivada no servidor: perfil ativo + org ativa.
  -- profiles.user_id tem índice único exato (pin acima, nesta transação), logo a
  -- resolução é determinística; o LIMIT 1 é defensivo. Nunca vem de parâmetro.
  SELECT p.organization_id INTO v_org
    FROM public.profiles p
    JOIN public.organizations o ON o.id = p.organization_id
   WHERE p.user_id = v_uid
     AND p.ativo = true
     AND o.ativo = true
     AND o.status = 'ativa'
   LIMIT 1;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'actor_scope_unavailable' USING ERRCODE = '42501';
  END IF;

  -- Somente administração interna da empresa dona da carteira. Papéis externos
  -- (parceiro_b2b etc.) não autorizam; superadmin sem papel interno também é
  -- negado aqui — o canal do fornecedor é a lista administrativa existente.
  -- Papel misto (administrador + papel externo) resolve pela org do perfil ativo.
  IF NOT (platform_private.has_role(v_uid, 'administrador'::public.app_role)
       OR platform_private.has_role(v_uid, 'gestor_comercial'::public.app_role)) THEN
    RAISE EXCEPTION 'actor_not_allowed' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', q.id,
           'numero', q.numero,
           'status', q.status,
           'total', q.total,
           'created_at', q.created_at,
           'requested_delivery_date', q.requested_delivery_date,
           'estimated_delivery_date', q.estimated_delivery_date,
           'partner_id', q.partner_id,
           'partner_razao_social', q.razao_social,
           'c2_external_origin_snapshot', q.c2_external_origin_snapshot
         ) ORDER BY q.created_at DESC, q.id), '[]'::jsonb)
    INTO v_orders
    FROM (
      SELECT o.id, o.numero, o.status::text AS status, o.total, o.created_at,
             o.requested_delivery_date, o.estimated_delivery_date,
             o.partner_id, o.c2_external_origin_snapshot,
             pa.razao_social
        FROM public.partner_orders o
        JOIN public.partner_accounts pa ON pa.id = o.partner_id
       WHERE pa.commercial_owner_organization_id = v_org
         AND pa.ativo IS TRUE
         AND pa.deleted_at IS NULL
         AND (p_status IS NULL OR o.status::text = p_status)
         AND (p_partner_id IS NULL OR o.partner_id = p_partner_id)
         AND (p_start IS NULL OR o.created_at >= p_start)
         AND (p_end IS NULL OR o.created_at <= p_end)
       ORDER BY o.created_at DESC, o.id
       LIMIT 200
    ) q;

  RETURN jsonb_build_object(
    'contract', 'C2_COMMERCIAL_OWNER_ORDERS_V1',
    'organization_id', v_org,
    'orders', v_orders
  );
END;
$$;


ALTER FUNCTION platform_private.c2_commercial_owner_orders_core(p_status text, p_partner_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) OWNER TO postgres;

--
-- Name: c2_external_final_state_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_external_final_state_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.c2_external_origin_snapshot IS NOT NULL AND OLD.internal_economic_snapshot IS NULL AND NEW.internal_economic_snapshot IS NOT NULL AND NEW.status IS DISTINCT FROM 'aprovado' THEN
  RAISE EXCEPTION 'C2_EXTERNAL_UNFINALIZED_APPROVAL' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2_external_final_state_guard() OWNER TO postgres;

--
-- Name: c2_external_origin_assert(jsonb, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE uid uuid:=auth.uid(); org uuid; p public.partner_accounts;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.partner_accounts WHERE id=partner FOR SHARE;
 org:=p.commercial_owner_organization_id;
 IF NOT FOUND OR p.ativo IS NOT TRUE OR p.deleted_at IS NOT NULL OR org IS NULL
 OR NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=org AND o.ativo AND o.status='ativa')
 OR EXISTS(SELECT 1 FROM public.organizations o WHERE o.partner_account_id=partner)
 OR NOT platform_private.c2_external_origin_contract_valid(s)
 OR s->>'organization_id' IS DISTINCT FROM org::text OR s->>'partner_id' IS DISTINCT FROM partner::text
 THEN RAISE EXCEPTION 'C2_EXTERNAL_ORIGIN_DENIED' USING ERRCODE='42501'; END IF;
 IF client IS DISTINCT FROM p.client_id OR (client IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=client AND c.organization_id=org))
 THEN RAISE EXCEPTION 'C2_EXTERNAL_CLIENT_DENIED' USING ERRCODE='42501'; END IF;
 -- Initial writes are authorized only inside the existing canonical create transaction.
 -- Subsequent administration uses P1's active internal owner authority, never buyer roles.
 IF platform_private.has_ticket('c2_external_order_create',partner) THEN
  IF s->>'actor_user_id' IS DISTINCT FROM uid::text OR NOT platform_private.c2_owner_order_create_allowed(uid,partner)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_CREATE_DENIED' USING ERRCODE='42501'; END IF;
  ELSE
  IF public.h15_actor_organization() IS DISTINCT FROM org OR NOT platform_private.c2p1_settings_allowed(partner,true)
  THEN RAISE EXCEPTION 'C2_EXTERNAL_OWNER_DENIED' USING ERRCODE='42501'; END IF;
 END IF;
END $$;


ALTER FUNCTION platform_private.c2_external_origin_assert(s jsonb, partner uuid, client uuid) OWNER TO postgres;

--
-- Name: c2_external_origin_contract_valid(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_external_origin_contract_valid(s jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 SELECT coalesce(
  (s->>'contract'='C2_EXTERNAL_ORDER_ORIGIN_V1' AND platform_private.b2b_internal_origin_valid(s))
  OR (jsonb_typeof(s)='object' AND s->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1' AND s->>'schema_version'='1'
      AND nullif(s->>'organization_id','') IS NOT NULL AND s->>'organization_id'=s->>'creditor_organization_id'
      AND nullif(s->>'actor_user_id','') IS NOT NULL AND nullif(s->>'partner_id','') IS NOT NULL
      AND s->'accounting_validated'='false'::jsonb
      AND NOT (s ? 'issuer_organization_id') AND NOT (s ? 'issuer_legal_name') AND NOT (s ? 'issuer_cnpj')
      AND s->>'issuer_state' IS NOT NULL),false)
$$;


ALTER FUNCTION platform_private.c2_external_origin_contract_valid(s jsonb) OWNER TO postgres;

--
-- Name: c2_internal_order_target_reason(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_internal_order_target_reason(_uid uuid, _partner uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s record; org uuid;
BEGIN
  -- Mirrors LIVE guards; NULL means allowed. Never authorizes by itself: callers must RAISE.
  IF _uid IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN 'auth_required'; END IF;
  IF NOT platform_private.b2b_internal_commercial_actor() THEN RETURN 'actor_not_allowed'; END IF;
  SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
  IF s.profile_ok IS NOT TRUE THEN RETURN 'inactive_scope'; END IF;
  IF NOT public._saas_user_has_feature(_uid,'pedidos_b2b') THEN RETURN 'feature_disabled'; END IF;
  org := public.h15_actor_organization();
  IF org IS NULL THEN RETURN 'actor_not_allowed'; END IF;
  IF _partner IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_accounts p
       WHERE p.id=_partner AND p.ativo IS TRUE AND p.deleted_at IS NULL AND p.commercial_owner_organization_id=org
         AND (p.client_id IS NULL OR EXISTS (SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=org))) THEN
    RETURN 'target_outside_portfolio';
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION platform_private.c2_internal_order_target_reason(_uid uuid, _partner uuid) OWNER TO postgres;

--
-- Name: c2_order_actor_scope(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_order_actor_scope(_uid uuid, _partner uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s record; r text;
BEGIN
  -- C2_INTERNAL_ORDER_ENTRY_V1: exclusive internal commercial actor (admin/gestor_comercial,
  -- no external B2B role) may target only its own organization's portfolio.
  IF platform_private.b2b_internal_commercial_actor() AND auth.uid() IS NOT DISTINCT FROM _uid THEN
    r := platform_private.c2_internal_order_target_reason(_uid,_partner);
    IF r IS NOT NULL OR _partner IS NULL THEN
      RAISE EXCEPTION 'C2_INTERNAL_TARGET_DENIED:%', COALESCE(r,'target_required') USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  IF public.has_role(_uid,'parceiro_b2b_tecnico'::public.app_role) AND public.has_role(_uid,'parceiro_b2b'::public.app_role)
     AND NOT public.is_platform_superadmin(_uid) THEN
    IF _uid IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
    IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
      RAISE EXCEPTION 'forbidden_financial_terms' USING ERRCODE='42501';
    END IF;
    SELECT * INTO s FROM platform_private.b2b_actor_scope(_uid);
    IF NOT s.profile_ok THEN RAISE EXCEPTION 'inactive_scope' USING ERRCODE='42501'; END IF;
    IF s.org_partner IS DISTINCT FROM _partner OR NOT s.partner_valid
       OR s.user_partner_count <> 1 OR s.user_partner IS DISTINCT FROM _partner THEN
      RAISE EXCEPTION 'forbidden_partner' USING ERRCODE='42501';
    END IF;
    RETURN;
  END IF;
  PERFORM platform_private.assert_b2b_partner_scope(_uid,_partner);
END $$;


ALTER FUNCTION platform_private.c2_order_actor_scope(_uid uuid, _partner uuid) OWNER TO postgres;

--
-- Name: c2_order_internal_recipients(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_order_internal_recipients(_partner uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT DISTINCT ur.user_id
    FROM public.partner_accounts pa
    JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id AND o.ativo IS TRUE AND o.status = 'ativa'
    JOIN public.profiles p ON p.organization_id = o.id AND p.ativo IS TRUE
    JOIN public.user_roles ur ON ur.user_id = p.user_id
   WHERE pa.id = _partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
     AND ur.role IN ('administrador'::public.app_role,'gestor_comercial'::public.app_role);
$$;


ALTER FUNCTION platform_private.c2_order_internal_recipients(_partner uuid) OWNER TO postgres;

--
-- Name: c2_order_journal_capability(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_order_journal_capability(p_partner uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
DECLARE org uuid;
BEGIN
 org:=platform_private.c2_attempt_scope_lock(auth.uid(),p_partner);
 RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','enabled',true,'actor_id',auth.uid(),'organization_id',org,'partner_id',p_partner);
END $$;


ALTER FUNCTION platform_private.c2_order_journal_capability(p_partner uuid) OWNER TO postgres;

--
-- Name: c2_order_partner_recipients(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_order_partner_recipients(_partner uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT DISTINCT pu.user_id
    FROM public.partner_users pu
    JOIN public.partner_accounts pa ON pa.id = pu.partner_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
    JOIN public.profiles p ON p.user_id = pu.user_id AND p.ativo IS TRUE AND p.organization_id = pu.tenant_id
   WHERE pu.partner_id = _partner AND pu.revoked_at IS NULL
     AND (pu.valid_from IS NULL OR pu.valid_from <= now())
     AND public.is_valid_b2b_partner_user(pu.user_id, pu.partner_id);
$$;


ALTER FUNCTION platform_private.c2_order_partner_recipients(_partner uuid) OWNER TO postgres;

--
-- Name: c2_owner_order_create_allowed(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c jsonb;
BEGIN
  -- c2_ord_writer_v1: nunca confia em parâmetro de uid que não seja o JWT atual.
  IF _uid IS NULL OR _partner IS NULL OR auth.uid() IS DISTINCT FROM _uid THEN RETURN false; END IF;
  -- Gestor B2B vigente (user_roles canônico; revogação remove a linha). Técnico isolado nunca compra.
  IF NOT public.has_role(_uid,'parceiro_b2b'::public.app_role) THEN RETURN false; END IF;
  c := platform_private.b2b_commercial_context();
  IF c IS NULL OR c->>'contract' <> 'C2_MULTIPROFILE_V1' OR c->>'mode' <> 'commercial_owner'
     OR (c->>'partner_id')::uuid IS DISTINCT FROM _partner OR COALESCE((c->>'manager')::boolean,false) IS NOT TRUE THEN
    RETURN false;
  END IF;
  -- Cliente comercial = sem organização própria; tenant dono ativo e coerente com perfil/vínculo.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN false; END IF;
  IF NOT COALESCE(platform_private.b2b_phase1_partner_visible(_partner,true),false) THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      JOIN public.profiles p ON p.user_id = pu.user_id
      JOIN public.organizations o ON o.id = pa.commercial_owner_organization_id
     WHERE pu.user_id = _uid AND pu.partner_id = _partner
       AND pu.revoked_at IS NULL AND (pu.valid_from IS NULL OR pu.valid_from <= now())
       AND pa.ativo AND pa.deleted_at IS NULL AND o.ativo AND o.status = 'ativa'
       AND (o.partner_account_id IS NULL OR o.partner_account_id = _partner)
       AND p.ativo AND p.organization_id = pu.tenant_id AND pu.tenant_id = o.id
       AND (c->>'tenant_id')::uuid = o.id
       AND public.is_valid_b2b_partner_user(_uid, pa.id)) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'pedidos_b2b')
     AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos');
END $$;


ALTER FUNCTION platform_private.c2_owner_order_create_allowed(_uid uuid, _partner uuid) OWNER TO postgres;

--
-- Name: c2_owner_order_guard(uuid, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_owner_order_guard(_uid uuid, _partner uuid, _plan uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Internos e superadmin seguem as regras existentes da função chamadora.
  IF public.is_platform_superadmin(_uid)
     OR public.has_role(_uid,'administrador'::public.app_role) OR public.has_role(_uid,'financeiro'::public.app_role)
     OR public.has_role(_uid,'gestor_comercial'::public.app_role) THEN
    RETURN;
  END IF;
  -- Parceiro com organização própria (fornecedor legado): comportamento inalterado.
  IF EXISTS (SELECT 1 FROM public.organizations o WHERE o.partner_account_id = _partner) THEN RETURN; END IF;
  IF NOT platform_private.c2_owner_order_create_allowed(_uid,_partner) THEN
    RAISE EXCEPTION 'C2_OWNER_ORDER_CLOSED' USING ERRCODE='42501';
  END IF;
  IF _plan IS NULL OR NOT platform_private.c2_owner_plan_assigned(_partner,_plan) THEN
    RAISE EXCEPTION 'plan_not_assigned' USING ERRCODE='42501';
  END IF;
END $$;


ALTER FUNCTION platform_private.c2_owner_order_guard(_uid uuid, _partner uuid, _plan uuid) OWNER TO postgres;

--
-- Name: c2_owner_plan_assigned(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_owner_plan_assigned(_partner uuid, _plan uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT public.fn_b2b_plan_selectable(_plan) AND EXISTS (
    SELECT 1 FROM public.commercial_payment_plan_assignments a
     WHERE a.plan_id = _plan AND a.partner_id = _partner
       AND a.buyer_scope = 'partner' AND a.status = 'published'
       AND a.valid_from <= CURRENT_DATE AND (a.valid_until IS NULL OR a.valid_until >= CURRENT_DATE));
$$;


ALTER FUNCTION platform_private.c2_owner_plan_assigned(_partner uuid, _plan uuid) OWNER TO postgres;

--
-- Name: c2_partner_lifecycle(uuid, uuid, text[], text, text, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_partner_lifecycle(p_partner_id uuid, p_user_id uuid, p_roles text[], p_action text, p_expected text, p_key uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
 actor uuid:=auth.uid(); org uuid; before_state jsonb; after_state jsonb;
 existing_receipt record; fingerprint text; requested text[]; current_roles text[];
 link public.partner_users%ROWTYPE; result jsonb; partner_owner uuid;
BEGIN
 -- Authority is ALWAYS the caller subject, never a payload actor or owner.
 IF actor IS NULL OR actor=p_user_id OR p_partner_id IS NULL OR p_user_id IS NULL
 OR platform_private.platform_actor_access_ready(actor) IS NOT TRUE
 OR public.has_role(actor,'administrador'::public.app_role) IS NOT TRUE
 OR public.is_platform_superadmin(actor) IS TRUE
 OR public.is_platform_superadmin(p_user_id) IS TRUE THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR p_key IS NULL OR p_expected IS NULL
 OR length(p_expected)<>32 OR p_expected !~ '^[a-f0-9]{32}$'
 OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 2 AND 500
 OR p_action IS NULL OR p_action NOT IN ('assign','revoke_roles','unlink','reactivate')
 OR p_roles IS NULL OR array_position(p_roles,NULL) IS NOT NULL
 OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor'))
 OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) THEN
  RAISE EXCEPTION 'c2_invalid_input' USING ERRCODE='22023'; END IF;
 SELECT array_agg(r ORDER BY r) INTO requested FROM unnest(p_roles) r;
 requested:=COALESCE(requested,ARRAY[]::text[]);
 fingerprint:=md5(jsonb_build_object('partner',p_partner_id,'user',p_user_id,
   'roles',requested,'action',p_action,'expected',p_expected,'reason',btrim(p_reason))::text);
 -- Preauthorization before waiting. Historical revoked links are still editable
 -- by their proven owner, but never usable to authorize portal data.
 IF NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
   WHERE p.user_id=p_user_id AND p.organization_id=org AND p.ativo AND o.ativo AND o.status='ativa'
   AND platform_private.platform_actor_access_ready(p.user_id))
 OR NOT EXISTS(SELECT 1 FROM public.partner_accounts pa JOIN public.organizations o ON o.id=pa.commercial_owner_organization_id
   WHERE pa.id=p_partner_id AND pa.commercial_owner_organization_id=org AND pa.ativo
   AND pa.deleted_at IS NULL AND o.ativo AND o.status='ativa') THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 -- Same lock order as the existing statement gate, BEFORE profile/role/link locks.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'c2_guard_unavailable' USING ERRCODE='55000'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner_id FOR SHARE;
 PERFORM 1 FROM public.profiles WHERE user_id IN(actor,p_user_id) ORDER BY user_id FOR UPDATE;
 PERFORM 1 FROM public.user_roles WHERE user_id IN(actor,p_user_id) ORDER BY user_id,role FOR UPDATE;
 SELECT * INTO link FROM public.partner_users WHERE user_id=p_user_id FOR UPDATE;
 IF link.id IS NOT NULL AND (link.partner_id IS DISTINCT FROM p_partner_id OR link.tenant_id IS DISTINCT FROM org) THEN
  RAISE EXCEPTION 'c2_cross_partner' USING ERRCODE='42501'; END IF;
 SELECT commercial_owner_organization_id INTO partner_owner FROM public.partner_accounts WHERE id=p_partner_id AND ativo AND deleted_at IS NULL;
 IF partner_owner IS DISTINCT FROM org OR public.h15_actor_organization() IS DISTINCT FROM org
 OR platform_private.platform_actor_access_ready(actor) IS NOT TRUE
 OR public.has_role(actor,'administrador'::public.app_role) IS NOT TRUE
 OR public.is_platform_superadmin(actor) OR public.is_platform_superadmin(p_user_id)
 OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user_id AND organization_id=org AND ativo
   AND platform_private.platform_actor_access_ready(user_id))
 OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND ativo AND status='ativa') THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 -- Replay before state/roles validation: a subsequent revocation cannot cause
 -- the same committed attempt to grant again or become a false conflict.
 SELECT * INTO existing_receipt FROM public.partner_audit_logs
  WHERE acao='c2_partner_lifecycle' AND usuario_id=actor
    AND dados_novos->>'key'=p_key::text LIMIT 1;
 IF FOUND THEN
  IF existing_receipt.dados_novos->>'fingerprint' IS DISTINCT FROM fingerprint THEN
   RAISE EXCEPTION 'c2_replay_conflict' USING ERRCODE='PT409'; END IF;
  RETURN existing_receipt.dados_novos->'receipt';
 END IF;
 SELECT COALESCE(array_agg(role::text ORDER BY role::text),ARRAY[]::text[]) INTO current_roles FROM public.user_roles WHERE user_id=p_user_id;
 IF EXISTS(SELECT 1 FROM unnest(current_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN
  RAISE EXCEPTION 'c2_internal_identity_closed' USING ERRCODE='42501'; END IF;
 before_state:=jsonb_build_object('user',p_user_id,'partner',p_partner_id,'org',org,
   'roles',current_roles,'link',CASE WHEN link.id IS NULL THEN NULL ELSE to_jsonb(link) END,
   'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=p_user_id));
 IF md5(before_state::text)<>p_expected THEN RAISE EXCEPTION 'c2_version_conflict' USING ERRCODE='PT409'; END IF;
 IF p_action IN ('unlink','reactivate') AND requested IS DISTINCT FROM current_roles THEN
  RAISE EXCEPTION 'c2_roles_must_be_preserved' USING ERRCODE='22023'; END IF;
 IF p_action='revoke_roles' AND EXISTS(SELECT 1 FROM unnest(requested) r WHERE NOT r=ANY(current_roles)) THEN
  RAISE EXCEPTION 'c2_revocation_cannot_grant' USING ERRCODE='42501'; END IF;
 IF p_action='assign' AND link.id IS NOT NULL AND link.revoked_at IS NOT NULL THEN
  RAISE EXCEPTION 'c2_explicit_reactivation_required' USING ERRCODE='42501'; END IF;
 IF p_action IN ('unlink','reactivate') AND link.id IS NULL THEN
  RAISE EXCEPTION 'c2_link_missing' USING ERRCODE='22023'; END IF;
 IF p_action='reactivate' AND link.revoked_at IS NULL THEN
  RAISE EXCEPTION 'c2_not_revoked' USING ERRCODE='22023'; END IF;
 -- This slice does not create/transfer clients or adopt an Auth identity.
 -- Producer requires an explicit live client AND property, never UUID alone.
 IF 'cliente_produtor'=ANY(requested) AND p_action='assign' THEN
  PERFORM 1 FROM public.user_clientes WHERE user_id=p_user_id ORDER BY id FOR SHARE;
  PERFORM 1 FROM public.clientes c WHERE EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_user_id AND uc.cliente_id=c.id) ORDER BY c.id FOR SHARE;
  PERFORM 1 FROM public.fazendas f WHERE EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_user_id AND uc.cliente_id=f.cliente_id) ORDER BY f.id FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.user_clientes uc JOIN public.clientes c ON c.id=uc.cliente_id
    JOIN public.fazendas f ON f.cliente_id=c.id
    WHERE uc.user_id=p_user_id AND uc.is_active AND uc.revoked_at IS NULL
      AND uc.valid_from<=now() AND (uc.valid_until IS NULL OR uc.valid_until>=now())
      AND c.organization_id=org AND c.status_cliente='ativo'
      AND f.organization_id=org AND f.ativo) THEN
   RAISE EXCEPTION 'c2_producer_link_required' USING ERRCODE='42501'; END IF;
 END IF;
 IF p_action='assign' AND link.id IS NULL AND NOT ('parceiro_b2b'=ANY(requested) OR 'parceiro_b2b_tecnico'=ANY(requested)) THEN
  RAISE EXCEPTION 'c2_partner_role_required' USING ERRCODE='22023'; END IF;
 IF p_action IN ('assign','revoke_roles') THEN
  DELETE FROM public.user_roles WHERE user_id=p_user_id AND role::text=ANY(current_roles) AND NOT role::text=ANY(requested);
  INSERT INTO public.user_roles(user_id,role) SELECT p_user_id,r::public.app_role FROM unnest(requested) r
   WHERE NOT r=ANY(current_roles) ON CONFLICT(user_id,role) DO NOTHING;
 END IF;
 IF p_action='assign' AND link.id IS NULL THEN
  INSERT INTO public.partner_users(user_id,partner_id,papel,tenant_id)
   VALUES(p_user_id,p_partner_id,CASE WHEN 'parceiro_b2b'=ANY(requested) THEN 'gestor' ELSE 'tecnico' END,org);
 ELSIF p_action IN ('assign','revoke_roles') AND link.id IS NOT NULL
   AND ('parceiro_b2b'=ANY(requested) OR 'parceiro_b2b_tecnico'=ANY(requested)) THEN
  UPDATE public.partner_users SET papel=CASE WHEN 'parceiro_b2b'=ANY(requested) THEN 'gestor' ELSE 'tecnico' END WHERE id=link.id;
 ELSIF p_action='unlink' THEN
  UPDATE public.partner_users SET revoked_at=clock_timestamp(),revoked_by=actor,revoke_reason=btrim(p_reason) WHERE id=link.id AND revoked_at IS NULL;
 ELSIF p_action='reactivate' THEN
  UPDATE public.partner_users SET revoked_at=NULL,revoked_by=NULL,revoke_reason=NULL,valid_from=clock_timestamp() WHERE id=link.id;
 END IF;
 -- No role INSERT on reactivation/unlink. Independent producer remains untouched.
 SELECT jsonb_build_object('user',p_user_id,'partner',p_partner_id,'org',org,'roles',requested,
   'link',(SELECT to_jsonb(pu) FROM public.partner_users pu WHERE pu.user_id=p_user_id),
   'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=p_user_id)) INTO after_state;
 result:=jsonb_build_object('ok',true,'user_id',p_user_id,'partner_id',p_partner_id,
   'version',md5(after_state::text),'action',p_action,'reader_activation',false);
 INSERT INTO public.partner_audit_logs(partner_id,usuario_id,acao,dados_anteriores,dados_novos)
 VALUES(p_partner_id,actor,'c2_partner_lifecycle',before_state,
   jsonb_build_object('key',p_key,'fingerprint',fingerprint,'reason',btrim(p_reason),'state',after_state,'receipt',result));
 RETURN result;
END $_$;


ALTER FUNCTION platform_private.c2_partner_lifecycle(p_partner_id uuid, p_user_id uuid, p_roles text[], p_action text, p_expected text, p_key uuid, p_reason text) OWNER TO postgres;

--
-- Name: c2_partner_order_attempt_authz(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_partner_order_attempt_authz(p_uid uuid, p_partner_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_is_internal boolean; v_is_partner boolean; v_is_partner_tech boolean; v_user_partner uuid;
BEGIN
  -- Espelha a autorização do create canônico (mesma ordem/mensagens). Chamado antes E
  -- depois do lock b2b_idem; cada chamada lê um snapshot novo (READ COMMITTED).
  IF p_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  PERFORM platform_private.c2_order_actor_scope(p_uid, p_partner_id);
  v_is_internal := public.has_role(p_uid,'administrador'::public.app_role)
                OR public.has_role(p_uid,'financeiro'::public.app_role)
                OR public.has_role(p_uid,'gestor_comercial'::public.app_role);
  v_is_partner      := public.has_role(p_uid,'parceiro_b2b'::public.app_role);
  v_is_partner_tech := public.has_role(p_uid,'parceiro_b2b_tecnico'::public.app_role);
  v_user_partner    := public.get_user_partner_id();
  IF public.has_role(p_uid,'cliente_produtor'::public.app_role) AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED';
  END IF;
  IF v_is_partner_tech AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'partner_tech_cannot_create_order';
  END IF;
  IF NOT v_is_internal THEN
    IF NOT v_is_partner OR v_user_partner IS NULL OR v_user_partner <> p_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;
  PERFORM 1 FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'partner_not_found'; END IF;
END;
$$;


ALTER FUNCTION platform_private.c2_partner_order_attempt_authz(p_uid uuid, p_partner_id uuid) OWNER TO postgres;

--
-- Name: c2_producer_links(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_producer_links(p_user uuid, p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT platform_private.platform_actor_access_ready(p_user)
 AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
 JOIN public.user_clientes uc ON uc.user_id=p.user_id JOIN public.clientes c ON c.id=uc.cliente_id
 JOIN public.fazendas f ON f.cliente_id=c.id
 WHERE p.user_id=p_user AND p.organization_id=p_org AND p.ativo AND o.ativo AND o.status='ativa'
 AND uc.is_active AND uc.revoked_at IS NULL AND uc.valid_from<=now()
 AND (uc.valid_until IS NULL OR uc.valid_until>=now())
 AND c.organization_id=p_org AND c.status_cliente='ativo' AND f.organization_id=p_org AND f.ativo);
$$;


ALTER FUNCTION platform_private.c2_producer_links(p_user uuid, p_org uuid) OWNER TO postgres;

--
-- Name: c2_promote_accounting_pending_order_core(uuid, timestamp with time zone); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_promote_accounting_pending_order_core(p_order_id uuid, p_expected_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE uid uuid:=auth.uid(); o public.partner_orders; cs public.company_fiscal_settings; n integer; org uuid; v1 jsonb;
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.b2b_internal_commercial_actor() THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL OR p_order_id IS NULL THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 -- Rows of other organizations do not satisfy the predicate and are skipped without being locked or waited on.
 SELECT * INTO o FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot->>'organization_id'=org::text FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501'; END IF;
 -- Re-validate authority under the lock (revocation / organization change during the wait).
 IF NOT platform_private.b2b_internal_commercial_actor()
    OR public.h15_actor_organization() IS DISTINCT FROM org
    OR o.c2_external_origin_snapshot->>'organization_id' IS DISTINCT FROM org::text
    OR NOT platform_private.c2p1_settings_allowed(o.partner_id,true) THEN
  RAISE EXCEPTION 'C2AP_ORDER_DENIED' USING ERRCODE='42501';
 END IF;
 IF o.c2_external_origin_snapshot->>'contract' IS DISTINCT FROM 'C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1' THEN RAISE EXCEPTION 'C2AP_NOT_PENDING' USING ERRCODE='22023'; END IF;
 IF p_expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'C2AP_STALE' USING ERRCODE='PT409'; END IF;
 IF o.status::text NOT IN ('em_analise_comercial','aguardando_cotacao','aguardando_aprovacao_credito') THEN RAISE EXCEPTION 'C2AP_STATUS_DENIED' USING ERRCODE='42501'; END IF;
 SELECT count(*) INTO n FROM public.company_fiscal_settings c WHERE c.organization_id=org AND c.is_active;
 IF n=1 THEN SELECT * INTO cs FROM public.company_fiscal_settings c WHERE c.organization_id=org AND c.is_active FOR SHARE; END IF;
 IF n<>1 OR cs.configuration_status IS DISTINCT FROM 'VALIDATED' OR cs.accounting_validated_at IS NULL OR nullif(btrim(cs.legal_name),'') IS NULL OR nullif(btrim(cs.cnpj),'') IS NULL THEN
  RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501';
 END IF;
 v1:=jsonb_build_object('contract','C2_EXTERNAL_ORDER_ORIGIN_V1','schema_version','1','organization_id',org,'creditor_organization_id',org,'issuer_organization_id',org,'company_settings_id',cs.id,'company_configuration_version',cs.configuration_version,'issuer_legal_name',cs.legal_name,'issuer_cnpj',cs.cnpj,'actor_user_id',o.c2_external_origin_snapshot->>'actor_user_id','partner_id',o.partner_id,'promoted_from_contract','C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1','accounting_promoted_by',uid,'accounting_promoted_at',now());
 PERFORM platform_private.issue_ticket('c2_accounting_promote',p_order_id);
 UPDATE public.partner_orders SET c2_external_origin_snapshot=v1, updated_at=now() WHERE id=p_order_id;
 INSERT INTO public.partner_order_audit_logs(id,order_id,partner_id,usuario_id,acao,dados_anteriores,dados_novos,created_at)
 VALUES(gen_random_uuid(),p_order_id,o.partner_id,uid,'c2_accounting_pending_promoted',jsonb_build_object('origin',o.c2_external_origin_snapshot),jsonb_build_object('origin',v1),now());
 RETURN jsonb_build_object('order_id',p_order_id,'contract','C2_EXTERNAL_ORDER_ORIGIN_V1');
END $$;


ALTER FUNCTION platform_private.c2_promote_accounting_pending_order_core(p_order_id uuid, p_expected_updated_at timestamp with time zone) OWNER TO postgres;

--
-- Name: c2_recover_order_attempt_core(uuid, text, bigint, boolean, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2_recover_order_attempt_core(p_partner uuid, p_expected_key text DEFAULT NULL::text, p_expected_generation bigint DEFAULT NULL::bigint, p_advance boolean DEFAULT false, p_ack_order uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '5s'
    AS $$
DECLARE uid uuid:=auth.uid(); org uuid; j platform_private.partner_order_attempt_journal;
  result jsonb; nextgen bigint; nextkey text; fresh uuid; predecessors jsonb;
BEGIN
 org := platform_private.c2_attempt_scope_lock(uid,p_partner);
 SELECT * INTO j FROM platform_private.partner_order_attempt_journal
 WHERE actor_id=uid AND organization_id=org AND partner_id=p_partner ORDER BY generation DESC LIMIT 1;
 -- Immutable journal links plus canonical committed receipts/closure tombstones.
 -- Read only: no inferred closure, no added locks, no client-supplied terminal proof.
 SELECT coalesce(jsonb_agg(jsonb_build_object('key',h.idempotency_key,'generation',h.generation,
   'state',CASE WHEN i.order_id IS NOT NULL THEN 'committed' WHEN c.idempotency_key IS NOT NULL THEN 'closed' ELSE 'unknown' END)
   || CASE WHEN i.order_id IS NOT NULL THEN jsonb_build_object('order_id',i.order_id,'numero',o.numero) ELSE '{}'::jsonb END
   ORDER BY h.generation),'[]'::jsonb) INTO predecessors
 FROM platform_private.partner_order_attempt_journal h
 LEFT JOIN public.partner_order_idempotency i ON i.partner_id=h.partner_id AND i.idempotency_key=h.idempotency_key AND i.created_by=uid
 LEFT JOIN public.partner_orders o ON o.id=i.order_id
 LEFT JOIN platform_private.partner_order_idempotency_closures c ON c.partner_id=h.partner_id AND c.idempotency_key=h.idempotency_key
 WHERE h.actor_id=uid AND h.organization_id=org AND h.partner_id=p_partner AND h.generation<j.generation;
 IF p_advance THEN
  IF j.idempotency_key IS NULL OR p_expected_key IS DISTINCT FROM j.idempotency_key
   OR p_expected_generation IS DISTINCT FROM j.generation THEN
   RAISE EXCEPTION 'C2DJ_CAS_CONFLICT' USING ERRCODE='PT409'; END IF;
  -- Explicit click only; existing atomic close is the ONLY way to abandon uncertain K.
  result := platform_private.c2_close_partner_order_attempt_core(p_partner,j.idempotency_key);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  IF result->>'state'='in_progress' THEN RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','unknown'); END IF;
  IF result->>'state'='committed' AND p_ack_order IS DISTINCT FROM (result->>'order_id')::uuid THEN
   RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors); END IF;
  IF result->>'state' NOT IN ('closed','committed') OR result->>'state' IS NULL THEN
   RAISE EXCEPTION 'C2DJ_INVALID_CLOSURE'; END IF;
  predecessors:=predecessors||jsonb_build_array(result||jsonb_build_object('key',j.idempotency_key,'generation',j.generation));
 ELSIF j.idempotency_key IS NOT NULL THEN
  -- Recovery is read-only with respect to closure; never auto-close an absent order.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:'||p_partner::text||':'||j.idempotency_key,0));
  PERFORM platform_private.c2_partner_order_attempt_authz(uid,p_partner);
  SELECT organization_id INTO fresh FROM public.profiles WHERE user_id=uid AND ativo;
  IF fresh IS DISTINCT FROM org THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  SELECT jsonb_build_object('state','committed','order_id',i.order_id,'numero',o.numero) INTO result
   FROM public.partner_order_idempotency i JOIN public.partner_orders o ON o.id=i.order_id
   WHERE i.partner_id=p_partner AND i.idempotency_key=j.idempotency_key AND i.created_by=uid;
  IF result IS NULL THEN
   result := jsonb_build_object('state',CASE WHEN EXISTS(SELECT 1 FROM platform_private.partner_order_idempotency_closures
    WHERE partner_id=p_partner AND idempotency_key=j.idempotency_key) THEN 'closed' ELSE 'uncertain' END);
  END IF;
  RETURN result || jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','key',j.idempotency_key,'generation',j.generation,'predecessors',predecessors);
 ELSIF p_expected_key IS NOT NULL OR p_expected_generation IS NOT NULL THEN
  -- Lost legacy memory cannot be adopted by mere key knowledge.
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501';
 END IF;
 nextgen := coalesce(j.generation,0)+1; nextkey := gen_random_uuid()::text;
 IF j.idempotency_key IS NULL AND EXISTS(SELECT 1 FROM public.partner_order_idempotency i
 WHERE i.created_by=uid AND i.partner_id=p_partner) THEN
  RAISE EXCEPTION 'C2DJ_LEGACY_RECONCILIATION_REQUIRED' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.partner_order_attempt_journal(actor_id,organization_id,partner_id,generation,idempotency_key,predecessor_key)
 VALUES(uid,org,p_partner,nextgen,nextkey,j.idempotency_key);
 RETURN jsonb_build_object('contract','C2_ORDER_JOURNAL_V1','state','reserved','key',nextkey,'generation',nextgen,'predecessors',predecessors);
END $$;


ALTER FUNCTION platform_private.c2_recover_order_attempt_core(p_partner uuid, p_expected_key text, p_expected_generation bigint, p_advance boolean, p_ack_order uuid) OWNER TO postgres;

--
-- Name: c2p1_assignment_allowed(text, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_assignment_allowed(p_scope text, p_partner uuid, p_customer uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE(CASE
 WHEN p_scope='partner' AND p_partner IS NOT NULL AND p_customer IS NULL THEN EXISTS(
 SELECT 1 FROM public.partner_accounts pa JOIN public.organizations owner ON owner.id=pa.commercial_owner_organization_id
 WHERE pa.id=p_partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL AND owner.ativo IS TRUE AND owner.status='ativa'
 AND owner.id=platform_private.c2p1_internal_actor(ARRAY['administrador','financeiro','gestor_comercial']::public.app_role[]))
 WHEN p_scope='producer' AND p_partner IS NULL AND p_customer IS NOT NULL THEN EXISTS(
 SELECT 1 FROM public.clientes c JOIN public.organizations o ON o.id=c.organization_id
 WHERE c.id=p_customer AND c.status_cliente='ativo' AND o.ativo IS TRUE AND o.status='ativa'
 AND o.id=platform_private.c2p1_internal_actor(ARRAY['administrador','financeiro','gestor_comercial']::public.app_role[]))
 ELSE false END,false);
$$;


ALTER FUNCTION platform_private.c2p1_assignment_allowed(p_scope text, p_partner uuid, p_customer uuid) OWNER TO postgres;

--
-- Name: c2p1_assignment_children_fence(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_assignment_children_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.assignment_id=OLD.id
 AND (i.plan_id IS DISTINCT FROM NEW.plan_id OR i.buyer_scope IS DISTINCT FROM NEW.buyer_scope OR i.partner_id IS DISTINCT FROM NEW.partner_id OR i.customer_id IS DISTINCT FROM NEW.customer_id))
 THEN RAISE EXCEPTION 'C2P1_ASSIGNMENT_LINK_IMMUTABLE' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;


ALTER FUNCTION platform_private.c2p1_assignment_children_fence() OWNER TO postgres;

--
-- Name: c2p1_assignment_fence(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_assignment_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'C2P1_ASSIGNMENT_DELETE_CLOSED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),
 (SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=NEW.partner_id),
 (SELECT organization_id FROM public.clientes WHERE id=NEW.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (NEW.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN (NEW.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF TG_OP='UPDATE' AND NOT platform_private.c2p1_assignment_allowed(OLD.buyer_scope,OLD.partner_id,OLD.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NOT platform_private.c2p1_assignment_allowed(NEW.buyer_scope,NEW.partner_id,NEW.customer_id)
 THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2p1_assignment_fence() OWNER TO postgres;

--
-- Name: c2p1_history_allowed(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_history_allowed(p_entity text, p_id uuid, p_before jsonb, p_after jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE(p_id IS NOT NULL AND p_entity IN ('assignment','item_price')
 AND platform_private.c2p1_snapshot_allowed(p_entity,p_id,p_before)
 AND platform_private.c2p1_snapshot_allowed(p_entity,p_id,p_after)
 AND CASE WHEN p_entity='assignment' THEN EXISTS(SELECT 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id))
 ELSE EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.id=p_id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id)) END,false);
$$;


ALTER FUNCTION platform_private.c2p1_history_allowed(p_entity text, p_id uuid, p_before jsonb, p_after jsonb) OWNER TO postgres;

--
-- Name: c2p1_internal_actor(public.app_role[]); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_internal_actor(p_roles public.app_role[]) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.h15_actor_organization() WHERE auth.uid() IS NOT NULL
 AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
 WHERE p.user_id=auth.uid() AND p.ativo IS TRUE AND o.ativo IS TRUE AND o.status='ativa'
 AND platform_private.platform_actor_access_ready(p.user_id))
 AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=ANY(p_roles))
 AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()
 AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor'));
$$;


ALTER FUNCTION platform_private.c2p1_internal_actor(p_roles public.app_role[]) OWNER TO postgres;

--
-- Name: c2p1_item_allowed(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_item_allowed(p_assignment uuid, p_plan uuid, p_scope text, p_partner uuid, p_customer uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT platform_private.c2p1_assignment_allowed(p_scope,p_partner,p_customer) AND
 (p_assignment IS NULL OR EXISTS(SELECT 1 FROM public.commercial_payment_plan_assignments a
 WHERE a.id=p_assignment AND a.plan_id=p_plan AND a.buyer_scope=p_scope
 AND a.partner_id IS NOT DISTINCT FROM p_partner AND a.customer_id IS NOT DISTINCT FROM p_customer
 AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id)));
$$;


ALTER FUNCTION platform_private.c2p1_item_allowed(p_assignment uuid, p_plan uuid, p_scope text, p_partner uuid, p_customer uuid) OWNER TO postgres;

--
-- Name: c2p1_item_fence(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_item_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.commercial_condition_item_prices;
BEGIN
 IF TG_OP='DELETE' THEN r=OLD; ELSE r=NEW; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),(SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=r.partner_id),(SELECT organization_id FROM public.clientes WHERE id=r.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN(r.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN(r.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.commercial_payment_plan_assignments WHERE id IN(r.assignment_id,CASE WHEN TG_OP='UPDATE' THEN OLD.assignment_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF NOT platform_private.c2p1_item_allowed(r.assignment_id,r.plan_id,r.buyer_scope,r.partner_id,r.customer_id)
 OR (TG_OP='UPDATE' AND NOT platform_private.c2p1_item_allowed(OLD.assignment_id,OLD.plan_id,OLD.buyer_scope,OLD.partner_id,OLD.customer_id)) THEN
 RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at) THEN RAISE EXCEPTION 'C2P1_IDENTITY_IMMUTABLE' USING ERRCODE='42501'; END IF;
 IF TG_OP<>'DELETE' AND r.published_rule_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.commercial_price_rules pr WHERE pr.id=r.published_rule_id AND pr.plan_id=r.plan_id AND pr.buyer_scope=r.buyer_scope
 AND pr.partner_id IS NOT DISTINCT FROM r.partner_id AND pr.customer_id IS NOT DISTINCT FROM r.customer_id
 AND pr.product_id IS NOT DISTINCT FROM r.product_id AND pr.microrganismo_id IS NOT DISTINCT FROM r.microrganismo_id
 AND pr.unit_type=r.unit_type AND pr.volume_ml IS NOT DISTINCT FROM r.volume_ml) THEN RAISE EXCEPTION 'C2P1_RULE_LINK_INVALID' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2p1_item_fence() OWNER TO postgres;

--
-- Name: c2p1_rule_fence(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_rule_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.commercial_price_rules;
BEGIN
 IF TG_OP='DELETE' THEN r=OLD; ELSE r=NEW; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id IN (public.h15_actor_organization(),(SELECT commercial_owner_organization_id FROM public.partner_accounts WHERE id=r.partner_id),(SELECT organization_id FROM public.clientes WHERE id=r.customer_id)) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id IN(r.partner_id,CASE WHEN TG_OP='UPDATE' THEN OLD.partner_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 PERFORM 1 FROM public.clientes WHERE id IN(r.customer_id,CASE WHEN TG_OP='UPDATE' THEN OLD.customer_id ELSE NULL END) ORDER BY id FOR SHARE NOWAIT;
 IF NOT platform_private.c2p1_assignment_allowed(r.buyer_scope,r.partner_id,r.customer_id)
 OR (TG_OP='UPDATE' AND NOT platform_private.c2p1_assignment_allowed(OLD.buyer_scope,OLD.partner_id,OLD.customer_id)) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.published_rule_id=OLD.id AND (NEW.id IS DISTINCT FROM OLD.id OR i.plan_id IS DISTINCT FROM NEW.plan_id OR i.buyer_scope IS DISTINCT FROM NEW.buyer_scope OR i.partner_id IS DISTINCT FROM NEW.partner_id OR i.customer_id IS DISTINCT FROM NEW.customer_id OR i.product_id IS DISTINCT FROM NEW.product_id OR i.microrganismo_id IS DISTINCT FROM NEW.microrganismo_id OR i.unit_type IS DISTINCT FROM NEW.unit_type OR i.volume_ml IS DISTINCT FROM NEW.volume_ml)) THEN RAISE EXCEPTION 'C2P1_RULE_LINK_IMMUTABLE' USING ERRCODE='42501'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2p1_rule_fence() OWNER TO postgres;

--
-- Name: c2p1_rule_log_allowed(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_rule_log_allowed(p_action text, p_partner uuid, p_before jsonb, p_after jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT COALESCE(p_action IN ('price_rule_insert','price_rule_update','price_rule_delete')
 AND (p_before IS NOT NULL OR p_after IS NOT NULL)
 AND platform_private.c2p1_rule_snapshot_allowed(p_before,p_partner)
 AND platform_private.c2p1_rule_snapshot_allowed(p_after,p_partner),false);
$$;


ALTER FUNCTION platform_private.c2p1_rule_log_allowed(p_action text, p_partner uuid, p_before jsonb, p_after jsonb) OWNER TO postgres;

--
-- Name: c2p1_rule_snapshot_allowed(jsonb, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_rule_snapshot_allowed(p_data jsonb, p_partner uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN
 IF p_data IS NULL THEN RETURN true; END IF;
 RETURN jsonb_typeof(p_data)='object' AND p_data ? 'buyer_scope'
 AND (p_data->>'partner_id')::uuid IS NOT DISTINCT FROM p_partner
 AND platform_private.c2p1_assignment_allowed(p_data->>'buyer_scope',(p_data->>'partner_id')::uuid,(p_data->>'customer_id')::uuid)
 AND EXISTS(SELECT 1 FROM public.commercial_price_rules r WHERE r.id=(p_data->>'id')::uuid
 AND r.buyer_scope=p_data->>'buyer_scope' AND r.partner_id IS NOT DISTINCT FROM (p_data->>'partner_id')::uuid
 AND r.customer_id IS NOT DISTINCT FROM (p_data->>'customer_id')::uuid
 AND platform_private.c2p1_assignment_allowed(r.buyer_scope,r.partner_id,r.customer_id));
 EXCEPTION WHEN invalid_text_representation THEN RETURN false; END $$;


ALTER FUNCTION platform_private.c2p1_rule_snapshot_allowed(p_data jsonb, p_partner uuid) OWNER TO postgres;

--
-- Name: c2p1_settings_allowed(uuid, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_settings_allowed(p_partner uuid, p_write boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.partner_accounts pa JOIN public.organizations o
 ON o.id=platform_private.c2p1_internal_actor(CASE WHEN p_write THEN
 ARRAY['administrador','financeiro','gestor','gestor_comercial']::public.app_role[] ELSE
 ARRAY['administrador','financeiro','gestor','gestor_comercial','administrativo']::public.app_role[] END)
 WHERE pa.id=p_partner AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
 AND o.ativo IS TRUE AND o.status='ativa' AND
 (o.partner_account_id=pa.id OR EXISTS(SELECT 1 FROM public.organizations owner
 WHERE owner.id=pa.commercial_owner_organization_id AND owner.id=o.id AND owner.ativo IS TRUE AND owner.status='ativa')));
$$;


ALTER FUNCTION platform_private.c2p1_settings_allowed(p_partner uuid, p_write boolean) OWNER TO postgres;

--
-- Name: c2p1_settings_fence(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_settings_fence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_OP='DELETE' OR NOT platform_private.c2p1_settings_allowed(NEW.partner_id,true)
 OR NOT platform_private.has_ticket('c2p1_settings_write',NEW.partner_id) THEN
 RAISE EXCEPTION 'C2P1_SETTINGS_WRITE_CLOSED' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id
 OR NEW.created_at IS DISTINCT FROM OLD.created_at) THEN
 RAISE EXCEPTION 'C2P1_IDENTITY_IMMUTABLE' USING ERRCODE='42501'; END IF;
 IF (SELECT count(*) FROM public.payment_methods WHERE active IS TRUE AND name=NEW.default_payment_method)<>1
 THEN RAISE EXCEPTION 'C2P1_PAYMENT_METHOD_INVALID' USING ERRCODE='22023'; END IF;
 IF NEW.credit_limit::text IN ('NaN','Infinity','-Infinity') OR NEW.credit_limit<0
 OR NEW.credit_alert_threshold_1::text IN ('NaN','Infinity','-Infinity')
 OR NEW.credit_alert_threshold_2::text IN ('NaN','Infinity','-Infinity')
 OR NEW.credit_alert_threshold_1 NOT BETWEEN 0 AND 100 OR NEW.credit_alert_threshold_2 NOT BETWEEN 0 AND 100
 OR NEW.credit_alert_threshold_1>NEW.credit_alert_threshold_2
 THEN RAISE EXCEPTION 'C2P1_FINANCIAL_VALUES_INVALID' USING ERRCODE='22023'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.c2p1_settings_fence() OWNER TO postgres;

--
-- Name: c2p1_snapshot_allowed(text, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_snapshot_allowed(p_entity text, p_id uuid, p_data jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF p_data IS NULL THEN RETURN true; END IF;
 IF jsonb_typeof(p_data)<>'object' THEN RETURN false; END IF;
 IF p_entity='assignment' THEN
 RETURN (p_data->>'id')::uuid=p_id AND platform_private.c2p1_assignment_allowed(p_data->>'buyer_scope',(p_data->>'partner_id')::uuid,(p_data->>'customer_id')::uuid);
 ELSIF p_entity='item_price' THEN
 IF NOT (p_data ? 'buyer_scope') THEN
 -- Publication output contains only server-produced rule ID: verify full chain.
 RETURN EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i JOIN public.commercial_price_rules r ON r.id=i.published_rule_id
 WHERE i.id=p_id AND r.id=(p_data->>'price_rule_id')::uuid AND r.plan_id=i.plan_id AND r.buyer_scope=i.buyer_scope
 AND r.partner_id IS NOT DISTINCT FROM i.partner_id AND r.customer_id IS NOT DISTINCT FROM i.customer_id
 AND r.product_id IS NOT DISTINCT FROM i.product_id AND r.microrganismo_id IS NOT DISTINCT FROM i.microrganismo_id
 AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id));
 END IF;
 RETURN (p_data->>'id')::uuid=p_id AND platform_private.c2p1_item_allowed((p_data->>'assignment_id')::uuid,(p_data->>'plan_id')::uuid,p_data->>'buyer_scope',(p_data->>'partner_id')::uuid,(p_data->>'customer_id')::uuid);
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $$;


ALTER FUNCTION platform_private.c2p1_snapshot_allowed(p_entity text, p_id uuid, p_data jsonb) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: partner_financial_settings; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.partner_financial_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    partner_id uuid NOT NULL,
    billing_trigger text DEFAULT 'na_entrega'::text NOT NULL,
    payment_terms_days integer DEFAULT 7 NOT NULL,
    default_payment_method text,
    credit_limit numeric(14,2),
    block_if_overdue boolean DEFAULT false NOT NULL,
    auto_generate_receivable boolean DEFAULT true NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    credit_limit_action text DEFAULT 'block'::text NOT NULL,
    overdue_tolerance_days integer DEFAULT 0 NOT NULL,
    credit_alert_threshold_1 integer DEFAULT 80 NOT NULL,
    credit_alert_threshold_2 integer DEFAULT 90 NOT NULL,
    CONSTRAINT partner_financial_settings_billing_trigger_check CHECK ((billing_trigger = ANY (ARRAY['na_aprovacao'::text, 'na_producao_finalizada'::text, 'na_entrega'::text, 'manual'::text]))),
    CONSTRAINT partner_financial_settings_payment_terms_days_check CHECK ((payment_terms_days >= 0)),
    CONSTRAINT pfs_credit_limit_action_check CHECK ((credit_limit_action = ANY (ARRAY['block'::text, 'approval_required'::text]))),
    CONSTRAINT pfs_tolerance_check CHECK ((overdue_tolerance_days >= 0))
);


ALTER TABLE public.partner_financial_settings OWNER TO postgres;

--
-- Name: c2p1_update_settings(uuid, jsonb, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.c2p1_update_settings(p_partner_id uuid, p_expected jsonb, p_values jsonb) RETURNS public.partner_financial_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE oldrow public.partner_financial_settings; newrow public.partner_financial_settings; result public.partner_financial_settings; k text;
BEGIN
 IF NOT platform_private.c2p1_settings_allowed(p_partner_id,true) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Serialize absence and updates by canonical partner; lock actor/roles/organizations against revocation.
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.user_roles WHERE user_id=auth.uid() ORDER BY role FOR SHARE NOWAIT;
 PERFORM 1 FROM public.organizations WHERE id=public.h15_actor_organization() FOR SHARE NOWAIT;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner_id FOR UPDATE;
 IF NOT platform_private.c2p1_settings_allowed(p_partner_id,true) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_values IS NULL OR jsonb_typeof(p_values)<>'object' THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_values) LOOP
 IF k NOT IN ('billing_trigger','payment_terms_days','default_payment_method','credit_limit','block_if_overdue','auto_generate_receivable','active','credit_limit_action','overdue_tolerance_days','credit_alert_threshold_1','credit_alert_threshold_2')
 THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM jsonb_object_keys(p_values))<>11 THEN RAISE EXCEPTION 'C2P1_INVALID_PAYLOAD' USING ERRCODE='22023'; END IF;
 SELECT * INTO oldrow FROM public.partner_financial_settings WHERE partner_id=p_partner_id FOR UPDATE;
 IF FOUND THEN
 IF p_expected IS NULL OR p_expected<>to_jsonb(oldrow) THEN RAISE EXCEPTION 'settings_conflict' USING ERRCODE='PT409'; END IF;
 ELSE
 IF p_expected IS NOT NULL THEN RAISE EXCEPTION 'settings_conflict' USING ERRCODE='PT409'; END IF;
 END IF;
 newrow=jsonb_populate_record(NULL::public.partner_financial_settings,p_values);
 -- Exact canonical name; method row lock prevents concurrent deactivation through commit.
 PERFORM 1 FROM public.payment_methods WHERE name=newrow.default_payment_method AND active IS TRUE FOR SHARE;
 IF (SELECT count(*) FROM public.payment_methods WHERE name=newrow.default_payment_method AND active IS TRUE)<>1
 THEN RAISE EXCEPTION 'C2P1_PAYMENT_METHOD_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM platform_private.issue_ticket('c2p1_settings_write',p_partner_id);
 IF oldrow.id IS NULL THEN
 INSERT INTO public.partner_financial_settings(partner_id,billing_trigger,payment_terms_days,default_payment_method,credit_limit,block_if_overdue,auto_generate_receivable,active,credit_limit_action,overdue_tolerance_days,credit_alert_threshold_1,credit_alert_threshold_2)
 VALUES(p_partner_id,newrow.billing_trigger,newrow.payment_terms_days,newrow.default_payment_method,newrow.credit_limit,newrow.block_if_overdue,newrow.auto_generate_receivable,newrow.active,newrow.credit_limit_action,newrow.overdue_tolerance_days,newrow.credit_alert_threshold_1,newrow.credit_alert_threshold_2) RETURNING * INTO result;
 ELSE
 UPDATE public.partner_financial_settings SET billing_trigger=newrow.billing_trigger,payment_terms_days=newrow.payment_terms_days,default_payment_method=newrow.default_payment_method,credit_limit=newrow.credit_limit,block_if_overdue=newrow.block_if_overdue,auto_generate_receivable=newrow.auto_generate_receivable,active=newrow.active,credit_limit_action=newrow.credit_limit_action,overdue_tolerance_days=newrow.overdue_tolerance_days,credit_alert_threshold_1=newrow.credit_alert_threshold_1,credit_alert_threshold_2=newrow.credit_alert_threshold_2 WHERE id=oldrow.id RETURNING * INTO result;
 END IF;
 DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='c2p1_settings_write' AND target=p_partner_id;
 RETURN result;
END $$;


ALTER FUNCTION platform_private.c2p1_update_settings(p_partner_id uuid, p_expected jsonb, p_values jsonb) OWNER TO postgres;

