--
-- Name: catalog_touch_version(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_touch_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := GREATEST(pg_catalog.clock_timestamp(), OLD.updated_at + interval '1 microsecond');
  RETURN NEW;
END;
$$;


ALTER FUNCTION platform_private.catalog_touch_version() OWNER TO postgres;

--
-- Name: catalog_visit_reference_guard_current12(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_visit_reference_guard_current12() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_id uuid; v_col text; v_ok boolean;
BEGIN
 v_org:=platform_private.catalog_tenant_actor('read_prefs');
 IF NOT COALESCE(public.can_view_technical_visit(auth.uid(),NEW.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND OLD.registro_consultor_id IS DISTINCT FROM NEW.registro_consultor_id
  AND NOT COALESCE(public.can_view_technical_visit(auth.uid(),OLD.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.registros_consultor WHERE id=NEW.registro_consultor_id FOR UPDATE;
 IF NOT COALESCE(public.can_view_technical_visit(auth.uid(),NEW.registro_consultor_id),false) THEN
  RAISE EXCEPTION 'sem_permissao' USING ERRCODE='42501'; END IF;
 PERFORM public._assert_visita_editavel(NEW.registro_consultor_id);
 FOR v_col IN SELECT unnest(ARRAY['produto_biologico_sugerido_id','microrganismo_id']) LOOP
  IF TG_OP='UPDATE' AND NEW.registro_consultor_id=OLD.registro_consultor_id
   AND to_jsonb(NEW)->>v_col IS NOT DISTINCT FROM to_jsonb(OLD)->>v_col THEN CONTINUE; END IF;
  v_id:=NULLIF(to_jsonb(NEW)->>v_col,'')::uuid;
  IF v_id IS NULL THEN CONTINUE; END IF;
  IF v_col='microrganismo_id' THEN
   SELECT EXISTS(SELECT 1 FROM public.microrganismos m WHERE m.id=v_id AND m.ativo AND to_jsonb(m)->>'owner_organization_id' IS NULL) INTO v_ok;
  ELSE
   SELECT EXISTS(SELECT 1 FROM public.produtos p WHERE p.id=v_id AND p.ativo AND to_jsonb(p)->>'owner_organization_id' IS NULL) INTO v_ok;
  END IF;
  IF NOT v_ok OR EXISTS(SELECT 1 FROM public.catalog_tenant_visibility v WHERE v.organization_id=v_org
   AND v.entity_type=CASE WHEN v_col='microrganismo_id' THEN 'microrganismo' ELSE 'produto' END
   AND COALESCE(v.produto_id,v.microrganismo_id)=v_id AND v.hidden) THEN
   RAISE EXCEPTION 'catalog_visit_item_unavailable' USING ERRCODE='42501'; END IF;
 END LOOP;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.catalog_visit_reference_guard_current12() OWNER TO postgres;

--
-- Name: catalog_volume_assert_row(uuid, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_assert_row(p_id uuid, p_tipo text, p_item uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r public.catalogo_volumes%ROWTYPE;
BEGIN
  SELECT * INTO r FROM public.catalogo_volumes WHERE id=p_id;
  IF NOT FOUND OR r.item_tipo IS DISTINCT FROM p_tipo OR COALESCE(r.produto_id,r.microrganismo_id) IS DISTINCT FROM p_item
    OR r.moeda IS DISTINCT FROM 'BRL'
    OR r.preco_litro_brl IS DISTINCT FROM pg_catalog.round(r.preco_brl/(r.volume_ml/1000.0),2)
    OR r.valor_dose_100ml_brl IS DISTINCT FROM pg_catalog.round(r.preco_litro_brl/10.0,2)
    OR r.doses_por_volume IS DISTINCT FROM pg_catalog.round(r.volume_ml/100.0,4) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
  -- Duplicidade: no máximo uma apresentação ATIVA por pai e volume.
  IF r.ativo AND EXISTS (SELECT 1 FROM public.catalogo_volumes o WHERE o.id<>r.id AND o.ativo AND o.volume_ml=r.volume_ml
      AND o.item_tipo=r.item_tipo AND o.produto_id IS NOT DISTINCT FROM r.produto_id AND o.microrganismo_id IS NOT DISTINCT FROM r.microrganismo_id) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_volume_duplicate'; END IF;
END;
$$;


ALTER FUNCTION platform_private.catalog_volume_assert_row(p_id uuid, p_tipo text, p_item uuid) OWNER TO postgres;

--
-- Name: catalog_volume_dec(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_dec(p jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN p IS NULL OR pg_catalog.jsonb_typeof(p)='null' THEN 'null'::jsonb
    WHEN pg_catalog.jsonb_typeof(p)='number' THEN pg_catalog.to_jsonb(p#>>'{}')
    ELSE NULL END;  -- tipo inesperado => NULL SQL => objeto inválido detectado pelo chamador
$$;


ALTER FUNCTION platform_private.catalog_volume_dec(p jsonb) OWNER TO postgres;

--
-- Name: catalog_volume_normalize(jsonb, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_normalize(p jsonb, p_create boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE k text; v_out jsonb:='{}'::jsonb; v_num numeric; v_int numeric;
BEGIN
  IF p IS NULL OR pg_catalog.jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  FOR k IN SELECT pg_catalog.jsonb_object_keys(p) LOOP
    IF k = 'volume_ml' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,7}(\.[0-9]{1,3})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      IF v_num <= 0 OR v_num > 1000000 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'preco_brl' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR (p->>k) !~ '^[0-9]{1,9}(\.[0-9]{1,2})?$' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_num:=(p->>k)::numeric;
      -- > 0: preço zero ativo faria o sync anular o pai; preço desconhecido não é cadastrado.
      IF v_num <= 0 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_num);
    ELSIF k = 'rotulo' THEN
      IF pg_catalog.jsonb_typeof(p->k)='null' THEN v_out:=v_out||pg_catalog.jsonb_build_object(k,NULL::text);
      ELSIF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR pg_catalog.char_length(pg_catalog.btrim(p->>k)) > 60 THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
      ELSE v_out:=v_out||pg_catalog.jsonb_build_object(k,NULLIF(pg_catalog.btrim(p->>k),''));
      END IF;
    ELSIF k = 'ordem' THEN
      IF pg_catalog.jsonb_typeof(p->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_int:=(p->>k)::numeric;
      IF v_int <> pg_catalog.trunc(v_int) OR v_int < 0 OR v_int > 9999 THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
      v_out:=v_out||pg_catalog.jsonb_build_object(k,v_int::int);
    ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid';
    END IF;
  END LOOP;
  IF p_create AND NOT (v_out ? 'volume_ml' AND v_out ? 'preco_brl') THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF NOT p_create AND v_out = '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  RETURN v_out;
END;
$_$;


ALTER FUNCTION platform_private.catalog_volume_normalize(p jsonb, p_create boolean) OWNER TO postgres;

--
-- Name: catalog_volume_parent(text, uuid, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_parent(p_tipo text, p_id uuid, p_lock boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v jsonb;
BEGIN
  IF p_id IS NULL OR p_tipo IS NULL OR p_tipo NOT IN ('produto','microrganismo') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF p_tipo='produto' THEN
    IF p_lock THEN SELECT pg_catalog.to_jsonb(x) INTO v FROM public.produtos x WHERE x.id=p_id FOR UPDATE;
    ELSE SELECT pg_catalog.to_jsonb(x) INTO v FROM public.produtos x WHERE x.id=p_id; END IF;
  ELSE
    IF p_lock THEN SELECT pg_catalog.to_jsonb(x) INTO v FROM public.microrganismos x WHERE x.id=p_id FOR UPDATE;
    ELSE SELECT pg_catalog.to_jsonb(x) INTO v FROM public.microrganismos x WHERE x.id=p_id; END IF;
  END IF;
  IF v IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_volume_unavailable'; END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION platform_private.catalog_volume_parent(p_tipo text, p_id uuid, p_lock boolean) OWNER TO postgres;

--
-- Name: catalog_volume_preview_token(uuid, text, uuid, jsonb, text, timestamp with time zone, text, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_preview_token(p_actor uuid, p_operation text, p_id uuid, p_change jsonb, p_reason text, p_row_version timestamp with time zone, p_tipo text, p_item uuid, p_parent jsonb) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'v',1,'actor',p_actor,'operation',p_operation,'id',p_id,'change',p_change,'reason',pg_catalog.btrim(p_reason),
    'row_version',p_row_version,'parent',p_parent,
    'siblings',(SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_array(o.id,o.updated_at,o.ativo,o.volume_ml::text,o.preco_brl::text)
        ORDER BY o.id),'[]'::jsonb)
      FROM public.catalogo_volumes o WHERE o.item_tipo=p_tipo AND COALESCE(o.produto_id,o.microrganismo_id)=p_item AND o.id<>p_id)
  )::text,'UTF8')),'hex');
$$;


ALTER FUNCTION platform_private.catalog_volume_preview_token(p_actor uuid, p_operation text, p_id uuid, p_change jsonb, p_reason text, p_row_version timestamp with time zone, p_tipo text, p_item uuid, p_parent jsonb) OWNER TO postgres;

--
-- Name: catalog_volume_pricing(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_pricing(p_parent jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE l jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_litro_brl');
  d jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_dose_brl');
  h jsonb:=platform_private.catalog_volume_dec(p_parent->'valor_ha_brl');
BEGIN
  IF l IS NULL OR d IS NULL OR h IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_pricing_unexpected'; END IF;
  RETURN pg_catalog.jsonb_build_object('valor_litro_brl',l,'valor_dose_brl',d,'valor_ha_brl',h,'updated_at',p_parent->'updated_at');
END;
$$;


ALTER FUNCTION platform_private.catalog_volume_pricing(p_parent jsonb) OWNER TO postgres;

--
-- Name: catalog_volume_row(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_row(p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT pg_catalog.jsonb_build_object('id',v.id,'item_tipo',v.item_tipo,'item_id',COALESCE(v.produto_id,v.microrganismo_id),
    'volume_ml',v.volume_ml::text,'rotulo',v.rotulo,'preco_brl',v.preco_brl::text,'moeda',v.moeda,'ativo',v.ativo,'ordem',v.ordem,
    'preco_litro_brl',v.preco_litro_brl::text,'valor_dose_100ml_brl',v.valor_dose_100ml_brl::text,'doses_por_volume',v.doses_por_volume::text,
    'updated_at',v.updated_at)
  FROM public.catalogo_volumes v WHERE v.id=p_id;
$$;


ALTER FUNCTION platform_private.catalog_volume_row(p_id uuid) OWNER TO postgres;

--
-- Name: catalog_volume_settle(text, uuid, jsonb, boolean, boolean, boolean, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volume_settle(p_tipo text, p_item uuid, p_before jsonb, p_touches_active boolean, p_confirmed boolean, p_allow_reprice boolean, p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_after jsonb; v_strip text[]:=ARRAY['valor_litro_brl','valor_dose_brl','valor_ha_brl','updated_at'];
  v_pb jsonb; v_pa jsonb; v_repriced boolean;
BEGIN
  v_after:=platform_private.catalog_volume_parent(p_tipo,p_item,false);
  IF (v_after - v_strip) IS DISTINCT FROM (p_before - v_strip) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_parent_protected_changed'; END IF;
  v_pb:=platform_private.catalog_volume_pricing(p_before); v_pa:=platform_private.catalog_volume_pricing(v_after);
  v_repriced:=(v_pb - 'updated_at') IS DISTINCT FROM (v_pa - 'updated_at');
  IF v_repriced AND NOT p_allow_reprice THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_unexpected_repricing'; END IF;
  IF (p_touches_active OR v_repriced) AND NOT COALESCE(p_confirmed,false) THEN
    IF p_token IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
    RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='catalog_volume_confirmation_required',
      DETAIL=pg_catalog.jsonb_build_object('token',p_token,'repriced',v_repriced,
        'parent_before',v_pb - 'updated_at','parent_after',v_pa - 'updated_at')::text;
  END IF;
  RETURN pg_catalog.jsonb_build_object('repriced',v_repriced,'parent_before',v_pb,'parent_after',v_pa);
END;
$$;


ALTER FUNCTION platform_private.catalog_volume_settle(p_tipo text, p_item uuid, p_before jsonb, p_touches_active boolean, p_confirmed boolean, p_allow_reprice boolean, p_token text) OWNER TO postgres;

--
-- Name: catalog_volumes_audit_immutable(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.catalog_volumes_audit_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.operation LIKE '%\_global\_volume%' OR (TG_OP='UPDATE' AND NEW.operation LIKE '%\_global\_volume%') THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_volumes_audit_immutable';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION platform_private.catalog_volumes_audit_immutable() OWNER TO postgres;

--
-- Name: change_global_volume(text, uuid, timestamp with time zone, jsonb, boolean, text, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.change_global_volume(p_operation text, p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_ativo boolean, p_confirm_token text, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_tipo text; v_item uuid; v_parent jsonb; v_token text;
  v_old public.catalogo_volumes%ROWTYPE; v_before jsonb; v_settle jsonb; v_row jsonb; v_receipt jsonb; v_n int;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
    OR (p_confirm_token IS NOT NULL AND p_confirm_token !~ '^[0-9a-f]{64}$')
    OR (p_operation='set_global_volume_status' AND p_ativo IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  IF p_operation='update_global_volume' THEN v:=platform_private.catalog_volume_normalize(p_patch,false);
  ELSIF p_operation='set_global_volume_status' THEN v:=pg_catalog.jsonb_build_object('ativo',p_ativo);
  ELSE RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'change',v,'confirm_token',p_confirm_token,
    'reason',pg_catalog.btrim(p_reason));
  -- Replay idempotente (mesma chave + mesmo pedido, incluindo token) devolve o recibo original, mesmo que o estado tenha mudado.
  v_replay:=platform_private.catalog_entity_replay(v_actor,p_operation,v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT item_tipo, COALESCE(produto_id,microrganismo_id) INTO v_tipo, v_item FROM public.catalogo_volumes WHERE id=p_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_volume_unavailable'; END IF;
  v_parent:=platform_private.catalog_volume_parent(v_tipo,v_item,true);   -- lock do pai antes da linha (serializa irmãs)
  SELECT * INTO v_old FROM public.catalogo_volumes WHERE id=p_id FOR UPDATE;
  IF NOT FOUND OR v_old.item_tipo IS DISTINCT FROM v_tipo OR COALESCE(v_old.produto_id,v_old.microrganismo_id) IS DISTINCT FROM v_item THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  IF p_operation='set_global_volume_status' AND v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  -- Token recalculado sob lock do pai, ANTES da mutação. Token enviado e divergente => prévia desatualizada.
  v_token:=platform_private.catalog_volume_preview_token(v_actor,p_operation,p_id,v,p_reason,v_old.updated_at,v_tipo,v_item,v_parent);
  IF p_confirm_token IS NOT NULL AND p_confirm_token IS DISTINCT FROM v_token THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_preview_stale'; END IF;
  v_before:=platform_private.catalog_volume_row(p_id);
  -- Overflow em derivados ou na coluna de preço do pai (limite depende do tipo do pai e da dose/ha reais) =>
  -- 22003 de domínio; a transação inteira é revertida (linha, pai e ledger intactos). 55000/40001 passam inalterados.
  BEGIN
  UPDATE public.catalogo_volumes SET
    volume_ml=CASE WHEN v ? 'volume_ml' THEN (v->>'volume_ml')::numeric ELSE volume_ml END,
    preco_brl=CASE WHEN v ? 'preco_brl' THEN (v->>'preco_brl')::numeric ELSE preco_brl END,
    rotulo=CASE WHEN v ? 'rotulo' THEN v->>'rotulo' ELSE rotulo END,
    ordem=CASE WHEN v ? 'ordem' THEN (v->>'ordem')::int ELSE ordem END,
    ativo=CASE WHEN v ? 'ativo' THEN (v->>'ativo')::boolean ELSE ativo END
  WHERE id=p_id AND updated_at=p_expected_updated_at;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n <> 1 THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_conflict'; END IF;
  PERFORM platform_private.catalog_volume_assert_row(p_id,v_tipo,v_item);
  v_row:=platform_private.catalog_volume_row(p_id);
  IF (v_row->>'updated_at')::timestamptz <= v_old.updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_volume_confirmation_failed'; END IF;
  -- Toca linha ativa (antes ou depois) ou reprecifica o pai => sem token: 55000 com prévia (rollback integral);
  -- com token válido (já conferido acima): segue.
  v_settle:=platform_private.catalog_volume_settle(v_tipo,v_item,v_parent,v_old.ativo OR (v_row->>'ativo')::boolean,
    p_confirm_token IS NOT NULL,true,v_token);
  EXCEPTION WHEN numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='catalog_volume_price_out_of_range';
  END;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'item_tipo',v_tipo,'item_id',v_item,'ativo',(v_row->>'ativo')::boolean,
    'updated_at',v_row->'updated_at','repriced',v_settle->'repriced','idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,p_operation,p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('volume',v_before,'parent',v_settle->'parent_before'),
    pg_catalog.jsonb_build_object('volume',v_row,'parent',v_settle->'parent_after'));
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.change_global_volume(p_operation text, p_id uuid, p_expected_updated_at timestamp with time zone, p_patch jsonb, p_ativo boolean, p_confirm_token text, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: cnpj_normalizar(text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.cnpj_normalizar(_v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  SELECT nullif(upper(regexp_replace(coalesce(_v,''), '[\s./-]', '', 'g')), '')
$$;


ALTER FUNCTION platform_private.cnpj_normalizar(_v text) OWNER TO postgres;

--
-- Name: cnpj_valido(text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.cnpj_valido(_v text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE v text := upper(regexp_replace(coalesce(_v,''), '[\s./-]', '', 'g'));
  w1 int[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2]; w2 int[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  s int; r int; d1 int; d2 int; i int;
BEGIN
  IF v !~ '^[0-9A-Z]{12}[0-9]{2}$' THEN RETURN false; END IF;
  IF v ~ '^([0-9])\1{13}$' THEN RETURN false; END IF;
  s := 0; FOR i IN 1..12 LOOP s := s + (ascii(substr(v,i,1)) - 48) * w1[i]; END LOOP;
  r := s % 11; d1 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  s := 0; FOR i IN 1..12 LOOP s := s + (ascii(substr(v,i,1)) - 48) * w2[i]; END LOOP;
  s := s + d1 * w2[13];
  r := s % 11; d2 := CASE WHEN r < 2 THEN 0 ELSE 11 - r END;
  RETURN substr(v,13,2) = d1::text || d2::text;
END $_$;


ALTER FUNCTION platform_private.cnpj_valido(_v text) OWNER TO postgres;

--
-- Name: conclude_provisional_password(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.conclude_provisional_password() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid := auth.uid(); v_digest text; v_atual text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE user_id = v_uid AND senha_provisoria IS TRUE) THEN
    RETURN true;
  END IF;
  SELECT pwd_digest INTO v_digest FROM platform_private.provisional_password_state WHERE user_id = v_uid;
  SELECT md5(COALESCE(u.encrypted_password,'')) INTO v_atual FROM auth.users u WHERE u.id = v_uid;
  IF v_digest IS NULL OR v_atual IS NULL OR v_atual = v_digest OR v_atual = md5('') THEN
    RAISE EXCEPTION 'platform_senha_nao_alterada' USING ERRCODE='22023';
  END IF;
  PERFORM platform_private.issue_ticket('pwd_conclude', v_uid);
  PERFORM set_config('cf.concluir_senha','on', true);
  UPDATE public.profiles SET senha_provisoria = false, updated_at = now() WHERE user_id = v_uid;
  PERFORM set_config('cf.concluir_senha','off', true);
  UPDATE public.platform_org_admin_invites SET status='ativo', concluido_em=now()
   WHERE user_id = v_uid AND status='pendente';
  DELETE FROM platform_private.provisional_password_state WHERE user_id = v_uid;
  RETURN true;
END $$;


ALTER FUNCTION platform_private.conclude_provisional_password() OWNER TO postgres;

--
-- Name: conclude_provisional_password_server(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.conclude_provisional_password_server(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF p_user_id IS NULL OR public.is_platform_superadmin(p_user_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE user_id=p_user_id ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 PERFORM platform_private.issue_ticket('pwd_conclude',p_user_id);
 UPDATE public.profiles SET senha_provisoria=false WHERE user_id=p_user_id AND senha_provisoria IS TRUE;
 IF NOT FOUND THEN RAISE EXCEPTION 'platform_primeiro_acesso_nao_pendente' USING ERRCODE='22023'; END IF;
 UPDATE public.platform_org_admin_invites SET status='ativo',concluido_em=now(),access_valid_after=clock_timestamp(),access_expires_at=NULL,access_operation_status='completed' WHERE user_id=p_user_id;
 DELETE FROM platform_private.provisional_password_state WHERE user_id=p_user_id;
 IF j.id IS NOT NULL THEN INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key) VALUES(j.organization_id,p_user_id,j.id,p_user_id,'password_self_completed','succeeded','Senha pessoal definida pelo titular','platform_complete_first_access',gen_random_uuid()); END IF;
 RETURN true;
END $$;


ALTER FUNCTION platform_private.conclude_provisional_password_server(p_user_id uuid) OWNER TO postgres;

--
-- Name: create_global_culture_core(jsonb, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.create_global_culture_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_new public.culturas%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_culture_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_culture',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  -- Unicidade case-insensitive serializada (tabela sem UNIQUE).
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-culture-name',0));
  IF EXISTS (SELECT 1 FROM public.culturas WHERE pg_catalog.lower(pg_catalog.btrim(nome))=pg_catalog.lower(v->>'nome')) THEN
    RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate'; END IF;
  INSERT INTO public.culturas (nome,descricao,ativo) VALUES (v->>'nome',v->>'descricao',false) RETURNING * INTO v_new;
  IF v_new.id IS NULL OR v_new.ativo THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'ativo',false,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_culture',p_reason,p_idempotency_key,v_req,v_receipt,'{}'::jsonb,
    platform_private.read_global_culture_detail_core(v_new.id));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.create_global_culture_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: create_global_microorganism_core(jsonb, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.create_global_microorganism_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_new public.microrganismos%ROWTYPE; v_receipt jsonb; v_after jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_micro_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_microorganism',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  -- Novo item INATIVO, fora do B2B, sem preço/dose/safra/produto; código pelo trigger do servidor.
  BEGIN
    INSERT INTO public.microrganismos (nome,tipo,nome_cientifico,concentracao_ufc_ml,concentracao_label,fornecedor,producao_on_farm,
      meio_cultivo,funcao_agronomica,observacoes,descricao,ativo,b2b_enabled,codigo,dose_ml_ha,valor_dose_brl,valor_litro_brl,preco_tabela,
      safra_referencia,product_id)
    VALUES (v->>'nome',(v->>'tipo')::public.tipo_microrganismo,v->>'nome_cientifico',(v->>'concentracao_ufc_ml')::numeric,v->>'concentracao_label',
      v->>'fornecedor',(v->>'producao_on_farm')::boolean,v->>'meio_cultivo',v->>'funcao_agronomica',v->>'observacoes',v->>'descricao',
      false,false,NULL,NULL,NULL,NULL,NULL,NULL,NULL)
    RETURNING * INTO v_new;
  EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='catalog_entity_duplicate';
  END;
  IF v_new.id IS NULL OR v_new.codigo IS NULL OR v_new.ativo OR v_new.b2b_enabled OR v_new.valor_dose_brl IS NOT NULL
    OR v_new.dose_ml_ha IS NOT NULL OR v_new.safra_referencia IS NOT NULL
    OR v_new.valor_litro_brl IS NOT NULL OR v_new.preco_tabela IS NOT NULL OR v_new.product_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_after:=platform_private.read_global_microorganism_detail_core(v_new.id);
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'codigo',v_new.codigo,'ativo',false,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_microorganism',p_reason,p_idempotency_key,v_req,v_receipt,'{}'::jsonb,v_after);
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.create_global_microorganism_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: create_global_product_core(jsonb, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.create_global_product_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor uuid; v_existing public.catalog_platform_admin_audit%ROWTYPE;
  v_new public.produtos%ROWTYPE; v_request jsonb; v_receipt jsonb; v_audit uuid:=gen_random_uuid();
  v_key text; v_item jsonb; v_comp jsonb:='[]'::jsonb; v_ids uuid[]:='{}';
  v_snapshot jsonb; v_dose numeric; v_vol numeric; v_prop numeric; v_micro uuid; v_count int;
  v_allowed constant text[]:=ARRAY['nome','tipo','descricao','modo_acao','funcao_completa','modo_aplicacao','dose_ml_ha','composicao'];
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_idempotency_key IS NULL OR p_reason IS NULL
    OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500
    OR p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
  END IF;
  -- Só depois de provar 'object' chamamos jsonb_object_keys (arrays/escalares abortariam com erro genérico).
  FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_payload) LOOP
    IF NOT (v_key=ANY(v_allowed)) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;
  END LOOP;
  IF pg_catalog.jsonb_typeof(p_payload->'nome') IS DISTINCT FROM 'string'
    OR pg_catalog.char_length(pg_catalog.btrim(p_payload->>'nome')) NOT BETWEEN 1 AND 500
    OR pg_catalog.jsonb_typeof(p_payload->'tipo') IS DISTINCT FROM 'string'
    OR NOT ((p_payload->>'tipo') = ANY(pg_catalog.enum_range(NULL::public.tipo_produto)::text[])) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
  END IF;
  FOREACH v_key IN ARRAY ARRAY['descricao','modo_acao','funcao_completa','modo_aplicacao'] LOOP
    IF p_payload ? v_key AND (pg_catalog.jsonb_typeof(p_payload->v_key) IS DISTINCT FROM 'string'
      AND pg_catalog.jsonb_typeof(p_payload->v_key) IS DISTINCT FROM 'null'
      OR pg_catalog.char_length(p_payload->>v_key) > 10000) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
  END LOOP;
  -- Dose: número JSON finito (JSON não representa NaN/Infinity), 0 < d <= 1e6, até 6 casas.
  IF p_payload ? 'dose_ml_ha' AND pg_catalog.jsonb_typeof(p_payload->'dose_ml_ha') IS DISTINCT FROM 'null' THEN
    IF pg_catalog.jsonb_typeof(p_payload->'dose_ml_ha') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;
    v_dose:=(p_payload->>'dose_ml_ha')::numeric;
    IF v_dose <= 0 OR v_dose > 1000000 OR pg_catalog.scale(v_dose) > 6 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
  END IF;
  IF p_payload ? 'composicao' THEN
    IF pg_catalog.jsonb_typeof(p_payload->'composicao') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
    IF pg_catalog.jsonb_array_length(p_payload->'composicao') > 50 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
    END IF;
    FOR v_item IN SELECT * FROM pg_catalog.jsonb_array_elements(p_payload->'composicao') LOOP
      -- Objeto primeiro (curto-circuito explícito), depois chaves e tipos com IS DISTINCT FROM (NULL/ausente = inválido).
      IF pg_catalog.jsonb_typeof(v_item) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      IF EXISTS (SELECT 1 FROM pg_catalog.jsonb_object_keys(v_item) k WHERE k NOT IN ('microrganismo_id','volume_ml','proporcao'))
        OR pg_catalog.jsonb_typeof(v_item->'microrganismo_id') IS DISTINCT FROM 'string'
        OR (v_item->>'microrganismo_id') IS NULL
        OR (v_item->>'microrganismo_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        OR pg_catalog.jsonb_typeof(v_item->'volume_ml') IS DISTINCT FROM 'number'
        OR (v_item ? 'proporcao' AND pg_catalog.jsonb_typeof(v_item->'proporcao') IS DISTINCT FROM 'number'
            AND pg_catalog.jsonb_typeof(v_item->'proporcao') IS DISTINCT FROM 'null') THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      v_micro:=(v_item->>'microrganismo_id')::uuid; v_vol:=(v_item->>'volume_ml')::numeric;
      v_prop:=CASE WHEN pg_catalog.jsonb_typeof(v_item->'proporcao')='number' THEN (v_item->>'proporcao')::numeric END;
      IF v_vol IS NULL OR v_micro=ANY(v_ids) OR v_vol <= 0 OR v_vol > 1000000 OR pg_catalog.scale(v_vol) > 6
        OR (v_prop IS NOT NULL AND (v_prop <= 0 OR v_prop > 100 OR pg_catalog.scale(v_prop) > 6)) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid';
      END IF;
      v_ids:=v_ids||v_micro;
      v_comp:=v_comp||pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('microrganismo_id',v_micro,'volume_ml',v_vol,'proporcao',v_prop));
    END LOOP;
  END IF;
  v_request:=pg_catalog.jsonb_build_object('payload',(p_payload-'composicao')||pg_catalog.jsonb_build_object(
    'nome',pg_catalog.btrim(p_payload->>'nome'),'composicao',v_comp),'reason',pg_catalog.btrim(p_reason));

  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_idempotency_key;
  IF FOUND THEN
    IF v_existing.operation<>'create_global_product' OR v_existing.actor_id<>v_actor
      OR v_existing.counts_after->'request' IS DISTINCT FROM v_request THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_conflict';
    END IF;
    RETURN (v_existing.counts_after->'receipt')||pg_catalog.jsonb_build_object('idempotent',true);
  END IF;
  -- Microrganismos referenciados devem existir; lock compartilhado evita remoção concorrente.
  -- FOR SHARE bloqueia UPDATE concorrente (inclusive de ativo) até o fim da transação;
  -- só microrganismos ATIVOS entram em novas composições. Históricas não são tocadas.
  SELECT count(*) INTO v_count FROM (SELECT 1 FROM public.microrganismos WHERE id=ANY(v_ids) AND ativo IS TRUE FOR SHARE) s;
  IF v_count <> pg_catalog.cardinality(v_ids) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_create_invalid'; END IF;

  -- Novo item nasce INATIVO e fora do B2B; preços NULL (motor canônico decide depois);
  -- código NULL → trigger set_codigo_produto/proximo_codigo (upsert serializado).
  INSERT INTO public.produtos (nome,tipo,descricao,modo_acao,funcao_completa,modo_aplicacao,dose_ml_ha,
    ativo,b2b_enabled,codigo,valor_dose_brl,valor_litro_brl,valor_ha_brl)
  VALUES (pg_catalog.btrim(p_payload->>'nome'),(p_payload->>'tipo')::public.tipo_produto,
    p_payload->>'descricao',p_payload->>'modo_acao',p_payload->>'funcao_completa',p_payload->>'modo_aplicacao',
    v_dose,false,false,NULL,NULL,NULL,NULL)
  RETURNING * INTO v_new;
  IF v_new.id IS NULL OR v_new.codigo IS NULL OR v_new.ativo IS DISTINCT FROM false OR v_new.b2b_enabled
    OR v_new.valor_dose_brl IS NOT NULL OR v_new.valor_litro_brl IS NOT NULL OR v_new.valor_ha_brl IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  INSERT INTO public.formulacoes (produto_id,microrganismo_id,volume_ml,proporcao,e_volume_fixo,unidade)
  SELECT v_new.id,(c->>'microrganismo_id')::uuid,(c->>'volume_ml')::numeric,
    CASE WHEN c->>'proporcao' IS NULL THEN NULL ELSE (c->>'proporcao')::numeric END,true,'mL'
  FROM pg_catalog.jsonb_array_elements(v_comp) c;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> pg_catalog.jsonb_array_length(v_comp) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  -- Snapshot canônico relido do banco na mesma transação (produto + formulações com IDs).
  SELECT pg_catalog.jsonb_build_object('produto',pg_catalog.to_jsonb(p) - ARRAY['created_at'],
    'formulacoes',COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',f.id,'microrganismo_id',f.microrganismo_id,
      'volume_ml',f.volume_ml,'proporcao',f.proporcao,'e_volume_fixo',f.e_volume_fixo,'unidade',f.unidade) ORDER BY f.id)
      FROM public.formulacoes f WHERE f.produto_id=p.id),'[]'::jsonb))
  INTO v_snapshot FROM public.produtos p WHERE p.id=v_new.id;
  IF v_snapshot IS NULL OR pg_catalog.jsonb_array_length(v_snapshot->'formulacoes') <> v_count
    OR (v_snapshot->'produto'->>'ativo')::boolean IS DISTINCT FROM false
    OR (v_snapshot->'produto'->>'b2b_enabled')::boolean IS DISTINCT FROM false THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_create_confirmation_failed';
  END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',v_new.id,'codigo',v_new.codigo,'updated_at',v_new.updated_at,
    'composicao_count',v_count,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  INSERT INTO public.catalog_platform_admin_audit (id,operation,actor_id,reason,correlation_id,status,counts_before,counts_after,completed_at)
  VALUES (v_audit,'create_global_product',v_actor,pg_catalog.btrim(p_reason),p_idempotency_key,'completed','{}'::jsonb,
    pg_catalog.jsonb_build_object('request',v_request,'receipt',v_receipt,'after',v_snapshot),pg_catalog.clock_timestamp());
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.create_global_product_core(p_payload jsonb, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: create_global_volume_core(text, uuid, jsonb, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.create_global_volume_core(p_item_tipo text, p_item_id uuid, p_payload jsonb, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v jsonb; v_req jsonb; v_replay jsonb; v_before jsonb; v_settle jsonb; v_id uuid; v_row jsonb; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  v:=platform_private.catalog_volume_normalize(p_payload,true);
  v_req:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'item_id',p_item_id,'payload',v,'reason',pg_catalog.btrim(p_reason));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'create_global_volume',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  v_before:=platform_private.catalog_volume_parent(p_item_tipo,p_item_id,true);
  -- Overflow de derivados/preços do pai (p.ex. numeric(10,2) histórico) = rejeição de domínio atômica (sem ampliar tipos).
  BEGIN
  INSERT INTO public.catalogo_volumes (item_tipo,produto_id,microrganismo_id,volume_ml,rotulo,preco_brl,moeda,ativo,ordem)
  VALUES (p_item_tipo, CASE WHEN p_item_tipo='produto' THEN p_item_id END, CASE WHEN p_item_tipo='microrganismo' THEN p_item_id END,
    (v->>'volume_ml')::numeric, v->>'rotulo', (v->>'preco_brl')::numeric, 'BRL', false, COALESCE((v->>'ordem')::int,0))
  RETURNING id INTO v_id;
  PERFORM platform_private.catalog_volume_assert_row(v_id,p_item_tipo,p_item_id);
  -- Nasce inativa: qualquer alteração no pai é falha (não apaga preço legado silenciosamente).
  v_settle:=platform_private.catalog_volume_settle(p_item_tipo,p_item_id,v_before,false,false,false,NULL);
  EXCEPTION WHEN numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE='22003', MESSAGE='catalog_volume_price_out_of_range';
  END;
  v_row:=platform_private.catalog_volume_row(v_id);
  v_receipt:=pg_catalog.jsonb_build_object('id',v_id,'item_tipo',p_item_tipo,'item_id',p_item_id,'ativo',false,'updated_at',v_row->'updated_at',
    'repriced',false,'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'create_global_volume',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('volume','{}'::jsonb,'parent',v_settle->'parent_before'),
    pg_catalog.jsonb_build_object('volume',v_row,'parent',v_settle->'parent_after'));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.create_global_volume_core(p_item_tipo text, p_item_id uuid, p_payload jsonb, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: create_organization_core(text, text, text, text, text, boolean, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.create_organization_core(_nome text, _nome_fantasia text, _cnpj text, _email text, _plan_key text, _rascunho boolean DEFAULT false, _dados jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_id uuid; v_cnpj text; v_plan uuid; v_status text; v_patch jsonb; v_dados jsonb := '{}'::jsonb; k text; v text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING errcode='42501'; END IF;
  IF _nome IS NULL OR length(btrim(_nome))<2 OR length(_nome)>200 THEN RAISE EXCEPTION 'platform_invalid: nome/razão social obrigatório' USING ERRCODE='22023'; END IF;
  IF length(coalesce(_nome_fantasia,''))>200 THEN RAISE EXCEPTION 'platform_invalid: nome fantasia muito longo' USING ERRCODE='22023'; END IF;
  IF _email IS NULL OR length(_email)>255 OR btrim(_email)!~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'platform_invalid: e-mail corporativo inválido' USING ERRCODE='22023'; END IF;
  v_cnpj:=platform_private.cnpj_normalizar(_cnpj); IF v_cnpj IS NOT NULL AND NOT platform_private.cnpj_valido(v_cnpj) THEN RAISE EXCEPTION 'platform_invalid: CNPJ inválido (dígitos verificadores)' USING ERRCODE='22023'; END IF;
  IF v_cnpj IS NULL AND NOT coalesce(_rascunho,false) THEN RAISE EXCEPTION 'platform_invalid: sem CNPJ, crie como rascunho' USING ERRCODE='22023'; END IF;
  BEGIN
    v_patch := platform_private.org_cadastro_patch(_dados);
  EXCEPTION WHEN raise_exception THEN
    RAISE EXCEPTION 'platform_invalid: %', replace(SQLERRM,'org_invalid: ','') USING ERRCODE='22023';
  END;
  FOR k, v IN SELECT key, value #>> '{}' FROM jsonb_each(v_patch) LOOP
    IF v <> '' THEN v_dados := v_dados || jsonb_build_object(k, v); END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['telefone','cep','logradouro','numero','bairro','cidade','uf'] LOOP
    IF NOT v_dados ? k THEN RAISE EXCEPTION 'platform_invalid: % obrigatório', k USING ERRCODE='22023'; END IF;
  END LOOP;
  IF v_cnpj IS NOT NULL AND EXISTS(SELECT 1 FROM public.organizations WHERE cnpj_normalizado=v_cnpj) THEN RAISE EXCEPTION 'platform_duplicate: CNPJ já cadastrado' USING errcode='23505'; END IF;
  SELECT p.id INTO v_plan FROM public.saas_plans p WHERE p.key=_plan_key AND p.active; IF v_plan IS NULL THEN RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023'; END IF;
  v_status:=CASE WHEN coalesce(_rascunho,false) THEN 'rascunho' ELSE 'aguardando_ativacao' END;
  PERFORM platform_private.issue_ticket('org_create','00000000-0000-0000-0000-000000000000'::uuid);
  INSERT INTO public.organizations(nome,razao_social,nome_fantasia,cnpj,cnpj_normalizado,email_corporativo,status,ativo,onboarding_dados,fuso_horario)
  VALUES(btrim(_nome),btrim(_nome),nullif(btrim(coalesce(_nome_fantasia,'')),''),v_cnpj,v_cnpj,lower(btrim(_email)),v_status,true,v_dados,v_dados->>'fuso_horario') RETURNING id INTO v_id;
  INSERT INTO public.organization_status_audit(organization_id,status_anterior,status_novo,ator_id,motivo) VALUES(v_id,NULL,v_status,auth.uid(),'criação pela plataforma'); RETURN v_id;
END;
$_$;


ALTER FUNCTION platform_private.create_organization_core(_nome text, _nome_fantasia text, _cnpj text, _email text, _plan_key text, _rascunho boolean, _dados jsonb) OWNER TO postgres;

--
-- Name: current_user_organization_id(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.current_user_organization_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_organization_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  SELECT p.organization_id
    INTO v_organization_id
    FROM public.profiles p
   WHERE p.user_id = auth.uid()
     AND p.ativo = true
     AND p.organization_id IS NOT NULL;

  IF v_organization_id IS NULL THEN
    RAISE EXCEPTION 'Organização ativa não encontrada' USING ERRCODE = '42501';
  END IF;

  RETURN v_organization_id;
END;
$$;


ALTER FUNCTION platform_private.current_user_organization_id() OWNER TO postgres;

--
-- Name: delivery_actor_20261030(text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_actor_20261030(p_action text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'DELIVERY_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor','consultor_tecnico','aplicador','operador_onfarm','superadmin'))
 OR EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=auth.uid() AND revoked_at IS NULL AND (valid_from IS NULL OR valid_from<=pg_catalog.now()))
 OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role IN ('administrador','gestor') OR (p_action='group' AND role='producao') OR (p_action='cancel' AND role='administrativo')))
 THEN RAISE EXCEPTION 'DELIVERY_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT public.saas_has_feature('estoque_embalagens') THEN RAISE EXCEPTION 'DELIVERY_FEATURE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $$;


ALTER FUNCTION platform_private.delivery_actor_20261030(p_action text) OWNER TO postgres;

--
-- Name: delivery_gate_20261030(uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_gate_20261030(p_org uuid, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_AUTH_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 IF platform_private.delivery_actor_20261030(p_action) IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=p_org AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR platform_private.delivery_actor_20261030(p_action) IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.delivery_gate_20261030(p_org uuid, p_action text) OWNER TO postgres;

--
-- Name: delivery_merge_split_20261030(uuid, jsonb, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_merge_split_20261030(p_item uuid, p_ctx jsonb, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_s public.estoque_produto%ROWTYPE; v_main public.estoque_produto%ROWTYPE;
 v_ent uuid:=NULLIF(p_payload->>'referencia_id','')::uuid; v_total numeric; v_volume numeric;
BEGIN
 v_org:=platform_private.delivery_actor_20261030('cancel');
 IF NOT EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND organization_id=v_org AND action='cancel' AND target=v_ent AND NOT consumed)
 OR NOT EXISTS(SELECT 1 FROM platform_private.stock_motor_context WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND item=p_item AND ctx=p_ctx AND ctx->>'acao'='cancelamento_reserva')
 THEN RAISE EXCEPTION 'DELIVERY_MERGE_CONTEXT_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_s FROM public.estoque_produto WHERE id=p_item FOR UPDATE;
 PERFORM platform_private.stock_motor_item(p_item,'cancelamento_reserva',p_payload);
 IF v_s.status::text<>'reservado' OR v_s.quantidade IS DISTINCT FROM v_s.quantidade_reservada OR v_s.quantidade IS NULL OR v_s.quantidade<=0 OR v_s.quantidade::text IN ('NaN','Infinity','-Infinity') OR v_s.volume_total IS NULL OR v_s.volume_total<=0 OR v_s.volume_total::text IN ('NaN','Infinity','-Infinity') OR NOT EXISTS(SELECT 1 FROM public.entregas WHERE id=v_ent AND organization_id=v_org AND estoque_produto_id=p_item AND quantidade_entregue=v_s.quantidade) THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 SELECT * INTO v_main FROM public.estoque_produto WHERE lote_id=v_s.lote_id AND status='disponivel' AND coalesce(quantidade_reservada,0)=0 AND id<>p_item ORDER BY id LIMIT 1 FOR UPDATE;
 PERFORM platform_private.delivery_gate_20261030(v_org,'cancel');
 IF v_main.id IS NULL THEN
  UPDATE public.estoque_produto SET status='disponivel' WHERE id=p_item;
  RETURN;
 END IF;
 PERFORM platform_private.stock_motor_item(v_main.id,'cancelamento_reserva','{}'::jsonb);
 IF v_main.envase_id IS DISTINCT FROM v_s.envase_id OR v_main.produto_id IS DISTINCT FROM v_s.produto_id OR v_main.microrganismo_id IS DISTINCT FROM v_s.microrganismo_id OR v_main.validade IS DISTINCT FROM v_s.validade OR v_main.reservado_para_os_id IS NOT NULL OR v_main.reservado_para_cliente_id IS NOT NULL OR v_main.reservado_para_partner_id IS NOT NULL OR v_main.reservado_para_partner_order_id IS NOT NULL THEN RAISE EXCEPTION 'DELIVERY_MERGE_INCOMPATIBLE' USING ERRCODE='PT409'; END IF;
 IF v_main.quantidade IS NULL OR v_main.quantidade<=0 OR v_main.quantidade::text IN ('NaN','Infinity','-Infinity') OR v_main.volume_total IS NULL OR v_main.volume_total<=0 OR v_main.volume_total::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 v_total:=v_main.quantidade+v_s.quantidade; v_volume:=v_main.volume_total+v_s.volume_total;
 IF v_total IS NULL OR v_volume IS NULL OR v_total<=0 OR v_volume<=0 OR v_total::text IN ('NaN','Infinity','-Infinity') OR v_volume::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'DELIVERY_MERGE_BALANCE_DENIED' USING ERRCODE='PT409'; END IF;
 -- Keep source row and immutable movement history; retire it BEFORE growing the unique main row.
 UPDATE public.estoque_produto SET status='estornado',quantidade=0,volume_total=0,quantidade_reservada=0,reservado_para_os_id=NULL,reservado_para_os_tipo=NULL,reservado_para_cliente_id=NULL,reservado_para_partner_id=NULL,reservado_para_partner_order_id=NULL WHERE id=p_item;
 UPDATE public.estoque_produto SET quantidade=v_total,volume_total=v_volume WHERE id=v_main.id;
 IF NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE estoque_produto_id=p_item AND idempotency_key=p_ctx->>'idempotency_key' AND saldo_posterior=0 AND acao='cancelamento_reserva')
 OR NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE estoque_produto_id=v_main.id AND metadata->>'operacao_key'=p_ctx->>'idempotency_key' AND saldo_anterior=v_main.quantidade AND saldo_posterior=v_total AND volume_posterior=v_volume AND acao='cancelamento_reserva')
 THEN RAISE EXCEPTION 'DELIVERY_MERGE_LEDGER_DENIED' USING ERRCODE='PT409'; END IF;
END $$;


ALTER FUNCTION platform_private.delivery_merge_split_20261030(p_item uuid, p_ctx jsonb, p_payload jsonb) OWNER TO postgres;

--
-- Name: delivery_mutation_guard_20261030(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_mutation_guard_20261030() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c platform_private.delivery_context_20261030%ROWTYPE; v_org uuid;
 v_proof text[]:=ARRAY['comprovante_status','assinatura_tipo','recebedor_nome','recebedor_documento','recebedor_cargo','recebedor_telefone','comprovante_anexado_em','comprovante_anexado_por','assinatura_digital_capturada_em','assinatura_digital_capturada_por','comprovante_id','formulario_gerado_em','formulario_gerado_por','validation_token','validation_hash','updated_at'];
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM platform_private.delivery_context_20261030
 WHERE txid=pg_catalog.txid_current() AND actor=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='proof' THEN
  v_org:=platform_private.delivery_proof_actor_20261030();
  IF TG_OP='UPDATE' AND c.mutation='proof' AND c.organization_id=v_org AND NEW.id=c.target AND OLD.id=c.target
  AND OLD.organization_id=v_org AND NEW.organization_id=v_org
  AND OLD.partner_order_id IS NULL AND NEW.partner_order_id IS NULL
  AND OLD.ordem_servico_onfarm_id IS NULL AND NEW.ordem_servico_onfarm_id IS NULL
  AND NEW.status=OLD.status AND NEW.receivable_id IS NOT DISTINCT FROM OLD.receivable_id
  AND (pg_catalog.to_jsonb(NEW)-v_proof) IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-v_proof) THEN
   UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
   RETURN NEW;
  END IF;
  RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501';
 END IF;
 v_org:=platform_private.delivery_actor_20261030(c.action);
 IF c.organization_id IS DISTINCT FROM v_org OR NEW.organization_id IS DISTINCT FROM v_org
 OR NEW.partner_order_id IS NOT NULL OR NEW.receivable_id IS NOT NULL OR NEW.ordem_servico_onfarm_id IS NOT NULL
 THEN RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 IF c.action='group' AND TG_OP='INSERT' AND c.mutation='create' AND c.delivery IS NULL
 AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item AND NEW.status::text='separado' THEN
  UPDATE platform_private.delivery_context_20261030 SET delivery=NEW.id,mutation='decorate' WHERE txid=c.txid;
 ELSIF c.action='group' AND TG_OP='UPDATE' AND c.mutation='decorate' AND NEW.id=c.delivery
 AND OLD.id=c.delivery AND NEW.ordem_servico_id=c.target AND NEW.estoque_produto_id=c.item
 AND NEW.organization_id=OLD.organization_id AND NEW.status=OLD.status THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSIF c.action='cancel' AND TG_OP='UPDATE' AND c.mutation='cancel' AND NEW.id=c.target AND OLD.id=c.target
 AND OLD.organization_id=v_org AND NEW.status::text='cancelada' AND NEW.financial_status='CANCELED'
 AND (pg_catalog.to_jsonb(NEW)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status'])
 IS NOT DISTINCT FROM (pg_catalog.to_jsonb(OLD)-ARRAY['status','motivo_cancelamento','updated_at','cancelada_em','cancelada_por','financial_status']) THEN
  UPDATE platform_private.delivery_context_20261030 SET mutation='done' WHERE txid=c.txid;
 ELSE RAISE EXCEPTION 'DELIVERY_MUTATION_CLOSED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.delivery_mutation_guard_20261030() OWNER TO postgres;

--
-- Name: delivery_no_downstream_20261030(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_no_downstream_20261030() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current()) THEN
  RAISE EXCEPTION 'DELIVERY_DOWNSTREAM_FORBIDDEN: %.%',TG_TABLE_SCHEMA,TG_TABLE_NAME USING ERRCODE='42501';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;


ALTER FUNCTION platform_private.delivery_no_downstream_20261030() OWNER TO postgres;

--
-- Name: delivery_order_transition_guard_20261030(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_order_transition_guard_20261030() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.status IS DISTINCT FROM OLD.status AND EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current()) THEN
  RAISE EXCEPTION 'DELIVERY_B2B_TRANSITION_CLOSED' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.delivery_order_transition_guard_20261030() OWNER TO postgres;

--
-- Name: delivery_proof_actor_20261030(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_actor_20261030() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_uid uuid:=auth.uid(); BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'DELIVERY_PROOF_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL
 OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=v_uid AND role IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor','consultor_tecnico','superadmin'))
 OR EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=v_uid AND revoked_at IS NULL AND (valid_from IS NULL OR valid_from<=pg_catalog.now()))
 OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=v_uid AND role IN ('administrador','gestor','administrativo','producao','operador_onfarm','aplicador'))
 THEN RAISE EXCEPTION 'DELIVERY_PROOF_ACTOR_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $$;


ALTER FUNCTION platform_private.delivery_proof_actor_20261030() OWNER TO postgres;

--
-- Name: delivery_proof_apply_20261030(text, uuid, text, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_apply_20261030(p_action text, p_entrega uuid, p_request_key text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $_$
DECLARE v_uid uuid:=auth.uid(); v_org uuid; v_e public.entregas%ROWTYPE; v_c public.entrega_comprovantes%ROWTYPE;
 v_p jsonb; v_fp text; v_prev platform_private.delivery_requests_20261030%ROWTYPE; v_action text:='proof:'||p_action;
 v_path text; v_num text; v_token uuid; v_hash text; v_result jsonb; v_reused boolean:=false;
BEGIN
 v_org:=platform_private.delivery_proof_actor_20261030();
 IF p_entrega IS NULL OR p_request_key IS NULL OR p_request_key !~ '^[A-Za-z0-9:_-]{8,128}$' THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: key' USING ERRCODE='22023'; END IF;
 v_p:=platform_private.delivery_proof_payload_20261030(p_action,p_entrega,p_payload);
 v_fp:=pg_catalog.md5(pg_catalog.jsonb_build_object('entrega',p_entrega,'action',p_action,'payload',v_p)::text);
 SELECT * INTO v_e FROM public.entregas WHERE id=p_entrega AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_PROOF_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('entrega_proof:'||p_entrega::text));
 IF platform_private.delivery_proof_actor_20261030() IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.delivery_proof_gate_20261030(v_org);
 SELECT * INTO v_e FROM public.entregas WHERE id=p_entrega AND organization_id=v_org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_PROOF_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Replay only after full reauthorization under every lock (re-read, not the pre-lock copy).
 v_e:=platform_private.delivery_proof_recheck_20261030(p_entrega,v_org,p_action);
 SELECT * INTO v_prev FROM platform_private.delivery_requests_20261030
 WHERE organization_id=v_org AND actor=v_uid AND action=v_action AND request_key=p_request_key;
 IF FOUND THEN
  IF v_prev.fingerprint<>v_fp THEN RAISE EXCEPTION 'DELIVERY_PROOF_REQUEST_CONFLICT' USING ERRCODE='PT409'; END IF;
  RETURN v_prev.result||'{"replayed":true}'::jsonb;
 END IF;
 IF p_action IN ('sign','attach') THEN
  v_path:=CASE p_action WHEN 'sign' THEN v_p->>'assinatura_digital_png_path' ELSE v_p->>'arquivo_path' END;
  -- Object must exist, belong to the caller and stay locked until commit.
  PERFORM 1 FROM storage.objects WHERE bucket_id='entrega-documentos' AND name=v_path AND owner_id=v_uid::text FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_PROOF_OBJECT_DENIED' USING ERRCODE='42501'; END IF;
  -- The FOR SHARE may have waited: re-authorize before trusting anything.
  v_e:=platform_private.delivery_proof_recheck_20261030(p_entrega,v_org,p_action);
  IF EXISTS(SELECT 1 FROM public.entrega_comprovantes WHERE arquivo_path=v_path OR assinatura_digital_png_path=v_path) THEN
   RAISE EXCEPTION 'DELIVERY_PROOF_OBJECT_ALREADY_LINKED' USING ERRCODE='PT409';
  END IF;
 END IF;
 IF v_e.comprovante_id IS NOT NULL THEN
  SELECT * INTO v_c FROM public.entrega_comprovantes WHERE id=v_e.comprovante_id FOR UPDATE;
  IF NOT FOUND OR v_c.entrega_id<>v_e.id THEN RAISE EXCEPTION 'DELIVERY_PROOF_INCONSISTENT' USING ERRCODE='PT409'; END IF;
 ELSE
  SELECT * INTO v_c FROM public.entrega_comprovantes WHERE entrega_id=v_e.id AND tipo='formulario_entrega' ORDER BY gerado_em DESC LIMIT 1 FOR UPDATE;
 END IF;
 -- The comprovante FOR UPDATE may have waited: re-authorize again.
 v_e:=platform_private.delivery_proof_recheck_20261030(p_entrega,v_org,p_action);
 IF v_c.id IS NOT NULL AND v_c.status IN ('rejeitado','cancelado') THEN v_c:=NULL; END IF;
 IF p_action<>'generate' AND v_c.status='confirmado' THEN RAISE EXCEPTION 'DELIVERY_PROOF_CLOSED' USING ERRCODE='PT409'; END IF;
 INSERT INTO platform_private.delivery_context_20261030(txid,actor,organization_id,action,target,mutation)
 VALUES(pg_catalog.txid_current(),v_uid,v_org,'proof',v_e.id,'proof');
 IF v_c.id IS NULL THEN
  v_token:=pg_catalog.gen_random_uuid();
  v_num:='AR-ENT-'||pg_catalog.lpad(pg_catalog.nextval('public.entrega_formulario_seq')::text,6,'0');
  v_hash:=pg_catalog.encode(extensions.digest(v_e.id::text||v_num||v_token::text||pg_catalog.now()::text,'sha256'),'hex');
  INSERT INTO public.entrega_comprovantes(entrega_id,numero_formulario,tipo,status,validation_token,validation_hash,qr_code_payload,gerado_por)
  VALUES(v_e.id,v_num,'formulario_entrega','gerado',v_token,v_hash,v_token::text,v_uid) RETURNING * INTO v_c;
  PERFORM public._entrega_seed_checklist(v_e.id);
  INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by)
  VALUES('entrega',v_e.id,'DELIVERY_FORM_GENERATED',pg_catalog.jsonb_build_object('comprovante_id',v_c.id,'numero_formulario',v_num),v_uid);
 ELSE v_reused:=true; END IF;
 IF p_action='sign' THEN
  UPDATE public.entrega_comprovantes SET status='assinatura_digital_coletada',assinatura_coletada=true,assinatura_tipo='digital_tela',
   assinatura_digital_png_path=v_path,assinatura_digital_svg=v_p->>'assinatura_digital_svg',assinatura_hash=v_p->>'assinatura_hash',
   assinatura_user_agent=v_p->>'assinatura_user_agent',assinatura_capturada_em=pg_catalog.now(),
   recebedor_nome=v_p->>'recebedor_nome',recebedor_documento=v_p->>'recebedor_documento',recebedor_cargo=v_p->>'recebedor_cargo',recebedor_telefone=v_p->>'recebedor_telefone',
   data_assinatura=pg_catalog.now(),
   validation_hash=pg_catalog.encode(extensions.digest(v_e.id::text||(v_p->>'assinatura_hash')||pg_catalog.now()::text,'sha256'),'hex'),updated_at=pg_catalog.now()
  WHERE id=v_c.id RETURNING * INTO v_c;
  INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by)
  VALUES('entrega',v_e.id,'DELIVERY_DIGITAL_SIGNATURE_CAPTURED',pg_catalog.jsonb_build_object('comprovante_id',v_c.id,'hash',v_p->>'assinatura_hash'),v_uid);
 ELSIF p_action='attach' THEN
  UPDATE public.entrega_comprovantes SET status='anexado',arquivo_path=v_path,arquivo_url=NULL,arquivo_nome=v_p->>'arquivo_nome',arquivo_mime=v_p->>'arquivo_mime',
   assinatura_coletada=true,assinatura_tipo='fisica_anexada',
   recebedor_nome=v_p->>'recebedor_nome',recebedor_documento=v_p->>'recebedor_documento',recebedor_cargo=v_p->>'recebedor_cargo',recebedor_telefone=v_p->>'recebedor_telefone',
   data_assinatura=pg_catalog.now(),anexado_por=v_uid,anexado_em=pg_catalog.now(),updated_at=pg_catalog.now()
  WHERE id=v_c.id RETURNING * INTO v_c;
  INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by)
  VALUES('entrega',v_e.id,'DELIVERY_PROOF_ATTACHED',pg_catalog.jsonb_build_object('comprovante_id',v_c.id,'arquivo_path',v_path),v_uid);
 END IF;
 -- Immediately before the delivery writer: re-authorize (no wait is trusted).
 PERFORM platform_private.delivery_proof_recheck_20261030(p_entrega,v_org,p_action);
 -- Exactly one delivery row update; the barrier verifies the column set.
 UPDATE public.entregas SET
  comprovante_id=v_c.id,
  comprovante_status=CASE p_action WHEN 'generate' THEN CASE WHEN v_reused THEN comprovante_status ELSE 'formulario_gerado' END WHEN 'sign' THEN 'assinatura_digital_coletada' ELSE 'anexado' END,
  formulario_gerado_em=CASE WHEN v_reused THEN formulario_gerado_em ELSE pg_catalog.now() END,
  formulario_gerado_por=CASE WHEN v_reused THEN formulario_gerado_por ELSE v_uid END,
  validation_token=CASE WHEN v_reused THEN validation_token ELSE v_c.validation_token END,
  validation_hash=CASE WHEN v_reused THEN validation_hash ELSE v_c.validation_hash END,
  assinatura_tipo=CASE p_action WHEN 'sign' THEN 'digital_tela' WHEN 'attach' THEN 'fisica_anexada' ELSE assinatura_tipo END,
  recebedor_nome=CASE WHEN p_action='generate' THEN recebedor_nome ELSE v_p->>'recebedor_nome' END,
  recebedor_documento=coalesce(v_p->>'recebedor_documento',recebedor_documento),
  recebedor_cargo=coalesce(v_p->>'recebedor_cargo',recebedor_cargo),
  recebedor_telefone=coalesce(v_p->>'recebedor_telefone',recebedor_telefone),
  assinatura_digital_capturada_em=CASE WHEN p_action='sign' THEN pg_catalog.now() ELSE assinatura_digital_capturada_em END,
  assinatura_digital_capturada_por=CASE WHEN p_action='sign' THEN v_uid ELSE assinatura_digital_capturada_por END,
  comprovante_anexado_em=CASE WHEN p_action='attach' THEN pg_catalog.now() ELSE comprovante_anexado_em END,
  comprovante_anexado_por=CASE WHEN p_action='attach' THEN v_uid ELSE comprovante_anexado_por END,
  updated_at=pg_catalog.now()
 WHERE id=v_e.id;
 IF NOT EXISTS(SELECT 1 FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current() AND mutation='done') THEN
  RAISE EXCEPTION 'DELIVERY_PROOF_PERMIT_UNUSED' USING ERRCODE='42501';
 END IF;
 -- One-shot permit is removed on success; receipts are kept.
 DELETE FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current() AND action='proof';
 v_result:=pg_catalog.jsonb_build_object('success',true,'action',p_action,'entrega_id',v_e.id,'comprovante_id',v_c.id,
  'numero_formulario',v_c.numero_formulario,'validation_token',v_c.validation_token,'reused',v_reused,'object_path',v_path);
 INSERT INTO platform_private.delivery_requests_20261030(request_key,actor,organization_id,action,fingerprint,result)
 VALUES(p_request_key,v_uid,v_org,v_action,v_fp,v_result);
 RETURN v_result;
END $_$;


ALTER FUNCTION platform_private.delivery_proof_apply_20261030(p_action text, p_entrega uuid, p_request_key text, p_payload jsonb) OWNER TO postgres;

--
-- Name: delivery_proof_gate_20261030(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_gate_20261030(p_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_AUTH_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 IF platform_private.delivery_proof_actor_20261030() IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=p_org AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR platform_private.delivery_proof_actor_20261030() IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.delivery_proof_gate_20261030(p_org uuid) OWNER TO postgres;

--
-- Name: delivery_proof_payload_20261030(text, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_payload_20261030(p_action text, p_entrega uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE v_allowed text[]; k text; v jsonb; v_max int; v_out jsonb:='{}'::jsonb; v_path text;
 uuidre text:='[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
BEGIN
 IF p_action='generate' THEN
  IF p_payload IS NOT NULL AND p_payload<>'{}'::jsonb THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: payload' USING ERRCODE='22023'; END IF;
  RETURN '{}'::jsonb;
 END IF;
 IF p_payload IS NULL OR pg_catalog.jsonb_typeof(p_payload)<>'object' THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: payload' USING ERRCODE='22023'; END IF;
 v_allowed:=CASE p_action
  WHEN 'sign' THEN ARRAY['assinatura_digital_png_path','assinatura_digital_svg','assinatura_hash','assinatura_user_agent','recebedor_nome','recebedor_documento','recebedor_cargo','recebedor_telefone']
  WHEN 'attach' THEN ARRAY['arquivo_path','arquivo_nome','arquivo_mime','recebedor_nome','recebedor_documento','recebedor_cargo','recebedor_telefone']
  ELSE NULL END;
 IF v_allowed IS NULL THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: action' USING ERRCODE='22023'; END IF;
 FOR k,v IN SELECT * FROM pg_catalog.jsonb_each(p_payload) LOOP
  IF NOT k=ANY(v_allowed) THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: field %',k USING ERRCODE='22023'; END IF;
  IF pg_catalog.jsonb_typeof(v)='null' OR (pg_catalog.jsonb_typeof(v)='string' AND pg_catalog.btrim(v#>>'{}')='') THEN CONTINUE; END IF;
  IF pg_catalog.jsonb_typeof(v)<>'string' THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: field %',k USING ERRCODE='22023'; END IF;
  v_max:=CASE WHEN k='assinatura_digital_svg' THEN 8000 WHEN k IN ('assinatura_user_agent','arquivo_path') THEN 512 ELSE 255 END;
  IF pg_catalog.length(v#>>'{}')>v_max THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: field %',k USING ERRCODE='22023'; END IF;
  v_out:=v_out||pg_catalog.jsonb_build_object(k,pg_catalog.btrim(v#>>'{}'));
 END LOOP;
 IF NOT v_out ? 'recebedor_nome' THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: recebedor_nome' USING ERRCODE='22023'; END IF;
 IF p_action='sign' THEN
  v_path:=v_out->>'assinatura_digital_png_path';
  IF v_path IS NULL OR v_path !~ ('^entregas/'||p_entrega::text||'/assinaturas/'||uuidre||'\.png$') THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: path' USING ERRCODE='22023'; END IF;
  IF coalesce(v_out->>'assinatura_hash','') !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: hash' USING ERRCODE='22023'; END IF;
 ELSE
  v_path:=v_out->>'arquivo_path';
  IF v_path IS NULL OR v_path !~ ('^entregas/'||p_entrega::text||'/comprovantes/'||uuidre||'\.(pdf|png|jpg|jpeg|webp)$') THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: path' USING ERRCODE='22023'; END IF;
  IF coalesce(v_out->>'arquivo_mime','') NOT IN ('application/pdf','image/png','image/jpeg','image/webp')
  OR NOT (v_out ? 'arquivo_nome')
  OR (v_out->>'arquivo_mime'='application/pdf' AND v_path !~ '\.pdf$')
  OR (v_out->>'arquivo_mime'='image/png' AND v_path !~ '\.png$')
  OR (v_out->>'arquivo_mime'='image/jpeg' AND v_path !~ '\.jpe?g$')
  OR (v_out->>'arquivo_mime'='image/webp' AND v_path !~ '\.webp$')
  THEN RAISE EXCEPTION 'DELIVERY_PROOF_INVALID: mime' USING ERRCODE='22023'; END IF;
 END IF;
 RETURN v_out;
END $_$;


ALTER FUNCTION platform_private.delivery_proof_payload_20261030(p_action text, p_entrega uuid, p_payload jsonb) OWNER TO postgres;

