    status public.status_entrega DEFAULT 'separado'::public.status_entrega NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    estoque_produto_id uuid,
    lote_id uuid,
    produto_id uuid,
    quantidade_entregue numeric,
    volume_entregue_ml numeric,
    cancelada_por uuid,
    cancelada_em timestamp with time zone,
    motivo_cancelamento text,
    receivable_id uuid,
    confirmada_em timestamp with time zone,
    confirmada_por uuid,
    recebido_por_nome text,
    entregue_em timestamp with time zone,
    recebido_por_cargo text,
    recebido_por_documento text,
    observacoes_confirmacao text,
    confirmado_por uuid,
    comprovante_entrega_obrigatorio boolean DEFAULT false NOT NULL,
    financial_status text,
    billing_generated_at timestamp with time zone,
    billing_generated_by uuid,
    not_billable_reason text,
    ordem_servico_onfarm_id uuid,
    os_faturamento_base_id uuid,
    comprovante_status text DEFAULT 'pendente'::text NOT NULL,
    comprovante_id uuid,
    recebedor_nome text,
    recebedor_documento text,
    recebedor_cargo text,
    recebedor_telefone text,
    assinatura_obrigatoria boolean DEFAULT true NOT NULL,
    assinatura_tipo text,
    formulario_gerado_em timestamp with time zone,
    formulario_gerado_por uuid,
    comprovante_anexado_em timestamp with time zone,
    comprovante_anexado_por uuid,
    assinatura_digital_capturada_em timestamp with time zone,
    assinatura_digital_capturada_por uuid,
    recebimento_confirmado_em timestamp with time zone,
    recebimento_confirmado_por uuid,
    validation_token uuid,
    validation_hash text,
    separacao_status text DEFAULT 'pendente'::text NOT NULL,
    separacao_confirmada_em timestamp with time zone,
    separacao_confirmada_por uuid,
    partner_order_id uuid,
    grupo_entrega_id uuid,
    motorista_telefone text,
    motorista_documento text,
    veiculo_placa text,
    veiculo_tipo text,
    hora_saida_prevista time without time zone,
    data_chegada_prevista date,
    hora_chegada_prevista time without time zone,
    destinatario_nome text,
    destinatario_telefone text,
    destinatario_whatsapp text,
    endereco_origem text DEFAULT 'cadastro'::text,
    endereco_logradouro text,
    endereco_numero text,
    endereco_complemento text,
    endereco_bairro text,
    endereco_cidade text,
    endereco_uf text,
    endereco_cep text,
    endereco_referencia text,
    tipo_entrega text DEFAULT 'motorista'::text NOT NULL,
    reentrega_origem_id uuid,
    organization_id uuid,
    CONSTRAINT entregas_comprovante_status_chk CHECK ((comprovante_status = ANY (ARRAY['pendente'::text, 'formulario_gerado'::text, 'aguardando_assinatura'::text, 'assinatura_digital_coletada'::text, 'anexado'::text, 'confirmado'::text, 'dispensado'::text, 'rejeitado'::text]))),
    CONSTRAINT entregas_financial_status_chk CHECK (((financial_status IS NULL) OR (financial_status = ANY (ARRAY['NOT_BILLABLE'::text, 'PENDING_BILLING'::text, 'BILLED'::text, 'CANCELED'::text])))),
    CONSTRAINT entregas_tipo_entrega_check CHECK ((tipo_entrega = ANY (ARRAY['motorista'::text, 'retirada'::text])))
);


