--
-- Name: delivery_proof_recheck_20261030(uuid, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_recheck_20261030(p_entrega uuid, p_org uuid, p_action text) RETURNS public.entregas
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_e public.entregas%ROWTYPE; BEGIN
 IF platform_private.delivery_proof_actor_20261030() IS DISTINCT FROM p_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_e FROM public.entregas WHERE id=p_entrega AND organization_id=p_org;
 IF NOT FOUND OR NOT platform_private.delivery_proof_row_ok_20261030(v_e,p_org,p_action) THEN RAISE EXCEPTION 'DELIVERY_PROOF_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_e;
END $$;


ALTER FUNCTION platform_private.delivery_proof_recheck_20261030(p_entrega uuid, p_org uuid, p_action text) OWNER TO postgres;

--
-- Name: delivery_proof_row_ok_20261030(public.entregas, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.delivery_proof_row_ok_20261030(p_e public.entregas, p_org uuid, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid:=auth.uid(); BEGIN
 IF p_e.id IS NULL OR p_e.organization_id IS DISTINCT FROM p_org OR p_e.cliente_id IS NULL
 OR p_e.partner_order_id IS NOT NULL OR p_e.ordem_servico_onfarm_id IS NOT NULL THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=p_e.cliente_id AND organization_id=p_org) THEN RETURN false; END IF;
 IF p_action='generate' THEN
  IF p_e.status::text NOT IN ('separado','em_rota','entregue') THEN RETURN false; END IF;
 ELSIF p_e.status::text NOT IN ('separado','em_rota') THEN RETURN false; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=v_uid AND role IN ('administrador','gestor','administrativo','producao','operador_onfarm'))
 AND NOT (p_e.cliente_id = ANY(public.get_cliente_ids_for_user(v_uid))) THEN RETURN false; END IF;
 RETURN true;
END $$;


ALTER FUNCTION platform_private.delivery_proof_row_ok_20261030(p_e public.entregas, p_org uuid, p_action text) OWNER TO postgres;

--
-- Name: entitlements_for_user(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.entitlements_for_user(_uid uuid) RETURNS TABLE(module_key text, feature_key text, limit_value numeric, config jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH actor AS (
    SELECT p.organization_id
    FROM public.profiles p
    JOIN public.organizations org
      ON org.id = p.organization_id
     AND org.ativo IS TRUE
    WHERE p.user_id = _uid
      AND p.ativo IS TRUE
      AND p.organization_id IS NOT NULL
    ORDER BY p.created_at, p.organization_id
    LIMIT 1
  ), current_subscription AS (
    SELECT s.organization_id, s.plan_version_id
    FROM public.organization_subscriptions s
    JOIN actor a ON a.organization_id = s.organization_id
    JOIN public.saas_plan_versions v
      ON v.id = s.plan_version_id
     AND v.status = 'PUBLISHED'
     AND v.effective_from <= now()
     AND (v.effective_to IS NULL OR v.effective_to > now())
    WHERE s.plan_version_id IS NOT NULL
      AND (
        s.status = 'ACTIVE'
        OR (s.status = 'TRIAL' AND s.trial_ends_at IS NOT NULL AND s.trial_ends_at > now())
      )
      AND (s.cancel_at IS NULL OR s.cancel_at > now())
    ORDER BY s.started_at DESC, s.id DESC
    LIMIT 1
  ), candidates AS (
    SELECT f.id AS feature_id, f.module_id, f.key AS feature_key,
           vf.enabled AS base_enabled, vf.limit_value AS base_limit, vf.config AS base_config
    FROM current_subscription s
    JOIN public.saas_plan_version_features vf ON vf.plan_version_id = s.plan_version_id
    JOIN public.saas_features f ON f.id = vf.feature_id AND f.active IS TRUE
    UNION
    SELECT f.id, f.module_id, f.key, false, NULL::numeric, NULL::jsonb
    FROM current_subscription s
    JOIN public.organization_feature_overrides o ON o.organization_id = s.organization_id
    JOIN public.saas_features f ON f.id = o.feature_id AND f.active IS TRUE
    WHERE o.ended_at IS NULL
      AND o.starts_at <= now()
      AND (o.ends_at IS NULL OR o.ends_at > now())
  ), effective AS (
    SELECT DISTINCT ON (c.feature_id)
      c.feature_id, c.module_id, c.feature_key,
      CASE
        WHEN o.mode = 'REVOKE' THEN false
        WHEN o.mode = 'GRANT' THEN true
        ELSE c.base_enabled
      END AS enabled,
      CASE
        WHEN o.mode = 'GRANT' THEN o.limit_value
        WHEN o.mode = 'REVOKE' THEN NULL::numeric
        ELSE c.base_limit
      END AS effective_limit,
      c.base_config AS effective_config
    FROM candidates c
    CROSS JOIN current_subscription s
    LEFT JOIN LATERAL (
      SELECT x.mode, x.limit_value
      FROM public.organization_feature_overrides x
      WHERE x.organization_id = s.organization_id
        AND x.feature_id = c.feature_id
        AND x.ended_at IS NULL
        AND x.starts_at <= now()
        AND (x.ends_at IS NULL OR x.ends_at > now())
      ORDER BY x.created_at DESC, x.id DESC
      LIMIT 1
    ) o ON true
    ORDER BY c.feature_id
  )
  SELECT m.key::text, e.feature_key::text, e.effective_limit::numeric, e.effective_config
  FROM effective e
  JOIN public.saas_modules m ON m.id = e.module_id AND m.active IS TRUE
  WHERE e.enabled IS TRUE
  ORDER BY m.key, e.feature_key
$$;


ALTER FUNCTION platform_private.entitlements_for_user(_uid uuid) OWNER TO postgres;

--
-- Name: entrega_termo_tenant_ok(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.entrega_termo_tenant_ok(p_entrega_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_entrega_id IS NOT NULL AND EXISTS (
    SELECT 1
      FROM public.entregas e
      JOIN public.clientes c ON c.id = e.cliente_id
     WHERE e.id = p_entrega_id
       AND e.organization_id IS NOT NULL
       AND c.organization_id = e.organization_id
       AND e.organization_id = platform_private.h15_actor_organization());
$$;


ALTER FUNCTION platform_private.entrega_termo_tenant_ok(p_entrega_id uuid) OWNER TO postgres;

--
-- Name: envase_insert_final_v1(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.envase_insert_final_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE p platform_private.envase_insert_permits_v1%ROWTYPE;
BEGIN
 DELETE FROM platform_private.envase_insert_permits_v1 WHERE txid=txid_current() AND actor=auth.uid() AND action=TG_TABLE_NAME AND target=NEW.id AND admitted RETURNING * INTO p;
 IF FOUND THEN
  IF p.organization_id IS DISTINCT FROM platform_private.stock_envase_scope_v1(p.lote,p.prog,p.os,'manual')
   OR (to_jsonb(NEW)-'created_at'-'updated_at') IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'ENVASE_FINAL_PERMIT_MISMATCH' USING ERRCODE='42501'; END IF;
 ELSIF TG_TABLE_NAME='envase' THEN RAISE EXCEPTION 'ENVASE_FINAL_PERMIT_MISSING' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.envase_insert_final_v1() OWNER TO postgres;

--
-- Name: envase_insert_guard_v1(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.envase_insert_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE p platform_private.envase_insert_permits_v1%ROWTYPE; c record; parent public.estoque_produto%ROWTYPE; a jsonb; org uuid;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'ENVASE_ISOLATION_UNSUPPORTED' USING ERRCODE='0A000'; END IF;
 UPDATE platform_private.envase_insert_permits_v1 SET admitted=true WHERE txid=txid_current() AND actor=auth.uid() AND action=TG_TABLE_NAME AND target=NEW.id AND admitted=false RETURNING * INTO p;
 IF FOUND THEN
  IF p.organization_id IS DISTINCT FROM platform_private.stock_envase_scope_v1(p.lote,p.prog,p.os,'manual')
   OR NEW.lote_id IS DISTINCT FROM p.lote OR (to_jsonb(NEW)-'created_at'-'updated_at') IS DISTINCT FROM p.payload THEN RAISE EXCEPTION 'ENVASE_INSERT_PERMIT_MISMATCH' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 -- Preserve ONLY the installed canonical partial reservation semantics under
 -- its private txid/actor/parent context, not an invented envase permit.
 IF TG_TABLE_NAME='estoque_produto' THEN
  SELECT * INTO c FROM platform_private.stock_motor_context WHERE txid=txid_current() AND actor=auth.uid();
  IF FOUND AND c.ctx->>'acao'='reserva' AND c.item IS NOT NULL AND NEW.id<>c.item THEN
   SELECT * INTO parent FROM public.estoque_produto WHERE id=c.item;
   a:=c.ctx->'reserve_args'; org:=platform_private.stock_motor_actor('reserva');
   IF parent.status::text='disponivel' AND NEW.status::text='reservado' AND NEW.quantidade>0 AND NEW.quantidade<parent.quantidade
    AND NEW.quantidade_reservada=NEW.quantidade AND NEW.lote_id=parent.lote_id
    AND NEW.envase_id IS NOT DISTINCT FROM parent.envase_id AND NEW.produto_id IS NOT DISTINCT FROM parent.produto_id AND NEW.microrganismo_id IS NOT DISTINCT FROM parent.microrganismo_id
    AND NEW.validade IS NOT DISTINCT FROM parent.validade AND NEW.volume_total=NEW.quantidade*parent.volume_total/parent.quantidade
    AND NEW.reservado_para_os_id::text IS NOT DISTINCT FROM a->>'os_id' AND NEW.reservado_para_os_tipo IS NOT DISTINCT FROM a->>'os_tipo'
    AND NEW.reservado_para_cliente_id::text IS NOT DISTINCT FROM a->>'cliente_id'
    AND NEW.reservado_para_partner_id::text IS NOT DISTINCT FROM a->>'partner_id' AND NEW.reservado_para_partner_order_id::text IS NOT DISTINCT FROM a->>'partner_order_id'
    AND NEW.observacao_reserva IS NOT DISTINCT FROM a->>'observacao'
    AND EXISTS(SELECT 1 FROM public.lotes WHERE id=parent.lote_id AND organization_id=org) THEN RETURN NEW; END IF;
  END IF;
 END IF;
 RAISE EXCEPTION 'ENVASE_INSERT_CLOSED' USING ERRCODE='42501';
END $$;


ALTER FUNCTION platform_private.envase_insert_guard_v1() OWNER TO postgres;

--
-- Name: external_provisioning_scope(uuid, public.app_role[], uuid, uuid[], uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_roles public.app_role[], p_partner uuid, p_clients uuid[], p_primary uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid; snapshot jsonb; partner_snapshot jsonb; p_role public.app_role;
BEGIN
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_actor FOR UPDATE;
 IF p_actor IS NULL OR org IS NULL OR platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE
 OR public.has_role(p_actor,'administrador') IS NOT TRUE OR public.is_platform_superadmin(p_actor) IS TRUE
 THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF p_roles IS NULL OR cardinality(p_roles) NOT BETWEEN 1 AND 3 OR array_position(p_roles,NULL) IS NOT NULL OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r NOT IN ('parceiro_b2b','parceiro_b2b_tecnico','cliente_produtor')) THEN RAISE EXCEPTION 'c2_invalid_roles' USING ERRCODE='22023'; END IF;
 IF p_partner IS NOT NULL THEN
 IF NOT ('parceiro_b2b'=ANY(p_roles) OR 'parceiro_b2b_tecnico'=ANY(p_roles)) THEN RAISE EXCEPTION 'c2_partner_role_required'; END IF;
 IF p_partner IS NULL OR (NOT ('cliente_produtor'=ANY(p_roles)) AND (cardinality(p_clients) IS DISTINCT FROM 0 OR p_primary IS NOT NULL))
 OR NOT EXISTS(SELECT 1 FROM platform_private.entitlements_for_user(p_actor) WHERE feature_key='catalogo_precos') THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner FOR SHARE;
 SELECT jsonb_build_object('id',id,'updated_at',updated_at) INTO partner_snapshot FROM public.partner_accounts
 WHERE id=p_partner AND commercial_owner_organization_id=org AND ativo IS TRUE AND deleted_at IS NULL;
 IF partner_snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden'; END IF;
 END IF;
 IF 'cliente_produtor'=ANY(p_roles) THEN
 IF cardinality(p_clients) NOT BETWEEN 1 AND 100
 OR p_clients IS NULL OR array_position(p_clients,NULL) IS NOT NULL
 OR cardinality(p_clients)<>(SELECT count(DISTINCT id) FROM unnest(p_clients) id)
 OR p_primary IS NULL OR NOT (p_primary=ANY(p_clients)) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Explicit portal creation, never derive portal authority from technical user_clientes.
 PERFORM 1 FROM public.clientes WHERE id=ANY(p_clients) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.clientes WHERE id=ANY(p_clients) AND organization_id=org AND status_cliente='ativo')<>cardinality(p_clients) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) ORDER BY id) INTO snapshot FROM public.clientes WHERE id=ANY(p_clients);
 END IF;
 IF 'cliente_produtor'=ANY(p_roles) THEN PERFORM 1 FROM public.fazendas WHERE cliente_id=ANY(p_clients) ORDER BY id FOR SHARE; END IF;
 IF platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE OR public.has_role(p_actor,'administrador') IS NOT TRUE THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF 'cliente_produtor'=ANY(p_roles) AND EXISTS(SELECT 1 FROM unnest(p_clients) cid WHERE NOT EXISTS(SELECT 1 FROM public.fazendas f WHERE f.cliente_id=cid AND f.organization_id=org AND f.ativo)) THEN RAISE EXCEPTION 'c2_producer_farm_required'; END IF;
 IF p_partner IS NULL AND p_roles IS DISTINCT FROM ARRAY['cliente_produtor']::public.app_role[] THEN RAISE EXCEPTION 'c2_partner_required'; END IF;
 snapshot:=jsonb_build_object('partner',partner_snapshot,'clients',snapshot,'roles',to_jsonb(p_roles));
 IF snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('organization_id',org,'snapshot',snapshot);
END $$;


ALTER FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_roles public.app_role[], p_partner uuid, p_clients uuid[], p_primary uuid) OWNER TO postgres;

--
-- Name: external_provisioning_scope(uuid, public.app_role, uuid, uuid[], uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_role public.app_role, p_partner uuid, p_clients uuid[], p_primary uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid; snapshot jsonb;
BEGIN
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=p_actor FOR UPDATE;
 IF p_actor IS NULL OR org IS NULL OR platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE
 OR public.has_role(p_actor,'administrador') IS NOT TRUE OR public.is_platform_superadmin(p_actor) IS TRUE
 THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF p_role = 'parceiro_b2b' THEN
 IF p_partner IS NULL OR cardinality(p_clients) IS DISTINCT FROM 0 OR p_primary IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM platform_private.entitlements_for_user(p_actor) WHERE feature_key='catalogo_precos') THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.partner_accounts WHERE id=p_partner FOR SHARE;
 SELECT jsonb_build_object('id',id,'updated_at',updated_at) INTO snapshot FROM public.partner_accounts
 WHERE id=p_partner AND commercial_owner_organization_id=org AND ativo IS TRUE AND deleted_at IS NULL;
 ELSE
 IF p_role IS DISTINCT FROM 'cliente_produtor' OR p_partner IS NOT NULL OR cardinality(p_clients) NOT BETWEEN 1 AND 100
 OR p_clients IS NULL OR array_position(p_clients,NULL) IS NOT NULL
 OR cardinality(p_clients)<>(SELECT count(DISTINCT id) FROM unnest(p_clients) id)
 OR p_primary IS NULL OR NOT (p_primary=ANY(p_clients)) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 -- Explicit portal creation, never derive portal authority from technical user_clientes.
 PERFORM 1 FROM public.clientes WHERE id=ANY(p_clients) ORDER BY id FOR SHARE;
 IF (SELECT count(*) FROM public.clientes WHERE id=ANY(p_clients) AND organization_id=org AND status_cliente='ativo')<>cardinality(p_clients) THEN
 RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) ORDER BY id) INTO snapshot FROM public.clientes WHERE id=ANY(p_clients);
 END IF;
 IF platform_private.platform_actor_access_ready(p_actor) IS NOT TRUE OR public.has_role(p_actor,'administrador') IS NOT TRUE THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 IF snapshot IS NULL THEN RAISE EXCEPTION 'external_provisioning_forbidden' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('organization_id',org,'snapshot',snapshot);
END $$;


ALTER FUNCTION platform_private.external_provisioning_scope(p_actor uuid, p_role public.app_role, p_partner uuid, p_clients uuid[], p_primary uuid) OWNER TO postgres;

--
-- Name: get_partner_user_lifecycle(uuid, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.get_partner_user_lifecycle(p_partner_id uuid, p_user_id uuid, p_limit integer, p_before timestamp with time zone, p_before_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE actor uuid:=auth.uid(); org uuid; state jsonb; history jsonb; next_cursor jsonb;
BEGIN
 org:=public.h15_actor_organization();
 IF actor IS NULL OR org IS NULL OR platform_private.platform_actor_access_ready(actor) IS NOT TRUE
 OR NOT public.has_role(actor,'administrador'::public.app_role) OR public.is_platform_superadmin(actor)
 OR public.is_platform_superadmin(p_user_id)
 OR NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=org AND ativo AND status='ativa')
 OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_user_id AND organization_id=org AND ativo
   AND platform_private.platform_actor_access_ready(user_id))
 OR NOT EXISTS(SELECT 1 FROM public.partner_accounts WHERE id=p_partner_id AND commercial_owner_organization_id=org AND ativo AND deleted_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.partner_users WHERE user_id=p_user_id AND (partner_id<>p_partner_id OR tenant_id IS DISTINCT FROM org)) THEN
  RAISE EXCEPTION 'c2_forbidden' USING ERRCODE='42501'; END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR (p_before IS NULL)<>(p_before_id IS NULL) THEN
  RAISE EXCEPTION 'c2_invalid_page' USING ERRCODE='22023'; END IF;
 state:=jsonb_build_object('user',p_user_id,'partner',p_partner_id,'org',org,
   'roles',(SELECT COALESCE(array_agg(role::text ORDER BY role::text),ARRAY[]::text[]) FROM public.user_roles WHERE user_id=p_user_id),
   'link',(SELECT to_jsonb(pu) FROM public.partner_users pu WHERE user_id=p_user_id),
   'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=p_user_id));
 -- Immutable log scoped by partner + target + tenant BOTH before and after.
 -- Return an explicit audit whitelist, never raw payload/receipt/profile data.
 WITH eligible AS (
  SELECT a.* FROM public.partner_audit_logs a
  WHERE a.partner_id=p_partner_id AND a.acao='c2_partner_lifecycle'
    AND a.dados_anteriores->>'user'=p_user_id::text AND a.dados_anteriores->>'org'=org::text
    AND a.dados_novos->'state'->>'user'=p_user_id::text AND a.dados_novos->'state'->>'org'=org::text
    AND (p_before IS NULL OR (a.created_at,a.id)<(p_before,p_before_id))
  ORDER BY a.created_at DESC,a.id DESC LIMIT p_limit+1
 ), page AS (SELECT * FROM eligible ORDER BY created_at DESC,id DESC LIMIT p_limit)
 SELECT COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',id,'at',created_at,'actor_id',usuario_id,'reason',dados_novos->>'reason',
    'action',dados_novos->'receipt'->>'action',
    'before',jsonb_build_object('roles',dados_anteriores->'roles','link',
      CASE WHEN dados_anteriores->'link'='null'::jsonb THEN NULL ELSE jsonb_build_object(
       'partner_id',dados_anteriores->'link'->'partner_id','valid_from',dados_anteriores->'link'->'valid_from',
       'revoked_at',dados_anteriores->'link'->'revoked_at','version',dados_anteriores->'link'->'version') END),
    'after',jsonb_build_object('roles',dados_novos->'state'->'roles','link',
      CASE WHEN dados_novos->'state'->'link'='null'::jsonb THEN NULL ELSE jsonb_build_object(
       'partner_id',dados_novos->'state'->'link'->'partner_id','valid_from',dados_novos->'state'->'link'->'valid_from',
       'revoked_at',dados_novos->'state'->'link'->'revoked_at','version',dados_novos->'state'->'link'->'version') END)
   ) ORDER BY created_at DESC,id DESC) FROM page),'[]'::jsonb),
   CASE WHEN (SELECT count(*) FROM eligible)>p_limit THEN
    (SELECT jsonb_build_object('at',created_at,'id',id) FROM page ORDER BY created_at,id LIMIT 1) ELSE NULL END
 INTO history,next_cursor;
 RETURN jsonb_build_object('state',state,'version',md5(state::text),'history',history,'next_cursor',next_cursor);
END $$;


ALTER FUNCTION platform_private.get_partner_user_lifecycle(p_partner_id uuid, p_user_id uuid, p_limit integer, p_before timestamp with time zone, p_before_id uuid) OWNER TO postgres;

--
-- Name: global_product_fiscal_before_write(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.global_product_fiscal_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.is_active IS NOT TRUE THEN RAISE EXCEPTION 'FISCAL_HISTORY_IMMUTABLE' USING ERRCODE='42501'; END IF;
  IF NEW.product_id IS DISTINCT FROM OLD.product_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'FISCAL_IDENTITY_IMMUTABLE'; END IF;
  -- Server-owned CAS token for ALL direct editor and IBS/CBS updates.
  -- Strictly newer even inside one transaction; caller timestamps are ignored.
  -- The existing AFTER fiscal audit observes this token in the same transaction.
  NEW.updated_at:=greatest(clock_timestamp(),OLD.updated_at+interval '1 microsecond');
 ELSE NEW.updated_at:=clock_timestamp(); END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.global_product_fiscal_before_write() OWNER TO postgres;

--
-- Name: global_product_fiscal_ibs_save(uuid, jsonb, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.global_product_fiscal_ibs_save(p_product_id uuid, payload jsonb, expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE current_row public.product_fiscal_profiles; result public.product_fiscal_profiles; BEGIN
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Lock the same existing gate BEFORE the row; role revokers use this gate too.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE'; END IF;
 IF NOT platform_private.global_product_fiscal_write_ready() THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM public._fiscal_rtc_assert_payload(payload,'item');
 SELECT * INTO current_row FROM public.product_fiscal_profiles WHERE product_id=p_product_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 IF expected_revision IS NULL OR expected_revision<>current_row.updated_at::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='40001'; END IF;
 UPDATE public.product_fiscal_profiles SET ibs_cbs_configuration=payload WHERE id=current_row.id AND product_id=p_product_id AND is_active IS TRUE AND updated_at=current_row.updated_at RETURNING * INTO result;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='40001'; END IF;
 RETURN jsonb_build_object('configuration',result.ibs_cbs_configuration,'revision',result.updated_at::text);
END $$;


ALTER FUNCTION platform_private.global_product_fiscal_ibs_save(p_product_id uuid, payload jsonb, expected_revision text) OWNER TO postgres;

--
-- Name: global_product_fiscal_read_ready(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.global_product_fiscal_read_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT auth.uid() IS NOT NULL AND platform_private.platform_actor_access_ready(auth.uid()) AND
 (public.is_platform_superadmin(auth.uid()) OR platform_private.has_role(auth.uid(),'administrador') OR platform_private.has_role(auth.uid(),'gestor') OR platform_private.has_role(auth.uid(),'financeiro'));
$$;


ALTER FUNCTION platform_private.global_product_fiscal_read_ready() OWNER TO postgres;

--
-- Name: global_product_fiscal_statement_gate(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.global_product_fiscal_statement_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF TG_WHEN<>'BEFORE' OR TG_LEVEL<>'STATEMENT' OR TG_OP NOT IN ('INSERT','UPDATE') OR TG_RELID<>'public.product_fiscal_profiles'::regclass THEN RAISE EXCEPTION 'invalid_fiscal_guard_context' USING ERRCODE='42501'; END IF;
 IF current_setting('role',true) IN ('anon','authenticated') AND auth.uid() IS NULL THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION platform_private.global_product_fiscal_statement_gate() OWNER TO postgres;

