-- Name: is_same_tenant_user(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.is_same_tenant_user(p_target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_target_user_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.profiles target
       WHERE target.user_id = p_target_user_id
         AND target.organization_id = platform_private.current_user_organization_id()
     );
$$;


ALTER FUNCTION platform_private.is_same_tenant_user(p_target_user_id uuid) OWNER TO postgres;

--
-- Name: is_tenant_admin_for_user(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.is_tenant_admin_for_user(p_target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT auth.uid() IS NOT NULL
     AND public.has_role(auth.uid(), 'administrador'::public.app_role)
     AND NOT public.is_platform_superadmin(auth.uid())
     AND NOT public.is_platform_superadmin(p_target_user_id)
     AND platform_private.is_same_tenant_user(p_target_user_id);
$$;


ALTER FUNCTION platform_private.is_tenant_admin_for_user(p_target_user_id uuid) OWNER TO postgres;

--
-- Name: issue_saas_plan_version_ticket(text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.issue_saas_plan_version_ticket(_scope text, _target uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE = '42501';
  END IF;
  IF _scope NOT IN ('saas_plan_version_create','saas_plan_version_write','saas_plan_version_audit',
                    'saas_plan_version_archive','saas_plan_version_supersede') THEN
    RAISE EXCEPTION 'platform_invalid: escopo de autorização inválido' USING ERRCODE = '22023';
  END IF;
  IF _scope = 'saas_plan_version_supersede' THEN
    -- Alvo é a versão antecessora exata: publicada e com vigência aberta.
    IF NOT EXISTS (SELECT 1 FROM public.saas_plan_versions v
                    WHERE v.id = _target AND v.status = 'PUBLISHED' AND v.effective_to IS NULL) THEN
      RAISE EXCEPTION 'platform_invalid: versão antecessora inexistente ou não vigente' USING ERRCODE = '22023';
    END IF;
  ELSIF NOT EXISTS (SELECT 1 FROM public.saas_plans p WHERE p.id = _target) THEN
    RAISE EXCEPTION 'platform_invalid: plano inexistente' USING ERRCODE = '22023';
  END IF;
  INSERT INTO platform_private.authz_tickets(txid, scope, target)
  VALUES (txid_current(), _scope, _target) ON CONFLICT DO NOTHING;
END; $$;


ALTER FUNCTION platform_private.issue_saas_plan_version_ticket(_scope text, _target uuid) OWNER TO postgres;

--
-- Name: issue_ticket(text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
