    SET search_path TO ''
    AS $$
  INSERT INTO platform_private.authz_tickets(txid, scope, target)
  VALUES (txid_current(), _scope, _target) ON CONFLICT DO NOTHING;
$$;


ALTER FUNCTION platform_private.issue_ticket(_scope text, _target uuid) OWNER TO postgres;

--
-- Name: lab_assert_manufacturable(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.lab_assert_manufacturable(p_product_id uuid, p_microorganism_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT platform_private.lab_item_is_manufacturable(p_product_id,p_microorganism_id) THEN
    RAISE EXCEPTION 'LAB_ITEM_NOT_MANUFACTURABLE' USING ERRCODE='23514',
      HINT='Somente produtos biológicos e microrganismos podem gerar fabricação laboratorial.';
  END IF;
END $$;


ALTER FUNCTION platform_private.lab_assert_manufacturable(p_product_id uuid, p_microorganism_id uuid) OWNER TO postgres;

--
-- Name: lab_item_is_manufacturable(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.lab_item_is_manufacturable(p_product_id uuid, p_microorganism_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    -- Duas referências na mesma linha são ambíguas e falham fechadas. Isso impede que
    -- um microrganismo válido transforme produto químico/fertilizante em fabricável.
    WHEN p_product_id IS NOT NULL AND p_microorganism_id IS NOT NULL THEN false
    WHEN p_product_id IS NOT NULL THEN EXISTS(SELECT 1 FROM public.produtos p WHERE p.id=p_product_id AND p.familia_catalogo='biologico')
    WHEN p_microorganism_id IS NOT NULL THEN EXISTS(SELECT 1 FROM public.microrganismos m WHERE m.id=p_microorganism_id)
    ELSE false END
$$;


ALTER FUNCTION platform_private.lab_item_is_manufacturable(p_product_id uuid, p_microorganism_id uuid) OWNER TO postgres;

--
-- Name: lab_partner_order_authorized(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.lab_partner_order_authorized(p_order_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_org uuid;
BEGIN
 IF v_uid IS NULL OR NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id
 WHERE o.id=p_order_id AND p.commercial_owner_organization_id=v_org AND p.ativo IS TRUE AND p.deleted_at IS NULL
 AND (p.client_id IS NULL OR EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=p.client_id AND c.organization_id=v_org)));
END $$;


ALTER FUNCTION platform_private.lab_partner_order_authorized(p_order_id uuid) OWNER TO postgres;

--
-- Name: lab_visit_recommendation_lock(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.lab_visit_recommendation_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_id uuid; v_status text;
BEGIN
 FOR v_id IN SELECT DISTINCT id FROM unnest(ARRAY[
   CASE WHEN TG_OP<>'INSERT' THEN OLD.registro_consultor_id END,
   CASE WHEN TG_OP<>'DELETE' THEN NEW.registro_consultor_id END]) id WHERE id IS NOT NULL ORDER BY id LOOP
   SELECT status::text INTO v_status FROM public.registros_consultor WHERE id=v_id FOR UPDATE;
   IF v_status='convertido_os' THEN RAISE EXCEPTION 'VISIT07_REVIEW_REQUIRED' USING ERRCODE='23514',HINT='Visita já encaminhada; preserve a seleção e revise pelo fluxo técnico autorizado.'; END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.lab_visit_recommendation_lock() OWNER TO postgres;

--
-- Name: link_alert_origin_core(uuid, uuid, timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.link_alert_origin_core(p_alerta_id uuid, p_registro_id uuid, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta public.alertas_agronomicos;
  v_reg public.registros_consultor;
  v_receipt jsonb;
  v_updated timestamptz;
  v_obs text;
  v_fp text := md5(jsonb_build_object('op','link_origin','alerta',p_alerta_id,'visit',p_registro_id,
    'alert_at',p_expected_alert_updated_at,'version',p_expected_visit_version)::text);
BEGIN
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='42501';
  END IF;
  IF p_alerta_id IS NULL OR p_registro_id IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';
  END IF;
  IF p_expected_alert_updated_at IS NULL OR NOT isfinite(p_expected_alert_updated_at)
    OR p_expected_visit_version IS NULL OR p_expected_visit_version<=0 THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  SELECT * INTO v_alerta FROM public.alertas_agronomicos
   WHERE id=p_alerta_id AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,NULL)
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404'; END IF;
  v_reg := public._visita_lock_and_check(p_registro_id,NULL,false);
  -- Re-read authority after every wait (READ COMMITTED: new snapshot per statement).
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false)
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,NULL),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  SELECT jsonb_build_object('fp',fingerprint,'op',operation,'result',result) INTO v_receipt
    FROM platform_private.monitoring_alert_receipts
   WHERE actor_id=v_uid AND alerta_id=p_alerta_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'op'<>'link_origin' OR v_receipt->>'fp' IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  IF v_reg.status::text NOT IN ('rascunho','em_andamento') THEN
    RAISE EXCEPTION 'technical_record_content_locked' USING ERRCODE='42501';
  END IF;
  IF v_reg.version IS DISTINCT FROM p_expected_visit_version
    OR v_alerta.updated_at IS DISTINCT FROM p_expected_alert_updated_at THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    RAISE EXCEPTION 'alert_origin_already_linked' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.status::text NOT IN ('ativo','monitoramento') THEN
    RAISE EXCEPTION 'monitoring_alert_not_active' USING ERRCODE='P0001';
  END IF;
  -- Sync contract: at most one open alert per origin visit (its date is the visit/plan date).
  IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=p_registro_id
      AND o.id<>p_alerta_id AND o.status::text<>'encerrado') THEN
    RAISE EXCEPTION 'visit_already_has_origin_alert' USING ERRCODE='PT409';
  END IF;
  -- Supported scope only: one canonical plan block, present date, exactly one coherent notice.
  -- Checked BEFORE any alert write; nothing is created automatically.
  v_obs := coalesce(v_reg.observacoes_tecnicas,'');
  IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]')<>1
    OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]')<>1
    OR position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)
    OR v_reg.data_proxima_visita IS NULL
    OR (SELECT count(*) FROM regexp_matches(substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]'),'(^|\n)Próxima Avaliação: [^\n]*','g'))<>1
    OR substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]') !~ ('(^|\n)Próxima Avaliação: '||v_reg.data_proxima_visita::text||'(\n|$)')
    OR (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento')<>1
    OR NOT EXISTS(SELECT 1 FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento'
      AND data_referencia=v_reg.data_proxima_visita) THEN
    RAISE EXCEPTION 'origin_requires_saved_plan' USING ERRCODE='PT409';
  END IF;
  -- Date policy: linking never creates divergence; reprogram the alert first.
  IF v_alerta.data_vencimento IS DISTINCT FROM v_reg.data_proxima_visita THEN
    RAISE EXCEPTION 'origin_date_mismatch' USING ERRCODE='22023';
  END IF;
  -- Same farm and compatible plot; an alert without plot only matches by farm.
  IF v_reg.fazenda_id IS DISTINCT FROM v_alerta.fazenda_id
    OR (v_alerta.talhao_id IS NOT NULL AND v_reg.talhao_id IS DISTINCT FROM v_alerta.talhao_id)
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'origin_reference_mismatch' USING ERRCODE='22023';
  END IF;
  INSERT INTO platform_private.alert_origin_write_tickets VALUES(txid_current(),p_alerta_id);
  UPDATE public.alertas_agronomicos
     SET registro_origem_id=p_registro_id,
         updated_at=greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
   WHERE id=p_alerta_id AND updated_at=p_expected_alert_updated_at AND registro_origem_id IS NULL
   RETURNING updated_at INTO v_updated;
  IF NOT FOUND THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
  DELETE FROM platform_private.alert_origin_write_tickets WHERE transaction_id=txid_current() AND alerta_id=p_alerta_id;
  v_receipt := jsonb_build_object('ok',true,'alerta_id',p_alerta_id,'registro_origem_id',p_registro_id,
    'tipo_alerta',v_alerta.tipo_alerta,'alerta_updated_at',v_updated,'visit_version',v_reg.version,'request_id',p_request_id);
  INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
    VALUES(p_registro_id,v_uid,'alerta_origem_vinculada','Alerta agronômico vinculado à visita de origem',
      jsonb_build_object('request_id',p_request_id,'alerta_id',p_alerta_id,'fingerprint',v_fp));
  INSERT INTO platform_private.monitoring_alert_receipts VALUES(v_uid,p_alerta_id,p_request_id,'link_origin',v_fp,v_receipt);
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.link_alert_origin_core(p_alerta_id uuid, p_registro_id uuid, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: list_linkable_alerts_core(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.list_linkable_alerts_core(p_registro_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid := auth.uid(); v_reg public.registros_consultor;
BEGIN
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  SELECT * INTO v_reg FROM public.registros_consultor WHERE id=p_registro_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404'; END IF;
  RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'tipo_alerta',a.tipo_alerta,'nivel_risco',a.nivel_risco,
      'status',a.status,'data_vencimento',a.data_vencimento,'updated_at',a.updated_at,'descricao',a.descricao,
      'registro_origem_id',a.registro_origem_id) ORDER BY a.created_at DESC)
    FROM public.alertas_agronomicos a
    WHERE a.fazenda_id=v_reg.fazenda_id
      AND (a.talhao_id IS NULL OR a.talhao_id IS NOT DISTINCT FROM v_reg.talhao_id)
      AND a.status::text IN ('ativo','monitoramento')
      AND (a.registro_origem_id IS NULL OR a.registro_origem_id=p_registro_id)
      AND platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,p_registro_id)),'[]'::jsonb);
END;
$$;


ALTER FUNCTION platform_private.list_linkable_alerts_core(p_registro_id uuid) OWNER TO postgres;

--
-- Name: manual_cq_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.manual_cq_v1(p_os_id uuid, p_programacao_id uuid, p_cq jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 uid uuid:=auth.uid(); org uuid; os public.ordens_servico%ROWTYPE; pp public.programacao_producao%ROWTYPE;
 lot public.lotes%ROWTYPE; cq public.controle_qualidade%ROWTYPE; ref public.cq_parametros_referencia%ROWTYPE;
 key text; phase text; outcome text; v_ph numeric; concentration numeric; refid uuid;
 payload jsonb; receipt public.cockpit_operacao_idempotencia%ROWTYPE; receipt_key text; digest text;
 result jsonb; cqid uuid; profileid uuid;
BEGIN
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 org:=platform_private.h15_actor_organization();
 IF uid IS NULL OR org IS NULL OR public.technical_actor_ready(uid) IS NOT TRUE
 OR public._saas_user_has_feature(uid,'ordens_producao') IS NOT TRUE
 OR public._saas_user_has_feature(uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(uid,'administrador') OR public.has_role(uid,'gestor') OR public.has_role(uid,'producao')) IS NOT TRUE
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p_os_id IS NULL OR p_programacao_id IS NULL OR current_setting('transaction_isolation')<>'read committed' THEN
 RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 phase:=CASE WHEN p_cq IS NULL THEN 'enviar_cq' ELSE 'registrar_cq' END;
 IF p_cq IS NOT NULL THEN
  IF jsonb_typeof(p_cq) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  FOR key IN SELECT jsonb_object_keys(p_cq) LOOP
   IF key NOT IN ('lote_id','resultado','ph','concentracao','aparencia','odor','contaminacao','referencia_id','dados_sinteticos') THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  END LOOP;
  IF p_cq->'dados_sinteticos' IS DISTINCT FROM 'true'::jsonb OR p_cq->>'resultado' NOT IN ('aprovado','reprovado')
   OR jsonb_typeof(p_cq->'ph') IS DISTINCT FROM 'number' OR jsonb_typeof(p_cq->'concentracao') IS DISTINCT FROM 'number'
   OR jsonb_typeof(p_cq->'lote_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  outcome:=p_cq->>'resultado'; v_ph:=(p_cq->>'ph')::numeric; concentration:=(p_cq->>'concentracao')::numeric;
  IF outcome IS NULL OR v_ph::text IN ('NaN','Infinity','-Infinity') OR v_ph<0 OR v_ph>14
   OR concentration::text IN ('NaN','Infinity','-Infinity') OR concentration<0 OR concentration>1e30 THEN RAISE EXCEPTION 'CQ_VALUES_INVALID'; END IF;
  FOREACH key IN ARRAY ARRAY['aparencia','odor','contaminacao'] LOOP
   IF jsonb_typeof(p_cq->key) IS DISTINCT FROM 'string' OR length(btrim(p_cq->>key)) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'CQ_PAYLOAD_INVALID'; END IF;
  END LOOP;
  IF p_cq ? 'referencia_id' AND jsonb_typeof(p_cq->'referencia_id') NOT IN ('null','string') THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
  BEGIN refid:=nullif(p_cq->>'referencia_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END;
  payload:=p_cq||jsonb_build_object('aparencia',btrim(p_cq->>'aparencia'),'odor',btrim(p_cq->>'odor'),'contaminacao',btrim(p_cq->>'contaminacao'),'referencia_id',refid);
 ELSE payload:='{}'::jsonb; END IF;
 -- Same lock order / phantom fences as reviewed lot generation. No legacy assert-only delegation.
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 PERFORM pg_advisory_xact_lock(hashtext('cockpit_lote:'||p_programacao_id::text));
 SELECT * INTO os FROM public.ordens_servico WHERE id=p_os_id FOR UPDATE;
 IF os.id IS NULL OR os.organization_id IS DISTINCT FROM org THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=uid ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE id=p_programacao_id OR ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.lotes WHERE programacao_id=p_programacao_id ORDER BY id FOR UPDATE;
 IF public.technical_actor_ready(uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM org
 OR public._saas_user_has_feature(uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(uid,'administrador') OR public.has_role(uid,'gestor') OR public.has_role(uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=os.cliente_id AND c.organization_id=org)
 OR EXISTS(SELECT 1 FROM public.ordens_servico_onfarm WHERE id=p_os_id)
 OR (os.fazenda_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.fazendas f WHERE f.id=os.fazenda_id AND f.organization_id=org AND f.cliente_id=os.cliente_id AND f.ativo))
 OR (os.talhao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.talhoes t WHERE t.id=os.talhao_id AND t.organization_id=org AND t.fazenda_id=os.fazenda_id AND t.ativo))
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF os.origem='b2b' OR os.partner_order_id IS NOT NULL OR os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id)
 OR EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id)
 OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id)
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id)<>1
 OR (SELECT count(*) FROM public.lotes WHERE programacao_id=p_programacao_id)<>1
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO pp FROM public.programacao_producao WHERE id=p_programacao_id;
 SELECT * INTO lot FROM public.lotes WHERE programacao_id=p_programacao_id;
 IF pp.id IS NULL OR pp.organization_id IS DISTINCT FROM org OR pp.ordem_servico_id IS DISTINCT FROM p_os_id OR pp.ordem_servico_onfarm_id IS NOT NULL
 OR lot.organization_id IS DISTINCT FROM org OR lot.produto_id IS DISTINCT FROM pp.produto_id OR lot.microrganismo_id IS DISTINCT FROM pp.microrganismo_id
 OR pp.produto_id IS DISTINCT FROM os.produto_id OR pp.microrganismo_id IS DISTINCT FROM os.microrganismo_id
 OR pp.data_programada IS NULL OR pp.volume_necessario IS DISTINCT FROM os.volume_total_ml
 OR lot.volume_produzido IS NULL OR lot.volume_produzido<=0 OR lot.volume_produzido::text IN ('NaN','Infinity','-Infinity')
 OR pp.responsavel_id IS NOT NULL OR nullif(btrim(pp.responsavel),'') IS NOT NULL
 OR platform_private.lab_item_is_manufacturable(pp.produto_id,pp.microrganismo_id) IS NOT TRUE
 OR EXISTS(SELECT 1 FROM public.envase WHERE lote_id=lot.id) OR EXISTS(SELECT 1 FROM public.estoque_produto WHERE lote_id=lot.id)
 OR NOT EXISTS(SELECT 1 FROM public.laboratorio_esteira_eventos e WHERE e.lote_id=lot.id AND e.os_id=os.id AND e.programacao_id=pp.id AND e.origem_os='manual' AND e.acao='gerar_lote')
 THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p_cq IS NOT NULL AND (p_cq->>'lote_id') IS DISTINCT FROM lot.id::text THEN RAISE EXCEPTION 'CQ_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('cq_lote:'||lot.id::text));
 PERFORM 1 FROM public.controle_qualidade WHERE lote_id=lot.id ORDER BY seq FOR UPDATE;
 -- Resolve the canonical item, never infer/create a product->microorganism link.
 IF p_cq IS NOT NULL THEN
  LOCK TABLE public.cq_parametros_referencia IN SHARE MODE;
  IF (SELECT count(*) FROM public.cq_parametros_referencia r WHERE r.ativo IS TRUE AND
   ((pp.produto_id IS NOT NULL AND r.produto_id=pp.produto_id) OR
    (pp.produto_id IS NULL AND pp.microrganismo_id IS NOT NULL AND r.produto_id IS NULL AND r.microrganismo_id=pp.microrganismo_id)))>1
   THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
  SELECT r.* INTO ref FROM public.cq_parametros_referencia r WHERE r.ativo IS TRUE AND
   ((pp.produto_id IS NOT NULL AND r.produto_id=pp.produto_id) OR
    (pp.produto_id IS NULL AND pp.microrganismo_id IS NOT NULL AND r.produto_id IS NULL AND r.microrganismo_id=pp.microrganismo_id));
 END IF;
 IF p_cq IS NOT NULL AND refid IS DISTINCT FROM ref.id THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
 IF p_cq IS NOT NULL AND outcome='aprovado' AND ref.id IS NULL THEN RAISE EXCEPTION 'CQ_REFERENCE_REQUIRED'; END IF;
 IF ref.id IS NOT NULL AND (ref.ph_min IS NULL OR ref.ph_max IS NULL OR ref.concentracao_min_ufc_ml IS NULL
 OR ref.ph_min::text IN ('NaN','Infinity','-Infinity') OR ref.ph_max::text IN ('NaN','Infinity','-Infinity') OR ref.concentracao_min_ufc_ml::text IN ('NaN','Infinity','-Infinity')
 OR ref.ph_min<0 OR ref.ph_max>14 OR ref.ph_min>ref.ph_max OR ref.concentracao_min_ufc_ml<0
 OR nullif(btrim(ref.aparencia_esperada),'') IS NULL OR nullif(btrim(ref.odor_esperado),'') IS NULL OR nullif(btrim(ref.contaminacao_esperada),'') IS NULL)
 THEN RAISE EXCEPTION 'CQ_REFERENCE_INVALID'; END IF;
 IF p_cq IS NOT NULL AND outcome='aprovado' AND ref.id IS NOT NULL AND
 ((ref.ph_min IS NOT NULL AND v_ph<ref.ph_min) OR (ref.ph_max IS NOT NULL AND v_ph>ref.ph_max)
 OR (ref.concentracao_min_ufc_ml IS NOT NULL AND concentration<ref.concentracao_min_ufc_ml)
 OR (nullif(btrim(ref.aparencia_esperada),'') IS NOT NULL AND btrim(p_cq->>'aparencia')<>btrim(ref.aparencia_esperada))
 OR (nullif(btrim(ref.odor_esperado),'') IS NOT NULL AND btrim(p_cq->>'odor')<>btrim(ref.odor_esperado))
 OR (nullif(btrim(ref.contaminacao_esperada),'') IS NOT NULL AND btrim(p_cq->>'contaminacao')<>btrim(ref.contaminacao_esperada))) THEN RAISE EXCEPTION 'CQ_REFERENCE_FAILED'; END IF;
 receipt_key:='manual_cq_v1:'||phase||':'||lot.id::text;
 payload:=payload||jsonb_build_object('os_id',os.id,'programacao_id',pp.id,'lote_id',lot.id,'referencia_snapshot',CASE WHEN p_cq IS NULL OR ref.id IS NULL THEN NULL ELSE to_jsonb(ref) END);
 digest:=md5(payload::text);
 SELECT * INTO receipt FROM public.cockpit_operacao_idempotencia WHERE idempotency_key=receipt_key FOR UPDATE;
 IF receipt.idempotency_key IS NOT NULL THEN
  IF receipt.usuario_id IS DISTINCT FROM uid OR receipt.payload_hash IS DISTINCT FROM digest OR receipt.alvo_id IS DISTINCT FROM lot.id OR receipt.status<>'completed'
   OR os.status::text<>'em_cq' OR lot.status::text NOT IN ('aguardando_cq','aprovado','reprovado')
   OR (p_cq IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.controle_qualidade c WHERE c.id=(receipt.resultado->>'cq_id')::uuid AND c.lote_id=lot.id AND c.organization_id=org AND c.resultado::text=outcome AND c.ph=v_ph AND c.concentracao=concentration AND c.aparencia=payload->>'aparencia' AND c.odor=payload->>'odor' AND c.contaminacao=payload->>'contaminacao'))
  THEN RAISE EXCEPTION 'CQ_REPLAY_DIVERGENT'; END IF;
  RETURN receipt.resultado||jsonb_build_object('replay',true);
 END IF;
 SELECT id INTO profileid FROM public.profiles WHERE user_id=uid AND ativo AND organization_id=org;
 IF p_cq IS NULL THEN
  IF os.status::text<>'programada' OR pp.status::text<>'aguardando' OR lot.status::text<>'em_producao'
   OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=lot.id) THEN RAISE EXCEPTION 'CQ_STATE_INVALID'; END IF;
  INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(txid_current(),'manual_cq_send_v1',lot.id),(txid_current(),'manual_cq_send_v1',os.id),(txid_current(),'manual_cq_send_v1',pp.id);
  -- Ticket-specific transition reflects a pre-existing lot; never simulates production intermediate steps.
  UPDATE public.ordens_servico SET status='em_cq' WHERE id=os.id;
 ELSE
  IF os.status::text<>'em_cq' OR pp.status::text<>'aguardando_cq' OR lot.status::text<>'aguardando_cq'
   OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=lot.id)
   OR NOT EXISTS(SELECT 1 FROM public.cockpit_operacao_idempotencia WHERE idempotency_key='manual_cq_v1:enviar_cq:'||lot.id::text AND status='completed') THEN RAISE EXCEPTION 'CQ_STATE_INVALID'; END IF;
  cqid:=gen_random_uuid();
  INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(txid_current(),'manual_cq_'||outcome||'_v1',lot.id),(txid_current(),'manual_cq_'||outcome||'_v1',pp.id),(txid_current(),'manual_cq_insert_v1',cqid);
  INSERT INTO public.controle_qualidade(id,lote_id,ph,concentracao,aparencia,odor,contaminacao,responsavel,responsavel_id,resultado,organization_id)
  VALUES(cqid,lot.id,v_ph,concentration,payload->>'aparencia',payload->>'odor',payload->>'contaminacao','DADOS FICTICIOS SEM VALOR COMERCIAL',profileid,outcome::public.resultado_cq,org);
  UPDATE public.lotes SET status=outcome::public.status_lote WHERE id=lot.id;
  IF outcome='aprovado' THEN UPDATE public.programacao_producao SET status='aprovado' WHERE id=pp.id; END IF;
 END IF;
 IF (SELECT status::text FROM public.ordens_servico WHERE id=os.id)<>'em_cq'
 OR (SELECT status::text FROM public.lotes WHERE id=lot.id)<>(CASE WHEN p_cq IS NULL THEN 'aguardando_cq' ELSE outcome END)
 OR (SELECT status::text FROM public.programacao_producao WHERE id=pp.id)<>(CASE WHEN outcome='aprovado' THEN 'aprovado' ELSE 'aguardando_cq' END)
 OR public.technical_actor_ready(uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM org THEN RAISE EXCEPTION 'CQ_POSTCONDITION_FAILED'; END IF;
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,lote_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 VALUES(os.id,'manual',pp.id,lot.id,os.status::text,CASE WHEN p_cq IS NULL THEN 'aguardando_cq' ELSE outcome END,phase,uid,'DADOS FICTICIOS SEM VALOR COMERCIAL; sem producao fisica/venda/uso agricola. '||payload::text);
 result:=jsonb_build_object('success',true,'replay',false,'lote_id',lot.id,'cq_id',cqid,'status','em_cq','resultado',outcome);
 INSERT INTO public.cockpit_operacao_idempotencia(idempotency_key,operacao,usuario_id,resultado,payload_hash,alvo_id,status)
 VALUES(receipt_key,phase,uid,result,digest,lot.id,'completed');
 DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope IN ('manual_cq_send_v1','manual_cq_aprovado_v1','manual_cq_reprovado_v1','manual_cq_insert_v1');
 RETURN result;
END $$;


ALTER FUNCTION platform_private.manual_cq_v1(p_os_id uuid, p_programacao_id uuid, p_cq jsonb) OWNER TO postgres;

--
-- Name: monitoring_refs_in_actor_tenant(uuid, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.monitoring_refs_in_actor_tenant(p_fazenda uuid, p_talhao uuid, p_origem uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.technical_actor_ready(auth.uid()) AND EXISTS(
 SELECT 1 FROM public.fazendas f WHERE f.id=p_fazenda
 AND public.technical_refs_in_actor_tenant(f.cliente_id,f.id,p_talhao)
 AND (p_origem IS NULL OR EXISTS(SELECT 1 FROM public.registros_consultor r
 WHERE r.id=p_origem AND r.cliente_id=f.cliente_id AND r.fazenda_id=f.id
 AND (p_talhao IS NULL OR r.talhao_id IS NOT DISTINCT FROM p_talhao)
 AND public.technical_refs_in_actor_tenant(r.cliente_id,r.fazenda_id,r.talhao_id))));
$$;


ALTER FUNCTION platform_private.monitoring_refs_in_actor_tenant(p_fazenda uuid, p_talhao uuid, p_origem uuid) OWNER TO postgres;

--
-- Name: my_entitlement_context(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.my_entitlement_context() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_org uuid;
  v_status public.saas_subscription_status;
  v_version uuid;
  v_trial_end timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'saas_auth_required' USING ERRCODE = '42501';
  END IF;

  IF public.is_platform_superadmin(auth.uid()) THEN
    RETURN 'platform_superadmin';
  END IF;

  SELECT p.organization_id
    INTO v_org
  FROM public.profiles p
  JOIN public.organizations org
    ON org.id = p.organization_id
   AND org.ativo IS TRUE
  WHERE p.user_id = auth.uid()
    AND p.ativo IS TRUE
    AND p.organization_id IS NOT NULL
  LIMIT 1;

  IF v_org IS NULL THEN RETURN 'no_context'; END IF;

  SELECT s.status, s.plan_version_id, s.trial_ends_at
    INTO v_status, v_version, v_trial_end
  FROM public.organization_subscriptions s
  WHERE s.organization_id = v_org
  ORDER BY s.started_at DESC, s.id DESC
  LIMIT 1;

  IF NOT FOUND THEN RETURN 'no_subscription'; END IF;
  IF v_version IS NULL THEN RETURN 'legacy_unversioned'; END IF;
  IF v_status = 'ACTIVE' THEN RETURN 'active'; END IF;
  IF v_status = 'TRIAL' AND v_trial_end IS NOT NULL AND v_trial_end > now() THEN RETURN 'trial_active'; END IF;
  IF v_status = 'TRIAL' THEN RETURN 'trial_expired'; END IF;
  RETURN 'blocked_status';
END;
$$;


ALTER FUNCTION platform_private.my_entitlement_context() OWNER TO postgres;

--
-- Name: normalize_commercial_reason(text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.normalize_commercial_reason(_reason text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_reason text := btrim(coalesce(_reason, ''));
BEGIN
  IF char_length(v_reason) < 2 THEN
    RAISE EXCEPTION 'platform_invalid: motivo deve ter pelo menos 2 caracteres' USING ERRCODE = '22023';
  END IF;
  RETURN v_reason;
END;
$$;


ALTER FUNCTION platform_private.normalize_commercial_reason(_reason text) OWNER TO postgres;

--
-- Name: notification_external_block(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_external_block() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION 'NOTIF_EXTERNAL_DELIVERY_DISABLED' USING ERRCODE='42501'; END $$;


ALTER FUNCTION platform_private.notification_external_block() OWNER TO postgres;

--
-- Name: notification_outbox_closed(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_outbox_closed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.template_chave='tenant_smtp_diagnostic_v1' AND NEW.status='processing' AND NEW.max_attempts=1 AND NEW.lease_expires_at IS NULL
 AND NEW.attempts=1 AND NEW.canal='email' AND NEW.recipient_cliente_id IS NULL AND NEW.recipient_hash IS NULL
 AND EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_insert_tickets t
 JOIN public.comunicacao_eventos e ON e.id=NEW.event_id
 WHERE t.outbox_id=NEW.id AND t.tx=txid_current() AND NEW.recipient_user_id=t.actor_id
 AND platform_private.tenant_smtp_test_actor(t.actor_id)=t.organization_id
 AND e.source_type='tenant_smtp_diagnostic_v1' AND e.source_id=t.organization_id AND e.created_by=t.actor_id
 AND e.event_key='tenant.smtp.diagnostic' AND e.status='processed') THEN RETURN NEW; END IF;
 IF NEW.template_chave='solicitacao_atribuida_consultor_v1' AND NEW.status='processing' AND NEW.max_attempts=1 AND NEW.lease_expires_at IS NULL
 AND NEW.attempts=0 AND NEW.canal='email' AND NEW.recipient_cliente_id IS NULL AND NEW.recipient_hash IS NULL AND NEW.locked_by='tenant_smtp_lane'
 AND EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_insert_tickets t
 JOIN public.comunicacao_eventos e ON e.id=NEW.event_id
 WHERE t.outbox_id=NEW.id AND t.tx=txid_current() AND NEW.recipient_user_id=t.recipient_user_id
 AND platform_private.tenant_smtp_lane_recipient(t.organization_id,t.recipient_user_id) IS NOT NULL
 AND e.source_type='portal_solicitacoes' AND e.source_id=t.source_id
 AND e.event_key='tenant.smtp.solicitacao_atribuida' AND e.status='processed') THEN RETURN NEW; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION platform_private.notification_outbox_closed() OWNER TO postgres;

--
-- Name: notification_p1_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_p1_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE org uuid; uid uuid; cid uuid; BEGIN
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-'lido') IS DISTINCT FROM (to_jsonb(OLD)-'lido') THEN RAISE EXCEPTION 'NOTIF_CONTENT_IMMUTABLE' USING ERRCODE='42501'; END IF;
  RETURN NEW;
 END IF;
 -- Unknown source is quarantined, not attributed from recipient or message/link. Preserve parent operations.
 IF NEW.source_type IS NULL OR NEW.source_id IS NULL THEN RETURN NULL; END IF;
 org:=platform_private.notification_source_org(NEW.source_type,NEW.source_id);
 IF TG_TABLE_NAME='notificacoes_operacionais' THEN uid:=NEW.usuario_id; ELSE uid:=NEW.recipient_user_id; cid:=NEW.cliente_id; END IF;
 IF NOT COALESCE(platform_private.notification_user_ok(uid,org),false) THEN RAISE EXCEPTION 'NOTIF_SOURCE_RECIPIENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF cid IS NOT NULL AND (platform_private.notification_source_client(NEW.source_type,NEW.source_id) IS DISTINCT FROM cid OR NOT public.has_role(uid,'cliente_produtor') OR NOT public._portal_cliente_user_has_link(uid,cid) OR NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cid AND c.organization_id=org)) THEN RAISE EXCEPTION 'NOTIF_PORTAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.tipo::text='sistema' THEN RAISE EXCEPTION 'NOTIF_GLOBAL_PRODUCER_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN NEW; END $$;


ALTER FUNCTION platform_private.notification_p1_guard() OWNER TO postgres;

--
-- Name: notification_p1_visible(uuid, text, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_p1_visible(uid uuid, st text, sid uuid, cid uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE org uuid; BEGIN
 org:=platform_private.notification_source_org(st,sid);
 IF uid IS DISTINCT FROM auth.uid() OR NOT COALESCE(platform_private.notification_user_ok(uid,org),false) OR public.h15_actor_organization() IS DISTINCT FROM org THEN RETURN false; END IF;
 IF cid IS NOT NULL THEN
IF platform_private.notification_source_client(st,sid) IS DISTINCT FROM cid THEN RETURN false; END IF;
  RETURN public.has_role(uid,'cliente_produtor') AND EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=cid AND c.organization_id=org) AND public._portal_cliente_user_has_link(uid,cid);
 END IF;
 RETURN true; END $$;


ALTER FUNCTION platform_private.notification_p1_visible(uid uuid, st text, sid uuid, cid uuid) OWNER TO postgres;

--
-- Name: notification_source_client(text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_source_client(st text, sid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE cid uuid; BEGIN CASE st WHEN 'registros_consultor','registro_consultor','monitoramento_vencido' THEN SELECT cliente_id INTO cid FROM public.registros_consultor WHERE id=sid; WHEN 'portal_solicitacoes' THEN SELECT cliente_id INTO cid FROM public.portal_solicitacoes WHERE id=sid; WHEN 'ordem_servico','ordens_servico' THEN SELECT cliente_id INTO cid FROM public.ordens_servico WHERE id=sid; WHEN 'aplicacao','aplicacoes' THEN SELECT o.cliente_id INTO cid FROM public.aplicacoes a JOIN public.ordens_servico o ON o.id=a.ordem_servico_id WHERE a.id=sid AND a.ordem_servico_onfarm_id IS NULL; ELSE RETURN NULL; END CASE; RETURN cid; END $$;


ALTER FUNCTION platform_private.notification_source_client(st text, sid uuid) OWNER TO postgres;

--
-- Name: notification_source_org(text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_source_org(st text, sid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v uuid; BEGIN
 IF sid IS NULL THEN RETURN NULL; END IF;
 CASE st
 WHEN 'registros_consultor','registro_consultor','monitoramento_vencido' THEN SELECT c.organization_id INTO v FROM public.registros_consultor r JOIN public.clientes c ON c.id=r.cliente_id WHERE r.id=sid;
 WHEN 'ordem_servico','ordens_servico' THEN SELECT o.organization_id INTO v FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=sid;
 WHEN 'portal_solicitacoes' THEN SELECT c.organization_id INTO v FROM public.portal_solicitacoes s JOIN public.clientes c ON c.id=s.cliente_id WHERE s.id=sid;
 WHEN 'programacao_producao' THEN SELECT p.organization_id INTO v FROM public.programacao_producao p WHERE p.id=sid AND ((p.ordem_servico_id IS NOT NULL AND p.ordem_servico_onfarm_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE o.id=p.ordem_servico_id AND o.organization_id=p.organization_id)) OR (p.ordem_servico_onfarm_id IS NOT NULL AND p.ordem_servico_id IS NULL AND EXISTS(SELECT 1 FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=p.ordem_servico_onfarm_id AND c.organization_id=p.organization_id)));
 WHEN 'estoque_produto' THEN RETURN NULL;
 WHEN 'aplicacao','aplicacoes' THEN SELECT a.organization_id INTO v FROM public.aplicacoes a JOIN public.ordens_servico o ON o.id=a.ordem_servico_id AND o.organization_id=a.organization_id JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=o.organization_id WHERE a.id=sid AND a.ordem_servico_onfarm_id IS NULL;
 WHEN 'partner_orders' THEN SELECT c.organization_id INTO v FROM public.partner_orders o JOIN public.partner_accounts p ON p.id=o.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE o.id=sid;
 WHEN 'partner_simulations' THEN SELECT c.organization_id INTO v FROM public.partner_simulations s JOIN public.partner_accounts p ON p.id=s.partner_id AND p.ativo IS TRUE AND p.deleted_at IS NULL JOIN public.clientes c ON c.id=p.client_id WHERE s.id=sid;
 ELSE RETURN NULL; END CASE;
 IF NOT EXISTS(SELECT 1 FROM public.organizations o WHERE o.id=v AND o.ativo IS TRUE) THEN RETURN NULL; END IF;
 RETURN v; END $$;


ALTER FUNCTION platform_private.notification_source_org(st text, sid uuid) OWNER TO postgres;

--
-- Name: notification_user_ok(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.notification_user_ok(uid uuid, org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT org IS NOT NULL AND public.h15_user_organization(uid)=org AND platform_private.platform_actor_access_ready(uid); $$;


ALTER FUNCTION platform_private.notification_user_ok(uid uuid, org uuid) OWNER TO postgres;

--
-- Name: onboarding_validar(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.onboarding_validar(_d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  spec jsonb := '{"razao_social":200,"nome_fantasia":200,"cnpj":18,"inscricao_estadual":20,"regime_tributario":40,"cep":9,"logradouro":200,"numero":20,"complemento":120,"bairro":120,"cidade":120,"uf":2,"telefone":20,"email_contato":255,"responsavel_nome":160,"responsavel_cargo":120,"fuso_horario":64,"idioma":10}'::jsonb;
  regimes constant text[] := ARRAY['simples_nacional','mei','lucro_presumido','lucro_real','imune_isenta','outros'];
  fusos constant text[] := ARRAY['America/Sao_Paulo','America/Manaus','America/Cuiaba','America/Campo_Grande','America/Rio_Branco','America/Noronha'];
  ufs constant text[] := ARRAY['AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'];
  k text; v jsonb; s text; out jsonb := '{}'::jsonb;
BEGIN
  IF _d IS NULL OR jsonb_typeof(_d) <> 'object' THEN RAISE EXCEPTION 'org_invalid: dados inválidos'; END IF;
  IF length(_d::text) > 8000 THEN RAISE EXCEPTION 'org_invalid: dados muito grandes'; END IF;
  FOR k, v IN SELECT * FROM jsonb_each(_d) LOOP
    IF k = 'confirmado' THEN
      IF jsonb_typeof(v) <> 'boolean' THEN RAISE EXCEPTION 'org_invalid: confirmado inválido'; END IF;
      out := out || jsonb_build_object(k, v); CONTINUE;
    END IF;
    IF NOT spec ? k THEN RAISE EXCEPTION 'org_invalid: campo não permitido (%)', left(k, 40); END IF;
    IF jsonb_typeof(v) = 'null' THEN CONTINUE; END IF;
    IF jsonb_typeof(v) <> 'string' THEN RAISE EXCEPTION 'org_invalid: % deve ser texto', k; END IF;
    s := btrim(v #>> '{}');
    IF length(s) > (spec->>k)::int THEN RAISE EXCEPTION 'org_invalid: % muito longo', k; END IF;
    IF s ~ '[\x00-\x08\x0B\x0C\x0E-\x1F<>]' THEN RAISE EXCEPTION 'org_invalid: % contém caracteres inválidos', k; END IF;
    IF s <> '' THEN
      IF k = 'uf' AND NOT (upper(s) = ANY(ufs)) THEN RAISE EXCEPTION 'org_invalid: UF inválida'; END IF;
      IF k = 'cep' THEN IF s !~ '^\d{5}-?\d{3}$' THEN RAISE EXCEPTION 'org_invalid: CEP inválido'; END IF;
        s := regexp_replace(s,'\D','','g'); s := substr(s,1,5)||'-'||substr(s,6,3); END IF;
      IF k = 'telefone' THEN s := regexp_replace(s,'\D','','g'); IF s !~ '^\d{10,11}$' THEN RAISE EXCEPTION 'org_invalid: telefone inválido'; END IF; END IF;
      IF k = 'email_contato' THEN s := lower(s); IF s !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'org_invalid: e-mail inválido'; END IF; END IF;
      IF k = 'fuso_horario' AND NOT (s = ANY(fusos)) THEN RAISE EXCEPTION 'org_invalid: fuso horário inválido'; END IF;
      IF k = 'regime_tributario' AND NOT (s = ANY(regimes)) THEN RAISE EXCEPTION 'org_invalid: regime tributário inválido'; END IF;
      IF k = 'cnpj' AND NOT platform_private.cnpj_valido(s) THEN RAISE EXCEPTION 'org_invalid: CNPJ inválido (dígitos verificadores)'; END IF;
      IF k = 'uf' THEN s := upper(s); END IF;
    END IF;
    out := out || jsonb_build_object(k, s);
  END LOOP;
  RETURN out;
END $_$;


ALTER FUNCTION platform_private.onboarding_validar(_d jsonb) OWNER TO postgres;

--
-- Name: org_cadastro_patch(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.org_cadastro_patch(_d jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  permitidos constant text[] := ARRAY['telefone','email_contato','responsavel_nome','responsavel_cargo','cep','logradouro','numero','complemento','bairro','cidade','uf','inscricao_estadual','fuso_horario'];
  k text;
BEGIN
  IF _d IS NULL THEN RETURN '{}'::jsonb; END IF;
  IF jsonb_typeof(_d) <> 'object' THEN RAISE EXCEPTION 'platform_invalid: dados inválidos' USING ERRCODE='22023'; END IF;
  FOR k IN SELECT jsonb_object_keys(_d) LOOP
    IF NOT (k = ANY(permitidos)) THEN RAISE EXCEPTION 'platform_invalid: campo não permitido (%)', left(k,40) USING ERRCODE='22023'; END IF;
  END LOOP;
  RETURN platform_private.onboarding_validar(_d);
END $$;


ALTER FUNCTION platform_private.org_cadastro_patch(_d jsonb) OWNER TO postgres;

--
-- Name: organization_fiscal_summary_core(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.organization_fiscal_summary_core(_org uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r record;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  SELECT f.legal_name, f.cnpj, f.state_registration, f.municipal_registration, f.tax_regime, f.crt,
         f.primary_cnae, f.configuration_status, f.nfe_enabled, f.nfse_enabled, f.is_active, f.updated_at
    INTO r FROM public.company_fiscal_settings f
   WHERE f.organization_id = _org
   ORDER BY f.is_active DESC NULLS LAST, f.updated_at DESC NULLS LAST LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('configurado', false); END IF;
  RETURN jsonb_build_object('configurado', true, 'razao_social', r.legal_name, 'cnpj', r.cnpj,
    'inscricao_estadual', r.state_registration, 'inscricao_municipal', r.municipal_registration,
    'regime_tributario', r.tax_regime, 'crt', r.crt, 'cnae_principal', r.primary_cnae,
    'situacao', r.configuration_status, 'nfe_habilitada', r.nfe_enabled, 'nfse_habilitada', r.nfse_enabled,
    'ativo', r.is_active, 'atualizado_em', r.updated_at);
END $$;


ALTER FUNCTION platform_private.organization_fiscal_summary_core(_org uuid) OWNER TO postgres;

--
-- Name: platform_actor_access_ready(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.platform_actor_access_ready(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user AND p.ativo IS TRUE AND p.senha_provisoria IS FALSE)
 AND NOT EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_user AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND auth.uid()=p_user AND to_timestamp(COALESCE((auth.jwt()->>'iat')::bigint,0))<=i.access_valid_after)));
$$;


ALTER FUNCTION platform_private.platform_actor_access_ready(p_user uuid) OWNER TO postgres;

--
-- Name: platform_read_global_product_catalog_core(text, integer, integer); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.platform_read_global_product_catalog_core(p_search text, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor uuid := auth.uid();
  v_search text;
  v_result jsonb;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  -- Signed session iat only; no user_metadata/app_metadata authorization or GUC ticket.
  IF pg_catalog.jsonb_typeof(auth.jwt()->'iat') IS DISTINCT FROM 'number'
     OR COALESCE(auth.jwt()->>'iat', '') !~ '^[0-9]{1,12}$' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  IF (auth.jwt()->>'iat')::bigint <= 0
     OR NOT COALESCE(platform_private.platform_actor_access_ready(v_actor), false)
     OR NOT COALESCE(public.has_role(v_actor, 'superadmin'::public.app_role), false)
     OR NOT COALESCE(public.is_platform_superadmin(v_actor), false) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'platform_catalog_forbidden';
  END IF;
  IF p_limit IS NULL OR p_limit < 1 OR p_limit > 50
     OR p_offset IS NULL OR p_offset < 0 OR p_offset > 1000000
     OR p_search IS NULL OR pg_catalog.char_length(p_search) > 120 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'platform_catalog_invalid_query';
  END IF;
  v_search := pg_catalog.lower(pg_catalog.btrim(p_search));
  -- Literal substring: %, _, quotes are data, not wildcard/filter syntax.
  -- One snapshot, deterministic tie-breaker; only an extra sentinel is read.
  WITH bounded AS MATERIALIZED (
    SELECT p.id, p.codigo, p.nome, p.tipo, p.ativo, p.b2b_enabled, p.updated_at
    FROM public.produtos p
    WHERE v_search = ''
       OR pg_catalog.strpos(pg_catalog.lower(p.nome), v_search) > 0
       OR pg_catalog.strpos(pg_catalog.lower(COALESCE(p.codigo, '')), v_search) > 0
    ORDER BY pg_catalog.lower(p.nome) COLLATE "C", p.id
    LIMIT (p_limit + 1) OFFSET p_offset
  ), page AS (
    SELECT b.id, b.codigo, b.nome, b.tipo, b.ativo, b.b2b_enabled, b.updated_at
    FROM bounded b
    ORDER BY pg_catalog.lower(b.nome) COLLATE "C", b.id LIMIT p_limit
  )
  SELECT pg_catalog.jsonb_build_object(
    'items', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)
      ORDER BY pg_catalog.lower(r.nome) COLLATE "C", r.id) FROM page r), '[]'::jsonb),
    'has_more', (SELECT pg_catalog.count(*) > p_limit FROM bounded)
  ) INTO v_result;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION platform_private.platform_read_global_product_catalog_core(p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: producer_commercial_client_scope(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.producer_commercial_client_scope(p_client uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT auth.uid() IS NOT NULL AND p_client IS NOT NULL
 AND platform_private.platform_actor_access_ready(auth.uid()) IS TRUE
 AND EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
 JOIN public.clientes c ON c.id=p_client AND c.organization_id=p.organization_id
 WHERE p.user_id=auth.uid() AND p.ativo IS TRUE AND p.senha_provisoria IS FALSE
 AND o.ativo IS TRUE AND c.status_cliente='ativo'
 AND (public.has_role(auth.uid(),'administrador'::public.app_role)
 OR public.has_role(auth.uid(),'gestor'::public.app_role)
 OR public.has_role(auth.uid(),'cliente_produtor'::public.app_role))
 AND p_client=ANY(public.get_cliente_ids_for_user(auth.uid())));
$$;


ALTER FUNCTION platform_private.producer_commercial_client_scope(p_client uuid) OWNER TO postgres;

--
-- Name: produto_etiqueta_root_org_v1(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.produto_etiqueta_root_org_v1(p_lote uuid, p_produto uuid, p_envase uuid, p_envase_item uuid, p_estoque_item uuid, p_embalagem uuid, p_entrega uuid, p_entrega_item uuid, p_cliente uuid, p_fazenda uuid, p_substitui uuid, p_substituida_por uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT l.organization_id FROM public.lotes l
  WHERE l.id = p_lote AND l.organization_id IS NOT NULL
    -- envase_item_id / entrega_item_id have no referenced table (opaque): any non-null value cannot be proven => deny.
    AND p_envase_item IS NULL AND p_entrega_item IS NULL
    -- global catalogue product: no tenant; only must match the lot's product when both are set.
    AND (p_produto IS NULL OR l.produto_id IS NULL OR l.produto_id = p_produto)
    AND (p_envase IS NULL OR EXISTS (SELECT 1 FROM public.envase v WHERE v.id = p_envase AND v.lote_id = l.id AND v.organization_id = l.organization_id))
    AND (p_estoque_item IS NULL OR EXISTS (SELECT 1 FROM public.estoque_produto s WHERE s.id = p_estoque_item AND s.lote_id = l.id
          AND (p_envase IS NULL OR s.envase_id IS NULL OR s.envase_id = p_envase)))
    AND (p_embalagem IS NULL OR EXISTS (SELECT 1 FROM public.estoque_embalagens m WHERE m.id = p_embalagem AND m.lote_id = l.id
          AND (p_envase IS NULL OR m.envase_id IS NULL OR m.envase_id = p_envase)
          AND (m.cliente_id IS NULL OR EXISTS (SELECT 1 FROM public.clientes mc WHERE mc.id = m.cliente_id AND mc.organization_id = l.organization_id))))
    AND (p_entrega IS NULL OR EXISTS (SELECT 1 FROM public.entregas e WHERE e.id = p_entrega AND e.organization_id = l.organization_id))
    AND (p_cliente IS NULL OR EXISTS (SELECT 1 FROM public.clientes c WHERE c.id = p_cliente AND c.organization_id = l.organization_id))
    AND (p_fazenda IS NULL OR EXISTS (SELECT 1 FROM public.fazendas f WHERE f.id = p_fazenda AND f.organization_id = l.organization_id
          AND (p_cliente IS NULL OR f.cliente_id = p_cliente)))
    -- substitutions: referenced label's own immutable lot must be of the same organization (one level, direct table
    -- read inside this DEFINER helper; no policy or helper recursion).
    AND (p_substitui IS NULL OR EXISTS (SELECT 1 FROM public.produto_etiquetas r JOIN public.lotes rl ON rl.id = r.lote_id
          WHERE r.id = p_substitui AND rl.organization_id = l.organization_id))
    AND (p_substituida_por IS NULL OR EXISTS (SELECT 1 FROM public.produto_etiquetas r JOIN public.lotes rl ON rl.id = r.lote_id
          WHERE r.id = p_substituida_por AND rl.organization_id = l.organization_id))
$$;


ALTER FUNCTION platform_private.produto_etiqueta_root_org_v1(p_lote uuid, p_produto uuid, p_envase uuid, p_envase_item uuid, p_estoque_item uuid, p_embalagem uuid, p_entrega uuid, p_entrega_item uuid, p_cliente uuid, p_fazenda uuid, p_substitui uuid, p_substituida_por uuid) OWNER TO postgres;

--
-- Name: read_global_b2b_state_core(text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_b2b_state_core(p_item_tipo text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_out jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_item_tipo IS NULL OR p_item_tipo NOT IN ('produto','microrganismo') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_invalid'; END IF;
  IF p_item_tipo='produto' THEN
    SELECT pg_catalog.jsonb_build_object('item_tipo','produto','id',p.id,'nome',p.nome,'codigo',p.codigo,
      'ativo',COALESCE(p.ativo,false),'b2b_enabled',p.b2b_enabled,'updated_at',p.updated_at)
      INTO v_out FROM public.produtos p WHERE p.id=p_id;
  ELSE
    SELECT pg_catalog.jsonb_build_object('item_tipo','microrganismo','id',m.id,'nome',m.nome,'codigo',m.codigo,
      'ativo',m.ativo,'b2b_enabled',m.b2b_enabled,'updated_at',m.updated_at)
      INTO v_out FROM public.microrganismos m WHERE m.id=p_id;
  END IF;
  IF v_out IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
  RETURN v_out;
END;
$$;


ALTER FUNCTION platform_private.read_global_b2b_state_core(p_item_tipo text, p_id uuid) OWNER TO postgres;

--
-- Name: read_global_culture_detail_core(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_culture_detail_core(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  SELECT pg_catalog.jsonb_build_object('id',c.id,'nome',c.nome,'descricao',c.descricao,'ativo',c.ativo,'updated_at',c.updated_at,
    'desativada_em',c.desativada_em)
  INTO v FROM public.culturas c WHERE c.id=p_id;
  IF v IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION platform_private.read_global_culture_detail_core(p_id uuid) OWNER TO postgres;

--
-- Name: read_global_cultures_core(text, integer, integer); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_cultures_core(p_search text, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_search text; v_items jsonb; v_count int;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR p_offset IS NULL OR p_offset NOT BETWEEN 0 AND 1000000
    OR pg_catalog.char_length(COALESCE(p_search,'')) > 120 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_search:=pg_catalog.btrim(COALESCE(p_search,''));
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',c.id,'nome',c.nome,'ativo',c.ativo) ORDER BY c.nome,c.id),'[]'::jsonb), count(*)
  INTO v_items, v_count FROM (SELECT id,nome,ativo FROM public.culturas
    WHERE v_search='' OR pg_catalog.strpos(pg_catalog.lower(nome),pg_catalog.lower(v_search))>0
    ORDER BY nome,id LIMIT p_limit+1 OFFSET p_offset) c;
  RETURN pg_catalog.jsonb_build_object('items',CASE WHEN v_count>p_limit THEN v_items - p_limit ELSE v_items END,'has_more',v_count>p_limit);
END;
$$;


ALTER FUNCTION platform_private.read_global_cultures_core(p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: read_global_item_volumes_core(text, uuid, integer, integer); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_item_volumes_core(p_item_tipo text, p_item_id uuid, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_parent jsonb; v_items jsonb; v_more boolean;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR p_offset IS NULL OR p_offset NOT BETWEEN 0 AND 10000 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_volume_invalid'; END IF;
  v_parent:=platform_private.catalog_volume_parent(p_item_tipo,p_item_id,false);
  WITH page AS (
    SELECT v.id, row_number() OVER (ORDER BY v.ordem, v.volume_ml, v.id) rn FROM public.catalogo_volumes v
     WHERE v.item_tipo=p_item_tipo AND COALESCE(v.produto_id,v.microrganismo_id)=p_item_id
     ORDER BY v.ordem, v.volume_ml, v.id LIMIT p_limit+1 OFFSET p_offset)
  SELECT COALESCE(pg_catalog.jsonb_agg(platform_private.catalog_volume_row(id) ORDER BY rn) FILTER (WHERE rn<=p_offset+p_limit),'[]'::jsonb),
         count(*)>p_limit
    INTO v_items, v_more FROM page;
  RETURN pg_catalog.jsonb_build_object('item',pg_catalog.jsonb_build_object('tipo',p_item_tipo,'id',p_item_id,'nome',v_parent->'nome',
      'codigo',v_parent->'codigo','ativo',v_parent->'ativo','pricing',platform_private.catalog_volume_pricing(v_parent) - 'updated_at'),
    'items',v_items,'has_more',v_more);
END;
$$;


ALTER FUNCTION platform_private.read_global_item_volumes_core(p_item_tipo text, p_item_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: read_global_microorganism_detail_core(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_microorganism_detail_core(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  -- Projeção sem preços, dose, B2B ou vínculo de produto.
  SELECT pg_catalog.jsonb_build_object('id',m.id,'codigo',m.codigo,'nome',m.nome,'tipo',m.tipo,'nome_cientifico',m.nome_cientifico,
    'concentracao_ufc_ml',m.concentracao_ufc_ml,'concentracao_label',m.concentracao_label,'fornecedor',m.fornecedor,
    'producao_on_farm',m.producao_on_farm,'meio_cultivo',m.meio_cultivo,'funcao_agronomica',m.funcao_agronomica,
    'observacoes',m.observacoes,'descricao',m.descricao,'ativo',m.ativo,'updated_at',m.updated_at)
  INTO v FROM public.microrganismos m WHERE m.id=p_id;
  IF v IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION platform_private.read_global_microorganism_detail_core(p_id uuid) OWNER TO postgres;

--
-- Name: read_global_microorganisms_core(text, integer, integer, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_microorganisms_core(p_search text, p_limit integer, p_offset integer, p_only_active boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_search text; v_items jsonb; v_count int;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR p_offset IS NULL OR p_offset NOT BETWEEN 0 AND 1000000
    OR p_only_active IS NULL OR pg_catalog.char_length(COALESCE(p_search,'')) > 120 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_micro_invalid';
  END IF;
  v_search:=pg_catalog.btrim(COALESCE(p_search,''));
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('id',m.id,'codigo',m.codigo,'nome',m.nome,'ativo',m.ativo)
    ORDER BY m.nome, m.id),'[]'::jsonb), count(*)
  INTO v_items, v_count FROM (
    SELECT id,codigo,nome,ativo FROM public.microrganismos
    WHERE (NOT p_only_active OR ativo IS TRUE)
      AND (v_search='' OR pg_catalog.strpos(pg_catalog.lower(nome),pg_catalog.lower(v_search))>0
        OR pg_catalog.strpos(pg_catalog.lower(COALESCE(codigo,'')),pg_catalog.lower(v_search))>0)
    ORDER BY nome, id LIMIT p_limit+1 OFFSET p_offset) m;
  -- has_more por sentinela (limit+1), itens cortados ao limite.
  RETURN pg_catalog.jsonb_build_object('items',
    CASE WHEN v_count>p_limit THEN v_items - p_limit ELSE v_items END,'has_more',v_count>p_limit);
END;
$$;


ALTER FUNCTION platform_private.read_global_microorganisms_core(p_search text, p_limit integer, p_offset integer, p_only_active boolean) OWNER TO postgres;

--
-- Name: read_global_product_catalog_by_family_core(text, text, text, integer, integer); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_product_catalog_by_family_core(p_familia text, p_revisao text, p_search text, p_limit integer, p_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_search text; v_result jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_revisao IS NULL OR p_revisao NOT IN ('familia','todos','pendentes')
     OR (p_revisao = 'familia' AND (p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo')))
     OR (p_revisao <> 'familia' AND p_familia IS NOT NULL)
     OR p_limit IS NULL OR p_limit < 1 OR p_limit > 50
     OR p_offset IS NULL OR p_offset < 0 OR p_offset > 1000000
     OR p_search IS NULL OR pg_catalog.char_length(p_search) > 120 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='platform_catalog_invalid_query';
  END IF;
  v_search := pg_catalog.lower(pg_catalog.btrim(p_search));
  WITH bounded AS MATERIALIZED (
    SELECT p.id, p.codigo, p.nome, p.tipo, COALESCE(p.ativo,false) AS ativo, p.b2b_enabled, p.updated_at,
           p.familia_catalogo, p.classe_catalogo
    FROM public.produtos p
    WHERE ((p_revisao = 'familia' AND p.familia_catalogo IS NOT NULL AND p.familia_catalogo = p_familia)
        OR p_revisao = 'todos'
        OR (p_revisao = 'pendentes' AND p.familia_catalogo IS NULL))
      AND (v_search = ''
       OR pg_catalog.strpos(pg_catalog.lower(p.nome), v_search) > 0
       OR pg_catalog.strpos(pg_catalog.lower(COALESCE(p.codigo, '')), v_search) > 0)
    ORDER BY (p.familia_catalogo IS NULL) DESC, pg_catalog.lower(p.nome) COLLATE "C", p.id
    LIMIT (p_limit + 1) OFFSET p_offset
  ), page AS (
    SELECT * FROM bounded b ORDER BY (b.familia_catalogo IS NULL) DESC, pg_catalog.lower(b.nome) COLLATE "C", b.id LIMIT p_limit
  )
  SELECT pg_catalog.jsonb_build_object(
    'items', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)
      ORDER BY (r.familia_catalogo IS NULL) DESC, pg_catalog.lower(r.nome) COLLATE "C", r.id) FROM page r), '[]'::jsonb),
    'has_more', (SELECT pg_catalog.count(*) > p_limit FROM bounded)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION platform_private.read_global_product_catalog_by_family_core(p_familia text, p_revisao text, p_search text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: read_global_product_composition_core(uuid, integer, integer); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.read_global_product_composition_core(p_produto_id uuid, p_limit integer, p_receita_offset integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_p public.produtos%ROWTYPE; v_result jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_produto_id IS NULL OR p_limit IS NULL OR p_limit < 1 OR p_limit > 50 OR p_receita_offset IS NULL OR p_receita_offset < 0 OR p_receita_offset > 10000 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid_query'; END IF;
  SELECT * INTO v_p FROM public.produtos WHERE id = p_produto_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_composition_unavailable'; END IF;
  WITH rec AS MATERIALIZED (
    SELECT f.id AS formulacao_id, f.microrganismo_id, m.nome AS micro_nome, m.ativo AS micro_ativo, f.component_insumo_id,
           ip.nome AS insumo_nome, f.volume_ml, f.proporcao, f.concentracao, f.unidade, f.e_volume_fixo
    FROM public.formulacoes f JOIN public.microrganismos m ON m.id = f.microrganismo_id
    LEFT JOIN public.produtos ip ON ip.id = f.component_insumo_id
    WHERE f.produto_id = p_produto_id ORDER BY f.created_at, f.id LIMIT p_limit + 1 OFFSET p_receita_offset
  ), dec AS MATERIALIZED (
    SELECT d.id, d.ordem::int AS ordem, d.tipo_componente, d.microrganismo_id, m.nome AS micro_nome, m.ativo AS micro_ativo,
           d.componente_nome, d.quantidade, d.unidade, d.base, d.natureza
    FROM public.produto_composicao_declaracoes d LEFT JOIN public.microrganismos m ON m.id = d.microrganismo_id
    WHERE d.produto_id = p_produto_id ORDER BY d.ordem LIMIT 51
  )
  SELECT pg_catalog.jsonb_build_object(
    'produto', pg_catalog.jsonb_build_object('id',v_p.id,'nome',v_p.nome,'familia_catalogo',v_p.familia_catalogo,'updated_at',v_p.updated_at),
    'conjunto', (SELECT pg_catalog.jsonb_build_object('status',c.status,'updated_at',c.updated_at)
                 FROM public.produto_composicao_conjuntos c WHERE c.produto_id = p_produto_id),
    'receita', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(r)) FROM (SELECT * FROM rec LIMIT p_limit) r), '[]'::jsonb),
    'receita_offset', p_receita_offset,
    'declaracoes', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.to_jsonb(x) ORDER BY x.ordem) FROM (SELECT * FROM dec LIMIT 50) x), '[]'::jsonb),
    'receita_has_more', (SELECT pg_catalog.count(*) > p_limit FROM rec),
    'declaracoes_has_more', (SELECT pg_catalog.count(*) > 50 FROM dec)) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION platform_private.read_global_product_composition_core(p_produto_id uuid, p_limit integer, p_receita_offset integer) OWNER TO postgres;

