--
-- Name: require_provisioned_admin_target(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.require_provisioned_admin_target(p_actor uuid, p_invite uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF p_actor IS NULL OR NOT public.is_platform_superadmin(p_actor) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor OR public.is_platform_superadmin(j.user_id) OR j.status NOT IN ('ativo','pendente') OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id AND p.ativo IS TRUE AND o.ativo IS TRUE) OR NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=j.user_id AND r.role='administrador'::public.app_role) OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=j.user_id AND u.raw_app_meta_data->>'provisioning_request_id'=j.request_id::text) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.require_provisioned_admin_target(p_actor uuid, p_invite uuid) OWNER TO postgres;

--
-- Name: require_service_role(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.require_service_role() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE v_role text;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
                     nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.require_service_role() OWNER TO postgres;

--
-- Name: reschedule_monitoring_core(uuid, date, timestamp with time zone, integer, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.reschedule_monitoring_core(p_alerta_id uuid, p_nova_data date, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta public.alertas_agronomicos;
  v_reg public.registros_consultor;
  v_receipt jsonb;
  v_obs text; v_block text; v_new_block text;
  v_notice uuid; v_version integer; v_updated timestamptz; v_visit_updated boolean := false; v_mode text := 'somente_alerta';
  v_fp text := md5(jsonb_build_object('op','reschedule','alerta',p_alerta_id,'date',p_nova_data,
    'alert_at',p_expected_alert_updated_at,'version',p_expected_visit_version)::text);
BEGIN
  IF v_uid IS NULL OR NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501';
  END IF;
  IF p_alerta_id IS NULL OR p_nova_data IS NULL OR p_request_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE='22023';
  END IF;
  IF p_expected_alert_updated_at IS NULL OR NOT isfinite(p_expected_alert_updated_at)
    OR (p_expected_visit_version IS NOT NULL AND p_expected_visit_version<=0) THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_alerta FROM public.alertas_agronomicos
   WHERE id=p_alerta_id AND platform_private.monitoring_refs_in_actor_tenant(fazenda_id,talhao_id,registro_origem_id)
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404'; END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    v_reg := public._visita_lock_and_check(v_alerta.registro_origem_id,NULL,false);
  END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false)
    OR NOT (public.has_role(v_uid,'administrador'::public.app_role) OR public.has_role(v_uid,'gestor'::public.app_role))
    OR NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_alerta.fazenda_id,v_alerta.talhao_id,v_alerta.registro_origem_id),false)
    OR (v_alerta.registro_origem_id IS NOT NULL AND NOT coalesce(public.can_manage_technical_visit(v_uid,v_alerta.registro_origem_id),false)) THEN
    RAISE EXCEPTION 'monitoring_alert_not_found' USING ERRCODE='PT404';
  END IF;
  SELECT jsonb_build_object('fp',fingerprint,'op',operation,'result',result) INTO v_receipt
    FROM platform_private.monitoring_alert_receipts
   WHERE actor_id=v_uid AND alerta_id=p_alerta_id AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'op'<>'reschedule' OR v_receipt->>'fp' IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  IF p_nova_data < (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'past_date_not_allowed' USING ERRCODE='22023';
  END IF;
  IF v_alerta.status IS DISTINCT FROM 'monitoramento'::public.status_alerta THEN
    RAISE EXCEPTION 'monitoring_alert_not_active' USING ERRCODE='P0001';
  END IF;
  IF v_alerta.updated_at IS DISTINCT FROM p_expected_alert_updated_at
    OR (v_alerta.registro_origem_id IS NULL AND p_expected_visit_version IS NOT NULL)
    OR (v_alerta.registro_origem_id IS NOT NULL AND v_reg.version IS DISTINCT FROM p_expected_visit_version) THEN
    RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409';
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL AND v_reg.status::text IN ('rascunho','em_andamento') THEN
    -- Shared date: any other open alert on the same visit makes synchronization ambiguous.
    IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=v_reg.id
        AND o.id<>p_alerta_id AND o.status::text<>'encerrado') THEN
      RAISE EXCEPTION 'multiple_alerts_share_visit' USING ERRCODE='PT409';
    END IF;
    v_obs := coalesce(v_reg.observacoes_tecnicas,'');
    IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]')>1
      OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]')>1
      OR (position('[PLANO DE MONITORAMENTO]' in v_obs)>0)<>(position('[FIM DO PLANO]' in v_obs)>0)
      OR (position('[FIM DO PLANO]' in v_obs)>0 AND position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)) THEN
      RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
    END IF;
    v_block := substring(v_obs from '\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]');
    IF v_block IS NOT NULL THEN
      -- Only the date line changes; every other byte of notes and plan is preserved.
      IF (SELECT count(*) FROM regexp_matches(v_block,'(^|\n)Próxima Avaliação: [^\n]*','g'))<>1 THEN
        RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
      END IF;
      v_new_block := regexp_replace(v_block,'(^|\n)Próxima Avaliação: [^\n]*','\1Próxima Avaliação: '||p_nova_data::text);
      v_obs := overlay(v_obs placing v_new_block from position(v_block in v_obs) for length(v_block));
      -- Exactly one coherent generic notice; never fabricate one.
      IF (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=v_reg.id AND tipo='plano_monitoramento')<>1
        OR v_block !~ ('(^|\n)Próxima Avaliação: '||coalesce(v_reg.data_proxima_visita::text,'<none>')||'(\n|$)') THEN
        RAISE EXCEPTION 'plan_notice_incoherent' USING ERRCODE='PT409';
      END IF;
      SELECT id INTO v_notice FROM public.monitoramento_avisos
       WHERE registro_consultor_id=v_reg.id AND tipo='plano_monitoramento'
         AND data_referencia IS NOT DISTINCT FROM v_reg.data_proxima_visita FOR UPDATE;
      IF v_notice IS NULL THEN RAISE EXCEPTION 'plan_notice_incoherent' USING ERRCODE='PT409'; END IF;
      INSERT INTO platform_private.visit_plan_write_tickets(transaction_id,registro_id,block,next_date)
        VALUES(txid_current(),v_reg.id,v_new_block,p_nova_data);
    ELSE
      -- Legacy origin without plan: generic writers are not all protected; refuse instead of claiming sync.
      RAISE EXCEPTION 'origin_without_plan_unsupported' USING ERRCODE='PT409';
    END IF;
    UPDATE public.registros_consultor
       SET observacoes_tecnicas=v_obs,
           data_proxima_visita=p_nova_data, version=p_expected_visit_version+1, updated_at=clock_timestamp()
     WHERE id=v_reg.id AND version=p_expected_visit_version
       AND public.can_manage_technical_visit(v_uid,id)
     RETURNING version INTO v_version;
    IF NOT FOUND OR v_version<>p_expected_visit_version+1 THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
    IF v_notice IS NOT NULL THEN
      UPDATE public.monitoramento_avisos SET data_referencia=p_nova_data WHERE id=v_notice AND registro_consultor_id=v_reg.id;
      IF NOT FOUND THEN RAISE EXCEPTION 'notice_conflict' USING ERRCODE='PT409'; END IF;
    END IF;
    DELETE FROM platform_private.visit_plan_write_tickets WHERE transaction_id=txid_current() AND registro_id=v_reg.id;
    v_visit_updated := true;
    v_mode := 'plano_visita_aviso_alerta';
  ELSIF v_alerta.registro_origem_id IS NOT NULL THEN
    -- Immutable visit: explicit alert-only mode; the visit/plan is NOT synchronized.
    v_version := v_reg.version;
  END IF;
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    INSERT INTO platform_private.alert_origin_write_tickets VALUES(txid_current(),p_alerta_id);
  END IF;
  UPDATE public.alertas_agronomicos
     SET data_vencimento=p_nova_data, nivel_risco='medio'::public.nivel_risco,
         updated_at=greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
   WHERE id=p_alerta_id AND updated_at=p_expected_alert_updated_at
   RETURNING updated_at INTO v_updated;
  IF NOT FOUND THEN RAISE EXCEPTION 'concurrent_update' USING ERRCODE='PT409'; END IF;
  DELETE FROM platform_private.alert_origin_write_tickets WHERE transaction_id=txid_current() AND alerta_id=p_alerta_id;
  v_receipt := jsonb_build_object('success',true,'alerta_id',p_alerta_id,'data_anterior',v_alerta.data_vencimento,
    'nova_data',p_nova_data,'registro_origem_id',v_alerta.registro_origem_id,'visita_atualizada',v_visit_updated,'modo',v_mode,
    'visit_version',v_version,'alerta_updated_at',v_updated,'request_id',p_request_id);
  IF v_alerta.registro_origem_id IS NOT NULL THEN
    INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
      VALUES(v_alerta.registro_origem_id,v_uid,'monitoramento_reprogramado','Monitoramento reprogramado pelo alerta de origem',
        jsonb_build_object('request_id',p_request_id,'alerta_id',p_alerta_id,'fingerprint',v_fp,'modo',v_mode));
  END IF;
  INSERT INTO platform_private.monitoring_alert_receipts VALUES(v_uid,p_alerta_id,p_request_id,'reschedule',v_fp,v_receipt);
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.reschedule_monitoring_core(p_alerta_id uuid, p_nova_data date, p_expected_alert_updated_at timestamp with time zone, p_expected_visit_version integer, p_request_id uuid) OWNER TO postgres;

--
-- Name: save_visit_monitoring_plan_core(uuid, integer, jsonb, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.save_visit_monitoring_plan_core(p_registro_id uuid, p_expected_version integer, p_plano jsonb, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_id uuid;
  v_version integer;
  v_date date;
  v_obs text;
  v_block text;
  v_receipt jsonb;
  v_fingerprint text := md5(jsonb_build_object('visit',p_registro_id,'version',p_expected_version,'plan',p_plano)::text);
BEGIN
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='42501';
  END IF;
  IF NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  IF p_expected_version IS NULL OR p_expected_version<=0 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409';
  END IF;
  IF p_request_id IS NULL OR jsonb_typeof(p_plano) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  IF (SELECT count(*) FROM jsonb_object_keys(p_plano))<>4
    OR NOT p_plano ?& ARRAY['items','frequency','triggers','next_date']
    OR jsonb_typeof(p_plano->'items') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_plano->'triggers') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_plano->'frequency') IS DISTINCT FROM 'string'
    OR jsonb_typeof(p_plano->'next_date') IS DISTINCT FROM 'string' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  IF jsonb_array_length(p_plano->'items') NOT BETWEEN 1 AND 6
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_plano->'items') x
      WHERE jsonb_typeof(x)<>'string' OR x#>>'{}' NOT IN ('Pragas','Doenças','Plantas Daninhas','Nutrição','Clima','Estande'))
    OR (SELECT count(DISTINCT x) FROM jsonb_array_elements(p_plano->'items') x)<>jsonb_array_length(p_plano->'items')
    OR p_plano->>'frequency' NOT IN ('7','14','30')
    OR length(p_plano->>'triggers')>2000
    OR p_plano->>'triggers' ~ '[\r\n]'
    OR position('[PLANO DE MONITORAMENTO]' in p_plano->>'triggers')>0
    OR position('[FIM DO PLANO]' in p_plano->>'triggers')>0
    OR p_plano->>'next_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN
    RAISE EXCEPTION 'invalid_plan' USING ERRCODE='22023';
  END IF;
  v_date := (p_plano->>'next_date')::date;
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'monitoring_gate_unavailable' USING ERRCODE='55000'; END IF;
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) OR
    NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- NULL here does not authorize CAS: replay is checked first, explicit mandatory CAS below.
  v_reg := public._visita_lock_and_check(p_registro_id,NULL,false);
  IF NOT coalesce(public.technical_actor_ready(v_uid),false) OR
    NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) OR
    NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_reg.fazenda_id,v_reg.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- visitas_logs accepts authenticated INSERT: never trust it as a receipt authority.
  SELECT jsonb_build_object('fingerprint',fingerprint,'result',result) INTO v_receipt
    FROM platform_private.visit_monitoring_plan_receipts
    WHERE registro_id=p_registro_id AND actor_id=v_uid AND request_id=p_request_id;
  IF FOUND THEN
    IF v_receipt->>'fingerprint' IS DISTINCT FROM v_fingerprint THEN
      RAISE EXCEPTION 'request_conflict' USING ERRCODE='PT409';
    END IF;
    RETURN v_receipt->'result';
  END IF;
  -- Time-dependent rule AFTER authorized replay; a confirmed receipt never expires.
  IF v_date < (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date THEN
    RAISE EXCEPTION 'past_date_not_allowed' USING ERRCODE='22023';
  END IF;
  IF v_reg.version IS DISTINCT FROM p_expected_version THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409';
  END IF;
  IF v_reg.status::text NOT IN ('rascunho','em_andamento') THEN
    RAISE EXCEPTION 'technical_record_content_locked' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM public.alertas_agronomicos o WHERE o.registro_origem_id=p_registro_id AND o.status::text<>'encerrado')
    AND v_date IS DISTINCT FROM v_reg.data_proxima_visita THEN
    RAISE EXCEPTION 'linked_alert_date_requires_reschedule' USING ERRCODE='PT409';
  END IF;
  IF (SELECT count(*) FROM public.monitoramento_avisos WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento')>1 THEN
    RAISE EXCEPTION 'ambiguous_plan_notice' USING ERRCODE='PT409';
  END IF;
  SELECT id INTO v_id FROM public.monitoramento_avisos
    WHERE registro_consultor_id=p_registro_id AND tipo='plano_monitoramento' FOR UPDATE;
  IF NOT coalesce(public.can_manage_technical_visit(v_uid,p_registro_id),false) OR
    NOT coalesce(platform_private.monitoring_refs_in_actor_tenant(v_reg.fazenda_id,v_reg.talhao_id,v_reg.id),false) THEN
    RAISE EXCEPTION 'monitoring_unavailable' USING ERRCODE='PT404';
  END IF;
  -- Replace only a complete single legacy block; malformed/ambiguous text needs human review.
  v_obs := coalesce(v_reg.observacoes_tecnicas,'');
  IF (length(v_obs)-length(replace(v_obs,'[PLANO DE MONITORAMENTO]','')))/length('[PLANO DE MONITORAMENTO]') > 1
    OR (length(v_obs)-length(replace(v_obs,'[FIM DO PLANO]','')))/length('[FIM DO PLANO]') > 1
    OR (position('[PLANO DE MONITORAMENTO]' in v_obs)>0)<>(position('[FIM DO PLANO]' in v_obs)>0)
    OR (position('[FIM DO PLANO]' in v_obs)>0 AND position('[FIM DO PLANO]' in v_obs)<position('[PLANO DE MONITORAMENTO]' in v_obs)) THEN
    RAISE EXCEPTION 'ambiguous_plan_text' USING ERRCODE='PT409';
  END IF;
  v_obs := regexp_replace(v_obs,'\[PLANO DE MONITORAMENTO\].*?\[FIM DO PLANO\]','','ns');
  v_block := '[PLANO DE MONITORAMENTO]'||chr(10)||'Itens: '||
    (SELECT string_agg(x,', ' ORDER BY ord) FROM jsonb_array_elements_text(p_plano->'items') WITH ORDINALITY a(x,ord))||chr(10)||
    'Frequência: '||(p_plano->>'frequency')||' dias'||chr(10)||'Gatilhos: '||(p_plano->>'triggers')||chr(10)||
    'Próxima Avaliação: '||v_date::text||chr(10)||'[FIM DO PLANO]';
  INSERT INTO platform_private.visit_plan_write_tickets(transaction_id,registro_id,block,next_date)
    VALUES(txid_current(),p_registro_id,v_block,v_date);
  UPDATE public.registros_consultor SET observacoes_tecnicas=btrim(v_obs||chr(10)||chr(10)||v_block),
    data_proxima_visita=v_date, version=p_expected_version+1, updated_at=clock_timestamp()
    WHERE id=p_registro_id AND version=p_expected_version
      AND public.can_manage_technical_visit(v_uid,id) RETURNING version INTO v_version;
  IF NOT FOUND OR v_version<>p_expected_version+1 THEN RAISE EXCEPTION 'version_conflict' USING ERRCODE='PT409'; END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.monitoramento_avisos(registro_consultor_id,tipo,data_referencia)
      VALUES(p_registro_id,'plano_monitoramento',v_date) RETURNING id INTO v_id;
  ELSE
    UPDATE public.monitoramento_avisos SET data_referencia=v_date WHERE id=v_id AND registro_consultor_id=p_registro_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'notice_conflict' USING ERRCODE='PT409'; END IF;
  END IF;
  v_receipt := jsonb_build_object('ok',true,'registro_id',p_registro_id,'version',v_version,
    'aviso_id',v_id,'data_referencia',v_date,'plano',p_plano,'request_id',p_request_id);
  INSERT INTO public.visitas_logs(registro_consultor_id,usuario_id,acao,descricao,metadata)
    VALUES(p_registro_id,v_uid,'plano_monitoramento_salvo','Plano de monitoramento atualizado',
      jsonb_build_object('request_id',p_request_id,'fingerprint',v_fingerprint,'version',v_version,'result',v_receipt));
  INSERT INTO platform_private.visit_monitoring_plan_receipts(actor_id,registro_id,request_id,fingerprint,result)
    VALUES(v_uid,p_registro_id,p_request_id,v_fingerprint,v_receipt);
  DELETE FROM platform_private.visit_plan_write_tickets WHERE transaction_id=txid_current() AND registro_id=p_registro_id;
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.save_visit_monitoring_plan_core(p_registro_id uuid, p_expected_version integer, p_plano jsonb, p_request_id uuid) OWNER TO postgres;

--
-- Name: set_global_b2b_enabled_core(text, uuid, timestamp with time zone, boolean, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_b2b_enabled_core(p_item_tipo text, p_id uuid, p_expected_updated_at timestamp with time zone, p_b2b_enabled boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid:=gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE;
  v_om public.microrganismos%ROWTYPE; v_nm public.microrganismos%ROWTYPE;
  v_old jsonb; v_new jsonb; v_old_ativo boolean; v_old_b2b boolean; v_old_ver timestamptz; v_new_ver timestamptz;
  v_vols_before jsonb; v_vols_after jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_item_tipo IS NULL OR p_item_tipo NOT IN ('produto','microrganismo') OR p_id IS NULL OR p_b2b_enabled IS NULL
    OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'expected_updated_at',p_expected_updated_at,
    'b2b_enabled',p_b2b_enabled,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  -- Motivo/chave validados e replay autorizado ANTES de qualquer efeito (lock por chave).
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_b2b_enabled',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- Serialização por item (mesmo lock de linha usado pelos writers de status/apresentações).
  IF p_item_tipo='produto' THEN
    SELECT * INTO v_op FROM public.produtos WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
    v_old:=pg_catalog.to_jsonb(v_op); v_old_ativo:=COALESCE(v_op.ativo,false); v_old_b2b:=v_op.b2b_enabled; v_old_ver:=v_op.updated_at;
  ELSE
    SELECT * INTO v_om FROM public.microrganismos WHERE id=p_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_b2b_unavailable'; END IF;
    v_old:=pg_catalog.to_jsonb(v_om); v_old_ativo:=v_om.ativo; v_old_b2b:=v_om.b2b_enabled; v_old_ver:=v_om.updated_at;
  END IF;
  IF v_old_ver IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_conflict'; END IF;
  IF v_old_b2b = p_b2b_enabled THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_no_change'; END IF;
  IF p_b2b_enabled AND NOT v_old_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_b2b_requires_active'; END IF;

  -- Apresentações do item: provamos que não mudam (sem sync de preço disparado aqui).
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_before
    FROM public.catalogo_volumes cv
   WHERE (p_item_tipo='produto' AND cv.produto_id=p_id) OR (p_item_tipo='microrganismo' AND cv.microrganismo_id=p_id);

  IF p_item_tipo='produto' THEN
    UPDATE public.produtos SET b2b_enabled=p_b2b_enabled WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_np;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;
    v_new:=pg_catalog.to_jsonb(v_np); v_new_ver:=v_np.updated_at;
  ELSE
    UPDATE public.microrganismos SET b2b_enabled=p_b2b_enabled WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_nm;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;
    v_new:=pg_catalog.to_jsonb(v_nm); v_new_ver:=v_nm.updated_at;
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_after
    FROM public.catalogo_volumes cv
   WHERE (p_item_tipo='produto' AND cv.produto_id=p_id) OR (p_item_tipo='microrganismo' AND cv.microrganismo_id=p_id);

  -- Confirmação: somente b2b_enabled/updated_at mudaram; versão estritamente crescente.
  -- (produtos usa update_updated_at_column = now(); se a versão não cresce, falha fechada.)
  IF (v_new->>'b2b_enabled')::boolean IS DISTINCT FROM p_b2b_enabled
    OR v_new_ver IS NULL OR v_new_ver <= v_old_ver
    OR (v_old - ARRAY['b2b_enabled','updated_at']) IS DISTINCT FROM (v_new - ARRAY['b2b_enabled','updated_at'])
    OR v_vols_before IS DISTINCT FROM v_vols_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_b2b_confirmation_failed'; END IF;

  v_receipt:=pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',p_b2b_enabled,
    'updated_at',v_new_ver,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_b2b_enabled',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',v_old_b2b,'updated_at',v_old_ver),
    pg_catalog.jsonb_build_object('item_tipo',p_item_tipo,'id',p_id,'ativo',v_old_ativo,'b2b_enabled',p_b2b_enabled,'updated_at',v_new_ver));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.set_global_b2b_enabled_core(p_item_tipo text, p_id uuid, p_expected_updated_at timestamp with time zone, p_b2b_enabled boolean, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_culture_status_core(uuid, timestamp with time zone, boolean, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_culture_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_old public.culturas%ROWTYPE; v_new public.culturas%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_ativo IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'ativo',p_ativo,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_culture_status',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT * INTO v_old FROM public.culturas WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  IF v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_no_change'; END IF;
  -- desativada_em/desativada_por carimbados pelo trigger existente tg_culturas_stamp_desativacao.
  UPDATE public.culturas SET ativo=p_ativo WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.ativo IS DISTINCT FROM p_ativo OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - ARRAY['ativo','updated_at','desativada_em','desativada_por'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - ARRAY['ativo','updated_at','desativada_em','desativada_por']) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_culture_status',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('ativo',v_old.ativo,'updated_at',v_old.updated_at,'desativada_em',v_old.desativada_em,'desativada_por',v_old.desativada_por),
    pg_catalog.jsonb_build_object('ativo',v_new.ativo,'updated_at',v_new.updated_at,'desativada_em',v_new.desativada_em,'desativada_por',v_new.desativada_por));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.set_global_culture_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_microorganism_status_core(uuid, timestamp with time zone, boolean, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_microorganism_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_old public.microrganismos%ROWTYPE; v_new public.microrganismos%ROWTYPE; v_receipt jsonb;
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_ativo IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_invalid'; END IF;
  v_req:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'ativo',p_ativo,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay:=platform_private.catalog_entity_replay(v_actor,'set_global_microorganism_status',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;
  SELECT * INTO v_old FROM public.microrganismos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_entity_unavailable'; END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_conflict'; END IF;
  IF v_old.ativo = p_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_entity_no_change'; END IF;
  -- Arquivar = ativo false; nunca exclui. b2b_enabled/preços não são tocados.
  UPDATE public.microrganismos SET ativo=p_ativo WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.ativo IS DISTINCT FROM p_ativo OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old) - ARRAY['ativo','updated_at'])
       IS DISTINCT FROM (pg_catalog.to_jsonb(v_new) - ARRAY['ativo','updated_at']) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_entity_confirmation_failed'; END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',gen_random_uuid(),'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_microorganism_status',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('ativo',v_old.ativo,'updated_at',v_old.updated_at),
    pg_catalog.jsonb_build_object('ativo',v_new.ativo,'updated_at',v_new.updated_at));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.set_global_microorganism_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_product_composition_core(uuid, timestamp with time zone, text, jsonb, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_product_composition_core(p_produto_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_itens jsonb, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE; v_e jsonb; v_i int := 0; v_n int;
  v_before jsonb; v_after jsonb; v_form_before text; v_form_after text; v_vol_before text; v_vol_after text;
  v_old_status text; v_keys text[] := ARRAY['base','componente_nome','microrganismo_id','natureza','ordem','quantidade','tipo_componente','unidade'];
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_produto_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) OR p_idempotency_key IS NULL
     OR p_status IS NULL OR p_status NOT IN ('rascunho','completo')
     OR p_itens IS NULL OR pg_catalog.jsonb_typeof(p_itens) <> 'array' OR pg_catalog.jsonb_array_length(p_itens) > 50
     OR (p_status = 'completo' AND pg_catalog.jsonb_array_length(p_itens) = 0) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
  -- Formato estrito de cada item (chaves exatas, tipos JSON, ordem 1..n sequencial). Valores finais validados pelos CHECKs.
  FOR v_e IN SELECT e FROM pg_catalog.jsonb_array_elements(p_itens) e LOOP
    v_i := v_i + 1;
    IF pg_catalog.jsonb_typeof(v_e) <> 'object'
       OR (SELECT pg_catalog.array_agg(k ORDER BY k) FROM pg_catalog.jsonb_object_keys(v_e) k) IS DISTINCT FROM v_keys
       OR pg_catalog.jsonb_typeof(v_e->'ordem') <> 'number' OR (v_e->>'ordem') <> v_i::text
       OR pg_catalog.jsonb_typeof(v_e->'quantidade') NOT IN ('number','null')
       OR pg_catalog.jsonb_typeof(v_e->'tipo_componente') <> 'string' OR pg_catalog.jsonb_typeof(v_e->'natureza') <> 'string'
       OR pg_catalog.jsonb_typeof(v_e->'microrganismo_id') NOT IN ('string','null')
       OR pg_catalog.jsonb_typeof(v_e->'componente_nome') NOT IN ('string','null')
       OR pg_catalog.jsonb_typeof(v_e->'unidade') NOT IN ('string','null') OR pg_catalog.jsonb_typeof(v_e->'base') NOT IN ('string','null')
       OR (v_e->>'microrganismo_id') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND v_e->>'microrganismo_id' IS NOT NULL
       OR (p_status = 'completo' AND v_e->>'quantidade' IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
    -- No máximo 6 casas decimais (numeric(24,6) arredondaria silenciosamente).
    IF v_e->>'quantidade' IS NOT NULL AND pg_catalog.scale((v_e->>'quantidade')::numeric) > 6 THEN
      RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_invalid'; END IF;
  END LOOP;
  v_req := pg_catalog.jsonb_build_object('produto_id',p_produto_id,'expected_updated_at',p_expected_updated_at,'status',p_status,
    'itens',p_itens,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay := platform_private.catalog_entity_replay(v_actor,'set_global_product_composition',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  SELECT * INTO v_op FROM public.produtos WHERE id = p_produto_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_composition_unavailable'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_conflict'; END IF;
  IF v_op.familia_catalogo IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_requires_family'; END IF;

  -- Família transacional (após lock) e regras cruzadas com a receita.
  FOR v_e IN SELECT e FROM pg_catalog.jsonb_array_elements(p_itens) e LOOP
    IF NOT platform_private.catalog_composition_type_allowed(v_op.familia_catalogo, v_e->>'tipo_componente') THEN
      RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='catalog_composition_family_conflict'; END IF;
    IF v_e->>'tipo_componente' = 'microrganismo' THEN
      -- Nova associação exige micro ativo; micro já declarado (mesmo arquivado depois) pode ser mantido.
      IF NOT EXISTS (SELECT 1 FROM public.microrganismos m WHERE m.id = (v_e->>'microrganismo_id')::uuid
          AND (m.ativo OR EXISTS (SELECT 1 FROM public.produto_composicao_declaracoes d
                 WHERE d.produto_id = p_produto_id AND d.microrganismo_id = m.id))) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_micro_unavailable'; END IF;
      IF EXISTS (SELECT 1 FROM public.formulacoes f WHERE f.produto_id = p_produto_id
          AND f.microrganismo_id = (v_e->>'microrganismo_id')::uuid AND f.concentracao IS NOT NULL) THEN
        RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='catalog_composition_duplicate_measure'; END IF;
    END IF;
  END LOOP;

  SELECT c.status INTO v_old_status FROM public.produto_composicao_conjuntos c WHERE c.produto_id = p_produto_id FOR UPDATE;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordem',d.ordem,'tipo_componente',d.tipo_componente,
      'microrganismo_id',d.microrganismo_id,'componente_nome',d.componente_nome,'quantidade',d.quantidade,'unidade',d.unidade,
      'base',d.base,'natureza',d.natureza) ORDER BY d.ordem), '[]'::jsonb) INTO v_before
    FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(f)::text, ',' ORDER BY f.id), '')) INTO v_form_before FROM public.formulacoes f WHERE f.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(v)::text, ',' ORDER BY v.id), '')) INTO v_vol_before FROM public.catalogo_volumes v WHERE v.produto_id = p_produto_id;

  INSERT INTO public.produto_composicao_conjuntos (produto_id, status, updated_by) VALUES (p_produto_id, p_status, v_actor)
  ON CONFLICT (produto_id) DO UPDATE SET status = EXCLUDED.status, updated_by = EXCLUDED.updated_by;
  DELETE FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  INSERT INTO public.produto_composicao_declaracoes (produto_id, ordem, tipo_componente, microrganismo_id, componente_nome, quantidade, unidade, base, natureza)
  SELECT p_produto_id, (e->>'ordem')::smallint, e->>'tipo_componente', (e->>'microrganismo_id')::uuid, e->>'componente_nome',
         (e->>'quantidade')::numeric, e->>'unidade', e->>'base', e->>'natureza'
  FROM pg_catalog.jsonb_array_elements(p_itens) e;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('ordem',d.ordem,'tipo_componente',d.tipo_componente,
      'microrganismo_id',d.microrganismo_id,'componente_nome',d.componente_nome,'quantidade',d.quantidade,'unidade',d.unidade,
      'base',d.base,'natureza',d.natureza) ORDER BY d.ordem), '[]'::jsonb) INTO v_after
    FROM public.produto_composicao_declaracoes d WHERE d.produto_id = p_produto_id;
  IF v_after = v_before AND v_old_status IS NOT DISTINCT FROM p_status THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_composition_no_change'; END IF;

  -- Versão monotônica do produto; demais colunas, receita e apresentações intactas.
  UPDATE public.produtos SET updated_at = updated_at WHERE id = p_produto_id AND updated_at = p_expected_updated_at RETURNING * INTO v_np;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_confirmation_failed'; END IF;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(f)::text, ',' ORDER BY f.id), '')) INTO v_form_after FROM public.formulacoes f WHERE f.produto_id = p_produto_id;
  SELECT md5(COALESCE(string_agg(pg_catalog.to_jsonb(v)::text, ',' ORDER BY v.id), '')) INTO v_vol_after FROM public.catalogo_volumes v WHERE v.produto_id = p_produto_id;
  IF v_n <> pg_catalog.jsonb_array_length(p_itens) OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR (pg_catalog.to_jsonb(v_op) - 'updated_at') IS DISTINCT FROM (pg_catalog.to_jsonb(v_np) - 'updated_at')
     OR v_form_before IS DISTINCT FROM v_form_after OR v_vol_before IS DISTINCT FROM v_vol_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_composition_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',p_status,'itens',v_n,'updated_at',v_np.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_product_composition',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',v_old_status,'itens',v_before,'updated_at',v_op.updated_at),
    pg_catalog.jsonb_build_object('produto_id',p_produto_id,'status',p_status,'itens',v_after,'updated_at',v_np.updated_at));
  RETURN v_receipt;
END;
$_$;


ALTER FUNCTION platform_private.set_global_product_composition_core(p_produto_id uuid, p_expected_updated_at timestamp with time zone, p_status text, p_itens jsonb, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_product_family_core(uuid, timestamp with time zone, text, text, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_product_family_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_familia text, p_classe text, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.produtos%ROWTYPE; v_np public.produtos%ROWTYPE; v_old jsonb; v_new jsonb;
  v_vols_before jsonb; v_vols_after jsonb; v_classe text := NULLIF(pg_catalog.btrim(COALESCE(p_classe,'')), '');
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at) OR p_idempotency_key IS NULL
     OR p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_invalid';
  END IF;
  v_req := pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,
    'familia_catalogo',p_familia,'classe_catalogo',v_classe,'reason',pg_catalog.btrim(COALESCE(p_reason,'')));
  v_replay := platform_private.catalog_entity_replay(v_actor,'set_global_product_family',v_req,p_reason,p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- Revalidação mutante APÓS o replay: só nova execução exige rótulo ativo (com lock).
  IF NOT (v_classe IS NULL OR platform_private.catalog_family_label_check(p_familia, v_classe)) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_invalid';
  END IF;

  SELECT * INTO v_op FROM public.produtos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_family_unavailable'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_conflict'; END IF;
  IF v_op.familia_catalogo IS NOT DISTINCT FROM p_familia AND v_op.classe_catalogo IS NOT DISTINCT FROM v_classe THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_family_no_change'; END IF;
  v_old := pg_catalog.to_jsonb(v_op);
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_before
    FROM public.catalogo_volumes cv WHERE cv.produto_id=p_id;

  UPDATE public.produtos SET familia_catalogo=p_familia, classe_catalogo=v_classe
   WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_np;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_confirmation_failed'; END IF;
  v_new := pg_catalog.to_jsonb(v_np);
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(cv) ORDER BY cv.id),'[]'::jsonb) INTO v_vols_after
    FROM public.catalogo_volumes cv WHERE cv.produto_id=p_id;
  -- Somente família/classe/versão mudam (ativo, B2B, preços, dose, tipo, código, owner intactos).
  IF v_np.familia_catalogo IS DISTINCT FROM p_familia OR v_np.classe_catalogo IS DISTINCT FROM v_classe
     OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR (v_old - ARRAY['familia_catalogo','classe_catalogo','updated_at']) IS DISTINCT FROM (v_new - ARRAY['familia_catalogo','classe_catalogo','updated_at'])
     OR v_vols_before IS DISTINCT FROM v_vols_after THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_family_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',p_familia,'classe_catalogo',v_classe,
    'updated_at',v_np.updated_at,'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  PERFORM platform_private.catalog_entity_audit(v_actor,'set_global_product_family',p_reason,p_idempotency_key,v_req,v_receipt,
    pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',v_op.familia_catalogo,'classe_catalogo',v_op.classe_catalogo,'updated_at',v_op.updated_at),
    pg_catalog.jsonb_build_object('id',p_id,'familia_catalogo',p_familia,'classe_catalogo',v_classe,'updated_at',v_np.updated_at));
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.set_global_product_family_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_familia text, p_classe text, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_product_status_core(uuid, timestamp with time zone, boolean, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_product_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid; v_old public.produtos%ROWTYPE; v_new public.produtos%ROWTYPE;
  v_existing public.catalog_platform_admin_audit%ROWTYPE; v_request jsonb; v_receipt jsonb; v_audit uuid:=gen_random_uuid();
BEGIN
  v_actor:=platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_ativo IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
    OR p_idempotency_key IS NULL OR p_reason IS NULL OR pg_catalog.char_length(pg_catalog.btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_status_invalid';
  END IF;
  v_request:=pg_catalog.jsonb_build_object('id',p_id,'expected_updated_at',p_expected_updated_at,'ativo',p_ativo,'reason',pg_catalog.btrim(p_reason));
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  SELECT * INTO v_old FROM public.produtos WHERE id=p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='catalog_status_unavailable'; END IF;
  SELECT * INTO v_existing FROM public.catalog_platform_admin_audit WHERE correlation_id=p_idempotency_key;
  IF FOUND THEN
    IF v_existing.operation<>'set_global_product_status' OR v_existing.actor_id<>v_actor
      OR v_existing.counts_after->'request' IS DISTINCT FROM v_request THEN
      RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_status_conflict';
    END IF;
    RETURN (v_existing.counts_after->'receipt')||pg_catalog.jsonb_build_object('idempotent',true);
  END IF;
  IF v_old.updated_at IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_status_conflict'; END IF;
  IF COALESCE(v_old.ativo,false)=p_ativo THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='catalog_status_no_change'; END IF;
  -- Arquivar = ativo false. Nunca exclui; históricos (pedidos/estoque/fiscal) preservados.
  -- b2b_enabled e preços não são tocados aqui.
  UPDATE public.produtos SET ativo=p_ativo, updated_at=pg_catalog.clock_timestamp()
  WHERE id=p_id AND updated_at=p_expected_updated_at RETURNING * INTO v_new;
  IF NOT FOUND OR v_new.id IS DISTINCT FROM p_id OR v_new.ativo IS DISTINCT FROM p_ativo
    OR v_new.updated_at IS NOT DISTINCT FROM v_old.updated_at OR v_new.updated_at <= v_old.updated_at
    OR (pg_catalog.to_jsonb(v_old)-ARRAY['ativo','updated_at']) IS DISTINCT FROM (pg_catalog.to_jsonb(v_new)-ARRAY['ativo','updated_at']) THEN
    RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='catalog_status_confirmation_failed';
  END IF;
  v_receipt:=pg_catalog.jsonb_build_object('id',p_id,'ativo',v_new.ativo,'updated_at',v_new.updated_at,
    'idempotency_key',p_idempotency_key,'audit_id',v_audit,'idempotent',false);
  INSERT INTO public.catalog_platform_admin_audit (id,operation,actor_id,reason,correlation_id,status,counts_before,counts_after,completed_at)
  VALUES (v_audit,'set_global_product_status',v_actor,pg_catalog.btrim(p_reason),p_idempotency_key,'completed',
    pg_catalog.jsonb_build_object('ativo',v_old.ativo),
    pg_catalog.jsonb_build_object('request',v_request,'receipt',v_receipt,'after',pg_catalog.jsonb_build_object('ativo',v_new.ativo)),
    pg_catalog.clock_timestamp());
  RETURN v_receipt;
END;
$$;


ALTER FUNCTION platform_private.set_global_product_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_global_volume_status_core(uuid, timestamp with time zone, boolean, text, text, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_global_volume_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_confirm_token text, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT platform_private.change_global_volume('set_global_volume_status',p_id,p_expected_updated_at,NULL,p_ativo,p_confirm_token,p_reason,p_idempotency_key) $$;


ALTER FUNCTION platform_private.set_global_volume_status_core(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_confirm_token text, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: set_org_principal_admin_core(uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.set_org_principal_admin_core(_org uuid, _user_id uuid, _motivo text, _expected_responsavel uuid, _idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o public.organizations%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE; v_motivo text; v_old uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _org IS NULL OR _user_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF v_motivo = '' THEN v_motivo := 'Alteração de responsável principal'; END IF;
  IF char_length(v_motivo) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo obrigatório (mínimo 2 caracteres)' USING ERRCODE='22023'; END IF;

  SELECT * INTO o FROM public.organizations WHERE id=_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='principal_transferred' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.organization_id=_org AND a.target_user_id=_user_id AND a.reason=v_motivo THEN
      RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF o.responsavel_user_id IS DISTINCT FROM _expected_responsavel THEN
    RAISE EXCEPTION 'platform_conflict: o responsável foi alterado por outra pessoa; recarregue' USING ERRCODE='40001'; END IF;
  IF o.responsavel_user_id = _user_id THEN
    RAISE EXCEPTION 'platform_invalid: este administrador já é o responsável principal' USING ERRCODE='22023'; END IF;
  IF public.is_platform_superadmin(_user_id)
     OR NOT EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE i.organization_id=_org AND i.user_id=_user_id AND i.status='ativo')
     OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=_user_id AND p.organization_id=_org AND p.ativo IS TRUE)
     OR NOT public.has_role(_user_id,'administrador'::public.app_role) THEN
    RAISE EXCEPTION 'platform_invalid: candidato precisa ser administrador ativo desta empresa' USING ERRCODE='22023'; END IF;

  v_old := o.responsavel_user_id;
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET responsavel_user_id=_user_id, responsavel_definido_em=now(), updated_at=now() WHERE id=_org;
  UPDATE public.platform_org_admin_invites SET responsavel_principal = coalesce(user_id=_user_id,false), updated_at=now()
   WHERE organization_id=_org AND responsavel_principal IS DISTINCT FROM coalesce(user_id=_user_id,false);
  UPDATE public.profiles SET cargo = CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END
   WHERE organization_id=_org AND user_id IN (_user_id, v_old) AND cargo IN ('Responsável Principal','Administrador')
     AND cargo IS DISTINCT FROM CASE WHEN user_id=_user_id THEN 'Responsável Principal' ELSE 'Administrador' END;

  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (_org,_user_id,auth.uid(),'principal_transferred','succeeded',v_motivo,'platform_rpc',_idempotency_key,
          jsonb_build_object('responsavel_user_id',v_old,'responsavel_definido_em',o.responsavel_definido_em),
          jsonb_build_object('responsavel_user_id',_user_id));
  RETURN jsonb_build_object('organization_id',_org,'responsavel_user_id',_user_id,'idempotent',false);
END $$;


ALTER FUNCTION platform_private.set_org_principal_admin_core(_org uuid, _user_id uuid, _motivo text, _expected_responsavel uuid, _idempotency_key uuid) OWNER TO postgres;

--
-- Name: stock_envase_complete_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_envase_complete_v1(p_os uuid, p_prog uuid, p_lote uuid, p_estado text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $$
DECLARE org uuid; o public.ordens_servico%ROWTYPE; p public.programacao_producao%ROWTYPE; l public.lotes%ROWTYPE; last_cq text; reserved numeric; prev text;
BEGIN
 org:=platform_private.stock_envase_scope_v1(p_lote,p_prog,p_os,'manual');
 IF p_estado NOT IN ('completed','completed_override') THEN RAISE EXCEPTION 'ENVASE_TRANSITION_STATE' USING ERRCODE='PT409'; END IF;
 IF p_estado='completed_override' AND public.fn_cockpit_is_gestor() IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_TRANSITION_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=p_os AND organization_id=org FOR UPDATE;
 IF NOT FOUND OR o.origem IS DISTINCT FROM 'agronomica' OR o.partner_order_id IS NOT NULL OR o.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os) THEN RAISE EXCEPTION 'ENVASE_TRANSITION_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF org IS DISTINCT FROM platform_private.stock_envase_scope_v1(p_lote,p_prog,p_os,'manual') THEN RAISE EXCEPTION 'ENVASE_TRANSITION_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 prev:=o.status::text;
 IF prev='pronto_entrega' THEN RETURN jsonb_build_object('success',true,'replay',true,'status','pronto_entrega'); END IF;
 IF prev NOT IN ('em_cq','envase') THEN RAISE EXCEPTION 'ENVASE_TRANSITION_STATE' USING ERRCODE='PT409'; END IF;
 SELECT * INTO p FROM public.programacao_producao WHERE id=p_prog AND organization_id=org AND ordem_servico_id=p_os AND ordem_servico_onfarm_id IS NULL FOR SHARE;
 SELECT * INTO l FROM public.lotes WHERE id=p_lote AND organization_id=org AND programacao_id=p_prog FOR SHARE;
 IF p.id IS NULL OR l.id IS NULL
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os OR ordem_servico_onfarm_id=p_os)<>1
 OR (SELECT count(*) FROM public.lotes WHERE programacao_id=p_prog)<>1 THEN RAISE EXCEPTION 'ENVASE_TRANSITION_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Existing CQ criteria, unchanged: lot approved by the reviewed CQ core and latest result aprovado.
 SELECT resultado::text INTO last_cq FROM public.controle_qualidade WHERE lote_id=p_lote ORDER BY created_at DESC, seq DESC LIMIT 1;
 IF l.status::text IS DISTINCT FROM 'aprovado' OR last_cq IS DISTINCT FROM 'aprovado' THEN RAISE EXCEPTION 'ENVASE_TRANSITION_CQ_REQUIRED' USING ERRCODE='PT409'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.envase WHERE lote_id=p_lote AND organization_id=org) THEN RAISE EXCEPTION 'ENVASE_TRANSITION_NO_ENVASE' USING ERRCODE='PT409'; END IF;
 SELECT coalesce(sum(volume_total),0)*1000 INTO reserved FROM public.estoque_produto
  WHERE reservado_para_os_id=p_os AND reservado_para_os_tipo='manual' AND status::text<>'estornado';
 IF p_estado='completed' AND reserved < coalesce(p.volume_necessario,0) THEN RAISE EXCEPTION 'ENVASE_TRANSITION_COVERAGE' USING ERRCODE='PT409'; END IF;
 -- Re-authorize after the programacao/lote/CQ waits and immediately before the first mutation.
 IF org IS DISTINCT FROM platform_private.stock_envase_scope_v1(p_lote,p_prog,p_os,'manual') THEN RAISE EXCEPTION 'ENVASE_TRANSITION_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(pg_catalog.txid_current(),'manual_envase_transition_v1',p_os);
 IF prev='em_cq' THEN UPDATE public.ordens_servico SET status='envase' WHERE id=p_os; END IF;
 UPDATE public.ordens_servico SET status='pronto_entrega' WHERE id=p_os;
 DELETE FROM platform_private.authz_tickets WHERE txid=pg_catalog.txid_current() AND scope='manual_envase_transition_v1' AND target=p_os;
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,lote_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 VALUES(p_os,'manual',p_prog,p_lote,prev,'pronto_entrega','concluir_envase_v2',auth.uid(),jsonb_build_object('estado',p_estado,'reservado_ml',reserved,'cq','aprovado')::text);
 RETURN jsonb_build_object('success',true,'replay',false,'status','pronto_entrega','status_anterior',prev);
END $$;


ALTER FUNCTION platform_private.stock_envase_complete_v1(p_os uuid, p_prog uuid, p_lote uuid, p_estado text) OWNER TO postgres;

--
-- Name: stock_envase_mutation_gate_v1(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_envase_mutation_gate_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $$
BEGIN
 IF TG_LEVEL<>'STATEMENT' OR TG_WHEN<>'BEFORE' OR TG_OP NOT IN ('INSERT','UPDATE','DELETE','TRUNCATE')
 OR TG_RELID NOT IN ('public.organizations'::regclass,'public.organization_subscriptions'::regclass,'public.saas_plan_versions'::regclass,'public.saas_plan_version_features'::regclass,'public.saas_features'::regclass,'public.saas_modules'::regclass,'public.organization_feature_overrides'::regclass,'public.clientes'::regclass,'public.programacao_producao'::regclass,'public.ordens_servico'::regclass,'public.lotes'::regclass,'public.controle_qualidade'::regclass,'public.estoque_produto'::regclass) THEN RAISE EXCEPTION 'ENVASE_GATE_CONTEXT_DENIED' USING ERRCODE='42501'; END IF;
 -- Existing upstream RPCs can prelock business rows before their first DML.
 -- Never wait here while owning those rows: reject contention atomically instead
 -- of closing the singleton/business-row deadlock cycle.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'STOCK_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION platform_private.stock_envase_mutation_gate_v1() OWNER TO postgres;

--
-- Name: stock_envase_reservation_root_v1(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_envase_reservation_root_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE p public.programacao_producao%ROWTYPE; l public.lotes%ROWTYPE; o public.ordens_servico%ROWTYPE;
BEGIN
 IF NEW.status::text<>'reservado' OR NEW.reservado_para_os_tipo IS DISTINCT FROM 'manual' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.lote_id IS NOT DISTINCT FROM OLD.lote_id AND NEW.reservado_para_os_id IS NOT DISTINCT FROM OLD.reservado_para_os_id THEN RETURN NEW; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=NEW.reservado_para_os_id;
 SELECT * INTO p FROM public.programacao_producao WHERE ordem_servico_id=o.id;
 IF NOT FOUND THEN RETURN NEW; END IF;
 SELECT * INTO l FROM public.lotes WHERE id=NEW.lote_id;
 IF o.status::text NOT IN ('em_cq','envase','pronto_entrega') OR l.programacao_id IS DISTINCT FROM p.id OR l.organization_id IS DISTINCT FROM o.organization_id OR p.organization_id IS DISTINCT FROM o.organization_id
 OR NEW.produto_id IS DISTINCT FROM p.produto_id OR NEW.microrganismo_id IS DISTINCT FROM p.microrganismo_id OR NEW.reservado_para_cliente_id IS DISTINCT FROM o.cliente_id
 OR (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=o.id)<>1 THEN RAISE EXCEPTION 'ENVASE_RESERVATION_LINEAGE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION platform_private.stock_envase_reservation_root_v1() OWNER TO postgres;

--
-- Name: stock_envase_scope_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_envase_scope_v1(p_lote uuid, p_prog uuid, p_os uuid, p_origem text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid; p public.programacao_producao%ROWTYPE; o public.ordens_servico%ROWTYPE; l public.lotes%ROWTYPE;
BEGIN
 org:=platform_private.stock_motor_actor('reserva');
 IF public.technical_actor_ready(auth.uid()) IS NOT TRUE OR public._saas_user_has_feature(auth.uid(),'envase') IS NOT TRUE
 OR public._saas_user_has_feature(auth.uid(),'ordens_producao') IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF public.fn_cockpit_norm_origem(p_origem) IS DISTINCT FROM 'manual' THEN RAISE EXCEPTION 'ENVASE_ORIGIN_COMPOSITION_PENDING' USING ERRCODE='42501'; END IF;
 IF (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'producao')) IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.programacao_producao WHERE id=p_prog AND organization_id=org;
 IF NOT FOUND OR p.ordem_servico_id IS DISTINCT FROM p_os OR p.ordem_servico_onfarm_id IS NOT NULL THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO o FROM public.ordens_servico WHERE id=p_os AND organization_id=org;
 IF NOT FOUND OR o.partner_order_id IS NOT NULL OR o.partner_order_item_id IS NOT NULL OR o.origem IS DISTINCT FROM 'agronomica'
 OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=o.cliente_id AND organization_id=org) THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO l FROM public.lotes WHERE id=p_lote AND organization_id=org;
 IF NOT FOUND OR l.programacao_id IS DISTINCT FROM p_prog OR l.produto_id IS DISTINCT FROM p.produto_id
 OR l.microrganismo_id IS DISTINCT FROM p.microrganismo_id THEN RAISE EXCEPTION 'ENVASE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN org;
END $$;


ALTER FUNCTION platform_private.stock_envase_scope_v1(p_lote uuid, p_prog uuid, p_os uuid, p_origem text) OWNER TO postgres;

--
-- Name: stock_motor_actor(text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_motor_actor(p_acao text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_org uuid; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'ESTQ_NAO_AUTENTICADO' USING ERRCODE='42501'; END IF;
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_IDENTIDADE_INATIVA' USING ERRCODE='42501'; END IF;
 IF NOT coalesce(public.fn_estoque_pode_operar(auth.uid(),p_acao),false) THEN RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO' USING ERRCODE='42501'; END IF;
 IF NOT coalesce(public.saas_has_feature('estoque_embalagens'),false) THEN RAISE EXCEPTION 'ESTQ_FEATURE_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $$;


ALTER FUNCTION platform_private.stock_motor_actor(p_acao text) OWNER TO postgres;

--
-- Name: stock_motor_context_set(jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_motor_context_set(p_ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 DELETE FROM platform_private.stock_motor_context WHERE txid=txid_current();
 IF p_ctx IS NOT NULL THEN
  PERFORM platform_private.stock_motor_actor(p_ctx->>'acao');
  IF p_ctx->>'usuario_id' IS DISTINCT FROM auth.uid()::text OR jsonb_typeof(p_ctx->'metadata') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  INSERT INTO platform_private.stock_motor_context(txid,actor,item,ctx) VALUES(txid_current(),auth.uid(),(p_ctx->'metadata'->>'stock_request_item')::uuid,p_ctx);
 END IF;
 PERFORM public.fn_estoque_ctx_force(p_ctx);
END $$;


ALTER FUNCTION platform_private.stock_motor_context_set(p_ctx jsonb) OWNER TO postgres;

--
-- Name: stock_motor_item(uuid, text, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_motor_item(p_item uuid, p_acao text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_org uuid; v_item public.estoque_produto%ROWTYPE; v_lote public.lotes%ROWTYPE;
BEGIN
 v_org:=platform_private.stock_motor_actor(p_acao);
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR (p_payload ? 'metadata' AND jsonb_typeof(p_payload->'metadata')<>'object') OR p_payload ?| ARRAY['organization_id','tenant_id','usuario_id','user_id','owner_id'] OR coalesce(p_payload->'metadata','{}'::jsonb) ?| ARRAY['stock_request_item','stock_request_actor','stock_request_fp'] THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(p_payload) e WHERE e.key IN ('motivo','observacao','origem','referencia_tipo','referencia_id','os_id','os_tipo','cliente_id','partner_id','partner_order_id','movimentacao_origem_id','classificacao','sentido','unidade') AND jsonb_typeof(e.value) NOT IN ('string','null')) OR (p_payload->>'sentido' IS NOT NULL AND p_payload->>'sentido' NOT IN ('entrada','saida')) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
 -- Scoped lookup never returns a foreign/orphan row, even under DEFINER.
 SELECT e.* INTO v_item FROM public.estoque_produto e JOIN public.lotes l ON l.id=e.lote_id WHERE e.id=p_item AND l.organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT l.* INTO v_lote FROM public.lotes l WHERE l.id=v_item.lote_id AND l.organization_id=v_org;
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.programacao_producao g WHERE g.id=v_lote.programacao_id AND g.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_item.envase_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.envase e WHERE e.id=v_item.envase_id AND e.lote_id=v_item.lote_id AND e.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,jsonb_build_object('os_id',v_item.reservado_para_os_id,'os_tipo',v_item.reservado_para_os_tipo,'cliente_id',v_item.reservado_para_cliente_id,'partner_id',v_item.reservado_para_partner_id,'partner_order_id',v_item.reservado_para_partner_order_id));
 PERFORM platform_private.stock_motor_refs(p_item,v_item.lote_id,v_org,p_payload);
END $$;


ALTER FUNCTION platform_private.stock_motor_item(p_item uuid, p_acao text, p_payload jsonb) OWNER TO postgres;

--
-- Name: stock_motor_refs(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_motor_refs(p_item uuid, p_lote uuid, p_org uuid, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_os uuid:=nullif(p->>'os_id','')::uuid; v_tipo text:=p->>'os_tipo'; v_cliente uuid:=nullif(p->>'cliente_id','')::uuid;
 v_partner uuid:=nullif(p->>'partner_id','')::uuid; v_order uuid:=nullif(p->>'partner_order_id','')::uuid;
 v_ref uuid:=nullif(p->>'referencia_id','')::uuid; v_rt text:=p->>'referencia_tipo'; v_origin uuid:=nullif(p->>'movimentacao_origem_id','')::uuid;
 v_os_cliente uuid; v_os_order uuid;
BEGIN
 IF v_cliente IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=v_cliente AND c.organization_id=p_org) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_partner IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(v_partner,false),false) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_order IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.partner_orders o WHERE o.id=v_order AND o.partner_id=v_partner AND public.b2b_phase1_order_visible(o.id)) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_os IS NOT NULL THEN
  IF v_tipo IN ('manual','b2b') THEN
   SELECT o.cliente_id,o.partner_order_id INTO v_os_cliente,v_os_order FROM public.ordens_servico o WHERE o.id=v_os AND o.organization_id=p_org;
   IF NOT FOUND THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='b2b' AND (v_order IS NULL OR v_os_order IS DISTINCT FROM v_order OR v_cliente IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
   IF v_tipo='manual' AND (v_os_order IS NOT NULL OR v_partner IS NOT NULL OR v_order IS NOT NULL) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSIF v_tipo IN ('onfarm','on_farm') THEN
   SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=v_os AND c.organization_id=p_org;
   IF NOT FOUND OR v_partner IS NOT NULL OR v_order IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  ELSE RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
  IF v_cliente IS NOT NULL AND v_cliente IS DISTINCT FROM v_os_cliente THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 END IF;
 IF v_origin IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=v_origin AND m.estoque_produto_id=p_item AND m.lote_id=p_lote AND public.stock_p1_movement_owned(m.estoque_produto_id,m.lote_id)) THEN RAISE EXCEPTION 'ESTQ_ESTORNO_ORIGEM_INVALIDA' USING ERRCODE='42501'; END IF;
 -- Only proven existing guard semantics. Unsupported literals fail even without an ID.
 IF v_rt IS NOT NULL AND v_rt NOT IN ('entrega','ordem_servico','manual','sistema') THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('manual','sistema') AND v_ref IS NOT NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_ref IS NOT NULL AND v_rt IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
 IF v_rt IN ('entrega','ordem_servico') AND v_ref IS NULL THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='ordem_servico' AND (v_os IS NULL OR v_ref IS DISTINCT FROM v_os OR v_tipo NOT IN ('manual','b2b','onfarm','on_farm')) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_rt='entrega' AND NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=v_ref AND e.organization_id=p_org AND e.estoque_produto_id=p_item AND (e.lote_id IS NULL OR e.lote_id=p_lote) AND (v_cliente IS NULL OR e.cliente_id=v_cliente) AND (v_os IS NULL OR (v_tipo IN ('manual','b2b') AND e.ordem_servico_id=v_os) OR (v_tipo IN ('onfarm','on_farm') AND e.ordem_servico_onfarm_id=v_os))) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END $$;


ALTER FUNCTION platform_private.stock_motor_refs(p_item uuid, p_lote uuid, p_org uuid, p jsonb) OWNER TO postgres;

--
-- Name: stock_p1_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_p1_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_org uuid := public.h15_actor_organization();
 v_ref uuid;
 v_lote public.lotes%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP IN ('UPDATE','DELETE') AND NOT platform_private.stock_p1_lote_owned(OLD.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
 IF NOT platform_private.stock_p1_lote_owned(NEW.lote_id) THEN
  RAISE EXCEPTION 'ESTQ_TENANT_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 SELECT * INTO v_lote FROM public.lotes WHERE id=NEW.lote_id;
 -- Explicit lote ownership is required; parent references never assign ownership.
 IF v_lote.programacao_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.programacao_producao p
   WHERE p.id=v_lote.programacao_id AND p.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.envase_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.envase e WHERE e.id=NEW.envase_id
   AND e.lote_id=NEW.lote_id AND e.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_cliente_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.clientes c WHERE c.id=NEW.reservado_para_cliente_id AND c.organization_id=v_org
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_partner_id IS NOT NULL AND NOT coalesce(public.b2b_phase1_partner_visible(NEW.reservado_para_partner_id,false),false) THEN
  RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
 END IF;
 IF NEW.reservado_para_partner_order_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM public.partner_orders o WHERE o.id=NEW.reservado_para_partner_order_id
    AND o.partner_id=NEW.reservado_para_partner_id
    AND public.b2b_phase1_order_visible(o.id)
 ) THEN RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF NEW.reservado_para_os_id IS NOT NULL THEN
  IF NEW.reservado_para_os_tipo IN ('onfarm','on_farm') THEN
   SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o
    JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.reservado_para_os_id;
  ELSIF NEW.reservado_para_os_tipo IN ('manual','b2b') THEN
   SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.reservado_para_os_id;
  ELSE
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  IF v_ref IS DISTINCT FROM v_org THEN
   RAISE EXCEPTION 'ESTQ_REFERENCE_FORBIDDEN' USING ERRCODE='42501';
  END IF;
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION platform_private.stock_p1_guard() OWNER TO postgres;

--
-- Name: stock_p1_lote_owned(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_p1_lote_owned(p_lote uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS (
   SELECT 1 FROM public.lotes l
   WHERE l.id = p_lote AND l.organization_id IS NOT NULL
     AND l.organization_id = public.h15_actor_organization()
 );
$$;


ALTER FUNCTION platform_private.stock_p1_lote_owned(p_lote uuid) OWNER TO postgres;

--
-- Name: stock_p1_movement_guard(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_p1_movement_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE v_org uuid:=public.h15_actor_organization(); v_lote uuid; v_ref uuid;
BEGIN
IF auth.uid() IS NULL OR v_org IS NULL THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
SELECT e.lote_id INTO v_lote FROM public.estoque_produto e WHERE e.id=NEW.estoque_produto_id;
IF v_lote IS NULL OR NOT platform_private.stock_p1_lote_owned(v_lote) THEN RAISE EXCEPTION 'ESTQ_MOV_TENANT_FORBIDDEN' USING ERRCODE='42501'; END IF;
-- Only a new ledger row may inherit its verified stock's lote, never organization or legacy backfill.
IF NEW.lote_id IS NULL THEN NEW.lote_id:=v_lote; END IF;
IF NEW.lote_id IS DISTINCT FROM v_lote THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=NEW.cliente_id AND c.organization_id=v_org) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.os_id IS NOT NULL THEN
 IF NEW.os_tipo IN ('manual','b2b') THEN SELECT o.organization_id INTO v_ref FROM public.ordens_servico o WHERE o.id=NEW.os_id;
 ELSIF NEW.os_tipo IN ('onfarm','on_farm') THEN SELECT c.organization_id INTO v_ref FROM public.ordens_servico_onfarm o JOIN public.clientes c ON c.id=o.cliente_id WHERE o.id=NEW.os_id;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF v_ref IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
END IF;
IF NEW.movimentacao_origem_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes m WHERE m.id=NEW.movimentacao_origem_id AND m.estoque_produto_id=NEW.estoque_produto_id AND m.lote_id=NEW.lote_id) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
IF NEW.referencia_id IS NOT NULL THEN
 IF NEW.referencia_tipo='entrega' THEN
  IF NOT EXISTS(SELECT 1 FROM public.entregas e WHERE e.id=NEW.referencia_id AND e.organization_id=v_org AND (e.lote_id IS NULL OR e.lote_id=NEW.lote_id) AND (NEW.cliente_id IS NULL OR e.cliente_id=NEW.cliente_id)) THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('estoque','estoque_produto') THEN
  IF NEW.referencia_id IS DISTINCT FROM NEW.estoque_produto_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSIF NEW.referencia_tipo IN ('os','ordem_servico') THEN
  IF NEW.os_id IS NULL OR NEW.referencia_id IS DISTINCT FROM NEW.os_id THEN RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_FORBIDDEN' USING ERRCODE='42501'; END IF;
 ELSE RAISE EXCEPTION 'ESTQ_MOV_REFERENCE_UNSUPPORTED' USING ERRCODE='42501'; END IF;
END IF;
RETURN NEW;
END $$;


ALTER FUNCTION platform_private.stock_p1_movement_guard() OWNER TO postgres;

--
-- Name: stock_p1_movement_owned(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.stock_p1_movement_owned(p_stock uuid, p_lote uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.estoque_produto e WHERE e.id=p_stock AND e.lote_id=p_lote AND platform_private.stock_p1_lote_owned(e.lote_id)); $$;


ALTER FUNCTION platform_private.stock_p1_movement_owned(p_stock uuid, p_lote uuid) OWNER TO postgres;

--
-- Name: storage1_application_allowed(text, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.storage1_application_allowed(p_name text, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE org uuid; r platform_private.application_save_preparations%ROWTYPE; a public.aplicacoes%ROWTYPE;
 client uuid; os_org uuid; product uuid; staff boolean; u uuid:=auth.uid(); responsible uuid; own_role boolean; os_status text; lot uuid;
BEGIN
 IF auth.uid() IS NULL OR public.storage1_path_strict(p_name) IS DISTINCT FROM true OR p_action IS NULL
 OR p_action NOT IN ('select','insert','update','delete') OR p_name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[A-Za-z0-9_.-]+$' THEN RETURN false; END IF;
 org:=public.h15_actor_organization(); IF org IS NULL THEN RETURN false; END IF;
 SELECT * INTO r FROM platform_private.application_save_preparations WHERE application_id=split_part(p_name,'/',2)::uuid;
 IF p_action='insert' AND r.application_id IS NOT NULL THEN
 IF r.actor_id IS DISTINCT FROM auth.uid() OR r.organization_id IS DISTINCT FROM org OR r.committed_at IS NOT NULL
 OR r.expires_at<=clock_timestamp() OR r.client_id::text IS DISTINCT FROM split_part(p_name,'/',1)
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r.manifest) ev WHERE ev->>'storage_path'=p_name)
 OR public.can_user_create_aplicacao_for_cliente(r.client_id) IS DISTINCT FROM true THEN RETURN false; END IF;
 -- Exact current RPC membership branch: a broad operator/applicator role must
 -- not rescue a revoked consultant/technical/producer portfolio.
 IF (public.has_role(u,'cliente_produtor') OR public.has_role(u,'consultor_tecnico') OR public.has_role(u,'tecnico_agronomo'))
 AND NOT (public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo'))
 AND NOT r.client_id=ANY(public.get_cliente_ids_for_user(u)) THEN RETURN false; END IF;
 responsible:=nullif(r.payload->>'responsavel_id','')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=responsible AND organization_id=org AND ativo IS TRUE AND senha_provisoria IS FALSE)
 OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=responsible AND role::text IN
 ('administrador','gestor','administrativo','consultor_tecnico','tecnico_agronomo','aplicador','operador_onfarm','cliente_produtor'))
 OR platform_private.platform_actor_access_ready(responsible) IS DISTINCT FROM true THEN RETURN false; END IF;
 own_role:=public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo') OR public.has_role(u,'consultor_tecnico');
 IF NOT own_role AND responsible IS DISTINCT FROM u THEN RETURN false; END IF;
 lot:=nullif(r.payload->>'lote_usado_id','')::uuid;
 IF r.payload->>'ordem_servico_id' IS NOT NULL THEN
 SELECT cliente_id,organization_id,produto_id,status::text INTO client,os_org,product,os_status FROM public.ordens_servico WHERE id=(r.payload->>'ordem_servico_id')::uuid;
 ELSE SELECT os.cliente_id,c.organization_id,os.produto_id,os.status::text INTO client,os_org,product,os_status FROM public.ordens_servico_onfarm os JOIN public.clientes c ON c.id=os.cliente_id WHERE os.id=(r.payload->>'ordem_servico_onfarm_id')::uuid; END IF;
 RETURN client=r.client_id AND os_org=org AND product::text=r.payload->>'produto_usado_id'
 AND (os_status IN ('entregue','pronto_entrega','envase') OR (r.rectify_id IS NOT NULL AND os_status='finalizada'))
 AND (lot IS NULL OR EXISTS(SELECT 1 FROM public.lotes WHERE id=lot AND produto_id=product AND organization_id=org AND status='aprovado'))
 AND EXISTS(SELECT 1 FROM public.clientes WHERE id=client AND organization_id=org)
 AND EXISTS(SELECT 1 FROM public.produtos WHERE id=product AND ativo IS TRUE)
 AND (r.rectify_id IS NULL OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE id=r.rectify_id AND organization_id=org AND is_latest IS TRUE)
 AND public.can_user_manage_aplicacao(r.rectify_id) AND public.can_user_access_aplicacao(r.rectify_id))
 AND public.h15_actor_organization()=org;
 END IF;
 SELECT * INTO a FROM public.aplicacoes WHERE id=split_part(p_name,'/',2)::uuid;
 IF NOT FOUND OR a.organization_id IS DISTINCT FROM org OR (a.ordem_servico_id IS NULL)=(a.ordem_servico_onfarm_id IS NULL) THEN RETURN false; END IF;
 IF a.ordem_servico_id IS NOT NULL THEN SELECT cliente_id,organization_id INTO client,os_org FROM public.ordens_servico WHERE id=a.ordem_servico_id;
 ELSE SELECT os.cliente_id,c.organization_id INTO client,os_org FROM public.ordens_servico_onfarm os JOIN public.clientes c ON c.id=os.cliente_id WHERE os.id=a.ordem_servico_onfarm_id; END IF;
 IF client::text IS DISTINCT FROM split_part(p_name,'/',1) OR os_org IS DISTINCT FROM org
 OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=client AND organization_id=org) THEN RETURN false; END IF;
 staff:=NOT public.has_role(auth.uid(),'aplicador') OR public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor')
 OR public.has_role(auth.uid(),'administrativo') OR public.has_role(auth.uid(),'consultor_tecnico') OR a.responsavel_id=auth.uid()
 OR client=ANY(public.get_cliente_ids_for_user(auth.uid()));
 IF p_action='select' THEN RETURN staff AND public.can_user_access_aplicacao(a.id); END IF;
 -- Finalized objects are immutable. Deletion remains denied when metadata references bytes.
 IF p_action IN ('insert','update') THEN RETURN false; END IF;
 RETURN staff AND a.is_latest IS TRUE AND public.can_user_manage_aplicacao(a.id)
 AND NOT EXISTS(SELECT 1 FROM public.aplicacao_evidencias WHERE storage_path=p_name);
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END;
$_$;


ALTER FUNCTION platform_private.storage1_application_allowed(p_name text, p_action text) OWNER TO postgres;

--
-- Name: storage1_consultor_allowed(text, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.storage1_consultor_allowed(p_name text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$ SELECT p_action IS NOT NULL AND platform_private.storage1_consultor_core(p_name,p_action); $$;


ALTER FUNCTION platform_private.storage1_consultor_allowed(p_name text, p_action text) OWNER TO postgres;

--
-- Name: storage1_consultor_core(text, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.storage1_consultor_core(p_name text, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_org uuid; v_id uuid; v_client uuid; v_status text;
BEGIN
 IF auth.uid() IS NULL OR p_action IS NULL OR NOT public.storage1_path_strict(p_name) OR p_action NOT IN ('select','insert','update','delete') THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization(); IF v_org IS NULL THEN RETURN false; END IF;
 IF p_name !~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/(foto|audio|documento)/[A-Za-z0-9_.-]+$' OR split_part(p_name,'/',1)<>v_org::text THEN RETURN false; END IF;
 BEGIN v_id:=split_part(p_name,'/',2)::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
 SELECT r.cliente_id,r.status::text INTO v_client,v_status FROM public.registros_consultor r JOIN public.clientes c ON c.id=r.cliente_id AND c.organization_id=v_org WHERE r.id=v_id;
 IF NOT FOUND THEN RETURN false; END IF;
 IF p_action='select' THEN RETURN public.technical_child_read_scope(v_id) AND ((public.has_role(auth.uid(),'cliente_produtor') AND v_client=ANY(public.get_cliente_ids_for_user(auth.uid()))) OR ((public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'consultor_tecnico') OR public.has_role(auth.uid(),'tecnico_agronomo') OR public.has_role(auth.uid(),'aplicador')) AND public.can_view_technical_visit(auth.uid(),v_id))); END IF;
 RETURN v_status IN ('rascunho','em_andamento') AND (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'consultor_tecnico') OR public.has_role(auth.uid(),'tecnico_agronomo') OR public.has_role(auth.uid(),'aplicador')) AND public.can_manage_technical_visit(auth.uid(),v_id);
END; $_$;


ALTER FUNCTION platform_private.storage1_consultor_core(p_name text, p_action text) OWNER TO postgres;

--
-- Name: storage1_delivery_allowed(text, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.storage1_delivery_allowed(p_name text, p_action text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_org uuid; v_id uuid; v_e public.entregas%ROWTYPE; v_client_org uuid; v_staff boolean;
BEGIN
 IF auth.uid() IS NULL OR p_action IS NULL OR NOT public.storage1_path_strict(p_name) OR p_action NOT IN ('select','insert','update','delete') THEN RETURN false; END IF;
 v_org:=public.h15_actor_organization(); IF v_org IS NULL THEN RETURN false; END IF;
 IF p_name !~ '^entregas/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/([A-Za-z0-9_-]+/)*[A-Za-z0-9_.-]+$' THEN RETURN false; END IF;
 v_id:=split_part(p_name,'/',2)::uuid;
 SELECT * INTO v_e FROM public.entregas WHERE id=v_id;
 IF NOT FOUND OR v_e.organization_id IS DISTINCT FROM v_org OR v_e.cliente_id IS NULL THEN RETURN false; END IF;
 SELECT organization_id INTO v_client_org FROM public.clientes WHERE id=v_e.cliente_id;
 IF v_client_org IS DISTINCT FROM v_org THEN RETURN false; END IF;
 v_staff:=public.is_delivery_staff(auth.uid()) AND (NOT public.has_role(auth.uid(),'aplicador') OR public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor') OR public.has_role(auth.uid(),'administrativo') OR public.has_role(auth.uid(),'producao') OR public.has_role(auth.uid(),'operador_onfarm') OR v_e.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid())));
 IF p_action='select' THEN RETURN v_staff OR public.is_financial_staff(auth.uid()) OR (public.has_role(auth.uid(),'cliente_produtor') AND v_e.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid()))); END IF;
 RETURN v_staff AND v_e.status::text IN ('separado','em_rota');
END; $_$;


ALTER FUNCTION platform_private.storage1_delivery_allowed(p_name text, p_action text) OWNER TO postgres;

--
-- Name: storage2_salvar_aplicacao_legacy_closed(uuid, jsonb, uuid, jsonb, uuid[]); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.storage2_salvar_aplicacao_legacy_closed(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid DEFAULT NULL::uuid, p_evidencias jsonb DEFAULT '[]'::jsonb, p_evidencias_manter uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
                                                                                                                                                                        DECLARE
                                                                                                                                                                          v_uid uuid := auth.uid();
                                                                                                                                                                            v_os_id uuid := NULLIF(p_payload->>'ordem_servico_id','')::uuid;
                                                                                                                                                                              v_os_onfarm_id uuid := NULLIF(p_payload->>'ordem_servico_onfarm_id','')::uuid;
                                                                                                                                                                                v_cliente_id uuid; v_produto_os uuid;
                                                                                                                                                                                  v_produto_payload uuid := NULLIF(p_payload->>'produto_usado_id','')::uuid;
                                                                                                                                                                                    v_lote_id uuid := NULLIF(p_payload->>'lote_usado_id','')::uuid; v_lote_produto uuid;
                                                                                                                                                                                      v_original public.aplicacoes%ROWTYPE; v_parent_id uuid; v_versao integer := 1;
                                                                                                                                                                                        v_motivo text := NULLIF(btrim(p_payload->>'motivo_retificacao'),'');
                                                                                                                                                                                          v_dose numeric := NULLIF(p_payload->>'dose_aplicada','')::numeric;
                                                                                                                                                                                            v_area numeric := NULLIF(p_payload->>'area_aplicada_ha','')::numeric;
                                                                                                                                                                                              v_hora_inicio timestamptz := NULLIF(p_payload->>'hora_inicio','')::timestamptz;
                                                                                                                                                                                                v_hora_fim timestamptz := NULLIF(p_payload->>'hora_fim','')::timestamptz;
                                                                                                                                                                                                  v_ev jsonb; v_ev_id uuid; v_manter uuid;
                                                                                                                                                                                                  BEGIN
                                                                                                                                                                                                    IF v_uid IS NULL THEN RAISE EXCEPTION 'Autenticacao obrigatoria' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                      IF p_aplicacao_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Identificador e dados da aplicacao sao obrigatorios' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                        IF jsonb_typeof(COALESCE(p_evidencias,'[]'::jsonb)) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Evidencias invalidas' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                          IF EXISTS (SELECT 1 FROM public.aplicacoes WHERE id=p_aplicacao_id AND created_by=v_uid) THEN RETURN jsonb_build_object('success',true,'created',false,'id',p_aplicacao_id); END IF;
                                                                                                                                                                                                            IF num_nonnulls(v_os_id,v_os_onfarm_id)<>1 THEN RAISE EXCEPTION 'Informe exatamente uma ordem de servico' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                              IF v_os_id IS NOT NULL THEN SELECT cliente_id,produto_id INTO v_cliente_id,v_produto_os FROM public.ordens_servico WHERE id=v_os_id FOR UPDATE;
                                                                                                                                                                                                                ELSE SELECT cliente_id,produto_id INTO v_cliente_id,v_produto_os FROM public.ordens_servico_onfarm WHERE id=v_os_onfarm_id FOR UPDATE; END IF;
                                                                                                                                                                                                                  IF v_cliente_id IS NULL THEN RAISE EXCEPTION 'Ordem de servico inexistente ou sem cliente' USING ERRCODE='23503'; END IF;
                                                                                                                                                                                                                    IF v_produto_os IS NULL THEN RAISE EXCEPTION 'A ordem de servico nao possui produto definido' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                      IF NOT public.can_user_create_aplicacao_for_cliente(v_cliente_id) THEN RAISE EXCEPTION 'Sem permissao para registrar aplicacao deste cliente' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                        IF v_produto_payload IS DISTINCT FROM v_produto_os THEN RAISE EXCEPTION 'Produto informado nao pertence a ordem de servico' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                          IF v_lote_id IS NOT NULL THEN SELECT produto_id INTO v_lote_produto FROM public.lotes WHERE id=v_lote_id; IF v_lote_produto IS DISTINCT FROM v_produto_os THEN RAISE EXCEPTION 'Lote informado nao pertence ao produto da ordem' USING ERRCODE='22023'; END IF; END IF;
                                                                                                                                                                                                                            IF v_dose IS NULL OR v_dose<=0 OR v_area IS NULL OR v_area<=0 THEN RAISE EXCEPTION 'Dose e area devem ser maiores que zero' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                              IF v_hora_inicio IS NOT NULL AND v_hora_fim IS NOT NULL AND v_hora_fim<v_hora_inicio THEN RAISE EXCEPTION 'Horario final nao pode ser anterior ao inicial' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                IF p_rectify_id IS NOT NULL THEN
                                                                                                                                                                                                                                    SELECT * INTO v_original FROM public.aplicacoes WHERE id=p_rectify_id FOR UPDATE;
                                                                                                                                                                                                                                        IF v_original.id IS NULL OR NOT v_original.is_latest THEN RAISE EXCEPTION 'Somente a versao vigente pode ser retificada' USING ERRCODE='40001'; END IF;
                                                                                                                                                                                                                                            IF NOT public.can_user_access_aplicacao(p_rectify_id) THEN RAISE EXCEPTION 'Sem acesso a aplicacao original' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                IF v_original.ordem_servico_id IS DISTINCT FROM v_os_id OR v_original.ordem_servico_onfarm_id IS DISTINCT FROM v_os_onfarm_id THEN RAISE EXCEPTION 'A ordem de servico nao pode ser alterada na retificacao' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                    IF v_motivo IS NULL OR char_length(v_motivo) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Motivo da retificacao deve ter entre 5 e 1000 caracteres' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                        v_parent_id:=COALESCE(v_original.parent_id,v_original.id); v_versao:=v_original.versao+1;
                                                                                                                                                                                                                                                            UPDATE public.aplicacoes SET is_latest=false WHERE id=v_original.id;
                                                                                                                                                                                                                                                              ELSE v_parent_id:=NULL; v_motivo:=NULL; END IF;
                                                                                                                                                                                                                                                                INSERT INTO public.aplicacoes (id,ordem_servico_id,ordem_servico_onfarm_id,data_aplicacao,hora_inicio,hora_fim,responsavel_id,responsavel,modo_aplicacao,produto_usado_id,lote_usado_id,dose_aplicada,volume_calda_l_ha,volume_total_aplicado_ml,area_aplicada_ha,equipamento,equipamento_modelo,bico_tipo,pressao_bar,temperatura_c,umidade_pct,vento_kmh,condicoes_climaticas,latitude,longitude,resultado_inicial,observacoes,created_by,parent_id,versao,motivo_retificacao,is_latest)
                                                                                                                                                                                                                                                                  VALUES (p_aplicacao_id,v_os_id,v_os_onfarm_id,COALESCE(NULLIF(p_payload->>'data_aplicacao','')::date,CURRENT_DATE),v_hora_inicio,v_hora_fim,NULLIF(p_payload->>'responsavel_id','')::uuid,NULLIF(btrim(p_payload->>'responsavel'),''),NULLIF(btrim(p_payload->>'modo_aplicacao'),''),v_produto_payload,v_lote_id,v_dose,NULLIF(p_payload->>'volume_calda_l_ha','')::numeric,NULLIF(p_payload->>'volume_total_aplicado_ml','')::numeric,v_area,NULLIF(btrim(p_payload->>'equipamento'),''),NULLIF(btrim(p_payload->>'equipamento_modelo'),''),NULLIF(btrim(p_payload->>'bico_tipo'),''),NULLIF(p_payload->>'pressao_bar','')::numeric,NULLIF(p_payload->>'temperatura_c','')::numeric,NULLIF(p_payload->>'umidade_pct','')::numeric,NULLIF(p_payload->>'vento_kmh','')::numeric,NULLIF(btrim(p_payload->>'condicoes_climaticas'),''),NULLIF(p_payload->>'latitude','')::numeric,NULLIF(p_payload->>'longitude','')::numeric,NULLIF(btrim(p_payload->>'resultado_inicial'),''),NULLIF(btrim(p_payload->>'observacoes'),''),v_uid,v_parent_id,v_versao,v_motivo,true);
                                                                                                                                                                                                                                                                    FOR v_ev IN SELECT value FROM jsonb_array_elements(COALESCE(p_evidencias,'[]'::jsonb)) LOOP
                                                                                                                                                                                                                                                                        IF (v_ev->>'storage_path') NOT LIKE v_cliente_id::text||'/'||p_aplicacao_id::text||'/%' THEN RAISE EXCEPTION 'Caminho de evidencia nao pertence a aplicacao' USING ERRCODE='22023'; END IF;
                                                                                                                                                                                                                                                                            INSERT INTO public.aplicacao_evidencias(aplicacao_id,tipo,url,storage_path,legenda,mime,tamanho_bytes,created_by,versao_origem_id) VALUES(p_aplicacao_id,v_ev->>'tipo',NULL,v_ev->>'storage_path',NULLIF(btrim(v_ev->>'legenda'),''),v_ev->>'mime',NULLIF(v_ev->>'tamanho_bytes','')::bigint,v_uid,p_aplicacao_id) RETURNING id INTO v_ev_id;
                                                                                                                                                                                                                                                                                INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,v_ev_id);
                                                                                                                                                                                                                                                                                  END LOOP;
                                                                                                                                                                                                                                                                                    IF p_rectify_id IS NOT NULL THEN FOREACH v_manter IN ARRAY COALESCE(p_evidencias_manter,'{}'::uuid[]) LOOP
                                                                                                                                                                                                                                                                                        IF NOT EXISTS(SELECT 1 FROM public.aplicacao_evidencias_vinculos WHERE aplicacao_id=p_rectify_id AND evidencia_id=v_manter) THEN RAISE EXCEPTION 'Evidencia herdada nao pertence a versao anterior' USING ERRCODE='42501'; END IF;
                                                                                                                                                                                                                                                                                            INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,v_manter) ON CONFLICT DO NOTHING;
                                                                                                                                                                                                                                                                                              END LOOP; END IF;
                                                                                                                                                                                                                                                                                                RETURN jsonb_build_object('success',true,'created',true,'id',p_aplicacao_id,'versao',v_versao);
                                                                                                                                                                                                                                                                                                END;
                                                                                                                                                                                                                                                                                                $$;


ALTER FUNCTION platform_private.storage2_salvar_aplicacao_legacy_closed(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid, p_evidencias jsonb, p_evidencias_manter uuid[]) OWNER TO postgres;

--
-- Name: tenant_admin_user_links(uuid[]); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_admin_user_links(p_user_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_items jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'administrador'::public.app_role) OR public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 SELECT organization_id INTO v_org FROM public.profiles WHERE user_id=auth.uid() AND ativo=true;
 IF v_org IS NULL THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 IF p_user_ids IS NULL OR cardinality(p_user_ids) NOT BETWEEN 1 AND 100 OR array_position(p_user_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'tenant_users_invalid_input' USING ERRCODE='22023'; END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'user_id',p.user_id,
   'expected_version',platform_private.user_edit_f2_version(p.user_id),
   'clientes',COALESCE((SELECT jsonb_agg(jsonb_build_object('cliente_id',c.id,'nome',c.nome,'principal',uc.principal,'status_cliente',c.status_cliente,
       'vigente',(uc.is_active AND uc.revoked_at IS NULL AND (uc.valid_from IS NULL OR uc.valid_from<=now()) AND (uc.valid_until IS NULL OR uc.valid_until>now())))
       ORDER BY uc.principal DESC,c.nome,c.id)
     FROM public.user_clientes uc JOIN public.clientes c ON c.id=uc.cliente_id AND c.organization_id=v_org WHERE uc.user_id=p.user_id),'[]'::jsonb),
   'parceiro',(SELECT jsonb_build_object('partner_id',pa.id,'razao_social',pa.razao_social,'papel',pu.papel,'ativo',(pa.ativo AND pa.deleted_at IS NULL))
     FROM public.partner_users pu JOIN public.partner_accounts pa ON pa.id=pu.partner_id AND pa.commercial_owner_organization_id=v_org WHERE pu.user_id=p.user_id ORDER BY pu.created_at,pu.id LIMIT 1),
   'parceiros_total',(SELECT count(*) FROM public.partner_users pu JOIN public.partner_accounts pa ON pa.id=pu.partner_id AND pa.commercial_owner_organization_id=v_org WHERE pu.user_id=p.user_id),
   'fora_do_alcance',(SELECT count(*) FROM public.user_clientes uc LEFT JOIN public.clientes c ON c.id=uc.cliente_id WHERE uc.user_id=p.user_id AND c.organization_id IS DISTINCT FROM v_org)
     +(SELECT count(*) FROM public.partner_users pu LEFT JOIN public.partner_accounts pa ON pa.id=pu.partner_id WHERE pu.user_id=p.user_id AND pa.commercial_owner_organization_id IS DISTINCT FROM v_org)
 ) ORDER BY p.user_id),'[]'::jsonb) INTO v_items
 FROM public.profiles p WHERE p.user_id=ANY(p_user_ids) AND p.organization_id=v_org AND NOT public.is_platform_superadmin(p.user_id);
 RETURN jsonb_build_object('items',v_items);
END $$;


ALTER FUNCTION platform_private.tenant_admin_user_links(p_user_ids uuid[]) OWNER TO postgres;

--
-- Name: tenant_email_actor_org(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_email_actor_org() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid;
BEGIN
 IF auth.uid() IS NULL OR public.is_platform_superadmin(auth.uid())
 OR platform_private.platform_actor_access_ready(auth.uid()) IS DISTINCT FROM true
 OR public.has_role(auth.uid(),'administrador'::public.app_role) IS DISTINCT FROM true THEN
  RETURN NULL;
 END IF;
 SELECT p.organization_id INTO v_org FROM public.profiles p
 JOIN public.organizations o ON o.id=p.organization_id
 WHERE p.user_id=auth.uid() AND p.ativo IS TRUE AND p.senha_provisoria IS FALSE AND o.ativo IS TRUE;
 RETURN v_org;
END $$;


ALTER FUNCTION platform_private.tenant_email_actor_org() OWNER TO postgres;

