-- Name: tenant_smtp_lane_ready(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_lane_ready(p_org uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ SELECT tenant_smtp_executor.tenant_smtp_dispatch_ready(p_org) $$;


ALTER FUNCTION platform_private.tenant_smtp_lane_ready(p_org uuid) OWNER TO postgres;

--
-- Name: tenant_smtp_lane_recipient(uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_lane_recipient(p_org uuid, p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 SELECT lower(u.email) FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id JOIN auth.users u ON u.id=p.user_id
 WHERE p.user_id=p_user AND p.organization_id=p_org AND p.ativo IS TRUE AND o.ativo IS TRUE
 AND u.email_confirmed_at IS NOT NULL AND u.email ~ '^[^@\s<>"]{1,64}@[^@\s<>"]{1,190}$'
 AND NOT public.is_platform_superadmin(p_user)
 AND (public.has_role(p_user,'consultor_tecnico'::public.app_role) OR public.has_role(p_user,'tecnico_agronomo'::public.app_role))
$_$;


ALTER FUNCTION platform_private.tenant_smtp_lane_recipient(p_org uuid, p_user uuid) OWNER TO postgres;

--
-- Name: tenant_smtp_lane_recipient_hash(uuid, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_lane_recipient_hash(p_outbox uuid, p_email text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$ SELECT encode(pg_catalog.sha256(pg_catalog.convert_to(p_outbox::text||':'||lower(btrim(p_email)),'UTF8')),'hex') $$;


ALTER FUNCTION platform_private.tenant_smtp_lane_recipient_hash(p_outbox uuid, p_email text) OWNER TO postgres;

--
-- Name: tenant_smtp_lane_source_reason(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_lane_source_reason(p_source uuid, p_cliente uuid, p_org uuid, p_recipient uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s record; c record;
BEGIN
 SELECT id,cliente_id,consultor_atribuido,status::text AS status INTO s FROM public.portal_solicitacoes WHERE id=p_source;
 IF NOT FOUND THEN RETURN 'source_missing'; END IF;
 IF s.cliente_id IS DISTINCT FROM p_cliente THEN RETURN 'source_client_changed'; END IF;
 IF s.consultor_atribuido IS NULL THEN RETURN 'source_unassigned'; END IF;
 IF s.consultor_atribuido IS DISTINCT FROM p_recipient THEN RETURN 'source_reassigned'; END IF;
 IF s.status IS NULL OR s.status NOT IN ('pendente','atribuida') THEN RETURN 'source_state_ineligible'; END IF;
 SELECT organization_id,status_cliente::text AS st INTO c FROM public.clientes WHERE id=p_cliente;
 IF NOT FOUND OR c.organization_id IS DISTINCT FROM p_org THEN RETURN 'client_tenant_changed'; END IF;
 IF c.st IS DISTINCT FROM 'ativo' THEN RETURN 'client_ineligible'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_recipient AND uc.cliente_id=p_cliente
  AND uc.is_active IS TRUE AND uc.revoked_at IS NULL AND (uc.valid_from IS NULL OR uc.valid_from<=now())
  AND (uc.valid_until IS NULL OR uc.valid_until>=now()) AND uc.access_level::text IN ('read','execute','manage')) THEN RETURN 'recipient_portfolio_revoked'; END IF;
 IF platform_private.tenant_smtp_lane_recipient(p_org,p_recipient) IS NULL THEN RETURN 'recipient_unproven'; END IF;
 RETURN NULL;
END $$;


ALTER FUNCTION platform_private.tenant_smtp_lane_source_reason(p_source uuid, p_cliente uuid, p_org uuid, p_recipient uuid) OWNER TO postgres;

--
-- Name: tenant_smtp_sender_challenge_claim(bigint, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_sender_challenge_claim(p_version bigint, p_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; s public.communication_tenant_email_settings; c platform_private.tenant_smtp_sender_challenges; v_id uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid();
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 IF p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 PERFORM platform_private.tenant_smtp_f4_reconcile(v_org);
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF c.version<>p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'challenge_id',c.id,'state',c.state,'version',c.version);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND state IN ('claimed','executing'))
 OR EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND state<>'complete') THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF (SELECT count(*) FROM platform_private.tenant_smtp_sender_challenges WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '24 hours')>=5 THEN RAISE EXCEPTION 'SMTP_QUOTA' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND version=p_version
  AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '10 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 -- A new challenge supersedes every open one (single valid code per tenant).
 UPDATE platform_private.tenant_smtp_sender_challenges SET state='invalidated',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp()
  WHERE organization_id=v_org AND state IN ('sent','ambiguous');
 INSERT INTO platform_private.tenant_smtp_sender_challenges(id,organization_id,actor_id,version,from_email,request_key,fence,actor_iat,state)
 VALUES(v_id,v_org,auth.uid(),p_version,lower(s.config->>'from_email'),p_key,v_fence,coalesce((auth.jwt()->>'iat')::bigint,0),'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'sender_challenge_claimed');
 RETURN jsonb_build_object('replay',false,'challenge_id',v_id,'fence',v_fence);
END $$;


ALTER FUNCTION platform_private.tenant_smtp_sender_challenge_claim(p_version bigint, p_key uuid) OWNER TO postgres;

--
-- Name: tenant_smtp_sender_challenge_confirm(uuid, bigint, text); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_sender_challenge_confirm(p_challenge uuid, p_version bigint, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_org uuid; c platform_private.tenant_smtp_sender_challenges; s public.communication_tenant_email_settings; v_ok boolean;
BEGIN
 v_org:=platform_private.tenant_smtp_f4_actor_org();
 IF p_challenge IS NULL OR p_version IS NULL OR p_code IS NULL OR p_code !~ '^[0-9]{8}$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 IF platform_private.tenant_smtp_f4_actor_org() IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Closed gate blocks confirmation of existing challenges (no attempt consumed).
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge AND organization_id=v_org AND actor_id=auth.uid() FOR UPDATE;
 IF c.id IS NULL OR c.state NOT IN ('sent','ambiguous') OR c.code_hash IS NULL THEN RETURN jsonb_build_object('code','SENDER_CHALLENGE_INVALID'); END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM c.version OR p_version IS DISTINCT FROM c.version OR lower(s.config->>'from_email') IS DISTINCT FROM c.from_email THEN
  UPDATE platform_private.tenant_smtp_sender_challenges SET state='invalidated',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp() WHERE id=c.id;
  RETURN jsonb_build_object('code','SENDER_CHALLENGE_STALE');
 END IF;
 IF c.expires_at<clock_timestamp() THEN
  UPDATE platform_private.tenant_smtp_sender_challenges SET state='expired',code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp() WHERE id=c.id;
  RETURN jsonb_build_object('code','SENDER_CHALLENGE_EXPIRED');
 END IF;
 v_ok:=encode(sha256(convert_to(c.code_salt||':'||c.id::text||':'||p_code,'UTF8')),'hex')=c.code_hash;
 IF v_ok THEN
  UPDATE platform_private.tenant_smtp_sender_challenges SET state='verified',attempts=attempts+1,code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp() WHERE id=c.id;
  INSERT INTO platform_private.tenant_smtp_sender_verifications(organization_id,version,from_email,challenge_id,verified_by)
  VALUES(v_org,c.version,c.from_email,c.id,auth.uid())
  ON CONFLICT(organization_id,version) DO UPDATE SET from_email=EXCLUDED.from_email,challenge_id=EXCLUDED.challenge_id,verified_by=EXCLUDED.verified_by,verified_at=clock_timestamp(),invalidated_at=NULL;
  INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),c.version,'sender_verified');
  RETURN jsonb_build_object('code','SENDER_VERIFIED');
 END IF;
 IF c.attempts+1>=5 THEN
  UPDATE platform_private.tenant_smtp_sender_challenges SET state='exhausted',attempts=5,code_hash=NULL,code_salt=NULL,closed_at=clock_timestamp() WHERE id=c.id;
  INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),c.version,'sender_challenge_exhausted');
  RETURN jsonb_build_object('code','SENDER_CHALLENGE_EXHAUSTED');
 END IF;
 UPDATE platform_private.tenant_smtp_sender_challenges SET attempts=attempts+1 WHERE id=c.id;
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),c.version,'sender_challenge_mismatch');
 RETURN jsonb_build_object('code','SENDER_CHALLENGE_MISMATCH','attempts_left',4-c.attempts);
END $_$;


ALTER FUNCTION platform_private.tenant_smtp_sender_challenge_confirm(p_challenge uuid, p_version bigint, p_code text) OWNER TO postgres;

--
-- Name: tenant_smtp_test_actor(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_test_actor(p_actor uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid;
BEGIN
 IF p_actor IS NULL OR public.is_platform_superadmin(p_actor) OR public.has_role(p_actor,'administrador') IS DISTINCT FROM true
 OR platform_private.platform_actor_access_ready(p_actor) IS DISTINCT FROM true THEN RETURN NULL; END IF;
 SELECT p.organization_id INTO v_org FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id
 JOIN auth.users u ON u.id=p.user_id WHERE p.user_id=p_actor AND p.ativo IS TRUE AND p.senha_provisoria IS FALSE
 AND o.ativo IS TRUE AND u.email_confirmed_at IS NOT NULL AND u.email IS NOT NULL;
 RETURN v_org;
END $$;


ALTER FUNCTION platform_private.tenant_smtp_test_actor(p_actor uuid) OWNER TO postgres;

--
-- Name: tenant_smtp_test_claim(text, bigint, uuid, boolean); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_test_claim(p_mode text, p_version bigint, p_key uuid, p_confirm boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; r platform_private.tenant_smtp_test_receipts; s public.communication_tenant_email_settings;
 v_id uuid:=gen_random_uuid(); v_out uuid:=gen_random_uuid(); v_event uuid:=gen_random_uuid(); v_fence uuid:=gen_random_uuid(); v_key text;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_mode IS NULL OR p_mode NOT IN ('connection','send') OR p_version IS NULL OR p_version<1 OR p_version>9007199254740991 OR p_key IS NULL
 OR (p_mode='send' AND p_confirm IS DISTINCT FROM true) THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 IF platform_private.tenant_email_actor_org() IS DISTINCT FROM v_org OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE approved AND id)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR NOT s.credential_configured THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid() AND request_key=p_key;
 IF FOUND THEN
  IF r.version<>p_version OR r.mode<>p_mode THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
  RETURN jsonb_build_object('replay',true,'code',coalesce(r.code,'SMTP_BUSY'),'version',r.version,'mode',r.mode,'dispatch_enabled',false,'sender_verified',false);
 END IF;
 -- Any abandoned/uncertain send blocks ALL future sends, even after version rotation.
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND
 (state<>'complete' OR (p_mode='send' AND mode='send' AND code='smtp_send_ambiguous'))) THEN RAISE EXCEPTION 'SMTP_BUSY' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND created_at>clock_timestamp()-interval '60 seconds') THEN RAISE EXCEPTION 'SMTP_COOLDOWN' USING ERRCODE='40001'; END IF;
 IF p_mode='send' AND NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=auth.uid()
 AND version=p_version AND mode='connection' AND code='smtp_connection_ok' AND state='complete' AND completed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 v_key:='tenant-smtp:'||v_org||':'||auth.uid()||':'||p_key;
 INSERT INTO public.comunicacao_eventos(id,event_key,source_type,source_id,created_by,idempotency_key,status,processed_at,payload)
 VALUES(v_event,'tenant.smtp.diagnostic','tenant_smtp_diagnostic_v1',v_org,auth.uid(),v_key,'processed',clock_timestamp(),'{}');
 INSERT INTO platform_private.tenant_smtp_test_insert_tickets VALUES(v_out,txid_current(),auth.uid(),v_org);
 INSERT INTO public.comunicacao_outbox(id,event_id,template_chave,template_versao,template_snapshot,canal,recipient_user_id,status,attempts,max_attempts,locked_by,lease_expires_at,idempotency_key)
 VALUES(v_out,v_event,'tenant_smtp_diagnostic_v1',1,'{}','email',auth.uid(),'processing',1,1,'tenant-smtp-test',NULL,v_key);
 IF NOT EXISTS(SELECT 1 FROM public.comunicacao_outbox WHERE id=v_out) THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE'; END IF;
 DELETE FROM platform_private.tenant_smtp_test_insert_tickets WHERE outbox_id=v_out;
 INSERT INTO platform_private.tenant_smtp_test_receipts(id,organization_id,actor_id,version,actor_iat,mode,request_key,fence,outbox_id,state)
 VALUES(v_id,v_org,auth.uid(),p_version,coalesce((auth.jwt()->>'iat')::bigint,0),p_mode,p_key,v_fence,v_out,'claimed');
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,auth.uid(),p_version,'smtp_test_'||p_mode||'_claimed');
 RETURN jsonb_build_object('replay',false,'job_id',v_id,'fence',v_fence);
END $$;


ALTER FUNCTION platform_private.tenant_smtp_test_claim(p_mode text, p_version bigint, p_key uuid, p_confirm boolean) OWNER TO postgres;

--
-- Name: tenant_smtp_test_context(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.tenant_smtp_test_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_version bigint;
BEGIN
 v_org:=platform_private.tenant_email_actor_org();
 IF v_org IS NULL OR platform_private.tenant_smtp_test_actor(auth.uid()) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT version INTO v_version FROM public.communication_tenant_email_settings WHERE organization_id=v_org;
 RETURN jsonb_build_object('actor',auth.uid(),'organization',v_org,'version',v_version);
END $$;


ALTER FUNCTION platform_private.tenant_smtp_test_context() OWNER TO postgres;

--
-- Name: transition_subscription_core(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.transition_subscription_core(_organization_id uuid, _action text, _reason text, _correlation_id uuid, _plan_version_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_sub public.organization_subscriptions%ROWTYPE;
  v_version public.saas_plan_versions%ROWTYPE;
  v_now timestamptz := now();
  v_target public.saas_subscription_status;
  v_existing uuid;
  v_existing_org uuid;
  v_existing_action text;
  v_existing_reason text;
  v_existing_version text;
BEGIN
  -- (1) Ator: papel superadmin (modelo live) + perfil real ativo.
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = auth.uid() AND p.ativo IS TRUE AND p.senha_provisoria IS NOT TRUE) THEN
    RAISE EXCEPTION 'platform_forbidden: perfil do ator inativo' USING ERRCODE='42501';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 OR _correlation_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023';
  END IF;
  IF _action IS NULL OR _action NOT IN ('start_trial','change_plan','mark_past_due','suspend','reactivate_manual','cancel','expire_trial','activate_subscription') THEN
    RAISE EXCEPTION 'platform_invalid: ação inválida' USING ERRCODE='22023';
  END IF;

  -- (5) Contrato de payload por ação, validado ANTES de qualquer replay.
  IF _action = 'activate_subscription' AND _plan_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: regularização não aceita versão; use Alterar plano separadamente' USING ERRCODE='22023';
  END IF;
  IF _action IN ('change_plan','start_trial') AND _plan_version_id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: versão obrigatória' USING ERRCODE='22023';
  END IF;
  IF _action <> 'change_plan' AND _action <> 'start_trial' AND _plan_version_id IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: versão só é aceita em change_plan/start_trial' USING ERRCODE='22023';
  END IF;

  -- (3) Lock da ORGANIZAÇÃO antes de seleção e de qualquer replay:
  -- serializa transições concorrentes da mesma empresa.
  PERFORM 1 FROM public.organizations o WHERE o.id = _organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023';
  END IF;

  v_now := clock_timestamp();

  -- Idempotência vinculada: mesma correlação só é reutilizada com MESMA
  -- organização, ação, motivo e versão coerente com a ação.
  SELECT h.subscription_id, h.organization_id, h.action, h.reason,
         h.new_values->>'plan_version_id'
  INTO v_existing, v_existing_org, v_existing_action, v_existing_reason, v_existing_version
  FROM public.organization_subscription_history h
  WHERE h.correlation_id = _correlation_id;
  IF v_existing IS NOT NULL THEN
    IF v_existing_org IS DISTINCT FROM _organization_id
       OR v_existing_action IS DISTINCT FROM _action
       OR v_existing_reason IS DISTINCT FROM btrim(_reason)
       OR (_plan_version_id IS NOT NULL
           AND nullif(v_existing_version, '')::uuid IS DISTINCT FROM _plan_version_id)
       OR (_plan_version_id IS NULL AND v_existing_action = 'change_plan') THEN
      RAISE EXCEPTION 'platform_conflict: correlação já utilizada em outra operação' USING ERRCODE='PT409';
    END IF;
    RETURN v_existing;
  END IF;

  -- (3) Corrente primeiro; EXPIRED só como fallback e somente para activate.
  SELECT * INTO v_sub
  FROM public.organization_subscriptions s
  WHERE s.organization_id = _organization_id
    AND s.status IN ('TRIAL','ACTIVE','PAST_DUE','SUSPENDED')
  ORDER BY s.started_at DESC, s.created_at DESC, s.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_sub.id IS NULL AND _action = 'activate_subscription' THEN
    -- Fallback EXPIRED: somente a assinatura MAIS RECENTE da empresa, e só
    -- se a origem TRIAL→EXPIRED estiver comprovada no histórico. Uma
    -- CANCELLED (ou qualquer outra) mais nova bloqueia a ressurreição.
    SELECT * INTO v_sub
    FROM public.organization_subscriptions s
    WHERE s.organization_id = _organization_id
    ORDER BY s.started_at DESC, s.created_at DESC, s.id DESC
    LIMIT 1
    FOR UPDATE;
    IF v_sub.id IS NOT NULL AND (
      v_sub.status <> 'EXPIRED'
      OR NOT EXISTS (
        SELECT 1 FROM public.organization_subscription_history h
        WHERE h.subscription_id = v_sub.id
          AND h.previous_status = 'TRIAL' AND h.new_status = 'EXPIRED'
      )
    ) THEN
      RAISE EXCEPTION 'platform_conflict: assinatura expirada sem origem em trial comprovada' USING ERRCODE='PT409';
    END IF;
  END IF;

  IF _plan_version_id IS NOT NULL THEN
    SELECT * INTO v_version
    FROM public.saas_plan_versions v
    WHERE v.id = _plan_version_id
      AND v.status = 'PUBLISHED'
      AND v.effective_from <= v_now
      AND (v.effective_to IS NULL OR v.effective_to > v_now)
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_invalid: versão inexistente, não publicada ou fora de vigência' USING ERRCODE='22023';
    END IF;
  END IF;

  IF _action = 'start_trial' THEN
    IF v_sub.id IS NOT NULL OR _plan_version_id IS NULL THEN
      RAISE EXCEPTION 'platform_conflict: trial exige empresa sem assinatura corrente e versão vigente' USING ERRCODE='PT409';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM public.organization_subscriptions s
      WHERE s.organization_id = _organization_id
        AND (
          s.status = 'TRIAL'
          OR EXISTS (
            SELECT 1 FROM public.organization_subscription_history h
            WHERE h.subscription_id = s.id
              AND (h.action = 'start_trial' OR h.new_status = 'TRIAL')
          )
        )
    ) THEN
      RAISE EXCEPTION 'platform_conflict: trial já utilizado' USING ERRCODE='PT409';
    END IF;

    PERFORM platform_private.issue_ticket('saas_subscription_write', _organization_id);
    PERFORM set_config('app.saas_change_reason', btrim(_reason), true);
    PERFORM set_config('app.saas_change_action', _action, true);
    PERFORM set_config('app.saas_correlation_id', _correlation_id::text, true);

    INSERT INTO public.organization_subscriptions(
      organization_id,plan_id,plan_version_id,status,started_at,trial_ends_at,
      price_snapshot,currency_snapshot,billing_cycle,billing_cycle_snapshot,
      limits_snapshot,features_snapshot,state_changed_at,last_correlation_id,created_by
    )
    VALUES(
      _organization_id,v_version.plan_id,v_version.id,'TRIAL',v_now,
      v_now + interval '14 days',v_version.price_amount,v_version.currency,
      v_version.billing_cycle,v_version.billing_cycle,v_version.limits_snapshot,
      v_version.features_snapshot,v_now,_correlation_id,auth.uid()
    )
    RETURNING * INTO v_sub;
    RETURN v_sub.id;
  END IF;

  IF v_sub.id IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: assinatura corrente inexistente' USING ERRCODE='22023';
  END IF;

  -- Assinatura legada (sem versão) só sai desse estado por change_plan.
  IF v_sub.plan_version_id IS NULL AND _action <> 'change_plan' THEN
    RAISE EXCEPTION 'platform_conflict: assinatura legada exige regularização explícita de versão (Alterar plano)' USING ERRCODE='PT409';
  END IF;

  -- (2) activate_subscription: valida a versão ATUAL da assinatura
  -- (publicada e vigente) e a empresa ativa; preserva TODOS os snapshots.
  IF _action = 'activate_subscription' THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = _organization_id AND o.ativo IS TRUE AND o.status = 'ativa') THEN
      RAISE EXCEPTION 'platform_conflict: empresa inativa não pode ser regularizada' USING ERRCODE='PT409';
    END IF;
    IF v_sub.status NOT IN ('TRIAL','EXPIRED') THEN
      RAISE EXCEPTION 'platform_conflict: transição inválida' USING ERRCODE='PT409';
    END IF;
    -- (4) cancelamento agendado bloqueia a regularização nesta fase.
    IF v_sub.cancel_at IS NOT NULL THEN
      RAISE EXCEPTION 'platform_conflict: assinatura com cancelamento agendado; cancele a agenda antes de regularizar' USING ERRCODE='PT409';
    END IF;
    SELECT * INTO v_version
    FROM public.saas_plan_versions v
    WHERE v.id = v_sub.plan_version_id
      AND v.status = 'PUBLISHED'
      AND v.effective_from <= v_now
      AND (v.effective_to IS NULL OR v.effective_to > v_now)
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_invalid: versão atual da assinatura não está publicada e vigente' USING ERRCODE='22023';
    END IF;
  END IF;

  IF (_action='mark_past_due' AND v_sub.status<>'ACTIVE')
     OR (_action='suspend' AND v_sub.status NOT IN('ACTIVE','PAST_DUE'))
     OR (_action='reactivate_manual' AND v_sub.status<>'SUSPENDED')
     OR (_action='cancel' AND v_sub.status NOT IN('TRIAL','ACTIVE','PAST_DUE','SUSPENDED'))
     OR (_action='expire_trial' AND (v_sub.status<>'TRIAL' OR v_sub.trial_ends_at IS NULL OR v_sub.trial_ends_at>v_now)) THEN
    RAISE EXCEPTION 'platform_conflict: transição inválida' USING ERRCODE='PT409';
  END IF;

  v_target := CASE _action
    WHEN 'mark_past_due' THEN 'PAST_DUE'::public.saas_subscription_status
    WHEN 'suspend' THEN 'SUSPENDED'::public.saas_subscription_status
    WHEN 'reactivate_manual' THEN 'ACTIVE'::public.saas_subscription_status
    WHEN 'cancel' THEN 'CANCELLED'::public.saas_subscription_status
    WHEN 'expire_trial' THEN 'EXPIRED'::public.saas_subscription_status
    WHEN 'activate_subscription' THEN 'ACTIVE'::public.saas_subscription_status
    ELSE v_sub.status
  END;

  PERFORM platform_private.issue_ticket('saas_subscription_write', _organization_id);
  PERFORM set_config('app.saas_change_reason', btrim(_reason), true);
  PERFORM set_config('app.saas_change_action', _action, true);
  PERFORM set_config('app.saas_correlation_id', _correlation_id::text, true);

  -- (4) activate_subscription NÃO toca current_period_start/end nem
  -- snapshots: conversão administrativa sem cobrança/expiração nova.
  UPDATE public.organization_subscriptions s
  SET plan_id = CASE WHEN _action='change_plan' THEN v_version.plan_id ELSE s.plan_id END,
      plan_version_id = CASE WHEN _action='change_plan' THEN v_version.id ELSE s.plan_version_id END,
      status = v_target,
      price_snapshot = CASE WHEN _action='change_plan' THEN v_version.price_amount ELSE s.price_snapshot END,
      currency_snapshot = CASE WHEN _action='change_plan' THEN v_version.currency ELSE s.currency_snapshot END,
      billing_cycle = CASE WHEN _action='change_plan' THEN v_version.billing_cycle ELSE s.billing_cycle END,
      billing_cycle_snapshot = CASE WHEN _action='change_plan' THEN v_version.billing_cycle ELSE s.billing_cycle_snapshot END,
      limits_snapshot = CASE WHEN _action='change_plan' THEN v_version.limits_snapshot ELSE s.limits_snapshot END,
      features_snapshot = CASE WHEN _action='change_plan' THEN v_version.features_snapshot ELSE s.features_snapshot END,
      suspended_at = CASE WHEN v_target='SUSPENDED' THEN coalesce(s.suspended_at,v_now) ELSE NULL END,
      cancelled_at = CASE WHEN v_target='CANCELLED' THEN coalesce(s.cancelled_at,v_now) ELSE NULL END,
      state_changed_at = v_now,
      last_correlation_id = _correlation_id
  WHERE s.id = v_sub.id;

  RETURN v_sub.id;
END;
$$;


ALTER FUNCTION platform_private.transition_subscription_core(_organization_id uuid, _action text, _reason text, _correlation_id uuid, _plan_version_id uuid) OWNER TO postgres;

--
-- Name: trg_lab_lot_biological_only(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.trg_lab_lot_biological_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.produto_id IS NOT DISTINCT FROM OLD.produto_id
                    AND NEW.microrganismo_id IS NOT DISTINCT FROM OLD.microrganismo_id THEN RETURN NEW; END IF;
  PERFORM platform_private.lab_assert_manufacturable(NEW.produto_id,NEW.microrganismo_id);
  RETURN NEW;
END $$;


