--
-- Name: update_org_admin_core(uuid, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.update_org_admin_core(_invite_id uuid, _nome text, _telefone text, _cpf text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE j public.platform_org_admin_invites%ROWTYPE; a public.platform_org_admin_audit%ROWTYPE;
  v_motivo text; v_nome text; v_tel text; v_cpf text; v_old jsonb; v_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL OR _invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros obrigatórios' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF char_length(v_motivo) = 1 THEN RAISE EXCEPTION 'platform_invalid: se informar o motivo, use ao menos 2 caracteres' USING ERRCODE='22023'; END IF;
  v_nome := regexp_replace(btrim(coalesce(_nome,'')), '\s+', ' ', 'g');
  v_tel := nullif(regexp_replace(coalesce(_telefone,''),'\D','','g'),'');
  v_cpf := nullif(regexp_replace(coalesce(_cpf,''),'\D','','g'),'');
  IF char_length(v_nome) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'platform_invalid: nome inválido' USING ERRCODE='22023'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone inválido' USING ERRCODE='22023'; END IF;
  IF v_cpf IS NOT NULL AND (length(v_cpf)<>11 OR v_cpf ~ '^(\d)\1{10}$') THEN RAISE EXCEPTION 'platform_invalid: CPF inválido' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.platform_org_admin_audit WHERE action='admin_profile_updated' AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.invite_id=_invite_id AND a.reason=v_motivo AND a.new_values->>'nome' IS NOT DISTINCT FROM v_nome
       AND a.new_values->>'telefone' IS NOT DISTINCT FROM v_tel AND a.new_values->>'cpf_cnpj' IS NOT DISTINCT FROM v_cpf THEN
      RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',true); END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp()) THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF _expected_updated_at IS NULL OR j.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'platform_conflict: o administrador foi alterado por outra pessoa; recarregue antes de salvar' USING ERRCODE='40001'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN
    RAISE EXCEPTION 'platform_forbidden: acesso de plataforma não é editável aqui' USING ERRCODE='42501'; END IF;
  IF v_cpf IS DISTINCT FROM j.cpf_cnpj AND j.status='ativo' AND j.cpf_cnpj IS NOT NULL THEN
    RAISE EXCEPTION 'platform_invalid: correção de CPF de administrador ativo exige fluxo específico' USING ERRCODE='22023'; END IF;
  IF (v_nome, v_tel, v_cpf) IS NOT DISTINCT FROM (j.nome, j.telefone, j.cpf_cnpj) THEN
    RAISE EXCEPTION 'platform_invalid: nenhuma alteração para salvar' USING ERRCODE='22023'; END IF;

  v_old := jsonb_build_object('nome',j.nome,'telefone',j.telefone,'cpf_cnpj',j.cpf_cnpj);
  UPDATE public.platform_org_admin_invites SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf,
         updated_at=greatest(clock_timestamp(), j.updated_at + interval '1 microsecond')
   WHERE id=_invite_id RETURNING * INTO j;
  IF j.user_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id IS DISTINCT FROM j.organization_id) THEN
      RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
    UPDATE public.profiles SET nome=v_nome, telefone=v_tel, cpf_cnpj=v_cpf
     WHERE user_id=j.user_id AND organization_id=j.organization_id;
  END IF;
  v_new := jsonb_build_object('nome',v_nome,'telefone',v_tel,'cpf_cnpj',v_cpf);
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,_invite_id,auth.uid(),'admin_profile_updated','succeeded',v_motivo,'platform_rpc',_idempotency_key,v_old,v_new);
  RETURN jsonb_build_object('invite_id',_invite_id,'updated_at',j.updated_at,'idempotent',false);
END $_$;


ALTER FUNCTION platform_private.update_org_admin_core(_invite_id uuid, _nome text, _telefone text, _cpf text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid) OWNER TO postgres;

--
-- Name: update_organization_profile_core(uuid, text, text, text, text, timestamp with time zone, uuid, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.update_organization_profile_core(_org uuid, _razao_social text, _nome_fantasia text, _email text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid, _dados jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  o public.organizations%ROWTYPE; a public.organization_profile_audit%ROWTYPE;
  v_razao text; v_fant text; v_email text; v_motivo text; v_old jsonb; v_new jsonb;
  v_patch jsonb; v_dold jsonb; v_dnew jsonb; v_fuso text; k text; v text;
  v_chg_old jsonb := '{}'::jsonb; v_chg_new jsonb := '{}'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _idempotency_key IS NULL THEN RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023'; END IF;
  v_motivo := btrim(coalesce(_motivo,''));
  IF char_length(v_motivo) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo obrigatório (mínimo 2 caracteres)' USING ERRCODE='22023'; END IF;
  v_razao := regexp_replace(btrim(coalesce(_razao_social,'')), '\s+', ' ', 'g');
  v_fant  := nullif(regexp_replace(btrim(coalesce(_nome_fantasia,'')), '\s+', ' ', 'g'), '');
  v_email := lower(btrim(coalesce(_email,'')));
  IF char_length(v_razao) < 2 OR char_length(v_razao) > 200 THEN RAISE EXCEPTION 'platform_invalid: razão social inválida' USING ERRCODE='22023'; END IF;
  IF v_fant IS NOT NULL AND char_length(v_fant) > 200 THEN RAISE EXCEPTION 'platform_invalid: nome fantasia inválido' USING ERRCODE='22023'; END IF;
  IF v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR char_length(v_email) > 254 THEN RAISE EXCEPTION 'platform_invalid: e-mail inválido' USING ERRCODE='22023'; END IF;
  BEGIN
    v_patch := platform_private.org_cadastro_patch(_dados);
  EXCEPTION WHEN raise_exception THEN
    RAISE EXCEPTION 'platform_invalid: %', replace(SQLERRM,'org_invalid: ','') USING ERRCODE='22023';
  END;

  SELECT * INTO o FROM public.organizations WHERE id=_org FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: empresa inexistente' USING ERRCODE='22023'; END IF;

  SELECT * INTO a FROM public.organization_profile_audit WHERE idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF a.organization_id=_org AND a.reason=v_motivo
       AND a.new_values->>'razao_social' IS NOT DISTINCT FROM v_razao
       AND a.new_values->>'nome_fantasia' IS NOT DISTINCT FROM v_fant
       AND a.new_values->>'email_corporativo' IS NOT DISTINCT FROM v_email
       AND coalesce(a.new_values->'dados_patch','{}'::jsonb) = v_patch THEN
      RETURN jsonb_build_object('organization_id',_org,'updated_at',o.updated_at,'idempotent',true);
    END IF;
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001';
  END IF;

  IF _expected_updated_at IS NULL OR o.updated_at IS DISTINCT FROM _expected_updated_at THEN
    RAISE EXCEPTION 'platform_conflict: a empresa foi alterada por outra pessoa; recarregue antes de salvar' USING ERRCODE='40001';
  END IF;

  -- Merge seguro: preserva chaves não enviadas/desconhecidas; '' remove só a chave enviada.
  v_dold := coalesce(o.onboarding_dados,'{}'::jsonb);
  v_dnew := v_dold;
  FOR k, v IN SELECT key, value #>> '{}' FROM jsonb_each(v_patch) LOOP
    IF v = '' THEN v_dnew := v_dnew - k; ELSE v_dnew := v_dnew || jsonb_build_object(k, v); END IF;
    IF (v_dold->>k) IS DISTINCT FROM (v_dnew->>k) THEN
      v_chg_old := v_chg_old || jsonb_build_object(k, v_dold->k);
      v_chg_new := v_chg_new || jsonb_build_object(k, v_dnew->k);
    END IF;
  END LOOP;
  v_fuso := CASE WHEN v_patch ? 'fuso_horario' THEN nullif(v_patch->>'fuso_horario','') ELSE o.fuso_horario END;

  IF o.razao_social IS NOT DISTINCT FROM v_razao AND o.nome IS NOT DISTINCT FROM v_razao
     AND o.nome_fantasia IS NOT DISTINCT FROM v_fant AND o.email_corporativo IS NOT DISTINCT FROM v_email
     AND v_chg_new = '{}'::jsonb AND o.fuso_horario IS NOT DISTINCT FROM v_fuso THEN
    RAISE EXCEPTION 'platform_invalid: nenhuma alteração para salvar' USING ERRCODE='22023';
  END IF;

  v_old := jsonb_build_object('razao_social',o.razao_social,'nome',o.nome,'nome_fantasia',o.nome_fantasia,'email_corporativo',o.email_corporativo,'fuso_horario',o.fuso_horario,'dados',v_chg_old,'updated_at',o.updated_at);
  PERFORM platform_private.issue_ticket('org_write', _org);
  UPDATE public.organizations SET razao_social=v_razao, nome=v_razao, nome_fantasia=v_fant,
    email_corporativo=v_email, fuso_horario=v_fuso, onboarding_dados=v_dnew, updated_at=now()
   WHERE id=_org RETURNING * INTO o;
  v_new := jsonb_build_object('razao_social',o.razao_social,'nome',o.nome,'nome_fantasia',o.nome_fantasia,'email_corporativo',o.email_corporativo,'fuso_horario',o.fuso_horario,'dados',v_chg_new,'dados_patch',v_patch,'updated_at',o.updated_at);
  INSERT INTO public.organization_profile_audit(organization_id,actor_user_id,origin,reason,idempotency_key,old_values,new_values)
  VALUES (_org, auth.uid(), 'platform_rpc', v_motivo, _idempotency_key, v_old, v_new);
  RETURN jsonb_build_object('organization_id',_org,'updated_at',o.updated_at,'idempotent',false);
END $_$;


ALTER FUNCTION platform_private.update_organization_profile_core(_org uuid, _razao_social text, _nome_fantasia text, _email text, _motivo text, _expected_updated_at timestamp with time zone, _idempotency_key uuid, _dados jsonb) OWNER TO postgres;

--
-- Name: user_edit_f2_authorize(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.user_edit_f2_authorize(p_target uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid;
BEGIN
 IF auth.uid() IS NULL OR platform_private.platform_actor_access_ready(auth.uid()) IS NOT TRUE
 OR NOT public.has_role(auth.uid(),'administrador') OR public.is_platform_superadmin(auth.uid())
 OR public.is_platform_superadmin(p_target) THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 SELECT organization_id INTO org FROM public.profiles WHERE user_id=auth.uid() AND ativo IS TRUE;
 IF org IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=p_target AND organization_id=org)
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org AND ativo IS TRUE AND status='ativa' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 RETURN org;
END $$;


ALTER FUNCTION platform_private.user_edit_f2_authorize(p_target uuid) OWNER TO postgres;

--
-- Name: user_edit_f2_common(uuid, timestamp with time zone, jsonb, public.app_role[], uuid[], uuid, uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.user_edit_f2_common(p_user uuid, p_stamp timestamp with time zone, p_profile jsonb, p_roles public.app_role[], p_clients uuid[], p_primary uuid, p_partner uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE org uuid; envelope jsonb:=p_profile->'_external_edit'; common jsonb:=p_profile-'_external_edit';
 current_roles public.app_role[]; before_version text; after_version text; req_hash text; receipt record;
 key uuid; reason text; stamp timestamptz; old_common jsonb; new_common jsonb; result jsonb; k text;
BEGIN
 -- Reject unauthorized callers before any global or target row lock.
 -- Repeat full authorization after locks to close concurrent permission changes.
 IF auth.uid() IS NULL
 OR platform_private.platform_actor_access_ready(auth.uid()) IS NOT TRUE
 OR platform_private.is_tenant_admin_for_user(p_user) IS NOT TRUE
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed)
 THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 -- Lock order shared with ALL existing identity/link DML (statement trigger).
 -- NOWAIT prevents reverse-order legacy writers from causing a deadlock; retry is explicit.
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_guard_unavailable' USING ERRCODE='PT503'; END IF;
 PERFORM 1 FROM platform_private.user_edit_f2_gate WHERE singleton AND reviewed FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_phase_closed' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id FOR UPDATE;
 org:=platform_private.user_edit_f2_authorize(p_user);
 PERFORM 1 FROM public.user_roles WHERE user_id IN (auth.uid(),p_user) ORDER BY user_id,id FOR UPDATE;
 PERFORM 1 FROM public.user_clientes WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.partner_users WHERE user_id=p_user ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.clientes WHERE id IN (SELECT cliente_id FROM public.user_clientes WHERE user_id=p_user) ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.partner_accounts WHERE id IN (SELECT partner_id FROM public.partner_users WHERE user_id=p_user) ORDER BY id FOR SHARE;
 SELECT array_agg(role ORDER BY role::text) INTO current_roles FROM public.user_roles WHERE user_id=p_user;
 IF current_roles IS NULL OR cardinality(current_roles)<>1 OR current_roles[1] NOT IN ('cliente_produtor','parceiro_b2b')
 OR p_roles IS DISTINCT FROM current_roles THEN RAISE EXCEPTION 'user_edit_linked_role_unavailable' USING ERRCODE='42501'; END IF;
 IF cardinality(coalesce(p_clients,'{}'::uuid[]))<>0 OR p_primary IS NOT NULL OR p_partner IS NOT NULL THEN
  RAISE EXCEPTION 'user_edit_unscoped_links_forbidden' USING ERRCODE='42501'; END IF;
 -- Common-only path may preserve inactive/revoked links, but never adopt unowned ones.
 IF EXISTS(SELECT 1 FROM public.user_clientes u LEFT JOIN public.clientes c ON c.id=u.cliente_id WHERE u.user_id=p_user AND c.organization_id IS DISTINCT FROM org)
 OR EXISTS(SELECT 1 FROM public.partner_users u LEFT JOIN public.partner_accounts p ON p.id=u.partner_id WHERE u.user_id=p_user AND p.commercial_owner_organization_id IS DISTINCT FROM org)
 THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(envelope) IS DISTINCT FROM 'object' OR envelope->>'mode' IS DISTINCT FROM 'common_preserve_links'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(envelope) x WHERE x NOT IN ('mode','expected_version','idempotency_key','reason'))
 OR jsonb_typeof(envelope->'expected_version') IS DISTINCT FROM 'string' OR (envelope->>'expected_version') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(envelope->'idempotency_key') IS DISTINCT FROM 'string' OR (envelope->>'idempotency_key') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
 OR jsonb_typeof(envelope->'reason') IS DISTINCT FROM 'string' OR char_length(btrim(envelope->>'reason')) NOT BETWEEN 2 AND 500
 OR p_stamp IS NULL THEN RAISE EXCEPTION 'user_edit_invalid_input' USING ERRCODE='22023'; END IF;
 key:=(envelope->>'idempotency_key')::uuid; reason:=btrim(envelope->>'reason');
 -- Exactly these six payload fields are intentional (not a profiles column count).
 -- Omitting a nullable field must not silently clear it in a whole-form update.
 IF (SELECT count(*) FROM jsonb_object_keys(common))<>6 OR EXISTS(SELECT 1 FROM jsonb_object_keys(common) x WHERE x NOT IN ('nome','telefone','cargo','cpf_cnpj','crea','especialidade')) THEN
 RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 FOR k IN SELECT jsonb_object_keys(common) LOOP
 IF jsonb_typeof(common->k) NOT IN ('string','null') OR char_length(coalesce(common->>k,''))>500 THEN RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF jsonb_typeof(common->'nome') IS DISTINCT FROM 'string' OR char_length(btrim(common->>'nome')) NOT BETWEEN 2 AND 150 THEN RAISE EXCEPTION 'user_edit_invalid_name' USING ERRCODE='22023'; END IF;
 IF nullif(common->>'telefone','') IS NOT NULL AND (common->>'telefone') !~ '^[0-9]{10,11}$' THEN RAISE EXCEPTION 'user_edit_invalid_phone' USING ERRCODE='22023'; END IF;
 req_hash:=encode(extensions.digest(convert_to(jsonb_build_object('target',p_user,'stamp',p_stamp,'profile',p_profile,'roles',p_roles,'clients',p_clients,'primary',p_primary,'partner',p_partner)::text,'UTF8'),'sha256'),'hex');
 -- Authorization, target type, ownership and gates were revalidated BEFORE replay.
 SELECT * INTO receipt FROM platform_private.user_edit_f2_audit WHERE actor_id=auth.uid() AND organization_id=org AND idempotency_key=key;
 IF FOUND THEN
  IF receipt.request_hash IS DISTINCT FROM req_hash THEN RAISE EXCEPTION 'user_edit_idempotency_conflict' USING ERRCODE='PT409'; END IF;
  -- A retry after unrelated target changes must not present a stale result as current.
  IF receipt.version_after IS DISTINCT FROM platform_private.user_edit_f2_version(p_user) THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
  RETURN receipt.result || jsonb_build_object('replayed',true);
 END IF;
 before_version:=platform_private.user_edit_f2_version(p_user);
 SELECT updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade)
 INTO stamp,old_common FROM public.profiles WHERE user_id=p_user;
 IF before_version IS DISTINCT FROM envelope->>'expected_version' OR stamp IS DISTINCT FROM p_stamp THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
 UPDATE public.profiles SET nome=btrim(common->>'nome'),telefone=nullif(common->>'telefone',''),cargo=nullif(common->>'cargo',''),cpf_cnpj=nullif(common->>'cpf_cnpj',''),crea=nullif(common->>'crea',''),especialidade=nullif(common->>'especialidade','')
 WHERE user_id=p_user RETURNING updated_at,jsonb_build_object('nome',nome,'telefone',telefone,'cargo',cargo,'cpf_cnpj',cpf_cnpj,'crea',crea,'especialidade',especialidade) INTO stamp,new_common;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 after_version:=platform_private.user_edit_f2_version(p_user);
 result:=jsonb_build_object('success',true,'user_id',p_user,'updated_at',stamp,'version',after_version,'replayed',false,'links_preserved',true);
 INSERT INTO platform_private.user_edit_f2_audit(actor_id,organization_id,target_id,idempotency_key,request_hash,reason,version_before,version_after,old_common,new_common,result)
 VALUES(auth.uid(),org,p_user,key,req_hash,reason,before_version,after_version,old_common,new_common,result);
 RETURN result;
END $_$;


ALTER FUNCTION platform_private.user_edit_f2_common(p_user uuid, p_stamp timestamp with time zone, p_profile jsonb, p_roles public.app_role[], p_clients uuid[], p_primary uuid, p_partner uuid) OWNER TO postgres;

--
-- Name: user_edit_f2_immutable(); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.user_edit_f2_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN RAISE EXCEPTION 'user_edit_audit_immutable' USING ERRCODE='42501'; END $$;


ALTER FUNCTION platform_private.user_edit_f2_immutable() OWNER TO postgres;

--
-- Name: user_edit_f2_version(uuid); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.user_edit_f2_version(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT encode(extensions.digest(convert_to(jsonb_build_object(
  'profile',(SELECT to_jsonb(p) FROM public.profiles p WHERE p.user_id=p_user),
  'roles',COALESCE((SELECT jsonb_agg(to_jsonb(r) ORDER BY r.id) FROM public.user_roles r WHERE r.user_id=p_user),'[]'),
  'clients',COALESCE((SELECT jsonb_agg(jsonb_build_object('link',to_jsonb(u),'vigente',(u.is_active AND u.revoked_at IS NULL AND (u.valid_from IS NULL OR u.valid_from<=now()) AND (u.valid_until IS NULL OR u.valid_until>now())),'client_state',jsonb_build_object('id',c.id,'owner',c.organization_id,'status',c.status_cliente)) ORDER BY u.id)
    FROM public.user_clientes u LEFT JOIN public.clientes c ON c.id=u.cliente_id WHERE u.user_id=p_user),'[]'),
  'partners',COALESCE((SELECT jsonb_agg(jsonb_build_object('link',to_jsonb(u),'partner_state',jsonb_build_object('id',p.id,'owner',p.commercial_owner_organization_id,'active',p.ativo,'deleted',p.deleted_at,'updated_at',p.updated_at)) ORDER BY u.id)
    FROM public.partner_users u LEFT JOIN public.partner_accounts p ON p.id=u.partner_id WHERE u.user_id=p_user),'[]')
 )::text,'UTF8'),'sha256'),'hex');
$$;


ALTER FUNCTION platform_private.user_edit_f2_version(p_user uuid) OWNER TO postgres;

--
-- Name: validate_commercial_plan_payload(uuid, jsonb, jsonb); Type: FUNCTION; Schema: platform_private; Owner: postgres
--

CREATE FUNCTION platform_private.validate_commercial_plan_payload(_plan_id uuid, _limits jsonb, _features jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  _entry record;
  _selected_keys text[];
  _legacy_catalog_cutoff constant timestamptz := '2026-10-06 02:42:42+00'::timestamptz;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.saas_plans p WHERE p.id = _plan_id AND p.active IS TRUE) THEN
    RAISE EXCEPTION 'saas_plan_unavailable' USING ERRCODE = '22023';
  END IF;
  IF _limits IS NULL OR jsonb_typeof(_limits) <> 'object' THEN
    RAISE EXCEPTION 'saas_limits_invalid' USING ERRCODE = '22023';
  END IF;
  IF _features IS NULL OR jsonb_typeof(_features) <> 'array' THEN
    RAISE EXCEPTION 'saas_features_invalid' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_features) item
    WHERE jsonb_typeof(item) <> 'string' OR nullif(btrim(item #>> '{}'), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'saas_feature_key_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(feature_key ORDER BY feature_key), ARRAY[]::text[])
    INTO _selected_keys
  FROM (SELECT DISTINCT jsonb_array_elements_text(_features) AS feature_key) selected;

  IF cardinality(_selected_keys) <> jsonb_array_length(_features) THEN
    RAISE EXCEPTION 'saas_feature_duplicate' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(_selected_keys) feature_key
    LEFT JOIN public.saas_features f ON f.key = feature_key
    LEFT JOIN public.saas_modules m ON m.id = f.module_id
    WHERE f.id IS NULL
       OR f.active IS NOT TRUE
       OR m.id IS NULL
       OR m.active IS NOT TRUE
       OR (f.commercializable IS NOT TRUE AND f.created_at >= _legacy_catalog_cutoff)
  ) THEN
    RAISE EXCEPTION 'saas_feature_unavailable' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.saas_feature_dependencies d
    JOIN public.saas_features f ON f.id = d.feature_id
    JOIN public.saas_features required_f ON required_f.id = d.depends_on_feature_id
    WHERE f.key = ANY(_selected_keys)
      AND NOT (required_f.key = ANY(_selected_keys))
  ) THEN
    RAISE EXCEPTION 'saas_feature_dependency_missing' USING ERRCODE = '22023';
  END IF;

  FOR _entry IN SELECT key, value FROM jsonb_each(_limits)
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM public.saas_limit_definitions ld
      JOIN public.saas_feature_limit_definitions fld ON fld.limit_definition_id = ld.id
      JOIN public.saas_features f ON f.id = fld.feature_id
      WHERE ld.key = _entry.key
        AND ld.active IS TRUE
        AND f.key = ANY(_selected_keys)
    ) THEN
      RAISE EXCEPTION 'saas_limit_unknown' USING ERRCODE = '22023';
    END IF;

    IF jsonb_typeof(_entry.value) <> 'object'
       OR NOT (_entry.value ? 'state')
       OR (_entry.value - 'state' - 'value') <> '{}'::jsonb
       OR (_entry.value->>'state') NOT IN ('not_included', 'limited', 'unlimited') THEN
      RAISE EXCEPTION 'saas_limit_state_invalid' USING ERRCODE = '22023';
    END IF;

    IF (_entry.value->>'state') = 'limited' THEN
      IF NOT (_entry.value ? 'value')
         OR jsonb_typeof(_entry.value->'value') <> 'number'
         OR ((_entry.value->>'value')::numeric < 0) THEN
        RAISE EXCEPTION 'saas_limit_value_invalid' USING ERRCODE = '22023';
      END IF;
      IF EXISTS (
        SELECT 1 FROM public.saas_limit_definitions ld
        WHERE ld.key = _entry.key
          AND ld.value_type = 'integer'
          AND trunc((_entry.value->>'value')::numeric) <> ((_entry.value->>'value')::numeric)
      ) THEN
        RAISE EXCEPTION 'saas_limit_value_type_invalid' USING ERRCODE = '22023';
      END IF;
    ELSIF _entry.value ? 'value' THEN
      RAISE EXCEPTION 'saas_limit_value_unexpected' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM public.saas_feature_limit_definitions fld
    JOIN public.saas_limit_definitions ld ON ld.id = fld.limit_definition_id
    JOIN public.saas_features f ON f.id = fld.feature_id
    WHERE fld.required IS TRUE
      AND ld.active IS TRUE
      AND f.key = ANY(_selected_keys)
      AND (NOT (_limits ? ld.key) OR _limits->ld.key->>'state' = 'not_included')
  ) THEN
    RAISE EXCEPTION 'saas_required_limit_missing' USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION platform_private.validate_commercial_plan_payload(_plan_id uuid, _limits jsonb, _features jsonb) OWNER TO postgres;

--
-- Name: assert_os_approval_scope(uuid, text); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.assert_os_approval_scope(p_os_id uuid, p_origin text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_os record; v_pp public.programacao_producao%ROWTYPE;
BEGIN
 v_org:=platform_private.h15_actor_organization();
 -- Alçada antes de lookup/status/replay. NULL não é permissão.
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')) IS NOT TRUE
 OR p_os_id IS NULL OR p_origin NOT IN ('manual','onfarm') OR p_origin IS NULL THEN
 RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=p_origin) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Mesmo ordenamento do caminho direto: lock da OS antes dos filhos, sem advisory invertido.
 IF p_origin='manual' THEN
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.origem,o.partner_order_id,o.partner_order_item_id INTO v_os FROM public.ordens_servico o WHERE id=p_os_id FOR UPDATE;
 ELSE
 SELECT NULL::uuid organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,'onfarm'::text origem,NULL::uuid partner_order_id,NULL::uuid partner_order_item_id INTO v_os FROM public.ordens_servico_onfarm o WHERE id=p_os_id FOR UPDATE;
 END IF;
 IF v_os.id IS NULL OR (p_origin='manual' AND v_os.organization_id IS DISTINCT FROM v_org) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid OR id IN (SELECT responsavel_id FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id) ORDER BY user_id FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR SHARE;
 -- Lock existing role rows; canonical has_role remains authority, never client claims.
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 IF platform_private.h15_actor_organization() IS DISTINCT FROM v_org OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os=p_origin) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Efeitos comerciais/planejamento ainda não homologados: não autorizar por alias.
 IF v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id)
 OR platform_private.lab_item_is_manufacturable(v_os.produto_id,v_os.microrganismo_id) IS NOT TRUE THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 -- Aprovação não cria programação nem inventa data. Ausência exige revisão do fluxo atual.
 IF (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id)<>1 THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_pp.organization_id IS DISTINCT FROM v_org OR v_pp.status::text IS DISTINCT FROM 'aguardando'
 OR v_pp.produto_id IS DISTINCT FROM v_os.produto_id OR v_pp.microrganismo_id IS DISTINCT FROM v_os.microrganismo_id
 OR NOT (((p_origin='manual' AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL)
 OR (p_origin='onfarm' AND v_pp.ordem_servico_onfarm_id=p_os_id AND v_pp.ordem_servico_id IS NULL)) IS TRUE)
 OR (v_pp.responsavel_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles pr WHERE pr.id=v_pp.responsavel_id AND pr.organization_id=v_org AND pr.ativo IS TRUE))
 OR EXISTS(SELECT 1 FROM public.lotes WHERE programacao_id=v_pp.id) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN v_org;
END $$;


ALTER FUNCTION private.assert_os_approval_scope(p_os_id uuid, p_origin text) OWNER TO postgres;

--
-- Name: fn_public_validation_rate_check(uuid); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.fn_public_validation_rate_check(p_token uuid) RETURNS TABLE(allowed boolean, retry_after_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_pepper       bytea;
  v_headers      jsonb;
  v_origin       text;
  v_now          timestamptz := pg_catalog.clock_timestamp();
  v_allowed      boolean := true;
  v_retry        integer := 0;
  v_retry_scope  integer;
  v_value        text;
  v_bucket       bytea;
  v_ws           timestamptz;
  v_hits         integer;
  r              record;
BEGIN
  SELECT p.pepper INTO v_pepper FROM private.public_validation_rate_pepper p WHERE p.id = 1;
  IF v_pepper IS NULL THEN
    -- fail-closed: sem pepper não há como contabilizar com privacidade.
    RAISE EXCEPTION 'rate_limit_not_initialized' USING ERRCODE = '55000';
  END IF;

  BEGIN
    v_headers := nullif(pg_catalog.current_setting('request.headers', true), '')::jsonb;
  EXCEPTION WHEN others THEN
    v_headers := NULL;
  END;
  v_origin := coalesce(
    nullif(pg_catalog.btrim(pg_catalog.split_part(v_headers->>'cf-connecting-ip', ',', 1)), ''),
    nullif(pg_catalog.btrim(pg_catalog.split_part(v_headers->>'x-forwarded-for', ',', 1)), ''),
    nullif(pg_catalog.btrim(v_headers->>'x-real-ip'), ''),
    'unknown');

  FOR r IN
    SELECT pol.scope, pol.max_hits, pol.window_seconds
      FROM private.public_validation_rate_policy pol
     ORDER BY pol.scope
  LOOP
    v_value := CASE r.scope
                 WHEN 'token'  THEN 'token:'  || coalesce(p_token::text, '')
                 WHEN 'origin' THEN 'origin:' || v_origin
                 ELSE 'global'
               END;
    v_bucket := extensions.hmac(pg_catalog.convert_to(v_value, 'utf8'), v_pepper, 'sha256');
    v_ws := pg_catalog.to_timestamp(
              pg_catalog.floor(extract(epoch FROM v_now) / r.window_seconds) * r.window_seconds);

    INSERT INTO private.public_validation_rate_counters AS c
           (scope, bucket_hash, window_start, hits, first_seen, last_seen)
    VALUES (r.scope, v_bucket, v_ws, 1, v_now, v_now)
    ON CONFLICT (scope, bucket_hash, window_start)
    DO UPDATE SET hits = c.hits + 1, last_seen = v_now
    RETURNING c.hits INTO v_hits;

    IF v_hits > r.max_hits THEN
      v_allowed := false;
      UPDATE private.public_validation_rate_counters c
         SET blocked = c.blocked + 1
       WHERE c.scope = r.scope AND c.bucket_hash = v_bucket AND c.window_start = v_ws;
      v_retry_scope := greatest(1,
        pg_catalog.ceil(extract(epoch FROM
          (v_ws + pg_catalog.make_interval(secs => r.window_seconds) - v_now)))::integer);
      v_retry := greatest(v_retry, v_retry_scope);
    END IF;

    -- housekeeping barato: descarta janelas anteriores do mesmo bucket (limita linhas por bucket).
    DELETE FROM private.public_validation_rate_counters c
     WHERE c.scope = r.scope AND c.bucket_hash = v_bucket AND c.window_start < v_ws;
  END LOOP;

  allowed := v_allowed;
  retry_after_seconds := v_retry;
  RETURN NEXT;
END
$$;


ALTER FUNCTION private.fn_public_validation_rate_check(p_token uuid) OWNER TO postgres;

--
-- Name: fn_public_validation_rate_prune(interval); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.fn_public_validation_rate_prune(p_keep interval DEFAULT '1 day'::interval) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_n integer;
BEGIN
  DELETE FROM private.public_validation_rate_counters c
   WHERE c.window_start < pg_catalog.clock_timestamp() - p_keep;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$$;


ALTER FUNCTION private.fn_public_validation_rate_prune(p_keep interval) OWNER TO postgres;

--
-- Name: guard_os_separate_approval(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.guard_os_separate_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_origin text; v_org uuid;
BEGIN
 IF TG_OP='INSERT' THEN
 -- Criação normal exclusivamente aberta, inclusive pelo serviço/DEFINER.
 -- NULL e qualquer estado avançado não podem saltar a aprovação humana.
 -- Sem whitelist service_role, flags GUC ou reparo de históricos.
 IF NEW.status::text IS DISTINCT FROM 'aberta' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 RETURN NEW;
 END IF;
 IF NEW.status::text IS DISTINCT FROM 'aprovada' THEN RETURN NEW; END IF;
 v_origin:=CASE TG_TABLE_NAME WHEN 'ordens_servico' THEN 'manual' WHEN 'ordens_servico_onfarm' THEN 'onfarm' END;
 IF TG_WHEN='BEFORE' THEN
 -- Um único UPDATE não pode substituir a identidade/referências e aprovar o estado anterior.
 IF (to_jsonb(NEW)-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at']) THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(OLD.id,v_origin);
 RETURN NEW;
 END IF;
 IF OLD.status::text='aberta' THEN
 v_org:=private.assert_os_approval_scope(NEW.id,v_origin);
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,etapa_anterior,etapa_nova,acao,usuario_id,observacao)
 SELECT NEW.id,v_origin,pp.id,'aberta','aprovada','aprovar_os',auth.uid(),jsonb_build_object(
 'organization_id',v_org,'before',jsonb_build_object('status',OLD.status,'volume',OLD.volume_total_ml,'data_os',to_jsonb(OLD)->'data_programada'),
 'after',jsonb_build_object('status',NEW.status,'volume',NEW.volume_total_ml,'data_os',to_jsonb(NEW)->'data_programada'),
 'programacao',jsonb_build_object('id',pp.id,'status',pp.status,'data',pp.data_programada,'volume',pp.volume_necessario),
 'actor',auth.uid(),'at',clock_timestamp(),'manufacturing_started',false,'commercial_completed',false)::text
 FROM public.programacao_producao pp WHERE pp.ordem_servico_id=NEW.id OR pp.ordem_servico_onfarm_id=NEW.id;
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION private.guard_os_separate_approval() OWNER TO postgres;

--
-- Name: h7n_catalogo_ficha_microrganismos(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.h7n_catalogo_ficha_microrganismos() RETURNS TABLE(id uuid, nome text, nome_cientifico text, funcao_agronomica text, ativo boolean, valor_dose_brl numeric, valor_litro_brl numeric, dose_ml_ha numeric, preco_fonte text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.id, m.nome, m.nome_cientifico, m.funcao_agronomica, m.ativo,
    coalesce(public.fn_catalogo_preco_canonico(null::uuid, m.id, 'dose'::text, null::numeric), m.valor_dose_brl),
    coalesce(public.fn_catalogo_preco_canonico(null::uuid, m.id, 'litro'::text, null::numeric), m.valor_litro_brl),
    m.dose_ml_ha,
    case when public.fn_catalogo_preco_canonico(null::uuid, m.id, 'litro'::text, null::numeric) is not null
      then 'catalogo_volumes'::text else 'legado_mestre'::text end
  from public.microrganismos m
  where m.ativo = true
    and (
      public.can_view_catalog_internal(auth.uid())
      or (
        (
          not exists (select 1 from public.microorganism_technical_profiles tp where tp.microrganismo_id = m.id)
          or exists (
            select 1 from public.microorganism_technical_profiles tp
            where tp.microrganismo_id = m.id and tp.status_validacao = 'aprovado'::text
          )
        )
        and (
          not (
            public.has_role(auth.uid(), 'parceiro_b2b'::public.app_role)
            or public.has_role(auth.uid(), 'parceiro_b2b_tecnico'::public.app_role)
          )
          or coalesce(m.b2b_enabled, false) = true
        )
      )
    );
$$;


ALTER FUNCTION private.h7n_catalogo_ficha_microrganismos() OWNER TO postgres;

