CREATE TABLE public.aplicacoes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ordem_servico_id uuid,
    data_aplicacao date DEFAULT CURRENT_DATE NOT NULL,
    responsavel text,
    equipamento text,
    condicoes_climaticas text,
    dose_aplicada numeric,
    observacoes text,
    resultado_inicial text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    hora_inicio timestamp with time zone,
    hora_fim timestamp with time zone,
    modo_aplicacao text,
    volume_calda_l_ha numeric,
    volume_total_aplicado_ml numeric,
    area_aplicada_ha numeric,
    produto_usado_id uuid,
    lote_usado_id uuid,
    responsavel_id uuid,
    equipamento_modelo text,
    bico_tipo text,
    pressao_bar numeric,
    temperatura_c numeric,
    umidade_pct numeric,
    vento_kmh numeric,
    latitude numeric,
    longitude numeric,
    assinatura_responsavel_url text,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    parent_id uuid,
    versao integer DEFAULT 1 NOT NULL,
    is_latest boolean DEFAULT true NOT NULL,
    motivo_retificacao text,
    email_envio text,
    ordem_servico_onfarm_id uuid,
    organization_id uuid,
    CONSTRAINT aplicacoes_textos_controlados_chk CHECK ((((responsavel IS NULL) OR ((char_length(btrim(responsavel)) >= 1) AND (char_length(btrim(responsavel)) <= 200))) AND ((equipamento IS NULL) OR ((char_length(btrim(equipamento)) >= 1) AND (char_length(btrim(equipamento)) <= 200))) AND ((equipamento_modelo IS NULL) OR ((char_length(btrim(equipamento_modelo)) >= 1) AND (char_length(btrim(equipamento_modelo)) <= 200))) AND ((bico_tipo IS NULL) OR ((char_length(btrim(bico_tipo)) >= 1) AND (char_length(btrim(bico_tipo)) <= 100))) AND ((condicoes_climaticas IS NULL) OR ((char_length(btrim(condicoes_climaticas)) >= 1) AND (char_length(btrim(condicoes_climaticas)) <= 1000))) AND ((observacoes IS NULL) OR ((char_length(btrim(observacoes)) >= 1) AND (char_length(btrim(observacoes)) <= 5000))) AND ((resultado_inicial IS NULL) OR (resultado_inicial = ANY (ARRAY['satisfatorio'::text, 'parcial'::text, 'insuficiente'::text, 'em_avaliacao'::text]))))),
    CONSTRAINT aplicacoes_uma_origem_os_chk CHECK ((num_nonnulls(ordem_servico_id, ordem_servico_onfarm_id) = 1)),
    CONSTRAINT aplicacoes_valores_agronomicos_chk CHECK (((dose_aplicada > (0)::numeric) AND (area_aplicada_ha > (0)::numeric) AND ((volume_calda_l_ha IS NULL) OR (volume_calda_l_ha >= (0)::numeric)) AND ((volume_total_aplicado_ml IS NULL) OR (volume_total_aplicado_ml > (0)::numeric)) AND ((pressao_bar IS NULL) OR (pressao_bar >= (0)::numeric)) AND ((temperatura_c IS NULL) OR ((temperatura_c >= ('-50'::integer)::numeric) AND (temperatura_c <= (70)::numeric))) AND ((umidade_pct IS NULL) OR ((umidade_pct >= (0)::numeric) AND (umidade_pct <= (100)::numeric))) AND ((vento_kmh IS NULL) OR ((vento_kmh >= (0)::numeric) AND (vento_kmh <= (250)::numeric))) AND ((latitude IS NULL) OR ((latitude >= ('-90'::integer)::numeric) AND (latitude <= (90)::numeric))) AND ((longitude IS NULL) OR ((longitude >= ('-180'::integer)::numeric) AND (longitude <= (180)::numeric))) AND ((hora_inicio IS NULL) OR (hora_fim IS NULL) OR (hora_fim >= hora_inicio)))),
    CONSTRAINT aplicacoes_versionamento_chk CHECK (((versao >= 1) AND (parent_id IS DISTINCT FROM id) AND (((parent_id IS NULL) AND (versao = 1) AND (motivo_retificacao IS NULL)) OR ((parent_id IS NOT NULL) AND (versao > 1) AND ((char_length(btrim(motivo_retificacao)) >= 5) AND (char_length(btrim(motivo_retificacao)) <= 1000))))))
);


