    pdf_status text,
    origem_atendimento text,
    CONSTRAINT registros_consultor_origem_atendimento_chk CHECK (((origem_atendimento IS NULL) OR (origem_atendimento = ANY (ARRAY['ocorrencia_campo'::text, 'solicitacao_produtor'::text, 'agenda'::text, 'retorno_monitoramento'::text, 'visita_avulsa'::text])))),
    CONSTRAINT registros_consultor_pdf_status_check CHECK (((pdf_status IS NULL) OR (pdf_status = ANY (ARRAY['pending'::text, 'generating'::text, 'generated'::text, 'error'::text]))))
);


