--
-- Name: _src_vw_fluxo_visita_tecnica; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public._src_vw_fluxo_visita_tecnica AS
 WITH cte_checkins AS (
         SELECT visitas_checkin.registro_consultor_id,
            min(visitas_checkin.data_hora_checkin) AS data_checkin,
            count(*) AS total_checkins
           FROM public.visitas_checkin
          GROUP BY visitas_checkin.registro_consultor_id
        ), cte_diagnosticos AS (
         SELECT visita_diagnosticos.registro_id AS registro_consultor_id,
            count(*) AS total_diagnosticos
           FROM public.visita_diagnosticos
          GROUP BY visita_diagnosticos.registro_id
        ), cte_evidencias AS (
         SELECT rca.registro_consultor_id,
            count(*) AS total_evidencias,
            (EXISTS ( SELECT 1
                   FROM public.registros_consultor_arquivos rca2
                  WHERE ((rca2.registro_consultor_id = rca.registro_consultor_id) AND (rca2.arquivo_path IS NULL)))) AS tem_arquivo_sem_path
           FROM public.registros_consultor_arquivos rca
          GROUP BY rca.registro_consultor_id
        ), cte_recomendacoes AS (
         SELECT rcr.registro_consultor_id,
            count(*) AS total_recomendacoes,
            (EXISTS ( SELECT 1
                   FROM public.registros_consultor_recomendacoes rcr2
                  WHERE ((rcr2.registro_consultor_id = rcr.registro_consultor_id) AND ((NULLIF(TRIM(BOTH FROM rcr2.recomendacao_tecnica), ''::text) IS NOT NULL) OR (NULLIF(TRIM(BOTH FROM rcr2.observacoes_finais), ''::text) IS NOT NULL) OR (rcr2.estrategia_manejo IS NOT NULL))))) AS possui_conteudo_real
           FROM public.registros_consultor_recomendacoes rcr
          GROUP BY rcr.registro_consultor_id
        ), cte_os_stats AS (
         SELECT ordens_servico_onfarm.registro_consultor_id,
            count(*) AS total_os_vinculadas
           FROM public.ordens_servico_onfarm
          GROUP BY ordens_servico_onfarm.registro_consultor_id
        ), cte_os_single AS (
         SELECT DISTINCT ON (ordens_servico_onfarm.registro_consultor_id) ordens_servico_onfarm.registro_consultor_id,
            ordens_servico_onfarm.id AS os_id,
            ordens_servico_onfarm.numero_os,
            (ordens_servico_onfarm.status)::text AS status_os,
            ordens_servico_onfarm.created_at AS data_geracao_os,
            ordens_servico_onfarm.microrganismo_id AS os_microrganismo_id
           FROM public.ordens_servico_onfarm
          ORDER BY ordens_servico_onfarm.registro_consultor_id, ordens_servico_onfarm.created_at DESC
        ), cte_logs_datas AS (
         SELECT visitas_logs.registro_consultor_id,
            max(
                CASE
                    WHEN (visitas_logs.acao = 'visita_finalizada'::text) THEN visitas_logs.created_at
                    ELSE NULL::timestamp with time zone
                END) AS data_log_finalizacao,
            max(
                CASE
                    WHEN (visitas_logs.acao = 'recomendacao_liberada'::text) THEN visitas_logs.created_at
                    ELSE NULL::timestamp with time zone
                END) AS data_log_liberacao,
            max(
                CASE
                    WHEN (visitas_logs.acao = 'os_gerada'::text) THEN visitas_logs.created_at
                    ELSE NULL::timestamp with time zone
                END) AS data_log_conversao
           FROM public.visitas_logs
          GROUP BY visitas_logs.registro_consultor_id
        ), cte_status_logs AS (
         SELECT registros_consultor_status_log.registro_consultor_id,
            max(
                CASE
                    WHEN (registros_consultor_status_log.status_novo = 'aprovado'::text) THEN registros_consultor_status_log.changed_at
                    ELSE NULL::timestamp with time zone
                END) AS data_status_aprovado,
            max(
                CASE
                    WHEN (registros_consultor_status_log.status_novo = 'convertido_os'::text) THEN registros_consultor_status_log.changed_at
                    ELSE NULL::timestamp with time zone
                END) AS data_status_convertido
           FROM public.registros_consultor_status_log
          GROUP BY registros_consultor_status_log.registro_consultor_id
        ), cte_aprovacoes AS (
         SELECT DISTINCT ON (aprovacoes_tecnicas.registro_consultor_id) aprovacoes_tecnicas.registro_consultor_id,
            (aprovacoes_tecnicas.status_aprovacao)::text AS status_aprovacao,
            aprovacoes_tecnicas.data_aprovacao
           FROM public.aprovacoes_tecnicas
          ORDER BY aprovacoes_tecnicas.registro_consultor_id, aprovacoes_tecnicas.created_at DESC
        ), base_fluxo AS (
         SELECT
                CASE
                    WHEN (rc_1.id IS NOT NULL) THEN 'visita_com_solicitacao'::text
                    ELSE 'solicitacao_sem_visita'::text
                END AS origem_fluxo,
            ps.id AS solicitacao_id,
            ps.numero_solicitacao,
            rc_1.id AS registro_consultor_id,
            rc_1.codigo_visita,
            ps.cliente_id,
            ps.fazenda_id,
            ps.talhao_id,
            rc_1.cultura_id,
            ps.consultor_atribuido AS consultor_id,
            ps.status AS status_solicitacao,
            (rc_1.status)::text AS status_visita,
            ps.tipo_demanda,
            ps.data_prevista_atendimento,
            ps.created_at AS solicitacao_created_at,
            rc_1.created_at AS visita_created_at,
            rc_1.updated_at AS visita_updated_at
           FROM (public.portal_solicitacoes ps
             LEFT JOIN public.registros_consultor rc_1 ON ((ps.id = rc_1.solicitacao_id)))
        UNION ALL
         SELECT 'visita_avulsa'::text AS origem_fluxo,
            NULL::uuid AS solicitacao_id,
            NULL::text AS numero_solicitacao,
            rc_1.id AS registro_consultor_id,
            rc_1.codigo_visita,
            rc_1.cliente_id,
            rc_1.fazenda_id,
            rc_1.talhao_id,
            rc_1.cultura_id,
            rc_1.consultor_responsavel AS consultor_id,
            NULL::text AS status_solicitacao,
            (rc_1.status)::text AS status_visita,
            NULL::text AS tipo_demanda,
            NULL::timestamp with time zone AS data_prevista_atendimento,
            NULL::timestamp with time zone AS solicitacao_created_at,
            rc_1.created_at AS visita_created_at,
            rc_1.updated_at AS visita_updated_at
           FROM public.registros_consultor rc_1
          WHERE (rc_1.solicitacao_id IS NULL)
        )
 SELECT bf.origem_fluxo,
    bf.solicitacao_id,
    bf.numero_solicitacao,
    bf.registro_consultor_id,
    bf.codigo_visita,
    bf.cliente_id,
    c.nome AS cliente_nome,
    bf.fazenda_id,
    f.nome AS fazenda_nome,
    bf.talhao_id,
    t.nome AS talhao_nome,
    bf.cultura_id,
    cult.nome AS cultura_nome,
    bf.consultor_id,
    u.nome AS consultor_nome,
    bf.status_solicitacao,
    bf.status_visita,
    COALESCE(ap.status_aprovacao, 'pendente'::text) AS status_aprovacao,
    bf.tipo_demanda,
    bf.data_prevista_atendimento,
    ck.data_checkin,
    bf.visita_created_at AS data_vistoria,
    COALESCE(cl.data_log_finalizacao,
        CASE
            WHEN (bf.status_visita = 'finalizado'::text) THEN bf.visita_updated_at
            ELSE NULL::timestamp with time zone
        END) AS data_finalizacao,
    COALESCE(cl.data_log_liberacao, sl.data_status_aprovado, ap.data_aprovacao) AS data_liberacao_recomendacao,
    COALESCE(os.data_geracao_os, cl.data_log_conversao, sl.data_status_convertido) AS data_conversao_os,
    (ck.data_checkin IS NOT NULL) AS possui_checkin,
    (COALESCE(dg.total_diagnosticos, (0)::bigint) > 0) AS possui_diagnostico,
    COALESCE(dg.total_diagnosticos, (0)::bigint) AS quantidade_diagnosticos,
    (COALESCE(ev.total_evidencias, (0)::bigint) > 0) AS possui_evidencias,
    COALESCE(ev.total_evidencias, (0)::bigint) AS quantidade_evidencias,
    COALESCE(rc.possui_conteudo_real, false) AS possui_recomendacao,
    COALESCE(rc.total_recomendacoes, (0)::bigint) AS quantidade_recomendacoes,
    (os.os_id IS NOT NULL) AS possui_os,
    os.os_id,
    os.numero_os,
    os.status_os,
    os.os_microrganismo_id AS microrganismo_id,
    mic.nome AS microrganismo_nome,
        CASE
            WHEN ((bf.status_visita = 'convertido_os'::text) AND (os.os_id IS NOT NULL)) THEN 'Concluído'::text
            WHEN ((bf.status_visita = 'convertido_os'::text) AND (os.os_id IS NULL)) THEN 'Corrigir vínculo da OS'::text
            WHEN ((bf.status_solicitacao = 'aguardando_decisao_produtor'::text) AND (bf.status_visita = 'aprovado'::text)) THEN 'Converter em OS'::text
            WHEN (bf.status_solicitacao = 'aguardando_decisao_produtor'::text) THEN 'Aguardando decisão do produtor'::text
            WHEN (COALESCE(rc.possui_conteudo_real, false) AND (bf.status_visita = 'finalizado'::text)) THEN 'Liberar recomendação'::text
            WHEN ((COALESCE(dg.total_diagnosticos, (0)::bigint) > 0) AND (NOT COALESCE(rc.possui_conteudo_real, false))) THEN 'Emitir recomendação'::text
            WHEN ((ck.data_checkin IS NOT NULL) AND (COALESCE(ev.total_evidencias, (0)::bigint) = 0)) THEN 'Inserir evidências'::text
            WHEN ((ck.data_checkin IS NOT NULL) AND (COALESCE(dg.total_diagnosticos, (0)::bigint) = 0)) THEN 'Registrar diagnóstico'::text
            WHEN ((bf.status_visita = 'agendada'::text) OR (bf.status_solicitacao = 'agendada'::text)) THEN 'Realizar check-in'::text
            WHEN (bf.status_solicitacao = 'atribuida'::text) THEN 'Agendar visita'::text
            WHEN (bf.consultor_id IS NULL) THEN 'Atribuir consultor'::text
            ELSE 'Aguardando triagem'::text
        END AS proxima_acao,
    ARRAY( SELECT unnest(((((((((((
                CASE
                    WHEN (bf.consultor_id IS NULL) THEN ARRAY['sem_consultor'::text]
                    ELSE ARRAY[]::text[]
                END ||
                CASE
                    WHEN ((bf.status_solicitacao = 'aberta'::text) AND (bf.consultor_id IS NOT NULL)) THEN ARRAY['sem_agendamento'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.registro_consultor_id IS NOT NULL) AND (ck.data_checkin IS NULL)) THEN ARRAY['sem_checkin'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'finalizado'::text) AND (COALESCE(dg.total_diagnosticos, (0)::bigint) = 0)) THEN ARRAY['sem_diagnostico'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'finalizado'::text) AND (COALESCE(ev.total_evidencias, (0)::bigint) = 0)) THEN ARRAY['sem_evidencia'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'finalizado'::text) AND (NOT COALESCE(rc.possui_conteudo_real, false))) THEN ARRAY['sem_recomendacao'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'aprovado'::text) AND (NOT COALESCE(rc.possui_conteudo_real, false))) THEN ARRAY['aprovada_sem_recomendacao'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'aprovado'::text) AND (bf.status_solicitacao <> ALL (ARRAY['aguardando_decisao_produtor'::text, 'convertida_os'::text, 'concluida'::text]))) THEN ARRAY['aprovada_com_solicitacao_antiga'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ((bf.status_visita = 'convertido_os'::text) AND (os.os_id IS NULL)) THEN ARRAY['convertida_os_sem_os'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN (COALESCE(oss.total_os_vinculadas, (0)::bigint) > 1) THEN ARRAY['os_duplicada'::text]
                    ELSE ARRAY[]::text[]
                END) ||
                CASE
                    WHEN ev.tem_arquivo_sem_path THEN ARRAY['evidencia_sem_arquivo_path'::text]
                    ELSE ARRAY[]::text[]
                END)) AS unnest) AS bloqueios,
    (EXTRACT(epoch FROM (now() - COALESCE(bf.solicitacao_created_at, bf.visita_created_at))) / 86400.0) AS dias_em_aberto,
    (EXTRACT(epoch FROM (ck.data_checkin - bf.solicitacao_created_at)) / 3600.0) AS tempo_solicitacao_ate_checkin,
    (EXTRACT(epoch FROM (COALESCE(cl.data_log_finalizacao,
        CASE
            WHEN (bf.status_visita = 'finalizado'::text) THEN bf.visita_updated_at
            ELSE NULL::timestamp with time zone
        END) - ck.data_checkin)) / 3600.0) AS tempo_checkin_ate_finalizacao,
    (EXTRACT(epoch FROM (COALESCE(cl.data_log_liberacao, sl.data_status_aprovado, ap.data_aprovacao) - COALESCE(cl.data_log_finalizacao,
        CASE
            WHEN (bf.status_visita = 'finalizado'::text) THEN bf.visita_updated_at
            ELSE NULL::timestamp with time zone
        END))) / 3600.0) AS tempo_finalizacao_ate_aprovacao,
    (EXTRACT(epoch FROM (COALESCE(os.data_geracao_os, cl.data_log_conversao, sl.data_status_convertido) - COALESCE(cl.data_log_liberacao, sl.data_status_aprovado, ap.data_aprovacao))) / 3600.0) AS tempo_aprovacao_ate_os,
    COALESCE(bf.solicitacao_created_at, bf.visita_created_at) AS created_at,
    COALESCE(bf.visita_updated_at, bf.solicitacao_created_at) AS updated_at
   FROM (((((((((((((((base_fluxo bf
     LEFT JOIN public.clientes c ON ((bf.cliente_id = c.id)))
     LEFT JOIN public.fazendas f ON ((bf.fazenda_id = f.id)))
     LEFT JOIN public.talhoes t ON ((bf.talhao_id = t.id)))
     LEFT JOIN public.culturas cult ON ((bf.cultura_id = cult.id)))
     LEFT JOIN public.profiles u ON ((bf.consultor_id = u.id)))
     LEFT JOIN cte_checkins ck ON ((bf.registro_consultor_id = ck.registro_consultor_id)))
     LEFT JOIN cte_diagnosticos dg ON ((bf.registro_consultor_id = dg.registro_consultor_id)))
     LEFT JOIN cte_evidencias ev ON ((bf.registro_consultor_id = ev.registro_consultor_id)))
     LEFT JOIN cte_recomendacoes rc ON ((bf.registro_consultor_id = rc.registro_consultor_id)))
     LEFT JOIN cte_os_single os ON ((bf.registro_consultor_id = os.registro_consultor_id)))
     LEFT JOIN cte_os_stats oss ON ((bf.registro_consultor_id = oss.registro_consultor_id)))
     LEFT JOIN cte_logs_datas cl ON ((bf.registro_consultor_id = cl.registro_consultor_id)))
     LEFT JOIN cte_status_logs sl ON ((bf.registro_consultor_id = sl.registro_consultor_id)))
     LEFT JOIN cte_aprovacoes ap ON ((bf.registro_consultor_id = ap.registro_consultor_id)))
     LEFT JOIN public.microrganismos mic ON ((os.os_microrganismo_id = mic.id)));


ALTER VIEW public._src_vw_fluxo_visita_tecnica OWNER TO postgres;

--
-- Name: mv_fluxo_visita_tecnica; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_fluxo_visita_tecnica AS
 SELECT origem_fluxo,
    solicitacao_id,
    numero_solicitacao,
    registro_consultor_id,
    codigo_visita,
    cliente_id,
    cliente_nome,
    fazenda_id,
    fazenda_nome,
    talhao_id,
    talhao_nome,
    cultura_id,
    cultura_nome,
    consultor_id,
    consultor_nome,
    status_solicitacao,
    status_visita,
    status_aprovacao,
    tipo_demanda,
    data_prevista_atendimento,
    data_checkin,
    data_vistoria,
    data_finalizacao,
    data_liberacao_recomendacao,
    data_conversao_os,
    possui_checkin,
    possui_diagnostico,
    quantidade_diagnosticos,
    possui_evidencias,
    quantidade_evidencias,
    possui_recomendacao,
    quantidade_recomendacoes,
    possui_os,
    os_id,
    numero_os,
    status_os,
    microrganismo_id,
    microrganismo_nome,
    proxima_acao,
    bloqueios,
    dias_em_aberto,
    tempo_solicitacao_ate_checkin,
    tempo_checkin_ate_finalizacao,
    tempo_finalizacao_ate_aprovacao,
    tempo_aprovacao_ate_os,
    created_at,
    updated_at
   FROM public._src_vw_fluxo_visita_tecnica
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_fluxo_visita_tecnica OWNER TO postgres;

--
-- Name: h7n_fluxo_visita_tecnica(); Type: FUNCTION; Schema: private; Owner: postgres
--

CREATE FUNCTION private.h7n_fluxo_visita_tecnica() RETURNS SETOF public.mv_fluxo_visita_tecnica
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.*
  from public.mv_fluxo_visita_tecnica m
  where public.has_role(auth.uid(), 'administrador'::public.app_role)
     or public.has_role(auth.uid(), 'gestor'::public.app_role)
     or public.has_role(auth.uid(), 'administrativo'::public.app_role)
     or public.has_role(auth.uid(), 'producao'::public.app_role)
     or public.has_role(auth.uid(), 'financeiro'::public.app_role)
     or (
       (public.has_role(auth.uid(), 'consultor_tecnico'::public.app_role)
        or public.has_role(auth.uid(), 'tecnico_agronomo'::public.app_role))
       and (m.consultor_id = auth.uid()
            or m.cliente_id = any(public.get_cliente_ids_for_user(auth.uid())))
     );
$$;


ALTER FUNCTION private.h7n_fluxo_visita_tecnica() OWNER TO postgres;

--
-- Name: _assert_visita_editavel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._assert_visita_editavel(p_registro_id uuid) RETURNS public.registros_consultor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_ok boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_reg FROM public.registros_consultor WHERE id = p_registro_id;
  IF v_reg.id IS NULL THEN RAISE EXCEPTION 'registro_nao_encontrado' USING ERRCODE = 'P0002'; END IF;

  v_ok := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
       OR COALESCE(v_reg.created_by = v_uid, false)
       OR COALESCE(v_reg.consultor_responsavel = v_uid, false)
       OR COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);

  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_reg.status::text) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  RETURN v_reg;
END;
$$;


ALTER FUNCTION public._assert_visita_editavel(p_registro_id uuid) OWNER TO postgres;

--
-- Name: _avancar_os_status(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._avancar_os_status(p_origem text, p_os_id uuid, p_alvo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    status_order TEXT[] := ARRAY['aberta','aprovada','programada','em_producao','em_cq','envase','aguardando_reserva','pronto_entrega','entregue','finalizada'];
    v_atual TEXT;
    v_idx_atual INT;
    v_idx_alvo INT;
    v_proximo TEXT;
    v_use_manual BOOLEAN;
BEGIN
    v_use_manual := p_origem IN ('manual','b2b');

    IF v_use_manual THEN
        SELECT status::text INTO v_atual FROM public.ordens_servico WHERE id = p_os_id;
    ELSE
        SELECT status::text INTO v_atual FROM public.ordens_servico_onfarm WHERE id = p_os_id;
    END IF;

    SELECT i INTO v_idx_atual FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = v_atual;
    SELECT i INTO v_idx_alvo FROM unnest(status_order) WITH ORDINALITY AS t(val,i) WHERE val = p_alvo;

    IF v_idx_atual IS NULL OR v_idx_alvo IS NULL THEN
        RAISE EXCEPTION 'Status OS inválido (% -> %).', v_atual, p_alvo;
    END IF;

    WHILE v_idx_atual < v_idx_alvo LOOP
        v_proximo := status_order[v_idx_atual + 1];
        IF v_use_manual THEN
            UPDATE public.ordens_servico SET status = v_proximo::public.status_os WHERE id = p_os_id;
        ELSE
            UPDATE public.ordens_servico_onfarm SET status = v_proximo::public.status_os_onfarm WHERE id = p_os_id;
        END IF;
        v_idx_atual := v_idx_atual + 1;
    END LOOP;
END;
$$;


ALTER FUNCTION public._avancar_os_status(p_origem text, p_os_id uuid, p_alvo text) OWNER TO postgres;

--
-- Name: _comunicacao_build_snapshot(text, uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_build_snapshot(_event_key text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_codigo_os text; v_data_prevista text; v_nome_dest text;
  v_titulo text; v_mensagem text; v_target_role text;
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT nome INTO v_nome_dest FROM public.profiles WHERE user_id = _user_id LIMIT 1;
  ELSIF _cliente_id IS NOT NULL THEN
    SELECT nome INTO v_nome_dest FROM public.clientes WHERE id = _cliente_id LIMIT 1;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    SELECT o.numero_os, to_char(o.data_programada, 'DD/MM/YYYY')
      INTO v_codigo_os, v_data_prevista
      FROM public.ordens_servico o WHERE o.id = _source_id;
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'codigo_os', COALESCE(v_codigo_os,''),
      'data_prevista', COALESCE(v_data_prevista,'')
    );
  END IF;
  IF _event_key = 'administrative_important_update' THEN
    v_titulo := left(COALESCE(_payload ->> 'titulo',''), 200);
    v_mensagem := left(COALESCE(_payload ->> 'mensagem',''), 2000);
    v_target_role := _payload ->> 'target_role';
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'titulo', v_titulo, 'mensagem', v_mensagem,
      'target_role', COALESCE(v_target_role,'')
    );
  END IF;
  RETURN '{}'::jsonb;
END$$;


ALTER FUNCTION public._comunicacao_build_snapshot(_event_key text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid) OWNER TO postgres;

--
-- Name: _comunicacao_build_snapshot_v2(text, text, uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_build_snapshot_v2(_event_key text, _source_type text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_codigo_os text; v_data_prevista text; v_nome_dest text;
  v_titulo text; v_mensagem text; v_target_role text;
  v_sol RECORD;
BEGIN
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    IF _user_id IS NOT NULL THEN
      SELECT nome INTO v_nome_dest FROM public.profiles WHERE user_id = _user_id LIMIT 1;
    ELSIF _cliente_id IS NOT NULL THEN
      SELECT nome INTO v_nome_dest FROM public.clientes WHERE id = _cliente_id LIMIT 1;
    END IF;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF _source_type NOT IN ('ordens_servico','ordens_servico_onfarm') THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    CASE _source_type
      WHEN 'ordens_servico' THEN
        SELECT o.numero_os, to_char(o.data_programada,'DD/MM/YYYY')
          INTO v_codigo_os, v_data_prevista FROM public.ordens_servico o WHERE o.id = _source_id;
      WHEN 'ordens_servico_onfarm' THEN
        SELECT o.numero_os, to_char(o.data_recomendada,'DD/MM/YYYY')
          INTO v_codigo_os, v_data_prevista FROM public.ordens_servico_onfarm o WHERE o.id = _source_id;
    END CASE;
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'codigo_os', COALESCE(v_codigo_os,''),
      'data_prevista', COALESCE(v_data_prevista,''));
  END IF;
  IF _event_key = 'administrative_important_update' THEN
    v_titulo := left(COALESCE(_payload->>'titulo',''), 200);
    v_mensagem := left(COALESCE(_payload->>'mensagem',''), 2000);
    v_target_role := _payload->>'target_role';
    RETURN jsonb_build_object(
      'nome_destinatario', COALESCE(v_nome_dest,''),
      'titulo', v_titulo, 'mensagem', v_mensagem,
      'target_role', COALESCE(v_target_role,''));
  END IF;
  IF _event_key IN (
    'solicitacao_criada','solicitacao_atribuida','solicitacao_checkin_realizado',
    'solicitacao_em_visita','solicitacao_aguardando_os','solicitacao_concluida',
    'solicitacao_cancelada','solicitacao_urgencia_critica'
  ) THEN
    IF _source_type <> 'portal_solicitacoes' THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    SELECT s.numero_solicitacao, s.tipo_demanda::text, s.urgencia::text, s.status::text
      INTO v_sol FROM public.portal_solicitacoes s WHERE s.id = _source_id;
    IF v_sol IS NULL THEN RETURN '{}'::jsonb; END IF;
    RETURN jsonb_build_object(
      'numero', COALESCE(v_sol.numero_solicitacao,''),
      'tipo_demanda', COALESCE(v_sol.tipo_demanda,''),
      'urgencia', COALESCE(v_sol.urgencia,''),
      'status_novo', COALESCE(v_sol.status,''),
      'solicitacao_id', _source_id::text);
  END IF;
  RETURN '{}'::jsonb;
END $$;


ALTER FUNCTION public._comunicacao_build_snapshot_v2(_event_key text, _source_type text, _source_id uuid, _payload jsonb, _user_id uuid, _cliente_id uuid) OWNER TO postgres;

--
-- Name: _comunicacao_can_deliver(uuid, uuid, public.comunicacao_canal); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_can_deliver(_user_id uuid, _cliente_id uuid, _canal public.comunicacao_canal) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE p public.comunicacao_preferencias%rowtype;
BEGIN
  IF _user_id IS NOT NULL THEN
    SELECT * INTO p FROM public.comunicacao_preferencias WHERE user_id = _user_id AND canal = _canal;
  ELSIF _cliente_id IS NOT NULL THEN
    SELECT * INTO p FROM public.comunicacao_preferencias WHERE cliente_id = _cliente_id AND canal = _canal;
  ELSE
    RETURN false;
  END IF;
  IF _canal = 'in_app' THEN RETURN COALESCE(p.enabled, true); END IF;
  IF NOT COALESCE(p.enabled, true) THEN RETURN false; END IF;
  IF _canal = 'whatsapp' AND p.whatsapp_opt_out_at IS NOT NULL THEN RETURN false; END IF;
  IF _canal = 'whatsapp' AND (p.whatsapp_opt_in_at IS NULL OR NOT COALESCE(p.telefone_verificado,false)) THEN
    RETURN false;
  END IF;
  IF _canal = 'email' AND NOT COALESCE(p.email_verificado,false) THEN RETURN false; END IF;
  IF _canal = 'push' AND _user_id IS NULL THEN RETURN false; END IF;
  RETURN true;
END$$;


ALTER FUNCTION public._comunicacao_can_deliver(_user_id uuid, _cliente_id uuid, _canal public.comunicacao_canal) OWNER TO postgres;

--
-- Name: _comunicacao_dlq_replay_rate_check(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_dlq_replay_rate_check(p_scope text, p_max_per_minute integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_actor uuid; v_cnt int;
BEGIN
  v_actor := auth.uid();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'sem contexto de usuário' USING ERRCODE='42501';
  END IF;
  SELECT count(*) INTO v_cnt
    FROM public.comunicacao_dlq_replay_audit
   WHERE actor_id = v_actor
     AND scope = p_scope
     AND created_at > now() - interval '1 minute';
  IF v_cnt >= p_max_per_minute THEN
    RAISE EXCEPTION 'rate_limited: replay % excede % por minuto', p_scope, p_max_per_minute
      USING ERRCODE='53400';
  END IF;
END;$$;


ALTER FUNCTION public._comunicacao_dlq_replay_rate_check(p_scope text, p_max_per_minute integer) OWNER TO postgres;

--
-- Name: _comunicacao_expand_event(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_expand_event(_event_id uuid, _event_key text, _source_type text, _source_id uuid, _payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_rule public.comunicacao_regras%rowtype;
  v_tpl public.comunicacao_templates%rowtype;
  v_rec record; v_snapshot jsonb; v_payload_snapshot jsonb; v_idem_out text;
  v_enq int := 0; v_skp int := 0; v_row int := 0; v_target_role public.app_role;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    BEGIN v_target_role := (_payload->>'target_role')::public.app_role;
    EXCEPTION WHEN others THEN RAISE EXCEPTION 'target_role inválido'; END;
  END IF;
  FOR v_rule IN
    SELECT * FROM public.comunicacao_regras
     WHERE event_key = _event_key AND enabled = true
       AND (_event_key <> 'administrative_important_update'
            OR (estrategia='broadcast_role' AND perfil = v_target_role))
     ORDER BY prioridade ASC
  LOOP
    v_tpl := public._comunicacao_resolve_template(v_rule.template_chave, v_rule.canal, v_rule.template_versao);
    IF v_tpl.id IS NULL OR v_tpl.canal <> v_rule.canal THEN v_skp := v_skp+1; CONTINUE; END IF;
    v_snapshot := jsonb_build_object(
      'assunto', v_tpl.assunto, 'corpo', v_tpl.corpo,
      'variaveis', v_tpl.variaveis, 'canal', v_tpl.canal, 'locale', v_tpl.locale,
      'provider_template_name', v_tpl.provider_template_name,
      'language_code', v_tpl.language_code,
      'parameter_mapping', v_tpl.parameter_mapping,
      'provider_template_status', v_tpl.provider_template_status);
    FOR v_rec IN SELECT * FROM public._comunicacao_resolve_recipients_v2(_event_key, v_rule, _source_type, _source_id)
    LOOP
      IF NOT public._comunicacao_can_deliver(v_rec.recipient_user_id, v_rec.recipient_cliente_id, v_rule.canal) THEN
        v_skp := v_skp+1; CONTINUE; END IF;
      v_payload_snapshot := public._comunicacao_build_snapshot_v2(
        _event_key, _source_type, _source_id, _payload,
        v_rec.recipient_user_id, v_rec.recipient_cliente_id);
      v_idem_out := encode(extensions.digest(
        concat_ws('|', _event_id::text, v_rule.id::text, v_tpl.id::text,
          COALESCE(v_rec.recipient_user_id::text,''),
          COALESCE(v_rec.recipient_cliente_id::text,'')), 'sha256'),'hex');
      INSERT INTO public.comunicacao_outbox(
        event_id, rule_id, template_id, template_chave, template_versao,
        template_snapshot, canal, recipient_user_id, recipient_cliente_id,
        payload_snapshot, idempotency_key)
      VALUES (_event_id, v_rule.id, v_tpl.id, v_tpl.chave, v_tpl.versao,
        v_snapshot, v_rule.canal, v_rec.recipient_user_id, v_rec.recipient_cliente_id,
        v_payload_snapshot, v_idem_out)
      ON CONFLICT (idempotency_key) DO NOTHING;
      GET DIAGNOSTICS v_row = ROW_COUNT;
      IF v_row = 1 THEN v_enq := v_enq+1; ELSE v_skp := v_skp+1; END IF;
    END LOOP;
  END LOOP;
  UPDATE public.comunicacao_eventos
     SET status='processed', processed_at=now(),
         outbox_enqueued=v_enq, outbox_skipped=v_skp
   WHERE id = _event_id;
  RETURN jsonb_build_object('enqueued',v_enq,'skipped',v_skp);
END$$;


ALTER FUNCTION public._comunicacao_expand_event(_event_id uuid, _event_key text, _source_type text, _source_id uuid, _payload jsonb) OWNER TO postgres;

