--
-- Name: comunicacao_regras; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.comunicacao_regras (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_key text NOT NULL,
    perfil public.app_role,
    estrategia text DEFAULT 'by_role'::text NOT NULL,
    canal public.comunicacao_canal NOT NULL,
    template_chave text NOT NULL,
    template_versao integer,
    condicoes jsonb DEFAULT '{}'::jsonb NOT NULL,
    prioridade integer DEFAULT 100 NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    cooldown_seconds integer DEFAULT 0 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT comunicacao_regras_condicoes_obj CHECK (((jsonb_typeof(condicoes) = 'object'::text) AND (length((condicoes)::text) <= 8000))),
    CONSTRAINT comunicacao_regras_cooldown_chk CHECK (((cooldown_seconds >= 0) AND (cooldown_seconds <= 604800))),
    CONSTRAINT comunicacao_regras_estrategia_chk CHECK ((estrategia = ANY (ARRAY['by_role'::text, 'source_participants'::text, 'broadcast_role'::text, 'source_cliente'::text, 'assigned_consultant'::text]))),
    CONSTRAINT comunicacao_regras_event_chk CHECK (((length(event_key) >= 3) AND (length(event_key) <= 100))),
    CONSTRAINT comunicacao_regras_prio_chk CHECK (((prioridade >= 0) AND (prioridade <= 1000)))
);


ALTER TABLE public.comunicacao_regras OWNER TO postgres;

--
-- Name: _comunicacao_resolve_recipients(text, public.comunicacao_regras, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_resolve_recipients(_event_key text, _rule public.comunicacao_regras, _source_id uuid) RETURNS TABLE(recipient_user_id uuid, recipient_cliente_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_os_cliente uuid;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    IF _rule.estrategia <> 'broadcast_role' OR _rule.perfil IS NULL THEN RETURN; END IF;
    RETURN QUERY
      SELECT DISTINCT pr.user_id, NULL::uuid
        FROM public.user_roles ur
        JOIN public.profiles pr ON pr.user_id = ur.user_id
       WHERE ur.role = _rule.perfil AND COALESCE(pr.ativo, true) = true;
    RETURN;
  END IF;
  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico o WHERE o.id = _source_id;
    IF v_os_cliente IS NULL THEN RETURN; END IF;
    IF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY
        SELECT NULL::uuid AS recipient_user_id, v_os_cliente AS recipient_cliente_id
        UNION
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.cliente_id = v_os_cliente AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur
          JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil AND pr.cliente_id = v_os_cliente
           AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSE
      RETURN;
    END IF;
  END IF;
END$$;


ALTER FUNCTION public._comunicacao_resolve_recipients(_event_key text, _rule public.comunicacao_regras, _source_id uuid) OWNER TO postgres;

--
-- Name: _comunicacao_resolve_recipients_v2(text, public.comunicacao_regras, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_resolve_recipients_v2(_event_key text, _rule public.comunicacao_regras, _source_type text, _source_id uuid) RETURNS TABLE(recipient_user_id uuid, recipient_cliente_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_os_cliente uuid;
  v_sol RECORD;
BEGIN
  IF _event_key = 'administrative_important_update' THEN
    IF _rule.estrategia <> 'broadcast_role' OR _rule.perfil IS NULL THEN RETURN; END IF;
    RETURN QUERY
      SELECT DISTINCT pr.user_id, NULL::uuid
        FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id = ur.user_id
       WHERE ur.role = _rule.perfil AND COALESCE(pr.ativo, true) = true;
    RETURN;
  END IF;

  IF _event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao') THEN
    IF _source_type NOT IN ('ordens_servico','ordens_servico_onfarm') THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    CASE _source_type
      WHEN 'ordens_servico' THEN
        SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico o WHERE o.id = _source_id;
      WHEN 'ordens_servico_onfarm' THEN
        SELECT o.cliente_id INTO v_os_cliente FROM public.ordens_servico_onfarm o WHERE o.id = _source_id;
    END CASE;
    IF v_os_cliente IS NULL THEN RETURN; END IF;
    IF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY
        SELECT NULL::uuid, v_os_cliente
        UNION
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.cliente_id = v_os_cliente AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil AND pr.cliente_id = v_os_cliente
           AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSE RETURN;
    END IF;
  END IF;

  IF _event_key IN (
    'solicitacao_criada','solicitacao_atribuida','solicitacao_checkin_realizado',
    'solicitacao_em_visita','solicitacao_aguardando_os','solicitacao_concluida',
    'solicitacao_cancelada','solicitacao_urgencia_critica'
  ) THEN
    IF _source_type <> 'portal_solicitacoes' THEN
      RAISE EXCEPTION 'source_type inválido: %', _source_type; END IF;
    SELECT s.cliente_id, s.consultor_atribuido INTO v_sol
      FROM public.portal_solicitacoes s WHERE s.id = _source_id;
    IF v_sol IS NULL THEN RETURN; END IF;

    IF _rule.estrategia = 'source_cliente' THEN
      IF v_sol.cliente_id IS NULL THEN RETURN; END IF;
      RETURN QUERY SELECT NULL::uuid, v_sol.cliente_id;
      RETURN;
    ELSIF _rule.estrategia = 'assigned_consultant' THEN
      IF v_sol.consultor_atribuido IS NULL THEN RETURN; END IF;
      RETURN QUERY
        SELECT pr.user_id, NULL::uuid
          FROM public.profiles pr
         WHERE pr.user_id = v_sol.consultor_atribuido
           AND COALESCE(pr.ativo, true) = true;
      RETURN;
    ELSIF _rule.estrategia = 'source_participants' THEN
      RETURN QUERY SELECT NULL::uuid, v_sol.cliente_id;
      IF v_sol.consultor_atribuido IS NOT NULL THEN
        RETURN QUERY SELECT v_sol.consultor_atribuido, NULL::uuid;
      END IF;
      RETURN;
    ELSIF _rule.estrategia = 'by_role' THEN
      IF _rule.perfil IS NULL THEN RETURN; END IF;
      IF _rule.perfil <> 'administrador'::public.app_role THEN RETURN; END IF;
      RETURN QUERY
        SELECT DISTINCT pr.user_id, NULL::uuid
          FROM public.user_roles ur
          JOIN public.profiles pr ON pr.user_id = ur.user_id
         WHERE ur.role = _rule.perfil
           AND COALESCE(pr.ativo,true) = true;
      RETURN;
    ELSE
      RETURN;
    END IF;
  END IF;
END $$;


ALTER FUNCTION public._comunicacao_resolve_recipients_v2(_event_key text, _rule public.comunicacao_regras, _source_type text, _source_id uuid) OWNER TO postgres;

--
-- Name: comunicacao_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.comunicacao_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    chave text NOT NULL,
    nome text NOT NULL,
    canal public.comunicacao_canal NOT NULL,
    versao integer DEFAULT 1 NOT NULL,
    status public.comunicacao_template_status DEFAULT 'draft'::public.comunicacao_template_status NOT NULL,
    locale text DEFAULT 'pt-BR'::text NOT NULL,
    assunto text,
    corpo text NOT NULL,
    variaveis jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    archived_at timestamp with time zone,
    provider_template_name text,
    language_code text,
    parameter_mapping jsonb DEFAULT '[]'::jsonb NOT NULL,
    provider_template_status text,
    CONSTRAINT comunicacao_templates_assunto_chk CHECK (((assunto IS NULL) OR (length(assunto) <= 300))),
    CONSTRAINT comunicacao_templates_chave_chk CHECK (((length(chave) >= 3) AND (length(chave) <= 120))),
    CONSTRAINT comunicacao_templates_corpo_chk CHECK (((length(corpo) >= 1) AND (length(corpo) <= 30000))),
    CONSTRAINT comunicacao_templates_email_assunto_chk CHECK (((status = 'draft'::public.comunicacao_template_status) OR (canal <> 'email'::public.comunicacao_canal) OR ((assunto IS NOT NULL) AND ((length(assunto) >= 1) AND (length(assunto) <= 300))))),
    CONSTRAINT comunicacao_templates_locale_chk CHECK ((locale = 'pt-BR'::text)),
    CONSTRAINT comunicacao_templates_non_whatsapp_meta_chk CHECK (((canal = 'whatsapp'::public.comunicacao_canal) OR ((provider_template_name IS NULL) AND (language_code IS NULL) AND (provider_template_status IS NULL) AND (jsonb_array_length(COALESCE(parameter_mapping, '[]'::jsonb)) = 0)))),
    CONSTRAINT comunicacao_templates_provider_status_chk CHECK (((provider_template_status IS NULL) OR (provider_template_status = ANY (ARRAY['draft'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'paused'::text, 'disabled'::text])))),
    CONSTRAINT comunicacao_templates_variaveis_arr CHECK (((jsonb_typeof(variaveis) = 'array'::text) AND (jsonb_array_length(variaveis) <= 64))),
    CONSTRAINT comunicacao_templates_versao_chk CHECK ((versao >= 1)),
    CONSTRAINT comunicacao_templates_whatsapp_meta_chk CHECK (((status = 'draft'::public.comunicacao_template_status) OR (canal <> 'whatsapp'::public.comunicacao_canal) OR ((provider_template_name IS NOT NULL) AND ((length(provider_template_name) >= 1) AND (length(provider_template_name) <= 512)) AND (language_code IS NOT NULL) AND (language_code ~ '^[a-z]{2}(_[A-Z]{2})?$'::text) AND (jsonb_typeof(parameter_mapping) = 'array'::text) AND (jsonb_array_length(parameter_mapping) <= 64) AND (provider_template_status = 'approved'::text))))
);


ALTER TABLE public.comunicacao_templates OWNER TO postgres;

--
-- Name: _comunicacao_resolve_template(text, public.comunicacao_canal, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._comunicacao_resolve_template(_chave text, _canal public.comunicacao_canal, _versao integer) RETURNS public.comunicacao_templates
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_templates%rowtype;
BEGIN
  IF _versao IS NULL THEN
    SELECT * INTO r FROM public.comunicacao_templates
     WHERE chave = _chave AND canal = _canal AND status = 'active' LIMIT 1;
  ELSE
    SELECT * INTO r FROM public.comunicacao_templates
     WHERE chave = _chave AND canal = _canal AND versao = _versao LIMIT 1;
  END IF;
  RETURN r;
END$$;


