--
-- Name: _sync_planning_from_os(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._sync_planning_from_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_partner_order_id uuid;
  v_planning_id uuid;
  v_total int;
  v_done int;
  v_in_prod int;
BEGIN
  v_partner_order_id := COALESCE(NEW.partner_order_id, OLD.partner_order_id);
  IF v_partner_order_id IS NULL THEN RETURN NEW; END IF;

  SELECT id INTO v_planning_id FROM public.production_planning WHERE partner_order_id = v_partner_order_id;
  IF v_planning_id IS NULL THEN RETURN NEW; END IF;

  SELECT COUNT(*),
         COUNT(*) FILTER (WHERE status IN ('finalizada','entregue','pronto_entrega')),
         COUNT(*) FILTER (WHERE status IN ('em_producao','em_cq','envase','programada'))
    INTO v_total, v_done, v_in_prod
  FROM public.ordens_servico WHERE partner_order_id = v_partner_order_id;

  IF v_total = 0 THEN RETURN NEW; END IF;

  IF v_done = v_total THEN
    UPDATE public.production_planning SET status='produzido', updated_at=now()
      WHERE id=v_planning_id AND status <> 'produzido';
  ELSIF v_in_prod > 0 THEN
    UPDATE public.production_planning SET status='em_producao', updated_at=now()
      WHERE id=v_planning_id AND status NOT IN ('em_producao','produzido','entregue');
  END IF;

  RETURN NEW;
END
$$;


ALTER FUNCTION public._sync_planning_from_os() OWNER TO postgres;

--
-- Name: _validate_planning_integrity(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._validate_planning_integrity(p_partner_order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_ready boolean;
  v_n_items int;
  v_bad_qty int;
BEGIN
  SELECT status::text, ready_for_production INTO v_status, v_ready
  FROM public.partner_orders WHERE id = p_partner_order_id;

  IF v_status IS NULL THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF v_status <> 'aprovado' OR v_ready IS NOT TRUE THEN RAISE EXCEPTION 'order_not_approved'; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE COALESCE(quantidade,0) <= 0)
    INTO v_n_items, v_bad_qty
  FROM public.partner_order_items WHERE order_id = p_partner_order_id;

  IF v_n_items = 0 THEN RAISE EXCEPTION 'no_items'; END IF;
  IF v_bad_qty > 0 THEN RAISE EXCEPTION 'invalid_quantity'; END IF;
END
$$;


ALTER FUNCTION public._validate_planning_integrity(p_partner_order_id uuid) OWNER TO postgres;

--
-- Name: _visita_lock_and_check(uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._visita_lock_and_check(p_registro_id uuid, p_expected_version integer, p_require_approver boolean DEFAULT false) RETURNS public.registros_consultor
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor%ROWTYPE;
  v_scoped_gestor boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  -- Require current actor, role, active scope and tenant before locking or disclosing status.
  IF NOT COALESCE(public.can_view_technical_visit(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'forbidden_visita' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_reg
    FROM public.registros_consultor
   WHERE id = p_registro_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'registro_inexistente' USING ERRCODE = 'P0002';
  END IF;

  IF v_reg.cliente_id IS NOT NULL AND public.has_role(v_uid, 'gestor'::public.app_role) THEN
    v_scoped_gestor := public.has_active_user_cliente_access(
      v_uid, v_reg.cliente_id, ARRAY['manage']::text[]
    );
  END IF;

  IF p_require_approver THEN
    IF NOT (
      public.has_role(v_uid, 'administrador'::public.app_role)
      OR public.is_visit_org_manager(v_uid, p_registro_id)
      OR v_scoped_gestor
    ) THEN
      RAISE EXCEPTION 'forbidden_aprovacao' USING ERRCODE = '42501';
    END IF;
  ELSIF NOT public.can_manage_technical_visit(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_visita' USING ERRCODE = '42501';
  END IF;

  IF p_expected_version IS NOT NULL
     AND COALESCE(v_reg.version, 1) <> p_expected_version THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
  END IF;
  RETURN v_reg;
END
$$;


ALTER FUNCTION public._visita_lock_and_check(p_registro_id uuid, p_expected_version integer, p_require_approver boolean) OWNER TO postgres;

--
-- Name: _visita_log_status(uuid, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._visita_log_status(p_registro_id uuid, p_acao text, p_status_anterior text, p_status_novo text, p_motivo text, p_version integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao, metadata)
  VALUES (
    p_registro_id, auth.uid(), p_acao,
    COALESCE(NULLIF(btrim(p_motivo), ''), p_acao),
    jsonb_build_object(
      'status_anterior', p_status_anterior,
      'status_novo', p_status_novo,
      'motivo', NULLIF(btrim(COALESCE(p_motivo, '')), ''),
      'version', p_version,
      'autor', auth.uid()
    )
  );
END;
$$;


ALTER FUNCTION public._visita_log_status(p_registro_id uuid, p_acao text, p_status_anterior text, p_status_novo text, p_motivo text, p_version integer) OWNER TO postgres;

--
-- Name: _visita_scope_ok(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._visita_scope_ok(p_user_id uuid, p_registro_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p_user_id IS NOT NULL
     AND p_registro_id IS NOT NULL
     AND (
       COALESCE(public.can_manage_technical_visit(p_user_id, p_registro_id), false)
       OR COALESCE(public.is_active_visit_participant(p_user_id, p_registro_id), false)
       OR EXISTS (
         SELECT 1 FROM public.registros_consultor r
          WHERE r.id = p_registro_id
            AND (r.created_by = p_user_id
                 OR r.consultor_responsavel = p_user_id
                 OR r.consultor_profile_id = p_user_id)
       )
     )
$$;


ALTER FUNCTION public._visita_scope_ok(p_user_id uuid, p_registro_id uuid) OWNER TO postgres;

--
-- Name: add_b2b_payment_terms_note_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_b2b_payment_terms_note_secure(p_partner_order_id uuid, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_note IS NULL OR btrim(p_note) = '' THEN
    RAISE EXCEPTION 'note_required';
  END IF;

  SELECT payment_terms_id INTO v_terms_id FROM public.partner_orders WHERE id = p_partner_order_id;
  IF v_terms_id IS NULL THEN RAISE EXCEPTION 'payment_terms_not_defined'; END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_notes = CASE
       WHEN approval_notes IS NULL OR approval_notes = ''
         THEN p_note
         ELSE approval_notes || E'\n---\n' || p_note
       END,
         updated_at = now()
   WHERE id = v_terms_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_note_added', v_uid,
          jsonb_build_object('note', p_note));

  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.add_b2b_payment_terms_note_secure(p_partner_order_id uuid, p_note text) OWNER TO postgres;

--
-- Name: admin_can_update_user_password_server(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_can_update_user_password_server(p_actor_id uuid, p_target_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 SELECT p_actor_id IS NOT NULL
   AND p_target_id IS NOT NULL
   AND p_actor_id = auth.uid()
   AND NOT public.is_platform_superadmin(p_actor_id)
   AND NOT public.is_platform_superadmin(p_target_id)
   AND public.has_role(p_actor_id,'administrador'::public.app_role)
   AND EXISTS (
     SELECT 1
       FROM public.profiles a
       JOIN public.profiles t ON t.user_id = p_target_id
      WHERE a.user_id = p_actor_id
        AND a.ativo = true
        AND a.organization_id IS NOT NULL
        AND a.organization_id = t.organization_id
   );
$$;


ALTER FUNCTION public.admin_can_update_user_password_server(p_actor_id uuid, p_target_id uuid) OWNER TO postgres;

--
-- Name: admin_edit_user_profile_v1(uuid, timestamp with time zone, jsonb, public.app_role[], uuid[], uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_edit_user_profile_v1(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_profile jsonb, p_roles public.app_role[], p_cliente_ids uuid[], p_principal_cliente_id uuid, p_partner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE caller uuid:=auth.uid(); stamp timestamptz; current_roles public.app_role[]; n integer;
BEGIN
 IF p_profile ? '_external_edit' THEN
 RETURN platform_private.user_edit_f2_common(p_user_id,p_expected_updated_at,p_profile,p_roles,p_cliente_ids,p_principal_cliente_id,p_partner_id);
 END IF;
 IF caller IS NULL OR NOT platform_private.is_tenant_admin_for_user(p_user_id) THEN RAISE EXCEPTION 'user_edit_forbidden' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR p_expected_updated_at IS NULL OR p_profile IS NULL OR jsonb_typeof(p_profile)<>'object' THEN RAISE EXCEPTION 'user_edit_invalid_input' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN ('nome','telefone','cargo','cpf_cnpj','crea','especialidade')) THEN RAISE EXCEPTION 'user_edit_invalid_fields' USING ERRCODE='22023'; END IF;
 IF jsonb_typeof(p_profile->'nome') IS DISTINCT FROM 'string' OR char_length(btrim(coalesce(p_profile->>'nome',''))) NOT BETWEEN 2 AND 150 THEN RAISE EXCEPTION 'user_edit_invalid_name' USING ERRCODE='22023'; END IF;
 IF nullif(p_profile->>'telefone','') IS NOT NULL AND (p_profile->>'telefone') !~ '^[0-9]{10,11}$' THEN RAISE EXCEPTION 'user_edit_invalid_phone' USING ERRCODE='22023'; END IF;
 IF p_roles IS NULL OR cardinality(p_roles) NOT BETWEEN 1 AND 13 OR array_position(p_roles,NULL) IS NOT NULL OR cardinality(p_roles)<>(SELECT count(DISTINCT r) FROM unnest(p_roles) r) THEN RAISE EXCEPTION 'user_edit_invalid_roles' USING ERRCODE='22023'; END IF;
 IF 'superadmin'::public.app_role=ANY(p_roles) OR public.is_platform_superadmin(p_user_id) THEN RAISE EXCEPTION 'user_edit_superadmin_forbidden' USING ERRCODE='42501'; END IF;
 IF cardinality(coalesce(p_cliente_ids,'{}'::uuid[]))<>0 OR p_principal_cliente_id IS NOT NULL OR p_partner_id IS NOT NULL THEN RAISE EXCEPTION 'user_edit_unscoped_links_forbidden' USING ERRCODE='42501'; END IF;
 SELECT array_agg(role ORDER BY role::text) INTO current_roles FROM public.user_roles WHERE user_id=p_user_id;
 IF EXISTS(SELECT 1 FROM unnest(coalesce(current_roles,'{}'::public.app_role[])) r WHERE r IN ('cliente_produtor','parceiro_b2b','parceiro_b2b_tecnico')) OR EXISTS(SELECT 1 FROM unnest(p_roles) r WHERE r IN ('cliente_produtor','parceiro_b2b','parceiro_b2b_tecnico')) THEN RAISE EXCEPTION 'user_edit_linked_role_unavailable' USING ERRCODE='42501'; END IF;
 IF caller=p_user_id AND NOT ('administrador'=ANY(p_roles)) THEN RAISE EXCEPTION 'user_edit_self_admin_removal' USING ERRCODE='42501'; END IF;
 SELECT updated_at INTO stamp FROM public.profiles WHERE user_id=p_user_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 IF stamp IS DISTINCT FROM p_expected_updated_at THEN RAISE EXCEPTION 'user_edit_conflict' USING ERRCODE='PT409'; END IF;
 INSERT INTO public.user_roles(user_id,role) SELECT p_user_id,r FROM unnest(p_roles) r WHERE NOT EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p_user_id AND ur.role=r);
 DELETE FROM public.user_roles WHERE user_id=p_user_id AND NOT(role=ANY(p_roles)) AND role<>'superadmin'::public.app_role;
 UPDATE public.profiles SET nome=btrim(p_profile->>'nome'),telefone=nullif(p_profile->>'telefone',''),cargo=nullif(p_profile->>'cargo',''),cpf_cnpj=nullif(p_profile->>'cpf_cnpj',''),crea=nullif(p_profile->>'crea',''),especialidade=nullif(p_profile->>'especialidade','') WHERE user_id=p_user_id RETURNING updated_at INTO stamp;
 GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'user_edit_not_found' USING ERRCODE='P0002'; END IF;
 RETURN jsonb_build_object('success',true,'user_id',p_user_id,'updated_at',stamp);
END; $_$;


ALTER FUNCTION public.admin_edit_user_profile_v1(p_user_id uuid, p_expected_updated_at timestamp with time zone, p_profile jsonb, p_roles public.app_role[], p_cliente_ids uuid[], p_principal_cliente_id uuid, p_partner_id uuid) OWNER TO postgres;

--
-- Name: admin_provision_user_profile_v1(uuid, text, text, public.app_role[], uuid[], uuid, uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_provision_user_profile_v1(p_user_id uuid, p_email text, p_nome text, p_roles public.app_role[], p_cliente_ids uuid[] DEFAULT ARRAY[]::uuid[], p_principal_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_papel text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_cargo text DEFAULT NULL::text, p_cpf_cnpj text DEFAULT NULL::text, p_crea text DEFAULT NULL::text, p_especialidade text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_profile_count integer;
  v_role_count integer;
  v_cliente_count integer;
  v_partner_role_count integer;
BEGIN
  PERFORM platform_private.require_service_role();
  IF p_user_id IS NULL OR p_email IS NULL OR p_nome IS NULL THEN
    RAISE EXCEPTION 'invalid_user_payload' USING ERRCODE = '22023';
  END IF;

  v_role_count := COALESCE(cardinality(p_roles), 0);
  IF v_role_count = 0 OR v_role_count > 13 THEN
    RAISE EXCEPTION 'invalid_roles' USING ERRCODE = '22023';
  END IF;

  IF 'superadmin'::public.app_role = ANY(p_roles) THEN
    RAISE EXCEPTION 'superadmin_role_reserved' USING ERRCODE = '42501';
  END IF;

  IF v_role_count <> (SELECT count(DISTINCT r) FROM unnest(p_roles) AS r) THEN
    RAISE EXCEPTION 'duplicate_roles' USING ERRCODE = '22023';
  END IF;

  p_cliente_ids := COALESCE(p_cliente_ids, ARRAY[]::uuid[]);
  v_cliente_count := cardinality(p_cliente_ids);
  IF v_cliente_count > 100
     OR v_cliente_count <> (SELECT count(DISTINCT c) FROM unnest(p_cliente_ids) AS c) THEN
    RAISE EXCEPTION 'invalid_customer_links' USING ERRCODE = '22023';
  END IF;

  IF 'cliente_produtor'::public.app_role = ANY(p_roles) AND v_cliente_count = 0 THEN
    RAISE EXCEPTION 'producer_requires_customer' USING ERRCODE = '23514';
  END IF;

  IF p_principal_cliente_id IS NOT NULL
     AND NOT (p_principal_cliente_id = ANY(p_cliente_ids)) THEN
    RAISE EXCEPTION 'invalid_primary_customer' USING ERRCODE = '23514';
  END IF;

  IF v_cliente_count > 0 AND (
    SELECT count(*) FROM public.clientes c WHERE c.id = ANY(p_cliente_ids)
  ) <> v_cliente_count THEN
    RAISE EXCEPTION 'customer_not_found' USING ERRCODE = '23503';
  END IF;

  SELECT count(*) INTO v_partner_role_count
  FROM unnest(p_roles) AS r
  WHERE r IN ('parceiro_b2b'::public.app_role, 'parceiro_b2b_tecnico'::public.app_role);

  IF v_partner_role_count > 1 AND NOT EXISTS(SELECT 1 FROM platform_private.b2b_provisioning_receipts r WHERE r.user_id=p_user_id AND r.status='claimed' AND r.external_roles=p_roles AND r.partner_id=p_partner_id) THEN RAISE EXCEPTION 'c2_receipt_required' USING ERRCODE='42501'; END IF;

  IF v_partner_role_count >= 1 THEN
    IF p_partner_id IS NULL OR p_partner_papel NOT IN ('gestor', 'tecnico') THEN
      RAISE EXCEPTION 'invalid_partner_link' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.partner_accounts pa WHERE pa.id = p_partner_id) THEN
      RAISE EXCEPTION 'partner_not_found' USING ERRCODE = '23503';
    END IF;
  ELSIF p_partner_id IS NOT NULL OR p_partner_papel IS NOT NULL THEN
    RAISE EXCEPTION 'unexpected_partner_link' USING ERRCODE = '23514';
  END IF;

  SELECT count(*) INTO v_profile_count
  FROM public.profiles p
  WHERE p.user_id = p_user_id;

  IF v_profile_count <> 1
     OR EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.user_clientes uc WHERE uc.user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.partner_users pu WHERE pu.user_id = p_user_id) THEN
    RAISE EXCEPTION 'user_not_ready_for_provisioning' USING ERRCODE = '23514';
  END IF;

  UPDATE public.profiles
     SET nome = p_nome,
         email = p_email,
         telefone = NULLIF(p_telefone, ''),
         cargo = NULLIF(p_cargo, ''),
         cpf_cnpj = NULLIF(p_cpf_cnpj, ''),
         crea = NULLIF(p_crea, ''),
         especialidade = NULLIF(p_especialidade, '')
   WHERE user_id = p_user_id;

  IF v_cliente_count > 0 THEN
    INSERT INTO public.user_clientes (user_id, cliente_id, principal)
    SELECT p_user_id, c,
           c = COALESCE(p_principal_cliente_id, p_cliente_ids[1])
    FROM unnest(p_cliente_ids) AS c;
  END IF;

  INSERT INTO public.user_roles (user_id, role)
  SELECT p_user_id, r FROM unnest(p_roles) AS r;

  IF v_partner_role_count >= 1 THEN
    INSERT INTO public.partner_users (user_id, partner_id, papel, tenant_id)
    VALUES (p_user_id, p_partner_id, p_partner_papel,(SELECT organization_id FROM public.profiles WHERE user_id=p_user_id));
  END IF;
END;
$$;


ALTER FUNCTION public.admin_provision_user_profile_v1(p_user_id uuid, p_email text, p_nome text, p_roles public.app_role[], p_cliente_ids uuid[], p_principal_cliente_id uuid, p_partner_id uuid, p_partner_papel text, p_telefone text, p_cargo text, p_cpf_cnpj text, p_crea text, p_especialidade text) OWNER TO postgres;

--
-- Name: aplicacao_storage_path_permitido(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aplicacao_storage_path_permitido(_name text, _modo text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
 SELECT COALESCE(platform_private.storage1_application_allowed(_name,_modo),false)
 AND CASE WHEN _modo='insert' THEN public.can_user_create_aplicacao_for_cliente(CASE WHEN public.storage1_path_strict(_name) AND split_part(_name,'/',1) ~ '^[0-9a-f-]{36}$' THEN split_part(_name,'/',1)::uuid ELSE NULL END) ELSE true END;
$_$;


ALTER FUNCTION public.aplicacao_storage_path_permitido(_name text, _modo text) OWNER TO postgres;

--
-- Name: approve_b2b_credit(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_b2b_credit(p_partner_order_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_order public.partner_orders%ROWTYPE;
  v_final_status public.partner_order_status;
  v_final_reason text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
          OR public.has_role(v_uid,'financeiro')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_order FROM public.partner_orders
   WHERE id = p_partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  -- Re-validate authority after the row-lock wait (READ COMMITTED sees revocations committed meanwhile).
  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
          OR public.has_role(v_uid,'financeiro')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_partner_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;

  IF v_order.status IN ('aprovado','reprovado','cancelado') THEN
    RAISE EXCEPTION 'already_processed: pedido já está em status %', v_order.status;
  END IF;

  IF v_order.status = 'em_analise_comercial' THEN
    RAISE EXCEPTION 'already_released: crédito já liberado, pedido em análise comercial';
  END IF;

  IF v_order.status <> 'aguardando_aprovacao_credito' THEN
    RAISE EXCEPTION 'invalid_status: %', v_order.status;
  END IF;

  -- H4-003: autoriza gravacao dos campos credit_approved_by/at nesta transacao.
  PERFORM set_config('arbio.b2b_credit_approval', 'on', true);

  UPDATE public.partner_orders SET
    status = 'em_analise_comercial',
    ready_for_production = false,
    approved_by = NULL,
    approved_at = NULL,
    credit_approved_by = COALESCE(credit_approved_by, v_uid),
    credit_approved_at = COALESCE(credit_approved_at, now()),
    credit_approval_notes = COALESCE(NULLIF(p_notes, ''), credit_approval_notes),
    credit_block_reason = NULL,
    updated_at = now()
  WHERE id = p_partner_order_id
    AND status = 'aguardando_aprovacao_credito';

  PERFORM set_config('arbio.b2b_credit_approval', 'off', true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou durante a aprovação';
  END IF;

  SELECT status, credit_block_reason INTO v_final_status, v_final_reason
  FROM public.partner_orders WHERE id = p_partner_order_id;

  IF v_final_status <> 'em_analise_comercial' THEN
    RAISE EXCEPTION 'credit_release_failed: %', COALESCE(v_final_reason, 'status_nao_liberado');
  END IF;

  INSERT INTO public.partner_order_audit_logs(usuario_id, partner_id, order_id, acao, dados_anteriores, dados_novos)
  VALUES (v_uid, v_order.partner_id, p_partner_order_id, 'credito_aprovado',
          jsonb_build_object('status', v_order.status, 'reason', v_order.credit_block_reason),
          jsonb_build_object('status', v_final_status, 'approved_by', v_uid, 'notes', p_notes));

  RETURN jsonb_build_object('ok', true, 'order_id', p_partner_order_id, 'status', v_final_status);
END;
$$;


ALTER FUNCTION public.approve_b2b_credit(p_partner_order_id uuid, p_notes text) OWNER TO postgres;

--
-- Name: approve_b2b_payment_terms_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_b2b_payment_terms_secure(p_partner_order_id uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
  v_created_by uuid;
  v_numero text;
BEGIN

  IF NOT public.b2b_phase1_order_visible(p_partner_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;

  SELECT po.payment_terms_id, po.created_by, po.numero
    INTO v_terms_id, v_created_by, v_numero
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_terms_id IS NULL THEN
    RAISE EXCEPTION 'payment_terms_not_defined';
  END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_status = 'approved',
         approved_by = v_uid,
         approved_at = now(),
         approval_notes = COALESCE(p_notes, approval_notes),
         updated_at = now()
   WHERE id = v_terms_id;

  UPDATE public.partner_orders
     SET financial_approval_status = 'approved',
         payment_condition_status = 'approved',
         updated_at = now()
   WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_approved', v_uid,
          jsonb_build_object('notes', p_notes));

  -- Notifica comercial (criador)
  IF v_created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_created_by, 'b2b_payment_terms',
            'Condição financeira aprovada',
            format('Pedido %s teve a condição de pagamento aprovada.', COALESCE(v_numero,'B2B')),
            '/comercial/pedidos-b2b');
  END IF;

  RETURN jsonb_build_object('success', true, 'status', 'approved');
END;
$$;


ALTER FUNCTION public.approve_b2b_payment_terms_secure(p_partner_order_id uuid, p_notes text) OWNER TO postgres;

--
-- Name: approve_microorganism_profile_with_audit(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_microorganism_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_micro_id uuid;
  v_b2b_enabled boolean := false;
  v_has_sources boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT microrganismo_id INTO v_micro_id FROM microorganism_technical_profiles WHERE id = p_profile_id;
  IF v_micro_id IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  SELECT COALESCE(b2b_enabled, false) INTO v_b2b_enabled FROM microrganismos WHERE id = v_micro_id;

  SELECT EXISTS(
    SELECT 1 FROM catalog_technical_sources
    WHERE (entidade_tipo = 'microrganismo' AND entidade_id = v_micro_id)
       OR (entidade_tipo = 'ficha_microrganismo' AND entidade_id = p_profile_id)
  ) INTO v_has_sources;

  PERFORM public.validate_catalog_approval_checklist('micro', p_checklist, v_b2b_enabled, v_has_sources, p_aprovado_sem_fonte);

  UPDATE microorganism_technical_profiles
  SET status_validacao = 'aprovado',
      validado_por = v_uid,
      validado_em = now(),
      updated_by = v_uid,
      updated_at = now()
  WHERE id = p_profile_id;

  INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
  VALUES (
    'ficha_microrganismo',
    p_profile_id,
    CASE WHEN p_aprovado_sem_fonte THEN 'aprovacao_tecnica_sem_fonte' ELSE 'aprovacao_tecnica' END,
    v_uid,
    jsonb_build_object(
      'checklist_aprovacao', p_checklist,
      'aprovado_por', v_uid,
      'aprovado_em', now(),
      'aprovado_sem_fonte', p_aprovado_sem_fonte
    )
  );
END;
$$;


ALTER FUNCTION public.approve_microorganism_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean) OWNER TO postgres;

--
-- Name: approve_partner_order(uuid, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_partner_order(p_order_id uuid, p_approval_notes text DEFAULT NULL::text, p_estimated_delivery_date date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev partner_order_status; v_partner_user uuid; v_numero text;
  v_final_status partner_order_status; v_final_ready boolean; v_block text;
  v_amount numeric(14,2); v_credit_ok timestamptz; v_credit jsonb; v_reason text;
BEGIN

  IF NOT (public.b2b_phase1_order_visible(p_order_id) OR EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT partner_id, status, numero,
         ROUND(COALESCE(final_amount_with_interest, total, 0),2), credit_approved_at
    INTO v_pid, v_prev, v_numero, v_amount, v_credit_ok
    FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot->>'contract'='C2_EXTERNAL_ORDER_REQUEST_PENDING_ACCOUNTING_V1') THEN RAISE EXCEPTION 'C2_ACCOUNTING_PENDING' USING ERRCODE='42501'; END IF;

  IF v_prev = 'aguardando_cotacao' THEN
    RAISE EXCEPTION 'quote_required: defina o preco da cotacao antes de aprovar';
  END IF;
  IF NOT public.fn_b2b_order_priceable(p_order_id) THEN
    RAISE EXCEPTION 'order_not_priceable_quote_required';
  END IF;

  IF v_prev IN ('aprovado','reprovado','cancelado') THEN
    RAISE EXCEPTION 'already_processed: pedido já está em status %', v_prev;
  END IF;

  IF v_prev = 'aguardando_aprovacao_credito' THEN
    RAISE EXCEPTION 'credit_pending: aprove o crédito antes da análise comercial';
  END IF;

  IF v_prev NOT IN ('em_analise_comercial','solicitado','rascunho') THEN
    RAISE EXCEPTION 'invalid_status_transition: %', v_prev;
  END IF;

  -- H4-001/H4-003: reavaliar credito na aprovacao, com lock por parceiro.
  -- C2 single credit lock domain: same bigint key as create_partner_order_secure and tg_partner_orders_credit_guard.
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || v_pid::text, 0));
  -- Re-validate authority after a possible wait (READ COMMITTED: each statement sees revocations committed meanwhile).
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF NOT (public.b2b_phase1_order_visible(p_order_id) OR EXISTS (SELECT 1 FROM public.partner_orders po WHERE po.id=p_order_id
      AND platform_private.c2p1_settings_allowed(po.partner_id,true))) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  v_credit := public.fn_b2b_credit_exposure(v_pid, 0, NULL);
  v_reason := COALESCE(v_credit->>'reason_code','OK');

  IF v_credit_ok IS NULL THEN
    IF v_reason IN ('LIMIT_EXCEEDED_BLOCK','OVERDUE_BLOCK') THEN
      UPDATE public.partner_orders
         SET credit_block_reason = v_reason, updated_at = now()
       WHERE id = p_order_id;
      RAISE EXCEPTION 'credit_block_on_approval: %', v_reason;
    ELSIF v_reason = 'LIMIT_EXCEEDED_APPROVAL' THEN
      -- fail-closed: exige aprovacao financeira formal (approve_b2b_credit).
      UPDATE public.partner_orders
         SET credit_block_reason = v_reason, updated_at = now()
       WHERE id = p_order_id;
      RAISE EXCEPTION 'credit_approval_required: %', v_reason;
    END IF;
  END IF;

  UPDATE public.partner_orders
     SET status = 'aprovado', approved_by = v_uid, approved_at = now(),
         approval_notes = NULLIF(p_approval_notes,''),
         estimated_delivery_date = COALESCE(p_estimated_delivery_date, estimated_delivery_date),
         ready_for_production = CASE WHEN c2_external_origin_snapshot IS NOT NULL THEN false ELSE true END, updated_at = now()
   WHERE id = p_order_id AND status = v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou durante a aprovação';
  END IF;

  SELECT status, ready_for_production, credit_block_reason
    INTO v_final_status, v_final_ready, v_block
    FROM public.partner_orders WHERE id = p_order_id;

  IF v_final_status <> 'aprovado' OR (v_final_ready IS NOT TRUE AND NOT EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot IS NOT NULL AND internal_economic_snapshot IS NOT NULL)) THEN
    RAISE EXCEPTION 'credit_block: %', COALESCE(v_block, 'aprovacao_credito_pendente');
  END IF;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'approved',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status','aprovado','approval_notes',p_approval_notes,
                             'estimated_delivery_date',p_estimated_delivery_date,
                             'credit_reason_code', v_reason));

  FOR v_partner_user IN SELECT r FROM platform_private.c2_order_partner_recipients(v_pid) r LOOP -- c2_ord_recipients
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_aprovado',
            'Pedido ' || v_numero || ' aprovado',
            CASE WHEN EXISTS(SELECT 1 FROM public.partner_orders WHERE id=p_order_id AND c2_external_origin_snapshot IS NOT NULL)
            THEN 'Seu pedido recebeu aprovação comercial. Planejamento de produção ainda não liberado.'
            ELSE 'Seu pedido foi aprovado e seguirá para planejamento de produção.' END,
            '/portal-parceiro/pedidos');
  END LOOP;
END
$$;


ALTER FUNCTION public.approve_partner_order(p_order_id uuid, p_approval_notes text, p_estimated_delivery_date date) OWNER TO postgres;

--
-- Name: approve_product_profile_with_audit(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.approve_product_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_prod_id uuid;
  v_b2b_enabled boolean := false;
  v_has_sources boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT produto_id INTO v_prod_id FROM product_technical_profiles WHERE id = p_profile_id;
  IF v_prod_id IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  SELECT COALESCE(b2b_enabled, false) INTO v_b2b_enabled FROM produtos WHERE id = v_prod_id;

  SELECT EXISTS(
    SELECT 1 FROM catalog_technical_sources
    WHERE (entidade_tipo = 'produto' AND entidade_id = v_prod_id)
       OR (entidade_tipo = 'ficha_produto' AND entidade_id = p_profile_id)
  ) INTO v_has_sources;

  PERFORM public.validate_catalog_approval_checklist('produto', p_checklist, v_b2b_enabled, v_has_sources, p_aprovado_sem_fonte);

  UPDATE product_technical_profiles
  SET status_validacao = 'aprovado',
      validado_por = v_uid,
      validado_em = now(),
      updated_by = v_uid,
      updated_at = now()
  WHERE id = p_profile_id;

  INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
  VALUES (
    'ficha_produto',
    p_profile_id,
    CASE WHEN p_aprovado_sem_fonte THEN 'aprovacao_tecnica_sem_fonte' ELSE 'aprovacao_tecnica' END,
    v_uid,
    jsonb_build_object(
      'checklist_aprovacao', p_checklist,
      'aprovado_por', v_uid,
      'aprovado_em', now(),
      'aprovado_sem_fonte', p_aprovado_sem_fonte
    )
  );
END;
$$;


ALTER FUNCTION public.approve_product_profile_with_audit(p_profile_id uuid, p_checklist jsonb, p_aprovado_sem_fonte boolean) OWNER TO postgres;

--
-- Name: aprovar_ficha_versao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aprovar_ficha_versao(p_versao_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_versao public.ficha_tecnica_versoes%ROWTYPE;
  v_sql text;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador') OR public.has_role(auth.uid(), 'gestor')) THEN
    RAISE EXCEPTION 'Sem permissão para aprovar versões';
  END IF;

  SELECT * INTO v_versao FROM public.ficha_tecnica_versoes WHERE id = p_versao_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Versão não encontrada'; END IF;
  IF v_versao.status <> 'pendente' THEN RAISE EXCEPTION 'Versão não está pendente'; END IF;

  -- Aplica ao profile correto
  IF v_versao.entidade_tipo = 'produto' THEN
    v_sql := format(
      'UPDATE public.product_technical_profiles SET %I = $1, updated_at = now() WHERE produto_id = $2',
      v_versao.campo
    );
    EXECUTE v_sql USING v_versao.conteudo_novo, v_versao.entidade_id;
  ELSE
    v_sql := format(
      'UPDATE public.microorganism_technical_profiles SET %I = $1, updated_at = now() WHERE microrganismo_id = $2',
      v_versao.campo
    );
    EXECUTE v_sql USING v_versao.conteudo_novo, v_versao.entidade_id;
  END IF;

  -- Marca anteriores como substituidas
  UPDATE public.ficha_tecnica_versoes
  SET status = 'substituida'
  WHERE entidade_tipo = v_versao.entidade_tipo
    AND entidade_id = v_versao.entidade_id
    AND campo = v_versao.campo
    AND status = 'aprovada';

  UPDATE public.ficha_tecnica_versoes
  SET status = 'aprovada',
      revisado_por = auth.uid(),
      revisado_em = now()
  WHERE id = p_versao_id;
END;
$_$;


ALTER FUNCTION public.aprovar_ficha_versao(p_versao_id uuid) OWNER TO postgres;

--
-- Name: archive_partner_simulation_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_partner_simulation_secure(p_simulation_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN

  IF NOT public.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'Simulação já convertida em pedido não pode ser arquivada'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND v_sim.partner_id = v_partner_id THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para arquivar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'arquivada', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_archived',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'arquivada', 'reason', p_reason));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_archived', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL,
    jsonb_build_object('reason', p_reason));
END;
$$;


ALTER FUNCTION public.archive_partner_simulation_secure(p_simulation_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: assign_b2b_user_client_secure(uuid, uuid, text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_b2b_user_client_secure(p_user_id uuid, p_cliente_id uuid, p_assignment_type text DEFAULT 'monitoramento'::text, p_can_create_simulation boolean DEFAULT true, p_can_monitor boolean DEFAULT true, p_notes text DEFAULT NULL::text) RETURNS uuid
