--
-- Name: auto_advance_solicitacao_on_checkin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_advance_solicitacao_on_checkin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
      SET status = 'checkin_realizado', updated_at = now()
      WHERE id = NEW.solicitacao_id
        AND status NOT IN ('concluida','cancelada','aguardando_os','aguardando_recomendacao');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_advance_solicitacao_on_checkin() OWNER TO postgres;

--
-- Name: auto_advance_solicitacao_on_os(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_advance_solicitacao_on_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_solicitacao_id uuid;
BEGIN
  IF NEW.registro_consultor_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT solicitacao_id INTO v_solicitacao_id
    FROM public.registros_consultor WHERE id = NEW.registro_consultor_id;
  IF v_solicitacao_id IS NOT NULL THEN
    UPDATE public.portal_solicitacoes
      SET status = 'aguardando_os', updated_at = now()
      WHERE id = v_solicitacao_id
        AND status NOT IN ('concluida','cancelada');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_advance_solicitacao_on_os() OWNER TO postgres;

--
-- Name: auto_advance_solicitacao_on_registro(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_advance_solicitacao_on_registro() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.solicitacao_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND OLD.hora_inicio IS NULL AND NEW.hora_inicio IS NOT NULL THEN
  UPDATE public.portal_solicitacoes SET status='em_visita',updated_at=now()
   WHERE id=NEW.solicitacao_id AND status NOT IN ('concluida','cancelada');
 END IF;
 -- Não concluir solicitação no encaminhamento; OS/comerciais têm ciclos próprios.
 RETURN NEW;
END $$;


ALTER FUNCTION public.auto_advance_solicitacao_on_registro() OWNER TO postgres;

--
-- Name: auto_reject_partner_orders_no_items(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_reject_partner_orders_no_items(p_horas integer DEFAULT 72) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count int := 0; v_rec record;
BEGIN
  FOR v_rec IN
    SELECT id, partner_id, numero
      FROM public.partner_orders
     WHERE status = 'aguardando_itens'
       AND itens_pendentes_solicitado_em IS NOT NULL
       AND itens_pendentes_solicitado_em < now() - make_interval(hours => p_horas)
     FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.partner_orders
       SET status = 'reprovado_sem_itens',
           approved_at = now(),
           updated_at = now()
     WHERE id = v_rec.id AND status = 'aguardando_itens';

    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
    VALUES (v_rec.id, v_rec.partner_id, NULL, 'auto_rejected_no_items',
            jsonb_build_object('status','aguardando_itens'),
            jsonb_build_object('status','reprovado_sem_itens','sla_horas',p_horas));

    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.auto_reject_partner_orders_no_items(p_horas integer) OWNER TO postgres;

