--
-- Name: calculate_valor_ha_from_dose(numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_valor_ha_from_dose(p_dose_ml_ha numeric, p_valor_dose numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_dose_ml_ha IS NULL OR p_valor_dose IS NULL OR p_dose_ml_ha <= 0 THEN NULL
    ELSE (p_dose_ml_ha / 100.0) * p_valor_dose
  END;
$$;


ALTER FUNCTION public.calculate_valor_ha_from_dose(p_dose_ml_ha numeric, p_valor_dose numeric) OWNER TO postgres;

