--
-- Name: can_manage_technical_visit(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_manage_technical_visit(p_user_id uuid, p_registro_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.technical_actor_ready(p_user_id) AND EXISTS (
 SELECT 1 FROM public.registros_consultor r
 WHERE r.id=p_registro_id AND public.technical_refs_in_actor_tenant(r.cliente_id,r.fazenda_id,r.talhao_id)
 AND (public.has_role(p_user_id,'administrador') OR public.has_role(p_user_id,'gestor')
 OR ((public.has_role(p_user_id,'consultor_tecnico') OR public.has_role(p_user_id,'tecnico_agronomo'))
 AND public.technical_client_link(p_user_id,r.cliente_id,ARRAY['execute','manage'])
 AND public.is_visit_responsible(p_user_id,r.id))));
$$;


ALTER FUNCTION public.can_manage_technical_visit(p_user_id uuid, p_registro_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_alerta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_alerta(p_alerta_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_alerta record;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  IF public.has_role(v_uid, 'cliente_produtor'::app_role)
     OR public.has_role(v_uid, 'financeiro'::app_role) THEN
    RETURN false;
  END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role)
     OR public.has_role(v_uid, 'administrativo'::app_role) THEN
    RETURN true;
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN false; END IF;

  IF public.has_role(v_uid, 'consultor_tecnico'::app_role)
     OR public.has_role(v_uid, 'tecnico_agronomo'::app_role) THEN
    RETURN v_alerta.consultor_id = v_uid
        OR v_alerta.responsavel_id = v_uid
        OR v_alerta.criado_por = v_uid;
  END IF;

  IF public.has_role(v_uid, 'producao'::app_role)
     OR public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    RETURN v_alerta.origem IN ('laboratorio','cq','estoque','entrega');
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION public.can_user_access_alerta(p_alerta_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_aplicacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_aplicacao(_aplicacao_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    _aplicacao_id IS NOT NULL
    AND auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.aplicacoes a
      LEFT JOIN public.ordens_servico os ON os.id = a.ordem_servico_id
      LEFT JOIN public.clientes c ON c.id = os.cliente_id
      LEFT JOIN public.ordens_servico_onfarm oso ON oso.id = a.ordem_servico_onfarm_id
      LEFT JOIN public.clientes co ON co.id = oso.cliente_id
      WHERE a.id = _aplicacao_id
        AND a.organization_id = public.h15_actor_organization()
        -- Every present parent must exist and remain in the application's tenant.
        AND (a.ordem_servico_id IS NULL OR (
          os.id IS NOT NULL AND os.organization_id = a.organization_id
          AND c.id IS NOT NULL AND c.organization_id = a.organization_id
        ))
        -- On-farm has no organization_id: its persisted client is the tenant origin.
        AND (a.ordem_servico_onfarm_id IS NULL OR (
          oso.id IS NOT NULL AND co.id IS NOT NULL
          AND co.organization_id = a.organization_id
        ))
        AND (
          public.is_operational_staff(auth.uid())
          OR public.has_role(auth.uid(), 'financeiro'::app_role)
          OR os.cliente_id = ANY (public.get_cliente_ids_for_user(auth.uid()))
          OR oso.cliente_id = ANY (public.get_cliente_ids_for_user(auth.uid()))
        )
    ), false
  );
$$;


ALTER FUNCTION public.can_user_access_aplicacao(_aplicacao_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_arquivo(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_arquivo(_entidade_tipo text, _entidade_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT auth.uid() IS NOT NULL
     AND (
       public.has_role(auth.uid(), 'administrador'::app_role)
       OR public.has_role(auth.uid(), 'gestor'::app_role)
       OR (
         _entidade_id IS NOT NULL AND CASE lower(COALESCE(_entidade_tipo, ''))
           WHEN 'registro_consultor'  THEN public.can_user_access_registro_consultor(_entidade_id)
           WHEN 'registros_consultor' THEN public.can_user_access_registro_consultor(_entidade_id)
           WHEN 'visita'              THEN public.can_user_access_registro_consultor(_entidade_id)
           WHEN 'aplicacao'           THEN public.can_user_access_aplicacao(_entidade_id)
           WHEN 'solicitacao'         THEN public.can_user_access_solicitacao(_entidade_id)
           WHEN 'portal_solicitacao'  THEN public.can_user_access_solicitacao(_entidade_id)
           WHEN 'cliente'             THEN public.can_user_access_cliente(_entidade_id)
           WHEN 'fazenda'             THEN public.can_user_access_fazenda(_entidade_id)
           ELSE false
         END
       )
     );
$$;


ALTER FUNCTION public.can_user_access_arquivo(_entidade_tipo text, _entidade_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_cliente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_cliente(_cliente_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id uuid := auth.uid();
    v_is_admin boolean;
    v_is_gestor boolean;
    v_is_adm_sys boolean;
    v_is_financeiro boolean;
    v_is_comercial boolean;
    v_is_producao boolean;
    v_is_aplicador boolean;
    v_is_onfarm boolean;
    v_is_consultor boolean;
    v_is_tecnico boolean;
    v_is_cliente boolean;
    v_is_b2b boolean;
    v_is_b2b_tec boolean;
    v_partner_id uuid;
BEGIN
    IF v_user_id IS NULL OR _cliente_id IS NULL THEN
        RETURN FALSE;
    END IF;

    v_is_admin := COALESCE(has_role(v_user_id, 'administrador'::app_role), false);
    v_is_gestor := COALESCE(has_role(v_user_id, 'gestor'::app_role), false);
    v_is_adm_sys := COALESCE(has_role(v_user_id, 'administrativo'::app_role), false);
    v_is_financeiro := COALESCE(has_role(v_user_id, 'financeiro'::app_role), false);
    v_is_comercial := COALESCE(has_role(v_user_id, 'gestor_comercial'::app_role), false);
    v_is_producao := COALESCE(has_role(v_user_id, 'producao'::app_role), false);
    v_is_aplicador := COALESCE(has_role(v_user_id, 'aplicador'::app_role), false);
    v_is_onfarm := COALESCE(has_role(v_user_id, 'operador_onfarm'::app_role), false);
    v_is_consultor := COALESCE(has_role(v_user_id, 'consultor_tecnico'::app_role), false);
    v_is_tecnico := COALESCE(has_role(v_user_id, 'tecnico_agronomo'::app_role), false);
    v_is_cliente := COALESCE(has_role(v_user_id, 'cliente_produtor'::app_role), false);
    v_is_b2b := COALESCE(has_role(v_user_id, 'parceiro_b2b'::app_role), false);
    v_is_b2b_tec := COALESCE(has_role(v_user_id, 'parceiro_b2b_tecnico'::app_role), false);

    IF v_is_admin OR v_is_gestor OR v_is_adm_sys OR v_is_financeiro
       OR v_is_comercial OR v_is_producao OR v_is_aplicador OR v_is_onfarm THEN
        RETURN TRUE;
    END IF;

    IF v_is_cliente THEN
        RETURN COALESCE(_cliente_id = ANY(get_cliente_ids_for_user(v_user_id)), false);
    END IF;

    -- HARDENING: carteira ativa e vigente é obrigatória para papéis técnicos.
    IF v_is_consultor OR v_is_tecnico THEN
        RETURN COALESCE(
          public.has_active_user_cliente_access(
            v_user_id, _cliente_id, ARRAY['read','execute','manage']
          ), false);
    END IF;

    IF v_is_b2b_tec THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.technician_user_id = v_user_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          )), false);
    END IF;

    IF v_is_b2b THEN
        v_partner_id := public.get_user_partner_id();
        RETURN COALESCE((
          EXISTS (
            SELECT 1 FROM public.partner_technician_clients ptc
            WHERE ptc.cliente_id = _cliente_id
              AND ptc.partner_id = v_partner_id
              AND ptc.active = true
          ) OR EXISTS (
            SELECT 1 FROM public.partner_clients pc
            WHERE pc.cliente_id = _cliente_id
              AND pc.partner_id = v_partner_id
              AND pc.active = true
          )), false);
    END IF;

    RETURN FALSE;
END;
$$;


ALTER FUNCTION public.can_user_access_cliente(_cliente_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_cliente(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_cliente(_user_id uuid, _cliente_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF _user_id IS NULL OR _cliente_id IS NULL THEN
    RETURN false;
  END IF;

  IF COALESCE(public.has_role(_user_id,'administrador'::app_role), false)
     OR COALESCE(public.has_role(_user_id,'gestor_comercial'::app_role), false)
     OR COALESCE(public.has_role(_user_id,'gestor'::app_role), false)
  THEN
    RETURN true;
  END IF;

  -- HARDENING: papéis técnicos exigem carteira ativa e vigente.
  IF COALESCE(public.has_role(_user_id,'tecnico_agronomo'::app_role), false)
     OR COALESCE(public.has_role(_user_id,'consultor_tecnico'::app_role), false)
  THEN
    RETURN COALESCE(
      public.has_active_user_cliente_access(
        _user_id, _cliente_id, ARRAY['read','execute','manage']
      ), false);
  END IF;

  IF COALESCE(public.has_role(_user_id,'parceiro_b2b'::app_role), false) THEN
    RETURN COALESCE((EXISTS (
      SELECT 1 FROM public.partner_clients pc
      JOIN public.partner_users pu ON pu.partner_id = pc.partner_id
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
      WHERE pu.user_id = _user_id AND pc.cliente_id = _cliente_id AND pc.active = true
        AND pu.revoked_at IS NULL
        AND pa.ativo = true AND pa.deleted_at IS NULL
        AND pa.commercial_owner_organization_id IS NOT NULL
        AND pu.tenant_id IS NOT NULL
        AND pu.tenant_id = pa.commercial_owner_organization_id
    )), false);
  END IF;

  IF COALESCE(public.has_role(_user_id,'parceiro_b2b_tecnico'::app_role), false) THEN
    RETURN COALESCE((EXISTS (
      SELECT 1 FROM public.partner_user_clients puc
      JOIN public.partner_users pu2 ON pu2.partner_id = puc.partner_id AND pu2.user_id = puc.user_id
      JOIN public.partner_accounts pa2 ON pa2.id = puc.partner_id
      WHERE puc.user_id = _user_id AND puc.cliente_id = _cliente_id AND puc.active = true
        AND pu2.revoked_at IS NULL
        AND pa2.ativo = true AND pa2.deleted_at IS NULL
        AND pa2.commercial_owner_organization_id IS NOT NULL
        AND pu2.tenant_id IS NOT NULL
        AND pu2.tenant_id = pa2.commercial_owner_organization_id
    ) OR EXISTS (
      SELECT 1 FROM public.partner_technician_clients ptc
      JOIN public.partner_users pu3 ON pu3.partner_id = ptc.partner_id AND pu3.user_id = ptc.technician_user_id
      JOIN public.partner_accounts pa3 ON pa3.id = ptc.partner_id
      WHERE ptc.technician_user_id = _user_id AND ptc.cliente_id = _cliente_id AND ptc.active = true
        AND pu3.revoked_at IS NULL
        AND pa3.ativo = true AND pa3.deleted_at IS NULL
        AND pa3.commercial_owner_organization_id IS NOT NULL
        AND pu3.tenant_id IS NOT NULL
        AND pu3.tenant_id = pa3.commercial_owner_organization_id
    )), false);
  END IF;

  RETURN COALESCE((EXISTS (
    SELECT 1 FROM public.user_clientes uc
    WHERE uc.user_id = _user_id
      AND uc.cliente_id = _cliente_id
      AND uc.is_active = true
      AND uc.revoked_at IS NULL
      AND (uc.valid_from IS NULL OR uc.valid_from <= now())
      AND (uc.valid_until IS NULL OR uc.valid_until >= now())
  )), false);
END;
$$;


ALTER FUNCTION public.can_user_access_cliente(_user_id uuid, _cliente_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_estoque_embalagem(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_estoque_embalagem(p_embalagem_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_cli uuid; v_status text; v_entrega uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  SELECT cliente_id, status, entrega_id INTO v_cli, v_status, v_entrega
    FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role) THEN
    RETURN true;
  END IF;
  IF public.has_role(v_uid,'financeiro'::app_role) THEN
    RETURN v_entrega IS NOT NULL;
  END IF;
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role) THEN
    RETURN v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    RETURN v_status='entregue' AND v_cli IS NOT NULL AND EXISTS(
      SELECT 1 FROM public.user_clientes WHERE user_id=v_uid AND cliente_id=v_cli);
  END IF;
  RETURN false;
END $$;


ALTER FUNCTION public.can_user_access_estoque_embalagem(p_embalagem_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_fazenda(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_fazenda(_fazenda_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.fazendas f
    WHERE f.id = _fazenda_id
    AND can_user_access_cliente(f.cliente_id)
  );
$$;


ALTER FUNCTION public.can_user_access_fazenda(_fazenda_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_produto_etiqueta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_produto_etiqueta(p_etiqueta_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_cliente_id uuid;
  v_gerada_por uuid;
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;

  -- Perfis internos com acesso total
  IF public.has_role(v_uid,'administrador'::app_role)
     OR public.has_role(v_uid,'gestor'::app_role)
     OR public.has_role(v_uid,'producao'::app_role)
     OR public.has_role(v_uid,'operador_onfarm'::app_role)
     OR public.has_role(v_uid,'administrativo'::app_role)
     OR public.has_role(v_uid,'financeiro'::app_role)
  THEN
    RETURN true;
  END IF;

  SELECT cliente_id, gerada_por
    INTO v_cliente_id, v_gerada_por
    FROM public.produto_etiquetas
   WHERE id = p_etiqueta_id;

  IF NOT FOUND THEN RETURN false; END IF;

  -- Cliente produtor: apenas etiquetas dos seus clientes
  IF public.has_role(v_uid,'cliente_produtor'::app_role) THEN
    IF v_cliente_id IS NULL THEN RETURN false; END IF;
    RETURN EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    );
  END IF;

  -- Consultor/técnico: regra conservadora — apenas se gerada por ele
  -- ou se estiver vinculado ao cliente em user_clientes
  IF public.has_role(v_uid,'consultor_tecnico'::app_role)
     OR public.has_role(v_uid,'tecnico_agronomo'::app_role)
  THEN
    IF v_gerada_por = v_uid THEN RETURN true; END IF;
    IF v_cliente_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.user_clientes uc
       WHERE uc.user_id = v_uid AND uc.cliente_id = v_cliente_id
    ) THEN
      RETURN true;
    END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION public.can_user_access_produto_etiqueta(p_etiqueta_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_registro_consultor(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_registro_consultor(_registro_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _registro_id IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND (
       public.has_role(auth.uid(), 'administrador'::app_role)
       OR public.has_role(auth.uid(), 'gestor'::app_role)
       OR public.can_view_technical_visit(auth.uid(), _registro_id)
       OR EXISTS (
            SELECT 1 FROM public.registros_consultor r
            WHERE r.id = _registro_id
              AND (
                r.consultor_responsavel = auth.uid()
                OR r.created_by = auth.uid()
                OR r.finalized_by = auth.uid()
                OR r.cliente_id = ANY (public.get_cliente_ids_for_user(auth.uid()))
              )
          )
     );
$$;


ALTER FUNCTION public.can_user_access_registro_consultor(_registro_id uuid) OWNER TO postgres;

--
-- Name: can_user_access_solicitacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_access_solicitacao(_solicitacao_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.technical_actor_ready(auth.uid()) AND EXISTS (
 SELECT 1 FROM public.portal_solicitacoes s WHERE s.id=_solicitacao_id
 AND public.technical_refs_in_actor_tenant(s.cliente_id,s.fazenda_id,s.talhao_id)
 AND (public.has_role(auth.uid(),'administrador') OR public.has_role(auth.uid(),'gestor')
 OR ((public.has_role(auth.uid(),'consultor_tecnico') OR public.has_role(auth.uid(),'tecnico_agronomo') OR public.has_role(auth.uid(),'aplicador'))
 AND public.technical_client_link(auth.uid(),s.cliente_id,ARRAY['read','execute','manage'])
 AND (s.consultor_atribuido=auth.uid() OR s.created_by=auth.uid() OR s.user_id=auth.uid()))
 OR (public.has_role(auth.uid(),'cliente_produtor') AND s.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid())))));
$$;


ALTER FUNCTION public.can_user_access_solicitacao(_solicitacao_id uuid) OWNER TO postgres;

--
-- Name: can_user_create_aplicacao_for_cliente(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_create_aplicacao_for_cliente(_cliente_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
                                                                                                                              SELECT auth.uid() IS NOT NULL AND _cliente_id IS NOT NULL AND public.can_user_access_cliente(_cliente_id) AND (
                                                                                                                                  public.has_role(auth.uid(), 'administrador'::public.app_role)
                                                                                                                                      OR public.has_role(auth.uid(), 'gestor'::public.app_role)
                                                                                                                                          OR public.has_role(auth.uid(), 'administrativo'::public.app_role)
                                                                                                                                              OR public.has_role(auth.uid(), 'tecnico_agronomo'::public.app_role)
                                                                                                                                                  OR public.has_role(auth.uid(), 'consultor_tecnico'::public.app_role)
                                                                                                                                                      OR public.has_role(auth.uid(), 'aplicador'::public.app_role)
                                                                                                                                                          OR public.has_role(auth.uid(), 'operador_onfarm'::public.app_role)
                                                                                                                                                              OR public.has_role(auth.uid(), 'cliente_produtor'::public.app_role)
                                                                                                                                                                );
                                                                                                                                                                $$;


ALTER FUNCTION public.can_user_create_aplicacao_for_cliente(_cliente_id uuid) OWNER TO postgres;

--
-- Name: can_user_manage_aplicacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_manage_aplicacao(_aplicacao_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _aplicacao_id IS NOT NULL
     AND auth.uid() IS NOT NULL
     AND (
       public.has_role(auth.uid(), 'administrador'::app_role)
       OR public.has_role(auth.uid(), 'gestor'::app_role)
       OR public.has_role(auth.uid(), 'administrativo'::app_role)
       OR public.has_role(auth.uid(), 'consultor_tecnico'::app_role)
       OR public.has_role(auth.uid(), 'aplicador'::app_role)
     )
     AND EXISTS (SELECT 1 FROM public.aplicacoes a WHERE a.id = _aplicacao_id);
$$;


ALTER FUNCTION public.can_user_manage_aplicacao(_aplicacao_id uuid) OWNER TO postgres;

--
-- Name: can_user_manage_estoque_embalagem(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_user_manage_estoque_embalagem(p_embalagem_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RETURN false; END IF;
  RETURN public.has_role(v_uid,'administrador'::app_role)
      OR public.has_role(v_uid,'gestor'::app_role)
      OR public.has_role(v_uid,'producao'::app_role)
      OR public.has_role(v_uid,'operador_onfarm'::app_role);
END $$;


ALTER FUNCTION public.can_user_manage_estoque_embalagem(p_embalagem_id uuid) OWNER TO postgres;

--
-- Name: can_view_bi_operacional(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_view_bi_operacional(_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT _uid IS NOT NULL AND (
    public.has_role(_uid, 'administrador')
    OR public.has_role(_uid, 'gestor')
    OR public.has_role(_uid, 'administrativo')
    OR public.has_role(_uid, 'producao')
    OR public.has_role(_uid, 'financeiro')
    OR public.has_role(_uid, 'consultor_tecnico')
    OR public.has_role(_uid, 'tecnico_agronomo')
  );
$$;


ALTER FUNCTION public.can_view_bi_operacional(_uid uuid) OWNER TO postgres;

--
-- Name: can_view_catalog_internal(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_view_catalog_internal(_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT _uid IS NOT NULL
     AND (auth.uid() IS NULL AND current_user IN ('service_role','postgres') OR _uid = auth.uid())
     AND (
       public.is_platform_superadmin(_uid)
       OR (
         EXISTS (SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id = p.organization_id
                  WHERE p.user_id = _uid AND p.ativo = true AND o.ativo = true AND o.status = 'ativa')
         AND (public.has_role(_uid,'administrador') OR public.has_role(_uid,'gestor')
           OR public.has_role(_uid,'consultor_tecnico') OR public.has_role(_uid,'tecnico_agronomo')
           OR public.has_role(_uid,'gestor_comercial') OR public.has_role(_uid,'operador_onfarm')
           OR public.has_role(_uid,'producao') OR public.has_role(_uid,'administrativo')
           OR public.has_role(_uid,'financeiro'))
         AND EXISTS (SELECT 1 FROM platform_private.entitlements_for_user(_uid) e WHERE e.feature_key = 'catalogo_precos')
       )
     );
$$;


ALTER FUNCTION public.can_view_catalog_internal(_uid uuid) OWNER TO postgres;

