--
-- Name: cancel_financial_receipt(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_financial_receipt(_receipt_id uuid, _reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid; v_rec record;
BEGIN
 v_org:=public.h15_actor_organization();
 IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado' USING ERRCODE='42501'; END IF;
 IF _reason IS NULL OR length(trim(_reason))<5 THEN RAISE EXCEPTION 'Motivo do cancelamento é obrigatório (mín. 5 caracteres)'; END IF;
 SELECT * INTO v_rec FROM public.financial_receipts WHERE id=_receipt_id AND organization_id=v_org;
 IF NOT FOUND THEN RAISE EXCEPTION 'Recibo não encontrado' USING ERRCODE='42501'; END IF;
 IF v_rec.status='CANCELED' THEN RAISE EXCEPTION 'Recibo já cancelado'; END IF;
 IF NOT (public.has_role(auth.uid(),'administrador'::public.app_role) OR public.has_role(auth.uid(),'gestor'::public.app_role)) AND v_rec.issued_at::date<>CURRENT_DATE THEN RAISE EXCEPTION 'Apenas administrador/gestor podem cancelar recibos de outros dias'; END IF;
 UPDATE public.financial_receipts SET status='CANCELED',cancel_reason=_reason,canceled_by=auth.uid(),canceled_at=now() WHERE id=_receipt_id AND organization_id=v_org;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,new_data,performed_by,reason) VALUES('financial_receipts',_receipt_id,'FINANCIAL_RECEIPT_CANCELED',jsonb_build_object('reason',_reason),auth.uid(),_reason);
END $$;


ALTER FUNCTION public.cancel_financial_receipt(_receipt_id uuid, _reason text) OWNER TO postgres;

--
-- Name: catalog_audit_log(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.catalog_audit_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_entidade text := TG_ARGV[0];
  v_old jsonb;
  v_new jsonb;
  v_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_old := to_jsonb(OLD); v_new := NULL; v_id := OLD.id;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD); v_new := to_jsonb(NEW); v_id := NEW.id;
  ELSE
    v_old := NULL; v_new := to_jsonb(NEW); v_id := NEW.id;
  END IF;

  INSERT INTO public.catalog_technical_audit_logs(entidade_tipo, entidade_id, acao, dados_anteriores, dados_novos, usuario_id)
  VALUES (v_entidade, v_id, lower(TG_OP), v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.catalog_audit_log() OWNER TO postgres;

--
-- Name: catalog_family_labels_read(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.catalog_family_labels_read(p_familia text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid := auth.uid(); v_result jsonb;
BEGIN
  IF v_uid IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = v_uid AND p.ativo = true) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_label_read_forbidden';
  END IF;
  IF p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_family_invalid';
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'familia', l.familia, 'rotulo', l.rotulo, 'rotulo_exibicao', l.rotulo_exibicao)
    ORDER BY pg_catalog.lower(l.rotulo_exibicao) COLLATE "C", l.id), '[]'::jsonb)
  INTO v_result
  FROM public.catalog_family_labels l
  WHERE l.familia = p_familia AND l.ativo = true;
  RETURN v_result;
END $$;


ALTER FUNCTION public.catalog_family_labels_read(p_familia text) OWNER TO postgres;

