--
-- Name: catalog_sources_set_source_key(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.catalog_sources_set_source_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref text;
BEGIN
  v_ref := coalesce(NEW.fonte_url, NEW.fonte_titulo, '');
  v_ref := regexp_replace(trim(lower(v_ref)), '\s+', ' ', 'g');
  NEW.source_key := lower(md5(
    trim(lower(coalesce(NEW.entidade_tipo, ''))) || ':' ||
    trim(lower(coalesce(NEW.entidade_id::text, ''))) || ':' ||
    v_ref
  ));
  RETURN NEW;
END;
$$;


