--
-- Name: client_document_download_snapshot(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.client_document_download_snapshot(_name text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH actor AS MATERIALIZED (
    SELECT auth.uid() AS uid, public.h15_actor_organization() AS org
    WHERE auth.uid() IS NOT NULL
      AND length(_name) BETWEEN 1 AND 1024
      AND public.cliente_storage_object_permitted(_name)
  ), roles AS MATERIALIZED (
    SELECT jsonb_agg(r.role::text ORDER BY r.role::text) AS value
    FROM public.user_roles r JOIN actor a ON r.user_id = a.uid
  ), docs AS MATERIALIZED (
    SELECT d.id, d.cliente_id, d.arquivo_path, d.tamanho_bytes, d.mime, a.uid, a.org
    FROM public.cliente_documentos d
    JOIN public.clientes c ON c.id = d.cliente_id
    JOIN actor a ON c.organization_id = a.org
    WHERE d.arquivo_path = _name
      AND public.can_user_access_cliente(c.id)
  )
  SELECT CASE WHEN (SELECT count(*) FROM docs) = 1
    AND jsonb_array_length(coalesce((SELECT value FROM roles), '[]'::jsonb)) > 0
    THEN (SELECT jsonb_build_object('actor', uid, 'tenant', org,
      'roles', (SELECT value FROM roles), 'document', id, 'client', cliente_id,
      'path', arquivo_path, 'size', tamanho_bytes, 'mime', mime) FROM docs)
    ELSE NULL END;
$$;


ALTER FUNCTION public.client_document_download_snapshot(_name text) OWNER TO postgres;

--
-- Name: client_documents_backup_snapshot(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.client_documents_backup_snapshot(_client uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  SELECT CASE WHEN auth.uid() IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.clientes c WHERE c.id = _client
      AND c.organization_id = public.h15_actor_organization()
      AND public.can_user_access_cliente(c.id)
  ) THEN coalesce((SELECT jsonb_agg(jsonb_build_object(
    'doc', to_jsonb(d), 'proof', public.client_document_download_snapshot(d.arquivo_path)) ORDER BY d.id)
    FROM public.cliente_documentos d WHERE d.cliente_id = _client), '[]'::jsonb) ELSE NULL END;
$$;


ALTER FUNCTION public.client_documents_backup_snapshot(_client uuid) OWNER TO postgres;

--
-- Name: cliente_storage_object_permitted(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cliente_storage_object_permitted(_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE
  v_org uuid;
  v_parts text[];
  v_cliente uuid;
BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
  v_org := public.h15_actor_organization();
  v_parts := storage.foldername(_name);
  IF v_org IS NULL
     OR array_length(v_parts, 1) < 3
     OR v_parts[1] <> v_org::text
     OR v_parts[2] <> 'clientes' THEN
    RETURN false;
  END IF;
  BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
    v_cliente := v_parts[3]::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RETURN false;
  END;
  RETURN EXISTS (
    SELECT 1
      FROM public.clientes c
     WHERE c.id = v_cliente
       AND c.organization_id = v_org
       AND public.can_user_access_cliente(c.id)
  );
END
$$;


ALTER FUNCTION public.cliente_storage_object_permitted(_name text) OWNER TO postgres;

