--
-- Name: comunicacao_templates_guard_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comunicacao_templates_guard_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'active' THEN
    IF (NEW.corpo, NEW.assunto, NEW.variaveis, NEW.canal, NEW.chave, NEW.versao, NEW.locale)
       IS DISTINCT FROM
       (OLD.corpo, OLD.assunto, OLD.variaveis, OLD.canal, OLD.chave, OLD.versao, OLD.locale) THEN
      RAISE EXCEPTION 'template ativo imutável (chave=% canal=% versao=%)',
        OLD.chave, OLD.canal, OLD.versao USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status NOT IN ('active','archived') THEN
      RAISE EXCEPTION 'template ativo só transita para archived' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END$$;


ALTER FUNCTION public.comunicacao_templates_guard_immutable() OWNER TO postgres;

--
-- Name: convert_partner_simulation_to_order_secure(uuid, text, uuid, date, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.convert_partner_simulation_to_order_secure(p_simulation_id uuid, p_observacoes text DEFAULT NULL::text, p_payment_plan_id uuid DEFAULT NULL::uuid, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_confirm_price_change boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_partner_b2b boolean; v_is_tecnico boolean;
  v_user_partner uuid; v_sim record; v_partner_id uuid;
  v_items jsonb; v_result jsonb; v_order_id uuid;
  v_cart jsonb; v_new_table numeric(14,2);
  v_plan record; v_quote boolean; v_final numeric(14,2); v_hash text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF p_payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  v_is_admin := has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial');
  v_is_partner_b2b := has_role(v_uid,'parceiro_b2b');
  v_is_tecnico := has_role(v_uid,'parceiro_b2b_tecnico');

  IF v_is_tecnico AND NOT v_is_admin AND NOT v_is_partner_b2b THEN
    RAISE EXCEPTION 'forbidden_role_tecnico_cannot_convert';
  END IF;
  IF NOT (v_is_admin OR v_is_partner_b2b) THEN RAISE EXCEPTION 'forbidden_role'; END IF;

  SELECT * INTO v_sim FROM public.partner_simulations WHERE id = p_simulation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'simulation_not_found'; END IF;
  IF v_sim.status = 'convertida_pedido' THEN RAISE EXCEPTION 'already_converted'; END IF;
  IF v_sim.status NOT IN ('rascunho','enviada_gestor') THEN RAISE EXCEPTION 'invalid_status'; END IF;

  v_partner_id := v_sim.partner_id;
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, v_partner_id);
  IF v_is_partner_b2b AND NOT v_is_admin THEN
    v_user_partner := get_user_partner_id();
    IF v_user_partner IS NULL OR v_user_partner <> v_partner_id THEN RAISE EXCEPTION 'forbidden_partner'; END IF;
  END IF;

  IF v_sim.valid_until IS NOT NULL AND v_sim.valid_until < current_date
     AND NOT p_confirm_price_change THEN
    RAISE EXCEPTION 'simulation_expired_requires_confirmation';
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'item_id', item_id, 'item_tipo', item_tipo, 'quantidade', quantidade,
           'unidade_medida', COALESCE(unidade_medida,'hectare'), 'volume_ml', volume_ml)), '[]'::jsonb)
    INTO v_items
  FROM public.partner_simulation_items WHERE simulation_id = p_simulation_id;
  IF v_items = '[]'::jsonb THEN RAISE EXCEPTION 'empty_simulation'; END IF;

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = p_payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF; IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;

  -- Revalidacao autoritativa do preco no momento da conversao
  v_cart := public.fn_resolve_b2b_cart(v_partner_id, p_payment_plan_id, v_items, current_date);
  v_new_table := (v_cart->>'table_amount')::numeric;

  IF COALESCE(v_sim.total_cheio,0) > 0
     AND ABS(v_new_table - v_sim.total_cheio) > 0.01
     AND NOT p_confirm_price_change THEN
    RAISE EXCEPTION 'price_changed_requires_confirmation: simulado=% atual=%',
      v_sim.total_cheio, v_new_table USING ERRCODE='P0001';
  END IF;

  -- assinatura calculada no servidor a partir do carrinho recem-resolvido
  v_quote := COALESCE((v_cart->>'quote_required')::boolean,false);
  v_final := CASE WHEN v_quote THEN 0
                  ELSE public.fn_b2b_apply_interest((v_cart->>'net_amount')::numeric,
                         v_plan.interest_type, v_plan.monthly_interest_percent, v_plan.months_count) END;
  v_hash := public.fn_b2b_cart_hash(v_partner_id, p_payment_plan_id, v_cart, v_final);

  v_result := public.create_partner_order_secure(
    v_partner_id, COALESCE(p_observacoes, v_sim.observacoes), v_items,
    NULL, p_payment_plan_id, p_first_due_date, p_installment_count,
    v_hash, 'sim:' || p_simulation_id::text);
  v_order_id := (v_result->>'id')::uuid;

  UPDATE public.partner_orders
     SET origin_simulation_id = p_simulation_id, cliente_id = v_sim.cliente_id
   WHERE id = v_order_id;

  UPDATE public.partner_simulations
     SET status='convertida_pedido', converted_order_id=v_order_id,
         converted_by=v_uid, converted_at=now(), updated_at=now()
   WHERE id = p_simulation_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_order_id, v_partner_id, v_uid, 'converted_from_simulation',
          jsonb_build_object('simulation_id', p_simulation_id, 'numero', v_result->>'numero',
                             'cliente_id', v_sim.cliente_id, 'total', v_result->>'total',
                             'cart_hash', v_hash,
                             'price_change_confirmed', p_confirm_price_change));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_converted_to_order', v_partner_id, v_uid, v_sim.cliente_id,
    p_simulation_id, v_order_id, NULL, jsonb_build_object('total', v_result->>'total'));

  RETURN v_order_id;
END $$;


ALTER FUNCTION public.convert_partner_simulation_to_order_secure(p_simulation_id uuid, p_observacoes text, p_payment_plan_id uuid, p_first_due_date date, p_installment_count integer, p_confirm_price_change boolean) OWNER TO postgres;

--
-- Name: create_partner_order_secure(uuid, text, jsonb, date, uuid, date, integer, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_partner_order_secure(p_partner_id uuid, p_observacoes text DEFAULT NULL::text, p_items jsonb DEFAULT '[]'::jsonb, p_requested_delivery_date date DEFAULT NULL::date, p_payment_plan_id uuid DEFAULT NULL::uuid, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_expected_cart_hash text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_finance boolean; v_is_gestor boolean; v_is_internal boolean;
  v_is_partner boolean; v_is_partner_tech boolean; v_user_partner uuid;
  v_order_id uuid; v_numero text; v_plan record; v_cart jsonb; v_line jsonb;
  v_quote boolean; v_table numeric(14,2); v_disc numeric(14,2); v_net numeric(14,2);
  v_interest numeric(14,2); v_final numeric(14,2); v_hash text;
  v_installments integer; v_first_due date; v_terms_id uuid;
  v_status partner_order_status; v_fin_status text; v_approval_status text;
  v_credit jsonb; v_block_reason text := NULL;
  v_inst numeric(14,2); v_accum numeric(14,2) := 0;
  v_amount_i numeric(14,2); v_principal_i numeric(14,2); v_interest_i numeric(14,2);
  v_due_i date; v_admin record; i integer;
  v_idem text; v_prev_idem record; v_result jsonb;
  v_items_canon text; v_req_fp text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  PERFORM platform_private.c2_order_actor_scope(v_uid, p_partner_id); -- c2_ord_scope
  PERFORM platform_private.c2_owner_order_guard(v_uid, p_partner_id, p_payment_plan_id); -- c2_ord_guard
  IF p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'empty_cart'; END IF;
  IF p_payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  -- assinatura autoritativa obrigatoria para TODOS os chamadores
  IF NULLIF(btrim(COALESCE(p_expected_cart_hash,'')),'') IS NULL THEN
    RAISE EXCEPTION 'cart_hash_required';
  END IF;
  v_idem := NULLIF(btrim(COALESCE(p_idempotency_key,'')),'');
  IF v_idem IS NULL THEN RAISE EXCEPTION 'idempotency_key_required'; END IF;
  IF length(v_idem) > 120 THEN RAISE EXCEPTION 'invalid_idempotency_key'; END IF;

  -- ---------------------------------------------------------------
  -- request fingerprint canônico: reqfp_v2
  -- Cobre todos os parâmetros materialmente capazes de alterar o
  -- pedido resultante. Itens são normalizados (tipo|id|quantidade
  -- numérica canônica) e ordenados deterministicamente; textos são
  -- normalizados por btrim. cart_hash continua validado à parte.
  -- ---------------------------------------------------------------
  SELECT COALESCE(string_agg(t, ';' ORDER BY t), '')
    INTO v_items_canon
    FROM (
      SELECT lower(COALESCE(btrim(l->>'item_tipo'), '-')) || '|' ||
             lower(COALESCE(btrim(l->>'item_id'), '-'))   || '|' ||
             COALESCE(trim(to_char(COALESCE(NULLIF(btrim(l->>'quantidade'),'')::numeric, 0),
                                   'FM9999999990.000000')), '0') AS t
        FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) AS l
    ) s;

  v_req_fp := encode(sha256(convert_to(
      'reqfp_v2'
      || '|partner='   || p_partner_id::text
      || '|plan='      || COALESCE(p_payment_plan_id::text,'-')
      || '|delivery='  || COALESCE(p_requested_delivery_date::text,'-')
      || '|firstdue='  || COALESCE(p_first_due_date::text,'-')
      || '|inst='      || COALESCE(p_installment_count::text,'-')
      || '|obs='       || COALESCE(btrim(p_observacoes),'-')
      || '|items='     || v_items_canon
    ,'UTF8')),'hex');

  v_is_admin        := has_role(v_uid,'administrador'::app_role);
  v_is_finance      := has_role(v_uid,'financeiro'::app_role);
  v_is_gestor       := has_role(v_uid,'gestor_comercial'::app_role);
  v_is_internal     := v_is_admin OR v_is_finance OR v_is_gestor;
  v_is_partner      := has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_partner_tech := has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
  v_user_partner    := public.get_user_partner_id();

  IF has_role(v_uid,'cliente_produtor'::app_role) AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED';
  END IF;

  IF v_is_partner_tech AND NOT (v_is_internal OR v_is_partner) THEN
    RAISE EXCEPTION 'partner_tech_cannot_create_order';
  END IF;

  IF NOT v_is_internal THEN
    IF NOT v_is_partner OR v_user_partner IS NULL OR v_user_partner <> p_partner_id THEN
      RAISE EXCEPTION 'forbidden_partner';
    END IF;
  END IF;

  PERFORM 1 FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true;
  IF NOT FOUND THEN RAISE EXCEPTION 'partner_not_found'; END IF;

  -- idempotencia (lock deterministico #1: parceiro+chave)
  PERFORM platform_private.c2_attempt_dispatch_guard(v_uid,p_partner_id,v_idem);
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_idem:' || p_partner_id::text || ':' || v_idem, 0));
  -- c2_attempt_closure_v2: a espera no lock pode atravessar revogações; revalida a
  -- autorização canônica APÓS o lock e antes de revelar replay ou criar (ponto de
  -- linearização = esta instrução; revogação confirmada depois dela não é observada).
  PERFORM platform_private.c2_partner_order_attempt_authz(v_uid, p_partner_id);
  IF NOT EXISTS(SELECT 1 FROM platform_private.partner_order_attempt_journal j JOIN public.profiles p ON p.user_id=j.actor_id AND p.organization_id=j.organization_id AND p.ativo WHERE j.actor_id=v_uid AND j.partner_id=p_partner_id AND j.idempotency_key=v_idem) THEN RAISE EXCEPTION 'C2DJ_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  -- Fechamento durável sob ESTE MESMO lock: recusa envio tardio antes de qualquer efeito.
  -- (Corpos antigos em voo são cobertos pelo trigger c2_attempt_closure_guard.)
  IF EXISTS (SELECT 1 FROM platform_private.partner_order_idempotency_closures c
              WHERE c.partner_id = p_partner_id AND c.idempotency_key = v_idem) THEN
    RAISE EXCEPTION 'idempotency_key_closed';
  END IF;
  SELECT * INTO v_prev_idem FROM public.partner_order_idempotency
   WHERE partner_id = p_partner_id AND idempotency_key = v_idem;
  IF FOUND THEN
    -- linhas históricas sem fingerprint não podem ser reexecutadas em
    -- silêncio apenas com cart_hash: fail-safe, sem criar pedido.
    IF v_prev_idem.request_fingerprint IS NULL THEN
      RAISE EXCEPTION 'idempotency_legacy_unverifiable';
    END IF;
    IF v_prev_idem.cart_hash IS DISTINCT FROM p_expected_cart_hash THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    IF v_prev_idem.request_fingerprint IS DISTINCT FROM v_req_fp THEN
      RAISE EXCEPTION 'idempotency_conflict';
    END IF;
    RETURN v_prev_idem.result_snapshot;
  END IF;

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = p_payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;
  IF v_plan.active = false THEN RAISE EXCEPTION 'plan_inactive'; END IF;
  IF v_plan.monthly_interest_percent < 0 THEN RAISE EXCEPTION 'invalid_interest_rate'; END IF;
  IF v_plan.discount_percent > 40 AND NOT v_is_admin THEN RAISE EXCEPTION 'discount_exceeds_limit'; END IF;

  v_credit := public.fn_b2b_credit_exposure(p_partner_id, 0, NULL);
  IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
     AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
    RAISE EXCEPTION 'credit_blocked_overdue';
  END IF;

  IF NOT v_is_internal THEN
    v_installments := GREATEST(COALESCE(v_plan.installment_count,1),1);
  ELSE
    IF p_installment_count IS NOT NULL AND p_installment_count <= 0 THEN
      RAISE EXCEPTION 'invalid_installment_count';
    END IF;
    v_installments := GREATEST(COALESCE(p_installment_count, v_plan.installment_count, 1), 1);
  END IF;

  v_cart  := public.fn_resolve_b2b_cart(p_partner_id, p_payment_plan_id, p_items, current_date);
  v_quote := COALESCE((v_cart->>'quote_required')::boolean,false);
  v_table := (v_cart->>'table_amount')::numeric;
  v_disc  := (v_cart->>'discount_amount')::numeric;
  v_net   := (v_cart->>'net_amount')::numeric;
  v_final := CASE WHEN v_quote THEN 0
                  ELSE public.fn_b2b_apply_interest(v_net, v_plan.interest_type,
                         v_plan.monthly_interest_percent, v_plan.months_count) END;

  v_hash := public.fn_b2b_cart_hash(p_partner_id, p_payment_plan_id, v_cart, v_final);
  IF p_expected_cart_hash <> v_hash THEN
    RAISE EXCEPTION 'price_changed';
  END IF;

  IF v_quote THEN v_table := 0; v_disc := 0; v_net := 0; END IF;
  v_interest := ROUND(v_final - v_net, 2);

  IF NOT v_quote AND v_plan.minimum_order_amount IS NOT NULL AND v_table < v_plan.minimum_order_amount THEN
    RAISE EXCEPTION 'below_minimum_order_amount';
  END IF;

  IF p_first_due_date IS NOT NULL AND p_first_due_date < current_date THEN
    RAISE EXCEPTION 'invalid_due_date';
  END IF;
  v_first_due := COALESCE(p_first_due_date, current_date + v_plan.max_days);

  IF v_plan.requires_financial_approval OR v_plan.requires_guarantee THEN
    v_fin_status := 'pending'; v_approval_status := 'pending';
  ELSE
    v_fin_status := 'not_required'; v_approval_status := 'not_required';
  END IF;

  IF v_first_due > current_date + v_plan.max_days THEN
    IF NOT v_is_internal OR NOT (v_plan.requires_financial_approval OR v_plan.requires_guarantee) THEN
      v_first_due := current_date + v_plan.max_days;
    ELSE
      v_fin_status := 'pending'; v_approval_status := 'pending';
    END IF;
  END IF;

  IF v_quote THEN
    v_status := 'aguardando_cotacao'::partner_order_status;
  ELSE
    -- lock deterministico #2: credito do parceiro
    PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || p_partner_id::text, 0));
    v_credit := public.fn_b2b_credit_exposure(p_partner_id, v_final, NULL);

    IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
       AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
      RAISE EXCEPTION 'credit_blocked_overdue';
    END IF;

    IF COALESCE((v_credit->>'credit_limit')::numeric,0) > 0
       AND (v_credit->>'exposicao_projetada')::numeric > (v_credit->>'credit_limit')::numeric THEN
      IF COALESCE(v_credit->>'credit_limit_action','block') = 'approval_required' THEN
        v_status := 'aguardando_aprovacao_credito'::partner_order_status;
        v_block_reason := 'limite_excedido';
      ELSE
        RAISE EXCEPTION 'credit_limit_exceeded';
      END IF;
    ELSE
      v_status := 'em_analise_comercial'::partner_order_status;
    END IF;
  END IF;

  -- Issue only after canonical role/partner/plan/cart/hash/credit checks and idempotent replay.
  IF NOT v_is_internal AND platform_private.c2_owner_order_create_allowed(v_uid,p_partner_id) THEN
    PERFORM platform_private.issue_ticket('c2_external_order_create',p_partner_id);
  END IF;
  INSERT INTO public.partner_orders(
    partner_id, status, subtotal, desconto_total, total, observacoes, created_by,
    requested_delivery_date, ready_for_production, payment_plan_id, payment_condition_status,
    credit_block_reason
  ) VALUES (
    p_partner_id, v_status, 0, 0, 0, NULLIF(p_observacoes,''), v_uid,
    p_requested_delivery_date, false, p_payment_plan_id,
    CASE WHEN v_quote THEN 'quote_required' ELSE 'defined' END,
    v_block_reason
  ) RETURNING id, numero INTO v_order_id, v_numero;

  FOR v_line IN SELECT * FROM jsonb_array_elements(v_cart->'lines') LOOP
    INSERT INTO public.partner_order_items(
      order_id, product_id, microrganismo_id, quantidade, preco_unitario,
      desconto_percentual, subtotal, unidade_medida, volume_ml,
      produto_nome_snapshot, produto_codigo_snapshot,
      preco_tabela_snapshot, desconto_percentual_snapshot, preco_unitario_final_snapshot,
      pricing_mode_snapshot, price_source_snapshot, base_price_snapshot,
      condition_price_snapshot, plan_discount_percent_snapshot,
      unit_type_snapshot, volume_ml_snapshot, price_rule_id_snapshot
    ) VALUES (
      v_order_id,
      CASE WHEN v_line->>'item_tipo'='produto' THEN (v_line->>'item_id')::uuid END,
      CASE WHEN v_line->>'item_tipo'='microrganismo' THEN (v_line->>'item_id')::uuid END,
      (v_line->>'quantidade')::numeric,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'final_unit_price')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'plan_discount_percent')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'line_final_amount')::numeric, 0) END,
      v_line->>'unidade_medida',
      NULLIF(v_line->>'volume_ml','')::numeric,
      v_line->>'nome', v_line->>'codigo',
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'base_price')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'plan_discount_percent')::numeric, 0) END,
      CASE WHEN v_quote THEN 0 ELSE COALESCE((v_line->>'final_unit_price')::numeric, 0) END,
      v_line->>'pricing_mode', v_line->>'price_source',
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'base_price','')::numeric END,
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'condition_price','')::numeric END,
      CASE WHEN v_quote THEN NULL ELSE NULLIF(v_line->>'plan_discount_percent','')::numeric END,
      v_line->>'unidade_medida',
      NULLIF(v_line->>'volume_ml','')::numeric,
      NULLIF(v_line->>'rule_id','')::uuid
    );
  END LOOP;

  IF NOT v_quote THEN
    INSERT INTO public.partner_order_payment_terms(
      partner_order_id, payment_plan_id, plan_name_snapshot, plan_code_snapshot,
      discount_percent_snapshot, monthly_interest_percent_snapshot, months_count_snapshot,
      installment_count, first_due_date, interest_type_snapshot,
      table_amount, discount_amount, net_amount_after_discount,
      financial_interest_amount, final_amount, approval_status, created_by,
      pricing_mode_snapshot, credit_decision_snapshot
    ) VALUES (
      v_order_id, v_plan.id, v_plan.name, v_plan.code,
      v_plan.discount_percent, v_plan.monthly_interest_percent, v_plan.months_count,
      v_installments, v_first_due, v_plan.interest_type,
      v_table, v_disc, v_net, v_interest, v_final, v_approval_status, v_uid,
      COALESCE(v_plan.pricing_mode,'discount_from_base'), v_credit
    ) RETURNING id INTO v_terms_id;

    IF v_installments = 1 THEN
      INSERT INTO public.partner_order_payment_schedule(
        partner_order_id, payment_terms_id, installment_number, due_date,
        amount, principal_amount, interest_amount)
      VALUES (v_order_id, v_terms_id, 1, v_first_due, v_final, v_net, v_interest);
    ELSE
      v_inst := ROUND(v_final / v_installments, 2);
      FOR i IN 1..v_installments LOOP
        IF i < v_installments THEN v_amount_i := v_inst; ELSE v_amount_i := ROUND(v_final - v_accum,2); END IF;
        v_accum := v_accum + v_amount_i;
        v_principal_i := ROUND(v_amount_i * (v_net / NULLIF(v_final,0)), 2);
        v_interest_i  := ROUND(v_amount_i - v_principal_i, 2);
        v_due_i := v_first_due + ((i-1)*30);
        INSERT INTO public.partner_order_payment_schedule(
          partner_order_id, payment_terms_id, installment_number, due_date,
          amount, principal_amount, interest_amount)
        VALUES (v_order_id, v_terms_id, i, v_due_i, v_amount_i, v_principal_i, v_interest_i);
      END LOOP;
    END IF;
  END IF;

  UPDATE public.partner_orders SET
    subtotal = v_table, desconto_total = v_disc, total = v_final,
    payment_terms_id = v_terms_id,
    table_amount = v_table, commercial_discount_amount = v_disc,
    net_amount_after_discount = v_net, financial_interest_amount = v_interest,
    final_amount_with_interest = v_final,
    requires_financial_approval = (NOT v_quote AND (v_plan.requires_financial_approval OR v_plan.requires_guarantee)),
    financial_approval_status = CASE WHEN v_quote THEN 'not_required' ELSE v_fin_status END
  WHERE id = v_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (v_order_id, p_partner_id, v_uid, 'created_via_rpc',
          jsonb_build_object('numero', v_numero, 'total', v_final,
                             'items', jsonb_array_length(p_items),
                             'pricing_mode', COALESCE(v_plan.pricing_mode,'discount_from_base'),
                             'quote_required', v_quote,
                             'cart_hash', v_hash,
                             'hash_validated', true,
                             'idempotency_key', v_idem,
                             'fingerprint_algo', 'reqfp_v2',
                             'credit_reason_code', v_credit->>'reason_code',
                             'requested_delivery_date', p_requested_delivery_date));

  IF NOT v_quote THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
    VALUES (v_order_id, p_partner_id, v_uid, 'payment_terms_defined',
            jsonb_build_object('payment_plan_id', v_plan.id, 'plan_code', v_plan.code,
              'table_amount', v_table, 'discount_amount', v_disc,
              'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
              'final_amount', v_final, 'first_due_date', v_first_due,
              'installment_count', v_installments,
              'requires_financial_approval', (v_plan.requires_financial_approval OR v_plan.requires_guarantee)));
  END IF;

  IF COALESCE((v_credit->>'credit_limit')::numeric,0) <= 0 THEN
    INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
    VALUES (v_order_id, p_partner_id, v_uid, 'credit_limit_not_defined',
            jsonb_build_object('reason_code', v_credit->>'reason_code',
                               'exposicao_projetada', v_credit->>'exposicao_projetada'));
  END IF;

  FOR v_admin IN
    SELECT r AS user_id FROM platform_private.c2_order_internal_recipients(p_partner_id) r -- c2_ord_recipients
  LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_admin.user_id,
            CASE WHEN v_quote THEN 'pedido_b2b_cotacao' ELSE 'pedido_b2b_novo' END,
            CASE WHEN v_quote THEN 'Cotação B2B ' || v_numero ELSE 'Novo pedido B2B ' || v_numero END,
            CASE WHEN v_quote THEN 'Pedido sob consulta aguardando cotação comercial.'
                 ELSE 'Novo pedido B2B aguardando análise comercial. Total: R$ ' || to_char(v_final,'FM999G999G990D00') END,
            '/comercial/pedidos-b2b');
  END LOOP;

  v_result := jsonb_build_object(
    'id', v_order_id, 'numero', v_numero,
    'status', v_status::text,
    'pricing_mode', COALESCE(v_plan.pricing_mode,'discount_from_base'),
    'quote_required', v_quote,
    'cart_hash', v_hash,
    'idempotency_key', v_idem,
    'subtotal', v_table, 'desconto_total', v_disc, 'total', v_final,
    'table_amount', v_table, 'discount_amount', v_disc,
    'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
    'final_amount', v_final,
    'payment_terms_id', v_terms_id,
    'credit_reason_code', v_credit->>'reason_code',
    'credit_block_reason', v_block_reason,
    'requires_financial_approval', (NOT v_quote AND (v_plan.requires_financial_approval OR v_plan.requires_guarantee)),
    'financial_approval_status', CASE WHEN v_quote THEN 'not_required' ELSE v_fin_status END);

  INSERT INTO public.partner_order_idempotency(
    partner_id, idempotency_key, cart_hash, order_id, result_snapshot, created_by, request_fingerprint)
  VALUES (p_partner_id, v_idem, p_expected_cart_hash, v_order_id, v_result, v_uid, v_req_fp);

  DELETE FROM platform_private.authz_tickets WHERE txid=txid_current() AND scope='c2_external_order_create' AND target=p_partner_id;
  RETURN v_result;
END
$_$;


ALTER FUNCTION public.create_partner_order_secure(p_partner_id uuid, p_observacoes text, p_items jsonb, p_requested_delivery_date date, p_payment_plan_id uuid, p_first_due_date date, p_installment_count integer, p_expected_cart_hash text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: create_technical_visit_secure(uuid, uuid, uuid, uuid, timestamp with time zone, public.tipo_visita, public.urgencia_consultor, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_technical_visit_secure(p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid DEFAULT NULL::uuid, p_solicitacao_origem_id uuid DEFAULT NULL::uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_visit_type public.tipo_visita DEFAULT 'vistoria_inicial'::public.tipo_visita, p_priority public.urgencia_consultor DEFAULT 'media'::public.urgencia_consultor, p_initial_notes text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid) RETURNS TABLE(registro_id uuid, is_new boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_existing uuid;
  v_vinculo record;
  v_new_id uuid;
BEGIN
  -- 1) Auth
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  -- 2) Admin bypass (resolvido antes de qualquer leitura de dado)
  SELECT public.has_role(v_uid, 'administrador'::app_role) INTO v_is_admin;

  -- 3) Vínculo técnico ativo com o cliente alvo (autorização ANTES de ler dados)
  IF NOT v_is_admin THEN
    SELECT * INTO v_vinculo
      FROM public.user_clientes
     WHERE user_id = v_uid
       AND cliente_id = p_cliente_id
       AND is_active = true
       AND (valid_from IS NULL OR valid_from <= now())
       AND (valid_until IS NULL OR valid_until >= now())
       AND access_level IN ('execute','manage')
     LIMIT 1;

    IF v_vinculo.id IS NULL THEN
      RAISE EXCEPTION 'no_active_binding_or_insufficient_access' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 4) Idempotência (somente após autorização), escopada ao cliente autorizado
  --    e ao próprio chamador; admin fica escopado ao cliente autorizado.
  IF p_client_uuid IS NOT NULL THEN
    SELECT id INTO v_existing
      FROM public.registros_consultor
     WHERE client_uuid = p_client_uuid
       AND cliente_id = p_cliente_id
       AND (v_is_admin OR created_by = v_uid)
     LIMIT 1;

    IF v_existing IS NOT NULL THEN
      RETURN QUERY SELECT v_existing, false;
      RETURN;
    END IF;

    -- Colisão fora do escopo autorizado: falha genérica, sem revelar
    -- a existência ou a propriedade do client_uuid.
    IF EXISTS (
      SELECT 1 FROM public.registros_consultor WHERE client_uuid = p_client_uuid
    ) THEN
      RAISE EXCEPTION 'request_rejected' USING ERRCODE = '42501';
    END IF;
  END IF;

  -- 5) Cliente ativo
  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = p_cliente_id) THEN
    RAISE EXCEPTION 'cliente_not_found' USING ERRCODE = '22023';
  END IF;

  -- 6) Fazenda pertence ao cliente
  IF NOT EXISTS (
    SELECT 1 FROM public.fazendas
     WHERE id = p_fazenda_id AND cliente_id = p_cliente_id
  ) THEN
    RAISE EXCEPTION 'fazenda_does_not_belong_to_cliente' USING ERRCODE = '22023';
  END IF;

  -- 7) Talhão pertence à fazenda
  IF p_talhao_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.talhoes
       WHERE id = p_talhao_id AND fazenda_id = p_fazenda_id
    ) THEN
      RAISE EXCEPTION 'talhao_does_not_belong_to_fazenda' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 8) Solicitação pertence ao mesmo cliente
  IF p_solicitacao_origem_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.portal_solicitacoes
       WHERE id = p_solicitacao_origem_id AND cliente_id = p_cliente_id
    ) THEN
      RAISE EXCEPTION 'solicitacao_mismatch_cliente' USING ERRCODE = '22023';
    END IF;
  END IF;

  -- 9) Insert
  INSERT INTO public.registros_consultor(
    cliente_id, fazenda_id, talhao_id,
    consultor_responsavel, created_by,
    solicitacao_id, tipo_visita, urgencia,
    natureza_registro, status,
    observacoes_tecnicas, data_vistoria,
    client_uuid
  ) VALUES (
    p_cliente_id, p_fazenda_id, p_talhao_id,
    v_uid, v_uid,
    p_solicitacao_origem_id, p_visit_type, p_priority,
    'visita', 'rascunho',
    p_initial_notes, COALESCE(p_scheduled_at::date, CURRENT_DATE),
    p_client_uuid
  )
  RETURNING id INTO v_new_id;

  -- 10) Log de auditoria
  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (
    v_new_id, p_solicitacao_origem_id, 'visita_criada',
    'Visita técnica criada via create_technical_visit_secure',
    v_uid,
    jsonb_build_object(
      'tipo_visita', p_visit_type,
      'urgencia', p_priority,
      'admin_bypass', v_is_admin
    )
  );

  RETURN QUERY SELECT v_new_id, true;
END;
$$;


ALTER FUNCTION public.create_technical_visit_secure(p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid, p_solicitacao_origem_id uuid, p_scheduled_at timestamp with time zone, p_visit_type public.tipo_visita, p_priority public.urgencia_consultor, p_initial_notes text, p_client_uuid uuid) OWNER TO postgres;

--
-- Name: d51_5_p0d_ab_selftest(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.d51_5_p0d_ab_selftest() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if coalesce(current_setting('app.d51_5_p0d_selftest', true), '') <> 'enabled' then
    raise exception 'P0D_SELFTEST_DISABLED' using errcode = '42501';
  end if;

  -- Structural A/B assertions: every direct production surface must have a restrictive
  -- tenant policy; no historic true policy may survive; operational definers are not
  -- executable by signed-in callers until they embed resource-tenant checks.
  if exists (
    select 1 from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('clientes','fazendas','talhoes','ordens_servico','lotes','envase','controle_qualidade')
      and p.policyname = 'tenant_isolation_d51_5'
      and p.permissive <> 'RESTRICTIVE'
  ) or (
    select count(*) from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('clientes','fazendas','talhoes','ordens_servico','lotes','envase','controle_qualidade')
      and p.policyname = 'tenant_isolation_d51_5'
      and p.permissive = 'RESTRICTIVE'
  ) <> 7 then
    raise exception 'P0D_RESTRICTIVE_TENANT_POLICY_MISSING';
  end if;

  if exists (
    select 1 from pg_catalog.pg_policies p
    where p.schemaname = 'public'
      and p.tablename in ('lotes','envase','controle_qualidade')
      and (p.qual = 'true' or p.with_check = 'true')
  ) then
    raise exception 'P0D_TRUE_POLICY_SURVIVED';
  end if;

  if has_function_privilege('authenticated', 'public.rpc_programar_os_v1(uuid,text,date)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_gerar_lote_v1(uuid,uuid,text,jsonb)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_registrar_envase_v1(uuid,uuid,text,uuid,jsonb,date,text,text,boolean,text)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_avancar_esteira_laboratorio(uuid,text,text,uuid)', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.rpc_cockpit_listar_esteira_v1(text,text[],text[],text[],boolean,date,date,boolean,integer,integer)', 'EXECUTE') then
    raise exception 'P0D_UNSCOPED_DEFINER_STILL_EXECUTABLE';
  end if;

  v_result := jsonb_build_object(
    'tenant_restrictive_policies', 7,
    'legacy_true_policies', 0,
    'unscoped_cockpit_rpcs_executable', false,
    'transactional', true
  );
  return v_result;
end
$$;


ALTER FUNCTION public.d51_5_p0d_ab_selftest() OWNER TO postgres;

--
-- Name: d51_5_validate_financial_tenant_links(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.d51_5_validate_financial_tenant_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new jsonb := to_jsonb(NEW);
  v_org uuid;
  v_parent_id uuid;
BEGIN
  BEGIN
    v_org := NULLIF(v_new->>'organization_id', '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_INVALID' USING ERRCODE = '23514';
  END;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'FINANCIAL_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'accounts_receivable' THEN
    v_parent_id := NULLIF(v_new->>'customer_id', '')::uuid;
    IF v_parent_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.clientes c WHERE c.id = v_parent_id AND c.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_CUSTOMER_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'accounts_receivable_installments' THEN
    v_parent_id := NULLIF(v_new->>'receivable_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_receivable ar WHERE ar.id = v_parent_id AND ar.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIVABLE_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'accounts_payable_installments' THEN
    v_parent_id := NULLIF(v_new->>'payable_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_payable ap WHERE ap.id = v_parent_id AND ap.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_PAYABLE_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'receivable_payments' THEN
    v_parent_id := NULLIF(v_new->>'installment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_receivable_installments ari WHERE ari.id = v_parent_id AND ari.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIVABLE_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'payable_payments' THEN
    v_parent_id := NULLIF(v_new->>'installment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.accounts_payable_installments api WHERE api.id = v_parent_id AND api.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_PAYABLE_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  ELSIF TG_TABLE_NAME = 'financial_receipts' THEN
    v_parent_id := NULLIF(v_new->>'customer_id', '')::uuid;
    IF v_parent_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.clientes c WHERE c.id = v_parent_id AND c.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIPT_CUSTOMER_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
    v_parent_id := NULLIF(v_new->>'payment_id', '')::uuid;
    IF v_parent_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.receivable_payments rp WHERE rp.id = v_parent_id AND rp.organization_id = v_org
    ) THEN
      RAISE EXCEPTION 'FINANCIAL_RECEIPT_PAYMENT_TENANT_MISMATCH' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


ALTER FUNCTION public.d51_5_validate_financial_tenant_links() OWNER TO postgres;

--
-- Name: enforce_checkin_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_checkin_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status status_registro_consultor;
  v_natureza natureza_registro_consultor;
  v_registro_id uuid;
  v_is_admin boolean;
BEGIN
  v_registro_id := COALESCE(NEW.registro_consultor_id, OLD.registro_consultor_id);
  IF v_registro_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT status, COALESCE(natureza_registro, 'ocorrencia'::natureza_registro_consultor)
    INTO v_status, v_natureza
    FROM public.registros_consultor
   WHERE id = v_registro_id;

  IF v_natureza <> 'visita'::natureza_registro_consultor THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_is_admin := public.has_role(auth.uid(), 'administrador'::app_role);

  -- Only block UPDATE/DELETE on finalized (INSERT is allowed for the
  -- finish RPC which fires within the same transaction before status flips)
  IF TG_OP IN ('UPDATE','DELETE')
     AND v_status = 'finalizado'::status_registro_consultor
     AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Check-ins da visita % são imutáveis (visita finalizada).', v_registro_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.enforce_checkin_immutability() OWNER TO postgres;

--
-- Name: enforce_cliente_id_for_produtor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_cliente_id_for_produtor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_role app_role;
  v_count int;
BEGIN
  -- Lógica específica para a tabela user_roles
  IF TG_TABLE_NAME = 'user_roles' THEN
    -- Aqui o record NEW possui o campo 'role'
    IF NEW.role = 'cliente_produtor' THEN
      SELECT count(*) INTO v_count
        FROM public.user_clientes WHERE user_id = NEW.user_id;
      IF v_count = 0 THEN
        RAISE EXCEPTION 'Para a função "Produtor (Portal)" é obrigatório vincular o usuário a pelo menos um cliente.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  -- Lógica específica para a tabela user_clientes (que não possui campo 'role')
  IF TG_TABLE_NAME = 'user_clientes' THEN
    v_user := COALESCE(NEW.user_id, OLD.user_id);
    
    -- Verifica se o usuário tem a role de produtor
    SELECT role INTO v_role FROM public.user_roles
      WHERE user_id = v_user AND role = 'cliente_produtor' LIMIT 1;
      
    IF v_role IS NOT NULL THEN
      -- Conta quantos vínculos restariam após a operação
      IF TG_OP = 'DELETE' THEN
        SELECT count(*) INTO v_count FROM public.user_clientes
          WHERE user_id = v_user AND id <> OLD.id;
      ELSE
        SELECT count(*) INTO v_count FROM public.user_clientes
          WHERE user_id = v_user;
      END IF;

      IF v_count = 0 THEN
        RAISE EXCEPTION 'Este usuário é Produtor e precisa permanecer vinculado a pelo menos um cliente.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
  END IF;

  RETURN COALESCE(NEW, OLD);
END;$$;


ALTER FUNCTION public.enforce_cliente_id_for_produtor() OWNER TO postgres;

--
-- Name: enforce_diagnostico_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_diagnostico_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status status_registro_consultor;
  v_natureza natureza_registro_consultor;
  v_registro_id uuid;
  v_is_admin boolean;
BEGIN
  v_registro_id := COALESCE(NEW.registro_id, OLD.registro_id);

  SELECT status, COALESCE(natureza_registro, 'ocorrencia'::natureza_registro_consultor)
    INTO v_status, v_natureza
    FROM public.registros_consultor
   WHERE id = v_registro_id;

  IF v_natureza <> 'visita'::natureza_registro_consultor THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  v_is_admin := public.has_role(auth.uid(), 'administrador'::app_role);

  IF v_status = 'finalizado'::status_registro_consultor AND NOT v_is_admin THEN
    RAISE EXCEPTION 'Diagnósticos da visita % são imutáveis (visita finalizada).', v_registro_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.enforce_diagnostico_immutability() OWNER TO postgres;

--
-- Name: enforce_micro_profile_approval(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_micro_profile_approval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.mecanismo_acao), '') = '' THEN RAISE EXCEPTION 'approval_missing_mecanismo_acao'; END IF;
    IF COALESCE(btrim(NEW.beneficios_agronomicos), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficios_agronomicos'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = '' THEN RAISE EXCEPTION 'approval_missing_observacoes_regulatorias'; END IF;

    SELECT count(*) INTO v_alvos FROM public.microorganism_targets
      WHERE microrganismo_id = NEW.microrganismo_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_microrganismo' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'microrganismo' AND entidade_id = NEW.microrganismo_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_micro_profile_approval() OWNER TO postgres;

--
-- Name: enforce_product_profile_approval(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_product_profile_approval() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_alvos int;
  v_fontes int;
  v_comp int;
  v_old_status text := CASE WHEN TG_OP = 'UPDATE' THEN OLD.status_validacao ELSE NULL END;
BEGIN
  IF NEW.status_validacao = 'aprovado'
     AND (TG_OP = 'INSERT' OR COALESCE(v_old_status, '') <> 'aprovado') THEN

    IF COALESCE(btrim(NEW.resumo_curto), '') = '' THEN RAISE EXCEPTION 'approval_missing_resumo_curto'; END IF;
    IF COALESCE(btrim(NEW.explicacao_tecnica), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_tecnica'; END IF;
    IF COALESCE(btrim(NEW.explicacao_produtor), '') = '' THEN RAISE EXCEPTION 'approval_missing_explicacao_produtor'; END IF;
    IF COALESCE(btrim(NEW.beneficio_combinado), '') = '' THEN RAISE EXCEPTION 'approval_missing_beneficio_combinado'; END IF;
    IF COALESCE(btrim(NEW.observacoes_regulatorias), '') = ''
       AND COALESCE(btrim(NEW.cuidados_aplicacao), '') = '' THEN
      RAISE EXCEPTION 'approval_missing_observacoes_ou_cuidados';
    END IF;

    SELECT count(*) INTO v_comp FROM public.formulacoes WHERE produto_id = NEW.produto_id;
    IF v_comp = 0 THEN RAISE EXCEPTION 'approval_missing_composicao'; END IF;

    SELECT count(*) INTO v_alvos FROM public.product_target_recommendations
      WHERE produto_id = NEW.produto_id AND ativo = true;
    IF v_alvos = 0 THEN RAISE EXCEPTION 'approval_missing_alvos'; END IF;

    IF v_uid IS NOT NULL THEN
      SELECT (public.has_role(v_uid, 'administrador'::app_role)
           OR public.has_role(v_uid, 'gestor'::app_role)) INTO v_is_admin;
    END IF;

    IF NOT v_is_admin THEN
      SELECT count(*) INTO v_fontes FROM public.catalog_technical_sources
        WHERE (entidade_tipo = 'ficha_produto' AND entidade_id = NEW.id)
           OR (entidade_tipo = 'produto' AND entidade_id = NEW.produto_id);
      IF v_fontes = 0 THEN RAISE EXCEPTION 'approval_missing_fontes'; END IF;
    END IF;

    IF NEW.validado_por IS NULL THEN NEW.validado_por := v_uid; END IF;
    IF NEW.validado_em IS NULL THEN NEW.validado_em := now(); END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    NEW.updated_by := COALESCE(v_uid, NEW.updated_by);
    NEW.updated_at := now();
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_product_profile_approval() OWNER TO postgres;

--
-- Name: enforce_technical_content_editable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_technical_content_editable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_old uuid; v_new uuid; v_id uuid; v_status text;
BEGIN
 IF TG_OP <> 'INSERT' THEN v_old := (to_jsonb(OLD)->>TG_ARGV[0])::uuid; END IF;
 IF TG_OP <> 'DELETE' THEN v_new := (to_jsonb(NEW)->>TG_ARGV[0])::uuid; END IF;
 FOR v_id IN SELECT DISTINCT x FROM unnest(ARRAY[v_old,v_new]) x WHERE x IS NOT NULL ORDER BY x LOOP
  SELECT r.status::text INTO v_status FROM public.registros_consultor r WHERE r.id=v_id FOR SHARE;
  IF NOT FOUND OR v_status NOT IN ('rascunho','em_andamento') THEN
   RAISE EXCEPTION 'technical_content_locked: reabra a visita pelo fluxo autorizado antes de alterar seu conteúdo' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.enforce_technical_content_editable() OWNER TO postgres;

--
-- Name: enforce_visit_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_visit_immutability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Technical content is frozen for every nature and actor after submission.
  -- Official RPCs may change status; version, timestamp and PDF processing are metadata.
  IF OLD.status::text NOT IN ('rascunho', 'em_andamento') AND
    (to_jsonb(NEW) - ARRAY['status','version','updated_at','pdf_status']::text[])
      IS DISTINCT FROM
    (to_jsonb(OLD) - ARRAY['status','version','updated_at','pdf_status']::text[])
  THEN
    RAISE EXCEPTION 'technical_record_content_locked'
      USING ERRCODE = '23514',
      HINT = 'Use the authorized adjustment workflow before editing technical content.';
  END IF;
  NEW.version := COALESCE(OLD.version, 1) + 1;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_visit_immutability() OWNER TO postgres;

