--
-- Name: expire_due_trials(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.expire_due_trials(_limit integer DEFAULT 100) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text; v_count integer:=0; v_row record; v_correlation uuid;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF current_user<>'postgres' AND v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF _limit<1 OR _limit>500 THEN RAISE EXCEPTION 'platform_invalid: limite inválido' USING ERRCODE='22023'; END IF;
  FOR v_row IN SELECT id,organization_id FROM public.organization_subscriptions WHERE status='TRIAL' AND plan_version_id IS NOT NULL AND trial_ends_at IS NOT NULL AND trial_ends_at<=now() ORDER BY trial_ends_at FOR UPDATE SKIP LOCKED LIMIT _limit LOOP
    v_correlation:=gen_random_uuid();
    PERFORM platform_private.issue_ticket('saas_subscription_write',v_row.organization_id);
    PERFORM set_config('app.saas_change_reason','trial expirado automaticamente',true);
    PERFORM set_config('app.saas_change_action','expire_trial',true);
    PERFORM set_config('app.saas_correlation_id',v_correlation::text,true);
    UPDATE public.organization_subscriptions SET status='EXPIRED',state_changed_at=now(),last_correlation_id=v_correlation WHERE id=v_row.id AND status='TRIAL';
    IF FOUND THEN v_count:=v_count+1; END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.expire_due_trials(_limit integer) OWNER TO postgres;

--
-- Name: financial_document_download_snapshot(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.financial_document_download_snapshot(_name text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  WITH actor AS MATERIALIZED (
    SELECT auth.uid() AS uid, public.h15_actor_organization() AS org
    WHERE auth.uid() IS NOT NULL AND length(_name) BETWEEN 1 AND 1024
      AND public.financial_storage_object_permitted('financial-docs', _name)
  ), roles AS MATERIALIZED (
    SELECT jsonb_agg(r.role::text ORDER BY r.role::text) AS value
    FROM public.user_roles r JOIN actor a ON r.user_id = a.uid
  ), docs AS MATERIALIZED (
    SELECT d.id, d.owner_type, d.owner_id, d.storage_path, d.file_size, d.mime_type, a.uid, a.org
    FROM public.financial_documents d JOIN actor a ON true
    WHERE d.storage_path = _name AND d.deleted_at IS NULL
      AND (d.organization_id IS NULL OR d.organization_id = a.org)
      AND split_part(_name, '/', 1) = d.owner_type
      AND split_part(_name, '/', 2) = d.owner_id::text
  )
  SELECT CASE WHEN (SELECT count(*) FROM docs) = 1
    AND jsonb_array_length(coalesce((SELECT value FROM roles), '[]'::jsonb)) > 0
  THEN (SELECT jsonb_build_object('actor', uid, 'tenant', org, 'roles', (SELECT value FROM roles),
    'document', id, 'owner_type', owner_type, 'owner', owner_id, 'path', storage_path,
    'size', file_size, 'mime', mime_type) FROM docs) ELSE NULL END;
$$;


ALTER FUNCTION public.financial_document_download_snapshot(_name text) OWNER TO postgres;

--
-- Name: financial_storage_object_permitted(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.financial_storage_object_permitted(_bucket text, _name text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_parts text[]; v_owner_type text; v_owner_id uuid;
BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF;
  v_org := public.h15_actor_organization();
  IF v_org IS NULL OR NOT public.is_financial_staff(auth.uid()) THEN RETURN false; END IF;
  v_parts := storage.foldername(_name);
  IF _bucket IN ('financial-reports','financial-receipts') THEN
    RETURN array_length(v_parts,1) >= 1 AND v_parts[1] = v_org::text;
  END IF;
  IF _bucket <> 'financial-docs' OR array_length(v_parts,1) < 2 THEN RETURN false; END IF;
  v_owner_type := v_parts[1];
  BEGIN
  IF NOT public.storage1_path_strict(_name) THEN RETURN false; END IF; v_owner_id := v_parts[2]::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
  RETURN CASE v_owner_type
    WHEN 'RECEIVABLE' THEN EXISTS(SELECT 1 FROM public.accounts_receivable x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYABLE' THEN EXISTS(SELECT 1 FROM public.accounts_payable x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYMENT_RECEIVABLE' THEN EXISTS(SELECT 1 FROM public.receivable_payments x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'PAYMENT_PAYABLE' THEN EXISTS(SELECT 1 FROM public.payable_payments x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    WHEN 'FISCAL_INVOICE' THEN EXISTS(SELECT 1 FROM public.fiscal_invoices x WHERE x.id=v_owner_id AND x.organization_id=v_org)
    ELSE false END;
END $$;


ALTER FUNCTION public.financial_storage_object_permitted(_bucket text, _name text) OWNER TO postgres;

--
-- Name: finish_technical_visit_secure(uuid, numeric, numeric, numeric, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_technical_visit_secure(p_registro_id uuid, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_precisao_gps numeric DEFAULT NULL::numeric, p_foto_url text DEFAULT NULL::text, p_foto_path text DEFAULT NULL::text, p_observacoes text DEFAULT NULL::text, p_client_uuid uuid DEFAULT NULL::uuid) RETURNS TABLE(registro_id uuid, checkout_id uuid, finalized_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_reg public.registros_consultor;
  v_existing public.visitas_checkin;
  v_diag_count int;
  v_new_checkout uuid;
  v_now timestamptz := now();
  v_prev_final timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  v_is_admin := COALESCE(public.has_role(v_uid, 'administrador'::app_role), false);

  -- H9-E2 (A): gate de escopo fail-closed ANTES de qualquer SELECT em
  -- registros_consultor ou visitas_checkin. Registro inexistente, registro
  -- alheio, p_registro_id NULL e qualquer client_uuid (existente, alheio ou
  -- aleatorio) produzem a MESMA superficie publica: 42501 not_visit_owner.
  IF NOT v_is_admin
     AND NOT COALESCE(public._visita_scope_ok(v_uid, p_registro_id), false) THEN
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- H9-E2 (B): lock por registro ANTES da busca idempotente. Serializa
  -- encerramentos concorrentes do mesmo agregado; nao ha lock global.
  SELECT * INTO v_reg
    FROM public.registros_consultor r
   WHERE r.id = p_registro_id
     FOR UPDATE;

  IF v_reg.id IS NULL THEN
    -- Alcancavel apenas no bypass de administrador; mantem a superficie unica.
    RAISE EXCEPTION 'not_visit_owner' USING ERRCODE = '42501';
  END IF;

  -- H9-E2 (B): busca idempotente POS-lock e ANTES de qualquer rejeicao por
  -- estado. A sessao perdedora da corrida encontra aqui o resultado vencedor
  -- (ja commitado) e retorna identico, em vez de erro de estado.
  IF p_client_uuid IS NOT NULL THEN
    SELECT * INTO v_existing
      FROM public.visitas_checkin
     WHERE client_uuid = p_client_uuid
     LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
      IF v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
         OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
         OR (v_existing.consultor_id IS DISTINCT FROM v_uid AND NOT v_is_admin) THEN
        RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
      END IF;

      SELECT r.finalized_at INTO v_prev_final
        FROM public.registros_consultor r
       WHERE r.id = p_registro_id;

      RETURN QUERY
        SELECT p_registro_id,
               v_existing.id,
               COALESCE(v_prev_final, v_existing.data_hora_checkin);
      RETURN;
    END IF;
  END IF;
  -- Nota: com p_client_uuid NULL nao existe chave de idempotencia; a chamada
  -- permanece compativel, porem NAO e idempotente. Limitacao documentada.

  IF v_reg.status <> 'em_andamento' THEN
    RAISE EXCEPTION 'visit_not_in_progress:%', v_reg.status USING ERRCODE = '22023';
  END IF;

  -- Exige ao menos um diagnostico
  SELECT count(*) INTO v_diag_count
    FROM public.visita_diagnosticos vd WHERE vd.registro_id = v_reg.id;
  IF v_diag_count = 0 THEN
    RAISE EXCEPTION 'diagnostico_required' USING ERRCODE = '22023';
  END IF;

  -- H9-E1R (2): check-out gravado com o tipo canonico 'checkout'.
  BEGIN
    INSERT INTO public.visitas_checkin(
      registro_consultor_id, solicitacao_id, consultor_id,
      cliente_id, fazenda_id, talhao_id,
      latitude, longitude, precisao_gps,
      foto_url, foto_path, observacoes,
      tipo_checkin, status, client_uuid
    ) VALUES (
      v_reg.id, v_reg.solicitacao_id, v_uid,
      v_reg.cliente_id, v_reg.fazenda_id, v_reg.talhao_id,
      p_latitude, p_longitude, p_precisao_gps,
      p_foto_url, p_foto_path, p_observacoes,
      'checkout'::public.tipo_checkin, 'realizado', p_client_uuid
    )
    RETURNING id INTO v_new_checkout;
  EXCEPTION WHEN unique_violation THEN
    -- Corrida do mesmo client_uuid em registros distintos (fora do lock):
    -- converge para o vencedor, fail-closed.
    SELECT * INTO v_existing
      FROM public.visitas_checkin
     WHERE client_uuid = p_client_uuid
     LIMIT 1;

    IF v_existing.id IS NULL
       OR v_existing.registro_consultor_id IS DISTINCT FROM p_registro_id
       OR v_existing.tipo_checkin <> 'checkout'::public.tipo_checkin
       OR (v_existing.consultor_id IS DISTINCT FROM v_uid AND NOT v_is_admin) THEN
      RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '22023';
    END IF;

    SELECT r.finalized_at INTO v_prev_final
      FROM public.registros_consultor r
     WHERE r.id = p_registro_id;

    RETURN QUERY
      SELECT p_registro_id,
             v_existing.id,
             COALESCE(v_prev_final, v_existing.data_hora_checkin);
    RETURN;
  END;

  UPDATE public.registros_consultor
     SET status = 'finalizado',
         hora_fim = v_now,
         finalized_at = v_now,
         finalized_by = v_uid,
         updated_at = v_now
   WHERE id = v_reg.id;

  INSERT INTO public.visitas_logs(registro_consultor_id, solicitacao_id, acao, descricao, usuario_id, metadata)
  VALUES (v_reg.id, v_reg.solicitacao_id, 'checkout', 'Check-out e finalizacao da visita', v_uid,
          jsonb_build_object('checkout_id', v_new_checkout, 'admin_bypass', v_is_admin));

  RETURN QUERY SELECT v_reg.id, v_new_checkout, v_now;
END;
$$;


ALTER FUNCTION public.finish_technical_visit_secure(p_registro_id uuid, p_latitude numeric, p_longitude numeric, p_precisao_gps numeric, p_foto_url text, p_foto_path text, p_observacoes text, p_client_uuid uuid) OWNER TO postgres;

--
-- Name: fiscal_audit_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fiscal_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor uuid;
  v_allowed text[] := ARRAY[
    'company_fiscal_settings','product_fiscal_profiles','service_fiscal_profiles',
    'customer_fiscal_profiles','fiscal_invoices','fiscal_invoice_items',
    'fiscal_events','fiscal_idempotency_keys',
    'fiscal_operation_policies','fiscal_tax_rules','fiscal_document_series',
    'fiscal_number_reservations','fiscal_rule_sod_overrides','fiscal_calculation_runs'
  ];
BEGIN
  IF NOT (TG_TABLE_NAME = ANY(v_allowed)) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', v_actor, public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', v_actor,
            public.mask_sensitive_jsonb(to_jsonb(OLD)), public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values)
    VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', v_actor, public.mask_sensitive_jsonb(to_jsonb(OLD)));
    RETURN OLD;
  END IF;
  RETURN NULL;
END $$;


ALTER FUNCTION public.fiscal_audit_trigger() OWNER TO postgres;

