--
-- Name: fiscal_validate_key_usage(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fiscal_validate_key_usage(p_arr jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_len integer;
  v_el  jsonb;
BEGIN
  IF p_arr IS NULL THEN RETURN; END IF;
  IF jsonb_typeof(p_arr) <> 'array' THEN
    RAISE EXCEPTION 'key_usage_invalid' USING ERRCODE = '22023';
  END IF;
  v_len := jsonb_array_length(p_arr);
  IF v_len > 20 THEN
    RAISE EXCEPTION 'key_usage_too_many' USING ERRCODE = '22023';
  END IF;
  FOR v_el IN SELECT * FROM jsonb_array_elements(p_arr) LOOP
    IF jsonb_typeof(v_el) <> 'string' THEN
      RAISE EXCEPTION 'key_usage_item_not_string' USING ERRCODE = '22023';
    END IF;
    IF char_length(v_el #>> '{}') < 1 OR char_length(v_el #>> '{}') > 80 THEN
      RAISE EXCEPTION 'key_usage_item_length_invalid' USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fiscal_validate_key_usage(p_arr jsonb) OWNER TO postgres;

--
-- Name: fiscal_validate_snapshot_keys(jsonb, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fiscal_validate_snapshot_keys(p_obj jsonb, p_allowed text[], p_label text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE k text;
BEGIN
  IF p_obj IS NULL OR jsonb_typeof(p_obj) <> 'object' THEN
    RETURN;
  END IF;
  FOR k IN SELECT jsonb_object_keys(p_obj) LOOP
    IF NOT (k = ANY(p_allowed)) THEN
      RAISE EXCEPTION 'snapshot_unknown_key:%:%', p_label, k
        USING ERRCODE = '22023';
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.fiscal_validate_snapshot_keys(p_obj jsonb, p_allowed text[], p_label text) OWNER TO postgres;

--
-- Name: fn_assign_receipt_metadata(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_assign_receipt_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_year int;
  v_seq int;
  v_code text;
BEGIN
  v_year := EXTRACT(YEAR FROM COALESCE(NEW.payment_date, CURRENT_DATE))::int;
  -- lock the table portion for this year and compute next seq
  PERFORM 1 FROM public.financial_receipts WHERE receipt_year = v_year FOR UPDATE;
  SELECT COALESCE(MAX(receipt_seq), 0) + 1 INTO v_seq
    FROM public.financial_receipts WHERE receipt_year = v_year;
  NEW.receipt_year := v_year;
  NEW.receipt_seq := v_seq;
  NEW.receipt_number := 'REC-' || v_year::text || '-' || lpad(v_seq::text, 6, '0');
  IF NEW.authenticity_code IS NULL THEN
    v_code := upper(substr(encode(extensions.digest(NEW.id::text || gen_random_uuid()::text || clock_timestamp()::text, 'sha256'), 'hex'), 1, 12));
    NEW.authenticity_code := substr(v_code,1,4) || '-' || substr(v_code,5,4) || '-' || substr(v_code,9,4);
  END IF;
  IF NEW.public_verification_token IS NULL THEN
    NEW.public_verification_token := gen_random_uuid();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_assign_receipt_metadata() OWNER TO postgres;

