--
-- Name: fn_cc_validate_item_input(uuid, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cc_validate_item_input(p_plan_id uuid, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE v_plan_mode text;
BEGIN
  IF p_pricing_mode NOT IN ('fixed_item_price','discount_from_base','quote_only') THEN
    RAISE EXCEPTION 'invalid_pricing_mode';
  END IF;
  SELECT pricing_mode INTO v_plan_mode FROM public.commercial_payment_plans WHERE id = p_plan_id;
  IF v_plan_mode IS NULL THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_pricing_mode <> 'quote_only' AND p_pricing_mode <> v_plan_mode THEN
    RAISE EXCEPTION 'pricing_mode_conflicts_plan';
  END IF;
  IF p_pricing_mode = 'fixed_item_price' AND COALESCE(p_condition_price,0) <= 0 THEN
    RAISE EXCEPTION 'condition_price_required';
  END IF;
  IF p_pricing_mode = 'discount_from_base'
     AND p_discount_percent IS NOT NULL
     AND (p_discount_percent < 0 OR p_discount_percent > 100) THEN
    RAISE EXCEPTION 'discount_percent_out_of_range';
  END IF;
END $$;


ALTER FUNCTION public.fn_cc_validate_item_input(p_plan_id uuid, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric) OWNER TO postgres;

--
-- Name: fn_cockpit_assert_b2b_liberado(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_assert_b2b_liberado(p_partner_order_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r record;
BEGIN
  IF p_partner_order_id IS NULL THEN RETURN; END IF;

  SELECT status::text AS status,
         coalesce(financial_status, '')          AS fin,
         coalesce(financial_approval_status, '') AS fin_apr,
         coalesce(payment_condition_status, '')  AS pay,
         partner_id
    INTO r
    FROM public.partner_orders
   WHERE id = p_partner_order_id;

  IF r IS NULL THEN RAISE EXCEPTION 'COCKPIT_B2B_PEDIDO_NAO_ENCONTRADO'; END IF;
  IF r.partner_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_B2B_PARCEIRO_INVALIDO'; END IF;

  IF r.status IN ('rascunho','pendente','solicitado','em_analise_comercial',
                  'aguardando_cotacao','aguardando_aprovacao_credito',
                  'aguardando_ajuste_comercial','aguardando_itens') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_APROVACAO_PENDENTE';
  END IF;
  IF r.status IN ('reprovado','reprovado_sem_itens','cancelado') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_PEDIDO_BLOQUEADO';
  END IF;
  IF r.fin_apr IN ('pendente','rejeitado','bloqueado')
     OR r.fin IN ('bloqueado','inadimplente')
     OR r.pay IN ('pendente','rejeitado') THEN
    RAISE EXCEPTION 'COCKPIT_B2B_FINANCEIRO_BLOQUEADO';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_cockpit_assert_b2b_liberado(p_partner_order_id uuid) OWNER TO postgres;

--
-- Name: fn_cockpit_assert_operador(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_assert_operador() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED';
  END IF;
  IF NOT (
    public.has_role(auth.uid(), 'administrador'::app_role)
    OR public.has_role(auth.uid(), 'gestor'::app_role)
    OR public.has_role(auth.uid(), 'producao'::app_role)
    OR public.has_role(auth.uid(), 'operador_onfarm'::app_role)
  ) THEN
    RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_cockpit_assert_operador() OWNER TO postgres;

--
-- Name: fn_cockpit_assert_operador_origem(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_assert_operador_origem(p_origem text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_origem text := public.fn_cockpit_norm_origem(p_origem);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- produção: fluxo industrial (manual/onfarm/b2b), sem privilégio de override
  IF public.has_role(v_uid, 'producao'::app_role) THEN
    RETURN v_origem;
  END IF;

  -- operador on-farm: alçada restrita à própria origem
  IF public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    IF v_origem <> 'onfarm' THEN
      RAISE EXCEPTION 'COCKPIT_FORBIDDEN_ORIGEM';
    END IF;
    RETURN v_origem;
  END IF;

  RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
END;
$$;


ALTER FUNCTION public.fn_cockpit_assert_operador_origem(p_origem text) OWNER TO postgres;

--
-- Name: fn_cockpit_ctx_programacao(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_ctx_programacao(p_programacao_id uuid) RETURNS TABLE(programacao_id uuid, os_id uuid, origem text, produto_id uuid, microrganismo_id uuid, cliente_id uuid, partner_order_id uuid, volume_necessario numeric, status_os text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE pp record;
BEGIN
  SELECT * INTO pp FROM public.programacao_producao WHERE id = p_programacao_id;
  IF pp IS NULL THEN RAISE EXCEPTION 'COCKPIT_PROGRAMACAO_NAO_ENCONTRADA'; END IF;

  IF pp.ordem_servico_onfarm_id IS NOT NULL THEN
    RETURN QUERY
      SELECT pp.id, os.id, 'onfarm'::text, coalesce(pp.produto_id, os.produto_id),
             coalesce(pp.microrganismo_id, os.microrganismo_id), os.cliente_id,
             NULL::uuid, coalesce(pp.volume_necessario, 0), os.status::text
        FROM public.ordens_servico_onfarm os
       WHERE os.id = pp.ordem_servico_onfarm_id;
  ELSIF pp.ordem_servico_id IS NOT NULL THEN
    RETURN QUERY
      SELECT pp.id, os.id,
             CASE WHEN os.partner_order_id IS NOT NULL THEN 'b2b' ELSE 'manual' END,
             coalesce(pp.produto_id, os.produto_id),
             coalesce(pp.microrganismo_id, os.microrganismo_id), os.cliente_id,
             os.partner_order_id, coalesce(pp.volume_necessario, 0), os.status::text
        FROM public.ordens_servico os
       WHERE os.id = pp.ordem_servico_id;
  ELSE
    RAISE EXCEPTION 'COCKPIT_PROGRAMACAO_SEM_OS';
  END IF;
END;
$$;


ALTER FUNCTION public.fn_cockpit_ctx_programacao(p_programacao_id uuid) OWNER TO postgres;

