    AS $$
  SELECT public.has_role(auth.uid(), 'administrador'::app_role)
      OR public.has_role(auth.uid(), 'gestor'::app_role)
$$;


ALTER FUNCTION public.fn_cockpit_is_gestor() OWNER TO postgres;

--
-- Name: fn_cockpit_norm_origem(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_norm_origem(p_origem text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v text := lower(btrim(coalesce(p_origem, '')));
BEGIN
  IF v IN ('manual', 'os', 'ordem_servico') THEN RETURN 'manual'; END IF;
  IF v IN ('onfarm', 'on_farm', 'ordem_servico_onfarm') THEN RETURN 'onfarm'; END IF;
  IF v = 'b2b' THEN RETURN 'b2b'; END IF;
  RAISE EXCEPTION 'COCKPIT_ORIGEM_INVALIDA';
END;
$$;


ALTER FUNCTION public.fn_cockpit_norm_origem(p_origem text) OWNER TO postgres;

--
-- Name: fn_cockpit_payload_hash(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_payload_hash(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$ SELECT encode(extensions.digest(p_payload::text, 'sha256'), 'hex') $$;


ALTER FUNCTION public.fn_cockpit_payload_hash(p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_cockpit_stage(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cockpit_stage(p_status_oficial text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE lower(coalesce(p_status_oficial, ''))
    WHEN 'cancelada'        THEN 'cancelada'
    WHEN 'cancelado'        THEN 'cancelada'
    WHEN 'finalizada'       THEN 'finalizada'
    WHEN 'finalizado'       THEN 'finalizada'
    WHEN 'entregue'         THEN 'entregue'
    WHEN 'aplicado'         THEN 'entregue'
    WHEN 'em_entrega'       THEN 'em_entrega'
    WHEN 'estoque_reservado' THEN 'estoque_reservado'
    WHEN 'estoque_gerado'   THEN 'estoque_disponivel'
    WHEN 'pronto_entrega'   THEN 'estoque_disponivel'
    WHEN 'envase'           THEN 'em_envase'
    WHEN 'em_envase'        THEN 'em_envase'
    WHEN 'cq_reprovado'     THEN 'cq_reprovado'
    WHEN 'reprovado'        THEN 'cq_reprovado'
    WHEN 'cq_aprovado'      THEN 'cq_aprovado'
    WHEN 'aprovado_cq'      THEN 'cq_aprovado'
    WHEN 'aguardando_cq'    THEN 'aguardando_cq'
    WHEN 'em_cq'            THEN 'aguardando_cq'
    WHEN 'em_producao'      THEN 'em_producao'
    WHEN 'programada'       THEN 'programada'
    ELSE 'aguardando'
  END
$$;


ALTER FUNCTION public.fn_cockpit_stage(p_status_oficial text) OWNER TO postgres;

--
-- Name: fn_comprovante_entrega_montar_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_comprovante_entrega_montar_v1(p_entrega_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  e            public.entregas%ROWTYPE;
  v_emitente   jsonb;
  v_destino    jsonb;
  v_os         jsonb;
  v_itens      jsonb;
  v_transporte jsonb;
  v_receb      jsonb;
BEGIN
  PERFORM public.h15_require_staff();

  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'COMPROVANTE_UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
  IF NOT coalesce(public.is_delivery_staff(auth.uid()),false) THEN RAISE EXCEPTION 'COMPROVANTE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO e FROM public.entregas WHERE id = p_entrega_id;
  IF e.id IS NULL THEN
    RAISE EXCEPTION 'COMPROVANTE_ENTREGA_NAO_ENCONTRADA';
  END IF;

  SELECT jsonb_build_object(
           'razao_social', cs.legal_name,
           'nome_fantasia', cs.trade_name,
           'cnpj', cs.cnpj,
           'inscricao_estadual', cs.state_registration,
           'email', cs.fiscal_email,
           'telefone', cs.phone,
           'logradouro', cs.street,
           'numero', cs.number,
           'complemento', cs.complement,
           'bairro', cs.neighborhood,
           'cidade', cs.city,
           'uf', cs.state,
           'cep', cs.postal_code
         )
    INTO v_emitente
    FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) cs
   WHERE cs.is_active
   ORDER BY cs.updated_at DESC NULLS LAST
   LIMIT 1;

  SELECT jsonb_build_object(
           'cliente_id', c.id,
           'nome', coalesce(nullif(btrim(c.razao_social), ''), c.nome),
           'nome_fantasia', c.nome_fantasia,
           'cpf_cnpj', c.cpf_cnpj,
           'telefone', coalesce(nullif(btrim(c.telefone), ''), e.destinatario_telefone),
           'email', c.email,
           'cidade', coalesce(nullif(btrim(e.endereco_cidade), ''), c.endereco_municipio),
           'uf', coalesce(nullif(btrim(e.endereco_uf), ''), c.endereco_estado)
         )
    INTO v_destino
    FROM public.clientes c
   WHERE c.id = e.cliente_id;

  v_destino := coalesce(v_destino, '{}'::jsonb) || jsonb_build_object(
    'destinatario_nome', e.destinatario_nome,
    'local_entrega', nullif(btrim(concat_ws(', ',
        nullif(btrim(coalesce(e.endereco_logradouro, '')), ''),
        nullif(btrim(coalesce(e.endereco_numero, '')), ''),
        nullif(btrim(coalesce(e.endereco_bairro, '')), ''),
        nullif(btrim(coalesce(e.endereco_cidade, '')), ''),
        nullif(btrim(coalesce(e.endereco_uf, '')), ''))), '')
  );

  -- OS canonica: fluxo padrao (ordens_servico) ou fluxo On-Farm legitimo.
  SELECT jsonb_build_object(
           'os_id', o.id,
           'numero_os', o.numero_os,
           'origem', coalesce(o.origem, 'manual'),
           'tipo', 'ordem_servico'
         )
    INTO v_os
    FROM public.ordens_servico o
   WHERE o.id = e.ordem_servico_id;

  IF v_os IS NULL AND e.ordem_servico_onfarm_id IS NOT NULL THEN
    SELECT jsonb_build_object(
             'os_id', onf.id,
             'numero_os', onf.numero_os,
             'origem', 'on_farm',
             'tipo', 'ordem_servico_onfarm'
           )
      INTO v_os
      FROM public.ordens_servico_onfarm onf
     WHERE onf.id = e.ordem_servico_onfarm_id;
  END IF;

  -- Origem legitima adicional mapeada no dominio: entrega vinculada a pedido
  -- de parceiro (B2B) sem OS de laboratorio. Documentado em
  -- docs/auditorias/comprovante-entrega-fase2.md.
  IF v_os IS NULL AND e.partner_order_id IS NOT NULL THEN
    SELECT jsonb_build_object(
             'os_id', po.id,
             'numero_os', po.numero,
             'origem', 'pedido_parceiro',
             'tipo', 'partner_order'
           )
      INTO v_os
      FROM public.partner_orders po
     WHERE po.id = e.partner_order_id;
  END IF;

  -- Itens: caminho canonico por etiqueta
  SELECT jsonb_agg(item ORDER BY item->>'lote')
    INTO v_itens
    FROM (
      SELECT jsonb_build_object(
               'produto', coalesce(pe.produto_nome, pr.nome),
               'microrganismo', coalesce(array_to_string(pe.cepas, ', '), m.nome_cientifico, m.nome),
               'lote', coalesce(pe.lote_codigo, l.codigo_lote),
               'fabricacao', coalesce(pe.fabricado_em::date, l.data_producao),
               'validade', pe.validade_em::date,
               'embalagem', coalesce(eb.tipo_embalagem, pe.unidade),
               'quantidade', coalesce(pe.quantidade_embalagens, 1),
               'volume_unitario_ml', pe.volume,
               'volume_total_ml', coalesce(pe.volume, 0) * coalesce(pe.quantidade_embalagens, 1)
             ) AS item
        FROM public.entrega_etiquetas ee
        JOIN public.produto_etiquetas pe ON pe.id = ee.etiqueta_id
        LEFT JOIN public.produtos pr ON pr.id = pe.produto_id
        LEFT JOIN public.lotes l ON l.id = pe.lote_id
        LEFT JOIN public.microrganismos m ON m.id = l.microrganismo_id
        LEFT JOIN public.estoque_embalagens eb ON eb.id = pe.embalagem_id
       WHERE ee.entrega_id = p_entrega_id AND ee.ativo
    ) s;

  -- Fallback: vinculo direto da entrega (fluxo classico produto_id/lote_id).
  -- Referencias sempre por e2 (linha atual), sem depender da variavel PL/pgSQL.
  IF v_itens IS NULL OR jsonb_array_length(v_itens) = 0 THEN
    SELECT jsonb_build_array(jsonb_build_object(
             'produto', pr.nome,
             'microrganismo', coalesce(m.nome_cientifico, m.nome),
             'lote', l.codigo_lote,
             'fabricacao', l.data_producao,
             'validade', ep.validade,
             'embalagem', env.tipo_embalagem,
             'quantidade', e2.quantidade_entregue,
             'volume_unitario_ml', coalesce(
               env.volume_por_unidade,
               CASE WHEN coalesce(e2.quantidade_entregue, 0) > 0
                    THEN round(e2.volume_entregue_ml / e2.quantidade_entregue, 2) END),
             'volume_total_ml', coalesce(
               e2.volume_entregue_ml,
               env.volume_por_unidade * e2.quantidade_entregue)
           ))
      INTO v_itens
      FROM public.entregas e2
      LEFT JOIN public.produtos pr
             ON pr.id = coalesce(e2.produto_id,
                                 (SELECT l2.produto_id FROM public.lotes l2 WHERE l2.id = e2.lote_id))
      LEFT JOIN public.lotes l ON l.id = e2.lote_id
      LEFT JOIN public.microrganismos m ON m.id = l.microrganismo_id
      LEFT JOIN public.estoque_produto ep ON ep.id = e2.estoque_produto_id
      LEFT JOIN LATERAL (
        SELECT en.tipo_embalagem, en.volume_por_unidade
          FROM public.envase en
         WHERE en.lote_id = e2.lote_id
         ORDER BY en.data_envase DESC NULLS LAST
         LIMIT 1
      ) env ON true
     WHERE e2.id = p_entrega_id;
  END IF;

  v_transporte := jsonb_build_object(
    'modalidade', e.tipo_entrega,
    'motorista', e.motorista,
    'motorista_telefone', e.motorista_telefone,
    'veiculo', e.veiculo,
    'placa', e.veiculo_placa,
    'veiculo_tipo', e.veiculo_tipo,
    'data_saida', e.data_saida,
    'hora_saida_prevista', e.hora_saida_prevista
  );

  v_receb := jsonb_build_object(
    'recebido_por_nome', coalesce(nullif(btrim(coalesce(e.recebido_por_nome, '')), ''),
                                  nullif(btrim(coalesce(e.recebedor_nome, '')), '')),
    'documento', coalesce(e.recebido_por_documento, e.recebedor_documento),
    'cargo', coalesce(e.recebido_por_cargo, e.recebedor_cargo),
    'observacoes', e.observacoes_confirmacao,
    'confirmado_em', coalesce(e.confirmada_em, e.entregue_em, e.recebimento_confirmado_em),
    'confirmado_por', coalesce(e.confirmado_por, e.confirmada_por, e.recebimento_confirmado_por),
    'assinatura_tipo', e.assinatura_tipo
  );

  RETURN jsonb_build_object(
    'template_versao', 'comprovante-entrega-v1',
    'entrega_id', e.id,
    'entrega_status', e.status::text,
    'emitente', coalesce(v_emitente, '{}'::jsonb),
    'destinatario', coalesce(v_destino, '{}'::jsonb),
    'ordem_servico', v_os,
    'itens', coalesce(v_itens, '[]'::jsonb),
    'transporte', v_transporte,
    'recebimento', v_receb
  );
END
$$;


ALTER FUNCTION public.fn_comprovante_entrega_montar_v1(p_entrega_id uuid) OWNER TO postgres;

--
-- Name: produto_conformidade_perfis; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.produto_conformidade_perfis (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    perfil_key text NOT NULL,
    produto_id uuid,
    categoria text,
    versao integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'rascunho'::text NOT NULL,
    vigencia_inicio date,
    vigencia_fim date,
    responsavel_informacao text,
    fonte_documento text,
    documento_referencia text,
    documento_validade date,
    campos_obrigatorios text[] DEFAULT ARRAY[]::text[] NOT NULL,
    conservacao_texto text,
    transporte_texto text,
    uso_texto text,
    advertencias text[] DEFAULT ARRAY[]::text[] NOT NULL,
    responsavel_tecnico_nome text,
    responsavel_tecnico_registro text,
    registro_mapa text,
    identificadores_regulatorios jsonb DEFAULT '{}'::jsonb NOT NULL,
    identificadores_fiscais jsonb DEFAULT '{}'::jsonb NOT NULL,
    politica_validade text,
    validade_meses integer,
    template_versao text,
    criado_por uuid,
    aprovado_por uuid,
    aprovado_em timestamp with time zone,
    motivo_aprovacao text,
    inativado_por uuid,
    inativado_em timestamp with time zone,
    motivo_inativacao text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pcp_escopo_chk CHECK (((produto_id IS NOT NULL) OR (categoria IS NOT NULL))),
    CONSTRAINT pcp_status_chk CHECK ((status = ANY (ARRAY['rascunho'::text, 'em_revisao'::text, 'aprovado'::text, 'inativo'::text]))),
    CONSTRAINT pcp_validade_meses_chk CHECK (((validade_meses IS NULL) OR (validade_meses > 0)))
);


ALTER TABLE public.produto_conformidade_perfis OWNER TO postgres;

--
-- Name: fn_conformidade_perfil_vigente(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_conformidade_perfil_vigente(p_produto_id uuid, p_categoria text) RETURNS public.produto_conformidade_perfis
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT *
  FROM public.produto_conformidade_perfis p
  WHERE p.status = 'aprovado'
    AND (p.vigencia_inicio IS NULL OR p.vigencia_inicio <= CURRENT_DATE)
    AND (p.vigencia_fim IS NULL OR p.vigencia_fim >= CURRENT_DATE)
    AND (
      (p_produto_id IS NOT NULL AND p.produto_id = p_produto_id)
      OR (p.produto_id IS NULL AND p_categoria IS NOT NULL AND p.categoria = p_categoria)
    )
  ORDER BY (p.produto_id IS NOT NULL) DESC, p.versao DESC
  LIMIT 1;
$$;


ALTER FUNCTION public.fn_conformidade_perfil_vigente(p_produto_id uuid, p_categoria text) OWNER TO postgres;

--
-- Name: fn_cq_aprovado_avanca_os(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cq_aprovado_avanca_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  IF EXISTS(SELECT 1 FROM public.lotes l JOIN public.programacao_producao p ON p.id=l.programacao_id WHERE l.id=NEW.lote_id AND p.ordem_servico_id IS NOT NULL) THEN RETURN NEW; END IF;
  IF NEW.resultado::text <> 'aprovado' THEN
    RETURN NEW;
  END IF;

  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Mirror status on programacao and lote
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id;

  -- Advance OS On-Farm if it is at em_producao or em_cq
  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'envase'
      WHERE id = v_os_onfarm_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  -- Advance legacy OS if it is at em_producao or em_cq
  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'envase'
      WHERE id = v_os_id
        AND status::text IN ('em_producao','em_cq');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cq_aprovado_avanca_os() OWNER TO postgres;

--
-- Name: fn_cq_autoria_servidor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cq_autoria_servidor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_profile uuid;
BEGIN
  -- Sem excecao por GUC: autoria e imutabilidade valem em todas as chamadas.
  IF TG_OP = 'INSERT' THEN
    IF v_uid IS NOT NULL THEN
      SELECT id INTO v_profile FROM public.profiles WHERE user_id = v_uid LIMIT 1;
      IF v_profile IS NOT NULL THEN
        IF NEW.responsavel_id IS NOT NULL AND NEW.responsavel_id IS DISTINCT FROM v_profile THEN
          RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: responsavel_id informado (%) difere do perfil do usuario autenticado.', NEW.responsavel_id
            USING ERRCODE = 'check_violation';
        END IF;
        NEW.responsavel_id := v_profile;
      ELSIF NEW.responsavel_id IS NOT NULL THEN
        RAISE EXCEPTION 'CQ_AUTORIA_FORJADA: usuario autenticado sem perfil nao pode informar responsavel_id.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id THEN
    RAISE EXCEPTION 'CQ_AUTORIA_IMUTAVEL: responsavel_id da analise % nao pode ser alterado.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.seq IS DISTINCT FROM OLD.seq
     OR NEW.lote_id IS DISTINCT FROM OLD.lote_id THEN
    RAISE EXCEPTION 'CQ_TRILHA_IMUTAVEL: created_at/seq/lote_id da analise % nao podem ser alterados.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cq_autoria_servidor() OWNER TO postgres;

--
-- Name: fn_cq_resultado_imutavel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cq_resultado_imutavel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Sem excecao por GUC: autoria e imutabilidade valem em todas as chamadas.
  IF TG_OP = 'DELETE' THEN
    IF OLD.resultado IS NOT NULL THEN
      RAISE EXCEPTION 'CQ_RESULTADO_FINAL_IMUTAVEL: análise % do lote % já possui resultado final (%) e não pode ser excluída. Registre uma nova análise (reanálise) para o mesmo lote.',
        OLD.id, OLD.lote_id, OLD.resultado USING ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
  END IF;

  -- transição inicial (pendente -> resultado final) continua permitida
  IF OLD.resultado IS NULL THEN
    IF NEW.lote_id IS DISTINCT FROM OLD.lote_id THEN
      RAISE EXCEPTION 'CQ_LOTE_IMUTAVEL: não é permitido mover a análise de CQ para outro lote.'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.resultado      IS DISTINCT FROM OLD.resultado
     OR NEW.lote_id        IS DISTINCT FROM OLD.lote_id
     OR NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id
     OR NEW.responsavel    IS DISTINCT FROM OLD.responsavel
     OR NEW.data_analise   IS DISTINCT FROM OLD.data_analise
     OR NEW.created_at     IS DISTINCT FROM OLD.created_at
     OR NEW.seq            IS DISTINCT FROM OLD.seq
     OR NEW.ph             IS DISTINCT FROM OLD.ph
     OR NEW.aparencia      IS DISTINCT FROM OLD.aparencia
     OR NEW.odor           IS DISTINCT FROM OLD.odor
     OR NEW.concentracao   IS DISTINCT FROM OLD.concentracao
     OR NEW.contaminacao   IS DISTINCT FROM OLD.contaminacao
  THEN
    RAISE EXCEPTION 'CQ_RESULTADO_FINAL_IMUTAVEL: a análise % do lote % já foi finalizada (%). Registre uma NOVA análise (reanálise) para o mesmo lote em vez de sobrescrever o histórico.',
      OLD.id, OLD.lote_id, OLD.resultado USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_cq_resultado_imutavel() OWNER TO postgres;

