--
-- Name: fn_create_programacao_on_os_classica_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_programacao_on_os_classica_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status::text NOT IN ('aberta','aprovada','programada') THEN
    RETURN NEW;
  END IF;
  IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.programacao_producao WHERE ordem_servico_id = NEW.id) THEN
    RETURN NEW;
  END IF;
  INSERT INTO public.programacao_producao
    (produto_id, microrganismo_id, volume_necessario, data_programada, status, ordem_servico_id)
  VALUES
    (NEW.produto_id, NEW.microrganismo_id, NEW.volume_total_ml,
     COALESCE(NEW.data_programada, CURRENT_DATE), 'aguardando', NEW.id);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_create_programacao_on_os_classica_insert() OWNER TO postgres;

--
-- Name: fn_create_programacao_on_os_onfarm_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_create_programacao_on_os_onfarm_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.status::text NOT IN ('aberta','aprovada','programada') THEN RETURN NEW; END IF;
 IF NEW.produto_id IS NULL AND NEW.microrganismo_id IS NULL THEN RETURN NEW; END IF;
 PERFORM platform_private.lab_assert_manufacturable(NEW.produto_id,NEW.microrganismo_id);
 IF EXISTS(SELECT 1 FROM public.programacao_producao WHERE ordem_servico_onfarm_id=NEW.id) THEN RETURN NEW; END IF;
 INSERT INTO public.programacao_producao(produto_id,microrganismo_id,volume_necessario,data_programada,status,ordem_servico_onfarm_id)
 VALUES(NEW.produto_id,NEW.microrganismo_id,NEW.volume_total_ml,coalesce(NEW.data_recomendada,CURRENT_DATE),'aguardando',NEW.id);
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_create_programacao_on_os_onfarm_insert() OWNER TO postgres;

--
-- Name: fn_cultura_em_uso(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_cultura_em_uso(_cultura_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM public.talhoes t WHERE t.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.talhao_safras ts WHERE ts.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.visitas_campo v WHERE v.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.registros_consultor r WHERE r.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.ordens_servico_onfarm o WHERE o.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.product_crop_recommendations p WHERE p.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.microorganism_crop_recommendations m WHERE m.cultura_id = _cultura_id)
      OR EXISTS (SELECT 1 FROM public.objetivos_visita_sugestoes ov WHERE ov.cultura_id = _cultura_id);
$$;


ALTER FUNCTION public.fn_cultura_em_uso(_cultura_id uuid) OWNER TO postgres;

--
-- Name: fn_entrega_assert_confirmador(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_assert_confirmador(p_origem text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid    uuid := auth.uid();
  v_origem text := public.fn_cockpit_norm_origem(p_origem);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;

  IF public.has_role(v_uid, 'administrador'::app_role)
     OR public.has_role(v_uid, 'gestor'::app_role)
     OR public.has_role(v_uid, 'administrativo'::app_role)
     OR public.has_role(v_uid, 'producao'::app_role) THEN
    RETURN v_origem;
  END IF;

  IF public.has_role(v_uid, 'operador_onfarm'::app_role) THEN
    IF v_origem <> 'onfarm' THEN RAISE EXCEPTION 'COCKPIT_FORBIDDEN_ORIGEM'; END IF;
    RETURN v_origem;
  END IF;

  RAISE EXCEPTION 'COCKPIT_FORBIDDEN';
END;
$$;


ALTER FUNCTION public.fn_entrega_assert_confirmador(p_origem text) OWNER TO postgres;

--
-- Name: fn_entrega_assinatura_exigir_imagem_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_assinatura_exigir_imagem_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF NEW.assinatura_tipo='digital_tela' AND NEW.assinatura_digital_png_path IS NULL THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='A assinatura digital exige uma imagem armazenada.';
 END IF;
 IF NEW.assinatura_digital_png_path IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM storage.objects o
  WHERE o.bucket_id='entrega-documentos' AND o.name=NEW.assinatura_digital_png_path
 ) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Imagem da assinatura não encontrada ou sem acesso no armazenamento.';
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_entrega_assinatura_exigir_imagem_v1() OWNER TO postgres;

--
-- Name: fn_entrega_build_snapshot_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_build_snapshot_v1(p_entrega_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'sessao_invalida' USING ERRCODE = '42501';
  END IF;
  IF NOT coalesce(public.is_delivery_staff(auth.uid()), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'template_versao', 'termo-entrega-v1',
    'gerado_em', now(),
    'entrega', to_jsonb(e),
    'cliente', (SELECT to_jsonb(c) FROM public.clientes c WHERE c.id = e.cliente_id),
    'ordem_servico', (SELECT to_jsonb(o) FROM public.ordens_servico o WHERE o.id = e.ordem_servico_id),
    'ordem_servico_onfarm', (SELECT to_jsonb(o) FROM public.ordens_servico_onfarm o WHERE o.id = e.ordem_servico_onfarm_id),
    'pedido_b2b', (SELECT to_jsonb(po) FROM public.partner_orders po WHERE po.id = e.partner_order_id),
    'comprovante', (SELECT to_jsonb(cp) FROM public.entrega_comprovantes cp WHERE cp.id = e.comprovante_id),
    'entregador', jsonb_build_object(
      'motorista', e.motorista, 'documento', e.motorista_documento,
      'telefone', e.motorista_telefone, 'veiculo', e.veiculo,
      'placa', e.veiculo_placa, 'tipo', e.veiculo_tipo),
    'destino', jsonb_build_object(
      'destinatario', e.destinatario_nome, 'telefone', e.destinatario_telefone,
      'logradouro', e.endereco_logradouro, 'numero', e.endereco_numero,
      'complemento', e.endereco_complemento, 'bairro', e.endereco_bairro,
      'cidade', e.endereco_cidade, 'uf', e.endereco_uf, 'cep', e.endereco_cep,
      'referencia', e.endereco_referencia, 'origem', e.endereco_origem),
    'recebedor', jsonb_build_object(
      'nome', e.recebedor_nome, 'documento', e.recebedor_documento,
      'cargo', e.recebedor_cargo, 'telefone', e.recebedor_telefone),
    'itens', coalesce((
      SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'etiqueta', to_jsonb(pe),
        'embalagem', (SELECT to_jsonb(eb) FROM public.estoque_embalagens eb WHERE eb.id = pe.embalagem_id),
        'lote', (SELECT to_jsonb(l) FROM public.lotes l WHERE l.id = pe.lote_id),
        'produto', (SELECT to_jsonb(pr) FROM public.produtos pr WHERE pr.id = pe.produto_id),
        'conferencia', (SELECT to_jsonb(ci) FROM public.entrega_conferencia_itens ci
                        WHERE ci.entrega_id = p_entrega_id AND ci.etiqueta_id = pe.id)
      )) ORDER BY pe.id)
      FROM public.entrega_etiquetas ee
      JOIN public.produto_etiquetas pe ON pe.id = ee.etiqueta_id
      WHERE ee.entrega_id = p_entrega_id AND ee.ativo
    ), '[]'::jsonb),
    'checklist', coalesce((SELECT jsonb_agg(to_jsonb(ck) ORDER BY ck.id)
                           FROM public.entrega_checklist ck WHERE ck.entrega_id = p_entrega_id), '[]'::jsonb),
    'ocorrencias', coalesce((SELECT jsonb_agg(to_jsonb(oc) ORDER BY oc.id)
                             FROM public.entrega_ocorrencias oc WHERE oc.entrega_id = p_entrega_id), '[]'::jsonb),
    'divergencias', coalesce((
      SELECT jsonb_agg(jsonb_build_object('etiqueta_id', ci.etiqueta_id, 'status', ci.status,
                                          'quantidade', ci.quantidade, 'motivo', ci.motivo) ORDER BY ci.id)
      FROM public.entrega_conferencia_itens ci
      WHERE ci.entrega_id = p_entrega_id AND ci.status <> 'aceito'), '[]'::jsonb)
  ))
  INTO v
  FROM public.entregas e
  WHERE e.id = p_entrega_id;

  IF v IS NULL THEN
    RAISE EXCEPTION 'entrega_nao_encontrada' USING ERRCODE = 'raise_exception';
  END IF;
  RETURN v;
END $$;


ALTER FUNCTION public.fn_entrega_build_snapshot_v1(p_entrega_id uuid) OWNER TO postgres;

--
-- Name: fn_entrega_cobertura_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_cobertura_v1(p_entrega_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN (SELECT count(*) FROM public.entrega_etiquetas ee
          WHERE ee.entrega_id = p_entrega_id AND ee.ativo) = 0 THEN 'pendente'
    WHEN EXISTS (SELECT 1 FROM public.entrega_etiquetas ee
                 LEFT JOIN public.entrega_conferencia_itens ci
                   ON ci.entrega_id = ee.entrega_id AND ci.etiqueta_id = ee.etiqueta_id
                 WHERE ee.entrega_id = p_entrega_id AND ee.ativo
                   AND coalesce(ci.status,'pendente') = 'pendente') THEN 'pendente'
    WHEN EXISTS (SELECT 1 FROM public.entrega_conferencia_itens ci
                 WHERE ci.entrega_id = p_entrega_id AND ci.status = 'recusado') THEN 'parcial'
    ELSE 'integral'
  END
$$;


ALTER FUNCTION public.fn_entrega_cobertura_v1(p_entrega_id uuid) OWNER TO postgres;

--
-- Name: fn_entrega_comprovante_exigir_arquivo_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_comprovante_exigir_arquivo_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NEW.arquivo_path IS NULL THEN
    IF NEW.assinatura_tipo = 'fisica_anexada' THEN
      RAISE EXCEPTION USING ERRCODE = '23514',
        MESSAGE = 'O comprovante físico exige um arquivo anexado.';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM storage.objects AS o
    WHERE o.bucket_id = 'entrega-documentos'
      AND o.name = NEW.arquivo_path
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514',
      MESSAGE = 'Arquivo do comprovante não encontrado ou sem acesso no armazenamento.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_entrega_comprovante_exigir_arquivo_v1() OWNER TO postgres;

--
-- Name: fn_entrega_comprovante_preservar_encerrado_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_comprovante_preservar_encerrado_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
 v_operacionais text[]:=ARRAY['updated_at','metadata','qr_code_path','qr_code_generated_at','validation_public_enabled','validation_expires_at','validation_url'];
 v_campo text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.status='confirmado' OR OLD.metadata ? 'comprovante_snapshot_v1' THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Comprovante encerrado não pode ser excluído.';
  END IF;
  RETURN OLD;
 END IF;
 IF OLD.status='confirmado' AND
   (to_jsonb(NEW)-v_operacionais) IS DISTINCT FROM (to_jsonb(OLD)-v_operacionais) THEN
  RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Dados do comprovante confirmado não podem ser alterados.';
 END IF;
 IF OLD.metadata ? 'comprovante_snapshot_v1' THEN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
   RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Vínculo do comprovante congelado não pode ser alterado.';
  END IF;
  FOREACH v_campo IN ARRAY ARRAY['comprovante_snapshot_v1','comprovante_snapshot_hash','comprovante_numero'] LOOP
   IF NEW.metadata->v_campo IS DISTINCT FROM OLD.metadata->v_campo THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Conteúdo do comprovante congelado não pode ser alterado.';
   END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_entrega_comprovante_preservar_encerrado_v1() OWNER TO postgres;

--
-- Name: fn_entrega_confirmar_engine_v1(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_confirmar_engine_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb, p_opcoes jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_os_id uuid;
  v_ent record;
  v_est public.estoque_produto%ROWTYPE;
  v_pendentes int; v_total_entregue numeric; v_total_reservado numeric;
  v_finalizada boolean := false; v_avanco jsonb;
  v_recebedor_nome text;
  v_entregue_em timestamptz;
  v_faturamento text := nullif(btrim(coalesce(p_opcoes->>'faturamento','')), '');
  v_motivo_nb text := nullif(btrim(coalesce(p_opcoes->>'motivo_nao_faturavel','')), '');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'COCKPIT_UNAUTHENTICATED'; END IF;
  IF p_entrega_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;

  PERFORM public.fn_estoque_ctx_open(jsonb_build_object(
    'acao','entrega','origem','fn_entrega_confirmar_engine_v1','usuario_id', v_uid::text));

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_entrega:' || p_entrega_id::text));

  SELECT e.id, e.status::text AS status, e.estoque_produto_id,
         coalesce(e.quantidade_entregue, 0) AS qtd, e.partner_order_id,
         e.ordem_servico_id, e.ordem_servico_onfarm_id
    INTO v_ent
    FROM public.entregas e
   WHERE e.id = p_entrega_id
   FOR UPDATE;

  IF v_ent.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_NAO_ENCONTRADA'; END IF;

  -- Origem: explícita quando informada; derivada do vínculo caso contrário.
  IF nullif(btrim(coalesce(p_origem,'')), '') IS NOT NULL THEN
    v_origem := public.fn_cockpit_norm_origem(p_origem);
  ELSIF v_ent.ordem_servico_onfarm_id IS NOT NULL THEN
    v_origem := 'onfarm';
  ELSIF v_ent.partner_order_id IS NOT NULL THEN
    v_origem := 'b2b';
  ELSE
    v_origem := 'manual';
  END IF;

  v_origem := public.fn_entrega_assert_confirmador(v_origem);

  v_os_id := CASE WHEN v_origem = 'onfarm' THEN v_ent.ordem_servico_onfarm_id
                  ELSE v_ent.ordem_servico_id END;

  IF p_os_id IS NOT NULL AND v_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_OS';
  END IF;

  IF v_ent.status = 'cancelada' THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_CANCELADA'; END IF;
  IF v_ent.status = 'entregue' THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'finalizada', false,
      'entrega_id', p_entrega_id,
      'message', 'Entrega já confirmada anteriormente.');
  END IF;

  IF v_origem = 'b2b' AND v_ent.partner_order_id IS NOT NULL THEN
    PERFORM public.fn_cockpit_assert_b2b_liberado(v_ent.partner_order_id);
  END IF;

  IF v_ent.estoque_produto_id IS NOT NULL THEN
    SELECT * INTO v_est FROM public.estoque_produto WHERE id = v_ent.estoque_produto_id FOR UPDATE;
    IF v_est.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO'; END IF;
    IF v_est.status::text <> 'expedido' THEN
      IF v_os_id IS NOT NULL THEN
        IF v_est.reservado_para_os_id IS DISTINCT FROM v_os_id THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
        END IF;
        IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
          RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
        END IF;
      END IF;
      IF v_ent.qtd > coalesce(v_est.quantidade, 0) THEN
        RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
      END IF;
    END IF;
  END IF;

  -- Recebedor físico é OBRIGATÓRIO e distinto de confirmado_por.
  v_recebedor_nome := nullif(btrim(coalesce(p_recebedor->>'nome','')), '');
  IF v_recebedor_nome IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;

  v_entregue_em := coalesce(nullif(btrim(coalesce(p_opcoes->>'entregue_em','')), '')::timestamptz, now());

  UPDATE public.entregas
     SET status = 'entregue'::public.status_entrega,
         entregue_em = v_entregue_em,
         recebido_por_nome = v_recebedor_nome,
         recebido_por_cargo = coalesce(nullif(btrim(coalesce(p_recebedor->>'cargo','')), ''), recebido_por_cargo),
         recebido_por_documento = coalesce(nullif(btrim(coalesce(p_recebedor->>'documento','')), ''), recebido_por_documento),
         observacoes_confirmacao = coalesce(nullif(btrim(coalesce(p_recebedor->>'observacoes','')), ''), observacoes_confirmacao),
         confirmado_por = v_uid,
         financial_status = CASE WHEN v_faturamento = 'bill_later' THEN 'PENDING_BILLING'
                                 ELSE financial_status END
   WHERE id = p_entrega_id;

  IF v_est.id IS NOT NULL THEN
    UPDATE public.estoque_produto
       SET status = 'expedido'::public.status_estoque, expedido_por = v_uid,
           expedido_em = now(), updated_at = now()
     WHERE id = v_est.id AND status <> 'expedido'::public.status_estoque;

    IF FOUND THEN
      INSERT INTO public.estoque_movimentacoes
        (estoque_produto_id, acao, quantidade, status_anterior, status_novo, os_id, os_tipo, usuario_id, lote_id, observacao)
      VALUES (v_est.id, 'expedicao', v_ent.qtd, 'reservado', 'expedido',
              v_os_id, v_origem, v_uid, v_est.lote_id, 'Baixa por confirmação de entrega');
    END IF;
  END IF;

  IF v_os_id IS NOT NULL THEN
    v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'enviar_entrega', NULL);

    INSERT INTO public.laboratorio_esteira_eventos
      (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
    VALUES (v_os_id, v_origem, 'em_entrega', 'entregue', 'confirmar_entrega_v1', v_uid,
            format('Confirmação transacional da entrega %s (recebedor: %s)', p_entrega_id, v_recebedor_nome));

    IF v_origem = 'onfarm' THEN
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_onfarm_id = v_os_id;
    ELSE
      SELECT count(*) FILTER (WHERE status::text NOT IN ('entregue','cancelada')),
             coalesce(sum(quantidade_entregue) FILTER (WHERE status::text = 'entregue'), 0)
        INTO v_pendentes, v_total_entregue
        FROM public.entregas WHERE ordem_servico_id = v_os_id;
    END IF;

    SELECT coalesce(sum(quantidade_reservada), 0) INTO v_total_reservado
      FROM public.estoque_produto
     WHERE reservado_para_os_id = v_os_id
       AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
       AND status <> 'estornado'::public.status_estoque;

    IF v_pendentes = 0 AND v_total_reservado > 0 AND v_total_entregue >= v_total_reservado THEN
      v_avanco := public._rpc_avancar_esteira_laboratorio_internal(v_os_id, v_origem, 'finalizar_os', NULL);
      IF coalesce((v_avanco->>'success')::boolean, false) THEN
        v_finalizada := true;
        INSERT INTO public.laboratorio_esteira_eventos
          (os_id, origem_os, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
        VALUES (v_os_id, v_origem, 'entregue', 'finalizada', 'finalizacao_automatica_por_entrega', v_uid,
                'Cobertura completa: OS finalizada na mesma transação da confirmação de entrega.');
      END IF;
    END IF;
  END IF;

  IF v_faturamento = 'not_billable' THEN
    IF v_motivo_nb IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_MOTIVO_NAO_FATURAVEL_OBRIGATORIO'; END IF;
    PERFORM public.fn_mark_entrega_not_billable(p_entrega_id, v_motivo_nb);
  END IF;

  RETURN jsonb_build_object('success', true, 'replay', false, 'finalizada', v_finalizada,
    'entrega_id', p_entrega_id, 'os_id', v_os_id, 'origem', v_origem,
    'parcial', (coalesce(v_pendentes, 0) > 0 OR coalesce(v_total_entregue, 0) < coalesce(v_total_reservado, 0)),
    'total_entregue', coalesce(v_total_entregue, 0), 'total_reservado', coalesce(v_total_reservado, 0),
    'message', CASE WHEN v_finalizada THEN 'Entrega confirmada — OS finalizada.'
                    ELSE 'Entrega confirmada.' END);
END;
$$;


ALTER FUNCTION public.fn_entrega_confirmar_engine_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb, p_opcoes jsonb) OWNER TO postgres;

--
-- Name: fn_entrega_evidencia_estado_editavel_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_evidencia_estado_editavel_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE v_id uuid; v_status text; v_comp_status text;
BEGIN
 IF TG_OP='UPDATE' AND NEW.entrega_id IS DISTINCT FROM OLD.entrega_id THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Não é permitido transferir evidências entre entregas.';
 END IF;
 IF TG_OP='DELETE' THEN v_id:=OLD.entrega_id; ELSE v_id:=NEW.entrega_id; END IF;
 SELECT e.status,e.comprovante_status INTO v_status,v_comp_status
 FROM public.entregas e WHERE e.id=v_id FOR SHARE;
 IF NOT FOUND THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Entrega não encontrada ou sem acesso.';
 END IF;
 IF v_status='cancelada' OR v_comp_status IN ('confirmado','dispensado') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='As evidências desta entrega estão encerradas e não podem ser alteradas.';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_entrega_evidencia_estado_editavel_v1() OWNER TO postgres;

--
-- Name: fn_entrega_guard_faturamento_v1(uuid, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_guard_faturamento_v1(p_entrega_id uuid, p_total numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_r public.entrega_reconciliacoes%ROWTYPE;
  v_conf int;
  v_canon jsonb;
  v_max numeric;
  v_canon_valor numeric;
BEGIN
  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  v_canon := public.fn_entrega_valor_faturavel_v1(p_entrega_id);

  -- H6C-001: condição comercial pendente/rejeitada/não vinculada bloqueia o
  -- faturamento em qualquer modo, inclusive o manual.
  IF (v_canon->>'origem') = 'bloqueado' THEN
    RAISE EXCEPTION 'condicao_b2b_bloqueada: %', COALESCE(v_canon->>'motivo','indefinido')
      USING ERRCODE='check_violation';
  END IF;

  v_canon_valor := NULLIF(v_canon->>'valor','')::numeric;

  IF v_conf = 0 THEN
    -- H6c-003: entrega integral também é comparada ao canônico, quando existir.
    IF v_canon_valor IS NOT NULL AND p_total IS NOT NULL
       AND abs(p_total - v_canon_valor) > 0.01 THEN
      RAISE EXCEPTION 'valor_divergente_do_canonico: informado=%, canonico=%',
        round(p_total,2), round(v_canon_valor,2) USING ERRCODE='check_violation';
    END IF;
    IF v_canon_valor IS NULL THEN
      -- sem fonte histórica confiável: fluxo legado/manual, o guard não arbitra preço.
      RETURN jsonb_build_object('modo','legado','ratio_aceito',1,'canonico',v_canon);
    END IF;
    RETURN jsonb_build_object('modo','integral_canonico','ratio_aceito',1,
                              'valor_faturavel_max', round(v_canon_valor,2),
                              'canonico', v_canon);
  END IF;

  SELECT * INTO v_r FROM public.entrega_reconciliacoes
   WHERE entrega_id = p_entrega_id AND status = 'reconciliada';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entrega_nao_reconciliada: conclua a conferencia e a reconciliacao antes de faturar'
      USING ERRCODE='check_violation';
  END IF;
  IF NOT v_r.faturavel THEN
    RAISE EXCEPTION 'entrega_nao_faturavel: todos os itens foram recusados'
      USING ERRCODE='check_violation';
  END IF;

  v_max := COALESCE(v_r.valor_faturavel_max, v_canon_valor);
  IF v_max IS NOT NULL AND p_total > v_max + 0.01 THEN
    RAISE EXCEPTION 'valor_acima_do_aceito' USING ERRCODE='check_violation';
  END IF;

  RETURN jsonb_build_object('modo', 'reconciliado', 'reconciliacao_id', v_r.id,
                            'ratio_aceito', v_r.ratio_aceito,
                            'valor_faturavel_max', v_max, 'canonico', v_canon);
END
$$;


ALTER FUNCTION public.fn_entrega_guard_faturamento_v1(p_entrega_id uuid, p_total numeric) OWNER TO postgres;

--
-- Name: fn_entrega_marcar_cancelamento(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_marcar_cancelamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF NEW.status::text='cancelada' AND (TG_OP='INSERT' OR OLD.status::text IS DISTINCT FROM 'cancelada') THEN
  UPDATE platform_private.delivery_context_20261030 SET consumed=true
   WHERE txid=pg_catalog.txid_current() AND actor=auth.uid() AND organization_id=NEW.organization_id
    AND action='cancel' AND target=NEW.id AND consumed=false;
  IF NOT FOUND THEN RAISE EXCEPTION 'ENTREGA_CANCELAMENTO_EXIGE_RPC' USING ERRCODE='42501'; END IF;
  NEW.cancelada_em:=COALESCE(NEW.cancelada_em,pg_catalog.now()); NEW.cancelada_por:=auth.uid();
 END IF;
 RETURN NEW;
END $$;


ALTER FUNCTION public.fn_entrega_marcar_cancelamento() OWNER TO postgres;

--
-- Name: fn_entrega_valor_faturavel_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_entrega_valor_faturavel_v1(p_entrega_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_e public.entregas%ROWTYPE;
  v_po public.partner_orders%ROWTYPE;
  v_t public.partner_order_payment_terms%ROWTYPE;
  v_fin text;
  v_ap text;
  v_total_snapshot numeric;
  v_origem text;
  v_base numeric;
  v_aceito numeric;
  v_valor numeric;
  v_conf int;
  v_itens jsonb;
  v_ident jsonb;
BEGIN
  SELECT * INTO v_e FROM public.entregas WHERE id = p_entrega_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('origem','indisponivel','motivo','entrega_nao_encontrada');
  END IF;

  SELECT count(*)::int INTO v_conf
    FROM public.entrega_conferencia_itens WHERE entrega_id = p_entrega_id;

  -- ------------------- caminho B2B (snapshot canônico) -------------------
  IF v_e.partner_order_id IS NOT NULL THEN
    SELECT * INTO v_po FROM public.partner_orders WHERE id = v_e.partner_order_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','pedido_b2b_nao_encontrado');
    END IF;

    v_fin := COALESCE(v_po.financial_approval_status, 'not_required');
    v_ident := jsonb_build_object(
      'partner_order_id', v_po.id,
      'payment_terms_id', v_po.payment_terms_id,
      'financial_approval_status', v_fin,
      'order_status', v_po.status);

    IF v_po.payment_terms_id IS NOT NULL THEN
      -- identidade imutável da condição econômica
      SELECT * INTO v_t FROM public.partner_order_payment_terms
       WHERE id = v_po.payment_terms_id;
      IF NOT FOUND OR v_t.partner_order_id IS DISTINCT FROM v_po.id THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_canonico_invalido')
               || v_ident;
      END IF;

      v_ap := COALESCE(v_t.approval_status, 'pending');
      v_ident := v_ident || jsonb_build_object('approval_status', v_ap);

      IF v_ap = 'approved' THEN
        NULL; -- liberado
      ELSIF v_ap = 'not_required'
            AND v_fin = 'not_required'
            AND COALESCE(v_po.requires_financial_approval, false) = false THEN
        NULL; -- liberado: nenhuma aprovação exigida em nenhum nível
      ELSE
        -- pending / rejected / adjustment_requested / incoerência => fail-closed.
        -- Proibido fallback silencioso para outro termo ou para o pedido.
        RETURN jsonb_build_object('origem','bloqueado','motivo','condicao_b2b_nao_liberada')
               || v_ident;
      END IF;

      v_total_snapshot := v_t.final_amount;
      v_origem := 'B2B_PAYMENT_TERMS_SNAPSHOT';
    ELSE
      -- legado: sem condição vinculada ao pedido.
      IF EXISTS (SELECT 1 FROM public.partner_order_payment_terms t
                  WHERE t.partner_order_id = v_po.id) THEN
        -- existe termo, mas não é o canônico do pedido => nunca usar "o mais novo"
        RETURN jsonb_build_object('origem','bloqueado','motivo','termo_nao_vinculado_ao_pedido')
               || v_ident;
      END IF;
      IF v_fin IN ('pending','rejected') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','aprovacao_financeira_'||v_fin)
               || v_ident;
      END IF;
      IF COALESCE(v_po.status,'') IN ('cancelado','reprovado','reprovado_sem_itens',
                                      'rascunho','pendente','solicitado','em_analise_comercial',
                                      'aguardando_aprovacao_credito','aguardando_ajuste_comercial',
                                      'aguardando_itens','aguardando_cotacao') THEN
        RETURN jsonb_build_object('origem','bloqueado','motivo','pedido_nao_faturavel')
               || v_ident;
      END IF;
      v_total_snapshot := COALESCE(v_po.final_amount_with_interest, v_po.total);
      v_origem := 'B2B_ORDER_SNAPSHOT_LEGACY';
    END IF;

    IF v_total_snapshot IS NULL OR v_total_snapshot <= 0 THEN
      RETURN jsonb_build_object('origem','indisponivel','motivo','snapshot_b2b_ausente')
             || v_ident;
    END IF;

    -- base econômica do pedido = soma dos subtotais snapshot dos itens
    SELECT COALESCE(sum(COALESCE(i.subtotal,
             COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0))), 0)
      INTO v_base
      FROM public.partner_order_items i WHERE i.order_id = v_po.id;

    IF v_conf = 0 OR v_base <= 0 THEN
      RETURN jsonb_build_object('origem', v_origem, 'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','integral','total_snapshot', round(v_total_snapshot,2),
                                     'base_itens', round(COALESCE(v_base,0),2)))
             || v_ident;
    END IF;

    -- participação econômica aceita POR PRODUTO (volume conferido aceito / volume conferido)
    WITH conf AS (
      SELECT ee.produto_id AS produto_id, ci.status AS status,
             COALESCE(ee.volume,0) * COALESCE(ci.quantidade,1) AS vol
        FROM public.entrega_conferencia_itens ci
        JOIN public.estoque_embalagens ee ON ee.id = ci.embalagem_id
       WHERE ci.entrega_id = p_entrega_id
    ), ratio AS (
      SELECT produto_id,
             CASE WHEN SUM(vol) > 0
                  THEN LEAST(1, round(COALESCE(SUM(vol) FILTER (WHERE status='aceito'), 0) / SUM(vol), 6))
                  ELSE 0 END AS r
        FROM conf GROUP BY produto_id
    ), itens AS (
      SELECT i.product_id AS product_id,
             COALESCE(i.subtotal,
               COALESCE(i.preco_unitario_final_snapshot, i.preco_unitario, 0) * COALESCE(i.quantidade,0)) AS sub,
             COALESCE(r.r, 0) AS r
        FROM public.partner_order_items i
        LEFT JOIN ratio r ON r.produto_id = i.product_id
       WHERE i.order_id = v_po.id
    )
    SELECT COALESCE(sum(sub * r),0),
           COALESCE(jsonb_agg(jsonb_build_object('produto_id', product_id,
                     'subtotal_snapshot', round(sub,2), 'ratio_aceito', r,
                     'base_aceita_item', round(sub * r, 2))
                    ORDER BY product_id), '[]'::jsonb)
      INTO v_aceito, v_itens
      FROM itens;

    IF abs(v_aceito - v_base) <= 0.01 THEN
      v_valor := round(v_total_snapshot, 2);
    ELSE
      -- alocação do ajuste histórico do pedido (juros/desconto de nível pedido)
      -- proporcional à participação econômica aceita dos itens.
      v_valor := round(v_total_snapshot * (v_aceito / v_base), 2);
    END IF;

    RETURN jsonb_build_object('origem', v_origem, 'valor', v_valor,
      'metodo', jsonb_build_object('tipo','participacao_economica_aceita_x_snapshot',
        'total_snapshot', round(v_total_snapshot,2),
        'base_itens', round(v_base,2), 'base_aceita', round(v_aceito,2),
        'fator', round(v_aceito / NULLIF(v_base,0), 6), 'itens', v_itens))
           || v_ident;
  END IF;

  -- ---------------- caminho OS / base de faturamento histórica -------------
  IF v_e.os_faturamento_base_id IS NOT NULL THEN
    SELECT b.valor_total_faturavel INTO v_total_snapshot
      FROM public.os_faturamento_base b WHERE b.id = v_e.os_faturamento_base_id;
    IF v_total_snapshot IS NOT NULL AND v_total_snapshot > 0 THEN
      RETURN jsonb_build_object('origem','OS_FATURAMENTO_BASE_SNAPSHOT',
        'valor', round(v_total_snapshot,2),
        'metodo', jsonb_build_object('tipo','os_base','os_faturamento_base_id', v_e.os_faturamento_base_id));
    END IF;
  END IF;

  RETURN jsonb_build_object('origem','indisponivel','motivo','sem_fonte_historica_confiavel');
END
$$;


ALTER FUNCTION public.fn_entrega_valor_faturavel_v1(p_entrega_id uuid) OWNER TO postgres;

--
-- Name: fn_envase_avanca_os(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_envase_avanca_os() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prog_id uuid;
  v_os_onfarm_id uuid;
  v_os_id uuid;
BEGIN
  SELECT programacao_id INTO v_prog_id FROM public.lotes WHERE id = NEW.lote_id;
  IF v_prog_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ordem_servico_onfarm_id, ordem_servico_id
    INTO v_os_onfarm_id, v_os_id
    FROM public.programacao_producao
    WHERE id = v_prog_id;

  -- Ensure lote is marked as aprovado (envase only passes if CQ aprovado)
  UPDATE public.lotes SET status = 'aprovado' WHERE id = NEW.lote_id AND status::text <> 'aprovado';
  UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id AND status::text <> 'aprovado';

  IF v_os_onfarm_id IS NOT NULL THEN
    UPDATE public.ordens_servico_onfarm
      SET status = 'pronto_entrega'
      WHERE id = v_os_onfarm_id
        AND status::text = 'envase';
  END IF;

  IF v_os_id IS NOT NULL THEN
    UPDATE public.ordens_servico
      SET status = 'pronto_entrega'
      WHERE id = v_os_id
        AND status::text = 'envase';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_envase_avanca_os() OWNER TO postgres;

--
-- Name: fn_envase_material_imutavel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_envase_material_imutavel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: o envase % do lote % nao pode ser excluido. Registre um estorno/novo envase.', OLD.id, OLD.lote_id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.lote_id IS DISTINCT FROM OLD.lote_id
     OR NEW.quantidade IS DISTINCT FROM OLD.quantidade
     OR NEW.volume_por_unidade IS DISTINCT FROM OLD.volume_por_unidade THEN
    RAISE EXCEPTION 'ENVASE_IMUTAVEL: lote/quantidade/volume_por_unidade do envase % nao podem ser alterados apos o registro.', OLD.id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_envase_material_imutavel() OWNER TO postgres;

