--
-- Name: fn_estoque_ctx_force(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_ctx_force(p_ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM set_config('app.estoque_mov_ctx', COALESCE(p_ctx, '{}'::jsonb)::text, true);
END; $$;


ALTER FUNCTION public.fn_estoque_ctx_force(p_ctx jsonb) OWNER TO postgres;

--
-- Name: fn_estoque_ctx_open(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_ctx_open(p_ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_atual text := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
BEGIN
  -- Contexto externo (operação principal) tem precedência sobre chamadas internas aninhadas
  IF v_atual IS NOT NULL THEN RETURN; END IF;
  PERFORM set_config('app.estoque_mov_ctx', COALESCE(p_ctx, '{}'::jsonb)::text, true);
END; $$;


ALTER FUNCTION public.fn_estoque_ctx_open(p_ctx jsonb) OWNER TO postgres;

--
-- Name: fn_estoque_ctx_read(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_ctx_read() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v text;
BEGIN
  v := NULLIF(current_setting('app.estoque_mov_ctx', true), '');
  IF v IS NULL THEN RETURN NULL; END IF;
  RETURN v::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END; $$;


ALTER FUNCTION public.fn_estoque_ctx_read() OWNER TO postgres;

--
-- Name: fn_estoque_fingerprint(text, uuid, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_fingerprint(p_acao text, p_item uuid, p_qtd numeric, p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT encode(extensions.digest(
    'estmovv1|'||coalesce(p_acao,'')||'|'||coalesce(p_item::text,'')||'|'||
    coalesce(trim_scale(p_qtd)::text,'')||'|'||
    coalesce((SELECT jsonb_object_agg(k, v ORDER BY k) FROM jsonb_each(coalesce(p_payload,'{}'::jsonb)) e(k,v))::text,'{}'),
    'sha256'),'hex');
$$;


ALTER FUNCTION public.fn_estoque_fingerprint(p_acao text, p_item uuid, p_qtd numeric, p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_estoque_pode_operar(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_pode_operar(_uid uuid, _acao text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN _uid IS NULL THEN false
    WHEN _acao IN ('ajuste','perda','descarte')
      THEN public.has_role(_uid,'administrador'::app_role) OR public.has_role(_uid,'gestor'::app_role)
        OR public.has_role(_uid,'producao'::app_role)
    ELSE public.has_role(_uid,'administrador'::app_role) OR public.has_role(_uid,'gestor'::app_role)
      OR public.has_role(_uid,'producao'::app_role) OR public.has_role(_uid,'administrativo'::app_role)
  END;
$$;


ALTER FUNCTION public.fn_estoque_pode_operar(_uid uuid, _acao text) OWNER TO postgres;

--
-- Name: fn_estoque_produto_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_estoque_produto_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ctx jsonb := public.fn_estoque_ctx_read();
BEGIN
  IF v_ctx IS NULL OR v_ctx->>'origem' IS NULL THEN
    RAISE EXCEPTION 'estoque_produto so pode ser alterado pelo motor canonico (rpc_estoque_operar_v1)'
      USING ERRCODE = '42501';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION public.fn_estoque_produto_guard() OWNER TO postgres;

--
-- Name: fn_fin_aging(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_aging(_type text DEFAULT 'RECEIVABLE'::text) RETURNS TABLE(bucket text, total numeric, qtd integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF _type = 'PAYABLE' THEN
    RETURN QUERY
    SELECT CASE WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 0 THEN 'A vencer'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 30 THEN '1-30'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 60 THEN '31-60'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 90 THEN '61-90'
                ELSE '90+' END,
           SUM(original_amount - COALESCE(paid_amount,0) - COALESCE(discount_amount,0))::numeric,
           COUNT(*)::int
    FROM accounts_payable_installments
    WHERE status IN ('OPEN','PARTIAL','OVERDUE')
    GROUP BY 1 ORDER BY 1;
  ELSE
    RETURN QUERY
    SELECT CASE WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 0 THEN 'A vencer'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 30 THEN '1-30'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 60 THEN '31-60'
                WHEN (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - due_date <= 90 THEN '61-90'
                ELSE '90+' END,
           SUM(original_amount - COALESCE(received_amount,0) - COALESCE(discount_amount,0))::numeric,
           COUNT(*)::int
    FROM accounts_receivable_installments
    WHERE status IN ('OPEN','PARTIAL','OVERDUE')
    GROUP BY 1 ORDER BY 1;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_aging(_type text) OWNER TO postgres;

--
-- Name: fn_fin_cashflow(date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_cashflow(_from date, _to date, _granularity text DEFAULT 'day'::text, _mode text DEFAULT 'projected'::text) RETURNS TABLE(bucket date, entradas numeric, saidas numeric, saldo numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trunc text;
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  v_trunc := CASE _granularity WHEN 'week' THEN 'week' WHEN 'month' THEN 'month' ELSE 'day' END;

  IF _mode = 'realized' THEN
    RETURN QUERY
    WITH ent AS (SELECT date_trunc(v_trunc, payment_date)::date AS b, SUM(amount_received) AS v
                 FROM receivable_payments WHERE payment_date BETWEEN _from AND _to GROUP BY 1),
         sai AS (SELECT date_trunc(v_trunc, payment_date)::date AS b, SUM(amount_paid) AS v
                 FROM payable_payments WHERE payment_date BETWEEN _from AND _to GROUP BY 1)
    SELECT COALESCE(e.b, s.b),
           COALESCE(e.v,0)::numeric,
           COALESCE(s.v,0)::numeric,
           (COALESCE(e.v,0) - COALESCE(s.v,0))::numeric
    FROM ent e FULL JOIN sai s ON s.b = e.b
    ORDER BY 1;
  ELSE
    RETURN QUERY
    WITH ent AS (SELECT date_trunc(v_trunc, due_date)::date AS b,
                        SUM(GREATEST(0,original_amount + COALESCE(interest_amount,0) + COALESCE(penalty_amount,0) - COALESCE(received_amount,0) - COALESCE(discount_amount,0))) AS v
                 FROM accounts_receivable_installments
                 WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date BETWEEN _from AND _to GROUP BY 1),
         sai AS (SELECT date_trunc(v_trunc, due_date)::date AS b,
                        SUM(GREATEST(0,original_amount + COALESCE(interest_amount,0) + COALESCE(penalty_amount,0) - COALESCE(paid_amount,0) - COALESCE(discount_amount,0))) AS v
                 FROM accounts_payable_installments
                 WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date BETWEEN _from AND _to GROUP BY 1)
    SELECT COALESCE(e.b, s.b),
           COALESCE(e.v,0)::numeric,
           COALESCE(s.v,0)::numeric,
           (COALESCE(e.v,0) - COALESCE(s.v,0))::numeric
    FROM ent e FULL JOIN sai s ON s.b = e.b
    ORDER BY 1;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_cashflow(_from date, _to date, _granularity text, _mode text) OWNER TO postgres;

--
-- Name: fn_fin_dashboard_kpis(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_dashboard_kpis(_from date, _to date) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb;
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  SELECT jsonb_build_object(
    'receitas_previstas', COALESCE((SELECT SUM(original_amount - COALESCE(received_amount,0) - COALESCE(discount_amount,0))
        FROM accounts_receivable_installments WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date BETWEEN _from AND _to),0),
    'receitas_realizadas', COALESCE((SELECT SUM(amount_received) FROM receivable_payments WHERE payment_date BETWEEN _from AND _to),0),
    'despesas_previstas', COALESCE((SELECT SUM(original_amount - COALESCE(paid_amount,0) - COALESCE(discount_amount,0))
        FROM accounts_payable_installments WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date BETWEEN _from AND _to),0),
    'despesas_realizadas', COALESCE((SELECT SUM(amount_paid) FROM payable_payments WHERE payment_date BETWEEN _from AND _to),0),
    'inadimplencia_total', COALESCE((SELECT SUM(original_amount - COALESCE(received_amount,0) - COALESCE(discount_amount,0))
        FROM accounts_receivable_installments WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date),0),
    'pagar_vencidas', COALESCE((SELECT SUM(original_amount - COALESCE(paid_amount,0) - COALESCE(discount_amount,0))
        FROM accounts_payable_installments WHERE status IN ('OPEN','PARTIAL','OVERDUE') AND due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date),0),
    'entregas_nao_faturadas_qtd', COALESCE((SELECT COUNT(*) FROM entregas WHERE financial_status='PENDING_BILLING' AND receivable_id IS NULL),0),
    'entregas_nao_faturadas_valor', COALESCE((SELECT SUM(e.quantidade_entregue * p.valor_litro_brl) FROM entregas e
        LEFT JOIN produtos p ON p.id = e.produto_id WHERE e.financial_status='PENDING_BILLING' AND e.receivable_id IS NULL),0),
    'nfe_pendente_qtd', COALESCE((SELECT COUNT(*) FROM accounts_receivable WHERE fiscal_invoice_required=true AND fiscal_invoice_status='PENDING'),0),
    'nfe_pendente_valor', COALESCE((SELECT SUM(total_amount) FROM accounts_receivable WHERE fiscal_invoice_required=true AND fiscal_invoice_status='PENDING'),0)
  ) INTO r;
  RETURN r;
END $$;


ALTER FUNCTION public.fn_fin_dashboard_kpis(_from date, _to date) OWNER TO postgres;

--
-- Name: fn_fin_dre_summary(date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_dre_summary(_from date, _to date, _regime text DEFAULT 'COMPETENCIA'::text) RETURNS TABLE(dre_group text, total numeric, qtd integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;

  IF _regime = 'CAIXA' THEN
    RETURN QUERY
    WITH receitas AS (
      SELECT COALESCE(fc.dre_group, 'NAO_CLASSIFICADO') AS g, SUM(rp.amount_received) AS v, COUNT(*) AS q
      FROM receivable_payments rp
      JOIN accounts_receivable_installments ari ON ari.id = rp.installment_id
      JOIN accounts_receivable ar ON ar.id = ari.receivable_id
      LEFT JOIN financial_categories fc ON fc.id = ar.category_id
      WHERE rp.payment_date BETWEEN _from AND _to
      GROUP BY 1
    ),
    despesas AS (
      SELECT COALESCE(fc.dre_group, 'NAO_CLASSIFICADO') AS g, SUM(pp.amount_paid) AS v, COUNT(*) AS q
      FROM payable_payments pp
      JOIN accounts_payable_installments api ON api.id = pp.installment_id
      JOIN accounts_payable ap ON ap.id = api.payable_id
      LEFT JOIN financial_categories fc ON fc.id = ap.category_id
      WHERE pp.payment_date BETWEEN _from AND _to
      GROUP BY 1
    )
    SELECT g, v::numeric, q::int FROM receitas
    UNION ALL
    SELECT g, v::numeric, q::int FROM despesas;
  ELSE
    RETURN QUERY
    WITH receitas AS (
      SELECT COALESCE(fc.dre_group, 'NAO_CLASSIFICADO') AS g, SUM(ari.original_amount) AS v, COUNT(*) AS q
      FROM accounts_receivable_installments ari
      JOIN accounts_receivable ar ON ar.id = ari.receivable_id
      LEFT JOIN financial_categories fc ON fc.id = ar.category_id
      WHERE ari.due_date BETWEEN _from AND _to AND ari.status <> 'CANCELED'
      GROUP BY 1
    ),
    despesas AS (
      SELECT COALESCE(fc.dre_group, 'NAO_CLASSIFICADO') AS g, SUM(api.original_amount) AS v, COUNT(*) AS q
      FROM accounts_payable_installments api
      JOIN accounts_payable ap ON ap.id = api.payable_id
      LEFT JOIN financial_categories fc ON fc.id = ap.category_id
      WHERE api.due_date BETWEEN _from AND _to AND api.status <> 'CANCELED'
      GROUP BY 1
    )
    SELECT g, v::numeric, q::int FROM receitas
    UNION ALL
    SELECT g, v::numeric, q::int FROM despesas;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_dre_summary(_from date, _to date, _regime text) OWNER TO postgres;

--
-- Name: fn_fin_expense_by_category(date, date, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_expense_by_category(_from date, _to date, _regime text DEFAULT 'COMPETENCIA'::text, _limit integer DEFAULT 10) RETURNS TABLE(category_id uuid, category_name text, dre_group text, total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF _regime = 'CAIXA' THEN
    RETURN QUERY
    SELECT fc.id, fc.name, fc.dre_group, SUM(pp.amount_paid)::numeric
    FROM payable_payments pp
    JOIN accounts_payable_installments api ON api.id = pp.installment_id
    JOIN accounts_payable ap ON ap.id = api.payable_id
    JOIN financial_categories fc ON fc.id = ap.category_id
    WHERE pp.payment_date BETWEEN _from AND _to
    GROUP BY fc.id, fc.name, fc.dre_group
    ORDER BY 4 DESC LIMIT _limit;
  ELSE
    RETURN QUERY
    SELECT fc.id, fc.name, fc.dre_group, SUM(api.original_amount)::numeric
    FROM accounts_payable_installments api
    JOIN accounts_payable ap ON ap.id = api.payable_id
    JOIN financial_categories fc ON fc.id = ap.category_id
    WHERE api.due_date BETWEEN _from AND _to AND api.status <> 'CANCELED'
    GROUP BY fc.id, fc.name, fc.dre_group
    ORDER BY 4 DESC LIMIT _limit;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_expense_by_category(_from date, _to date, _regime text, _limit integer) OWNER TO postgres;

--
-- Name: fn_fin_inadimplencia(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_inadimplencia() RETURNS TABLE(installment_id uuid, receivable_id uuid, customer_id uuid, customer_name text, due_date date, amount numeric, dias_atraso integer)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  RETURN QUERY
  SELECT ari.id, ar.id, ar.customer_id, c.nome, ari.due_date,
         (ari.original_amount - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0))::numeric,
         ((pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - ari.due_date)::int
  FROM accounts_receivable_installments ari
  JOIN accounts_receivable ar ON ar.id = ari.receivable_id
  JOIN clientes c ON c.id = ar.customer_id
  WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date
  ORDER BY ari.due_date ASC;
END $$;


ALTER FUNCTION public.fn_fin_inadimplencia() OWNER TO postgres;

--
-- Name: fn_fin_revenue_by_category(date, date, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_revenue_by_category(_from date, _to date, _regime text DEFAULT 'COMPETENCIA'::text, _limit integer DEFAULT 10) RETURNS TABLE(category_id uuid, category_name text, dre_group text, total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF _regime = 'CAIXA' THEN
    RETURN QUERY
    SELECT fc.id, fc.name, fc.dre_group, SUM(rp.amount_received)::numeric
    FROM receivable_payments rp
    JOIN accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
    JOIN financial_categories fc ON fc.id = ar.category_id
    WHERE rp.payment_date BETWEEN _from AND _to
    GROUP BY fc.id, fc.name, fc.dre_group
    ORDER BY 4 DESC LIMIT _limit;
  ELSE
    RETURN QUERY
    SELECT fc.id, fc.name, fc.dre_group, SUM(ari.original_amount)::numeric
    FROM accounts_receivable_installments ari
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
    JOIN financial_categories fc ON fc.id = ar.category_id
    WHERE ari.due_date BETWEEN _from AND _to AND ari.status <> 'CANCELED'
    GROUP BY fc.id, fc.name, fc.dre_group
    ORDER BY 4 DESC LIMIT _limit;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_revenue_by_category(_from date, _to date, _regime text, _limit integer) OWNER TO postgres;

--
-- Name: fn_fin_revenue_by_customer(date, date, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fin_revenue_by_customer(_from date, _to date, _regime text DEFAULT 'COMPETENCIA'::text, _limit integer DEFAULT 10) RETURNS TABLE(customer_id uuid, customer_name text, total numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF _regime = 'CAIXA' THEN
    RETURN QUERY
    SELECT ar.customer_id, c.nome, SUM(rp.amount_received)::numeric
    FROM receivable_payments rp
    JOIN accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
    JOIN clientes c ON c.id = ar.customer_id
    WHERE rp.payment_date BETWEEN _from AND _to
    GROUP BY ar.customer_id, c.nome
    ORDER BY 3 DESC LIMIT _limit;
  ELSE
    RETURN QUERY
    SELECT ar.customer_id, c.nome, SUM(ari.original_amount)::numeric
    FROM accounts_receivable_installments ari
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
    JOIN clientes c ON c.id = ar.customer_id
    WHERE ari.due_date BETWEEN _from AND _to AND ari.status <> 'CANCELED'
    GROUP BY ar.customer_id, c.nome
    ORDER BY 3 DESC LIMIT _limit;
  END IF;
END $$;


ALTER FUNCTION public.fn_fin_revenue_by_customer(_from date, _to date, _regime text, _limit integer) OWNER TO postgres;

--
-- Name: fn_financial_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_financial_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old jsonb; v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN v_old := to_jsonb(OLD); v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'DELETE' THEN v_old := to_jsonb(OLD);
  END IF;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES (TG_TABLE_NAME, COALESCE((NEW).id, (OLD).id), TG_OP, v_old, v_new, auth.uid());

  RETURN COALESCE(NEW, OLD);
END $$;


ALTER FUNCTION public.fn_financial_audit() OWNER TO postgres;

--
-- Name: fn_financial_inconsistencies(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_financial_inconsistencies() RETURNS TABLE(code text, severity text, entity_type text, entity_id uuid, description text, recommended_action text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.h15_require_staff();

  IF NOT public.is_financial_staff(auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado' USING ERRCODE='insufficient_privilege';
  END IF;

  RETURN QUERY
  -- 1. Entrega BILLED sem receivable_id
  SELECT 'DELIVERY_BILLED_NO_AR'::text, 'alta'::text, 'entregas'::text, e.id,
         'Entrega marcada como faturada sem título financeiro vinculado.'::text,
         'Reprocessar faturamento ou reverter status para PENDING_BILLING.'::text
    FROM public.entregas e
   WHERE e.financial_status = 'BILLED' AND e.receivable_id IS NULL

  UNION ALL
  -- 2. Entrega NOT_BILLABLE com receivable_id
  SELECT 'DELIVERY_NOT_BILLABLE_WITH_AR', 'alta', 'entregas', e.id,
         'Entrega marcada como sem cobrança porém possui título financeiro.',
         'Revisar status financeiro da entrega ou cancelar o título.'
    FROM public.entregas e
   WHERE e.financial_status = 'NOT_BILLABLE' AND e.receivable_id IS NOT NULL

  UNION ALL
  -- 3. Entrega com receivable_id apontando para AR inexistente
  SELECT 'DELIVERY_AR_BROKEN_FK', 'critica', 'entregas', e.id,
         'Entrega referencia um título que não existe mais.',
         'Limpar receivable_id ou recriar o título via faturamento.'
    FROM public.entregas e
    LEFT JOIN public.accounts_receivable ar ON ar.id = e.receivable_id
   WHERE e.receivable_id IS NOT NULL AND ar.id IS NULL

  UNION ALL
  -- 4. AR sem parcelas
  SELECT 'AR_NO_INSTALLMENTS', 'alta', 'accounts_receivable', ar.id,
         'Conta a receber sem parcelas geradas.',
         'Gerar parcelas manualmente ou cancelar o título.'
    FROM public.accounts_receivable ar
    LEFT JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.status <> 'CANCELED'
   GROUP BY ar.id
  HAVING count(ari.id) = 0

  UNION ALL
  -- 5. AP sem parcelas
  SELECT 'AP_NO_INSTALLMENTS', 'alta', 'accounts_payable', ap.id,
         'Conta a pagar sem parcelas geradas.',
         'Gerar parcelas manualmente ou cancelar o título.'
    FROM public.accounts_payable ap
    LEFT JOIN public.accounts_payable_installments api ON api.payable_id = ap.id
   WHERE ap.status <> 'CANCELED'
   GROUP BY ap.id
  HAVING count(api.id) = 0

  UNION ALL
  -- 6. AR PAID com parcela ainda em aberto
  SELECT 'AR_PAID_OPEN_INSTALLMENT', 'critica', 'accounts_receivable', ar.id,
         'Título marcado como PAGO mas possui parcela em aberto/parcial/vencida.',
         'Reprocessar status do título.'
    FROM public.accounts_receivable ar
   WHERE ar.status = 'PAID'
     AND EXISTS (
       SELECT 1 FROM public.accounts_receivable_installments ari
        WHERE ari.receivable_id = ar.id AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
     )

  UNION ALL
  -- 7. AP PAID com parcela ainda em aberto
  SELECT 'AP_PAID_OPEN_INSTALLMENT', 'critica', 'accounts_payable', ap.id,
         'Título marcado como PAGO mas possui parcela em aberto/parcial/vencida.',
         'Reprocessar status do título.'
    FROM public.accounts_payable ap
   WHERE ap.status = 'PAID'
     AND EXISTS (
       SELECT 1 FROM public.accounts_payable_installments api
        WHERE api.payable_id = ap.id AND api.status IN ('OPEN','PARTIAL','OVERDUE')
     )

  UNION ALL
  -- 8. Conta CANCELED com pagamento ativo (não estorno)
  SELECT 'AR_CANCELED_WITH_PAYMENT', 'alta', 'accounts_receivable', ar.id,
         'Título cancelado possui baixas ativas não estornadas.',
         'Estornar pagamentos antes de manter o cancelamento.'
    FROM public.accounts_receivable ar
   WHERE ar.status = 'CANCELED'
     AND EXISTS (
       SELECT 1 FROM public.accounts_receivable_installments ari
        JOIN public.receivable_payments rp ON rp.installment_id = ari.id
       WHERE ari.receivable_id = ar.id AND COALESCE(rp.is_reversal,false) = false
         AND NOT EXISTS (SELECT 1 FROM public.receivable_payments rp2 WHERE rp2.reversed_payment_id = rp.id)
     )

  UNION ALL
  -- 9. Recibo emitido para pagamento de estorno
  SELECT 'RECEIPT_FOR_REVERSAL', 'alta', 'financial_receipts', fr.id,
         'Recibo emitido sobre um lançamento de estorno.',
         'Cancelar o recibo.'
    FROM public.financial_receipts fr
    JOIN public.receivable_payments rp ON rp.id = fr.payment_id
   WHERE fr.status = 'ISSUED' AND rp.is_reversal = true

  UNION ALL
  -- 10. Recibo emitido para pagamento inexistente
  SELECT 'RECEIPT_PAYMENT_BROKEN_FK', 'critica', 'financial_receipts', fr.id,
         'Recibo aponta para pagamento inexistente.',
         'Cancelar o recibo ou restaurar o pagamento.'
    FROM public.financial_receipts fr
    LEFT JOIN public.receivable_payments rp ON rp.id = fr.payment_id
   WHERE fr.status = 'ISSUED' AND fr.payment_id IS NOT NULL AND rp.id IS NULL

  UNION ALL
  -- 11. NF vinculada a AR inexistente
  SELECT 'FISCAL_INVOICE_AR_BROKEN_FK', 'critica', 'fiscal_invoices', fi.id,
         'Nota fiscal vinculada a um título que não existe.',
         'Religar a NF a um título válido ou cancelá-la.'
    FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
    LEFT JOIN public.accounts_receivable ar ON ar.id = fi.receivable_id
   WHERE fi.receivable_id IS NOT NULL AND ar.id IS NULL

  UNION ALL
  -- 12. Documento financeiro órfão (owner_id sem registro)
  SELECT 'FINANCIAL_DOC_ORPHAN', 'media', 'financial_documents', fd.id,
         'Documento financeiro vinculado a um registro inexistente ('||fd.owner_type||').',
         'Excluir logicamente ou religar a entidade correta.'
    FROM public.financial_documents fd
   WHERE fd.deleted_at IS NULL
     AND (
       (fd.owner_type = 'RECEIVABLE' AND NOT EXISTS (SELECT 1 FROM public.accounts_receivable WHERE id = fd.owner_id))
       OR (fd.owner_type = 'PAYABLE' AND NOT EXISTS (SELECT 1 FROM public.accounts_payable WHERE id = fd.owner_id))
       OR (fd.owner_type = 'FISCAL_INVOICE' AND public.h15_invoice_access(fd.owner_id) AND NOT EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = fd.owner_id))
       OR (fd.owner_type IN ('PAYMENT_RECEIVABLE') AND NOT EXISTS (SELECT 1 FROM public.receivable_payments WHERE id = fd.owner_id))
       OR (fd.owner_type IN ('PAYMENT_PAYABLE') AND NOT EXISTS (SELECT 1 FROM public.payable_payments WHERE id = fd.owner_id))
       OR (fd.owner_type = 'FINANCIAL_RECEIPT' AND NOT EXISTS (SELECT 1 FROM public.financial_receipts WHERE id = fd.owner_id))
     )

  UNION ALL
  -- 13. Entrega faturada duplicada (mesma entrega com >1 AR)
  SELECT 'DELIVERY_DUPLICATED_AR', 'critica', 'accounts_receivable', ar.id,
         'Mais de um título financeiro foi gerado para a mesma entrega.',
         'Cancelar os títulos extras.'
    FROM public.accounts_receivable ar
   WHERE ar.origin_type = 'DELIVERY'
     AND ar.origin_id IN (
       SELECT origin_id FROM public.accounts_receivable
        WHERE origin_type = 'DELIVERY' AND origin_id IS NOT NULL AND status <> 'CANCELED'
        GROUP BY origin_id HAVING count(*) > 1
     )

  ORDER BY 2, 1, 4;
END $$;


ALTER FUNCTION public.fn_financial_inconsistencies() OWNER TO postgres;

--
-- Name: fn_fiscal_access_key_dv(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_access_key_dv(_key43 text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  d text := public.fn_fiscal_digits(_key43);
  s int := 0; i int; w int := 2; r int;
BEGIN
  IF length(d) <> 43 THEN
    RAISE EXCEPTION 'FISCAL_ACCESS_KEY_LENGTH: esperado 43 digitos antes do DV, recebido %', length(d);
  END IF;
  FOR i IN REVERSE 43..1 LOOP
    s := s + substr(d,i,1)::int * w;
    w := CASE WHEN w = 9 THEN 2 ELSE w + 1 END;
  END LOOP;
  r := 11 - (s % 11);
  RETURN CASE WHEN r >= 10 THEN 0 ELSE r END;
END $$;


ALTER FUNCTION public.fn_fiscal_access_key_dv(_key43 text) OWNER TO postgres;

--
-- Name: fn_fiscal_base_components_valid(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_base_components_valid(_c jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_typeof(_c) = 'array'
     AND NOT EXISTS (
       SELECT 1 FROM jsonb_array_elements_text(_c) x
        WHERE x NOT IN ('PRODUTO','FRETE','SEGURO','OUTRAS_DESPESAS','DESCONTO','IPI','ICMS_ST'));
$$;


ALTER FUNCTION public.fn_fiscal_base_components_valid(_c jsonb) OWNER TO postgres;

--
-- Name: fn_fiscal_uf_ibge_code(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_uf_ibge_code(_uf text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE upper(btrim(coalesce(_uf,'')))
    WHEN 'RO' THEN '11' WHEN 'AC' THEN '12' WHEN 'AM' THEN '13' WHEN 'RR' THEN '14'
    WHEN 'PA' THEN '15' WHEN 'AP' THEN '16' WHEN 'TO' THEN '17' WHEN 'MA' THEN '21'
    WHEN 'PI' THEN '22' WHEN 'CE' THEN '23' WHEN 'RN' THEN '24' WHEN 'PB' THEN '25'
    WHEN 'PE' THEN '26' WHEN 'AL' THEN '27' WHEN 'SE' THEN '28' WHEN 'BA' THEN '29'
    WHEN 'MG' THEN '31' WHEN 'ES' THEN '32' WHEN 'RJ' THEN '33' WHEN 'SP' THEN '35'
    WHEN 'PR' THEN '41' WHEN 'SC' THEN '42' WHEN 'RS' THEN '43' WHEN 'MS' THEN '50'
    WHEN 'MT' THEN '51' WHEN 'GO' THEN '52' WHEN 'DF' THEN '53'
    ELSE NULL END;
$$;


ALTER FUNCTION public.fn_fiscal_uf_ibge_code(_uf text) OWNER TO postgres;

--
-- Name: fiscal_tax_rules; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fiscal_tax_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    rule_key text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    tax_kind text NOT NULL,
    calc_mode text DEFAULT 'PERCENT'::text NOT NULL,
    crt text,
    origin_uf text,
    destination_uf text,
    ncm_prefix text,
    product_category text,
    final_consumer boolean,
    taxpayer_indicator text,
    cst text,
    csosn text,
    rate numeric(9,4),
    base_reduction_pct numeric(9,4),
    deferral_pct numeric(9,4),
    mva_pct numeric(9,4),
    fcp_rate numeric(9,4),
    difal_dest_share_pct numeric(9,4),
    legal_basis text,
    legal_version text,
    source_id uuid,
    justification text,
    priority integer DEFAULT 100 NOT NULL,
    valid_from date DEFAULT CURRENT_DATE NOT NULL,
    valid_until date,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    prepared_by uuid,
    published_by uuid,
    published_at timestamp with time zone,
    superseded_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    st_modality text,
    internal_rate_pct numeric,
    interstate_rate_pct numeric,
    fcp_st_rate numeric,
    credit_own_icms boolean DEFAULT true NOT NULL,
    base_components jsonb DEFAULT '[]'::jsonb NOT NULL,
    base_reduction_mode text DEFAULT 'NONE'::text NOT NULL,
    CONSTRAINT ftr_base_components_chk CHECK (public.fn_fiscal_base_components_valid(base_components)),
    CONSTRAINT ftr_base_reduction_mode_coherent CHECK ((((base_reduction_mode = 'NONE'::text) AND (COALESCE(base_reduction_pct, (0)::numeric) = (0)::numeric)) OR ((base_reduction_mode = 'FIXED'::text) AND (base_reduction_pct IS NOT NULL) AND (base_reduction_pct > (0)::numeric)) OR ((base_reduction_mode = 'MANUAL'::text) AND (base_reduction_pct IS NULL)))),
    CONSTRAINT ftr_base_reduction_mode_domain CHECK ((base_reduction_mode = ANY (ARRAY['NONE'::text, 'FIXED'::text, 'MANUAL'::text]))),
    CONSTRAINT ftr_calc_mode_domain CHECK ((calc_mode = ANY (ARRAY['PERCENT'::text, 'EXEMPT_DOCUMENTED'::text, 'NOT_TAXED_DOCUMENTED'::text, 'SUSPENDED_DOCUMENTED'::text, 'DEFERRED_DOCUMENTED'::text]))),
    CONSTRAINT ftr_crt_cst_csosn_chk CHECK (((tax_kind <> ALL (ARRAY['ICMS'::text, 'ICMS_ST'::text])) OR (crt IS NULL) OR ((crt = ANY (ARRAY['1'::text, '2'::text])) AND (csosn IS NOT NULL) AND (cst IS NULL)) OR ((crt = ANY (ARRAY['3'::text, '4'::text])) AND (cst IS NOT NULL) AND (csosn IS NULL)))),
    CONSTRAINT ftr_crt_domain CHECK (((crt IS NULL) OR (crt = ANY (ARRAY['1'::text, '2'::text, '3'::text, '4'::text])))),
    CONSTRAINT ftr_cst_csosn_exclusive CHECK (((cst IS NULL) OR (csosn IS NULL))),
    CONSTRAINT ftr_non_icms_csosn_chk CHECK (((tax_kind <> ALL (ARRAY['PIS'::text, 'COFINS'::text, 'IPI'::text, 'FCP'::text, 'FCP_ST'::text, 'DIFAL'::text])) OR (csosn IS NULL))),
    CONSTRAINT ftr_pct_ranges CHECK ((((base_reduction_pct IS NULL) OR ((base_reduction_pct >= (0)::numeric) AND (base_reduction_pct <= (100)::numeric))) AND ((deferral_pct IS NULL) OR ((deferral_pct >= (0)::numeric) AND (deferral_pct <= (100)::numeric))) AND ((mva_pct IS NULL) OR (mva_pct >= (0)::numeric)) AND ((fcp_rate IS NULL) OR ((fcp_rate >= (0)::numeric) AND (fcp_rate <= (100)::numeric))) AND ((difal_dest_share_pct IS NULL) OR ((difal_dest_share_pct >= (0)::numeric) AND (difal_dest_share_pct <= (100)::numeric))))),
    CONSTRAINT ftr_published_requires_evidence CHECK (((status <> 'PUBLISHED'::text) OR ((source_id IS NOT NULL) AND (NULLIF(btrim(COALESCE(legal_basis, ''::text)), ''::text) IS NOT NULL) AND (published_at IS NOT NULL) AND (published_by IS NOT NULL) AND ((cst IS NOT NULL) OR (csosn IS NOT NULL) OR (tax_kind = ANY (ARRAY['IBS'::text, 'CBS'::text, 'IS'::text]))) AND ((calc_mode <> 'PERCENT'::text) OR (rate IS NOT NULL)) AND ((calc_mode = 'PERCENT'::text) OR (length(btrim(COALESCE(justification, ''::text))) >= 20))))),
    CONSTRAINT ftr_rate_range CHECK (((rate IS NULL) OR ((rate >= (0)::numeric) AND (rate <= (100)::numeric)))),
    CONSTRAINT ftr_rtc_not_publishable_chk CHECK (((tax_kind <> ALL (ARRAY['IBS'::text, 'CBS'::text, 'IS'::text])) OR (status <> 'PUBLISHED'::text))),
    CONSTRAINT ftr_st_modality_chk CHECK (((st_modality IS NULL) OR (st_modality = ANY (ARRAY['MVA'::text, 'PAUTA'::text, 'PRECO_TABELADO'::text, 'VALOR_OPERACAO'::text])))),
    CONSTRAINT ftr_status_domain CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'SUPERSEDED'::text]))),
    CONSTRAINT ftr_tax_kind_domain CHECK ((tax_kind = ANY (ARRAY['ICMS'::text, 'ICMS_ST'::text, 'FCP'::text, 'FCP_ST'::text, 'DIFAL'::text, 'PIS'::text, 'COFINS'::text, 'IPI'::text, 'IBS'::text, 'CBS'::text, 'IS'::text]))),
    CONSTRAINT ftr_ufs_domain CHECK ((((origin_uf IS NULL) OR (public.fn_fiscal_uf_ibge_code(origin_uf) IS NOT NULL)) AND ((destination_uf IS NULL) OR (destination_uf = 'EX'::text) OR (public.fn_fiscal_uf_ibge_code(destination_uf) IS NOT NULL)))),
    CONSTRAINT ftr_validity CHECK (((valid_until IS NULL) OR (valid_until >= valid_from)))
);


