    CONSTRAINT cfs_nfe_readiness_domain CHECK ((nfe_readiness_status = ANY (ARRAY['NOT_READY'::text, 'PARTIAL'::text, 'READY_HOMOLOGATION'::text, 'READY_PRODUCTION'::text, 'BLOCKED'::text]))),
    CONSTRAINT cfs_nfe_readiness_pendencies_shape CHECK ((jsonb_typeof(nfe_readiness_pendencies) = 'array'::text)),
    CONSTRAINT cfs_nfe_series_number_range CHECK (((nfe_series_number IS NULL) OR ((nfe_series_number >= 1) AND (nfe_series_number <= 999)))),
    CONSTRAINT cfs_nfse_configuration_is_object CHECK ((jsonb_typeof(nfse_configuration) = 'object'::text)),
    CONSTRAINT cfs_nfse_provider_domain CHECK ((nfse_provider = ANY (ARRAY['NONE'::text, 'NOT_CONFIGURED'::text, 'FOCUS_NFE'::text, 'PLUGNOTAS'::text, 'SEFAZ_DIRETO'::text, 'NFSE_NACIONAL'::text, 'MUNICIPAL'::text, 'OTHER_FUTURE'::text]))),
    CONSTRAINT cfs_no_sensitive_keys_in_jsonb CHECK (((NOT public.fiscal_json_has_sensitive_key(nfe_configuration)) AND (NOT public.fiscal_json_has_sensitive_key(nfse_configuration)) AND (NOT public.fiscal_json_has_sensitive_key(last_validation_summary)))),
    CONSTRAINT cfs_pis_cofins_regime_domain CHECK (((pis_cofins_regime IS NULL) OR (pis_cofins_regime = ANY (ARRAY['CUMULATIVO'::text, 'NAO_CUMULATIVO'::text, 'MISTO'::text, 'SIMPLES_NACIONAL'::text])))),
    CONSTRAINT cfs_refs_shape CHECK ((((nfe_credential_ref IS NULL) OR ((length(nfe_credential_ref) >= 1) AND (length(nfe_credential_ref) <= 120) AND (nfe_credential_ref ~ '^[A-Za-z0-9_.:\-]+$'::text))) AND ((nfse_credential_ref IS NULL) OR ((length(nfse_credential_ref) >= 1) AND (length(nfse_credential_ref) <= 120) AND (nfse_credential_ref ~ '^[A-Za-z0-9_.:\-]+$'::text))) AND ((certificate_ref IS NULL) OR ((length(certificate_ref) >= 1) AND (length(certificate_ref) <= 120) AND (certificate_ref ~ '^[A-Za-z0-9_.:\-]+$'::text))) AND ((webhook_ref IS NULL) OR ((length(webhook_ref) >= 1) AND (length(webhook_ref) <= 120) AND (webhook_ref ~ '^[A-Za-z0-9_.:\-]+$'::text))))),
    CONSTRAINT cfs_uf_accreditations_shape CHECK (((jsonb_typeof(uf_accreditations) = 'array'::text) AND (NOT public.fiscal_json_has_sensitive_key(jsonb_build_object('v', uf_accreditations))))),
    CONSTRAINT company_fiscal_settings_configuration_status_check CHECK ((configuration_status = ANY (ARRAY['DRAFT'::text, 'PENDING_ACCOUNTING'::text, 'VALIDATED'::text, 'BLOCKED'::text]))),
    CONSTRAINT company_fiscal_settings_fiscal_environment_check CHECK ((fiscal_environment = ANY (ARRAY['NOT_CONFIGURED'::text, 'HOMOLOGATION'::text, 'PRODUCTION'::text]))),
    CONSTRAINT company_fiscal_settings_fiscal_provider_check CHECK ((fiscal_provider = ANY (ARRAY['NONE'::text, 'NOT_CONFIGURED'::text, 'FOCUS_NFE'::text, 'SEFAZ_DIRETO'::text, 'NFSE_NACIONAL'::text, 'MUNICIPAL'::text]))),
    CONSTRAINT company_fiscal_settings_rtc_config_no_secret_chk CHECK ((NOT public.fiscal_rtc_has_sensitive_key(rtc_configuration))),
    CONSTRAINT company_fiscal_settings_rtc_config_object_chk CHECK ((jsonb_typeof(rtc_configuration) = 'object'::text))
);


