--
-- Name: fn_fiscal_compute_item_taxes_v1(public.company_fiscal_settings, public.customer_fiscal_profiles, text, text, date, text, numeric, numeric, numeric, numeric, numeric, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_compute_item_taxes_v1(p_emit public.company_fiscal_settings, p_dest public.customer_fiscal_profiles, p_direction text, p_sales_channel text, p_ref_date date, p_ncm text, p_prod numeric, p_desconto numeric, p_frete numeric, p_seguro numeric, p_outras numeric, p_inputs jsonb, p_manual_by uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  pol public.fiscal_operation_policies%ROWTYPE;
  rule public.fiscal_tax_rules%ROWTYPE;
  kinds text[]; k text; ctx jsonb; res jsonb; item_taxes jsonb := '{}'::jsonb;
  v_prod numeric := public.fn_fiscal_round(coalesce(p_prod,0));
  v_icms_own numeric := 0; v_ipi numeric := 0; v_base_st numeric := NULL; v_st_val numeric := 0;
  v_fcp_own numeric := 0; v_fcp_st numeric := 0;
  v_difal_dest numeric := 0; v_difal_orig numeric := 0; v_fcp_dest numeric := 0;
  has_difal boolean := false;
BEGIN
  pol := public.fn_fiscal_resolve_operation(
    coalesce(p_direction,'OUT'), p_emit.state, coalesce(p_dest.fiscal_state, p_emit.state), p_emit.crt,
    p_dest.final_consumer, p_dest.taxpayer_indicator, p_ncm, null, p_sales_channel, p_ref_date);

  kinds := ARRAY['ICMS']::text[];
  IF coalesce(p_emit.ipi_taxpayer,false) THEN kinds := array_append(kinds,'IPI'); END IF;
  IF coalesce(p_emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'ICMS_ST'); END IF;
  IF coalesce(p_emit.fcp_applicable,false) THEN
    kinds := array_append(kinds,'FCP');
    IF coalesce(p_emit.icms_st_responsible,false) THEN kinds := array_append(kinds,'FCP_ST'); END IF;
  END IF;
  IF coalesce(p_emit.difal_responsible,false)
     AND upper(coalesce(p_dest.fiscal_state,'')) <> upper(coalesce(p_emit.state,''))
     AND coalesce(p_dest.final_consumer,true) THEN
    kinds := array_append(kinds,'DIFAL');
  END IF;
  kinds := kinds || ARRAY['PIS','COFINS']::text[];

  FOREACH k IN ARRAY kinds LOOP
    ctx := jsonb_build_object(
      'produto', v_prod,
      'frete',    public.fn_fiscal_round(coalesce(p_frete,0)),
      'seguro',   public.fn_fiscal_round(coalesce(p_seguro,0)),
      'outras',   public.fn_fiscal_round(coalesce(p_outras,0)),
      'desconto', public.fn_fiscal_round(coalesce(p_desconto,0)),
      'ipi', v_ipi, 'icmsSt', v_st_val, 'icmsOwnValue', v_icms_own, 'baseST', v_base_st);

    rule := public.fn_fiscal_resolve_tax_rule(k, p_emit.crt, p_emit.state,
      coalesce(p_dest.fiscal_state, p_emit.state), p_ncm, null,
      p_dest.final_consumer, p_dest.taxpayer_indicator, p_ref_date);

    IF coalesce(rule.base_reduction_mode,'NONE') = 'MANUAL' THEN
      ctx := ctx || jsonb_build_object(
        'manualBaseReductionPct', coalesce(p_inputs,'{}'::jsonb)->k->>'baseReductionPct',
        'manualReason',           coalesce(p_inputs,'{}'::jsonb)->k->>'baseReductionReason',
        'manualBy', p_manual_by::text,
        'manualAt', to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SSZ'));
    END IF;

    res := public.fn_fiscal_apply_tax_v2(rule, ctx);
    item_taxes := item_taxes || jsonb_build_object(k, res || jsonb_build_object('contextIn', ctx));

    IF k = 'ICMS'    THEN v_icms_own := (res->>'value')::numeric; END IF;
    IF k = 'IPI'     THEN v_ipi := (res->>'value')::numeric; END IF;
    IF k = 'ICMS_ST' THEN
      v_st_val  := (res->>'value')::numeric;
      v_base_st := (res->'params'->>'baseST')::numeric;
    END IF;
    IF k = 'FCP'     THEN v_fcp_own := (res->>'value')::numeric; END IF;
    IF k = 'FCP_ST'  THEN v_fcp_st := (res->>'value')::numeric; END IF;
    IF k = 'DIFAL'   THEN
      has_difal := true;
      v_difal_dest := coalesce((res->'params'->>'valueDestination')::numeric,0);
      v_difal_orig := coalesce((res->'params'->>'valueOrigin')::numeric,0);
      v_fcp_dest   := coalesce((res->'params'->>'fcpValue')::numeric,0);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'taxOrder', to_jsonb(kinds),
    'hasDifal', has_difal,
    'policy', jsonb_build_object(
      'id', pol.id, 'cfop', pol.cfop, 'natureOperation', pol.nature_operation,
      'legalVersion', pol.legal_version, 'legalBasis', pol.legal_basis, 'sourceId', pol.source_id),
    'chained', jsonb_build_object(
      'icmsOwnValue', v_icms_own, 'ipi', v_ipi, 'icmsSt', v_st_val, 'baseST', v_base_st),
    'itemTotals', jsonb_build_object(
      'vFCP', v_fcp_own, 'vFCPST', v_fcp_st,
      'vICMSUFDest', v_difal_dest, 'vICMSUFRemet', v_difal_orig, 'vFCPUFDest', v_fcp_dest),
    'taxes', item_taxes);
END $$;


ALTER FUNCTION public.fn_fiscal_compute_item_taxes_v1(p_emit public.company_fiscal_settings, p_dest public.customer_fiscal_profiles, p_direction text, p_sales_channel text, p_ref_date date, p_ncm text, p_prod numeric, p_desconto numeric, p_frete numeric, p_seguro numeric, p_outras numeric, p_inputs jsonb, p_manual_by uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_cpf_is_valid(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_cpf_is_valid(_v text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  d text := public.fn_fiscal_digits(_v);
  s int := 0; i int; dv1 int; dv2 int;
BEGIN
  IF length(d) <> 11 THEN RETURN false; END IF;
  IF d ~ ('^(' || substr(d,1,1) || '){11}$') THEN RETURN false; END IF;
  FOR i IN 1..9 LOOP s := s + substr(d,i,1)::int * (11 - i); END LOOP;
  dv1 := (s * 10) % 11; IF dv1 = 10 THEN dv1 := 0; END IF;
  IF dv1 <> substr(d,10,1)::int THEN RETURN false; END IF;
  s := 0;
  FOR i IN 1..10 LOOP s := s + substr(d,i,1)::int * (12 - i); END LOOP;
  dv2 := (s * 10) % 11; IF dv2 = 10 THEN dv2 := 0; END IF;
  RETURN dv2 = substr(d,11,1)::int;
END $_$;


ALTER FUNCTION public.fn_fiscal_cpf_is_valid(_v text) OWNER TO postgres;

--
-- Name: fn_fiscal_digits(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_digits(_v text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT regexp_replace(coalesce(_v,''), '[^0-9]', '', 'g');
$$;


ALTER FUNCTION public.fn_fiscal_digits(_v text) OWNER TO postgres;

--
-- Name: fn_fiscal_emitter_pendencies(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_emitter_pendencies(_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE r public.company_fiscal_settings%ROWTYPE;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_company(_id);

  SELECT * INTO r FROM (SELECT * FROM public.company_fiscal_settings WHERE organization_id = public.h15_actor_organization()) company_fiscal_settings WHERE id = _id;
  IF NOT FOUND THEN
    RETURN jsonb_build_array(jsonb_build_object('code','EMITTER_NOT_FOUND','field','id','severity','BLOCK'));
  END IF;
  RETURN public.fn_fiscal_emitter_pendencies_row(r);
END $$;


ALTER FUNCTION public.fn_fiscal_emitter_pendencies(_id uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_emitter_pendencies_row(public.company_fiscal_settings); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_emitter_pendencies_row(r public.company_fiscal_settings) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE out jsonb := '[]'::jsonb; ie_state text;
BEGIN
  IF current_setting('role', true) = 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.organizations o
      WHERE o.id = r.organization_id AND o.ativo IS TRUE
    ) THEN
      RAISE EXCEPTION 'H15_ORGANIZATION_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  ELSE
    PERFORM public.h15_require_staff();
    IF r.organization_id IS DISTINCT FROM public.h15_actor_organization() THEN
      RAISE EXCEPTION 'H15_COMPANY_FORBIDDEN' USING ERRCODE='42501';
    END IF;
  END IF;

  IF NOT public.fn_fiscal_cnpj_is_valid(r.cnpj) THEN
    out := out || jsonb_build_object('code','EMITTER_CNPJ_INVALID','field','cnpj','severity','BLOCK','message','CNPJ ausente ou com digito verificador invalido.');
  END IF;
  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_LEGAL_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social obrigatoria.');
  END IF;
  IF r.crt IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CRT_MISSING','field','crt','severity','BLOCK','message','CRT (1,2,3,4) obrigatorio.');
  END IF;
  IF nullif(btrim(coalesce(r.primary_cnae,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_CNAE_MISSING','field','primary_cnae','severity','BLOCK','message','CNAE principal obrigatorio.');
  END IF;
  IF r.pis_cofins_regime IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_PIS_COFINS_REGIME_MISSING','field','pis_cofins_regime','severity','BLOCK','message','Regime de PIS/COFINS obrigatorio para calculo.');
  END IF;
  IF NOT public.fn_fiscal_cep_is_valid(r.postal_code) THEN
    out := out || jsonb_build_object('code','EMITTER_CEP_INVALID','field','postal_code','severity','BLOCK','message','CEP deve ter 8 digitos.');
  END IF;
  IF public.fn_fiscal_uf_ibge_code(r.state) IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_UF_INVALID','field','state','severity','BLOCK','message','UF invalida.');
  ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.municipality_ibge_code, r.state) THEN
    out := out || jsonb_build_object('code','EMITTER_IBGE_INCOHERENT','field','municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
  END IF;
  IF nullif(btrim(coalesce(r.street,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.number,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.neighborhood,'')),'') IS NULL
     OR nullif(btrim(coalesce(r.city,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco completo obrigatorio (logradouro, numero, bairro, municipio).');
  END IF;
  IF coalesce(r.country_code,'') NOT IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','EMITTER_COUNTRY_MISSING','field','country_code','severity','BLOCK','message','Pais obrigatorio (1058 - Brasil).');
  END IF;
  ie_state := public.fn_fiscal_ie_check(r.state, r.state_registration);
  IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF') THEN
    out := out || jsonb_build_object('code','EMITTER_IE_INVALID','field','state_registration','severity','BLOCK','message','Inscricao estadual invalida para a UF: '||ie_state);
  ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
    out := out || jsonb_build_object('code','EMITTER_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; digito verificador desta UF nao e verificado automaticamente.');
  END IF;
  IF r.nfe_series_number IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_SERIES_MISSING','field','nfe_series_number','severity','BLOCK','message','Serie da NF-e (1-999) obrigatoria.');
  END IF;
  IF r.nfe_environment_code IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ENVIRONMENT_MISSING','field','nfe_environment_code','severity','BLOCK','message','Ambiente tpAmb (2 homologacao / 1 producao) obrigatorio.');
  END IF;
  IF jsonb_array_length(r.uf_accreditations) = 0 THEN
    out := out || jsonb_build_object('code','EMITTER_ACCREDITATION_MISSING','field','uf_accreditations','severity','BLOCK','message','Credenciamento por UF nao registrado.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.fiscal_certificates c
    WHERE c.id::text = r.certificate_ref AND c.company_settings_id = r.id
      AND c.environment = 'HOMOLOGATION' AND c.status = 'AVAILABLE'
      AND c.is_active IS TRUE AND c.revoked_at IS NULL
      AND c.valid_from <= now() AND c.valid_until > now()) THEN
    out := out || jsonb_build_object('code','EMITTER_CERTIFICATE_MISSING','field','certificate_ref','severity','BLOCK','message','Certificado ausente, indisponivel, revogado, vencido ou de outra empresa.');
  END IF;
  IF r.accounting_validated_at IS NULL THEN
    out := out || jsonb_build_object('code','EMITTER_ACCOUNTING_NOT_VALIDATED','field','accounting_validated_at','severity','BLOCK','message','Validacao contabil pendente.');
  END IF;
  IF coalesce(r.nfe_environment_code,'2') = '1' THEN
    out := out || jsonb_build_object('code','EMITTER_PRODUCTION_BLOCKED_F3','field','nfe_environment_code','severity','BLOCK',
      'message','Ambiente de producao (tpAmb=1) bloqueado na fase F3: teto e READY_HOMOLOGATION ate fluxo controlado de homologacao SEFAZ.');
  END IF;
  RETURN out;
END $$;


ALTER FUNCTION public.fn_fiscal_emitter_pendencies_row(r public.company_fiscal_settings) OWNER TO postgres;

--
-- Name: fn_fiscal_emitter_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_emitter_status(_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH p AS (SELECT public.fn_fiscal_emitter_pendencies(_id) AS j)
  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM p, jsonb_array_elements(p.j) e WHERE e->>'severity' = 'BLOCK') THEN 'NOT_READY'
    WHEN EXISTS (SELECT 1 FROM p, jsonb_array_elements(p.j) e) THEN 'PARTIAL'
    ELSE 'READY_HOMOLOGATION' END
  FROM p;
$$;


ALTER FUNCTION public.fn_fiscal_emitter_status(_id uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_environment_gate_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_environment_gate_v1(p_operation text DEFAULT 'GENERIC'::text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
  v_env   text;
BEGIN
  IF current_setting('role',true) = 'service_role' THEN IF (SELECT count(*) FROM public.company_fiscal_settings WHERE is_active) <> 1 THEN RAISE EXCEPTION 'H15_SERVICE_EMITTER_AMBIGUOUS' USING ERRCODE='42501'; END IF; ELSE PERFORM public.h15_require_staff(); END IF;

  PERFORM public.fn_fiscal_assert_staging_marker(p_operation);

  SELECT count(*) INTO v_count FROM (SELECT * FROM public.company_fiscal_settings WHERE (organization_id = public.h15_actor_organization() OR current_setting('role',true) = 'service_role')) company_fiscal_settings WHERE is_active;
  IF v_count = 0 THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_EMITTER_NOT_CONFIGURED — nenhum emitente fiscal ativo (operacao=%).', p_operation;
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_EMITTER_AMBIGUOUS — % emitentes ativos (operacao=%).', v_count, p_operation;
  END IF;

  SELECT btrim(coalesce(nfe_environment_code, '')) INTO v_env
    FROM (SELECT * FROM public.company_fiscal_settings WHERE (organization_id = public.h15_actor_organization() OR current_setting('role',true) = 'service_role')) company_fiscal_settings WHERE is_active LIMIT 1;

  IF v_env IS NULL OR v_env NOT IN ('1', '2') THEN
    RAISE EXCEPTION
      'FISCAL_ENV_NOT_READY: FISCAL_ENVIRONMENT_INVALID — tpAmb ausente/invalido (operacao=%).', p_operation;
  END IF;
  IF v_env = '1' THEN
    RAISE EXCEPTION
      'FISCAL_PRODUCTION_DISABLED: FISCAL_PRODUCTION_BLOCKED — emissao em producao desabilitada (operacao=%).', p_operation;
  END IF;

  RETURN v_env;
END;
$$;


ALTER FUNCTION public.fn_fiscal_environment_gate_v1(p_operation text) OWNER TO postgres;

--
-- Name: fn_fiscal_event_fingerprint_v1(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_event_fingerprint_v1(_event_type text, _notes text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT md5(
    coalesce(upper(btrim(_event_type)), '') || '|' ||
    coalesce(btrim(_notes), '')
  );
$$;


ALTER FUNCTION public.fn_fiscal_event_fingerprint_v1(_event_type text, _notes text) OWNER TO postgres;

--
-- Name: fn_fiscal_ibge_municipio_coerente(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_ibge_municipio_coerente(_cmun text, _uf text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT public.fn_fiscal_digits(_cmun) ~ '^[0-9]{7}$'
     AND public.fn_fiscal_uf_ibge_code(_uf) IS NOT NULL
     AND substr(public.fn_fiscal_digits(_cmun),1,2) = public.fn_fiscal_uf_ibge_code(_uf);
$_$;


ALTER FUNCTION public.fn_fiscal_ibge_municipio_coerente(_cmun text, _uf text) OWNER TO postgres;

--
-- Name: fn_fiscal_ie_check(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_ie_check(_uf text, _ie text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  uf text := upper(btrim(coalesce(_uf,'')));
  raw text := upper(btrim(coalesce(_ie,'')));
  d text; len int; s int := 0; i int; dv int; w int;
BEGIN
  IF raw = '' THEN RETURN 'MISSING'; END IF;
  IF raw IN ('ISENTO','ISENTA') THEN RETURN 'ISENTO'; END IF;
  IF public.fn_fiscal_uf_ibge_code(uf) IS NULL THEN RETURN 'INVALID_UF'; END IF;
  d := public.fn_fiscal_digits(raw);
  len := length(d);

  IF (uf = 'AC' AND len <> 13)
  OR (uf = 'AL' AND len <> 9) OR (uf = 'AM' AND len <> 9)
  OR (uf = 'AP' AND len <> 9) OR (uf = 'BA' AND len NOT IN (8,9))
  OR (uf = 'CE' AND len <> 9) OR (uf = 'DF' AND len <> 13)
  OR (uf = 'ES' AND len <> 9) OR (uf = 'GO' AND len <> 9)
  OR (uf = 'MA' AND len <> 9) OR (uf = 'MG' AND len <> 13)
  OR (uf = 'MS' AND len <> 9) OR (uf = 'MT' AND len <> 11)
  OR (uf = 'PA' AND len <> 9) OR (uf = 'PB' AND len <> 9)
  OR (uf = 'PE' AND len NOT IN (9,14)) OR (uf = 'PI' AND len <> 9)
  OR (uf = 'PR' AND len <> 10) OR (uf = 'RJ' AND len <> 8)
  OR (uf = 'RN' AND len NOT IN (9,10)) OR (uf = 'RO' AND len <> 14)
  OR (uf = 'RR' AND len <> 9) OR (uf = 'RS' AND len <> 10)
  OR (uf = 'SC' AND len <> 9) OR (uf = 'SE' AND len <> 9)
  OR (uf = 'SP' AND len NOT IN (12,13)) OR (uf = 'TO' AND len <> 9)
  THEN
    RETURN 'INVALID_LENGTH';
  END IF;

  -- Dígito verificador: subconjunto com algoritmo público e estável.
  IF uf = 'GO' THEN
    IF substr(d,1,2) NOT IN ('10','11','15') THEN RETURN 'INVALID_FORMAT'; END IF;
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := s % 11;
    dv := CASE WHEN dv = 0 THEN 0 WHEN dv = 1 THEN 1 ELSE 11 - dv END;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'RJ' THEN
    s := 0; w := 2;
    FOR i IN 1..7 LOOP
      s := s + substr(d,i,1)::int * w;
      w := CASE WHEN w = 7 THEN 2 ELSE w + 1 END;
    END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,8,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  ELSIF uf = 'SC' THEN
    s := 0;
    FOR i IN 1..8 LOOP s := s + substr(d,i,1)::int * (10 - i); END LOOP;
    dv := 11 - (s % 11); IF dv >= 10 THEN dv := 0; END IF;
    RETURN CASE WHEN dv = substr(d,9,1)::int THEN 'VALID_DV' ELSE 'INVALID_DV' END;
  END IF;

  RETURN 'VALID_LENGTH_DV_NOT_IMPLEMENTED';
END $$;


ALTER FUNCTION public.fn_fiscal_ie_check(_uf text, _ie text) OWNER TO postgres;

--
-- Name: fn_fiscal_invoice_eligibility(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_invoice_eligibility(_source_type text, _source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  reasons jsonb := '[]'::jsonb;
  po public.partner_orders%ROWTYPE;
  ent public.entregas%ROWTYPE;
  st text;
  v_order_id uuid;
  v_debtor uuid;
  n_items int := 0; n_quote int := 0; n_no_snapshot int := 0;
  canceled boolean := false;
  allowed text[];
BEGIN
  PERFORM public.h15_require_staff();

  IF _source_type IS NULL OR _source_id IS NULL THEN
    RETURN jsonb_build_object('eligible', false, 'reasons',
      jsonb_build_array(jsonb_build_object('code','FISCAL_SOURCE_MISSING','severity','BLOCK',
        'message','Origem fiscal (pedido/entrega) obrigatoria.')));
  END IF;

  IF _source_type = 'PARTNER_ORDER' THEN
    SELECT * INTO po FROM public.partner_orders WHERE id = _source_id;
    IF NOT FOUND THEN
      reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_NOT_FOUND','severity','BLOCK','message','Pedido inexistente.');
    ELSE
      v_order_id := po.id;
      st := po.status::text;
      allowed := public.fn_fiscal_billing_allowed_order_status();

      IF st = 'cancelado' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_CANCELED','severity','BLOCK','message','Pedido cancelado; emissao bloqueada.');
      ELSIF st IN ('reprovado','reprovado_sem_itens') THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_REJECTED','severity','BLOCK','message','Pedido reprovado; emissao bloqueada.');
      ELSIF st = 'aguardando_cotacao' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_QUOTE_PENDING','severity','BLOCK','message','Pedido aguardando cotacao; emissao bloqueada.');
      ELSIF st = 'faturado' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_ALREADY_INVOICED','severity','BLOCK','message','Pedido ja faturado.');
      ELSIF NOT (st = ANY (allowed)) THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_STATUS_NOT_BILLABLE','severity','BLOCK',
          'message','Status do pedido nao habilitado para faturamento: '||st);
      END IF;

      -- Aprovacao comercial obrigatoria.
      IF po.approved_at IS NULL OR po.approved_by IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_COMMERCIAL_APPROVAL_MISSING','severity','BLOCK',
          'message','Pedido sem aprovacao comercial registrada.');
      END IF;

      -- Aprovacao financeira quando exigida.
      IF coalesce(po.requires_financial_approval,false)
         AND coalesce(po.financial_approval_status,'pending') <> 'approved' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_FINANCIAL_APPROVAL_MISSING','severity','BLOCK',
          'message','Pedido exige aprovacao financeira e ela nao foi concedida.');
      END IF;

      -- Condicao de pagamento aceita/definida.
      IF coalesce(po.payment_condition_status,'') NOT IN ('defined','accepted','aceita') THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_PAYMENT_CONDITION_NOT_ACCEPTED','severity','BLOCK',
          'message','Condicao de pagamento nao aceita/definida.');
      END IF;

      -- Devedor correto: parceiro B2B, nunca o produtor final vinculado.
      IF po.partner_id IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DEBTOR_UNRESOLVED','severity','BLOCK',
          'message','Parceiro devedor do pedido nao identificado.');
      ELSE
        v_debtor := po.partner_id;
      END IF;

      -- Snapshot de preco/condicao e ausencia de itens sob consulta.
      SELECT count(*),
             count(*) FILTER (WHERE coalesce(pricing_mode_snapshot,'') = 'quote_only'),
             count(*) FILTER (WHERE preco_unitario_final_snapshot IS NULL
                                 OR price_source_snapshot IS NULL)
        INTO n_items, n_quote, n_no_snapshot
        FROM public.partner_order_items WHERE order_id = _source_id;

      IF n_items = 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_NO_ITEMS','severity','BLOCK','message','Pedido sem itens.');
      END IF;
      IF n_quote > 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_QUOTE_ONLY_BLOCKED','severity','BLOCK',
          'message','Pedido possui itens sob consulta (quote_only); emissao bloqueada sem efeito colateral.');
      END IF;
      IF n_no_snapshot > 0 THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_PRICE_SNAPSHOT_MISSING','severity','BLOCK',
          'message','Itens sem snapshot de preco/condicao comercial.');
      END IF;
    END IF;

  ELSIF _source_type = 'ENTREGA' THEN
    SELECT * INTO ent FROM public.entregas WHERE id = _source_id;
    IF NOT FOUND THEN
      reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_NOT_FOUND','severity','BLOCK','message','Entrega inexistente.');
    ELSE
      IF ent.cancelada_em IS NOT NULL OR coalesce(ent.status,'') = 'cancelada'
         OR coalesce(ent.financial_status,'') = 'CANCELED' THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_CANCELED','severity','BLOCK','message','Entrega cancelada.');
      END IF;
      IF NOT (coalesce(ent.status,'') = ANY (public.fn_fiscal_billing_allowed_delivery_status())) THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_NOT_COMPLETED','severity','BLOCK',
          'message','Entrega nao concluida/aceita. Status atual: '||coalesce(ent.status,'-'));
      END IF;
      IF ent.recebimento_confirmado_em IS NULL AND ent.confirmada_em IS NULL AND ent.entregue_em IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_RECEIPT_MISSING','severity','BLOCK',
          'message','Entrega sem aceite/recebimento registrado.');
      END IF;
      IF ent.partner_order_id IS NULL THEN
        reasons := reasons || jsonb_build_object('code','FISCAL_DELIVERY_ORDER_LINK_MISSING','severity','BLOCK',
          'message','Entrega sem vinculo inequivoco a pedido B2B.');
      ELSE
        v_order_id := ent.partner_order_id;
        SELECT partner_id, status::text INTO v_debtor, st FROM public.partner_orders WHERE id = ent.partner_order_id;
        IF v_debtor IS NULL THEN
          reasons := reasons || jsonb_build_object('code','FISCAL_DEBTOR_UNRESOLVED','severity','BLOCK',
            'message','Parceiro devedor da entrega nao identificado.');
        END IF;
        IF st IS NULL OR NOT (st = ANY (public.fn_fiscal_billing_allowed_order_status())) THEN
          reasons := reasons || jsonb_build_object('code','FISCAL_ORDER_STATUS_NOT_BILLABLE','severity','BLOCK',
            'message','Pedido vinculado a entrega nao esta habilitado para faturamento: '||coalesce(st,'-'));
        END IF;
      END IF;
    END IF;

  ELSE
    reasons := reasons || jsonb_build_object('code','FISCAL_SOURCE_TYPE_UNSUPPORTED','severity','BLOCK',
      'message','Escopo fiscal nao suportado nesta fase: '||_source_type);
  END IF;

  -- Duplicidade fiscal: documento vivo para a mesma origem.
  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
             WHERE fi.source_type = _source_type AND fi.source_id = _source_id
               AND fi.document_model = 'NFE'
               AND fi.status NOT IN ('CANCELED','REJECTED')
               AND fi.access_key IS NOT NULL) THEN
    reasons := reasons || jsonb_build_object('code','FISCAL_DUPLICATE_DOCUMENT','severity','BLOCK',
      'message','Ja existe documento fiscal vigente para esta origem.');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi
    WHERE fi.source_type = _source_type AND fi.source_id = _source_id
      AND fi.document_model = 'NFE' AND fi.status = 'CANCELED') INTO canceled;

  RETURN jsonb_build_object(
    'eligible', jsonb_array_length(reasons) = 0,
    'reasons', reasons,
    'sourceType', _source_type,
    'orderId', v_order_id,
    'debtorPartnerId', v_debtor,
    'has_canceled_history', canceled);
END $$;


ALTER FUNCTION public.fn_fiscal_invoice_eligibility(_source_type text, _source_id uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_invoice_eligibility(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_invoice_eligibility(_source_type text, _source_id uuid, _current_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$ declare v_result jsonb;v_reasons jsonb; begin
  PERFORM public.h15_require_staff();
  IF _current_invoice_id IS NOT NULL THEN PERFORM public.h15_require_invoice(_current_invoice_id); END IF;
 v_result:=public.fn_fiscal_invoice_eligibility(_source_type,_source_id); if _current_invoice_id is not null and exists(select 1 from (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi where fi.id=_current_invoice_id and fi.source_type=_source_type and fi.source_id=_source_id and fi.document_model='NFE' and fi.status not in ('CANCELED','REJECTED') and fi.access_key is not null) and not exists(select 1 from (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fi where fi.source_type=_source_type and fi.source_id=_source_id and fi.id<>_current_invoice_id and fi.document_model='NFE' and fi.status not in ('CANCELED','REJECTED') and fi.access_key is not null) then select coalesce(jsonb_agg(reason),'[]'::jsonb) into v_reasons from jsonb_array_elements(coalesce(v_result->'reasons','[]'::jsonb)) reason where reason->>'code'<>'FISCAL_DUPLICATE_DOCUMENT'; v_result:=jsonb_set(v_result,'{reasons}',v_reasons,true); v_result:=jsonb_set(v_result,'{eligible}',to_jsonb(jsonb_array_length(v_reasons)=0),true); end if; return v_result; end $$;


ALTER FUNCTION public.fn_fiscal_invoice_eligibility(_source_type text, _source_id uuid, _current_invoice_id uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_item_base(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_item_base(_components jsonb, _ctx jsonb) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v numeric := 0; c text;
BEGIN
  IF _components IS NULL OR jsonb_array_length(_components) = 0 THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_INCOMPLETE: regra sem componentes de base declarados (base_components).'
      USING HINT = 'Declare explicitamente PRODUTO/FRETE/SEGURO/OUTRAS_DESPESAS/DESCONTO/IPI/ICMS_ST conforme base legal publicada.';
  END IF;
  FOR c IN SELECT jsonb_array_elements_text(_components) LOOP
    v := v + CASE c
      WHEN 'PRODUTO'          THEN coalesce((_ctx->>'produto')::numeric,0)
      WHEN 'FRETE'            THEN coalesce((_ctx->>'frete')::numeric,0)
      WHEN 'SEGURO'           THEN coalesce((_ctx->>'seguro')::numeric,0)
      WHEN 'OUTRAS_DESPESAS'  THEN coalesce((_ctx->>'outras')::numeric,0)
      WHEN 'DESCONTO'         THEN -coalesce((_ctx->>'desconto')::numeric,0)
      WHEN 'IPI'              THEN coalesce((_ctx->>'ipi')::numeric,0)
      WHEN 'ICMS_ST'          THEN coalesce((_ctx->>'icmsSt')::numeric,0)
      ELSE 0 END;
  END LOOP;
  RETURN public.fn_fiscal_round(v);
END $$;


ALTER FUNCTION public.fn_fiscal_item_base(_components jsonb, _ctx jsonb) OWNER TO postgres;

--
-- Name: fn_fiscal_item_profile_gate_eval(text, text, boolean, text, timestamp with time zone, text, text, text, text, text, text, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_item_profile_gate_eval(p_scope text, p_crt text, p_is_active boolean, p_profile_status text, p_accounting_validated_at timestamp with time zone, p_accounting_notes text, p_fiscal_description text, p_commercial_unit text, p_taxable_unit text, p_ncm text, p_origin_code text, p_cfop_in_state text, p_cfop_interstate text, p_icms_cst text, p_icms_csosn text, p_pis_cst text, p_cofins_cst text, p_regulatory jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_p jsonb := '[]'::jsonb;   -- pendências técnicas
  v_reg jsonb := '[]'::jsonb; -- pendências regulatórias
  v_na jsonb := '[]'::jsonb;  -- itens declarados NÃO APLICÁVEIS (com justificativa)
  v_notes text := lower(coalesce(p_accounting_notes, ''));
  v_synthetic boolean;
  v_technical_ready boolean;
  v_regulatory_ready boolean;
  v_has_cst boolean := nullif(btrim(coalesce(p_icms_cst,'')),'') IS NOT NULL;
  v_has_csosn boolean := nullif(btrim(coalesce(p_icms_csosn,'')),'') IS NOT NULL;
  v_pend_count int;
BEGIN
  -- ---------------- Camada REGULATÓRIA (Fase F2) ----------------
  -- Exigida apenas onde o dossiê existe como conceito: microrganismos.
  IF p_scope <> 'MICROORGANISM' THEN
    v_reg := '[]'::jsonb;
  ELSIF p_regulatory IS NULL OR p_regulatory = 'null'::jsonb THEN
    v_reg := jsonb_build_array(jsonb_build_object(
      'code','REGULATORY_DOSSIER_MISSING','field','microorganism_regulatory_dossiers','layer','REGULATORY',
      'message','Sem dossie regulatorio cadastrado para o item.'));
  ELSE
    v_na := coalesce(p_regulatory->'checklist_not_applicable','[]'::jsonb);

    IF coalesce(p_regulatory->>'status','') = 'BLOCKED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOSSIER_BLOCKED','field','status','layer','REGULATORY',
        'message', coalesce(p_regulatory->>'blocked_reason','Dossie regulatorio bloqueado.')));
    ELSIF coalesce(p_regulatory->>'status','') <> 'VALIDATED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOSSIER_NOT_PUBLISHED','field','status','layer','REGULATORY',
        'message','Dossie regulatorio em '||coalesce(p_regulatory->>'status','?')||'; exigido VALIDATED.'));
    END IF;

    IF p_regulatory->>'regulatory_category' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_CATEGORY_MISSING','field','regulatory_category','layer','REGULATORY',
        'message','Finalidade/categoria regulatoria nao definida (nao pode ser presumida pela especie).'));
    END IF;
    IF p_regulatory->>'strain' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_STRAIN_MISSING','field','strain_code','layer','REGULATORY',
        'message','Cepa/estirpe nao informada.'));
    END IF;
    IF p_regulatory->>'formulation' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_FORMULATION_MISSING','field','formulation','layer','REGULATORY',
        'message','Formulacao/apresentacao nao informada.'));
    END IF;
    IF p_regulatory->>'label_guarantee' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_LABEL_GUARANTEE_MISSING','field','label_guarantee','layer','REGULATORY',
        'message','Composicao/garantia de rotulo nao informada.'));
    END IF;

    -- MAPA: MISSING x NOT_APPLICABLE justificado x vencido
    IF coalesce(p_regulatory->>'mapa_status','') = 'NOT_APPLICABLE' THEN
      v_na := v_na || jsonb_build_array(jsonb_build_object(
        'item_key','REGISTRO_MAPA','justification', p_regulatory->>'mapa_not_applicable_reason'));
    ELSIF p_regulatory->>'mapa_registration_number' IS NULL THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_MISSING','field','mapa_registration_number','layer','REGULATORY',
        'message','Registro MAPA/SIPEAGRO ausente e sem declaracao justificada de nao aplicabilidade.'));
    ELSIF coalesce(p_regulatory->>'mapa_status','') IN ('EXPIRED','SUSPENDED') THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_INVALID','field','mapa_status','layer','REGULATORY',
        'message','Registro MAPA em situacao '||(p_regulatory->>'mapa_status')||'.'));
    ELSIF (p_regulatory->>'mapa_valid_until') IS NOT NULL
          AND (p_regulatory->>'mapa_valid_until')::date < current_date THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_MAPA_REGISTRATION_INVALID','field','mapa_valid_until','layer','REGULATORY',
        'message','Registro MAPA com validade expirada.'));
    END IF;
    IF p_regulatory->>'mapa_holder' IS NULL AND coalesce(p_regulatory->>'mapa_status','') <> 'NOT_APPLICABLE' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_HOLDER_MISSING','field','mapa_holder','layer','REGULATORY',
        'message','Titular/fabricante do registro nao informado.'));
    END IF;

    -- Documentos de evidência
    IF coalesce((p_regulatory->>'has_label_document')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_LABEL_DOCUMENT_MISSING','field','documents','layer','REGULATORY',
        'message','Rotulo nao anexado ao dossie.'));
    END IF;
    IF coalesce((p_regulatory->>'has_report_document')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_REPORT_DOCUMENT_MISSING','field','documents','layer','REGULATORY',
        'message','Laudo/certificado de analise nao anexado ao dossie.'));
    END IF;
    IF coalesce((p_regulatory->>'expired_documents')::int,0) > 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_DOCUMENT_EXPIRED','field','documents','layer','REGULATORY',
        'message',(p_regulatory->>'expired_documents')||' documento(s) com validade expirada.'));
    END IF;

    -- Aprovações separadas
    IF coalesce(p_regulatory->>'review_technical','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_TECHNICAL_APPROVAL_MISSING','field','technical_review_status','layer','REGULATORY',
        'message','Revisao tecnica nao aprovada.'));
    END IF;
    IF coalesce(p_regulatory->>'review_regulatory','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_RESPONSIBLE_APPROVAL_MISSING','field','regulatory_review_status','layer','REGULATORY',
        'message','Revisao do responsavel tecnico (regulatoria) nao aprovada.'));
    END IF;
    IF coalesce(p_regulatory->>'review_fiscal','PENDING') <> 'APPROVED' THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_FISCAL_APPROVAL_MISSING','field','fiscal_review_status','layer','REGULATORY',
        'message','Revisao contabil/fiscal nao aprovada.'));
    END IF;

    -- Checklist
    v_pend_count := jsonb_array_length(coalesce(p_regulatory->'checklist_pending','[]'::jsonb));
    IF v_pend_count > 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_CHECKLIST_INCOMPLETE','field','checklist','layer','REGULATORY',
        'message', v_pend_count||' item(ns) de checklist pendente(s).',
        'items', p_regulatory->'checklist_pending'));
    END IF;

    -- NCM aprovado e coerente com o perfil fiscal
    IF coalesce((p_regulatory->>'ncm_approved')::boolean,false) IS NOT TRUE THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_NCM_NOT_APPROVED','field','microorganism_ncm_candidates','layer','REGULATORY',
        'message','Nenhum candidato de NCM aprovado; sugestao nunca vale como codigo aprovado.'));
    ELSIF nullif(btrim(coalesce(p_ncm,'')),'') IS NOT NULL
          AND p_regulatory->>'published_ncm' IS NOT NULL
          AND p_regulatory->>'published_ncm' <> btrim(p_ncm) THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_NCM_DIVERGES_FROM_PROFILE','field','ncm','layer','REGULATORY',
        'message','NCM do perfil fiscal diverge do NCM publicado no dossie.'));
    END IF;

    -- Apresentações: unidades e GTIN exigem confirmação explícita
    IF coalesce((p_regulatory->>'presentations_total')::int,0) = 0 THEN
      v_reg := v_reg || jsonb_build_array(jsonb_build_object(
        'code','REGULATORY_PRESENTATION_MISSING','field','presentations','layer','REGULATORY',
        'message','Nenhuma apresentacao cadastrada.'));
    ELSE
      IF coalesce((p_regulatory->>'presentations_units_unconfirmed')::int,0) > 0 THEN
        v_reg := v_reg || jsonb_build_array(jsonb_build_object(
          'code','REGULATORY_UNITS_NOT_CONFIRMED','field','presentations.units','layer','REGULATORY',
          'message',(p_regulatory->>'presentations_units_unconfirmed')||' apresentacao(oes) sem uCom/uTrib/fator confirmados.'));
      END IF;
      IF coalesce((p_regulatory->>'presentations_gtin_unconfirmed')::int,0) > 0 THEN
        v_reg := v_reg || jsonb_build_array(jsonb_build_object(
          'code','REGULATORY_GTIN_NOT_DECLARED','field','presentations.gtin','layer','REGULATORY',
          'message',(p_regulatory->>'presentations_gtin_unconfirmed')||' apresentacao(oes) sem GTIN confirmado nem declaracao SEM GTIN.'));
      END IF;
    END IF;
  END IF;

  -- ---------------- Camada TÉCNICA (Fase F1, inalterada) ----------------
  IF p_profile_status IS NULL THEN
    RETURN jsonb_build_object(
      'scope', p_scope, 'ready', false, 'technical_ready', false, 'regulatory_ready', false,
      'status', 'NOT_READY', 'quarantined', false, 'profile_present', false,
      'not_applicable', v_na,
      'pendencies', jsonb_build_array(jsonb_build_object(
        'code','PROFILE_MISSING','field','profile_status','layer','TECHNICAL',
        'message','Item sem perfil fiscal cadastrado.')) || v_reg);
  END IF;

  v_synthetic := v_notes LIKE '%sintetic%'
              OR v_notes LIKE '%sintétic%'
              OR v_notes LIKE '%homologacao%'
              OR v_notes LIKE '%homologação%'
              OR v_notes LIKE '%hml-b2b%'
              OR v_notes LIKE '%test_only%'
              OR v_notes LIKE '%quarentena%';

  IF coalesce(p_is_active, false) IS NOT TRUE THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_INACTIVE','field','is_active','layer','TECHNICAL','message','Perfil fiscal inativo.'));
  END IF;

  IF p_profile_status = 'BLOCKED' THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_QUARANTINED','field','profile_status','layer','TECHNICAL',
      'message','Perfil fiscal em quarentena (BLOCKED).'));
  ELSIF p_profile_status <> 'VALIDATED' THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_NOT_PUBLISHED','field','profile_status','layer','TECHNICAL',
      'message','Perfil fiscal nao publicado (exigido VALIDATED).'));
  END IF;

  IF p_accounting_validated_at IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','ACCOUNTING_NOT_VALIDATED','field','accounting_validated_at','layer','TECHNICAL',
      'message','Sem validacao contabil preliminar registrada.'));
  END IF;

  IF v_synthetic THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','PROFILE_SYNTHETIC','field','accounting_notes','layer','TECHNICAL',
      'message','Classificacao sintetica de homologacao; nao utilizavel em faturamento.'));
  END IF;

  IF nullif(btrim(coalesce(p_fiscal_description,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_FISCAL_DESCRIPTION','field','fiscal_description','layer','TECHNICAL','message','Descricao fiscal ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_commercial_unit,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_COMMERCIAL_UNIT','field','commercial_unit','layer','TECHNICAL','message','Unidade comercial ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_taxable_unit,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_TAXABLE_UNIT','field','taxable_unit','layer','TECHNICAL','message','Unidade tributavel ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_ncm,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_NCM','field','ncm','layer','TECHNICAL','message','NCM ausente.'));
  ELSIF p_accounting_validated_at IS NULL OR v_synthetic THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','NCM_NOT_ACCOUNTING_REVIEWED','field','ncm','layer','TECHNICAL',
      'message','NCM sem revisao contabil preliminar (validacao contabil ausente ou perfil sintetico). Nao afirma nem substitui evidencia regulatoria.'));
  END IF;
  IF nullif(btrim(coalesce(p_origin_code,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_ORIGIN_CODE','field','origin_code','layer','TECHNICAL','message','Codigo de origem ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cfop_in_state,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_CFOP_IN_STATE','field','cfop_in_state','layer','TECHNICAL','message','CFOP interno ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cfop_interstate,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_CFOP_INTERSTATE','field','cfop_interstate','layer','TECHNICAL','message','CFOP interestadual ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_pis_cst,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_PIS_CST','field','pis_cst','layer','TECHNICAL','message','CST de PIS ausente.'));
  END IF;
  IF nullif(btrim(coalesce(p_cofins_cst,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object('code','MISSING_COFINS_CST','field','cofins_cst','layer','TECHNICAL','message','CST de COFINS ausente.'));
  END IF;

  IF v_has_cst AND v_has_csosn THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','CST_AND_CSOSN_CONFLICT','field','icms_cst,icms_csosn','layer','TECHNICAL',
      'message','CST e CSOSN preenchidos simultaneamente; mutuamente exclusivos.'));
  END IF;

  IF nullif(btrim(coalesce(p_crt,'')),'') IS NULL THEN
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','TAX_REGIME_UNKNOWN','field','company_fiscal_settings.crt','layer','TECHNICAL',
      'message','CRT do emitente nao configurado.'));
  ELSIF p_crt = '3' THEN
    IF v_has_csosn THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CSOSN_NOT_ALLOWED_FOR_CRT3','field','icms_csosn','layer','TECHNICAL',
        'message','CSOSN e exclusivo do Simples Nacional; emitente em CRT 3 (Regime Normal).'));
    END IF;
    IF NOT v_has_cst THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CST_REQUIRED_FOR_CRT3','field','icms_cst','layer','TECHNICAL',
        'message','CST de ICMS obrigatorio para CRT 3.'));
    END IF;
  ELSIF p_crt IN ('1','2') THEN
    IF v_has_cst THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CST_NOT_ALLOWED_FOR_SIMPLES','field','icms_cst','layer','TECHNICAL',
        'message','CST de ICMS nao se aplica a emitente do Simples Nacional.'));
    END IF;
    IF NOT v_has_csosn THEN
      v_p := v_p || jsonb_build_array(jsonb_build_object(
        'code','CSOSN_REQUIRED_FOR_SIMPLES','field','icms_csosn','layer','TECHNICAL',
        'message','CSOSN obrigatorio para CRT 1/2.'));
    END IF;
  ELSE
    v_p := v_p || jsonb_build_array(jsonb_build_object(
      'code','TAX_REGIME_UNKNOWN','field','company_fiscal_settings.crt','layer','TECHNICAL',
      'message','CRT do emitente com valor nao reconhecido.'));
  END IF;

  v_technical_ready := (jsonb_array_length(v_p) = 0);
  v_regulatory_ready := (jsonb_array_length(v_reg) = 0);

  RETURN jsonb_build_object(
    'scope', p_scope,
    'ready', (v_technical_ready AND v_regulatory_ready),
    'technical_ready', v_technical_ready,
    'regulatory_ready', v_regulatory_ready,
    'status', CASE WHEN (v_technical_ready AND v_regulatory_ready) THEN 'READY' ELSE 'NOT_READY' END,
    'quarantined', (p_profile_status = 'BLOCKED'),
    'profile_present', true,
    'not_applicable', v_na,
    'pendencies', v_p || v_reg);
END
$$;


ALTER FUNCTION public.fn_fiscal_item_profile_gate_eval(p_scope text, p_crt text, p_is_active boolean, p_profile_status text, p_accounting_validated_at timestamp with time zone, p_accounting_notes text, p_fiscal_description text, p_commercial_unit text, p_taxable_unit text, p_ncm text, p_origin_code text, p_cfop_in_state text, p_cfop_interstate text, p_icms_cst text, p_icms_csosn text, p_pis_cst text, p_cofins_cst text, p_regulatory jsonb) OWNER TO postgres;

--
-- Name: fn_fiscal_official_url_allowlisted(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_official_url_allowlisted(_url text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  SELECT _url IS NOT NULL
     AND lower(_url) ~ '^https://([a-z0-9-]+\.)*gov\.br(/|$)';
$_$;


ALTER FUNCTION public.fn_fiscal_official_url_allowlisted(_url text) OWNER TO postgres;

--
-- Name: fn_fiscal_partner_fiscal_customer(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_partner_fiscal_customer(_partner_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_customer uuid; n_share int;
BEGIN
  IF _partner_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT pa.client_id INTO v_customer
    FROM public.partner_accounts pa
   WHERE pa.id = _partner_id
     AND pa.deleted_at IS NULL;

  IF v_customer IS NULL THEN
    RETURN NULL;
  END IF;

  -- Duplicidade: mais de um parceiro ativo apontando para o mesmo cliente fiscal
  -- torna o destinatário ambíguo. Nunca escolher em silêncio.
  SELECT count(*) INTO n_share
    FROM public.partner_accounts pa
   WHERE pa.client_id = v_customer
     AND pa.deleted_at IS NULL
     AND coalesce(pa.ativo, true);

  IF n_share > 1 THEN
    RAISE EXCEPTION
      'FISCAL_DEBTOR_RECIPIENT_MISMATCH: % contas de parceiro ativas compartilham o mesmo cliente fiscal; destinatario ambiguo.', n_share
      USING HINT = 'Regularize o cadastro comercial antes de faturar. O motor fiscal nunca desempata devedor automaticamente.';
  END IF;

  RETURN v_customer;
END $$;


ALTER FUNCTION public.fn_fiscal_partner_fiscal_customer(_partner_id uuid) OWNER TO postgres;

--
-- Name: fn_fiscal_recipient_pendencies_row(public.customer_fiscal_profiles); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_recipient_pendencies_row(r public.customer_fiscal_profiles) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE out jsonb := '[]'::jsonb; ie_state text; doc text;
BEGIN
  doc := public.fn_fiscal_digits(r.cpf_cnpj);
  IF r.person_type IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_PERSON_TYPE_MISSING','field','person_type','severity','BLOCK','message','Tipo de pessoa (PF/PJ/ESTRANGEIRO) obrigatorio.');
  ELSIF r.person_type = 'PJ' AND NOT public.fn_fiscal_cnpj_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CNPJ_INVALID','field','cpf_cnpj','severity','BLOCK','message','CNPJ do destinatario invalido.');
  ELSIF r.person_type = 'PF' AND NOT public.fn_fiscal_cpf_is_valid(doc) THEN
    out := out || jsonb_build_object('code','RECIPIENT_CPF_INVALID','field','cpf_cnpj','severity','BLOCK','message','CPF do destinatario invalido.');
  ELSIF r.person_type = 'ESTRANGEIRO' AND coalesce(r.country_code,'1058') IN ('1058','BR') THEN
    out := out || jsonb_build_object('code','RECIPIENT_FOREIGN_COUNTRY_REQUIRED','field','country_code','severity','BLOCK','message','Destinatario estrangeiro exige pais diferente de Brasil.');
  END IF;

  IF nullif(btrim(coalesce(r.legal_name,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_NAME_MISSING','field','legal_name','severity','BLOCK','message','Razao social / nome do destinatario obrigatorio.');
  END IF;
  IF r.taxpayer_indicator IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_TAXPAYER_INDICATOR_MISSING','field','taxpayer_indicator','severity','BLOCK','message','Indicador de IE do destinatario (indIEDest) obrigatorio.');
  END IF;
  IF coalesce(r.foreign_customer_indicator,false) = false THEN
    IF public.fn_fiscal_uf_ibge_code(r.fiscal_state) IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_UF_INVALID','field','fiscal_state','severity','BLOCK','message','UF do destinatario invalida.');
    ELSIF NOT public.fn_fiscal_ibge_municipio_coerente(r.fiscal_municipality_ibge_code, r.fiscal_state) THEN
      out := out || jsonb_build_object('code','RECIPIENT_IBGE_INCOHERENT','field','fiscal_municipality_ibge_code','severity','BLOCK','message','Codigo IBGE do municipio ausente ou incoerente com a UF.');
    END IF;
    IF NOT public.fn_fiscal_cep_is_valid(r.fiscal_postal_code) THEN
      out := out || jsonb_build_object('code','RECIPIENT_CEP_INVALID','field','fiscal_postal_code','severity','BLOCK','message','CEP do destinatario deve ter 8 digitos.');
    END IF;
    IF nullif(btrim(coalesce(r.fiscal_street,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_number,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_neighborhood,'')),'') IS NULL
       OR nullif(btrim(coalesce(r.fiscal_city,'')),'') IS NULL THEN
      out := out || jsonb_build_object('code','RECIPIENT_ADDRESS_INCOMPLETE','field','address','severity','BLOCK','message','Endereco fiscal completo obrigatorio.');
    END IF;
    IF coalesce(r.icms_taxpayer,false) THEN
      ie_state := public.fn_fiscal_ie_check(r.fiscal_state, r.state_registration);
      IF ie_state IN ('MISSING','INVALID_LENGTH','INVALID_DV','INVALID_FORMAT','INVALID_UF','ISENTO') THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_INVALID','field','state_registration','severity','BLOCK','message','Destinatario contribuinte exige IE valida: '||ie_state);
      ELSIF ie_state = 'VALID_LENGTH_DV_NOT_IMPLEMENTED' THEN
        out := out || jsonb_build_object('code','RECIPIENT_IE_DV_NOT_IMPLEMENTED','field','state_registration','severity','WARN','message','IE com formato compativel; DV desta UF nao e verificado automaticamente.');
      END IF;
    END IF;
  END IF;
  IF nullif(btrim(coalesce(r.fiscal_email,'')),'') IS NULL THEN
    out := out || jsonb_build_object('code','RECIPIENT_FISCAL_EMAIL_MISSING','field','fiscal_email','severity','WARN','message','E-mail fiscal ausente; DANFE/XML nao poderao ser enviados automaticamente.');
  END IF;
  RETURN out;
END $$;


ALTER FUNCTION public.fn_fiscal_recipient_pendencies_row(r public.customer_fiscal_profiles) OWNER TO postgres;

--
-- Name: fn_fiscal_reference_entry_normalize(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_reference_entry_normalize() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.search_text := lower(translate(
    coalesce(NEW.code,'') || ' ' || coalesce(NEW.description,''),
    'ÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇáàâãäéèêëíìîïóòôõöúùûüç',
    'AAAAAEEEEIIIIOOOOOUUUUCaaaaaeeeeiiiiooooouuuuc'
  ));
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


