--
-- Name: fn_fiscal_requirement_resolve(text, text, text, text, uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_requirement_resolve(p_sales_channel text, p_operation_type text, p_uf text, p_scope_type text DEFAULT NULL::text, p_scope_id uuid DEFAULT NULL::uuid, p_ref_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_ex record; v_pol record;
BEGIN
  IF p_scope_type IS NOT NULL AND p_scope_id IS NOT NULL THEN
    SELECT * INTO v_ex FROM public.fiscal_requirement_exemptions
     WHERE active AND scope_type = p_scope_type AND scope_id = p_scope_id LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object('required', false, 'status','EXEMPT', 'source','exemption',
        'exemption_id', v_ex.id, 'motivo', v_ex.motivo, 'approved_by', v_ex.approved_by);
    END IF;
  END IF;

  SELECT * INTO v_pol FROM public.fiscal_operation_policies
   WHERE active AND sales_channel = p_sales_channel AND operation_type = p_operation_type
     AND (uf IS NULL OR uf = p_uf)
     AND valid_from <= p_ref_date AND (valid_until IS NULL OR valid_until >= p_ref_date)
   ORDER BY (uf IS NOT NULL) DESC, valid_from DESC LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object('required', v_pol.requires_invoice,
      'status', CASE WHEN v_pol.requires_invoice THEN 'PENDING' ELSE 'NOT_REQUIRED' END,
      'source','policy','policy_id', v_pol.id, 'document_model', v_pol.document_model);
  END IF;

  -- Fail-closed: nunca assume NOT_REQUIRED em silêncio
  RETURN jsonb_build_object('required', true, 'status','PENDING_PARAMETRIZATION',
    'source','pending_parametrization', 'policy_id', NULL,
    'motivo','Nenhuma política fiscal cadastrada para o canal/operação/UF — parametrização contábil pendente');
END $$;


ALTER FUNCTION public.fn_fiscal_requirement_resolve(p_sales_channel text, p_operation_type text, p_uf text, p_scope_type text, p_scope_id uuid, p_ref_date date) OWNER TO postgres;

--
-- Name: fiscal_operation_policies; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.fiscal_operation_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    sales_channel text NOT NULL,
    operation_type text NOT NULL,
    uf text,
    requires_invoice boolean NOT NULL,
    document_model text,
    legal_basis text,
    notes text,
    active boolean DEFAULT true NOT NULL,
    valid_from date DEFAULT CURRENT_DATE NOT NULL,
    valid_until date,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    direction text,
    fin_nfe smallint,
    nature_operation text,
    presence_indicator smallint,
    final_consumer boolean,
    taxpayer_indicator text,
    origin_uf text,
    destination_uf text,
    cfop text,
    crt text,
    ncm_prefix text,
    product_category text,
    priority integer DEFAULT 100 NOT NULL,
    source_id uuid,
    legal_version text,
    policy_status text DEFAULT 'DRAFT'::text NOT NULL,
    published_at timestamp with time zone,
    published_by uuid,
    prepared_by uuid,
    CONSTRAINT fiscal_operation_policies_sales_channel_check CHECK ((sales_channel = ANY (ARRAY['b2b_partner'::text, 'direct_producer'::text, 'internal'::text]))),
    CONSTRAINT fop_cfop_format CHECK (((cfop IS NULL) OR (cfop ~ '^[1-7][0-9]{3}$'::text))),
    CONSTRAINT fop_crt_domain CHECK (((crt IS NULL) OR (crt = ANY (ARRAY['1'::text, '2'::text, '3'::text, '4'::text])))),
    CONSTRAINT fop_direction_domain CHECK (((direction IS NULL) OR (direction = ANY (ARRAY['IN'::text, 'OUT'::text])))),
    CONSTRAINT fop_fin_nfe_domain CHECK (((fin_nfe IS NULL) OR ((fin_nfe >= 1) AND (fin_nfe <= 4)))),
    CONSTRAINT fop_presence_domain CHECK (((presence_indicator IS NULL) OR ((presence_indicator >= 0) AND (presence_indicator <= 9)))),
    CONSTRAINT fop_published_requires_evidence CHECK (((policy_status <> 'PUBLISHED'::text) OR ((cfop IS NOT NULL) AND (nature_operation IS NOT NULL) AND (direction IS NOT NULL) AND (document_model = '55'::text) AND (source_id IS NOT NULL) AND (NULLIF(btrim(COALESCE(legal_basis, ''::text)), ''::text) IS NOT NULL) AND (published_at IS NOT NULL) AND (published_by IS NOT NULL)))),
    CONSTRAINT fop_status_domain CHECK ((policy_status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'SUPERSEDED'::text]))),
    CONSTRAINT fop_ufs_domain CHECK ((((origin_uf IS NULL) OR (public.fn_fiscal_uf_ibge_code(origin_uf) IS NOT NULL)) AND ((destination_uf IS NULL) OR (destination_uf = 'EX'::text) OR (public.fn_fiscal_uf_ibge_code(destination_uf) IS NOT NULL)))),
    CONSTRAINT fop_validity_ck CHECK (((valid_until IS NULL) OR (valid_until >= valid_from)))
);


ALTER TABLE public.fiscal_operation_policies OWNER TO postgres;

--
-- Name: fn_fiscal_resolve_operation(text, text, text, text, boolean, text, text, text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_resolve_operation(_direction text, _origin_uf text, _destination_uf text, _crt text, _final_consumer boolean, _taxpayer_indicator text, _ncm text, _product_category text, _sales_channel text, _ref_date date DEFAULT CURRENT_DATE) RETURNS public.fiscal_operation_policies
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE p public.fiscal_operation_policies%ROWTYPE; n_tie int;
BEGIN
  WITH cand AS (
    SELECT f.*,
           row_number() OVER (ORDER BY f.priority ASC,
             (f.ncm_prefix IS NOT NULL) DESC, (f.destination_uf IS NOT NULL) DESC,
             (f.origin_uf IS NOT NULL) DESC, (f.taxpayer_indicator IS NOT NULL) DESC,
             (f.final_consumer IS NOT NULL) DESC, f.valid_from DESC) AS rn,
           f.priority AS p_ord,
           (f.ncm_prefix IS NOT NULL) AS s_ncm,
           (f.destination_uf IS NOT NULL) AS s_dest,
           (f.origin_uf IS NOT NULL) AS s_orig,
           (f.taxpayer_indicator IS NOT NULL) AS s_ind,
           (f.final_consumer IS NOT NULL) AS s_fc
      FROM public.fiscal_operation_policies f
     WHERE f.policy_status = 'PUBLISHED' AND f.document_model = '55' AND f.active IS TRUE
       AND f.direction = _direction
       AND (f.origin_uf IS NULL OR f.origin_uf = upper(_origin_uf))
       AND (f.destination_uf IS NULL OR f.destination_uf = upper(_destination_uf))
       AND (f.crt IS NULL OR f.crt = _crt)
       AND (f.final_consumer IS NULL OR f.final_consumer = _final_consumer)
       AND (f.taxpayer_indicator IS NULL OR f.taxpayer_indicator = _taxpayer_indicator)
       AND (f.ncm_prefix IS NULL OR public.fn_fiscal_digits(_ncm) LIKE f.ncm_prefix || '%')
       AND (f.product_category IS NULL OR f.product_category = _product_category)
       AND (f.sales_channel IS NULL OR f.sales_channel = _sales_channel)
       AND f.valid_from <= _ref_date
       AND (f.valid_until IS NULL OR f.valid_until >= _ref_date)
  )
  SELECT count(*) INTO n_tie
    FROM cand
   WHERE (p_ord, s_ncm, s_dest, s_orig, s_ind, s_fc, valid_from)
       = (SELECT p_ord, s_ncm, s_dest, s_orig, s_ind, s_fc, valid_from FROM cand WHERE rn = 1);

  IF n_tie IS NULL OR n_tie = 0 THEN
    RAISE EXCEPTION 'FISCAL_OPERATION_POLICY_NOT_FOUND: sem politica publicada para direcao=% origem=% destino=% crt=% consumidorFinal=% indIEDest=% ncm=%',
      _direction, _origin_uf, _destination_uf, _crt, _final_consumer, _taxpayer_indicator, coalesce(_ncm,'-')
      USING HINT = 'Cadastre e publique a politica de operacao com CFOP, natureza, base legal e fonte oficial.';
  END IF;
  IF n_tie > 1 THEN
    RAISE EXCEPTION 'FISCAL_OPERATION_POLICY_AMBIGUOUS: % politicas publicadas com a mesma precedencia efetiva (origem=%, destino=%).',
      n_tie, _origin_uf, _destination_uf
      USING HINT = 'Resolva a ambiguidade por priority/vigencia/especificidade antes de emitir.';
  END IF;

  SELECT * INTO p FROM public.fiscal_operation_policies f
   WHERE f.policy_status = 'PUBLISHED' AND f.document_model = '55' AND f.active IS TRUE
     AND f.direction = _direction
     AND (f.origin_uf IS NULL OR f.origin_uf = upper(_origin_uf))
     AND (f.destination_uf IS NULL OR f.destination_uf = upper(_destination_uf))
     AND (f.crt IS NULL OR f.crt = _crt)
     AND (f.final_consumer IS NULL OR f.final_consumer = _final_consumer)
     AND (f.taxpayer_indicator IS NULL OR f.taxpayer_indicator = _taxpayer_indicator)
     AND (f.ncm_prefix IS NULL OR public.fn_fiscal_digits(_ncm) LIKE f.ncm_prefix || '%')
     AND (f.product_category IS NULL OR f.product_category = _product_category)
     AND (f.sales_channel IS NULL OR f.sales_channel = _sales_channel)
     AND f.valid_from <= _ref_date
     AND (f.valid_until IS NULL OR f.valid_until >= _ref_date)
   ORDER BY f.priority ASC, (f.ncm_prefix IS NOT NULL) DESC,
            (f.destination_uf IS NOT NULL) DESC, (f.origin_uf IS NOT NULL) DESC,
            (f.taxpayer_indicator IS NOT NULL) DESC, (f.final_consumer IS NOT NULL) DESC,
            f.valid_from DESC
   LIMIT 1;
  RETURN p;
END $$;


ALTER FUNCTION public.fn_fiscal_resolve_operation(_direction text, _origin_uf text, _destination_uf text, _crt text, _final_consumer boolean, _taxpayer_indicator text, _ncm text, _product_category text, _sales_channel text, _ref_date date) OWNER TO postgres;

--
-- Name: fn_fiscal_resolve_tax_rule(text, text, text, text, text, text, boolean, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_fiscal_resolve_tax_rule(_tax_kind text, _crt text, _origin_uf text, _destination_uf text, _ncm text, _product_category text, _final_consumer boolean, _taxpayer_indicator text, _ref_date date DEFAULT CURRENT_DATE) RETURNS public.fiscal_tax_rules
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE r public.fiscal_tax_rules%ROWTYPE; n_tie int;
BEGIN
  IF _tax_kind IN ('IBS','CBS','IS') THEN
    RAISE EXCEPTION 'FISCAL_RTC_ENGINE_UNAVAILABLE: tributo % nao possui engine compativel nesta fase.', _tax_kind;
  END IF;

  WITH cand AS (
    SELECT t.*,
           row_number() OVER (ORDER BY t.priority ASC,
             (t.ncm_prefix IS NOT NULL) DESC, (t.destination_uf IS NOT NULL) DESC,
             (t.origin_uf IS NOT NULL) DESC, t.valid_from DESC, t.version DESC) AS rn,
           t.priority AS p_ord,
           (t.ncm_prefix IS NOT NULL) AS s_ncm,
           (t.destination_uf IS NOT NULL) AS s_dest,
           (t.origin_uf IS NOT NULL) AS s_orig
      FROM public.fiscal_tax_rules t
     WHERE t.status = 'PUBLISHED'
       AND t.tax_kind = _tax_kind
       AND (t.crt IS NULL OR t.crt = _crt)
       AND (t.origin_uf IS NULL OR t.origin_uf = upper(_origin_uf))
       AND (t.destination_uf IS NULL OR t.destination_uf = upper(_destination_uf))
       AND (t.ncm_prefix IS NULL OR public.fn_fiscal_digits(_ncm) LIKE t.ncm_prefix || '%')
       AND (t.product_category IS NULL OR t.product_category = _product_category)
       AND (t.final_consumer IS NULL OR t.final_consumer = _final_consumer)
       AND (t.taxpayer_indicator IS NULL OR t.taxpayer_indicator = _taxpayer_indicator)
       AND t.valid_from <= _ref_date
       AND (t.valid_until IS NULL OR t.valid_until >= _ref_date)
  )
  SELECT count(*) INTO n_tie
    FROM cand
   WHERE (p_ord, s_ncm, s_dest, s_orig, valid_from)
       = (SELECT p_ord, s_ncm, s_dest, s_orig, valid_from FROM cand WHERE rn = 1);

  IF n_tie IS NULL OR n_tie = 0 THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_NOT_FOUND: sem regra publicada para tributo=% crt=% origem=% destino=% ncm=%',
      _tax_kind, _crt, _origin_uf, _destination_uf, coalesce(_ncm,'-')
      USING HINT = 'Cadastre a regra com CST/CSOSN, parametros do tributo, base legal e fonte oficial, e publique-a. Ausencia de regra nunca e isencao.';
  END IF;
  IF n_tie > 1 THEN
    RAISE EXCEPTION 'FISCAL_TAX_RULE_AMBIGUOUS: % regras publicadas com a mesma precedencia efetiva para tributo=% origem=% destino=%.',
      n_tie, _tax_kind, _origin_uf, _destination_uf
      USING HINT = 'Ajuste priority/vigencia/especificidade. O motor nunca escolhe silenciosamente.';
  END IF;

  SELECT * INTO r FROM public.fiscal_tax_rules t
   WHERE t.status = 'PUBLISHED' AND t.tax_kind = _tax_kind
     AND (t.crt IS NULL OR t.crt = _crt)
     AND (t.origin_uf IS NULL OR t.origin_uf = upper(_origin_uf))
     AND (t.destination_uf IS NULL OR t.destination_uf = upper(_destination_uf))
     AND (t.ncm_prefix IS NULL OR public.fn_fiscal_digits(_ncm) LIKE t.ncm_prefix || '%')
     AND (t.product_category IS NULL OR t.product_category = _product_category)
     AND (t.final_consumer IS NULL OR t.final_consumer = _final_consumer)
     AND (t.taxpayer_indicator IS NULL OR t.taxpayer_indicator = _taxpayer_indicator)
     AND t.valid_from <= _ref_date
     AND (t.valid_until IS NULL OR t.valid_until >= _ref_date)
   ORDER BY t.priority ASC, (t.ncm_prefix IS NOT NULL) DESC,
            (t.destination_uf IS NOT NULL) DESC, (t.origin_uf IS NOT NULL) DESC,
            t.valid_from DESC, t.version DESC
   LIMIT 1;

  -- Coerencia CRT em tempo de resolucao (defesa adicional a constraint).
  IF r.tax_kind IN ('ICMS','ICMS_ST') AND _crt IS NOT NULL THEN
    IF _crt IN ('1','2') AND r.csosn IS NULL THEN
      RAISE EXCEPTION 'FISCAL_CRT_INCOHERENT: emitente CRT % exige CSOSN na regra de %.', _crt, r.tax_kind;
    END IF;
    IF _crt IN ('3','4') AND r.cst IS NULL THEN
      RAISE EXCEPTION 'FISCAL_CRT_INCOHERENT: emitente CRT % exige CST de ICMS na regra de %.', _crt, r.tax_kind;
    END IF;
  END IF;

  RETURN r;
END $$;


ALTER FUNCTION public.fn_fiscal_resolve_tax_rule(_tax_kind text, _crt text, _origin_uf text, _destination_uf text, _ncm text, _product_category text, _final_consumer boolean, _taxpayer_indicator text, _ref_date date) OWNER TO postgres;

