CREATE FUNCTION public.fn_fiscal_round(_v numeric) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT round(coalesce(_v, 0)::numeric, 2);
$$;


