--
-- Name: fn_h6_guard_title_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6_guard_title_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.total_amount IS DISTINCT FROM OLD.total_amount
     OR NEW.installment_count IS DISTINCT FROM OLD.installment_count
     OR NEW.origin_type IS DISTINCT FROM OLD.origin_type
     OR NEW.origin_id IS DISTINCT FROM OLD.origin_id
     OR NEW.issue_date IS DISTINCT FROM OLD.issue_date
     OR NEW.first_due_date IS DISTINCT FROM OLD.first_due_date
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'Snapshot financeiro imutavel: valor, parcelas, origem e datas de emissao nao podem ser alterados.'
      USING ERRCODE='check_violation';
  END IF;

  IF TG_TABLE_NAME = 'accounts_receivable'
     AND (to_jsonb(NEW)->>'payment_method_id') IS DISTINCT FROM (to_jsonb(OLD)->>'payment_method_id') THEN
    RAISE EXCEPTION 'Condicao/metodo do titulo e imutavel apos a criacao: use o metodo na baixa (receivable_payments).'
      USING ERRCODE='check_violation';
  END IF;

  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_h6_guard_title_snapshot() OWNER TO postgres;

--
-- Name: fn_h6_payments_append_only(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6_payments_append_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF public.fn_h6d_hard_delete_allowed() THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'Baixa financeira nao pode ser excluida: use estorno (fn_reverse_payment).'
      USING ERRCODE='check_violation';
  END IF;
  RAISE EXCEPTION 'Baixa financeira e imutavel: use estorno (fn_reverse_payment).'
    USING ERRCODE='check_violation';
END $$;


ALTER FUNCTION public.fn_h6_payments_append_only() OWNER TO postgres;

--
-- Name: fn_h6b_num(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6b_num(p numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT to_char(round(COALESCE(p,0), 2), 'FM9999999999990.00');
$$;


ALTER FUNCTION public.fn_h6b_num(p numeric) OWNER TO postgres;

--
-- Name: fn_h6b_payment_fingerprint(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6b_payment_fingerprint(p_kind text, p_installment_id uuid, p_payload jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  SELECT encode(extensions.digest(
    concat_ws('|',
      'v1', p_kind, p_installment_id::text,
      public.fn_h6b_num(COALESCE((p_payload->>'amount_received')::numeric,
                                 (p_payload->>'amount_paid')::numeric)),
      public.fn_h6b_num((p_payload->>'discount_amount')::numeric),
      public.fn_h6b_num((p_payload->>'interest_amount')::numeric),
      public.fn_h6b_num((p_payload->>'penalty_amount')::numeric),
      COALESCE(NULLIF(p_payload->>'payment_method_id',''), '-'),
      COALESCE(NULLIF(p_payload->>'bank_account_id',''), '-'),
      COALESCE(NULLIF(p_payload->>'payment_date',''), '-'),
      COALESCE(NULLIF(p_payload->>'notes',''), '-'),
      COALESCE(NULLIF(p_payload->>'has_receipt',''), '-')
    ), 'sha256'), 'hex');
$$;


ALTER FUNCTION public.fn_h6b_payment_fingerprint(p_kind text, p_installment_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: fn_h6b_reconciliacao_valor_faturavel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6b_reconciliacao_valor_faturavel() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_canon jsonb;
BEGIN
  IF NEW.status = 'reconciliada' AND NEW.valor_faturavel_max IS NULL THEN
    v_canon := public.fn_entrega_valor_faturavel_v1(NEW.entrega_id);
    IF (v_canon->>'valor') IS NOT NULL THEN
      NEW.valor_faturavel_max  := round((v_canon->>'valor')::numeric, 2);
      NEW.valor_faturavel_origem := v_canon->>'origem';
      NEW.valor_faturavel_metodo := v_canon->'metodo';
    ELSE
      NEW.valor_faturavel_origem := 'indisponivel';
      NEW.valor_faturavel_metodo := v_canon;
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.fn_h6b_reconciliacao_valor_faturavel() OWNER TO postgres;

--
-- Name: fn_h6c_entrega_ar_b2b_link(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_h6c_entrega_ar_b2b_link() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_po public.partner_orders%ROWTYPE;
  v_settings record;
BEGIN
  IF NEW.receivable_id IS NULL
     OR NEW.partner_order_id IS NULL
     OR NEW.receivable_id IS NOT DISTINCT FROM OLD.receivable_id THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_po FROM public.partner_orders WHERE id = NEW.partner_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- 1) o recebível passa a pertencer ao parceiro (entra em saldo_em_aberto)
  UPDATE public.accounts_receivable
     SET partner_id = v_po.partner_id
   WHERE id = NEW.receivable_id AND partner_id IS DISTINCT FROM v_po.partner_id;

  -- 2) vínculo financeiro canônico (idempotente: unique em partner_order_id)
  SELECT * INTO v_settings FROM public.partner_financial_settings WHERE partner_id = v_po.partner_id;
  INSERT INTO public.partner_order_financial_links(
    partner_order_id, partner_id, receivable_id, financial_status, billing_trigger, created_by)
  VALUES (v_po.id, v_po.partner_id, NEW.receivable_id, 'gerado',
          COALESCE(v_settings.billing_trigger, 'entrega'), NEW.billing_generated_by)
  ON CONFLICT (partner_order_id) DO NOTHING;

  -- 3) pedido deixa de ser "comprometido não faturado"
  UPDATE public.partner_orders
     SET financial_status = 'gerado',
         receivable_generated = true,
         receivable_generated_at = COALESCE(receivable_generated_at, now()),
         receivable_generated_by = COALESCE(receivable_generated_by, NEW.billing_generated_by)
   WHERE id = v_po.id AND COALESCE(receivable_generated,false) = false;

  RETURN NEW;
END
$$;


ALTER FUNCTION public.fn_h6c_entrega_ar_b2b_link() OWNER TO postgres;

