--
-- Name: fn_mark_entrega_not_billable(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_entrega_not_billable(_entrega_id uuid, _reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_entrega public.entregas%ROWTYPE;
BEGIN
  IF NOT public.is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para marcar entrega como sem cobrança.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF _reason IS NULL OR length(trim(_reason)) = 0 THEN
    RAISE EXCEPTION 'Motivo é obrigatório.' USING ERRCODE='check_violation';
  END IF;

  SELECT * INTO v_entrega FROM public.entregas WHERE id = _entrega_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.'; END IF;
  IF v_entrega.receivable_id IS NOT NULL THEN
    RAISE EXCEPTION 'Entrega já foi faturada.' USING ERRCODE='check_violation';
  END IF;

  UPDATE public.entregas
    SET financial_status = 'NOT_BILLABLE',
        not_billable_reason = _reason
    WHERE id = _entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES ('entregas', _entrega_id, 'MARK_NOT_BILLABLE',
    jsonb_build_object('financial_status', v_entrega.financial_status),
    jsonb_build_object('financial_status', 'NOT_BILLABLE', 'reason', _reason),
    v_uid);
END $$;


ALTER FUNCTION public.fn_mark_entrega_not_billable(_entrega_id uuid, _reason text) OWNER TO postgres;

--
-- Name: fn_mark_financial_overdue(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_mark_financial_overdue() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_org uuid := platform_private.h15_actor_organization();
BEGIN
 IF auth.uid() IS NULL OR v_org IS NULL OR NOT COALESCE(public.is_financial_staff(auth.uid()),false) THEN
  RAISE EXCEPTION 'FINANCIAL_SCOPE_DENIED' USING ERRCODE='42501';
 END IF;
 UPDATE public.accounts_receivable_installments i SET status='OVERDUE'
 WHERE i.organization_id=v_org AND i.status='OPEN' AND i.due_date<(pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date
 AND EXISTS (SELECT 1 FROM public.accounts_receivable p WHERE p.id=i.receivable_id AND p.organization_id=v_org);
 UPDATE public.accounts_payable_installments i SET status='OVERDUE'
 WHERE i.organization_id=v_org AND i.status='OPEN' AND i.due_date<(pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date
 AND EXISTS (SELECT 1 FROM public.accounts_payable p WHERE p.id=i.payable_id AND p.organization_id=v_org);
 UPDATE public.accounts_receivable p SET status='OVERDUE'
 WHERE p.organization_id=v_org AND p.status IN ('OPEN','PARTIAL')
 AND EXISTS (SELECT 1 FROM public.accounts_receivable_installments i WHERE i.receivable_id=p.id AND i.organization_id=v_org AND i.status='OVERDUE');
 UPDATE public.accounts_payable p SET status='OVERDUE'
 WHERE p.organization_id=v_org AND p.status IN ('OPEN','PARTIAL')
 AND EXISTS (SELECT 1 FROM public.accounts_payable_installments i WHERE i.payable_id=p.id AND i.organization_id=v_org AND i.status='OVERDUE');
END $$;


ALTER FUNCTION public.fn_mark_financial_overdue() OWNER TO postgres;

--
-- Name: fn_microorganism_regulatory_facts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_microorganism_regulatory_facts(p_microorganism_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH g AS (
    SELECT (auth.uid() IS NULL
            OR public.fn_regulatory_can_read(auth.uid())
            OR public.fn_fiscal_can_read_internal(auth.uid())
            OR public.can_view_catalog_internal(auth.uid())) AS ok
  ), d AS (
    SELECT * FROM public.microorganism_regulatory_dossiers
     WHERE microorganism_id = p_microorganism_id AND deleted_at IS NULL
       AND (SELECT ok FROM g)
     ORDER BY (status='VALIDATED') DESC, version DESC
     LIMIT 1)
  SELECT CASE WHEN NOT (SELECT ok FROM g) THEN NULL
              WHEN NOT EXISTS (SELECT 1 FROM d) THEN NULL ELSE (
    SELECT jsonb_build_object(
      'dossier_id', d.id,
      'version', d.version,
      'status', d.status,
      'blocked_reason', d.blocked_reason,
      'regulatory_category', d.regulatory_category,
      'strain', coalesce(nullif(btrim(coalesce(d.strain_code,'')),''), nullif(btrim(coalesce(d.strain_name,'')),'')),
      'formulation', nullif(btrim(coalesce(d.formulation,'')),''),
      'label_guarantee', nullif(btrim(coalesce(d.label_guarantee,'')),''),
      'mapa_status', d.mapa_status,
      'mapa_registration_number', nullif(btrim(coalesce(d.mapa_registration_number,'')),''),
      'mapa_holder', nullif(btrim(coalesce(d.mapa_holder,'')),''),
      'mapa_valid_until', d.mapa_valid_until,
      'mapa_not_applicable_reason', nullif(btrim(coalesce(d.mapa_not_applicable_reason,'')),''),
      'published_ncm', d.published_ncm,
      'published_cest', d.published_cest,
      'effective_from', d.effective_from,
      'effective_to', d.effective_to,
      'review_technical', d.technical_review_status,
      'review_regulatory', d.regulatory_review_status,
      'review_fiscal', d.fiscal_review_status,
      'has_label_document', EXISTS (SELECT 1 FROM public.microorganism_regulatory_documents x
                                     WHERE x.dossier_id=d.id AND x.deleted_at IS NULL AND x.doc_type='ROTULO'),
      'has_report_document', EXISTS (SELECT 1 FROM public.microorganism_regulatory_documents x
                                     WHERE x.dossier_id=d.id AND x.deleted_at IS NULL AND x.doc_type IN ('LAUDO','CERTIFICADO_ANALISE')),
      'expired_documents', (SELECT count(*) FROM public.microorganism_regulatory_documents x
                             WHERE x.dossier_id=d.id AND x.deleted_at IS NULL
                               AND x.valid_until IS NOT NULL AND x.valid_until < current_date),
      'ncm_approved', EXISTS (SELECT 1 FROM public.microorganism_ncm_candidates c
                               WHERE c.dossier_id=d.id AND c.status='APPROVED'),
      'ncm_candidates', (SELECT count(*) FROM public.microorganism_ncm_candidates c WHERE c.dossier_id=d.id),
      'checklist_total', (SELECT count(*) FROM public.microorganism_regulatory_checklist c WHERE c.dossier_id=d.id),
      'checklist_pending', coalesce((SELECT jsonb_agg(c.item_key ORDER BY c.item_key)
                                      FROM public.microorganism_regulatory_checklist c
                                      WHERE c.dossier_id=d.id AND c.state='PENDING'),'[]'::jsonb),
      'checklist_not_applicable', coalesce((SELECT jsonb_agg(jsonb_build_object(
                                      'item_key',c.item_key,'justification',c.justification) ORDER BY c.item_key)
                                      FROM public.microorganism_regulatory_checklist c
                                      WHERE c.dossier_id=d.id AND c.state='NOT_APPLICABLE'),'[]'::jsonb),
      'checklist_confirmed', (SELECT count(*) FROM public.microorganism_regulatory_checklist c
                               WHERE c.dossier_id=d.id AND c.state='CONFIRMED'),
      'presentations_total', (SELECT count(*) FROM public.microorganism_regulatory_presentations p WHERE p.dossier_id=d.id),
      'presentations_units_unconfirmed', (SELECT count(*) FROM public.microorganism_regulatory_presentations p
                                           WHERE p.dossier_id=d.id AND NOT p.units_confirmed),
      'presentations_gtin_unconfirmed', (SELECT count(*) FROM public.microorganism_regulatory_presentations p
                                          WHERE p.dossier_id=d.id AND NOT p.gtin_confirmed))
    FROM d) END;
$$;


ALTER FUNCTION public.fn_microorganism_regulatory_facts(p_microorganism_id uuid) OWNER TO postgres;

--
-- Name: fn_notify_lab_on_programacao(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notify_lab_on_programacao() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ DECLARE org uuid; prod text; cli text; BEGIN
 IF NEW.status::text<>'aguardando' THEN RETURN NEW; END IF;
 org:=platform_private.notification_source_org('programacao_producao',NEW.id);
 IF org IS NULL THEN RETURN NEW; END IF;
 SELECT nome INTO prod FROM public.produtos WHERE id=NEW.produto_id;
 SELECT c.nome INTO cli FROM public.ordens_servico o JOIN public.clientes c ON c.id=o.cliente_id AND c.organization_id=org WHERE o.id=NEW.ordem_servico_id;
 INSERT INTO public.notificacoes_operacionais(usuario_id,tipo,titulo,mensagem,link,source_type,source_id)
 SELECT DISTINCT ur.user_id,'nova_demanda_producao','Nova demanda de produção',coalesce(prod,'Bioinsumo')||coalesce(' · '||cli,'')||coalesce(' · '||round(NEW.volume_necessario/1000.0,1)::text||' L',''),'/pcp?coluna=aguardando','programacao_producao',NEW.id
 FROM public.user_roles ur WHERE ur.role IN ('producao','administrador','gestor') AND platform_private.notification_user_ok(ur.user_id,org);
 RETURN NEW; END $$;


ALTER FUNCTION public.fn_notify_lab_on_programacao() OWNER TO postgres;

