-- Name: get_b2b_partner_clients_for_assignment_secure(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_partner_clients_for_assignment_secure(p_search text DEFAULT NULL::text) RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, cidade text, estado text, documento_mascarado text, active boolean, ja_vinculado_ao_parceiro boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='AUTHENTICATION_REQUIRED'; END IF;
 IF public.h15_actor_organization() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ACTIVE_TENANT_REQUIRED'; END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='B2B_ASSIGNMENT_CONTRACT_UNAVAILABLE';
END $$;


ALTER FUNCTION public.get_b2b_partner_clients_for_assignment_secure(p_search text) OWNER TO postgres;

--
-- Name: get_b2b_technician_client_detail_secure(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_technician_client_detail_secure(p_cliente_id uuid) RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, email text, cidade text, estado text, bairro text, logradouro text, observacoes text, total_simulacoes bigint, ultima_simulacao_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_comercial boolean;
  v_is_gestor boolean;
  v_is_tecnico boolean;
  v_user_partner uuid;
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  v_is_admin := public.has_role(v_uid, 'administrador'::app_role);
  v_is_comercial := public.has_role(v_uid, 'gestor_comercial'::app_role);
  v_is_gestor := public.has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_tecnico := public.has_role(v_uid, 'parceiro_b2b_tecnico'::app_role);

  IF v_is_admin OR v_is_comercial THEN
    v_allowed := true;
  ELSIF v_is_gestor THEN
    v_user_partner := public.get_user_partner_id();
    SELECT EXISTS(
      SELECT 1 FROM public.partner_technician_clients ptc
      WHERE ptc.cliente_id = p_cliente_id AND ptc.partner_id = v_user_partner AND ptc.active = true
    ) INTO v_allowed;
  ELSIF v_is_tecnico THEN
    v_user_partner := public.get_user_partner_id();
    SELECT EXISTS(
      SELECT 1 FROM public.partner_technician_clients ptc
      WHERE ptc.cliente_id = p_cliente_id
        AND ptc.technician_user_id = v_uid
        AND ptc.partner_id = v_user_partner
        AND ptc.active = true
    ) INTO v_allowed;
  END IF;

  IF NOT v_allowed THEN RAISE EXCEPTION 'forbidden'; END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.nome,
    c.razao_social,
    c.nome_fantasia,
    c.tipo_pessoa,
    CASE
      WHEN c.cpf_cnpj IS NULL THEN NULL
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 11
        THEN '***.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 4, 3) || '.***-**'
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 14
        THEN '**.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 3, 3) || '.***/****-**'
      ELSE '***'
    END,
    c.telefone,
    c.email,
    c.endereco_municipio,
    c.endereco_estado,
    c.endereco_bairro,
    c.endereco_logradouro,
    c.observacoes,
    COALESCE((SELECT COUNT(*) FROM public.partner_simulations ps WHERE ps.cliente_id = c.id), 0),
    (SELECT MAX(ps.created_at) FROM public.partner_simulations ps WHERE ps.cliente_id = c.id)
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
END;
$$;


ALTER FUNCTION public.get_b2b_technician_client_detail_secure(p_cliente_id uuid) OWNER TO postgres;

--
-- Name: get_b2b_technician_clients_secure(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_technician_clients_secure(p_partner_id uuid DEFAULT NULL::uuid, p_technician_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, cidade text, estado text, ultima_simulacao_at timestamp with time zone, total_simulacoes bigint, assigned_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_comercial boolean;
  v_is_gestor boolean;
  v_is_tecnico boolean;
  v_user_partner uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth required';
  END IF;

  v_is_admin := public.has_role(v_uid, 'administrador'::app_role);
  v_is_comercial := public.has_role(v_uid, 'gestor_comercial'::app_role);
  v_is_gestor := public.has_role(v_uid, 'parceiro_b2b'::app_role);
  v_is_tecnico := public.has_role(v_uid, 'parceiro_b2b_tecnico'::app_role);

  IF NOT (v_is_admin OR v_is_comercial OR v_is_gestor OR v_is_tecnico) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF v_is_gestor OR v_is_tecnico THEN
    v_user_partner := public.get_user_partner_id();
  END IF;

  RETURN QUERY
  WITH links AS (
    SELECT ptc.cliente_id, ptc.partner_id, ptc.technician_user_id, ptc.assigned_at
    FROM public.partner_technician_clients ptc
    WHERE ptc.active = true
      AND (
        v_is_admin OR v_is_comercial
        OR (v_is_gestor AND ptc.partner_id = v_user_partner)
        OR (v_is_tecnico AND ptc.technician_user_id = v_uid AND ptc.partner_id = v_user_partner)
      )
      AND (p_partner_id IS NULL OR ptc.partner_id = p_partner_id)
      AND (
        p_technician_user_id IS NULL
        OR ptc.technician_user_id = p_technician_user_id
        OR v_is_tecnico -- técnico sempre restrito a si mesmo, ignora filtro externo
      )
      AND (NOT v_is_tecnico OR ptc.technician_user_id = v_uid)
  ),
  agg AS (
    SELECT l.cliente_id,
           MIN(l.assigned_at) AS assigned_at
    FROM links l
    GROUP BY l.cliente_id
  ),
  sims AS (
    SELECT ps.cliente_id,
           COUNT(*) AS total,
           MAX(ps.created_at) AS ultima
    FROM public.partner_simulations ps
    WHERE ps.cliente_id IS NOT NULL
    GROUP BY ps.cliente_id
  )
  SELECT
    c.id,
    c.nome,
    c.razao_social,
    c.nome_fantasia,
    c.tipo_pessoa,
    CASE
      WHEN c.cpf_cnpj IS NULL THEN NULL
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 11
        THEN '***.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 4, 3) || '.***-**'
      WHEN length(regexp_replace(c.cpf_cnpj, '\D', '', 'g')) = 14
        THEN '**.' || substring(regexp_replace(c.cpf_cnpj, '\D', '', 'g'), 3, 3) || '.***/****-**'
      ELSE '***'
    END,
    c.telefone,
    c.endereco_municipio,
    c.endereco_estado,
    s.ultima,
    COALESCE(s.total, 0),
    a.assigned_at
  FROM agg a
  JOIN public.clientes c ON c.id = a.cliente_id
  LEFT JOIN sims s ON s.cliente_id = c.id
  ORDER BY c.nome NULLS LAST;
END;
$$;


ALTER FUNCTION public.get_b2b_technician_clients_secure(p_partner_id uuid, p_technician_user_id uuid) OWNER TO postgres;

--
-- Name: get_b2b_user_client_detail_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_user_client_detail_secure(p_cliente_id uuid, p_scope text DEFAULT 'meus_produtores'::text) RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, email text, cidade text, estado text, assignment_type text, can_create_simulation boolean, assigned_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_ok boolean := false;
  v_scope text := COALESCE(p_scope, 'meus_produtores');
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;

  IF v_scope NOT IN ('meus_produtores','equipe','admin') THEN
    RAISE EXCEPTION 'invalid scope';
  END IF;

  IF has_role(v_uid,'parceiro_b2b_tecnico'::app_role) THEN
    v_scope := 'meus_produtores';
    v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                   WHERE puc.user_id = v_uid AND puc.cliente_id = p_cliente_id AND puc.active = true);
  ELSIF has_role(v_uid,'parceiro_b2b'::app_role) THEN
    v_partner := get_user_partner_id();
    IF v_scope = 'meus_produtores' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_user_clients puc
                     WHERE puc.user_id = v_uid
                       AND puc.cliente_id = p_cliente_id
                       AND puc.partner_id = v_partner
                       AND puc.active = true);
    ELSIF v_scope = 'equipe' THEN
      v_ok := EXISTS(SELECT 1 FROM public.partner_clients pc
                     WHERE pc.partner_id = v_partner AND pc.cliente_id = p_cliente_id AND pc.active = true);
    END IF;
  ELSIF has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role) THEN
    IF v_scope IN ('admin','equipe') THEN
      v_ok := true;
    END IF;
  END IF;

  IF NOT v_ok THEN RAISE EXCEPTION 'access denied'; END IF;

  RETURN QUERY
  SELECT c.id, c.nome, c.razao_social, c.nome_fantasia, c.tipo_pessoa,
    CASE WHEN c.cpf_cnpj IS NULL THEN NULL
         ELSE repeat('*', greatest(length(c.cpf_cnpj)-4,0)) || right(c.cpf_cnpj,4)
    END,
    c.telefone, c.email,
    c.endereco_municipio, c.endereco_estado,
    (SELECT assignment_type FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT can_create_simulation FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1),
    (SELECT assigned_at FROM public.partner_user_clients puc
      WHERE puc.cliente_id = c.id AND puc.user_id = v_uid AND puc.active = true LIMIT 1)
  FROM public.clientes c
  WHERE c.id = p_cliente_id;
END;
$$;


ALTER FUNCTION public.get_b2b_user_client_detail_secure(p_cliente_id uuid, p_scope text) OWNER TO postgres;

--
-- Name: get_b2b_user_client_simulations_secure(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_user_client_simulations_secure(p_cliente_id uuid) RETURNS TABLE(id uuid, titulo text, status text, total_cheio numeric, created_at timestamp with time zone, created_by uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_partner uuid;
  v_is_admin boolean := has_role(v_uid,'administrador'::app_role) OR has_role(v_uid,'gestor_comercial'::app_role);
  v_is_gest boolean := has_role(v_uid,'parceiro_b2b'::app_role);
  v_is_tec boolean := has_role(v_uid,'parceiro_b2b_tecnico'::app_role);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF NOT (v_is_admin OR v_is_gest OR v_is_tec) THEN RAISE EXCEPTION 'access denied'; END IF;

  IF v_is_admin THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
      ORDER BY s.created_at DESC
      LIMIT 100;
    RETURN;
  END IF;

  v_partner := public.get_user_partner_id();
  IF v_partner IS NULL THEN RAISE EXCEPTION 'partner nao identificado'; END IF;

  -- Cliente precisa estar vinculado ao usuário
  IF NOT EXISTS (
    SELECT 1 FROM public.partner_user_clients
    WHERE partner_id = v_partner
      AND cliente_id = p_cliente_id
      AND user_id = v_uid
      AND active = true
  ) THEN
    RAISE EXCEPTION 'cliente nao vinculado';
  END IF;

  IF v_is_tec THEN
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
        AND s.created_by = v_uid
      ORDER BY s.created_at DESC
      LIMIT 100;
  ELSE
    RETURN QUERY
      SELECT s.id, s.titulo, s.status::text, s.total_cheio, s.created_at, s.created_by
      FROM public.partner_simulations s
      WHERE s.cliente_id = p_cliente_id
        AND s.partner_id = v_partner
      ORDER BY s.created_at DESC
      LIMIT 100;
  END IF;
END;
$$;


ALTER FUNCTION public.get_b2b_user_client_simulations_secure(p_cliente_id uuid) OWNER TO postgres;

--
-- Name: get_b2b_user_clients_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_user_clients_secure(p_user_id uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text) RETURNS TABLE(cliente_id uuid, nome text, razao_social text, nome_fantasia text, tipo_pessoa text, documento_mascarado text, telefone text, cidade text, estado text, assignment_type text, can_create_simulation boolean, can_monitor boolean, assigned_at timestamp with time zone, ultima_simulacao_at timestamp with time zone, total_simulacoes bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid:=public.h15_actor_organization(); BEGIN
IF NOT platform_private.b2b_internal_commercial_actor() THEN RAISE EXCEPTION 'b2b_client_assignments_unavailable' USING ERRCODE='42501'; END IF;
IF p_search IS NOT NULL AND length(p_search)>200 THEN RAISE EXCEPTION 'invalid_search' USING ERRCODE='22023'; END IF;
IF p_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.user_id=p_user_id AND p.organization_id=org AND p.ativo IS TRUE) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
RETURN QUERY SELECT c.id,c.nome,c.razao_social,c.nome_fantasia,c.tipo_pessoa::text,CASE WHEN c.cpf_cnpj IS NULL THEN NULL WHEN length(c.cpf_cnpj)>=4 THEN repeat('*',greatest(length(c.cpf_cnpj)-4,0))||right(c.cpf_cnpj,4) ELSE '****' END,c.telefone,c.endereco_municipio,c.endereco_estado,puc.assignment_type,puc.can_create_simulation,puc.can_monitor,puc.assigned_at,(SELECT max(ps.created_at) FROM public.partner_simulations ps WHERE ps.cliente_id=c.id AND ps.partner_id=puc.partner_id AND ps.created_by=puc.user_id),(SELECT count(*) FROM public.partner_simulations ps WHERE ps.cliente_id=c.id AND ps.partner_id=puc.partner_id AND ps.created_by=puc.user_id) FROM public.partner_user_clients puc JOIN public.clientes c ON c.id=puc.cliente_id JOIN public.partner_accounts pa ON pa.id=puc.partner_id WHERE puc.active IS TRUE AND (p_user_id IS NULL OR puc.user_id=p_user_id) AND c.organization_id=org AND pa.commercial_owner_organization_id=org AND pa.ativo IS TRUE AND pa.deleted_at IS NULL AND platform_private.b2b_assignment_identity_coherent(puc.user_id,puc.partner_id,org) AND (p_search IS NULL OR p_search='' OR coalesce(c.nome,'') ILIKE '%'||p_search||'%' OR coalesce(c.razao_social,'') ILIKE '%'||p_search||'%' OR coalesce(c.nome_fantasia,'') ILIKE '%'||p_search||'%' OR coalesce(c.endereco_municipio,'') ILIKE '%'||p_search||'%'); END $$;


ALTER FUNCTION public.get_b2b_user_clients_secure(p_user_id uuid, p_search text) OWNER TO postgres;

--
-- Name: get_b2b_user_role_for_partner(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_b2b_user_role_for_partner(p_user_id uuid, p_partner_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT CASE WHEN public.is_valid_b2b_partner_user(p_user_id,p_partner_id)
 AND (SELECT count(*) FROM public.user_roles WHERE user_id=p_user_id AND role IN ('parceiro_b2b','parceiro_b2b_tecnico'))=1
 THEN CASE WHEN public.has_role(p_user_id,'parceiro_b2b') THEN 'parceiro_b2b' ELSE 'parceiro_b2b_tecnico' END END;
$$;


ALTER FUNCTION public.get_b2b_user_role_for_partner(p_user_id uuid, p_partner_id uuid) OWNER TO postgres;

--
-- Name: get_cliente_id_for_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cliente_id_for_user(_user_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN NOT public.fn_authz_uid_scope_ok(_user_id) THEN NULL::uuid ELSE (
    SELECT uc.cliente_id
      FROM public.user_clientes uc
     WHERE uc.user_id = _user_id
       AND uc.is_active = true
       AND uc.revoked_at IS NULL
       AND (uc.valid_from IS NULL OR uc.valid_from <= now())
       AND (uc.valid_until IS NULL OR uc.valid_until >= now())
     ORDER BY uc.principal DESC, uc.created_at ASC
     LIMIT 1
  ) END
$$;


ALTER FUNCTION public.get_cliente_id_for_user(_user_id uuid) OWNER TO postgres;

--
-- Name: get_cliente_ids_for_user(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_cliente_ids_for_user(_user_id uuid) RETURNS uuid[]
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN public.fn_authz_uid_scope_ok(_user_id) THEN ARRAY(
    SELECT uc.cliente_id
      FROM public.user_clientes uc
     WHERE uc.user_id = _user_id
       AND uc.is_active = true
       AND uc.revoked_at IS NULL
       AND (uc.valid_from IS NULL OR uc.valid_from <= now())
       AND (uc.valid_until IS NULL OR uc.valid_until >= now())
    UNION
    SELECT pr.cliente_id
      FROM public.profiles pr
     WHERE pr.user_id = _user_id
       AND pr.cliente_id IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM public.user_clientes uc2
          WHERE uc2.user_id = pr.user_id
            AND uc2.cliente_id = pr.cliente_id
            AND uc2.is_active = true
            AND uc2.revoked_at IS NULL
            AND (uc2.valid_from IS NULL OR uc2.valid_from <= now())
            AND (uc2.valid_until IS NULL OR uc2.valid_until >= now())
       )
  ) ELSE ARRAY[]::uuid[] END;
$$;


ALTER FUNCTION public.get_cliente_ids_for_user(_user_id uuid) OWNER TO postgres;

--
-- Name: get_financial_alerts(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_alerts(p_reference_date date DEFAULT CURRENT_DATE) RETURNS TABLE(alert_type text, severity text, title text, description text, amount numeric, count integer, action_key text)
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;

  -- 1 entregas sem faturamento
  RETURN QUERY
  SELECT 'DELIVERIES_PENDING_BILLING'::text, 'CRITICAL'::text,
         'Entregas confirmadas sem faturamento'::text,
         'Existem entregas concluídas que ainda não geraram conta a receber.'::text,
         COALESCE(SUM(e.quantidade_entregue * COALESCE(p.valor_litro_brl,0)),0)::numeric,
         COUNT(*)::int, 'entregas-nao-faturadas'::text
    FROM entregas e LEFT JOIN produtos p ON p.id = e.produto_id
   WHERE e.financial_status = 'PENDING_BILLING' AND e.receivable_id IS NULL
  HAVING COUNT(*) > 0;

  -- 2 recebimentos vencidos
  RETURN QUERY
  SELECT 'OVERDUE_RECEIVABLES'::text, 'CRITICAL'::text,
         'Recebimentos vencidos'::text,
         'Parcelas a receber em atraso.'::text,
         COALESCE(SUM(ari.original_amount - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0)),0)::numeric,
         COUNT(*)::int, 'receber-vencidos'::text
    FROM accounts_receivable_installments ari
   WHERE ari.due_date < p_reference_date AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
  HAVING COUNT(*) > 0;

  -- 3 pagamentos vencidos
  RETURN QUERY
  SELECT 'OVERDUE_PAYABLES'::text, 'CRITICAL'::text,
         'Pagamentos vencidos'::text,
         'Parcelas a pagar em atraso.'::text,
         COALESCE(SUM(api.original_amount - COALESCE(api.paid_amount,0) - COALESCE(api.discount_amount,0)),0)::numeric,
         COUNT(*)::int, 'pagar-vencidos'::text
    FROM accounts_payable_installments api
   WHERE api.due_date < p_reference_date AND api.status IN ('OPEN','PARTIAL','OVERDUE')
  HAVING COUNT(*) > 0;

  -- 4 NF-e pendente
  RETURN QUERY
  SELECT 'PENDING_FISCAL_INVOICE'::text, 'HIGH'::text,
         'NF-e pendente'::text,
         'Contas a receber aguardando emissão de NF-e.'::text,
         COALESCE(SUM(total_amount),0)::numeric, COUNT(*)::int, 'nfe-pendente'::text
    FROM accounts_receivable
   WHERE fiscal_invoice_required = true AND fiscal_invoice_status = 'PENDING'
  HAVING COUNT(*) > 0;

  -- 5 categorias sem DRE
  RETURN QUERY
  SELECT 'UNCLASSIFIED_DRE'::text, 'MEDIUM'::text,
         'Categorias sem classificação DRE'::text,
         'Algumas categorias usadas em títulos não têm grupo DRE definido.'::text,
         0::numeric, COUNT(*)::int, 'categorias-dre'::text
    FROM financial_categories fc
   WHERE fc.dre_group IS NULL
     AND (EXISTS (SELECT 1 FROM accounts_receivable ar WHERE ar.category_id = fc.id)
       OR EXISTS (SELECT 1 FROM accounts_payable ap WHERE ap.category_id = fc.id))
  HAVING COUNT(*) > 0;

  -- 6 recorrências com falha
  RETURN QUERY
  SELECT 'RECURRING_FAILED'::text, 'HIGH'::text,
         'Recorrências com falha'::text,
         'Erros recentes na geração automática de títulos recorrentes.'::text,
         0::numeric, COUNT(*)::int, 'recorrencias'::text
    FROM recurring_generation_log WHERE status = 'FAILED' AND generated_at >= (p_reference_date - INTERVAL '30 days')
  HAVING COUNT(*) > 0;

  -- 7 recorrências atrasadas
  RETURN QUERY
  SELECT 'RECURRING_DUE'::text, 'HIGH'::text,
         'Recorrências atrasadas para geração'::text,
         'Modelos recorrentes ativos com geração pendente.'::text,
         0::numeric, COUNT(*)::int, 'recorrencias'::text
    FROM recurring_financial_templates
   WHERE active = true AND auto_generate = true
     AND next_generation_date IS NOT NULL AND next_generation_date < p_reference_date
  HAVING COUNT(*) > 0;

  -- 8 contas sem centro de custo
  RETURN QUERY
  SELECT 'MISSING_COST_CENTER'::text, 'MEDIUM'::text,
         'Contas sem centro de custo'::text,
         'Títulos financeiros sem centro de custo associado.'::text,
         0::numeric,
         ((SELECT COUNT(*) FROM accounts_receivable WHERE cost_center_id IS NULL AND status <> 'CANCELED')
        + (SELECT COUNT(*) FROM accounts_payable WHERE cost_center_id IS NULL AND status <> 'CANCELED'))::int,
         'centros-custo'::text
   WHERE EXISTS (SELECT 1 FROM accounts_receivable WHERE cost_center_id IS NULL AND status <> 'CANCELED')
      OR EXISTS (SELECT 1 FROM accounts_payable WHERE cost_center_id IS NULL AND status <> 'CANCELED');
END $$;


ALTER FUNCTION public.get_financial_alerts(p_reference_date date) OWNER TO postgres;

--
-- Name: get_financial_cashflow(date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_cashflow(p_start_date date, p_end_date date, p_view_mode text DEFAULT 'PROJECTED'::text, p_group_by text DEFAULT 'DAY'::text) RETURNS TABLE(period_label text, period_start date, expected_inflows numeric, expected_outflows numeric, realized_inflows numeric, realized_outflows numeric, projected_balance numeric, realized_balance numeric, accumulated_projected_balance numeric, accumulated_realized_balance numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trunc text; v_fmt text;
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'Periodo invalido: informe datas inicial e final em ordem.' USING ERRCODE='22023';
  END IF;
  IF p_group_by IS NULL OR upper(p_group_by) NOT IN ('DAY','WEEK','MONTH') THEN
    RAISE EXCEPTION 'Agrupamento invalido.' USING ERRCODE='22023';
  END IF;
  IF p_view_mode IS NULL OR upper(p_view_mode) NOT IN ('PROJECTED','REALIZED','COMPARATIVE') THEN
    RAISE EXCEPTION 'Modo de visualizacao invalido.' USING ERRCODE='22023';
  END IF;
  v_trunc := CASE upper(p_group_by) WHEN 'WEEK' THEN 'week' WHEN 'MONTH' THEN 'month' ELSE 'day' END;
  v_fmt := CASE upper(p_group_by) WHEN 'MONTH' THEN 'MM/YYYY' WHEN 'WEEK' THEN '"Sem" IW/IYYY' ELSE 'DD/MM' END;

  RETURN QUERY
  WITH proj_in AS (
    SELECT date_trunc(v_trunc, ari.due_date)::date b,
           SUM(CASE WHEN ari.status = 'PAID' THEN 0 ELSE GREATEST(0,ari.original_amount + COALESCE(ari.interest_amount,0) + COALESCE(ari.penalty_amount,0) - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0)) END) v
      FROM accounts_receivable_installments ari
     WHERE ari.due_date BETWEEN p_start_date AND p_end_date AND ari.status <> 'CANCELED'
     GROUP BY 1
  ), proj_out AS (
    SELECT date_trunc(v_trunc, api.due_date)::date b,
           SUM(CASE WHEN api.status = 'PAID' THEN 0 ELSE GREATEST(0,api.original_amount + COALESCE(api.interest_amount,0) + COALESCE(api.penalty_amount,0) - COALESCE(api.paid_amount,0) - COALESCE(api.discount_amount,0)) END) v
      FROM accounts_payable_installments api
     WHERE api.due_date BETWEEN p_start_date AND p_end_date AND api.status <> 'CANCELED'
     GROUP BY 1
  ), real_in AS (
    SELECT date_trunc(v_trunc, rp.payment_date)::date b, SUM(rp.amount_received) v
      FROM receivable_payments rp
     WHERE rp.payment_date BETWEEN p_start_date AND p_end_date
     GROUP BY 1
  ), real_out AS (
    SELECT date_trunc(v_trunc, pp.payment_date)::date b, SUM(pp.amount_paid) v
      FROM payable_payments pp
     WHERE pp.payment_date BETWEEN p_start_date AND p_end_date
     GROUP BY 1
  ), buckets AS (
    SELECT b FROM proj_in UNION SELECT b FROM proj_out
    UNION SELECT b FROM real_in UNION SELECT b FROM real_out
  ), combined AS (
    SELECT b.b AS bk,
           COALESCE(pi.v,0)::numeric ei, COALESCE(po.v,0)::numeric eo,
           COALESCE(ri.v,0)::numeric ri_v, COALESCE(ro.v,0)::numeric ro_v
      FROM buckets b
      LEFT JOIN proj_in pi ON pi.b = b.b
      LEFT JOIN proj_out po ON po.b = b.b
      LEFT JOIN real_in ri ON ri.b = b.b
      LEFT JOIN real_out ro ON ro.b = b.b
  )
  SELECT to_char(bk, v_fmt),
         bk,
         CASE WHEN upper(p_view_mode)='REALIZED' THEN 0 ELSE ei END,
         CASE WHEN upper(p_view_mode)='REALIZED' THEN 0 ELSE eo END,
         CASE WHEN upper(p_view_mode)='PROJECTED' THEN 0 ELSE ri_v END,
         CASE WHEN upper(p_view_mode)='PROJECTED' THEN 0 ELSE ro_v END,
         (ei - eo)::numeric,
         (ri_v - ro_v)::numeric,
         SUM(ei - eo) OVER (ORDER BY bk)::numeric,
         SUM(ri_v - ro_v) OVER (ORDER BY bk)::numeric
    FROM combined
   ORDER BY bk;
END $$;


ALTER FUNCTION public.get_financial_cashflow(p_start_date date, p_end_date date, p_view_mode text, p_group_by text) OWNER TO postgres;

--
-- Name: get_financial_dashboard_summary(date, date, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_dashboard_summary(p_start_date date, p_end_date date, p_cost_center_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  r jsonb;
  v_rec_expected numeric := 0; v_rec_received numeric := 0;
  v_rec_open numeric := 0; v_rec_overdue numeric := 0; v_rec_partial numeric := 0;
  v_rec_overdue_count int := 0; v_rec_avg_days int := 0;
  v_pay_expected numeric := 0; v_pay_paid numeric := 0;
  v_pay_open numeric := 0; v_pay_overdue numeric := 0; v_pay_partial numeric := 0;
  v_pay_overdue_count int := 0;
  v_nfe_count int := 0; v_nfe_amount numeric := 0;
  v_deliv_count int := 0; v_deliv_amount numeric := 0;
  v_rec_recurring numeric := 0; v_pay_recurring numeric := 0;
  v_rec_errors int := 0;
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION 'Periodo invalido: informe datas inicial e final em ordem.' USING ERRCODE = '22023';
  END IF;

  -- A receber (previsto: pelo vencimento no período)
  SELECT COALESCE(SUM(ari.original_amount),0),
         COALESCE(SUM(ari.original_amount - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0))
           FILTER (WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE')),0),
         COALESCE(SUM(ari.original_amount - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0))
           FILTER (WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date),0),
         COALESCE(SUM(ari.original_amount - COALESCE(ari.received_amount,0) - COALESCE(ari.discount_amount,0))
           FILTER (WHERE ari.status = 'PARTIAL'),0),
         COUNT(*) FILTER (WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date)::int,
         COALESCE(AVG((pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - ari.due_date)
           FILTER (WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date),0)::int
    INTO v_rec_expected, v_rec_open, v_rec_overdue, v_rec_partial, v_rec_overdue_count, v_rec_avg_days
    FROM accounts_receivable_installments ari
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
   WHERE ari.due_date BETWEEN p_start_date AND p_end_date
     AND ari.status <> 'CANCELED'
     AND (p_customer_id IS NULL OR ar.customer_id = p_customer_id)
     AND (p_category_id IS NULL OR ar.category_id = p_category_id)
     AND (p_cost_center_id IS NULL OR ar.cost_center_id = p_cost_center_id);

  -- A receber (realizado: por payment_date)
  SELECT COALESCE(SUM(rp.amount_received),0)
    INTO v_rec_received
    FROM receivable_payments rp
    JOIN accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN accounts_receivable ar ON ar.id = ari.receivable_id
   WHERE rp.payment_date BETWEEN p_start_date AND p_end_date
     AND (p_customer_id IS NULL OR ar.customer_id = p_customer_id)
     AND (p_category_id IS NULL OR ar.category_id = p_category_id)
     AND (p_cost_center_id IS NULL OR ar.cost_center_id = p_cost_center_id);

  -- A pagar (previsto)
  SELECT COALESCE(SUM(api.original_amount),0),
         COALESCE(SUM(api.original_amount - COALESCE(api.paid_amount,0) - COALESCE(api.discount_amount,0))
           FILTER (WHERE api.status IN ('OPEN','PARTIAL','OVERDUE')),0),
         COALESCE(SUM(api.original_amount - COALESCE(api.paid_amount,0) - COALESCE(api.discount_amount,0))
           FILTER (WHERE api.status IN ('OPEN','PARTIAL','OVERDUE') AND api.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date),0),
         COALESCE(SUM(api.original_amount - COALESCE(api.paid_amount,0) - COALESCE(api.discount_amount,0))
           FILTER (WHERE api.status = 'PARTIAL'),0),
         COUNT(*) FILTER (WHERE api.status IN ('OPEN','PARTIAL','OVERDUE') AND api.due_date < (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date)::int
    INTO v_pay_expected, v_pay_open, v_pay_overdue, v_pay_partial, v_pay_overdue_count
    FROM accounts_payable_installments api
    JOIN accounts_payable ap ON ap.id = api.payable_id
   WHERE api.due_date BETWEEN p_start_date AND p_end_date
     AND api.status <> 'CANCELED'
     AND (p_category_id IS NULL OR ap.category_id = p_category_id)
     AND (p_cost_center_id IS NULL OR ap.cost_center_id = p_cost_center_id);

  -- A pagar (realizado)
  SELECT COALESCE(SUM(pp.amount_paid),0)
    INTO v_pay_paid
    FROM payable_payments pp
    JOIN accounts_payable_installments api ON api.id = pp.installment_id
    JOIN accounts_payable ap ON ap.id = api.payable_id
   WHERE pp.payment_date BETWEEN p_start_date AND p_end_date
     AND (p_category_id IS NULL OR ap.category_id = p_category_id)
     AND (p_cost_center_id IS NULL OR ap.cost_center_id = p_cost_center_id);

  -- NF-e pendente
  SELECT COUNT(*)::int, COALESCE(SUM(total_amount),0)
    INTO v_nfe_count, v_nfe_amount
    FROM accounts_receivable
   WHERE fiscal_invoice_required = true
     AND fiscal_invoice_status = 'PENDING';

  -- Entregas pendentes faturamento
  SELECT COUNT(*)::int, COALESCE(SUM(e.quantidade_entregue * COALESCE(p.valor_litro_brl,0)),0)
    INTO v_deliv_count, v_deliv_amount
    FROM entregas e LEFT JOIN produtos p ON p.id = e.produto_id
   WHERE e.financial_status = 'PENDING_BILLING' AND e.receivable_id IS NULL;

  -- Recorrências ativas
  SELECT COALESCE(SUM(amount) FILTER (WHERE type='RECEIVABLE'),0),
         COALESCE(SUM(amount) FILTER (WHERE type='PAYABLE'),0)
    INTO v_rec_recurring, v_pay_recurring
    FROM recurring_financial_templates
   WHERE active = true;

  SELECT COUNT(*)::int INTO v_rec_errors
    FROM recurring_generation_log WHERE status = 'FAILED' AND generated_at >= ((pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date - INTERVAL '30 days');

  r := jsonb_build_object(
    'total_receivable_expected', v_rec_expected,
    'total_receivable_received', v_rec_received,
    'total_receivable_open', v_rec_open,
    'total_receivable_overdue', v_rec_overdue,
    'total_receivable_partial', v_rec_partial,
    'overdue_receivables_count', v_rec_overdue_count,
    'average_days_overdue', v_rec_avg_days,
    'total_payable_expected', v_pay_expected,
    'total_payable_paid', v_pay_paid,
    'total_payable_open', v_pay_open,
    'total_payable_overdue', v_pay_overdue,
    'total_payable_partial', v_pay_partial,
    'overdue_payables_count', v_pay_overdue_count,
    'projected_balance', v_rec_expected - v_pay_expected,
    'realized_balance', v_rec_received - v_pay_paid,
    'collection_rate', CASE WHEN v_rec_expected > 0 THEN ROUND((v_rec_received / v_rec_expected)::numeric, 4) ELSE 0 END,
    'payment_rate', CASE WHEN v_pay_expected > 0 THEN ROUND((v_pay_paid / v_pay_expected)::numeric, 4) ELSE 0 END,
    'pending_fiscal_invoice_count', v_nfe_count,
    'pending_fiscal_invoice_amount', v_nfe_amount,
    'pending_billing_deliveries_count', v_deliv_count,
    'pending_billing_deliveries_amount', v_deliv_amount,
    'active_recurring_receivables_amount', v_rec_recurring,
    'active_recurring_payables_amount', v_pay_recurring,
    'recurring_net_balance', v_rec_recurring - v_pay_recurring,
    'recurring_generation_errors_count', v_rec_errors
  );
  RETURN r;
END $$;


ALTER FUNCTION public.get_financial_dashboard_summary(p_start_date date, p_end_date date, p_cost_center_id uuid, p_category_id uuid, p_customer_id uuid) OWNER TO postgres;

--
-- Name: get_financial_dre_summary(date, date, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_dre_summary(p_start_date date, p_end_date date, p_regime text DEFAULT 'CASH'::text, p_cost_center_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb; g RECORD;
  v_groups jsonb := '{}'::jsonb;
  v_unclassified jsonb := '[]'::jsonb;
  v_receita numeric := 0; v_deducoes numeric := 0;
  v_resultado numeric := 0; v_margem numeric := 0;
BEGIN
  IF NOT public.is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;

  IF p_start_date IS NULL OR p_end_date IS NULL OR p_start_date > p_end_date THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Período inválido';
  END IF;
  IF p_regime IS NULL OR upper(p_regime) NOT IN ('CASH','ACCRUAL') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Regime inválido';
  END IF;

  IF upper(p_regime) = 'ACCRUAL' THEN
    FOR g IN
      SELECT COALESCE(fc.dre_group,'SEM_CLASSIFICACAO') AS grp, SUM(ari.original_amount) AS total, COUNT(*) AS qtd
        FROM accounts_receivable_installments ari
        JOIN accounts_receivable ar ON ar.id = ari.receivable_id
        LEFT JOIN financial_categories fc ON fc.id = ar.category_id
       WHERE ari.due_date BETWEEN p_start_date AND p_end_date AND ari.status <> 'CANCELED'
         AND (p_cost_center_id IS NULL OR ar.cost_center_id = p_cost_center_id)
       GROUP BY 1
    LOOP v_groups := v_groups || jsonb_build_object(lower(g.grp), jsonb_build_object('total', g.total, 'qtd', g.qtd)); END LOOP;
    FOR g IN
      SELECT COALESCE(fc.dre_group,'SEM_CLASSIFICACAO') AS grp, SUM(api.original_amount) AS total, COUNT(*) AS qtd
        FROM accounts_payable_installments api
        JOIN accounts_payable ap ON ap.id = api.payable_id
        LEFT JOIN financial_categories fc ON fc.id = ap.category_id
       WHERE api.due_date BETWEEN p_start_date AND p_end_date AND api.status <> 'CANCELED'
         AND (p_cost_center_id IS NULL OR ap.cost_center_id = p_cost_center_id)
       GROUP BY 1
    LOOP
      v_groups := v_groups || jsonb_build_object(lower(g.grp),
        COALESCE(v_groups->lower(g.grp),'{}'::jsonb) || jsonb_build_object('total',
          COALESCE((v_groups->lower(g.grp)->>'total')::numeric,0) + g.total, 'qtd',
          COALESCE((v_groups->lower(g.grp)->>'qtd')::int,0) + g.qtd::int));
    END LOOP;
  ELSE
    -- CASH: NÃO filtrar is_reversal. O estorno tem valor negativo e cancela o pagamento original na soma.
    FOR g IN
      SELECT COALESCE(fc.dre_group,'SEM_CLASSIFICACAO') AS grp, SUM(rp.amount_received) AS total,
             COUNT(*) FILTER (WHERE COALESCE(rp.is_reversal,false) = false) AS qtd
        FROM receivable_payments rp
        JOIN accounts_receivable_installments ari ON ari.id = rp.installment_id
        JOIN accounts_receivable ar ON ar.id = ari.receivable_id
        LEFT JOIN financial_categories fc ON fc.id = ar.category_id
       WHERE rp.payment_date BETWEEN p_start_date AND p_end_date
         AND (p_cost_center_id IS NULL OR ar.cost_center_id = p_cost_center_id)
       GROUP BY 1
    LOOP v_groups := v_groups || jsonb_build_object(lower(g.grp), jsonb_build_object('total', g.total, 'qtd', g.qtd)); END LOOP;
    FOR g IN
      SELECT COALESCE(fc.dre_group,'SEM_CLASSIFICACAO') AS grp, SUM(pp.amount_paid) AS total,
             COUNT(*) FILTER (WHERE COALESCE(pp.is_reversal,false) = false) AS qtd
        FROM payable_payments pp
        JOIN accounts_payable_installments api ON api.id = pp.installment_id
        JOIN accounts_payable ap ON ap.id = api.payable_id
        LEFT JOIN financial_categories fc ON fc.id = ap.category_id
       WHERE pp.payment_date BETWEEN p_start_date AND p_end_date
         AND (p_cost_center_id IS NULL OR ap.cost_center_id = p_cost_center_id)
       GROUP BY 1
    LOOP
      v_groups := v_groups || jsonb_build_object(lower(g.grp),
        COALESCE(v_groups->lower(g.grp),'{}'::jsonb) || jsonb_build_object('total',
          COALESCE((v_groups->lower(g.grp)->>'total')::numeric,0) + g.total, 'qtd',
          COALESCE((v_groups->lower(g.grp)->>'qtd')::int,0) + g.qtd::int));
    END LOOP;
  END IF;

  SELECT jsonb_agg(jsonb_build_object('id', id, 'name', name))
    INTO v_unclassified
    FROM financial_categories WHERE dre_group IS NULL AND active = true;

  v_receita := COALESCE((v_groups->'receita_bruta'->>'total')::numeric,0)
             + COALESCE((v_groups->'outras_receitas'->>'total')::numeric,0);
  v_deducoes := COALESCE((v_groups->'deducoes'->>'total')::numeric,0)
              + COALESCE((v_groups->'custo_producao'->>'total')::numeric,0)
              + COALESCE((v_groups->'despesa_variavel'->>'total')::numeric,0)
              + COALESCE((v_groups->'despesa_fixa'->>'total')::numeric,0)
              + COALESCE((v_groups->'despesa_administrativa'->>'total')::numeric,0)
              + COALESCE((v_groups->'despesa_comercial'->>'total')::numeric,0)
              + COALESCE((v_groups->'despesa_financeira'->>'total')::numeric,0)
              + COALESCE((v_groups->'impostos'->>'total')::numeric,0)
              + COALESCE((v_groups->'outras_despesas'->>'total')::numeric,0);
  v_resultado := v_receita - v_deducoes;
  v_margem := CASE WHEN v_receita > 0 THEN (v_resultado / v_receita) * 100 ELSE 0 END;

  r := v_groups
    || jsonb_build_object('resultado_operacional', v_resultado,
                          'margem_operacional_percentual', v_margem,
                          'unclassified_categories', COALESCE(v_unclassified, '[]'::jsonb));
  RETURN r;
END $$;


ALTER FUNCTION public.get_financial_dre_summary(p_start_date date, p_end_date date, p_regime text, p_cost_center_id uuid) OWNER TO postgres;

--
-- Name: get_financial_report_data(text, date, date, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_financial_report_data(p_report_type text, p_start_date date, p_end_date date, p_customer_id uuid DEFAULT NULL::uuid, p_category_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_regime text DEFAULT 'CASH'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_filters jsonb; v_rows jsonb; v_summary jsonb;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  IF p_start_date IS NULL OR p_end_date IS NULL THEN
    RAISE EXCEPTION 'Datas inicial e final são obrigatórias'; END IF;
  IF p_end_date < p_start_date THEN
    RAISE EXCEPTION 'Data final não pode ser menor que data inicial'; END IF;
  v_filters := jsonb_build_object(
    'start_date', p_start_date, 'end_date', p_end_date,
    'customer_id', p_customer_id, 'category_id', p_category_id,
    'cost_center_id', p_cost_center_id, 'status', p_status, 'regime', p_regime
  );
  CASE upper(p_report_type)
    WHEN 'MONTHLY_FINANCIAL' THEN
      v_summary := get_report_monthly_financial(p_start_date, p_end_date, p_cost_center_id, p_regime);
    WHEN 'ACCOUNTS_RECEIVABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_receivables(v_filters) t;
    WHEN 'ACCOUNTS_PAYABLE' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_payables(v_filters) t;
    WHEN 'CASHFLOW' THEN
      v_summary := get_financial_cashflow(p_start_date, p_end_date, 'PROJECTED', 'DAY');
    WHEN 'DRE' THEN
      v_summary := get_financial_dre_summary(p_start_date, p_end_date, p_regime, p_cost_center_id);
    WHEN 'INADIMPLENCIA' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_delinquency(p_end_date) t;
    WHEN 'FISCAL_PENDING' THEN
      SELECT jsonb_agg(to_jsonb(t)) INTO v_rows FROM get_report_nfe_pending(v_filters) t;
    WHEN 'DELIVERY_BILLING' THEN
      v_summary := (SELECT to_jsonb(x) FROM get_report_deliveries_billing_status(p_start_date, p_end_date) x);
    WHEN 'CUSTOMER_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para extrato'; END IF;
      v_summary := get_report_customer_statement(p_customer_id, p_start_date, p_end_date);
    WHEN 'ACCOUNTABILITY_STATEMENT' THEN
      IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Cliente é obrigatório para prestação de contas'; END IF;
      v_summary := get_report_accountability(jsonb_build_object(
        'customer_id', p_customer_id, 'from', p_start_date, 'to', p_end_date));
    ELSE RAISE EXCEPTION 'Tipo de relatório inválido: %', p_report_type;
  END CASE;
  PERFORM log_report_view(p_report_type, v_filters);
  RETURN jsonb_build_object(
    'report_type', p_report_type, 'filters', v_filters,
    'summary', COALESCE(v_summary, '{}'::jsonb),
    'rows', COALESCE(v_rows, '[]'::jsonb),
    'generated_at', now()
  );
END$$;


ALTER FUNCTION public.get_financial_report_data(p_report_type text, p_start_date date, p_end_date date, p_customer_id uuid, p_category_id uuid, p_cost_center_id uuid, p_status text, p_regime text) OWNER TO postgres;

--
-- Name: get_my_available_portal_contexts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_my_available_portal_contexts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE u uuid:=auth.uid(); org uuid; management boolean:=false; tech boolean:=false; partner boolean:=false; scopes record; contexts text[]:=ARRAY[]::text[]; pref text; last_ctx text; skip boolean:=false; def text;
BEGIN
 IF u IS NULL OR NOT platform_private.platform_actor_access_ready(u) THEN
  RETURN jsonb_build_object('available_contexts',contexts,'default_context',NULL,'must_select_context',false,'has_b2b_access',false,'has_technical_access',false,'is_admin',false,'preferred_context',NULL,'skip_context_selector',false);
 END IF;
 org:=public.h15_actor_organization();
 IF org IS NULL THEN RETURN jsonb_build_object('available_contexts',contexts,'default_context',NULL,'must_select_context',false,'has_b2b_access',false,'has_technical_access',false,'is_admin',false,'preferred_context',NULL,'skip_context_selector',false); END IF;
 SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role IN ('administrador','gestor')),
 EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=u AND r.role IN ('tecnico_agronomo','consultor_tecnico','aplicador')) INTO management,tech;
 partner:=platform_private.b2b_commercial_context() IS NOT NULL;
 IF management THEN contexts:=array_append(contexts,'admin'); END IF;
 IF partner AND public.has_role(u,'parceiro_b2b') THEN contexts:=array_append(contexts,'b2b'); END IF;
 IF partner AND public.has_role(u,'parceiro_b2b_tecnico') THEN tech:=true; END IF;
 IF public.has_role(u,'cliente_produtor') AND platform_private.c2_producer_links(u,org) THEN contexts:=array_append(contexts,'producer'); END IF;
 IF tech THEN contexts:=array_append(contexts,'technical'); END IF;
 SELECT preferred_context,last_context,skip_context_selector INTO pref,last_ctx,skip FROM public.user_access_preferences WHERE user_id=u;
 IF pref IS NOT NULL AND pref=ANY(contexts) THEN def:=pref;
 ELSIF last_ctx IS NOT NULL AND last_ctx=ANY(contexts) THEN def:=last_ctx;
 ELSIF cardinality(contexts)=1 THEN def:=contexts[1]; END IF;
 IF pref IS NULL OR NOT(pref=ANY(contexts)) THEN pref:=NULL; skip:=false; END IF;
 RETURN jsonb_build_object('contract','C2_MULTIPROFILE_V1','actor_id',u,'tenant_id',org,'partner_id',(platform_private.b2b_commercial_context()->>'partner_id')::uuid,'ready',true,'profile_stamp',(SELECT updated_at FROM public.profiles WHERE user_id=u),'link_version',(SELECT version FROM public.partner_users WHERE user_id=u),'producer_links_valid',platform_private.c2_producer_links(u,org),'available_contexts',contexts,'default_context',def,'must_select_context',cardinality(contexts)>1 AND NOT COALESCE(skip,false),
 'has_b2b_access',management OR (partner AND public.has_role(u,'parceiro_b2b')),'has_technical_access',management OR tech,'is_admin',management,
 'preferred_context',pref,'skip_context_selector',COALESCE(skip,false));
END $$;


ALTER FUNCTION public.get_my_available_portal_contexts() OWNER TO postgres;

