--
-- Name: insert_partner_catalog_access_log_internal(text, uuid, uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_partner_catalog_access_log_internal(p_action text, p_partner_id uuid, p_user_id uuid, p_cliente_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_id uuid;
  v_allowed text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'user_id obrigatório'; END IF;
  IF NOT (p_action = ANY(v_allowed)) THEN
    RAISE EXCEPTION 'action inválida: %', p_action;
  END IF;
  SELECT role::text INTO v_role FROM public.user_roles WHERE user_id = p_user_id LIMIT 1;
  INSERT INTO public.partner_catalog_access_logs
    (user_id, role, action, partner_id, cliente_id, simulation_id, order_id, target_user_id, details)
  VALUES
    (p_user_id, v_role, p_action, p_partner_id, p_cliente_id, p_simulation_id, p_order_id, p_target_user_id, COALESCE(p_details,'{}'::jsonb))
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.insert_partner_catalog_access_log_internal(p_action text, p_partner_id uuid, p_user_id uuid, p_cliente_id uuid, p_simulation_id uuid, p_order_id uuid, p_target_user_id uuid, p_details jsonb) OWNER TO postgres;

