--
-- Name: jsonb_get_array_safe(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.jsonb_get_array_safe(p_payload jsonb, p_key text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  IF p_payload IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;
  IF jsonb_typeof(p_payload) = 'array' THEN
    RETURN p_payload;
  END IF;
  IF jsonb_typeof(p_payload) = 'object' AND p_key IS NOT NULL THEN
    v := p_payload -> p_key;
    IF v IS NOT NULL AND jsonb_typeof(v) = 'array' THEN
      RETURN v;
    END IF;
  END IF;
  RETURN '[]'::jsonb;
END;
$$;


ALTER FUNCTION public.jsonb_get_array_safe(p_payload jsonb, p_key text) OWNER TO postgres;

--
-- Name: jsonb_object_keys_count(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.jsonb_object_keys_count(p jsonb) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE
           WHEN p IS NULL OR jsonb_typeof(p) <> 'object' THEN 0
           ELSE COALESCE((SELECT count(*)::int FROM jsonb_object_keys(p)), 0)
         END;
$$;


