--
-- Name: log_partner_catalog_access_secure(text, text, uuid, uuid, uuid, uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_partner_catalog_access_secure(p_action text, p_item_tipo text DEFAULT NULL::text, p_item_id uuid DEFAULT NULL::uuid, p_cliente_id uuid DEFAULT NULL::uuid, p_simulation_id uuid DEFAULT NULL::uuid, p_order_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb, p_partner_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_partner_id uuid;
  v_role text;
  v_log_id uuid;
  v_details jsonb;
  v_allowed_actions text[] := ARRAY[
    'b2b_user_client_assigned','b2b_user_client_unassigned','producer_view',
    'catalog_view','item_view','ficha_view','ficha_download',
    'simulation_created','simulation_sent_to_manager','simulation_archived',
    'simulation_converted_to_order'
  ];
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado';
  END IF;

  IF NOT (p_action = ANY(v_allowed_actions)) THEN
    RAISE EXCEPTION 'Ação de log inválida: %', p_action;
  END IF;

  IF has_role(v_uid, 'administrador') THEN
    v_role := 'administrador';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'gestor_comercial') THEN
    v_role := 'gestor_comercial';
    v_partner_id := p_partner_id;
  ELSIF has_role(v_uid, 'parceiro_b2b') THEN
    v_role := 'parceiro_b2b';
    v_partner_id := get_user_partner_id();
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') THEN
    v_role := 'parceiro_b2b_tecnico';
    v_partner_id := get_user_partner_id();
  ELSE
    RAISE EXCEPTION 'Sem permissão para registrar log B2B';
  END IF;

  v_details := COALESCE(p_details, '{}'::jsonb);
  IF p_item_tipo IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_tipo', p_item_tipo);
  END IF;
  IF p_item_id IS NOT NULL THEN
    v_details := v_details || jsonb_build_object('item_id', p_item_id);
  END IF;

  INSERT INTO partner_catalog_access_logs (
    user_id, role, action, partner_id, cliente_id,
    simulation_id, order_id, target_user_id, details
  ) VALUES (
    v_uid, v_role, p_action, v_partner_id, p_cliente_id,
    p_simulation_id, p_order_id, p_target_user_id, v_details
  ) RETURNING id INTO v_log_id;

  RETURN v_log_id;
END;
$$;


ALTER FUNCTION public.log_partner_catalog_access_secure(p_action text, p_item_tipo text, p_item_id uuid, p_cliente_id uuid, p_simulation_id uuid, p_order_id uuid, p_target_user_id uuid, p_details jsonb, p_partner_id uuid) OWNER TO postgres;

--
-- Name: log_report_export(text, jsonb, text, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.log_report_export(_report_type text, _filters jsonb, _format text, _storage_bucket text, _storage_path text, _status text DEFAULT 'SUCCESS'::text, _error text DEFAULT NULL::text, _row_count integer DEFAULT NULL::integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT is_financial_staff(auth.uid()) THEN RAISE EXCEPTION 'Acesso negado'; END IF;
  INSERT INTO financial_report_exports(report_type, filters, format, storage_bucket, storage_path, status, error_message, row_count, generated_by)
  VALUES (_report_type, _filters, _format, _storage_bucket, _storage_path, _status, _error, _row_count, auth.uid())
  RETURNING id INTO v_id;

  INSERT INTO financial_audit_log(entity_type, entity_id, action, new_data, performed_by)
  VALUES ('financial_report_exports', v_id, 'FINANCIAL_REPORT_EXPORTED',
          jsonb_build_object('report_type', _report_type, 'format', _format, 'status', _status), auth.uid());
  RETURN v_id;
END;$$;


ALTER FUNCTION public.log_report_export(_report_type text, _filters jsonb, _format text, _storage_bucket text, _storage_path text, _status text, _error text, _row_count integer) OWNER TO postgres;

