-- Name: lote_volume_envasado(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lote_volume_envasado(_lote_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
