--
-- Name: notify_consultor_atribuido_op(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_consultor_atribuido_op() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente_nome text;
BEGIN
  IF NEW.consultor_atribuido IS NULL THEN
    RETURN NEW;
  END IF;

  IF (TG_OP = 'INSERT')
     OR (TG_OP = 'UPDATE' AND COALESCE(OLD.consultor_atribuido::text,'') IS DISTINCT FROM NEW.consultor_atribuido::text) THEN

    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;

    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    VALUES (
      NEW.consultor_atribuido,
      CASE WHEN NEW.urgencia = 'critica' THEN 'urgencia_critica' ELSE 'nova_solicitacao' END,
      CASE WHEN NEW.urgencia = 'critica' THEN 'Solicitação CRÍTICA atribuída' ELSE 'Nova solicitação atribuída' END,
      'Cliente ' || COALESCE(v_cliente_nome,'') || ' — ' || COALESCE(NEW.tipo_demanda,''),
      '/solicitacoes?id=' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_consultor_atribuido_op() OWNER TO postgres;

--
-- Name: notify_consultor_on_confirmacao_produtor(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_consultor_on_confirmacao_produtor() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_cliente_nome text;
BEGIN
  -- Só dispara se for um retorno técnico e o status de confirmação mudou
  IF NEW.tipo_demanda = 'retorno_tecnico' AND OLD.confirmacao_produtor IS DISTINCT FROM NEW.confirmacao_produtor THEN
    
    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;

    INSERT INTO public.notificacoes_operacionais (usuario_id, tipo, titulo, mensagem, link)
    VALUES (
      NEW.consultor_atribuido,
      'confirmacao_retorno',
      CASE 
        WHEN NEW.confirmacao_produtor = 'confirmada' THEN 'Retorno confirmado pelo produtor'
        WHEN NEW.confirmacao_produtor = 'remarcacao_solicitada' THEN 'Remarcação solicitada pelo produtor'
        ELSE 'Status de retorno alterado'
      END,
      'Cliente ' || COALESCE(v_cliente_nome,'') || ' — ' || 
      CASE 
        WHEN NEW.confirmacao_produtor = 'confirmada' THEN 'confirmou a visita para ' || to_char(NEW.data_prevista_atendimento, 'DD/MM')
        WHEN NEW.confirmacao_produtor = 'remarcacao_solicitada' THEN 'pediu para remarcar a visita de ' || to_char(NEW.data_prevista_atendimento, 'DD/MM')
        ELSE 'atualizou o status'
      END,
      '/agenda-tecnica?id=' || NEW.id::text
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_consultor_on_confirmacao_produtor() OWNER TO postgres;

--
-- Name: notify_managers_on_simulation_sent(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_managers_on_simulation_sent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_manager uuid;
BEGIN
  IF NEW.status = 'enviada_gestor'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN
    FOR v_manager IN
      SELECT DISTINCT pu.user_id
      FROM public.partner_users pu
      JOIN public.user_roles ur ON ur.user_id = pu.user_id
      WHERE pu.partner_id = NEW.partner_id
        AND ur.role IN ('parceiro_b2b','administrador','gestor_comercial')
        AND pu.user_id <> NEW.created_by
    LOOP
      INSERT INTO public.notificacoes_operacionais (
        usuario_id, tipo, titulo, mensagem, link
      ) VALUES (
        v_manager,
        'simulacao_enviada',
        'Nova simulação enviada',
        COALESCE('Simulação: ' || NEW.titulo, 'Uma simulação técnica foi enviada para revisão.'),
        '/portal-parceiro/simulacoes-equipe'
      );
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_managers_on_simulation_sent() OWNER TO postgres;

--
-- Name: notify_solicitacao_atribuida(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_solicitacao_atribuida() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tipo TEXT;
  v_cliente_nome TEXT;
BEGIN
  -- Only notify on transition to 'atribuida' or when consultor_atribuido changes
  IF (TG_OP = 'UPDATE' AND OLD.consultor_atribuido IS DISTINCT FROM NEW.consultor_atribuido AND NEW.consultor_atribuido IS NOT NULL)
     OR (TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'checkin_realizado') THEN

    SELECT nome INTO v_cliente_nome FROM public.clientes WHERE id = NEW.cliente_id;

    -- Notify the client portal
    IF NEW.status = 'checkin_realizado' THEN
      INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
      VALUES (
        NEW.cliente_id,
        'Consultor chegou na sua área',
        COALESCE('Atendimento de "' || NEW.tipo_demanda || '" — check-in realizado.', 'Check-in realizado.'),
        'informativo'
      );
    ELSIF NEW.status = 'atribuida' OR (OLD.consultor_atribuido IS NULL AND NEW.consultor_atribuido IS NOT NULL) THEN
      INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
      VALUES (
        NEW.cliente_id,
        'Sua solicitação foi atribuída',
        'Um consultor técnico foi designado para a sua solicitação "' || NEW.tipo_demanda || '".',
        'informativo'
      );
    END IF;
  END IF;

  -- Notify on creation
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
    VALUES (
      NEW.cliente_id,
      'Solicitação recebida',
      'Sua solicitação "' || NEW.tipo_demanda || '" foi registrada e está em triagem.',
      'informativo'
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_solicitacao_atribuida() OWNER TO postgres;

--
-- Name: notify_visita_finalizada(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.notify_visita_finalizada() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.status IS DISTINCT FROM NEW.status
     AND NEW.status = 'finalizado'
     AND NEW.cliente_id IS NOT NULL THEN

    INSERT INTO public.portal_notificacoes (cliente_id, titulo, mensagem, tipo)
    VALUES (
      NEW.cliente_id,
      'Visita técnica concluída',
      'Sua visita técnica foi finalizada. ' || COALESCE('Problema identificado: ' || NEW.problema_principal, 'Confira os detalhes no portal.'),
      'informativo'
    );

    -- If linked to a solicitation, advance its status
    IF NEW.solicitacao_id IS NOT NULL THEN
      UPDATE public.portal_solicitacoes
      SET status = 'aguardando_recomendacao', updated_at = now()
      WHERE id = NEW.solicitacao_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.notify_visita_finalizada() OWNER TO postgres;

--
-- Name: ofo_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ofo_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'override_imutavel: exceções não podem ser apagadas';
  end if;
  if old.ended_at is not null then
    raise exception 'override_imutavel: exceção já encerrada';
  end if;
  if new.organization_id <> old.organization_id or new.feature_id <> old.feature_id
     or new.mode <> old.mode or new.limit_value is distinct from old.limit_value
     or new.starts_at <> old.starts_at or new.ends_at is distinct from old.ends_at
     or new.reason <> old.reason or new.created_by is distinct from old.created_by
     or new.created_at <> old.created_at or new.ended_at is null then
    raise exception 'override_imutavel: somente encerramento é permitido';
  end if;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION public.ofo_guard() OWNER TO postgres;

