-- Name: ofo_stamp_author(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ofo_stamp_author() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.created_by := auth.uid();
  new.ended_at := null; new.ended_by := null; new.end_reason := null;
  new.created_at := now(); new.updated_at := now();
  return new;
end $$;


