--
-- Name: organizations_guard_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.organizations_guard_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE via_api boolean := session_user = 'authenticator';
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.id <> OLD.id THEN
    RAISE EXCEPTION 'org_invalid: id imutável' USING errcode='42501'; END IF;
  IF NOT via_api THEN RETURN NEW; END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT platform_private.has_ticket('org_create', '00000000-0000-0000-0000-000000000000'::uuid) THEN
      RAISE EXCEPTION 'org_forbidden: criação apenas via plataforma' USING errcode='42501'; END IF;
    RETURN NEW;
  END IF;
  IF (NEW.status, NEW.razao_social, NEW.nome_fantasia, NEW.cnpj, NEW.cnpj_normalizado, NEW.email_corporativo,
      NEW.fuso_horario, NEW.onboarding_dados, NEW.onboarding_concluido_em, NEW.ativada_em, NEW.nome)
     IS DISTINCT FROM
     (OLD.status, OLD.razao_social, OLD.nome_fantasia, OLD.cnpj, OLD.cnpj_normalizado, OLD.email_corporativo,
      OLD.fuso_horario, OLD.onboarding_dados, OLD.onboarding_concluido_em, OLD.ativada_em, OLD.nome)
     AND NOT platform_private.has_ticket('org_write', NEW.id) THEN
    RAISE EXCEPTION 'org_forbidden: alteração apenas via fluxo do servidor' USING errcode='42501';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.organizations_guard_status() OWNER TO postgres;

--
-- Name: partner_apply_default_discount(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_apply_default_discount(p_partner_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_desc numeric(5,2);
  v_count integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT desconto_padrao INTO v_desc FROM public.partner_accounts WHERE id = p_partner_id AND ativo IS TRUE AND deleted_at IS NULL FOR UPDATE;
  IF v_desc IS NULL THEN RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501'; END IF;

  INSERT INTO public.partner_product_prices(partner_id, product_id, preco_tabela, desconto_percentual, preco_final, ativo)
  SELECT p_partner_id, p.id,
         COALESCE(p.valor_ha_brl, 0),
         v_desc,
         ROUND(COALESCE(p.valor_ha_brl, 0) * (1 - v_desc/100.0), 2),
         true
  FROM public.produtos p
  WHERE p.ativo = true
  ON CONFLICT (partner_id, product_id) WHERE product_id IS NOT NULL DO UPDATE
    SET preco_tabela = EXCLUDED.preco_tabela,
        desconto_percentual = EXCLUDED.desconto_percentual,
        preco_final = EXCLUDED.preco_final,
        ativo = true;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.partner_apply_default_discount(p_partner_id uuid) OWNER TO postgres;

--
-- Name: partner_audit_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_partner_id uuid;
  v_acao text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_acao := 'create';
    v_new := to_jsonb(NEW);
    v_partner_id := CASE
      WHEN TG_TABLE_NAME = 'partner_accounts' THEN (v_new->>'id')::uuid
      ELSE (v_new->>'partner_id')::uuid
    END;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    v_partner_id := CASE
      WHEN TG_TABLE_NAME = 'partner_accounts' THEN (v_new->>'id')::uuid
      ELSE (v_new->>'partner_id')::uuid
    END;
    IF TG_TABLE_NAME = 'partner_accounts' AND (v_old->>'ativo')::boolean = true AND (v_new->>'ativo')::boolean = false THEN
      v_acao := 'delete';
    ELSIF TG_TABLE_NAME = 'partner_accounts' AND (v_old->>'ativo')::boolean = false AND (v_new->>'ativo')::boolean = true THEN
      v_acao := 'restore';
    ELSIF TG_TABLE_NAME = 'partner_product_prices' THEN
      v_acao := 'price_change';
    ELSE
      v_acao := 'update';
    END IF;
  ELSE
    RETURN NULL;
  END IF;

  INSERT INTO public.partner_audit_logs(partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_partner_id, auth.uid(), v_acao, v_old, v_new);

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.partner_audit_trigger() OWNER TO postgres;

