--
-- Name: partner_order_sla_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_order_sla_status(p_order_id uuid) RETURNS TABLE(fase text, fase_inicio timestamp with time zone, horas_decorridas numeric, prazo_horas integer, atrasada boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD; v_planning RECORD; v_fase text; v_inicio timestamptz;
BEGIN
  SELECT po.id, po.status, po.approved_at INTO v_order
    FROM partner_orders po WHERE po.id = p_order_id;
  IF NOT FOUND OR v_order.approved_at IS NULL THEN RETURN; END IF;

  SELECT pp.status, pp.updated_at INTO v_planning
    FROM production_planning pp WHERE pp.partner_order_id = p_order_id
    ORDER BY pp.created_at DESC LIMIT 1;

  IF v_planning.status = 'entregue' THEN RETURN; END IF;
  IF v_planning.status = 'produzido' THEN v_fase := 'entrega';
  ELSIF v_planning.status = 'em_producao' THEN v_fase := 'em_producao';
  ELSE v_fase := 'planejamento';
  END IF;

  SELECT MAX(event_at) INTO v_inicio
    FROM production_timeline_events
    WHERE partner_order_id = p_order_id
      AND event_type = CASE v_fase
        WHEN 'planejamento' THEN 'planejamento_criado'
        WHEN 'em_producao' THEN 'producao_iniciada'
        WHEN 'entrega' THEN 'envase_concluido'
        ELSE event_type END;

  IF v_inicio IS NULL THEN
    v_inicio := COALESCE(v_planning.updated_at, v_order.approved_at);
  END IF;

  RETURN QUERY
  SELECT v_fase, v_inicio,
         EXTRACT(EPOCH FROM (now() - v_inicio))/3600.0,
         c.prazo_horas,
         c.ativo AND EXTRACT(EPOCH FROM (now() - v_inicio))/3600.0 > c.prazo_horas
    FROM partner_order_sla_config c WHERE c.fase = v_fase;
END; $$;


ALTER FUNCTION public.partner_order_sla_status(p_order_id uuid) OWNER TO postgres;

--
-- Name: partner_orders_audit_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_orders_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acao text;
  v_old jsonb;
  v_new jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_acao := 'order_created';
    v_new := to_jsonb(NEW);
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    v_new := to_jsonb(NEW);
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      v_acao := CASE WHEN NEW.status = 'cancelado' THEN 'order_cancelled' ELSE 'status_changed' END;
    ELSE
      v_acao := 'order_updated';
    END IF;
  ELSE
    RETURN NULL;
  END IF;
  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (COALESCE(NEW.id, OLD.id), COALESCE(NEW.partner_id, OLD.partner_id), auth.uid(), v_acao, v_old, v_new);
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.partner_orders_audit_trigger() OWNER TO postgres;

--
-- Name: partner_ppp_compute_final(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_ppp_compute_final() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.preco_final IS NULL THEN
    NEW.preco_final := ROUND(NEW.preco_tabela * (1 - COALESCE(NEW.desconto_percentual,0)/100.0), 2);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.partner_ppp_compute_final() OWNER TO postgres;

--
-- Name: partner_reset_prices_to_default(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_reset_prices_to_default(p_partner_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_d numeric(5,2);
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT desconto_padrao INTO v_d FROM public.partner_accounts WHERE id = p_partner_id AND ativo = true AND deleted_at IS NULL FOR UPDATE;
  IF v_d IS NULL THEN RAISE EXCEPTION 'partner_not_found' USING ERRCODE='42501'; END IF;

  UPDATE public.partner_product_prices
     SET desconto_percentual = v_d,
         preco_final = ROUND(preco_tabela * (1 - v_d/100.0), 2),
         updated_at = now()
   WHERE partner_id = p_partner_id
     AND ativo = true
     AND desconto_percentual IS DISTINCT FROM v_d;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION public.partner_reset_prices_to_default(p_partner_id uuid) OWNER TO postgres;

--
-- Name: partner_simulation_items_fill_snapshots(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.partner_simulation_items_fill_snapshots() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  p RECORD;
  m RECORD;
BEGIN
  IF NEW.item_tipo = 'produto' AND NEW.product_id IS NULL THEN
    NEW.product_id := NEW.item_id;
  ELSIF NEW.item_tipo = 'microrganismo' AND NEW.microrganismo_id IS NULL THEN
    NEW.microrganismo_id := NEW.item_id;
  END IF;

  IF NEW.item_tipo = 'produto' AND NEW.product_id IS NOT NULL THEN
    SELECT codigo, nome INTO p FROM public.produtos WHERE id = NEW.product_id;
    IF FOUND THEN
      NEW.produto_codigo_snapshot := COALESCE(NEW.produto_codigo_snapshot, p.codigo);
      NEW.produto_nome_snapshot   := COALESCE(NEW.produto_nome_snapshot, p.nome, NEW.nome);
    END IF;
    NEW.unidade_medida := COALESCE(NEW.unidade_medida, 'unidade');
  ELSIF NEW.item_tipo = 'microrganismo' AND NEW.microrganismo_id IS NOT NULL THEN
    SELECT codigo, nome INTO m FROM public.microrganismos WHERE id = NEW.microrganismo_id;
    IF FOUND THEN
      NEW.produto_codigo_snapshot := COALESCE(NEW.produto_codigo_snapshot, m.codigo);
      NEW.produto_nome_snapshot   := COALESCE(NEW.produto_nome_snapshot, m.nome, NEW.nome);
    END IF;
    NEW.unidade_medida := COALESCE(NEW.unidade_medida, 'dose');
  END IF;

  NEW.preco_tabela_snapshot := COALESCE(NEW.preco_tabela_snapshot, NEW.valor_unitario_cheio);
  NEW.preco_unitario        := COALESCE(NEW.preco_unitario, NEW.valor_unitario_cheio);
  NEW.desconto_percentual   := COALESCE(NEW.desconto_percentual, 0);

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.partner_simulation_items_fill_snapshots() OWNER TO postgres;

