--
-- Name: platform_accept_org_admin_email_delivery(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_accept_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.email_delivery_status='accepted' THEN
    RETURN jsonb_build_object('status','accepted','idempotent',true);
  END IF;
  IF j.email_delivery_status<>'sending' OR j.email_lease_token IS DISTINCT FROM p_lease_token
     OR j.email_lease_expires_at IS NULL OR j.email_lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'platform_stale_lease: confirmação sem reserva vigente' USING ERRCODE='55P03';
  END IF;
  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='accepted',email_accepted_at=now(),email_failed_at=NULL,
         email_lease_token=NULL,email_lease_expires_at=NULL,email_last_error_code=NULL,updated_at=now()
   WHERE id=j.id AND email_lease_token=p_lease_token;
  RETURN jsonb_build_object('status','accepted','idempotent',false);
END
$$;


ALTER FUNCTION public.platform_accept_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid) OWNER TO postgres;

--
-- Name: platform_archive_plan_version(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_archive_plan_version(_version_id uuid, _reason text, _idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE v public.saas_plan_versions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL OR length(btrim(coalesce(_reason,'')))<5 THEN
    RAISE EXCEPTION 'platform_invalid: motivo e chave idempotente obrigatórios' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_version_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: versão inexistente' USING ERRCODE='22023'; END IF;
  IF v.status='ARCHIVED' THEN RETURN v.id; END IF;
  IF v.status<>'PUBLISHED' THEN RAISE EXCEPTION 'platform_conflict: apenas publicada pode ser arquivada' USING ERRCODE='40001'; END IF;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_archive',v.plan_id);
  UPDATE public.saas_plan_versions SET status='ARCHIVED',archived_at=now(),archived_by=auth.uid(),archive_reason=btrim(_reason),updated_at=now() WHERE id=v.id;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
  INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
  VALUES(v.id,'archived',to_jsonb(v),(SELECT to_jsonb(x) FROM public.saas_plan_versions x WHERE x.id=v.id),btrim(_reason),'platform_rpc',auth.uid(),_idempotency_key);
  RETURN v.id;
END;
$$;


ALTER FUNCTION public.platform_archive_plan_version(_version_id uuid, _reason text, _idempotency_key uuid) OWNER TO postgres;

--
-- Name: platform_begin_org_admin_email_change(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_begin_org_admin_email_change(p_actor_id uuid, p_invite_id uuid, p_new_email text, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE j public.platform_org_admin_invites%ROWTYPE; c public.platform_org_admin_email_changes%ROWTYPE;
  v_email text := lower(btrim(coalesce(p_new_email,''))); v_reason text := btrim(coalesce(p_reason,''));
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
  PERFORM platform_private.require_service_role();
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_idempotency_key IS NULL OR p_invite_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: parâmetros' USING ERRCODE='22023'; END IF;
  IF v_reason = '' THEN v_reason := 'Alteração de e-mail administrativo'; END IF;
  IF char_length(v_reason) < 2 THEN RAISE EXCEPTION 'platform_invalid: motivo' USING ERRCODE='22023'; END IF;
  IF v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' OR length(v_email) > 254 THEN RAISE EXCEPTION 'platform_invalid: email' USING ERRCODE='22023'; END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: administrador' USING ERRCODE='22023'; END IF;

  SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE idempotency_key=p_idempotency_key FOR UPDATE;
  IF FOUND THEN
    IF c.invite_id<>p_invite_id OR c.new_email<>v_email OR c.reason<>v_reason THEN
      RAISE EXCEPTION 'platform_conflict: chave idempotente já usada com outro conteúdo' USING ERRCODE='40001'; END IF;
    IF c.status='cancelled' THEN RAISE EXCEPTION 'platform_conflict: solicitação substituída' USING ERRCODE='40001'; END IF;
    IF c.status='failed' THEN
      UPDATE public.platform_org_admin_email_changes SET status='requested', attempt_count=attempt_count+1, updated_at=now()
       WHERE id=c.id RETURNING * INTO c;
    END IF;
    RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
      'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',true);
  END IF;

  PERFORM platform_private.cancel_stale_email_change(p_invite_id, p_actor_id);
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.invite_id=p_invite_id AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_conflict: já existe mudança de e-mail pendente para este administrador' USING ERRCODE='55P03'; END IF;
  IF j.status='processando' OR (j.lease_expires_at IS NOT NULL AND j.lease_expires_at > clock_timestamp())
     OR j.email_delivery_status='sending' THEN
    RAISE EXCEPTION 'platform_conflict: provisionamento em andamento' USING ERRCODE='55P03'; END IF;
  IF j.user_id IS NOT NULL AND public.is_platform_superadmin(j.user_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF j.user_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id) THEN
    RAISE EXCEPTION 'platform_conflict: vínculo do perfil diverge da empresa' USING ERRCODE='40001'; END IF;
  IF lower(j.email)=v_email THEN RAISE EXCEPTION 'platform_invalid: e-mail igual ao atual' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.platform_org_admin_invites i WHERE lower(i.email)=v_email)
     OR EXISTS (SELECT 1 FROM public.profiles p WHERE lower(p.email)=v_email AND p.user_id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM auth.users u WHERE lower(u.email)=v_email AND u.id IS DISTINCT FROM j.user_id)
     OR EXISTS (SELECT 1 FROM public.platform_org_admin_email_changes x WHERE x.new_email=v_email AND x.status IN ('requested','auth_updated','failed')) THEN
    RAISE EXCEPTION 'platform_email_in_use' USING ERRCODE='23505'; END IF;

  INSERT INTO public.platform_org_admin_email_changes(idempotency_key,organization_id,invite_id,user_id,invite_status_at_request,old_email,new_email,reason,actor_user_id,status)
  VALUES (p_idempotency_key,j.organization_id,j.id,j.user_id,j.status,lower(j.email),v_email,v_reason,p_actor_id,'requested') RETURNING * INTO c;
  INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values)
  VALUES (j.organization_id,j.user_id,j.id,p_actor_id,'email_change_requested','requested',v_reason,'edge_platform_org_admin_email_change',p_idempotency_key,
          jsonb_build_object('email',lower(j.email),'invite_status',j.status),jsonb_build_object('email',v_email));
  RETURN jsonb_build_object('op_id',c.id,'status',c.status,'user_id',c.user_id,'old_email',c.old_email,'new_email',c.new_email,
    'invite_status',c.invite_status_at_request,'organization_id',c.organization_id,'attempt',c.attempt_count,'idempotent',false);
END $_$;


ALTER FUNCTION public.platform_begin_org_admin_email_change(p_actor_id uuid, p_invite_id uuid, p_new_email text, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

--
-- Name: platform_claim_admin_access(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_claim_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_kind text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$ SELECT public.platform_claim_admin_access(p_actor_id,p_invite_id,p_operation_id,p_kind,false); $$;


ALTER FUNCTION public.platform_claim_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_kind text) OWNER TO postgres;

--
-- Name: platform_claim_admin_access(uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_claim_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_kind text, p_confirm_ambiguous boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.platform_org_admin_invites%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
 PERFORM platform_private.require_service_role();
 IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) OR p_kind NOT IN ('temporary_password','password_link') OR p_operation_id IS NULL THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor_id OR public.is_platform_superadmin(j.user_id) OR j.status NOT IN ('ativo','pendente') OR NOT EXISTS(SELECT 1 FROM public.profiles p JOIN public.organizations o ON o.id=p.organization_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id AND p.ativo AND o.ativo) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
 IF j.access_operation_status IN ('ambiguous','processing') AND j.access_operation_id IS DISTINCT FROM p_operation_id AND NOT coalesce(p_confirm_ambiguous,false) THEN RAISE EXCEPTION 'access_ambiguous_requires_confirmation' USING ERRCODE='55P03'; END IF;
 IF j.access_operation_id=p_operation_id THEN
  IF j.access_operation_kind<>p_kind THEN RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE='40001'; END IF;
  IF j.access_operation_status IN ('completed','ambiguous') THEN RETURN jsonb_build_object('idempotent',true,'status',j.access_operation_status); END IF;
 END IF;
 IF (j.lease_expires_at>clock_timestamp()) OR j.status='processando' OR j.email_delivery_status='sending' OR (j.access_requested_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'access_cooldown_or_busy' USING ERRCODE='55P03'; END IF;
 IF (SELECT count(*) FROM public.platform_org_admin_audit WHERE actor_user_id=p_actor_id AND action='access_requested' AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'access_rate_limit' USING ERRCODE='53400'; END IF;
 UPDATE public.platform_org_admin_invites SET access_operation_id=p_operation_id,access_operation_kind=p_kind,access_operation_status='processing',access_requested_at=clock_timestamp(),access_valid_after=CASE WHEN p_kind='temporary_password' THEN clock_timestamp() ELSE access_valid_after END,lease_token=t,lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=now() WHERE id=j.id;
 IF p_kind='temporary_password' THEN
  UPDATE public.profiles SET senha_provisoria=true WHERE user_id=j.user_id;
  INSERT INTO platform_private.provisional_password_state(user_id,desde,expires_at) VALUES(j.user_id,now(),now()+interval '24 hours') ON CONFLICT(user_id) DO UPDATE SET desde=now(),expires_at=now()+interval '24 hours',pwd_digest=NULL;
 END IF;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(j.organization_id,j.user_id,j.id,p_actor_id,'access_requested','requested','Gestão segura de acesso','platform_invite_org_admin',p_operation_id,jsonb_build_object('kind',p_kind,'ambiguous_retry_confirmed',coalesce(p_confirm_ambiguous,false)));
 RETURN jsonb_build_object('user_id',j.user_id,'email',j.email,'nome',j.nome,'lease_token',t,'organization_id',j.organization_id,'status',j.status);
END $$;


ALTER FUNCTION public.platform_claim_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_kind text, p_confirm_ambiguous boolean) OWNER TO postgres;

--
-- Name: platform_claim_email_confirmation(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_claim_email_confirmation(p_actor_id uuid, p_op_id uuid, p_confirm_ambiguous boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE; t uuid:=gen_random_uuid();
BEGIN
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
 IF FOUND THEN PERFORM platform_private.require_provisioned_admin_target(p_actor_id,c.invite_id); END IF;
 IF NOT FOUND OR c.status NOT IN ('requested','failed') OR c.user_id IS NULL OR c.user_id=p_actor_id OR public.is_platform_superadmin(c.user_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 IF c.confirmation_next_attempt_at>clock_timestamp() OR c.confirmation_lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'email_confirmation_cooldown' USING ERRCODE='55P03'; END IF;
 IF c.confirmation_delivery_status IN ('sending','ambiguous') AND NOT p_confirm_ambiguous THEN RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='55P03'; END IF;
 IF c.attempt_count>=20 THEN RAISE EXCEPTION 'email_confirmation_rate_limit' USING ERRCODE='53400'; END IF;
 UPDATE public.platform_org_admin_email_changes SET status='requested',confirmation_lease=t,confirmation_lease_expires_at=clock_timestamp()+interval '2 minutes',confirmation_next_attempt_at=clock_timestamp()+interval '5 minutes',confirmation_expires_at=clock_timestamp()+interval '24 hours',confirmation_delivery_status='sending',attempt_count=attempt_count+1,updated_at=now() WHERE id=c.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_requested','requested','Reenvio de confirmação pelo titular','email_confirmation_claim',c.idempotency_key,jsonb_build_object('ambiguous_retry_confirmed',coalesce(p_confirm_ambiguous,false),'attempt',c.attempt_count+1));
 RETURN t;
END $$;


ALTER FUNCTION public.platform_claim_email_confirmation(p_actor_id uuid, p_op_id uuid, p_confirm_ambiguous boolean) OWNER TO postgres;

--
-- Name: platform_claim_org_admin_email_delivery(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_claim_org_admin_email_delivery(p_job_id uuid, p_cooldown_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_token uuid := gen_random_uuid();
  v_idempotency uuid;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  IF p_cooldown_seconds < 30 OR p_cooldown_seconds > 86400 THEN
    RAISE EXCEPTION 'platform_invalid: cooldown inválido' USING ERRCODE='22023';
  END IF;

  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.modo_acesso <> 'link' OR j.user_id IS NULL OR j.status NOT IN ('pendente','ativo') THEN
    RAISE EXCEPTION 'platform_invalid: convite ainda não está pronto para envio' USING ERRCODE='22023';
  END IF;
  IF j.email_delivery_status='sending' AND j.email_lease_expires_at > clock_timestamp() THEN
    RAISE EXCEPTION 'platform_email_busy: envio já reservado' USING ERRCODE='55P03';
  END IF;
  IF j.email_next_attempt_at > clock_timestamp() THEN
    RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
  END IF;

  v_idempotency := CASE
    WHEN j.email_delivery_status='accepted' THEN gen_random_uuid()
    ELSE j.email_idempotency_key
  END;

  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='sending',
         email_attempt_count=email_attempt_count+1,
         email_idempotency_key=v_idempotency,
         email_lease_token=v_token,
         email_lease_expires_at=clock_timestamp()+interval '2 minutes',
         email_last_attempt_at=now(),
         email_last_error_code=NULL,
         email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_cooldown_seconds),
         updated_at=now()
   WHERE id=j.id;

  RETURN jsonb_build_object(
    'job_id',j.id,
    'lease_token',v_token,
    'idempotency_key',v_idempotency,
    'recipient_email',lower(j.email),
    'recipient_name',j.nome
  );
END
$$;


ALTER FUNCTION public.platform_claim_org_admin_email_delivery(p_job_id uuid, p_cooldown_seconds integer) OWNER TO postgres;

--
-- Name: platform_claim_org_admin_email_delivery(uuid, uuid, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_claim_org_admin_email_delivery(p_job_id uuid, p_actor_id uuid, p_confirm_ambiguous_email_retry boolean DEFAULT false, p_cooldown_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_token uuid:=gen_random_uuid();
  v_idempotency uuid;
  v_ambiguous boolean;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' OR p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_cooldown_seconds<30 OR p_cooldown_seconds>86400 THEN RAISE EXCEPTION 'platform_invalid: cooldown inválido' USING ERRCODE='22023'; END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.modo_acesso<>'link' OR j.user_id IS NULL OR j.status NOT IN('pendente','ativo') THEN RAISE EXCEPTION 'platform_invalid: convite ainda não está pronto para envio' USING ERRCODE='22023'; END IF;
  v_ambiguous := j.email_delivery_status='ambiguous' OR (j.email_delivery_status='failed' AND j.email_last_error_code IN('email_unknown_error','email_send_ambiguous','email_accept_persistence_failed','email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'));
  IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001'; END IF;
  IF j.email_delivery_status='sending' AND j.email_lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_email_busy: envio já reservado' USING ERRCODE='55P03'; END IF;
  IF j.email_next_attempt_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03'; END IF;
  IF v_ambiguous THEN
    INSERT INTO public.comunicacao_audit_log(acao,entidade,entity_id,actor_id,before_state,after_state)
    VALUES('invite.email_ambiguous_retry_confirmed','platform_org_admin_invites',j.id,p_actor_id,
      jsonb_build_object('delivery_status',j.email_delivery_status,'safe_code',j.email_last_error_code),
      jsonb_build_object('confirmation','nao_recebimento_confirmado','next_action','retry_claimed'));
  END IF;
  v_idempotency:=CASE WHEN j.email_delivery_status='accepted' THEN gen_random_uuid() ELSE j.email_idempotency_key END;
  UPDATE public.platform_org_admin_invites SET email_delivery_status='sending',email_attempt_count=email_attempt_count+1,email_idempotency_key=v_idempotency,email_lease_token=v_token,email_lease_expires_at=clock_timestamp()+interval '2 minutes',email_last_attempt_at=now(),email_last_error_code=NULL,email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_cooldown_seconds),updated_at=now() WHERE id=j.id;
  RETURN jsonb_build_object('job_id',j.id,'lease_token',v_token,'idempotency_key',v_idempotency,'recipient_email',lower(j.email),'recipient_name',j.nome);
END $$;


