 IF EXISTS(SELECT 1 FROM public.platform_org_admin_email_changes c WHERE c.invite_id=j.id AND c.status IN ('requested','auth_updated','failed')) THEN RAISE EXCEPTION 'email_change_pending' USING ERRCODE='55P03'; END IF;
    IF j.organization_id<>p_organization_id THEN RAISE EXCEPTION 'platform_conflict: outro tenant' USING ERRCODE='23505'; END IF;
    IF j.status='ativo' THEN RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status','ativo','user_id',j.user_id,'completed',true); END IF;
    IF j.lease_expires_at IS NOT NULL AND j.lease_expires_at>clock_timestamp() THEN RAISE EXCEPTION 'platform_conflict: em andamento' USING ERRCODE='55P03'; END IF;
    IF (j.nome,j.cpf_cnpj,j.telefone,j.modo_acesso,j.responsavel_principal) IS DISTINCT FROM (btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal) THEN RAISE EXCEPTION 'platform_conflict: dados divergentes' USING ERRCODE='23505'; END IF;
    IF p_delivery_mode='email' THEN
      v_ambiguous := j.email_delivery_status='ambiguous' OR (
        j.email_delivery_status='failed' AND j.email_last_error_code IN (
          'email_unknown_error','email_send_ambiguous','email_accept_persistence_failed',
          'email_timeout','email_network_error','email_send_crash','email_delivery_setup_failed'
        )
      );
      IF v_ambiguous AND NOT coalesce(p_confirm_ambiguous_email_retry,false) THEN
        RAISE EXCEPTION 'email_ambiguous_confirmation_required' USING ERRCODE='P0001';
      END IF;
      IF j.email_next_attempt_at > clock_timestamp() THEN
        RAISE EXCEPTION 'platform_email_cooldown: reenvio em cooldown' USING ERRCODE='55P03';
      END IF;
    END IF;
    UPDATE public.platform_org_admin_invites
       SET status='processando',lease_token=token,lease_expires_at=clock_timestamp()+interval '2 minutes',attempt_count=attempt_count+1,last_error_code=NULL,updated_at=now()
     WHERE id=j.id RETURNING * INTO j;
  ELSE
    INSERT INTO public.platform_org_admin_invites(organization_id,user_id,email,nome,cpf_cnpj,telefone,modo_acesso,responsavel_principal,invited_by,status,request_id,attempt_count,lease_token,lease_expires_at,updated_at)
    VALUES(p_organization_id,NULL,v_email,btrim(p_nome),v_cpf,v_tel,p_modo_acesso,p_responsavel_principal,p_actor_id,'processando',gen_random_uuid(),1,token,clock_timestamp()+interval '2 minutes',now()) RETURNING * INTO j;
  END IF;
  RETURN jsonb_build_object('job_id',j.id,'request_id',j.request_id,'status',j.status,'lease_token',token,'lease_expires_at',j.lease_expires_at,'user_id',j.user_id,'completed',false);
END
$_$;


ALTER FUNCTION public.platform_claim_org_admin_provisioning(p_actor_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text, p_telefone text, p_modo_acesso text, p_responsavel_principal boolean, p_confirm_ambiguous_email_retry boolean, p_delivery_mode text) OWNER TO postgres;

--
-- Name: platform_complete_org_admin_email_change(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_complete_org_admin_email_change(p_actor_id uuid, p_op_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE; j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,c.invite_id);
 IF c.status='completed' THEN RETURN jsonb_build_object('status','completed','idempotent',true); END IF;
 IF c.status NOT IN ('requested','auth_updated','failed') OR c.confirmation_sent_at IS NULL OR c.user_id IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=c.user_id AND lower(u.email)=c.new_email AND u.email_confirmed_at IS NOT NULL AND COALESCE(u.email_change,'')='') THEN RAISE EXCEPTION 'email_confirmation_required' USING ERRCODE='55000'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=c.invite_id FOR UPDATE;
 IF j.user_id IS DISTINCT FROM c.user_id OR lower(j.email)<>c.old_email OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=c.user_id AND organization_id=c.organization_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 UPDATE public.profiles SET email=c.new_email WHERE user_id=c.user_id AND organization_id=c.organization_id;
 UPDATE public.platform_org_admin_invites SET email=c.new_email,access_valid_after=clock_timestamp(),updated_at=now() WHERE id=j.id;
 UPDATE public.platform_org_admin_email_changes SET status='completed',completed_at=now(),last_error_code=NULL,updated_at=now() WHERE id=c.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values) VALUES(c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_completed','succeeded',c.reason,'auth_confirmed_reconciliation',c.idempotency_key,jsonb_build_object('email','***'),jsonb_build_object('email','***'));
 RETURN jsonb_build_object('status','completed','idempotent',false);
END $$;


ALTER FUNCTION public.platform_complete_org_admin_email_change(p_actor_id uuid, p_op_id uuid) OWNER TO postgres;

