--
-- Name: platform_end_feature_override(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_end_feature_override(_override_id uuid, _reason text, _idempotency_key uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_existing public.organization_feature_overrides%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) < 5 THEN
    RAISE EXCEPTION 'platform_invalid: motivo obrigatório' USING ERRCODE='22023';
  END IF;

  SELECT * INTO v_existing
  FROM public.organization_feature_overrides o
  WHERE o.id=_override_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: exceção inexistente' USING ERRCODE='22023';
  END IF;
  IF v_existing.ended_at IS NOT NULL THEN
    IF v_existing.end_idempotency_key=_idempotency_key AND v_existing.end_reason=btrim(_reason) THEN
      RETURN;
    END IF;
    RAISE EXCEPTION 'platform_conflict: exceção já encerrada' USING ERRCODE='40001';
  END IF;

  UPDATE public.organization_feature_overrides
  SET ended_at=now(),ended_by=auth.uid(),end_reason=btrim(_reason),end_idempotency_key=_idempotency_key
  WHERE id=_override_id;
END;
$$;


ALTER FUNCTION public.platform_end_feature_override(_override_id uuid, _reason text, _idempotency_key uuid) OWNER TO postgres;

--
-- Name: platform_extend_trial(uuid, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_extend_trial(_subscription_id uuid, _new_trial_end timestamp with time zone, _reason text, _correlation_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE v_sub public.organization_subscriptions%ROWTYPE; v_existing uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _reason IS NULL OR length(btrim(_reason))<5 OR _correlation_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023'; END IF;
  SELECT h.subscription_id INTO v_existing FROM public.organization_subscription_history h WHERE h.correlation_id=_correlation_id;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  SELECT * INTO v_sub FROM public.organization_subscriptions WHERE id=_subscription_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: assinatura inexistente' USING ERRCODE='22023'; END IF;
  SELECT h.subscription_id INTO v_existing FROM public.organization_subscription_history h WHERE h.correlation_id=_correlation_id;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  IF v_sub.status<>'TRIAL' OR v_sub.plan_version_id IS NULL OR v_sub.trial_ends_at IS NULL OR _new_trial_end<=v_sub.trial_ends_at OR _new_trial_end>v_sub.trial_ends_at+interval '14 days' THEN RAISE EXCEPTION 'platform_conflict: extensão de trial inválida' USING ERRCODE='40001'; END IF;
  PERFORM platform_private.issue_ticket('saas_subscription_write',v_sub.organization_id);
  PERFORM set_config('app.saas_change_reason',btrim(_reason),true); PERFORM set_config('app.saas_change_action','extend_trial',true); PERFORM set_config('app.saas_correlation_id',_correlation_id::text,true);
  UPDATE public.organization_subscriptions SET trial_ends_at=_new_trial_end,state_changed_at=now(),last_correlation_id=_correlation_id WHERE id=_subscription_id;
  RETURN _subscription_id;
END;
$$;


ALTER FUNCTION public.platform_extend_trial(_subscription_id uuid, _new_trial_end timestamp with time zone, _reason text, _correlation_id uuid) OWNER TO postgres;

--
-- Name: platform_fail_org_admin_email_delivery(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_fail_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid, p_error_code text, p_retry_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_code text := left(regexp_replace(coalesce(nullif(btrim(p_error_code),''),'email_failed'),'[^a-zA-Z0-9_:-]','','g'),80);
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend' USING ERRCODE='42501';
  END IF;
  IF p_retry_seconds < 30 OR p_retry_seconds > 86400 THEN
    RAISE EXCEPTION 'platform_invalid: retry inválido' USING ERRCODE='22023';
  END IF;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.email_delivery_status<>'sending' OR j.email_lease_token IS DISTINCT FROM p_lease_token
     OR j.email_lease_expires_at IS NULL OR j.email_lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'platform_stale_lease: falha sem reserva vigente' USING ERRCODE='55P03';
  END IF;
  UPDATE public.platform_org_admin_invites
     SET email_delivery_status='failed',email_failed_at=now(),email_lease_token=NULL,
         email_lease_expires_at=NULL,email_last_error_code=v_code,
         email_next_attempt_at=clock_timestamp()+make_interval(secs=>p_retry_seconds),updated_at=now()
   WHERE id=j.id AND email_lease_token=p_lease_token;
  RETURN jsonb_build_object('status','failed','code',v_code);
END
$$;


ALTER FUNCTION public.platform_fail_org_admin_email_delivery(p_job_id uuid, p_lease_token uuid, p_error_code text, p_retry_seconds integer) OWNER TO postgres;

--
-- Name: platform_fail_org_admin_provisioning(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_fail_org_admin_provisioning(p_job_id uuid, p_lease_token uuid, p_error_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text;
BEGIN
  v_role := coalesce(nullif(current_setting('request.jwt.claim.role',true),''),
    nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  UPDATE public.platform_org_admin_invites SET status='falhou',lease_token=NULL,lease_expires_at=NULL,
    last_error_code=left(coalesce(p_error_code,'unknown'),40),updated_at=now()
  WHERE id=p_job_id AND status='processando' AND lease_token=p_lease_token;
  RETURN FOUND;
END
$$;


ALTER FUNCTION public.platform_fail_org_admin_provisioning(p_job_id uuid, p_lease_token uuid, p_error_code text) OWNER TO postgres;

--
-- Name: platform_finalize_org_admin_provisioning(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_finalize_org_admin_provisioning(p_job_id uuid, p_lease_token uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role text;
  j public.platform_org_admin_invites%ROWTYPE;
  v_auth_email text;
  v_origin text;
BEGIN
  v_role := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role',
    ''
  );

  IF v_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_authorization_failed'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
    INTO j
    FROM public.platform_org_admin_invites
   WHERE id = p_job_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_finalize_internal_error'
      USING ERRCODE = 'P0002';
  END IF;

  IF j.status = 'ativo' AND j.user_id = p_user_id THEN
    RETURN jsonb_build_object(
      'status', 'ativo',
      'idempotent', true,
      'user_id', j.user_id
    );
  END IF;

  IF j.status <> 'processando'
     OR j.lease_token IS DISTINCT FROM p_lease_token
     OR j.lease_expires_at IS NULL
     OR j.lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'platform_stale_lease'
      USING ERRCODE = '55P03';
  END IF;

  SELECT lower(u.email), coalesce(u.raw_app_meta_data->>'provisioning_request_id', '')
    INTO v_auth_email, v_origin
    FROM auth.users AS u
   WHERE u.id = p_user_id;

  IF v_auth_email IS NULL
     OR v_auth_email <> lower(j.email)
     OR v_origin <> j.request_id::text THEN
    RAISE EXCEPTION 'platform_auth_metadata_mismatch'
      USING ERRCODE = '23505';
  END IF;

  IF public.is_platform_superadmin(p_user_id) THEN
    RAISE EXCEPTION 'platform_authorization_failed'
      USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
       SELECT 1
         FROM public.profiles AS p
        WHERE p.user_id = p_user_id
          AND p.organization_id IS NOT NULL
          AND p.organization_id <> j.organization_id
     ) THEN
    RAISE EXCEPTION 'platform_profile_tenant_conflict'
      USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
       SELECT 1
         FROM public.user_roles AS r
        WHERE r.user_id = p_user_id
          AND r.role <> 'administrador'::public.app_role
     ) THEN
    RAISE EXCEPTION 'platform_authorization_failed'
      USING ERRCODE = '42501';
  END IF;

  BEGIN
    INSERT INTO public.profiles AS p (
      user_id,
      nome,
      email,
      telefone,
      cargo,
      cpf_cnpj,
      ativo,
      organization_id,
      senha_provisoria
    )
    VALUES (
      p_user_id,
      j.nome,
      j.email,
      j.telefone,
      CASE
        WHEN j.responsavel_principal THEN 'Responsável Principal'
        ELSE 'Administrador'
      END,
      j.cpf_cnpj,
      true,
      j.organization_id,
      true
    )
    ON CONFLICT (user_id) DO UPDATE
       SET nome = CASE
                    WHEN nullif(btrim(p.nome), '') IS NOT NULL THEN p.nome
                    ELSE excluded.nome
                  END,
           email = CASE
                     WHEN nullif(btrim(coalesce(p.email, '')), '') IS NOT NULL THEN p.email
                     ELSE excluded.email
                   END,
           telefone = coalesce(p.telefone, excluded.telefone),
           cargo = coalesce(p.cargo, excluded.cargo),
           cpf_cnpj = coalesce(p.cpf_cnpj, excluded.cpf_cnpj),
           ativo = true,
           organization_id = excluded.organization_id,
           senha_provisoria = true
     WHERE p.organization_id IS NULL
        OR p.organization_id = excluded.organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_profile_tenant_conflict'
        USING ERRCODE = '23505';
    END IF;

    INSERT INTO public.user_roles (user_id, role)
    VALUES (p_user_id, 'administrador'::public.app_role)
    ON CONFLICT (user_id, role) DO NOTHING;

    INSERT INTO platform_private.provisional_password_state (user_id)
    VALUES (p_user_id)
    ON CONFLICT (user_id) DO UPDATE
      SET desde = now(), expires_at = now()+interval '24 hours', pwd_digest = NULL;

    IF j.responsavel_principal THEN
      PERFORM platform_private.issue_ticket('org_write', j.organization_id);
      UPDATE public.organizations
         SET responsavel_user_id = p_user_id,
             responsavel_definido_em = now(),
             updated_at = now()
       WHERE id = j.organization_id;
    END IF;

    UPDATE public.platform_org_admin_invites
       SET user_id = p_user_id,
           status = 'pendente',
           auth_created_at = coalesce(auth_created_at, now()),
           lease_token = NULL,
           lease_expires_at = NULL,
           last_error_code = NULL,
           updated_at = now()
     WHERE id = j.id
       AND status = 'processando'
       AND lease_token = p_lease_token;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'platform_stale_lease'
        USING ERRCODE = '55P03';
    END IF;
  EXCEPTION
    WHEN integrity_constraint_violation THEN
      IF SQLERRM IN (
        'platform_profile_tenant_conflict',
        'platform_auth_metadata_mismatch'
      ) THEN
        RAISE;
      END IF;
      RAISE EXCEPTION 'platform_database_constraint'
        USING ERRCODE = '23000';
  END;

  RETURN jsonb_build_object(
    'status', 'pendente',
    'idempotent', false,
    'user_id', p_user_id
  );
END
$$;


ALTER FUNCTION public.platform_finalize_org_admin_provisioning(p_job_id uuid, p_lease_token uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: platform_find_org_admin_provisioning_auth_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_find_org_admin_provisioning_auth_user(p_job_id uuid, p_lease_token uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text; j public.platform_org_admin_invites%ROWTYPE; found_id uuid;
BEGIN
 v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
 IF v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id;
 IF NOT FOUND OR j.status<>'processando' OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'platform_stale_lease' USING ERRCODE='55P03'; END IF;
 SELECT u.id INTO found_id FROM auth.users u WHERE lower(u.email)=lower(j.email) AND u.raw_app_meta_data->>'provisioning_request_id'=j.request_id::text ORDER BY u.created_at LIMIT 1;
 RETURN found_id;
END $$;


ALTER FUNCTION public.platform_find_org_admin_provisioning_auth_user(p_job_id uuid, p_lease_token uuid) OWNER TO postgres;

--
-- Name: platform_finish_admin_access(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_finish_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_lease_token uuid, p_outcome text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.platform_org_admin_invites%ROWTYPE;
BEGIN
 PERFORM platform_private.require_service_role();
 IF NOT public.is_platform_superadmin(p_actor_id) OR p_outcome NOT IN ('completed','failed','ambiguous') THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id FOR UPDATE;
 IF j.access_operation_id IS DISTINCT FROM p_operation_id OR j.lease_token IS DISTINCT FROM p_lease_token OR j.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'stale_lease' USING ERRCODE='55P03'; END IF;
 UPDATE public.platform_org_admin_invites SET access_operation_status=p_outcome,lease_token=NULL,lease_expires_at=NULL,access_expires_at=CASE WHEN j.access_operation_kind='temporary_password' THEN now()+interval '24 hours' ELSE NULL END,access_valid_after=CASE WHEN j.access_operation_kind='temporary_password' AND p_outcome='completed' THEN clock_timestamp() ELSE access_valid_after END,email_last_attempt_at=CASE WHEN j.access_operation_kind='password_link' THEN j.access_requested_at ELSE email_last_attempt_at END,email_next_attempt_at=j.access_requested_at+interval '5 minutes',email_accepted_at=CASE WHEN j.access_operation_kind='password_link' AND p_outcome='completed' THEN now() ELSE email_accepted_at END,updated_at=now() WHERE id=j.id;
 INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,new_values) VALUES(j.organization_id,j.user_id,j.id,p_actor_id,CASE WHEN p_outcome='completed' THEN 'access_completed' ELSE 'access_failed' END,CASE WHEN p_outcome='completed' THEN 'succeeded' ELSE 'failed' END,'Gestão segura de acesso','platform_invite_org_admin',p_operation_id,jsonb_build_object('kind',j.access_operation_kind,'outcome',p_outcome));
 RETURN true;
END $$;


ALTER FUNCTION public.platform_finish_admin_access(p_actor_id uuid, p_invite_id uuid, p_operation_id uuid, p_lease_token uuid, p_outcome text) OWNER TO postgres;

--
-- Name: platform_finish_email_confirmation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_finish_email_confirmation(p_actor_id uuid, p_op_id uuid, p_lease uuid, p_outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) OR p_outcome NOT IN ('sent','failed','ambiguous') THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 UPDATE public.platform_org_admin_email_changes SET confirmation_delivery_status=p_outcome,confirmation_sent_at=CASE WHEN p_outcome='sent' THEN now() ELSE confirmation_sent_at END,confirmation_lease=NULL,confirmation_lease_expires_at=NULL,last_error_code=CASE WHEN p_outcome='sent' THEN NULL ELSE 'confirmation_delivery_unconfirmed' END,updated_at=now() WHERE id=p_op_id AND confirmation_lease=p_lease AND confirmation_lease_expires_at>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION 'stale_lease' USING ERRCODE='55P03'; END IF;
END $$;


ALTER FUNCTION public.platform_finish_email_confirmation(p_actor_id uuid, p_op_id uuid, p_lease uuid, p_outcome text) OWNER TO postgres;

--
-- Name: platform_first_access_pending(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_first_access_pending(p_user_id uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'platform_private', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = p_user_id
      AND p.senha_provisoria IS TRUE
      AND EXISTS (SELECT 1 FROM platform_private.provisional_password_state s WHERE s.user_id = p.user_id)
  )
$$;


ALTER FUNCTION public.platform_first_access_pending(p_user_id uuid) OWNER TO postgres;

