--
-- Name: platform_list_catalog_labels(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_list_catalog_labels(p_familia text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_result jsonb;
BEGIN
  PERFORM platform_private.catalog_metadata_require_actor();
  IF p_familia IS NULL OR p_familia NOT IN ('biologico','quimico','fertilizante_adubo') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_family_invalid';
  END IF;
  SELECT COALESCE(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', l.id, 'familia', l.familia, 'rotulo', l.rotulo, 'rotulo_exibicao', l.rotulo_exibicao,
      'ativo', l.ativo, 'updated_at', l.updated_at)
    ORDER BY pg_catalog.lower(l.rotulo_exibicao) COLLATE "C", l.id), '[]'::jsonb)
  INTO v_result
  FROM public.catalog_family_labels l
  WHERE l.familia = p_familia;
  RETURN v_result;
END $$;


ALTER FUNCTION public.platform_list_catalog_labels(p_familia text) OWNER TO postgres;

--
-- Name: platform_mark_org_admin_email_ambiguous(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_mark_org_admin_email_ambiguous(p_job_id uuid, p_lease_token uuid, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text; j public.platform_org_admin_invites%ROWTYPE; v_code text;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  v_code:=CASE WHEN p_error_code IN('email_send_ambiguous','email_accept_persistence_failed') THEN p_error_code ELSE 'email_send_ambiguous' END;
  SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: job inexistente' USING ERRCODE='22023'; END IF;
  IF j.email_delivery_status<>'sending' OR j.email_lease_token IS DISTINCT FROM p_lease_token OR j.email_lease_expires_at IS NULL OR j.email_lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'platform_stale_lease: ambiguidade sem reserva vigente' USING ERRCODE='55P03'; END IF;
  UPDATE public.platform_org_admin_invites SET email_delivery_status='ambiguous',email_failed_at=now(),email_lease_token=NULL,email_lease_expires_at=NULL,email_last_error_code=v_code,updated_at=now() WHERE id=j.id AND email_lease_token=p_lease_token;
  RETURN jsonb_build_object('status','ambiguous','code',v_code);
END $$;


ALTER FUNCTION public.platform_mark_org_admin_email_ambiguous(p_job_id uuid, p_lease_token uuid, p_error_code text) OWNER TO postgres;

--
-- Name: platform_mark_org_admin_email_change(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_mark_org_admin_email_change(p_actor_id uuid, p_op_id uuid, p_status text, p_error_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE c public.platform_org_admin_email_changes%ROWTYPE;
BEGIN
  PERFORM platform_private.require_service_role();
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF p_status NOT IN ('auth_updated','failed') THEN RAISE EXCEPTION 'platform_invalid: status' USING ERRCODE='22023'; END IF;
  SELECT * INTO c FROM public.platform_org_admin_email_changes WHERE id=p_op_id FOR UPDATE;
  IF NOT FOUND OR c.status='completed' THEN RETURN; END IF;
  UPDATE public.platform_org_admin_email_changes
     SET status=p_status, last_error_code=CASE WHEN p_status='failed' THEN left(coalesce(p_error_code,'unknown'),80) ELSE NULL END, updated_at=now()
   WHERE id=c.id;
  IF p_status='failed' THEN
    INSERT INTO public.platform_org_admin_audit(organization_id,target_user_id,invite_id,actor_user_id,action,status,reason,origin,idempotency_key,old_values,new_values,error_code,attempt)
    VALUES (c.organization_id,c.user_id,c.invite_id,p_actor_id,'email_change_failed','failed',c.reason,'edge_platform_org_admin_email_change',c.idempotency_key,
            jsonb_build_object('email',c.old_email),jsonb_build_object('email',c.new_email),left(coalesce(p_error_code,'unknown'),80),c.attempt_count);
  END IF;
END $$;


ALTER FUNCTION public.platform_mark_org_admin_email_change(p_actor_id uuid, p_op_id uuid, p_status text, p_error_code text) OWNER TO postgres;

--
-- Name: platform_org_admin_access_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_org_admin_access_state(p_actor_id uuid, p_invite_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j public.platform_org_admin_invites%ROWTYPE; pending boolean; exp timestamptz; active boolean;
BEGIN
 PERFORM platform_private.require_provisioned_admin_target(p_actor_id,p_invite_id);
 PERFORM platform_private.require_service_role(); IF NOT public.is_platform_superadmin(p_actor_id) THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO j FROM public.platform_org_admin_invites WHERE id=p_invite_id;
 IF NOT FOUND OR j.user_id IS NULL OR j.user_id=p_actor_id OR public.is_platform_superadmin(j.user_id) THEN RAISE EXCEPTION 'platform_target_denied' USING ERRCODE='42501'; END IF;
 SELECT p.senha_provisoria,p.ativo,s.expires_at INTO pending,active,exp FROM public.profiles p LEFT JOIN platform_private.provisional_password_state s ON s.user_id=p.user_id WHERE p.user_id=j.user_id AND p.organization_id=j.organization_id;
 RETURN jsonb_build_object('pending_password',pending,'provisional_expires_at',exp,'active',active,'last_sent_at',j.email_accepted_at,'next_attempt_at',greatest(j.email_next_attempt_at,j.access_requested_at+interval '5 minutes'),'status',j.status,'operation_status',j.access_operation_status,'user_id',j.user_id);
END $$;


ALTER FUNCTION public.platform_org_admin_access_state(p_actor_id uuid, p_invite_id uuid) OWNER TO postgres;

