--
-- Name: platform_publish_plan_version(text, numeric, text, text, jsonb, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_publish_plan_version(_plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _limits jsonb, _effective_from timestamp with time zone, _reason text, _correlation_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
DECLARE v_plan public.saas_plans%ROWTYPE; v_id uuid; v_version integer; v_features jsonb; v_existing public.saas_plan_versions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501'; END IF;
  IF _reason IS NULL OR length(btrim(_reason))<5 OR _correlation_id IS NULL THEN RAISE EXCEPTION 'platform_invalid: motivo e correlação obrigatórios' USING ERRCODE='22023'; END IF;
  IF _price_amount IS NULL OR _price_amount<0 OR upper(btrim(coalesce(_currency,'')))!~'^[A-Z]{3}$' OR _billing_cycle NOT IN ('monthly','quarterly','semiannual','annual','custom') OR _limits IS NULL OR jsonb_typeof(_limits)<>'object' OR _effective_from IS NULL THEN RAISE EXCEPTION 'platform_invalid: versão comercial incompleta' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_existing FROM public.saas_plan_versions v WHERE v.correlation_id=_correlation_id;
  IF FOUND THEN
    IF v_existing.price_amount=_price_amount AND v_existing.currency=upper(btrim(_currency)) AND v_existing.billing_cycle=_billing_cycle AND v_existing.limits_snapshot=_limits AND v_existing.effective_from=_effective_from AND EXISTS(SELECT 1 FROM public.saas_plans p WHERE p.id=v_existing.plan_id AND p.key=_plan_key) THEN RETURN v_existing.id; END IF;
    RAISE EXCEPTION 'platform_conflict: correlação já utilizada com conteúdo diferente' USING ERRCODE='40001';
  END IF;
  SELECT p.* INTO v_plan FROM public.saas_plans p WHERE p.key=_plan_key AND p.active FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM public.saas_plan_versions v WHERE v.plan_id=v_plan.id AND v.effective_from<=_effective_from AND (v.effective_to IS NULL OR v.effective_to>_effective_from)) THEN RAISE EXCEPTION 'platform_conflict: versão vigente não pode ser substituída' USING ERRCODE='40001'; END IF;
  SELECT coalesce(max(v.version_number),0)+1 INTO v_version FROM public.saas_plan_versions v WHERE v.plan_id=v_plan.id;
  SELECT coalesce(jsonb_agg(jsonb_build_object('feature_id',pf.feature_id,'enabled',pf.enabled,'limit_value',pf.limit_value,'config',pf.config) ORDER BY pf.feature_id::text),'[]'::jsonb) INTO v_features FROM public.saas_plan_features pf WHERE pf.plan_id=v_plan.id;
  PERFORM platform_private.issue_ticket('saas_plan_version_create',v_plan.id);
  INSERT INTO public.saas_plan_versions(plan_id,version_number,name_snapshot,description_snapshot,price_amount,currency,billing_cycle,limits_snapshot,features_snapshot,effective_from,created_by,publication_reason,correlation_id) VALUES(v_plan.id,v_version,v_plan.name,v_plan.description,_price_amount,upper(btrim(_currency)),_billing_cycle,_limits,v_features,_effective_from,auth.uid(),btrim(_reason),_correlation_id) RETURNING id INTO v_id;
  INSERT INTO public.saas_plan_version_features(plan_version_id,feature_id,enabled,limit_value,config) SELECT v_id,pf.feature_id,pf.enabled,pf.limit_value,pf.config FROM public.saas_plan_features pf WHERE pf.plan_id=v_plan.id;
  RETURN v_id;
END;
$_$;


ALTER FUNCTION public.platform_publish_plan_version(_plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _limits jsonb, _effective_from timestamp with time zone, _reason text, _correlation_id uuid) OWNER TO postgres;

--
-- Name: platform_publish_plan_version_draft(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_publish_plan_version_draft(_draft_id uuid, _reason text, _idempotency_key uuid, _confirmation text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v public.saas_plan_versions%ROWTYPE;
  prev public.saas_plan_versions%ROWTYPE;
  v_check jsonb; v_reason text; v_open int; v_prev_new jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _confirmation IS DISTINCT FROM 'PUBLICAR' THEN
    RAISE EXCEPTION 'platform_invalid: confirmação inválida' USING ERRCODE='22023';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  v_reason := platform_private.normalize_commercial_reason(_reason);

  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('saas_plan_version:' || v.plan_id::text,0));
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id FOR UPDATE;

  IF v.status='PUBLISHED' AND v.publish_key=_idempotency_key THEN
    IF v.publication_reason IS DISTINCT FROM v_reason THEN
      RAISE EXCEPTION 'platform_conflict: mesma chave idempotente com motivo divergente' USING ERRCODE='40001';
    END IF;
    RETURN v.id;
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.publish_key=_idempotency_key AND x.id<>v.id) THEN
    RAISE EXCEPTION 'platform_conflict: chave idempotente já usada em outra publicação' USING ERRCODE='40001';
  END IF;
  IF v.status <> 'DRAFT' THEN RAISE EXCEPTION 'platform_conflict: versão não está em rascunho' USING ERRCODE='40001'; END IF;

  v_check := public.platform_validate_plan_version_draft(v.id);
  IF NOT coalesce((v_check->>'complete')::boolean,false) OR NOT coalesce((v_check->>'valid')::boolean,false) THEN
    RAISE EXCEPTION 'platform_invalid: rascunho incompleto ou inválido' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO v_open FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL;
  IF v_open > 1 THEN
    RAISE EXCEPTION 'platform_conflict: mais de uma versão vigente para o plano' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_from >= v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: início da vigência deve ser posterior ao da versão publicada anterior' USING ERRCODE='40001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.saas_plan_versions x WHERE x.plan_id=v.plan_id AND x.status='PUBLISHED'
              AND x.effective_to IS NOT NULL AND x.effective_to > v.effective_from) THEN
    RAISE EXCEPTION 'platform_conflict: vigência sobreposta' USING ERRCODE='40001';
  END IF;

  SELECT * INTO prev FROM public.saas_plan_versions
   WHERE plan_id=v.plan_id AND status='PUBLISHED' AND effective_to IS NULL FOR UPDATE;
  IF FOUND THEN
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_supersede',prev.id);
    UPDATE public.saas_plan_versions SET effective_to = v.effective_from WHERE id = prev.id;
    SELECT to_jsonb(x) INTO v_prev_new FROM public.saas_plan_versions x WHERE x.id=prev.id;
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
    INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
    VALUES(prev.id,'superseded',to_jsonb(prev),v_prev_new || jsonb_build_object('superseded_by',v.id),
           v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  END IF;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v.plan_id);
  UPDATE public.saas_plan_versions SET status='PUBLISHED',published_at=now(),publication_reason=v_reason,
    publish_key=_idempotency_key WHERE id=v.id;
  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v.plan_id);
  INSERT INTO public.saas_plan_version_audit(plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key)
  VALUES(v.id,'published',to_jsonb(v),
         (SELECT to_jsonb(x) FROM public.saas_plan_versions x WHERE x.id=v.id) || jsonb_build_object('supersedes',prev.id),
         v_reason,'platform_rpc',auth.uid(),_idempotency_key);
  RETURN v.id;
END; $$;


ALTER FUNCTION public.platform_publish_plan_version_draft(_draft_id uuid, _reason text, _idempotency_key uuid, _confirmation text) OWNER TO postgres;

