--
-- Name: platform_register_org_admin(uuid, uuid, uuid, text, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_register_org_admin(p_actor_id uuid, p_user_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text DEFAULT NULL::text, p_telefone text DEFAULT NULL::text, p_modo_acesso text DEFAULT 'link'::text, p_responsavel_principal boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE v_jwt_role text; v_cpf text; v_tel text; v_email text; v_auth_email text; v_auth_created timestamptz;
BEGIN
  v_jwt_role := COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), '')::json ->> 'role'), '');
  IF v_jwt_role <> 'service_role' THEN
    RAISE EXCEPTION 'platform_forbidden: uso restrito ao backend da plataforma';
  END IF;
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin de plataforma';
  END IF;
  v_email := lower(btrim(COALESCE(p_email,'')));
  v_cpf := NULLIF(regexp_replace(COALESCE(p_cpf_cnpj,''), '\D', '', 'g'), '');
  v_tel := NULLIF(regexp_replace(COALESCE(p_telefone,''), '\D', '', 'g'), '');
  IF p_user_id IS NULL OR p_organization_id IS NULL OR v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$'
     OR length(btrim(COALESCE(p_nome,''))) < 3 OR length(btrim(p_nome)) > 200 THEN
    RAISE EXCEPTION 'platform_invalid: dados do administrador incompletos';
  END IF;
  IF v_cpf IS NOT NULL AND length(v_cpf) <> 11 THEN RAISE EXCEPTION 'platform_invalid: cpf'; END IF;
  IF v_tel IS NOT NULL AND length(v_tel) NOT IN (10,11) THEN RAISE EXCEPTION 'platform_invalid: telefone'; END IF;
  IF p_modo_acesso NOT IN ('link','senha_temporaria') THEN RAISE EXCEPTION 'platform_invalid: modo'; END IF;
  IF public.is_platform_superadmin(p_user_id) THEN
    RAISE EXCEPTION 'platform_forbidden: conta de plataforma não pode virar administrador de empresa';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = p_organization_id AND o.ativo IS TRUE) THEN
    RAISE EXCEPTION 'platform_invalid: empresa inexistente ou inativa';
  END IF;
  SELECT lower(u.email), u.created_at INTO v_auth_email, v_auth_created FROM auth.users u WHERE u.id = p_user_id;
  IF v_auth_email IS NULL OR v_auth_email <> v_email OR v_auth_created < now() - interval '10 minutes' THEN
    RAISE EXCEPTION 'platform_conflict: conta não é nova';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = p_user_id)
     OR EXISTS (SELECT 1 FROM public.profiles WHERE user_id = p_user_id AND (organization_id IS NOT NULL OR cliente_id IS NOT NULL))
     OR EXISTS (SELECT 1 FROM public.platform_org_admin_invites WHERE lower(email) = v_email) THEN
    RAISE EXCEPTION 'platform_conflict: usuário já existente';
  END IF;

  INSERT INTO public.profiles AS prof (user_id, nome, email, telefone, cargo, cpf_cnpj, ativo, organization_id, senha_provisoria)
  VALUES (p_user_id, btrim(p_nome), v_email, v_tel,
          CASE WHEN p_responsavel_principal THEN 'Responsável Principal' ELSE 'Administrador' END,
          v_cpf, true, p_organization_id, true)
  ON CONFLICT (user_id) DO UPDATE SET nome = EXCLUDED.nome, email = EXCLUDED.email, telefone = EXCLUDED.telefone,
    cargo = EXCLUDED.cargo, cpf_cnpj = EXCLUDED.cpf_cnpj, ativo = true,
    organization_id = EXCLUDED.organization_id, senha_provisoria = true, updated_at = now();

  INSERT INTO public.user_roles (user_id, role) VALUES (p_user_id, 'administrador'::public.app_role);

  INSERT INTO platform_private.provisional_password_state (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO UPDATE SET desde = now(), pwd_digest = NULL;

  IF p_responsavel_principal THEN
    UPDATE public.organizations SET responsavel_user_id = p_user_id, responsavel_definido_em = now(), updated_at = now()
     WHERE id = p_organization_id;
  END IF;

  INSERT INTO public.platform_org_admin_invites
    (organization_id, user_id, email, nome, cpf_cnpj, telefone, modo_acesso, responsavel_principal, invited_by, status)
  VALUES (p_organization_id, p_user_id, v_email, btrim(p_nome), v_cpf, v_tel, p_modo_acesso, p_responsavel_principal, p_actor_id, 'pendente');
END $_$;


ALTER FUNCTION public.platform_register_org_admin(p_actor_id uuid, p_user_id uuid, p_organization_id uuid, p_email text, p_nome text, p_cpf_cnpj text, p_telefone text, p_modo_acesso text, p_responsavel_principal boolean) OWNER TO postgres;

--
-- Name: platform_save_plan_version_draft(uuid, text, numeric, text, text, integer, jsonb, timestamp with time zone, jsonb, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_save_plan_version_draft(_draft_id uuid, _plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _trial_days integer, _limits jsonb, _effective_from timestamp with time zone, _features jsonb, _reason text, _idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_plan public.saas_plans%ROWTYPE;
  v_draft public.saas_plan_versions%ROWTYPE;
  v_id uuid;
  v_old jsonb;
  v_number integer;
  v_feature_keys jsonb;
  v_features_snapshot jsonb;
  v_existing uuid;
  v_reason text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  IF _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'platform_invalid: chave idempotente obrigatória' USING ERRCODE='22023';
  END IF;
  v_reason := platform_private.normalize_commercial_reason(_reason);
  IF _features IS NULL OR jsonb_typeof(_features) <> 'array' THEN
    RAISE EXCEPTION 'platform_invalid: funcionalidades inválidas' USING ERRCODE='22023';
  END IF;

  SELECT p.* INTO v_plan
  FROM public.saas_plans p
  WHERE p.key=_plan_key AND p.active;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'platform_invalid: plano inexistente ou inativo' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('saas_plan_version:' || v_plan.id::text,0));

  SELECT coalesce(jsonb_agg(DISTINCT btrim(item->>'feature_key')),'[]'::jsonb)
    INTO v_feature_keys
  FROM jsonb_array_elements(_features) item
  WHERE coalesce((item->>'enabled')::boolean,true)
    AND nullif(btrim(item->>'feature_key'),'') IS NOT NULL;

  PERFORM platform_private.validate_commercial_plan_payload(v_plan.id,_limits,v_feature_keys);

  SELECT a.plan_version_id INTO v_existing
  FROM public.saas_plan_version_audit a
  JOIN public.saas_plan_versions pv ON pv.id=a.plan_version_id
  WHERE a.idempotency_key=_idempotency_key
    AND a.actor_user_id=auth.uid()
    AND a.action IN ('draft_created','draft_updated')
    AND pv.plan_id=v_plan.id
  ORDER BY a.created_at DESC
  LIMIT 1;
  IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

  IF _draft_id IS NULL THEN
    SELECT id INTO v_id FROM public.saas_plan_versions
    WHERE plan_id=v_plan.id AND status='DRAFT'
    FOR UPDATE;
    IF v_id IS NOT NULL THEN
      RAISE EXCEPTION 'platform_conflict: já existe rascunho para este plano' USING ERRCODE='40001';
    END IF;
    SELECT coalesce(max(version_number),0)+1 INTO v_number
    FROM public.saas_plan_versions WHERE plan_id=v_plan.id;
    v_id:=gen_random_uuid();
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_create',v_plan.id);
    INSERT INTO public.saas_plan_versions(
      id,plan_id,version_number,name_snapshot,description_snapshot,price_amount,currency,
      billing_cycle,trial_days,limits_snapshot,features_snapshot,effective_from,status,
      revision,draft_key,created_by,updated_at
    ) VALUES (
      v_id,v_plan.id,v_number,v_plan.name,v_plan.description,_price_amount,
      nullif(upper(btrim(coalesce(_currency,''))),''),nullif(_billing_cycle,''),_trial_days,
      _limits,'[]'::jsonb,_effective_from,'DRAFT',1,_idempotency_key,auth.uid(),now()
    );
  ELSE
    SELECT * INTO v_draft
    FROM public.saas_plan_versions
    WHERE id=_draft_id AND plan_id=v_plan.id
    FOR UPDATE;
    IF NOT FOUND OR v_draft.status <> 'DRAFT' THEN
      RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023';
    END IF;
    v_id:=v_draft.id;
    v_old:=to_jsonb(v_draft);
    PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
    UPDATE public.saas_plan_versions SET
      price_amount=_price_amount,
      currency=nullif(upper(btrim(coalesce(_currency,''))),'') ,
      billing_cycle=nullif(_billing_cycle,''),
      trial_days=_trial_days,
      limits_snapshot=_limits,
      effective_from=_effective_from,
      revision=revision+1,
      updated_at=now()
    WHERE id=v_id;
  END IF;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
  DELETE FROM public.saas_plan_version_features WHERE plan_version_id=v_id;
  INSERT INTO public.saas_plan_version_features(plan_version_id,feature_id,enabled,limit_value,config)
  SELECT v_id,f.id,true,NULL,'{}'::jsonb
  FROM jsonb_array_elements_text(v_feature_keys) selected(feature_key)
  JOIN public.saas_features f ON f.key=selected.feature_key;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'feature_id',vf.feature_id,
    'feature_key',f.key,
    'feature_name',f.name,
    'module_key',m.key,
    'module_name',m.name,
    'enabled',vf.enabled,
    'limit_value',vf.limit_value,
    'config',vf.config
  ) ORDER BY m.key,f.key),'[]'::jsonb)
  INTO v_features_snapshot
  FROM public.saas_plan_version_features vf
  JOIN public.saas_features f ON f.id=vf.feature_id
  JOIN public.saas_modules m ON m.id=f.module_id
  WHERE vf.plan_version_id=v_id;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_write',v_plan.id);
  UPDATE public.saas_plan_versions
  SET features_snapshot=v_features_snapshot,updated_at=now()
  WHERE id=v_id;

  PERFORM platform_private.issue_saas_plan_version_ticket('saas_plan_version_audit',v_plan.id);
  INSERT INTO public.saas_plan_version_audit(
    plan_version_id,action,old_values,new_values,reason,origin,actor_user_id,idempotency_key
  ) VALUES (
    v_id,CASE WHEN _draft_id IS NULL THEN 'draft_created' ELSE 'draft_updated' END,
    v_old,(SELECT to_jsonb(current_version) FROM public.saas_plan_versions current_version WHERE current_version.id=v_id),
    v_reason,'platform_rpc',auth.uid(),_idempotency_key
  );
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.platform_save_plan_version_draft(_draft_id uuid, _plan_key text, _price_amount numeric, _currency text, _billing_cycle text, _trial_days integer, _limits jsonb, _effective_from timestamp with time zone, _features jsonb, _reason text, _idempotency_key uuid) OWNER TO postgres;

--
-- Name: platform_set_catalog_label_active(uuid, timestamp with time zone, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_set_catalog_label_active(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $$
DECLARE v_actor uuid; v_req jsonb; v_replay jsonb; v_receipt jsonb; v_audit uuid := gen_random_uuid();
  v_op public.catalog_family_labels%ROWTYPE; v_np public.catalog_family_labels%ROWTYPE;
BEGIN
  v_actor := platform_private.catalog_metadata_require_actor();
  IF p_id IS NULL OR p_expected_updated_at IS NULL OR NOT pg_catalog.isfinite(p_expected_updated_at)
     OR p_ativo IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_invalid';
  END IF;
  -- Gate canônico de revogação: writers de user_roles/profiles (a00_cf_user_gate) e convites
  -- (a00_cf_invitation_gate) adquirem cf_user_guards_v1.state. Ordem: gate -> idempotência -> linha.
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'PT503', MESSAGE = 'catalog_label_gate_unavailable'; END IF;
  -- Autoridade fresca (novo snapshot por statement) após a espera do gate.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  -- Mesma chave do catalog_entity_replay (reentrante na transação): espera aqui, revalida antes do replay.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('catalog-metadata:'||p_idempotency_key::text,0));
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  v_req := pg_catalog.jsonb_build_object('id', p_id, 'expected_updated_at', p_expected_updated_at,
    'ativo', p_ativo, 'reason', pg_catalog.btrim(COALESCE(p_reason, '')));
  v_replay := platform_private.catalog_entity_replay(v_actor, 'set_catalog_label_active', v_req, p_reason, p_idempotency_key);
  IF v_replay IS NOT NULL THEN RETURN v_replay; END IF;

  -- FOR UPDATE serializa com catalog_family_label_check (FOR KEY SHARE): ver comentário lá.
  SELECT * INTO v_op FROM public.catalog_family_labels WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_label_unavailable'; END IF;
  -- Revalida após a espera do lock de linha, antes do CAS/UPDATE.
  IF platform_private.catalog_metadata_require_actor() IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'catalog_metadata_forbidden'; END IF;
  IF v_op.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_conflict'; END IF;
  IF v_op.ativo IS NOT DISTINCT FROM p_ativo THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'catalog_label_no_change'; END IF;

  -- Inativação NÃO altera atribuições existentes em produtos; o trigger de
  -- validação só barra NOVAS atribuições de rótulo inativo.
  UPDATE public.catalog_family_labels SET ativo = p_ativo
   WHERE id = p_id AND updated_at = p_expected_updated_at
  RETURNING * INTO v_np;
  IF NOT FOUND OR v_np.updated_at IS NULL OR v_np.updated_at <= v_op.updated_at
     OR v_np.rotulo IS DISTINCT FROM v_op.rotulo OR v_np.familia IS DISTINCT FROM v_op.familia
     OR v_np.rotulo_exibicao IS DISTINCT FROM v_op.rotulo_exibicao THEN
    RAISE EXCEPTION USING ERRCODE = 'PT409', MESSAGE = 'catalog_label_confirmation_failed'; END IF;

  v_receipt := pg_catalog.jsonb_build_object('id', p_id, 'familia', v_np.familia, 'rotulo', v_np.rotulo,
    'ativo', p_ativo, 'updated_at', v_np.updated_at, 'idempotency_key', p_idempotency_key,
    'audit_id', v_audit, 'idempotent', false);
  PERFORM platform_private.catalog_entity_audit(v_actor, 'set_catalog_label_active', p_reason, p_idempotency_key,
    v_req, v_receipt,
    pg_catalog.jsonb_build_object('id', p_id, 'ativo', v_op.ativo, 'updated_at', v_op.updated_at),
    pg_catalog.jsonb_build_object('id', p_id, 'ativo', p_ativo, 'updated_at', v_np.updated_at));
  RETURN v_receipt;
END $$;


ALTER FUNCTION public.platform_set_catalog_label_active(p_id uuid, p_expected_updated_at timestamp with time zone, p_ativo boolean, p_reason text, p_idempotency_key uuid) OWNER TO postgres;

