--
-- Name: platform_validate_plan_version_draft(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_validate_plan_version_draft(_draft_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v public.saas_plan_versions%ROWTYPE;
  v_missing text[] := ARRAY[]::text[];
  v_feature_keys jsonb;
  v_feature_count integer;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_platform_superadmin(auth.uid()) THEN
    RAISE EXCEPTION 'platform_forbidden: apenas superadmin' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v FROM public.saas_plan_versions WHERE id=_draft_id;
  IF NOT FOUND OR v.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'platform_invalid: rascunho inexistente' USING ERRCODE='22023';
  END IF;

  SELECT count(*),coalesce(jsonb_agg(f.key ORDER BY f.key) FILTER (WHERE vf.enabled),'[]'::jsonb)
    INTO v_feature_count,v_feature_keys
  FROM public.saas_plan_version_features vf
  JOIN public.saas_features f ON f.id=vf.feature_id
  WHERE vf.plan_version_id=v.id AND vf.enabled;

  IF v.price_amount IS NULL OR v.price_amount <= 0 THEN v_missing:=array_append(v_missing,'price_amount'); END IF;
  IF v.currency IS NULL OR v.currency NOT IN ('BRL','USD','EUR') THEN v_missing:=array_append(v_missing,'currency'); END IF;
  IF v.billing_cycle IS NULL OR v.billing_cycle NOT IN ('monthly','quarterly','semiannual','annual','custom') THEN v_missing:=array_append(v_missing,'billing_cycle'); END IF;
  IF v.trial_days IS NULL OR v.trial_days < 1 OR v.trial_days > 365 THEN v_missing:=array_append(v_missing,'trial_days'); END IF;
  IF v.effective_from IS NULL THEN v_missing:=array_append(v_missing,'effective_from'); END IF;
  IF v.limits_snapshot IS NULL OR jsonb_typeof(v.limits_snapshot) <> 'object' THEN v_missing:=array_append(v_missing,'limits'); END IF;
  IF v_feature_count=0 THEN v_missing:=array_append(v_missing,'features'); END IF;

  IF cardinality(v_missing)=0 THEN
    BEGIN
      PERFORM platform_private.validate_commercial_plan_payload(v.plan_id,v.limits_snapshot,v_feature_keys);
    EXCEPTION WHEN SQLSTATE '22023' THEN
      v_missing:=array_append(v_missing,'commercial_payload');
    END;
  END IF;

  RETURN jsonb_build_object(
    'complete',cardinality(v_missing)=0,
    'valid',cardinality(v_missing)=0,
    'missing',to_jsonb(v_missing),
    'feature_count',v_feature_count,
    'revision',v.revision
  );
END;
$$;


ALTER FUNCTION public.platform_validate_plan_version_draft(_draft_id uuid) OWNER TO postgres;

--
-- Name: platform_wipe_global_product_catalog(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.platform_wipe_global_product_catalog(p_actor_id uuid, p_reason text, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_table text;
  v_count bigint;
  v_before jsonb := '{}'::jsonb;
  v_deleted jsonb := '{}'::jsonb;
  v_total_deleted bigint := 0;
  v_existing jsonb;
  v_tables constant text[] := ARRAY[
    'catalogo_volumes',
    'product_crop_recommendations',
    'product_fiscal_profiles',
    'product_target_recommendations',
    'product_technical_profiles',
    'formulacoes',
    'produtos'
  ];
BEGIN
  IF p_actor_id IS NULL OR NOT public.is_platform_superadmin(p_actor_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_correlation_id IS NULL THEN
    RAISE EXCEPTION 'correlation_id_required' USING ERRCODE = '22023';
  END IF;
  IF p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION 'invalid_reason' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('platform_wipe_global_product_catalog', 0));

  SELECT jsonb_build_object(
    'ok', true,
    'idempotent', true,
    'correlation_id', correlation_id,
    'deleted', counts_after -> 'deleted',
    'total_deleted', COALESCE((counts_after ->> 'total_deleted')::bigint, 0)
  )
  INTO v_existing
  FROM public.catalog_platform_admin_audit
  WHERE correlation_id = p_correlation_id
    AND operation = 'wipe_global_products'
    AND status = 'completed';

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  FOREACH v_table IN ARRAY v_tables LOOP
    EXECUTE format('SELECT count(*) FROM public.%I', v_table) INTO v_count;
    v_before := v_before || jsonb_build_object(v_table, v_count);
  END LOOP;

  FOREACH v_table IN ARRAY v_tables LOOP
    EXECUTE format('DELETE FROM public.%I WHERE id IS NOT NULL', v_table);
    GET DIAGNOSTICS v_count = ROW_COUNT;
    v_deleted := v_deleted || jsonb_build_object(v_table, v_count);
    v_total_deleted := v_total_deleted + v_count;
  END LOOP;

  INSERT INTO public.catalog_platform_admin_audit (
    operation, actor_id, reason, correlation_id, status,
    counts_before, counts_after, completed_at
  ) VALUES (
    'wipe_global_products', p_actor_id, btrim(p_reason), p_correlation_id, 'completed',
    v_before,
    jsonb_build_object('deleted', v_deleted, 'total_deleted', v_total_deleted),
    now()
  );

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'correlation_id', p_correlation_id,
    'deleted', v_deleted,
    'total_deleted', v_total_deleted
  );
END;
$$;


ALTER FUNCTION public.platform_wipe_global_product_catalog(p_actor_id uuid, p_reason text, p_correlation_id uuid) OWNER TO postgres;

--
-- Name: pode_acessar_recomendacao(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pode_acessar_recomendacao(_user_id uuid, _recomendacao_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT public.fn_authz_uid_scope_ok(_user_id) AND EXISTS (
    SELECT 1
    FROM public.registros_consultor_recomendacoes r
    JOIN public.registros_consultor rc ON rc.id = r.registro_consultor_id
    WHERE r.id = _recomendacao_id
      AND (
        public.has_role(_user_id, 'administrador'::app_role)
        OR public.has_role(_user_id, 'gestor'::app_role)
        OR public.has_role(_user_id, 'tecnico_agronomo'::app_role)
        OR public.has_role(_user_id, 'consultor_tecnico'::app_role)
        OR EXISTS (
          SELECT 1 FROM public.user_clientes uc
          WHERE uc.user_id = _user_id
            AND uc.cliente_id = rc.cliente_id
            AND uc.is_active = true
            AND uc.revoked_at IS NULL
            AND (uc.valid_from IS NULL OR uc.valid_from <= now())
            AND (uc.valid_until IS NULL OR uc.valid_until >= now())
        )
      )
  );
$$;


ALTER FUNCTION public.pode_acessar_recomendacao(_user_id uuid, _recomendacao_id uuid) OWNER TO postgres;

