-- Name: prefixo_para_microrganismo(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prefixo_para_microrganismo(_tipo text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE lower(coalesce(_tipo,''))
    WHEN 'bacteria' THEN 'BAC'
    WHEN 'fungo' THEN 'FUN'
    WHEN 'levedura' THEN 'LEV'
    WHEN 'consorcio' THEN 'CON'
    ELSE NULL
  END;
$$;


