--
-- Name: register_my_login_redirect_secure(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_my_login_redirect_secure(p_context text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_available jsonb;
BEGIN
  IF v_uid IS NULL OR NOT platform_private.platform_actor_access_ready(v_uid) OR public.h15_actor_organization() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF p_context IS NULL OR p_context NOT IN ('b2b','technical','producer','admin') THEN
    RAISE EXCEPTION 'invalid context %', p_context;
  END IF;

  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'c2_guard_unavailable'; END IF;
  v_available := public.get_my_available_portal_contexts();

  IF NOT (v_available->'available_contexts' ? p_context) THEN
    INSERT INTO public.user_context_access_logs (
      user_id, context_code, action, previous_context, metadata
    ) VALUES (
      v_uid, p_context, 'access_denied', NULL,
      jsonb_build_object('reason','context_not_available','source','login_redirect')
    );

    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'context_not_available',
      'context', p_context
    );
  END IF;

  -- Metadata fixa; frontend não escolhe.
  INSERT INTO public.user_context_access_logs (
    user_id, context_code, action, previous_context, metadata
  ) VALUES (
    v_uid, p_context, 'login_redirect', NULL,
    jsonb_build_object('source','auto')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'context', p_context,
    'action', 'login_redirect'
  );
END;
$$;


ALTER FUNCTION public.register_my_login_redirect_secure(p_context text) OWNER TO postgres;

--
-- Name: regulatory_audit_trigger(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.regulatory_audit_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_actor uuid; v_id uuid;
BEGIN
  BEGIN v_actor := auth.uid(); EXCEPTION WHEN OTHERS THEN v_actor := NULL; END;
  IF TG_OP = 'DELETE' THEN
    v_id := OLD.id;
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values)
    VALUES (TG_TABLE_NAME, v_id, 'DELETE', v_actor, public.mask_sensitive_jsonb(to_jsonb(OLD)));
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', v_actor,
            public.mask_sensitive_jsonb(to_jsonb(OLD)), public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  ELSE
    INSERT INTO public.fiscal_audit_log(table_name, record_id, action, changed_by, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', v_actor, public.mask_sensitive_jsonb(to_jsonb(NEW)));
    RETURN NEW;
  END IF;
END $$;


ALTER FUNCTION public.regulatory_audit_trigger() OWNER TO postgres;

--
-- Name: regulatory_block_published_child_edit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.regulatory_block_published_child_edit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_status text; v_dossier uuid;
BEGIN
  IF coalesce(current_setting('app.regulatory_formal_op', true),'') = 'on' THEN
    RETURN COALESCE(NEW, OLD);
  END IF;
  v_dossier := (to_jsonb(COALESCE(NEW, OLD)) ->> 'dossier_id')::uuid;
  SELECT status INTO v_status FROM public.microorganism_regulatory_dossiers WHERE id = v_dossier;
  IF v_status = 'VALIDATED' THEN
    RAISE EXCEPTION 'REGULATORY_PUBLISHED_IMMUTABLE' USING ERRCODE='55006';
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;


ALTER FUNCTION public.regulatory_block_published_child_edit() OWNER TO postgres;

--
-- Name: regulatory_block_published_edit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.regulatory_block_published_edit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF coalesce(current_setting('app.regulatory_formal_op', true),'') = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'VALIDATED' THEN
    RAISE EXCEPTION 'REGULATORY_PUBLISHED_IMMUTABLE'
      USING ERRCODE='55006',
            HINT='Versao publicada so muda por rpc_regulatory_dossier_new_version ou rpc_regulatory_dossier_block.';
  END IF;
  RETURN NEW;
END $$;


