-- Name: rejeitar_ficha_versao(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rejeitar_ficha_versao(p_versao_id uuid, p_observacao text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador') OR public.has_role(auth.uid(), 'gestor')) THEN
    RAISE EXCEPTION 'Sem permissão para rejeitar versões';
  END IF;
  UPDATE public.ficha_tecnica_versoes
  SET status = 'rejeitada',
      revisado_por = auth.uid(),
      revisado_em = now(),
      observacao = COALESCE(p_observacao, observacao)
  WHERE id = p_versao_id AND status = 'pendente';
END;
$$;


