--
-- Name: request_b2b_payment_terms_adjustment_secure(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_b2b_payment_terms_adjustment_secure(p_partner_order_id uuid, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_terms_id uuid;
  v_created_by uuid;
  v_numero text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF NOT (public.has_role(v_uid,'administrador')
       OR public.has_role(v_uid,'financeiro')
       OR public.has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_notes IS NULL OR btrim(p_notes) = '' THEN
    RAISE EXCEPTION 'notes_required';
  END IF;

  SELECT po.payment_terms_id, po.created_by, po.numero
    INTO v_terms_id, v_created_by, v_numero
  FROM public.partner_orders po
  WHERE po.id = p_partner_order_id;

  IF v_terms_id IS NULL THEN RAISE EXCEPTION 'payment_terms_not_defined'; END IF;

  UPDATE public.partner_order_payment_terms
     SET approval_status = 'pending',
         approval_notes = p_notes,
         updated_at = now()
   WHERE id = v_terms_id;

  UPDATE public.partner_orders
     SET financial_approval_status = 'pending',
         payment_condition_status = 'adjustment_requested',
         updated_at = now()
   WHERE id = p_partner_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, acao, usuario_id, dados_novos)
  VALUES (p_partner_order_id, 'payment_terms_adjustment_requested', v_uid,
          jsonb_build_object('notes', p_notes));

  IF v_created_by IS NOT NULL THEN
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_created_by, 'b2b_payment_terms',
            'Ajuste na condição solicitado',
            format('Pedido %s precisa de ajuste na condição de pagamento: %s',
                   COALESCE(v_numero,'B2B'), p_notes),
            '/comercial/pedidos-b2b');
  END IF;

  RETURN jsonb_build_object('success', true, 'status', 'adjustment_requested');
END;
$$;


ALTER FUNCTION public.request_b2b_payment_terms_adjustment_secure(p_partner_order_id uuid, p_notes text) OWNER TO postgres;

--
-- Name: request_partner_order_items(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_partner_order_items(p_order_id uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev partner_order_status; v_numero text; v_partner_user uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) = 0 THEN
    RAISE EXCEPTION 'reason_required';
  END IF;

  SELECT partner_id, status, numero INTO v_pid, v_prev, v_numero
    FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  IF v_prev NOT IN ('em_analise_comercial','solicitado','rascunho') THEN
    RAISE EXCEPTION 'invalid_status_transition: %', v_prev;
  END IF;

  UPDATE public.partner_orders
     SET status = 'aguardando_itens',
         itens_pendentes_motivo = p_motivo,
         itens_pendentes_solicitado_em = now(),
         itens_pendentes_solicitado_por = v_uid,
         itens_pendentes_resolvido_em = NULL,
         updated_at = now()
   WHERE id = p_order_id
     AND status = v_prev;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'concurrent_update: status do pedido mudou';
  END IF;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'request_items',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status','aguardando_itens','motivo',p_motivo));

  FOR v_partner_user IN SELECT user_id FROM public.partner_users WHERE partner_id = v_pid LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user, 'pedido_b2b_itens_pendentes',
            'Pedido ' || v_numero || ' — itens pendentes',
            COALESCE(p_motivo, 'O Comercial solicitou que você complete o pedido com os itens necessários.'),
            '/portal-parceiro/pedidos');
  END LOOP;
END;
$$;


ALTER FUNCTION public.request_partner_order_items(p_order_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: reservar_estoque_item(uuid, numeric, uuid, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reservar_estoque_item(p_item_id uuid, p_qty numeric, p_os_id uuid, p_os_tipo text, p_cliente_id uuid DEFAULT NULL::uuid, p_partner_id uuid DEFAULT NULL::uuid, p_partner_order_id uuid DEFAULT NULL::uuid, p_observacao text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item public.estoque_produto%ROWTYPE;
  v_volume_reservado numeric;
  v_new_id uuid;
  v_parent_ctx jsonb;
BEGIN
  PERFORM platform_private.stock_motor_actor('reserva');
  IF p_qty IS NULL OR p_qty::text IN ('NaN','Infinity','-Infinity') OR p_qty <= 0 THEN
    RAISE EXCEPTION 'ESTQ_QUANTIDADE_INVALIDA: quantidade deve ser finita e maior que zero.' USING ERRCODE='23514';
  END IF;
  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF auth.uid() IS NULL OR NOT public.fn_estoque_pode_operar(auth.uid(), 'reserva') THEN
    RAISE EXCEPTION 'ESTQ_SEM_PERMISSAO: perfil sem permissão para reservar estoque'
      USING ERRCODE = '42501';
  END IF;

  SELECT c.ctx INTO v_parent_ctx FROM platform_private.stock_motor_context c WHERE c.txid=txid_current() AND c.actor=auth.uid() AND c.item=p_item_id;
  IF v_parent_ctx IS NOT NULL AND (v_parent_ctx->>'acao' IS DISTINCT FROM 'reserva' OR v_parent_ctx->'reserve_args' IS DISTINCT FROM jsonb_strip_nulls(jsonb_build_object('os_id',p_os_id::text,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id::text,'partner_id',p_partner_id::text,'partner_order_id',p_partner_order_id::text,'observacao',p_observacao))) THEN RAISE EXCEPTION 'ESTQ_PAYLOAD_INVALIDO' USING ERRCODE='22023'; END IF;
  IF v_parent_ctx IS NULL THEN
   v_parent_ctx:=jsonb_build_object('acao','reserva','origem','reservar_estoque_item','usuario_id',auth.uid()::text,'metadata',jsonb_build_object('stock_request_item',p_item_id::text,'stock_request_actor',auth.uid()::text));
  END IF;
  PERFORM public.fn_estoque_ctx_force(v_parent_ctx);
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade a reservar deve ser maior que zero.'
      USING ERRCODE = 'check_violation';
  END IF;
  IF p_os_id IS NULL THEN
    RAISE EXCEPTION 'Reserva requer uma OS vinculada.'
      USING ERRCODE = 'check_violation';
  END IF;

  SELECT * INTO v_item
  FROM public.estoque_produto
  WHERE id = p_item_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de estoque % não encontrado.', p_item_id
      USING ERRCODE = 'no_data_found';
  END IF;

  PERFORM platform_private.stock_motor_item(p_item_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo',p_os_tipo,'cliente_id',p_cliente_id,'partner_id',p_partner_id,'partner_order_id',p_partner_order_id));
  IF v_item.status::text <> 'disponivel' THEN
    RAISE EXCEPTION 'Item % não está disponível para reserva (status: %).', p_item_id, v_item.status
      USING ERRCODE = 'check_violation';
  END IF;

  IF p_qty > COALESCE(v_item.quantidade, 0) THEN
    RAISE EXCEPTION 'Quantidade solicitada (%) excede o disponível (%) para esta embalagem.',
      p_qty, COALESCE(v_item.quantidade, 0)
      USING ERRCODE = 'check_violation';
  END IF;

  v_volume_reservado := CASE
    WHEN COALESCE(v_item.volume_total, 0) > 0 AND COALESCE(v_item.quantidade, 0) > 0
      THEN (p_qty * v_item.volume_total) / v_item.quantidade
    ELSE NULL
  END;

  IF p_qty = v_item.quantidade THEN
    UPDATE public.estoque_produto SET
      status = 'reservado',
      reservado_para_os_id = p_os_id,
      reservado_para_os_tipo = p_os_tipo,
      reservado_para_cliente_id = CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      reservado_para_partner_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      reservado_para_partner_order_id = CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      quantidade_reservada = p_qty,
      observacao_reserva = p_observacao
    WHERE id = p_item_id;
    v_new_id := p_item_id;
  ELSE
    INSERT INTO public.estoque_produto (
      produto_id, lote_id, microrganismo_id, envase_id,
      quantidade, volume_total, validade, status,
      reservado_para_os_id, reservado_para_os_tipo,
      reservado_para_cliente_id, reservado_para_partner_id, reservado_para_partner_order_id,
      quantidade_reservada, observacao_reserva
    ) VALUES (
      v_item.produto_id, v_item.lote_id, v_item.microrganismo_id, v_item.envase_id,
      p_qty, v_volume_reservado, v_item.validade, 'reservado',
      p_os_id, p_os_tipo,
      CASE WHEN p_os_tipo = 'b2b' THEN NULL ELSE p_cliente_id END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_id ELSE NULL END,
      CASE WHEN p_os_tipo = 'b2b' THEN p_partner_order_id ELSE NULL END,
      p_qty, p_observacao
    ) RETURNING id INTO v_new_id;

    UPDATE public.estoque_produto SET
      quantidade = v_item.quantidade - p_qty,
      volume_total = CASE
        WHEN COALESCE(v_item.volume_total, 0) > 0 THEN v_item.volume_total - v_volume_reservado
        ELSE volume_total
      END
    WHERE id = p_item_id;
  END IF;

  PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close();
  RETURN v_new_id;
EXCEPTION WHEN OTHERS THEN PERFORM platform_private.stock_motor_context_set(NULL); PERFORM public.fn_estoque_ctx_close(); RAISE;
END;
$$;


ALTER FUNCTION public.reservar_estoque_item(p_item_id uuid, p_qty numeric, p_os_id uuid, p_os_tipo text, p_cliente_id uuid, p_partner_id uuid, p_partner_order_id uuid, p_observacao text) OWNER TO postgres;

--
-- Name: respond_b2b_order_quote_secure(uuid, jsonb, date, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.respond_b2b_order_quote_secure(p_order_id uuid, p_lines jsonb, p_first_due_date date DEFAULT NULL::date, p_installment_count integer DEFAULT NULL::integer, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean; v_is_gestor boolean;
  v_order record; v_plan record;
  v_line jsonb; v_item record; v_price numeric(14,4);
  v_count_lines integer; v_count_distinct integer; v_count_items integer;
  v_prev jsonb;
  v_table numeric(14,2); v_net numeric(14,2); v_final numeric(14,2); v_interest numeric(14,2);
  v_installments integer; v_first_due date; v_terms_id uuid;
  v_fin_status text; v_approval_status text;
  v_inst numeric(14,2); v_accum numeric(14,2) := 0;
  v_amount_i numeric(14,2); v_principal_i numeric(14,2); v_interest_i numeric(14,2);
  v_due_i date; i integer; v_final_status text; v_block_reason text := NULL;
  v_partner_user record; v_credit jsonb; v_new_status partner_order_status;
BEGIN

  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF; PERFORM platform_private.b2b_internal_assert_origin((SELECT internal_origin_snapshot FROM public.partner_orders WHERE id=p_order_id),(SELECT partner_id FROM public.partner_orders WHERE id=p_order_id),(SELECT cliente_id FROM public.partner_orders WHERE id=p_order_id)); IF NOT public.b2b_phase1_order_visible(p_order_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;

  v_is_admin  := has_role(v_uid,'administrador'::app_role);
  v_is_gestor := has_role(v_uid,'gestor_comercial'::app_role);
  IF NOT (v_is_admin OR v_is_gestor) THEN
    RAISE EXCEPTION 'forbidden_quote_response';
  END IF;

  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'quote_incomplete';
  END IF;

  -- locks em ordem deterministica: (1) pedido/cotacao
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_quote:' || p_order_id::text, 0));

  SELECT * INTO v_order FROM public.partner_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
  IF v_order.status <> 'aguardando_cotacao'::partner_order_status THEN
    RAISE EXCEPTION 'order_not_in_quote_state';
  END IF;
  IF EXISTS(SELECT 1 FROM public.partner_order_payment_terms WHERE partner_order_id=p_order_id) THEN RAISE EXCEPTION 'B2B_INTERNAL_QUOTE_REVISION_UNAVAILABLE' USING ERRCODE='42501'; END IF; IF v_order.payment_plan_id IS NULL THEN RAISE EXCEPTION 'payment_plan_required'; END IF;

  -- (2) credito do parceiro
  PERFORM pg_advisory_xact_lock(hashtextextended('b2b_credit:' || v_order.partner_id::text, 0));

  SELECT * INTO v_plan FROM public.commercial_payment_plans WHERE id = v_order.payment_plan_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF; IF NOT public.fn_b2b_plan_selectable(v_plan.id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;
  IF v_plan.active = false THEN RAISE EXCEPTION 'plan_inactive'; END IF;

  SELECT count(*) INTO v_count_items FROM public.partner_order_items WHERE order_id = p_order_id;
  IF v_count_items = 0 THEN RAISE EXCEPTION 'empty_cart'; END IF;

  SELECT count(*), count(DISTINCT (l->>'item_id')::uuid)
    INTO v_count_lines, v_count_distinct
    FROM jsonb_array_elements(p_lines) l;
  IF v_count_lines <> v_count_distinct THEN RAISE EXCEPTION 'quote_duplicate_line'; END IF;
  IF v_count_distinct <> v_count_items THEN RAISE EXCEPTION 'quote_incomplete'; END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'item_id', poi.id, 'preco_unitario', poi.preco_unitario,
           'subtotal', poi.subtotal,
           'pricing_mode_snapshot', poi.pricing_mode_snapshot,
           'price_source_snapshot', poi.price_source_snapshot)), '[]'::jsonb)
    INTO v_prev
    FROM public.partner_order_items poi WHERE poi.order_id = p_order_id;

  FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
    BEGIN
      v_price := NULLIF(v_line->>'unit_price','')::numeric;
    EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'invalid_quote_price'; END;
    IF v_price IS NULL OR v_price <= 0 OR v_price > 10000000 THEN
      RAISE EXCEPTION 'invalid_quote_price';
    END IF;
    IF v_price <> ROUND(v_price, 4) THEN RAISE EXCEPTION 'invalid_quote_price_scale'; END IF;

    SELECT * INTO v_item FROM public.partner_order_items
     WHERE id = (v_line->>'item_id')::uuid AND order_id = p_order_id
     FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'quote_item_not_found'; END IF;

    UPDATE public.partner_order_items SET
      preco_unitario                 = v_price,
      desconto_percentual            = 0,
      subtotal                       = ROUND(v_item.quantidade * v_price, 2),
      preco_tabela_snapshot          = v_price,
      desconto_percentual_snapshot   = 0,
      preco_unitario_final_snapshot  = v_price,
      pricing_mode_snapshot          = 'fixed_item_price',
      price_source_snapshot          = 'quote_manual',
      base_price_snapshot            = v_price,
      condition_price_snapshot       = v_price,
      plan_discount_percent_snapshot = 0
    WHERE id = v_item.id;
  END LOOP;

  SELECT COALESCE(SUM(subtotal),0)::numeric(14,2) INTO v_table
    FROM public.partner_order_items WHERE order_id = p_order_id;
  v_net := v_table;

  IF v_plan.minimum_order_amount IS NOT NULL AND v_table < v_plan.minimum_order_amount THEN
    RAISE EXCEPTION 'below_minimum_order_amount';
  END IF;

  v_final := public.fn_b2b_apply_interest(v_net, v_plan.interest_type,
               v_plan.monthly_interest_percent, v_plan.months_count);
  v_interest := ROUND(v_final - v_net, 2);

  IF p_installment_count IS NOT NULL AND p_installment_count <= 0 THEN
    RAISE EXCEPTION 'invalid_installment_count';
  END IF;
  v_installments := GREATEST(COALESCE(p_installment_count, v_plan.installment_count, 1), 1);

  IF p_first_due_date IS NOT NULL AND p_first_due_date < current_date THEN
    RAISE EXCEPTION 'invalid_due_date';
  END IF;
  v_first_due := COALESCE(p_first_due_date, current_date + v_plan.max_days);

  IF v_plan.requires_financial_approval OR v_plan.requires_guarantee THEN
    v_fin_status := 'pending'; v_approval_status := 'pending';
  ELSE
    v_fin_status := 'not_required'; v_approval_status := 'not_required';
  END IF;

  IF v_first_due > current_date + v_plan.max_days THEN
    IF NOT (v_plan.requires_financial_approval OR v_plan.requires_guarantee) THEN
      v_first_due := current_date + v_plan.max_days;
    ELSE
      v_fin_status := 'pending'; v_approval_status := 'pending';
    END IF;
  END IF;

  -- ---- DECISAO DE CREDITO SOBRE O TOTAL RECEM-COTADO -----------------
  -- o proprio pedido e excluido da exposicao para nao ser contado duas vezes
  v_credit := public.fn_b2b_credit_exposure(v_order.partner_id, v_final, p_order_id);

  IF COALESCE((v_credit->>'block_if_overdue')::boolean,false)
     AND COALESCE((v_credit->>'tem_vencidos')::boolean,false) THEN
    RAISE EXCEPTION 'credit_blocked_overdue';
  END IF;

  IF COALESCE((v_credit->>'credit_limit')::numeric,0) > 0
     AND (v_credit->>'exposicao_projetada')::numeric > (v_credit->>'credit_limit')::numeric THEN
    IF COALESCE(v_credit->>'credit_limit_action','block') = 'approval_required' THEN
      v_new_status := 'aguardando_aprovacao_credito'::partner_order_status;
      v_block_reason := 'limite_excedido';
    ELSE
      RAISE EXCEPTION 'credit_limit_exceeded';
    END IF;
  ELSE
    v_new_status := 'em_analise_comercial'::partner_order_status;
  END IF;

  DELETE FROM public.partner_order_payment_schedule WHERE partner_order_id = p_order_id;
  DELETE FROM public.partner_order_payment_terms WHERE partner_order_id = p_order_id;

  INSERT INTO public.partner_order_payment_terms(
    partner_order_id, payment_plan_id, plan_name_snapshot, plan_code_snapshot,
    discount_percent_snapshot, monthly_interest_percent_snapshot, months_count_snapshot,
    installment_count, first_due_date, interest_type_snapshot,
    table_amount, discount_amount, net_amount_after_discount,
    financial_interest_amount, final_amount, approval_status, created_by,
    pricing_mode_snapshot, credit_decision_snapshot
  ) VALUES (
    p_order_id, v_plan.id, v_plan.name, v_plan.code,
    0, v_plan.monthly_interest_percent, v_plan.months_count,
    v_installments, v_first_due, v_plan.interest_type,
    v_table, 0, v_net, v_interest, v_final, v_approval_status, v_uid,
    'fixed_item_price', v_credit
  ) RETURNING id INTO v_terms_id;

  IF v_installments = 1 THEN
    INSERT INTO public.partner_order_payment_schedule(
      partner_order_id, payment_terms_id, installment_number, due_date,
      amount, principal_amount, interest_amount)
    VALUES (p_order_id, v_terms_id, 1, v_first_due, v_final, v_net, v_interest);
  ELSE
    v_inst := ROUND(v_final / v_installments, 2);
    FOR i IN 1..v_installments LOOP
      IF i < v_installments THEN v_amount_i := v_inst; ELSE v_amount_i := ROUND(v_final - v_accum,2); END IF;
      v_accum := v_accum + v_amount_i;
      v_principal_i := ROUND(v_amount_i * (v_net / NULLIF(v_final,0)), 2);
      v_interest_i  := ROUND(v_amount_i - v_principal_i, 2);
      v_due_i := v_first_due + ((i-1)*30);
      INSERT INTO public.partner_order_payment_schedule(
        partner_order_id, payment_terms_id, installment_number, due_date,
        amount, principal_amount, interest_amount)
      VALUES (p_order_id, v_terms_id, i, v_due_i, v_amount_i, v_principal_i, v_interest_i);
    END LOOP;
  END IF;

  UPDATE public.partner_orders SET
    status = v_new_status,
    payment_condition_status = 'defined',
    credit_block_reason = v_block_reason,
    subtotal = v_table, desconto_total = 0, total = v_final,
    payment_terms_id = v_terms_id,
    table_amount = v_table, commercial_discount_amount = 0,
    net_amount_after_discount = v_net, financial_interest_amount = v_interest,
    final_amount_with_interest = v_final,
    requires_financial_approval = (v_plan.requires_financial_approval OR v_plan.requires_guarantee),
    financial_approval_status = v_fin_status
  WHERE id = p_order_id;

  SELECT status::text INTO v_final_status FROM public.partner_orders WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_order.partner_id, v_uid, 'quote_responded',
          jsonb_build_object('items', v_prev,
                             'table_amount', v_order.table_amount,
                             'total', v_order.total,
                             'status', 'aguardando_cotacao'),
          jsonb_build_object('table_amount', v_table, 'final_amount', v_final,
                             'installment_count', v_installments,
                             'first_due_date', v_first_due,
                             'status', v_final_status,
                             'credit_block_reason', v_block_reason,
                             'credit_decision', v_credit,
                             'motivo', NULLIF(p_motivo,'')));

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_novos)
  VALUES (p_order_id, v_order.partner_id, v_uid, 'payment_terms_defined',
          jsonb_build_object('payment_plan_id', v_plan.id, 'plan_code', v_plan.code,
            'table_amount', v_table, 'discount_amount', 0,
            'net_amount_after_discount', v_net, 'financial_interest_amount', v_interest,
            'final_amount', v_final, 'first_due_date', v_first_due,
            'installment_count', v_installments,
            'credit_reason_code', v_credit->>'reason_code',
            'source', 'quote_response'));

  FOR v_partner_user IN
    SELECT pu.user_id FROM public.partner_users pu WHERE pu.partner_id = v_order.partner_id
  LOOP
    INSERT INTO public.notificacoes_operacionais(usuario_id, tipo, titulo, mensagem, link)
    VALUES (v_partner_user.user_id, 'pedido_b2b_cotacao_respondida',
            'Cotação respondida — pedido ' || v_order.numero,
            'A cotação do seu pedido foi respondida. Total: R$ ' || to_char(v_final,'FM999G999G990D00'),
            '/portal-parceiro/pedidos');
  END LOOP;

  RETURN jsonb_build_object(
    'id', p_order_id,
    'numero', v_order.numero,
    'status', v_final_status,
    'credit_block_reason', v_block_reason,
    'credit_reason_code', v_credit->>'reason_code',
    'table_amount', v_table,
    'net_amount_after_discount', v_net,
    'financial_interest_amount', v_interest,
    'final_amount', v_final,
    'installment_count', v_installments,
    'first_due_date', v_first_due,
    'payment_terms_id', v_terms_id,
    'requires_financial_approval', (v_plan.requires_financial_approval OR v_plan.requires_guarantee),
    'financial_approval_status', v_fin_status);
END $_$;


ALTER FUNCTION public.respond_b2b_order_quote_secure(p_order_id uuid, p_lines jsonb, p_first_due_date date, p_installment_count integer, p_motivo text) OWNER TO postgres;

--
-- Name: return_catalog_profile_to_review(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.return_catalog_profile_to_review(p_kind text, p_profile_id uuid, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_exists boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required';
  END IF;
  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'consultor_tecnico'::app_role)
    OR has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_kind NOT IN ('micro','produto') THEN
    RAISE EXCEPTION 'invalid_kind';
  END IF;
  IF p_motivo IS NULL OR length(btrim(p_motivo)) < 5 THEN
    RAISE EXCEPTION 'motivo_too_short';
  END IF;

  IF p_kind = 'micro' THEN
    SELECT EXISTS(SELECT 1 FROM microorganism_technical_profiles WHERE id = p_profile_id) INTO v_exists;
    IF NOT v_exists THEN RAISE EXCEPTION 'profile_not_found'; END IF;
    UPDATE microorganism_technical_profiles
    SET status_validacao = 'em_revisao',
        updated_by = v_uid,
        updated_at = now()
    WHERE id = p_profile_id;
    INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
    VALUES ('ficha_microrganismo', p_profile_id, 'retorno_ajuste', v_uid,
      jsonb_build_object('motivo_retorno_ajuste', btrim(p_motivo)));
  ELSE
    SELECT EXISTS(SELECT 1 FROM product_technical_profiles WHERE id = p_profile_id) INTO v_exists;
    IF NOT v_exists THEN RAISE EXCEPTION 'profile_not_found'; END IF;
    UPDATE product_technical_profiles
    SET status_validacao = 'em_revisao',
        updated_by = v_uid,
        updated_at = now()
    WHERE id = p_profile_id;
    INSERT INTO catalog_technical_audit_logs (entidade_tipo, entidade_id, acao, usuario_id, dados_novos)
    VALUES ('ficha_produto', p_profile_id, 'retorno_ajuste', v_uid,
      jsonb_build_object('motivo_retorno_ajuste', btrim(p_motivo)));
  END IF;
END;
$$;


ALTER FUNCTION public.return_catalog_profile_to_review(p_kind text, p_profile_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.rls_auto_enable() OWNER TO postgres;

--
-- Name: rpc_activate_communication_template(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_activate_communication_template(p_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_templates%rowtype; prev public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'archived' THEN RAISE EXCEPTION 'template arquivado'; END IF;
  SELECT * INTO prev FROM public.comunicacao_templates
    WHERE chave = r.chave AND canal = r.canal AND status = 'active' AND id <> r.id FOR UPDATE;
  IF FOUND THEN
    UPDATE public.comunicacao_templates
       SET status = 'archived', archived_at = now(), updated_by = auth.uid()
     WHERE id = prev.id;
    PERFORM public._comunicacao_write_audit('template.archive_prev_on_activate','comunicacao_templates',prev.id,
      to_jsonb(prev), jsonb_build_object('archived_by_activation_of', p_template_id));
  END IF;
  UPDATE public.comunicacao_templates
     SET status = 'active', updated_by = auth.uid() WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.activate','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$$;


ALTER FUNCTION public.rpc_activate_communication_template(p_template_id uuid) OWNER TO postgres;

--
-- Name: rpc_admin_communication_health_snapshot(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_communication_health_snapshot() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by_status jsonb;
  v_by_canal jsonb;
  v_by_event jsonb;
  v_by_canal_status jsonb;
  v_pending int;
  v_dlq int;
  v_processing int;
  v_oldest_pending_age_s int;
  v_oldest_locked_age_s int;
  v_success_24h int;
  v_failed_24h int;
  v_success_rate numeric;
  v_avg_attempts_sent numeric;
  v_avg_attempts_terminal numeric;
  v_max_attempts int;
  v_avg_latency_ms numeric;
  v_p95_latency_ms numeric;
  v_realtime_ready boolean;
  v_last_replay_at timestamptz;
  v_last_worker_activity timestamptz;
  v_last_sent_at timestamptz;
  v_worker_status text;
  v_worker_age_s int;
  v_flag_delivery boolean;
  v_flag_email boolean;
  v_flag_wa boolean;
  v_flag_inapp boolean;
  v_flag_webhook boolean;
  v_flag_test_mode boolean;
  v_prov_email jsonb;
  v_prov_wa jsonb;
  v_prov jsonb;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();

  SELECT jsonb_object_agg(status,cnt) INTO v_by_status
    FROM (SELECT status::text AS status, count(*) AS cnt
            FROM public.comunicacao_outbox GROUP BY status) s;

  SELECT jsonb_object_agg(canal,cnt) INTO v_by_canal
    FROM (SELECT canal::text AS canal, count(*) AS cnt
            FROM public.comunicacao_outbox GROUP BY canal) c;

  SELECT jsonb_object_agg(event_key, stats) INTO v_by_event
  FROM (
    SELECT e.event_key AS event_key,
           jsonb_build_object(
             'total', count(*),
             'sent', count(*) FILTER (WHERE o.status='sent'),
             'pending', count(*) FILTER (WHERE o.status='pending'),
             'failed', count(*) FILTER (WHERE o.status='failed'),
             'dead_letter', count(*) FILTER (WHERE o.status='dead_letter')
           ) AS stats
      FROM public.comunicacao_outbox o
      JOIN public.comunicacao_eventos e ON e.id = o.event_id
     WHERE o.created_at > now() - interval '7 days'
     GROUP BY e.event_key
  ) x;

  SELECT jsonb_object_agg(key, cnt) INTO v_by_canal_status
  FROM (
    SELECT (canal::text || '.' || status::text) AS key, count(*) AS cnt
      FROM public.comunicacao_outbox
     WHERE created_at > now() - interval '7 days'
     GROUP BY 1
  ) y;

  SELECT count(*) INTO v_pending FROM public.comunicacao_outbox WHERE status='pending';
  SELECT count(*) INTO v_dlq FROM public.comunicacao_outbox WHERE status='dead_letter';
  SELECT count(*) INTO v_processing FROM public.comunicacao_outbox WHERE status='processing';

  SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(created_at)))::int, 0)
    INTO v_oldest_pending_age_s
    FROM public.comunicacao_outbox WHERE status='pending';

  SELECT COALESCE(EXTRACT(EPOCH FROM (now() - min(locked_at)))::int, 0)
    INTO v_oldest_locked_age_s
    FROM public.comunicacao_outbox WHERE status='processing' AND locked_at IS NOT NULL;

  SELECT count(*) INTO v_success_24h
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours';
  SELECT count(*) INTO v_failed_24h
    FROM public.comunicacao_outbox
   WHERE status IN ('failed','dead_letter') AND updated_at > now() - interval '24 hours';

  v_success_rate := CASE WHEN (v_success_24h + v_failed_24h) = 0 THEN NULL
                         ELSE round(v_success_24h::numeric / (v_success_24h + v_failed_24h) * 100, 2) END;

  SELECT round(avg(attempts)::numeric, 2), max(attempts)
    INTO v_avg_attempts_sent, v_max_attempts
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours';

  SELECT round(avg(attempts)::numeric, 2)
    INTO v_avg_attempts_terminal
    FROM public.comunicacao_outbox
   WHERE status IN ('failed','dead_letter') AND updated_at > now() - interval '24 hours';

  SELECT round(avg(EXTRACT(EPOCH FROM (sent_at - created_at))*1000)::numeric, 0),
         round((percentile_cont(0.95) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (sent_at - created_at))*1000))::numeric, 0)
    INTO v_avg_latency_ms, v_p95_latency_ms
    FROM public.comunicacao_outbox
   WHERE status='sent' AND sent_at > now() - interval '24 hours' AND sent_at IS NOT NULL;

  SELECT EXISTS (
    SELECT 1 FROM pg_publication_tables
     WHERE pubname='supabase_realtime'
       AND schemaname='public'
       AND tablename IN ('notificacoes_operacionais','portal_notificacoes')
    HAVING count(*) >= 2
  ) INTO v_realtime_ready;

  SELECT max(created_at) INTO v_last_replay_at
    FROM public.comunicacao_dlq_replay_audit;

  SELECT GREATEST(
    COALESCE((SELECT max(locked_at) FROM public.comunicacao_outbox WHERE locked_at IS NOT NULL), 'epoch'),
    COALESCE((SELECT max(sent_at)   FROM public.comunicacao_outbox WHERE sent_at   IS NOT NULL), 'epoch'),
    COALESCE((SELECT max(updated_at) FROM public.comunicacao_outbox
               WHERE status IN ('failed','dead_letter','processing','sent')), 'epoch')
  ) INTO v_last_worker_activity;

  IF v_last_worker_activity IS NULL OR v_last_worker_activity = 'epoch'::timestamptz THEN
    v_worker_status := 'unknown';
    v_worker_age_s := NULL;
    v_last_worker_activity := NULL;
  ELSE
    v_worker_age_s := EXTRACT(EPOCH FROM (now() - v_last_worker_activity))::int;
    v_worker_status := CASE
      WHEN v_worker_age_s <= 300 THEN 'active'
      WHEN v_worker_age_s <= 1800 THEN 'idle'
      ELSE 'stale'
    END;
  END IF;

  SELECT max(sent_at) INTO v_last_sent_at FROM public.comunicacao_outbox WHERE sent_at IS NOT NULL;

  SELECT
    COALESCE(delivery_enabled, false),
    COALESCE(email_delivery_enabled, false),
    COALESCE(whatsapp_delivery_enabled, false),
    COALESCE(inapp_delivery_enabled, false),
    COALESCE(whatsapp_webhook_enabled, false),
    COALESCE(test_mode_enabled, false)
  INTO v_flag_delivery, v_flag_email, v_flag_wa, v_flag_inapp, v_flag_webhook, v_flag_test_mode
  FROM public.communication_provider_settings
  ORDER BY updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_flag_delivery IS NULL THEN v_flag_delivery := false; END IF;
  IF v_flag_email IS NULL THEN v_flag_email := false; END IF;
  IF v_flag_wa IS NULL THEN v_flag_wa := false; END IF;
  IF v_flag_inapp IS NULL THEN v_flag_inapp := false; END IF;
  IF v_flag_webhook IS NULL THEN v_flag_webhook := false; END IF;
  IF v_flag_test_mode IS NULL THEN v_flag_test_mode := false; END IF;

  SELECT jsonb_build_object(
           'configured', (smtp_host IS NOT NULL AND smtp_from IS NOT NULL AND secret_smtp_password IS NOT NULL),
           'enabled', COALESCE(email_delivery_enabled, false)
         )
    INTO v_prov_email
    FROM public.communication_provider_settings
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  SELECT jsonb_build_object(
           'configured', (whatsapp_phone_number_id IS NOT NULL AND secret_whatsapp_access_token IS NOT NULL),
           'enabled', COALESCE(whatsapp_delivery_enabled, false),
           'webhook_configured', (secret_whatsapp_verify_token IS NOT NULL AND secret_whatsapp_app_secret IS NOT NULL),
           'webhook_enabled', COALESCE(whatsapp_webhook_enabled, false)
         )
    INTO v_prov_wa
    FROM public.communication_provider_settings
    ORDER BY updated_at DESC NULLS LAST LIMIT 1;

  v_prov := jsonb_build_object(
    'email', COALESCE(v_prov_email, jsonb_build_object('configured', false, 'enabled', false)),
    'whatsapp', COALESCE(v_prov_wa, jsonb_build_object('configured', false, 'enabled', false, 'webhook_configured', false, 'webhook_enabled', false)),
    'in_app', jsonb_build_object('configured', true, 'enabled', v_flag_inapp)
  );

  RETURN jsonb_build_object(
    'ok', true,
    'generated_at', now(),
    'flags', jsonb_build_object(
      'delivery_enabled', v_flag_delivery,
      'email_enabled', v_flag_email,
      'whatsapp_enabled', v_flag_wa,
      'in_app_enabled', v_flag_inapp,
      'whatsapp_webhook_enabled', v_flag_webhook,
      'test_mode_enabled', v_flag_test_mode
    ),
    'providers', v_prov,
    'queue', jsonb_build_object(
      'by_status', COALESCE(v_by_status,'{}'::jsonb),
      'by_canal',  COALESCE(v_by_canal,'{}'::jsonb),
      'by_event_key_7d', COALESCE(v_by_event,'{}'::jsonb),
      'by_canal_status_7d', COALESCE(v_by_canal_status,'{}'::jsonb),
      'pending', v_pending,
      'processing', v_processing,
      'dead_letter', v_dlq,
      'oldest_pending_age_seconds', v_oldest_pending_age_s,
      'oldest_processing_age_seconds', v_oldest_locked_age_s
    ),
    'throughput_24h', jsonb_build_object(
      'sent', v_success_24h,
      'failed_or_dlq', v_failed_24h,
      'success_rate_pct', v_success_rate,
      'avg_attempts_sent', v_avg_attempts_sent,
      'avg_attempts_terminal', v_avg_attempts_terminal,
      'max_attempts', v_max_attempts,
      'avg_latency_ms', v_avg_latency_ms,
      'p95_latency_ms', v_p95_latency_ms
    ),
    'worker', jsonb_build_object(
      'status', v_worker_status,
      'last_activity_at', v_last_worker_activity,
      'last_activity_age_seconds', v_worker_age_s,
      'last_sent_at', v_last_sent_at
    ),
    'realtime', jsonb_build_object('ready', COALESCE(v_realtime_ready, false)),
    'dlq_admin', jsonb_build_object('last_replay_at', v_last_replay_at)
  );
END;$$;


ALTER FUNCTION public.rpc_admin_communication_health_snapshot() OWNER TO postgres;

--
-- Name: rpc_admin_communication_outbox_metrics(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_communication_outbox_metrics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by_status jsonb;
  v_by_canal jsonb;
  v_dlq_count bigint;
  v_pending_count bigint;
  v_last_dlq_at timestamptz;
  v_avg_attempts numeric;
  v_avg_latency_ms numeric;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();

  SELECT jsonb_object_agg(status, cnt) INTO v_by_status FROM (
    SELECT status::text AS status, count(*) AS cnt
      FROM public.comunicacao_outbox
     GROUP BY status
  ) s;

  SELECT jsonb_object_agg(canal, cnt) INTO v_by_canal FROM (
    SELECT canal::text AS canal, count(*) AS cnt
      FROM public.comunicacao_outbox
     GROUP BY canal
  ) c;

  SELECT count(*), max(updated_at) INTO v_dlq_count, v_last_dlq_at
    FROM public.comunicacao_outbox WHERE status = 'dead_letter';

  SELECT count(*) INTO v_pending_count
    FROM public.comunicacao_outbox WHERE status = 'pending';

  SELECT COALESCE(avg(attempts),0) INTO v_avg_attempts
    FROM public.comunicacao_outbox
   WHERE status IN ('sent','dead_letter');

  SELECT COALESCE(avg(EXTRACT(EPOCH FROM (sent_at - created_at)) * 1000), 0)
    INTO v_avg_latency_ms
    FROM public.comunicacao_outbox
   WHERE status = 'sent' AND sent_at IS NOT NULL;

  RETURN jsonb_build_object(
    'by_status', COALESCE(v_by_status, '{}'::jsonb),
    'by_canal', COALESCE(v_by_canal, '{}'::jsonb),
    'dead_letter_count', COALESCE(v_dlq_count, 0),
    'pending_count', COALESCE(v_pending_count, 0),
    'last_dead_letter_at', v_last_dlq_at,
    'avg_attempts_terminal', round(COALESCE(v_avg_attempts,0)::numeric, 2),
    'avg_latency_ms_sent', round(COALESCE(v_avg_latency_ms,0)::numeric, 0)
  );
END$$;


ALTER FUNCTION public.rpc_admin_communication_outbox_metrics() OWNER TO postgres;

--
-- Name: rpc_admin_create_commercial_plan(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_create_commercial_plan(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  PERFORM public._cpp_validate_payload(p_payload);

  INSERT INTO public.commercial_payment_plans (
    name, code, description, plan_type, max_days, months_count, installment_count,
    discount_percent, monthly_interest_percent, interest_type, requires_credit_approval,
    requires_guarantee, requires_financial_approval, minimum_order_amount, pricing_mode,
    active, sort_order, created_by, updated_by, valid_from, valid_until, version, version_reason
  ) VALUES (
    btrim(p_payload->>'name'), upper(btrim(p_payload->>'code')), nullif(btrim(coalesce(p_payload->>'description','')),''),
    p_payload->>'plan_type', coalesce((p_payload->>'max_days')::integer,0),
    coalesce((p_payload->>'months_count')::numeric,0), coalesce((p_payload->>'installment_count')::integer,1),
    coalesce((p_payload->>'discount_percent')::numeric,0), coalesce((p_payload->>'monthly_interest_percent')::numeric,0),
    coalesce(p_payload->>'interest_type','compound'), coalesce((p_payload->>'requires_credit_approval')::boolean,false),
    coalesce((p_payload->>'requires_guarantee')::boolean,false), coalesce((p_payload->>'requires_financial_approval')::boolean,false),
    nullif(p_payload->>'minimum_order_amount','')::numeric, coalesce(p_payload->>'pricing_mode','discount_from_base'),
    coalesce((p_payload->>'active')::boolean,true), coalesce((p_payload->>'sort_order')::integer,0),
    auth.uid(), auth.uid(), coalesce(nullif(p_payload->>'valid_from','')::timestamptz, now()),
    nullif(p_payload->>'valid_until','')::timestamptz, 1, nullif(btrim(coalesce(p_payload->>'motivo','')),'')
  ) RETURNING id INTO v_id;

  UPDATE public.commercial_payment_plans SET root_plan_id = v_id WHERE id = v_id;
  PERFORM public._cpp_audit('commercial_plan_created', v_id, NULL, p_payload, p_payload->>'motivo');
  RETURN v_id;
END
$$;


ALTER FUNCTION public.rpc_admin_create_commercial_plan(p_payload jsonb) OWNER TO postgres;

--
-- Name: rpc_admin_list_commercial_plans(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_list_commercial_plans(p_search text DEFAULT NULL::text, p_status text DEFAULT 'all'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, code text, name text, description text, plan_type text, version integer, root_plan_id uuid, superseded_by_id uuid, valid_from timestamp with time zone, valid_until timestamp with time zone, is_default boolean, active boolean, sort_order integer, max_days integer, months_count numeric, installment_count integer, discount_percent numeric, monthly_interest_percent numeric, interest_type text, pricing_mode text, minimum_order_amount numeric, requires_credit_approval boolean, requires_guarantee boolean, requires_financial_approval boolean, is_referenced boolean, selectable boolean, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_limit integer := least(greatest(coalesce(p_limit,20),1),100);
        v_offset integer := greatest(coalesce(p_offset,0),0);
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  RETURN QUERY
  WITH base AS (
    SELECT p.* FROM public.commercial_payment_plans p
    WHERE (p_search IS NULL OR btrim(p_search) = ''
           OR p.name ILIKE '%'||btrim(p_search)||'%' OR p.code ILIKE '%'||btrim(p_search)||'%')
      AND (coalesce(p_status,'all') = 'all'
           OR (p_status = 'active' AND p.active)
           OR (p_status = 'inactive' AND NOT p.active))
  ), counted AS (SELECT count(*)::bigint c FROM base)
  SELECT b.id, b.code, b.name, b.description, b.plan_type, b.version,
         b.root_plan_id, b.superseded_by_id, b.valid_from, b.valid_until,
         b.is_default, b.active, b.sort_order, b.max_days, b.months_count,
         b.installment_count, b.discount_percent, b.monthly_interest_percent,
         b.interest_type, b.pricing_mode, b.minimum_order_amount,
         b.requires_credit_approval, b.requires_guarantee, b.requires_financial_approval,
         public.fn_b2b_plan_referenced(b.id), public.fn_b2b_plan_selectable(b.id),
         (SELECT c FROM counted)
  FROM base b
  ORDER BY b.sort_order ASC, b.code ASC, b.version DESC
  LIMIT v_limit OFFSET v_offset;
END
$$;


ALTER FUNCTION public.rpc_admin_list_commercial_plans(p_search text, p_status text, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_admin_list_communication_dead_letter(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_list_communication_dead_letter(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, canal public.comunicacao_canal, template_chave text, template_versao integer, attempts integer, max_attempts integer, error_code text, error_message text, recipient_user_id uuid, recipient_cliente_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_limit int; v_offset int;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();
  v_limit := GREATEST(1, LEAST(200, COALESCE(p_limit, 50)));
  v_offset := GREATEST(0, COALESCE(p_offset, 0));
  RETURN QUERY
    SELECT o.id, o.canal, o.template_chave, o.template_versao,
           o.attempts, o.max_attempts,
           left(COALESCE(o.error_code,''), 80),
           left(COALESCE(o.error_message,''), 500),
           o.recipient_user_id, o.recipient_cliente_id,
           o.created_at, o.updated_at
      FROM public.comunicacao_outbox o
     WHERE o.status = 'dead_letter'
     ORDER BY o.updated_at DESC NULLS LAST, o.created_at DESC
     LIMIT v_limit OFFSET v_offset;
END$$;


ALTER FUNCTION public.rpc_admin_list_communication_dead_letter(p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_admin_reorder_commercial_plans(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_reorder_commercial_plans(p_orders jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_item jsonb;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF jsonb_typeof(p_orders) <> 'array' THEN RAISE EXCEPTION 'orders_payload_invalid'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('cpp_reorder'));

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_orders) LOOP
    IF (v_item->>'sort_order')::integer < 0 THEN RAISE EXCEPTION 'sort_order_invalid'; END IF;
    UPDATE public.commercial_payment_plans
       SET sort_order = (v_item->>'sort_order')::integer, updated_by = auth.uid()
     WHERE id = (v_item->>'id')::uuid;
  END LOOP;

  PERFORM public._cpp_audit('commercial_plan_reordered', NULL, NULL, jsonb_build_object('orders', p_orders), NULL);
END
$$;


ALTER FUNCTION public.rpc_admin_reorder_commercial_plans(p_orders jsonb) OWNER TO postgres;

--
-- Name: rpc_admin_replay_communication_dead_letter(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_replay_communication_dead_letter(p_outbox_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_outbox%rowtype; v_before jsonb; v_after jsonb;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();
  PERFORM public._comunicacao_dlq_replay_rate_check('unit', 30);

  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'dead_letter' THEN
    RAISE EXCEPTION 'item não está em dead_letter (status=%)', r.status
      USING ERRCODE='invalid_parameter_value';
  END IF;

  v_before := jsonb_build_object(
    'status', r.status::text, 'attempts', r.attempts,
    'error_code', r.error_code, 'error_message', left(COALESCE(r.error_message,''),200)
  );
  UPDATE public.comunicacao_outbox
     SET status='pending', attempts=0, next_attempt_at=now(),
         error_code=NULL, error_message=NULL,
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  v_after := jsonb_build_object('status','pending','attempts',0);

  INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, target_id)
    VALUES (auth.uid(), 'unit', p_outbox_id);

  PERFORM public._comunicacao_write_audit(
    'outbox.dlq_replay', 'comunicacao_outbox', p_outbox_id, v_before, v_after
  );
  RETURN jsonb_build_object('ok',true,'id',p_outbox_id,'status','pending');
END;$$;


ALTER FUNCTION public.rpc_admin_replay_communication_dead_letter(p_outbox_id uuid) OWNER TO postgres;

--
-- Name: rpc_admin_replay_communication_dead_letter_batch(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_replay_communication_dead_letter_batch(p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_limit int; v_ids uuid[]; v_id uuid; v_before jsonb; v_count int := 0;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  PERFORM public._comunicacao_require_admin();
  PERFORM public._comunicacao_dlq_replay_rate_check('batch', 6);

  v_limit := GREATEST(1, LEAST(20, COALESCE(p_limit, 10)));
  SELECT array_agg(id) INTO v_ids FROM (
    SELECT id FROM public.comunicacao_outbox
     WHERE status='dead_letter'
     ORDER BY updated_at ASC NULLS FIRST, created_at ASC
     LIMIT v_limit FOR UPDATE SKIP LOCKED
  ) s;
  IF v_ids IS NULL THEN
    INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, batch_size)
      VALUES (auth.uid(), 'batch', 0);
    RETURN jsonb_build_object('ok',true,'replayed',0,'ids','[]'::jsonb);
  END IF;

  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT jsonb_build_object(
      'status', o.status::text, 'attempts', o.attempts,
      'error_code', o.error_code, 'error_message', left(COALESCE(o.error_message,''),200)
    ) INTO v_before FROM public.comunicacao_outbox o WHERE o.id = v_id;
    UPDATE public.comunicacao_outbox
       SET status='pending', attempts=0, next_attempt_at=now(),
           error_code=NULL, error_message=NULL,
           locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
     WHERE id = v_id;
    PERFORM public._comunicacao_write_audit(
      'outbox.dlq_replay_batch', 'comunicacao_outbox', v_id, v_before,
      jsonb_build_object('status','pending','attempts',0)
    );
    v_count := v_count + 1;
  END LOOP;

  INSERT INTO public.comunicacao_dlq_replay_audit(actor_id, scope, batch_size)
    VALUES (auth.uid(), 'batch', v_count);

  RETURN jsonb_build_object('ok',true,'replayed',v_count,'ids',to_jsonb(v_ids));
END;$$;


ALTER FUNCTION public.rpc_admin_replay_communication_dead_letter_batch(p_limit integer) OWNER TO postgres;

--
-- Name: rpc_admin_set_commercial_plan_active(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_set_commercial_plan_active(p_plan_id uuid, p_active boolean, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_old public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_active AND v_old.superseded_by_id IS NOT NULL THEN RAISE EXCEPTION 'plan_superseded_cannot_activate'; END IF;

  UPDATE public.commercial_payment_plans
     SET active = p_active,
         is_default = CASE WHEN p_active THEN is_default ELSE false END,
         updated_by = auth.uid()
   WHERE id = p_plan_id;

  PERFORM public._cpp_audit(CASE WHEN p_active THEN 'commercial_plan_activated' ELSE 'commercial_plan_deactivated' END,
    p_plan_id, to_jsonb(v_old), jsonb_build_object('active', p_active), p_motivo);
END
$$;


ALTER FUNCTION public.rpc_admin_set_commercial_plan_active(p_plan_id uuid, p_active boolean, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_admin_set_default_commercial_plan(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_set_default_commercial_plan(p_plan_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_old public.commercial_payment_plans%ROWTYPE; v_prev public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('cpp_default_plan'));
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF NOT public.fn_b2b_plan_selectable(p_plan_id) THEN RAISE EXCEPTION 'plan_not_selectable'; END IF;

  SELECT * INTO v_prev FROM public.commercial_payment_plans
   WHERE is_default AND id <> p_plan_id FOR UPDATE;

  UPDATE public.commercial_payment_plans SET is_default = false, updated_by = auth.uid()
   WHERE is_default AND id <> p_plan_id;
  UPDATE public.commercial_payment_plans SET is_default = true, updated_by = auth.uid()
   WHERE id = p_plan_id;

  IF v_prev.id IS NOT NULL THEN
    PERFORM public._cpp_audit(
      'commercial_plan_unset_default',
      v_prev.id,
      jsonb_build_object('is_default', true, 'code', v_prev.code, 'name', v_prev.name),
      jsonb_build_object('is_default', false, 'replaced_by_plan_id', p_plan_id),
      'substituido_por_novo_plano_padrao');
  END IF;

  PERFORM public._cpp_audit(
    'commercial_plan_set_default',
    p_plan_id,
    jsonb_build_object('is_default', v_old.is_default, 'code', v_old.code, 'name', v_old.name),
    jsonb_build_object('is_default', true, 'previous_default_plan_id', v_prev.id),
    NULL);
END
$$;


ALTER FUNCTION public.rpc_admin_set_default_commercial_plan(p_plan_id uuid) OWNER TO postgres;

--
-- Name: rpc_admin_set_whatsapp_consent(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_set_whatsapp_consent(p_cliente_id uuid, p_user_id uuid, p_acao text, p_source text, p_justificativa text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_now   timestamptz := now();
  v_src   text := COALESCE(NULLIF(btrim(p_source), ''), 'admin_ui');
  v_just  text := NULLIF(btrim(COALESCE(p_justificativa, '')), '');
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF v_actor IS NULL OR NOT public.has_role(v_actor, 'administrador'::public.app_role) THEN
    RAISE EXCEPTION 'not_authorized' USING ERRCODE = '42501';
  END IF;
  IF (p_cliente_id IS NULL AND p_user_id IS NULL) OR (p_cliente_id IS NOT NULL AND p_user_id IS NOT NULL) THEN
    RAISE EXCEPTION 'exactly_one_of_cliente_or_user_required' USING ERRCODE = '22023';
  END IF;
  IF p_acao NOT IN ('opt_in','opt_out','verified') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;
  IF length(v_src) > 60 THEN RAISE EXCEPTION 'invalid_source' USING ERRCODE='22023'; END IF;
  IF v_just IS NOT NULL AND length(v_just) > 500 THEN
    RAISE EXCEPTION 'invalid_justificativa' USING ERRCODE='22023';
  END IF;

  -- Trilha imutável (append-only). `source` embute justificativa quando presente.
  INSERT INTO public.comunicacao_consent_log(user_id, cliente_id, canal, acao, source, actor_id)
  VALUES (
    p_user_id, p_cliente_id, 'whatsapp'::public.comunicacao_canal, p_acao,
    CASE WHEN v_just IS NULL THEN v_src ELSE v_src || ':' || substr(v_just,1,120) END,
    v_actor
  );

  -- Estado atual (idempotente por (user_id|cliente_id, canal))
  INSERT INTO public.comunicacao_preferencias
    (user_id, cliente_id, canal, enabled,
     whatsapp_opt_in_at, whatsapp_opt_out_at, telefone_verificado, source)
  VALUES (
    p_user_id, p_cliente_id, 'whatsapp'::public.comunicacao_canal, true,
    CASE WHEN p_acao = 'opt_in'   THEN v_now ELSE NULL END,
    CASE WHEN p_acao = 'opt_out'  THEN v_now ELSE NULL END,
    CASE WHEN p_acao = 'verified' THEN true  ELSE false END,
    'admin'
  )
  ON CONFLICT (COALESCE(user_id, '00000000-0000-0000-0000-000000000000'::uuid),
               COALESCE(cliente_id, '00000000-0000-0000-0000-000000000000'::uuid),
               canal)
  DO UPDATE SET
    whatsapp_opt_in_at  = CASE WHEN p_acao='opt_in'  THEN v_now
                               WHEN p_acao='opt_out' THEN public.comunicacao_preferencias.whatsapp_opt_in_at
                               ELSE public.comunicacao_preferencias.whatsapp_opt_in_at END,
    whatsapp_opt_out_at = CASE WHEN p_acao='opt_out' THEN v_now
                               WHEN p_acao='opt_in'  THEN NULL
                               ELSE public.comunicacao_preferencias.whatsapp_opt_out_at END,
    telefone_verificado = CASE WHEN p_acao='verified' THEN true
                               ELSE public.comunicacao_preferencias.telefone_verificado END,
    enabled = CASE WHEN p_acao='opt_out' THEN public.comunicacao_preferencias.enabled ELSE true END,
    updated_at = v_now,
    source = 'admin';

  RETURN jsonb_build_object('ok', true, 'acao', p_acao, 'at', v_now);
END;
$$;


ALTER FUNCTION public.rpc_admin_set_whatsapp_consent(p_cliente_id uuid, p_user_id uuid, p_acao text, p_source text, p_justificativa text) OWNER TO postgres;

--
-- Name: rpc_admin_update_commercial_plan_metadata(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_update_commercial_plan_metadata(p_plan_id uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_sort_order integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_old public.commercial_payment_plans%ROWTYPE;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF p_sort_order IS NOT NULL AND p_sort_order < 0 THEN RAISE EXCEPTION 'sort_order_invalid'; END IF;
  IF p_name IS NOT NULL AND btrim(p_name) = '' THEN RAISE EXCEPTION 'plan_name_required'; END IF;

  UPDATE public.commercial_payment_plans
     SET name = coalesce(btrim(p_name), name),
         description = coalesce(p_description, description),
         sort_order = coalesce(p_sort_order, sort_order),
         updated_by = auth.uid()
   WHERE id = p_plan_id;

  PERFORM public._cpp_audit('commercial_plan_metadata_updated', p_plan_id, to_jsonb(v_old),
    jsonb_build_object('name', p_name, 'description', p_description, 'sort_order', p_sort_order), NULL);
END
$$;


ALTER FUNCTION public.rpc_admin_update_commercial_plan_metadata(p_plan_id uuid, p_name text, p_description text, p_sort_order integer) OWNER TO postgres;

--
-- Name: rpc_admin_version_commercial_plan(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_admin_version_commercial_plan(p_plan_id uuid, p_payload jsonb, p_motivo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_old public.commercial_payment_plans%ROWTYPE; v_new_id uuid; v_next integer; v_code text;
BEGIN
  IF NOT public.fn_b2b_can_admin_plans() THEN RAISE EXCEPTION 'not_authorized'; END IF;
  PERFORM public._cpp_validate_payload(p_payload);

  SELECT * INTO v_old FROM public.commercial_payment_plans WHERE id = p_plan_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'plan_not_found'; END IF;
  IF v_old.superseded_by_id IS NOT NULL THEN RAISE EXCEPTION 'plan_already_superseded'; END IF;

  SELECT coalesce(max(version),0) + 1 INTO v_next
    FROM public.commercial_payment_plans WHERE root_plan_id = coalesce(v_old.root_plan_id, v_old.id);
  v_code := upper(btrim(coalesce(nullif(p_payload->>'code',''), v_old.code)));
  IF v_code = v_old.code THEN v_code := v_code || '-V' || v_next; END IF;

  INSERT INTO public.commercial_payment_plans (
    name, code, description, plan_type, max_days, months_count, installment_count,
    discount_percent, monthly_interest_percent, interest_type, requires_credit_approval,
    requires_guarantee, requires_financial_approval, minimum_order_amount, pricing_mode,
    active, sort_order, created_by, updated_by, valid_from, valid_until,
    version, root_plan_id, version_reason
  ) VALUES (
    btrim(coalesce(nullif(p_payload->>'name',''), v_old.name)), v_code,
    coalesce(nullif(btrim(coalesce(p_payload->>'description','')),''), v_old.description),
    coalesce(nullif(p_payload->>'plan_type',''), v_old.plan_type),
    coalesce((p_payload->>'max_days')::integer, v_old.max_days),
    coalesce((p_payload->>'months_count')::numeric, v_old.months_count),
    coalesce((p_payload->>'installment_count')::integer, v_old.installment_count),
    coalesce((p_payload->>'discount_percent')::numeric, v_old.discount_percent),
    coalesce((p_payload->>'monthly_interest_percent')::numeric, v_old.monthly_interest_percent),
    coalesce(nullif(p_payload->>'interest_type',''), v_old.interest_type),
    coalesce((p_payload->>'requires_credit_approval')::boolean, v_old.requires_credit_approval),
    coalesce((p_payload->>'requires_guarantee')::boolean, v_old.requires_guarantee),
    coalesce((p_payload->>'requires_financial_approval')::boolean, v_old.requires_financial_approval),
    coalesce(nullif(p_payload->>'minimum_order_amount','')::numeric, v_old.minimum_order_amount),
    coalesce(nullif(p_payload->>'pricing_mode',''), v_old.pricing_mode),
    true, v_old.sort_order, auth.uid(), auth.uid(),
    coalesce(nullif(p_payload->>'valid_from','')::timestamptz, now()),
    nullif(p_payload->>'valid_until','')::timestamptz,
    v_next, coalesce(v_old.root_plan_id, v_old.id), nullif(btrim(coalesce(p_motivo,'')),'')
  ) RETURNING id INTO v_new_id;

  UPDATE public.commercial_payment_plans
     SET superseded_by_id = v_new_id, active = false, is_default = false,
         valid_until = coalesce(valid_until, now()), updated_by = auth.uid()
   WHERE id = p_plan_id;

  PERFORM public._cpp_audit('commercial_plan_versioned', v_new_id, to_jsonb(v_old), p_payload || jsonb_build_object('version', v_next, 'previous_plan_id', p_plan_id), p_motivo);
  RETURN v_new_id;
END
$$;


ALTER FUNCTION public.rpc_admin_version_commercial_plan(p_plan_id uuid, p_payload jsonb, p_motivo text) OWNER TO postgres;

