--
-- Name: rpc_aplicar_sla_alertas(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_aplicar_sla_alertas() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_alerta record;
  v_config record;
  v_processados int := 0;
  v_configurados int := 0;
  v_vencidos int := 0;
  v_escalonados int := 0;
  v_reclassificados int := 0;
  v_sem_sla int := 0;
  v_grav_anterior text;
  v_uid uuid := auth.uid();
  v_is_service boolean := COALESCE((current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role', false);
BEGIN
  IF NOT v_is_service THEN
    IF v_uid IS NULL THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Usuario nao autenticado';
    END IF;
    IF NOT (
      public.has_role(v_uid,'administrador'::app_role)
      OR public.has_role(v_uid,'gestor'::app_role)
      OR public.has_role(v_uid,'administrativo'::app_role)
    ) THEN
      RAISE EXCEPTION 'permission_denied' USING HINT = 'Perfil sem permissao para aplicar SLA';
    END IF;
  END IF;

  FOR v_alerta IN
    SELECT * FROM public.alertas_operacionais
    WHERE COALESCE(status,'aberto') NOT IN ('resolvido','ignorado','cancelado')
  LOOP
    v_processados := v_processados + 1;

    SELECT * INTO v_config FROM public.alertas_sla_config
      WHERE ativo = true AND tipo_alerta = v_alerta.tipo
      LIMIT 1;
    IF NOT FOUND THEN
      SELECT * INTO v_config FROM public.alertas_sla_config
        WHERE ativo = true AND origem = v_alerta.origem AND gravidade = v_alerta.gravidade
        LIMIT 1;
    END IF;
    IF NOT FOUND THEN
      SELECT * INTO v_config FROM public.alertas_sla_config
        WHERE ativo = true AND tipo_alerta IS NULL AND origem IS NULL AND gravidade = v_alerta.gravidade
        LIMIT 1;
    END IF;

    IF NOT FOUND OR v_config.prazo_resolucao_minutos = 0 THEN
      v_sem_sla := v_sem_sla + 1;
      CONTINUE;
    END IF;

    IF v_alerta.sla_config_id IS NULL THEN
      UPDATE public.alertas_operacionais
        SET sla_config_id = v_config.id,
            sla_primeira_resposta_em = CASE WHEN v_config.prazo_primeira_resposta_minutos IS NOT NULL
              THEN v_alerta.created_at + make_interval(mins => v_config.prazo_primeira_resposta_minutos)
              ELSE NULL END,
            sla_resolucao_em = v_alerta.created_at + make_interval(mins => v_config.prazo_resolucao_minutos)
        WHERE id = v_alerta.id;

      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, prazo_primeira_resposta_em, prazo_resolucao_em)
        VALUES (v_alerta.id, v_config.id, 'sla_configurado',
          CASE WHEN v_config.prazo_primeira_resposta_minutos IS NOT NULL
            THEN v_alerta.created_at + make_interval(mins => v_config.prazo_primeira_resposta_minutos)
            ELSE NULL END,
          v_alerta.created_at + make_interval(mins => v_config.prazo_resolucao_minutos));

      v_configurados := v_configurados + 1;
      SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = v_alerta.id;
    END IF;

    IF NOT v_alerta.sla_vencido AND v_alerta.sla_resolucao_em IS NOT NULL AND now() > v_alerta.sla_resolucao_em THEN
      UPDATE public.alertas_operacionais
        SET sla_vencido = true, sla_vencido_em = now()
        WHERE id = v_alerta.id;
      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, vencido_em)
        VALUES (v_alerta.id, v_config.id, 'sla_resolucao_vencido', now());
      v_vencidos := v_vencidos + 1;
      v_alerta.sla_vencido := true;
    END IF;

    IF NOT v_alerta.escalonado
       AND v_config.escalonar_apos_minutos IS NOT NULL
       AND v_alerta.created_at + make_interval(mins => v_config.escalonar_apos_minutos) < now() THEN
      UPDATE public.alertas_operacionais
        SET escalonado = true, escalonado_em = now()
        WHERE id = v_alerta.id;
      INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, escalonado_em, gestor_notificado)
        VALUES (v_alerta.id, v_config.id, 'escalonado', now(), v_config.notificar_gestor);
      v_escalonados := v_escalonados + 1;
      v_alerta.escalonado := true;

      IF v_config.nova_gravidade_apos_sla IS NOT NULL
         AND v_config.nova_gravidade_apos_sla <> v_alerta.gravidade
         AND v_alerta.tipo IS DISTINCT FROM 'aplicacao_nao_registrada' THEN
        v_grav_anterior := v_alerta.gravidade;
        UPDATE public.alertas_operacionais
          SET gravidade = v_config.nova_gravidade_apos_sla
          WHERE id = v_alerta.id;
        INSERT INTO public.alertas_sla_eventos (alerta_id, config_id, evento, gravidade_anterior, gravidade_nova)
          VALUES (v_alerta.id, v_config.id, 'prioridade_reclassificada', v_grav_anterior, v_config.nova_gravidade_apos_sla);
        v_reclassificados := v_reclassificados + 1;
      END IF;
    END IF;

    PERFORM public.rpc_recalcular_prioridade_alerta(v_alerta.id);
  END LOOP;

  RETURN jsonb_build_object(
    'total_processados', v_processados,
    'total_sla_configurados', v_configurados,
    'total_vencidos', v_vencidos,
    'total_escalonados', v_escalonados,
    'total_reclassificados', v_reclassificados,
    'total_sem_sla', v_sem_sla,
    'executado_em', now()
  );
END;
$$;


ALTER FUNCTION public.rpc_aplicar_sla_alertas() OWNER TO postgres;

--
-- Name: rpc_aprovar_os_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_aprovar_os_v1(p_os_id uuid, p_origem text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_origin text; v_status text; v_org uuid;
BEGIN
 -- Normalização não consulta dados. Alias inválido/inexistente negado igualmente.
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin='b2b' THEN RAISE EXCEPTION 'OS_APPROVAL_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_org:=private.assert_os_approval_scope(p_os_id,v_origin);
 IF v_origin='manual' THEN SELECT status::text INTO v_status FROM public.ordens_servico WHERE id=p_os_id;
 ELSE SELECT status::text INTO v_status FROM public.ordens_servico_onfarm WHERE id=p_os_id; END IF;
 IF v_status='aprovada' THEN RETURN jsonb_build_object('success',true,'replay',true,'status','aprovada'); END IF;
 IF v_status IS DISTINCT FROM 'aberta' THEN RETURN jsonb_build_object('success',false,'message','Somente OS aberta pode ser aprovada separadamente.'); END IF;
 IF v_origin='manual' THEN UPDATE public.ordens_servico SET status='aprovada' WHERE id=p_os_id;
 ELSE UPDATE public.ordens_servico_onfarm SET status='aprovada' WHERE id=p_os_id; END IF;
 PERFORM private.assert_os_approval_scope(p_os_id,v_origin);
 RETURN jsonb_build_object('success',true,'replay',false,'status','aprovada','message','OS aprovada; programação e fabricação não iniciadas.');
END $$;


ALTER FUNCTION public.rpc_aprovar_os_v1(p_os_id uuid, p_origem text) OWNER TO postgres;

--
-- Name: rpc_archive_communication_template(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_archive_communication_template(p_template_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'archived' THEN
    RETURN jsonb_build_object('ok',true,'already_archived',true);
  END IF;
  UPDATE public.comunicacao_templates
     SET status = 'archived', archived_at = now(), updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.archive','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$$;


ALTER FUNCTION public.rpc_archive_communication_template(p_template_id uuid) OWNER TO postgres;

--
-- Name: rpc_arquivar_visita(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_arquivar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
  v_motivo text := NULLIF(btrim(COALESCE(p_motivo, '')), '');
BEGIN
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  IF v_reg.status::text = 'arquivado' THEN
    RETURN jsonb_build_object('ok', true, 'version', v_reg.version, 'status', 'arquivado', 'idempotent', true);
  END IF;

  IF v_reg.status::text <> 'rascunho' AND v_motivo IS NULL THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;

  -- a matriz de transições é validada pelo trigger de status do registro
  UPDATE public.registros_consultor
     SET status = 'arquivado', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  PERFORM public._visita_log_status(
    p_registro_id, 'visita_arquivada', v_reg.status::text, 'arquivado', v_motivo, v_new_version);

  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'arquivado');
END;
$$;


ALTER FUNCTION public.rpc_arquivar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_assign_visit_technician(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_assign_visit_technician(p_registro_id uuid, p_user_id uuid, p_role text DEFAULT 'tecnico'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_reactivated boolean := false;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE='42501'; END IF;
  IF p_registro_id IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'parametros_obrigatorios' USING ERRCODE='22023';
  END IF;
  IF NOT public.can_manage_technical_visit(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_gestao_equipe' USING ERRCODE='42501';
  END IF;

  SELECT id INTO v_id FROM public.technical_visit_assignments
    WHERE registro_consultor_id = p_registro_id AND user_id = p_user_id LIMIT 1;

  IF v_id IS NOT NULL THEN
    UPDATE public.technical_visit_assignments
       SET is_active = true,
           role = COALESCE(p_role, role),
           removed_at = NULL,
           removal_reason = NULL,
           assigned_by = v_uid,
           assigned_at = now(),
           updated_at = now()
     WHERE id = v_id;
    v_reactivated := true;
  ELSE
    INSERT INTO public.technical_visit_assignments
      (registro_consultor_id, user_id, role, is_active, assigned_by, assigned_at)
    VALUES (p_registro_id, p_user_id, COALESCE(p_role,'tecnico'), true, v_uid, now())
    RETURNING id INTO v_id;
  END IF;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, v_uid,
          CASE WHEN v_reactivated THEN 'tecnico_reativado' ELSE 'tecnico_atribuido' END,
          'Técnico ' || p_user_id::text || ' (' || COALESCE(p_role,'tecnico') || ') atribuído à visita');

  RETURN jsonb_build_object('id', v_id, 'reactivated', v_reactivated);
END; $$;


ALTER FUNCTION public.rpc_assign_visit_technician(p_registro_id uuid, p_user_id uuid, p_role text) OWNER TO postgres;

--
-- Name: rpc_associate_microorganism_fiscal_product(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_associate_microorganism_fiscal_product(p_microorganism_id uuid, p_product_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, product_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    public.has_role(v_uid, 'administrador'::public.app_role)
    OR public.has_role(v_uid, 'financeiro'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  IF p_microorganism_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.microrganismos m WHERE m.id = p_microorganism_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_product_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM public.produtos p WHERE p.id = p_product_id) THEN
      RAISE EXCEPTION 'product_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN QUERY
  UPDATE public.microrganismos m
     SET product_id = p_product_id
   WHERE m.id = p_microorganism_id
  RETURNING m.id, m.product_id;
END;
$$;


ALTER FUNCTION public.rpc_associate_microorganism_fiscal_product(p_microorganism_id uuid, p_product_id uuid) OWNER TO postgres;

--
-- Name: rpc_assumir_alerta(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_assumir_alerta(p_alerta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_alerta record;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'alerta_nao_encontrado');
  END IF;

  UPDATE public.alertas_operacionais
    SET responsavel_id = auth.uid()
    WHERE id = p_alerta_id;

  BEGIN
    INSERT INTO public.alertas_acoes (alerta_id, user_id, acao, observacao)
      VALUES (p_alerta_id, auth.uid(), 'assumir', 'Alerta assumido');
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success', true);
END;
$$;


ALTER FUNCTION public.rpc_assumir_alerta(p_alerta_id uuid) OWNER TO postgres;

--
-- Name: rpc_ativar_monitoramento_visita(uuid, integer, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_ativar_monitoramento_visita(p_registro_id uuid, p_expected_version integer, p_tipo text, p_data_referencia date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_id uuid;
  v_new_version integer;
BEGIN
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  IF p_tipo IS NULL OR btrim(p_tipo) = '' THEN
    RAISE EXCEPTION 'tipo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;

  SELECT id INTO v_id FROM public.monitoramento_avisos
   WHERE registro_consultor_id = p_registro_id AND tipo = p_tipo
     AND data_referencia IS NOT DISTINCT FROM p_data_referencia
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'id', v_id, 'version', v_reg.version, 'idempotent', true);
  END IF;

  INSERT INTO public.monitoramento_avisos (registro_consultor_id, tipo, data_referencia)
  VALUES (p_registro_id, p_tipo, p_data_referencia)
  RETURNING id INTO v_id;

  UPDATE public.registros_consultor
     SET version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_new_version;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao, metadata)
  VALUES (p_registro_id, auth.uid(), 'monitoramento_ativado', 'Plano de monitoramento: ' || p_tipo,
          jsonb_build_object('tipo', p_tipo, 'data_referencia', p_data_referencia, 'version', v_new_version));

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'version', v_new_version);
END;
$$;


ALTER FUNCTION public.rpc_ativar_monitoramento_visita(p_registro_id uuid, p_expected_version integer, p_tipo text, p_data_referencia date) OWNER TO postgres;

--
-- Name: rpc_atualizar_checklist_entrega(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_atualizar_checklist_entrega(p_checklist_id uuid, p_concluido boolean, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid := platform_private.h15_actor_organization();
  v_entrega_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Sessão inválida' USING ERRCODE='42501'; END IF;
  IF v_org IS NULL OR NOT public.is_delivery_staff(v_uid) THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE='42501'; END IF;
  SELECT c.entrega_id INTO v_entrega_id FROM public.entrega_checklist c JOIN public.entregas e ON e.id = c.entrega_id
   WHERE c.id = p_checklist_id AND e.organization_id = v_org;
  IF v_entrega_id IS NULL THEN RAISE EXCEPTION 'Checklist não encontrado' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.entregas e WHERE e.id = v_entrega_id AND e.organization_id = v_org FOR SHARE;
  IF NOT FOUND OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org OR NOT public.is_delivery_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão' USING ERRCODE='42501';
  END IF;

  UPDATE public.entrega_checklist SET
    concluido = p_concluido,
    observacao = coalesce(p_observacao, observacao),
    concluido_por = CASE WHEN p_concluido THEN v_uid ELSE NULL END,
    concluido_em = CASE WHEN p_concluido THEN now() ELSE NULL END
  WHERE id = p_checklist_id AND entrega_id = v_entrega_id;

  INSERT INTO public.financial_audit_log (entity_type, entity_id, action, new_data, performed_by)
  VALUES ('entrega', v_entrega_id, 'DELIVERY_CHECKLIST_UPDATED',
          jsonb_build_object('checklist_id', p_checklist_id, 'concluido', p_concluido), v_uid);

  RETURN jsonb_build_object('success', true);
END $$;


ALTER FUNCTION public.rpc_atualizar_checklist_entrega(p_checklist_id uuid, p_concluido boolean, p_observacao text) OWNER TO postgres;

--
-- Name: rpc_atualizar_identificacao_visita(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_atualizar_identificacao_visita(p_registro_id uuid, p_expected_version integer, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, false);

  IF NOT public.is_technical_visit_editable_status(v_reg.status::text) THEN
    RAISE EXCEPTION 'status_nao_editavel' USING ERRCODE = 'P0001';
  END IF;

  -- Política: chave ausente = mantém valor atual; chave presente = aplica valor
  -- (string vazia ou null limpam campos opcionais: safra, fase_fenologica, objetivo_visita).
  UPDATE public.registros_consultor SET
    cultura_id      = CASE WHEN p_payload ? 'cultura_id'
                             THEN NULLIF(p_payload->>'cultura_id','')::uuid ELSE cultura_id END,
    data_vistoria   = CASE WHEN p_payload ? 'data_vistoria'
                             THEN COALESCE(NULLIF(p_payload->>'data_vistoria','')::date, data_vistoria) ELSE data_vistoria END,
    tipo_visita     = CASE WHEN p_payload ? 'tipo_visita'
                             THEN COALESCE(NULLIF(p_payload->>'tipo_visita','')::tipo_visita, tipo_visita) ELSE tipo_visita END,
    objetivo_visita = CASE WHEN p_payload ? 'objetivo_visita'
                             THEN NULLIF(btrim(COALESCE(p_payload->>'objetivo_visita','')),'') ELSE objetivo_visita END,
    safra           = CASE WHEN p_payload ? 'safra'
                             THEN NULLIF(btrim(COALESCE(p_payload->>'safra','')),'') ELSE safra END,
    fase_fenologica = CASE WHEN p_payload ? 'fase_fenologica'
                             THEN NULLIF(btrim(COALESCE(p_payload->>'fase_fenologica','')),'') ELSE fase_fenologica END,
    version         = COALESCE(version, 1) + 1,
    updated_at      = now()
  WHERE id = p_registro_id
  RETURNING version INTO v_new_version;

  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao, metadata)
  VALUES (p_registro_id, auth.uid(), 'identificacao_atualizada', 'Identificação da visita atualizada',
          jsonb_build_object('version', v_new_version, 'campos', (SELECT jsonb_agg(k) FROM jsonb_object_keys(p_payload) k)));

  RETURN jsonb_build_object('ok', true, 'version', v_new_version);
END;
$$;


ALTER FUNCTION public.rpc_atualizar_identificacao_visita(p_registro_id uuid, p_expected_version integer, p_payload jsonb) OWNER TO postgres;

