--
-- Name: rpc_atualizar_status_alerta_agronomico_v1(uuid, public.status_alerta, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_atualizar_status_alerta_agronomico_v1(p_alerta_id uuid, p_novo_status public.status_alerta, p_updated_at_esperado timestamp with time zone) RETURNS public.alertas_agronomicos
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $$
declare
  v_alerta public.alertas_agronomicos;
begin
  if not public.technical_actor_ready(auth.uid()) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if p_alerta_id is null or p_novo_status is null or p_updated_at_esperado is null then
    raise exception 'INVALID_INPUT';
  end if;

  perform 1 from cf_user_guards_v1.state where singleton for update;
  if not found then raise exception 'monitoring_gate_unavailable' using errcode='55000'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(),'administrador'::public.app_role)
    or public.has_role(auth.uid(),'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  select * into v_alerta
  from public.alertas_agronomicos a
  where a.id = p_alerta_id and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
  for update;
  if not found then raise exception 'monitoring_alert_not_found' using errcode='PT404'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(),'administrador'::public.app_role)
    or public.has_role(auth.uid(),'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if v_alerta.updated_at IS DISTINCT FROM p_updated_at_esperado then raise exception 'CONCURRENT_UPDATE' using errcode='PT409'; end if;
  if v_alerta.status = 'encerrado'::public.status_alerta and p_novo_status <> v_alerta.status then
    raise exception 'CLOSED_ALERT';
  end if;

  update public.alertas_agronomicos a
  set status = p_novo_status, updated_at = greatest(clock_timestamp(),v_alerta.updated_at+interval '1 microsecond')
  where a.id = p_alerta_id and a.updated_at=p_updated_at_esperado and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
  returning * into v_alerta;
  if not found then raise exception 'CONCURRENT_UPDATE' using errcode='PT409'; end if;
  return v_alerta;
end;
$$;


ALTER FUNCTION public.rpc_atualizar_status_alerta_agronomico_v1(p_alerta_id uuid, p_novo_status public.status_alerta, p_updated_at_esperado timestamp with time zone) OWNER TO postgres;

--
-- Name: rpc_avancar_esteira_laboratorio(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_avancar_esteira_laboratorio(p_os_id uuid, p_origem text, p_etapa_destino text, p_programacao_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF p_origem IS DISTINCT FROM 'manual' OR p_etapa_destino IS DISTINCT FROM 'enviar_cq' THEN RAISE EXCEPTION 'CQ_OPERATION_CLOSED' USING ERRCODE='42501'; END IF;
 RETURN platform_private.manual_cq_v1(p_os_id,p_programacao_id,NULL);
END $$;


ALTER FUNCTION public.rpc_avancar_esteira_laboratorio(p_os_id uuid, p_origem text, p_etapa_destino text, p_programacao_id uuid) OWNER TO postgres;

--
-- Name: rpc_avancar_esteira_laboratorio(uuid, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_avancar_esteira_laboratorio(p_os_id uuid, p_origem text, p_etapa_destino text, p_programacao_id uuid, p_cq jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
 IF p_origem IS DISTINCT FROM 'manual' OR p_etapa_destino IS DISTINCT FROM 'registrar_cq' OR p_cq IS NULL THEN RAISE EXCEPTION 'CQ_OPERATION_CLOSED' USING ERRCODE='42501'; END IF;
 RETURN platform_private.manual_cq_v1(p_os_id,p_programacao_id,p_cq);
END $$;


ALTER FUNCTION public.rpc_avancar_esteira_laboratorio(p_os_id uuid, p_origem text, p_etapa_destino text, p_programacao_id uuid, p_cq jsonb) OWNER TO postgres;

--
-- Name: rpc_b2b_aging(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_aging(p_partner_id uuid DEFAULT NULL::uuid) RETURNS TABLE(faixa text, qtd_titulos integer, valor numeric, parceiros integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  -- H7O: autorização explícita (antes: filtro h7n_guarded devolvia 0 linhas).
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
       OR public.has_role(auth.uid(), 'gestor'::public.app_role)
       OR public.has_role(auth.uid(), 'financeiro'::public.app_role)
       OR public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
       OR public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: aging B2B restrito a administrador/gestor/financeiro/gestor_comercial/administrativo.';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT ar.partner_id, ari.id,
           (ari.original_amount - ari.received_amount) AS saldo,
           GREATEST(0, (current_date - ari.due_date)) AS dias
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type = 'B2B_ORDER'
      AND ar.status <> 'CANCELED'
      AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
  ), faixas AS (
    SELECT CASE
             WHEN dias <= 30 THEN '0-30'
             WHEN dias <= 60 THEN '31-60'
             WHEN dias <= 90 THEN '61-90'
             ELSE '90+'
           END AS faixa, partner_id, saldo
    FROM base
  )
  SELECT faixa, COUNT(*)::int, COALESCE(SUM(saldo),0), COUNT(DISTINCT partner_id)::int
  FROM faixas GROUP BY faixa
  ORDER BY CASE faixa WHEN '0-30' THEN 1 WHEN '31-60' THEN 2 WHEN '61-90' THEN 3 ELSE 4 END;
END
$$;


ALTER FUNCTION public.rpc_b2b_aging(p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_b2b_aging_detalhado(date, date, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_aging_detalhado(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_partner_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text) RETURNS TABLE(faixa text, qtd_titulos integer, valor numeric, qtd_parceiros integer, pct_carteira numeric, valor_medio_parceiro numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total numeric;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  WITH base AS (
    SELECT ar.partner_id, ari.id AS inst_id,
      (ari.original_amount - ari.received_amount) AS saldo,
      GREATEST(0, (CURRENT_DATE - ari.due_date)) AS dias_atraso
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type = 'B2B_ORDER'
      AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
      AND (p_from IS NULL OR ar.issue_date >= p_from)
      AND (p_to   IS NULL OR ar.issue_date <= p_to)
      AND (p_status IS NULL OR ari.status = p_status)
  ),
  classed AS (
    SELECT *,
      CASE
        WHEN dias_atraso <= 30 THEN '0-30'
        WHEN dias_atraso <= 60 THEN '31-60'
        WHEN dias_atraso <= 90 THEN '61-90'
        ELSE '90+'
      END AS bucket
    FROM base
  )
  SELECT COALESCE(SUM(saldo),0) INTO v_total FROM classed;

  RETURN QUERY
  WITH base AS (
    SELECT ar.partner_id,
      (ari.original_amount - ari.received_amount) AS saldo,
      GREATEST(0, (CURRENT_DATE - ari.due_date)) AS dias_atraso
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type = 'B2B_ORDER'
      AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
      AND (p_from IS NULL OR ar.issue_date >= p_from)
      AND (p_to   IS NULL OR ar.issue_date <= p_to)
      AND (p_status IS NULL OR ari.status = p_status)
  ),
  classed AS (
    SELECT *,
      CASE
        WHEN dias_atraso <= 30 THEN '0-30'
        WHEN dias_atraso <= 60 THEN '31-60'
        WHEN dias_atraso <= 90 THEN '61-90'
        ELSE '90+'
      END AS bucket
    FROM base
  )
  SELECT
    b AS faixa,
    COALESCE(COUNT(c.*),0)::int AS qtd_titulos,
    COALESCE(SUM(c.saldo),0)::numeric AS valor,
    COALESCE(COUNT(DISTINCT c.partner_id),0)::int AS qtd_parceiros,
    CASE WHEN v_total > 0 THEN ROUND((COALESCE(SUM(c.saldo),0)/v_total)*100,2) ELSE 0 END AS pct_carteira,
    CASE WHEN COUNT(DISTINCT c.partner_id) > 0 THEN ROUND(COALESCE(SUM(c.saldo),0)/COUNT(DISTINCT c.partner_id),2) ELSE 0 END AS valor_medio_parceiro
  FROM (VALUES ('0-30'),('31-60'),('61-90'),('90+')) AS f(b)
  LEFT JOIN classed c ON c.bucket = f.b
  GROUP BY f.b
  ORDER BY CASE f.b WHEN '0-30' THEN 1 WHEN '31-60' THEN 2 WHEN '61-90' THEN 3 ELSE 4 END;
END;$$;


ALTER FUNCTION public.rpc_b2b_aging_detalhado(p_from date, p_to date, p_partner_id uuid, p_status text) OWNER TO postgres;

--
-- Name: rpc_b2b_capacity_kpis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_capacity_kpis() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'producao'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  WITH os AS (
    SELECT os.status::text AS status,
           COALESCE(os.volume_total_ml, 0) / 1000.0 AS litros,
           os.updated_at,
           os.partner_order_id
    FROM public.ordens_servico os
    WHERE os.origem = 'b2b' AND os.partner_order_id IS NOT NULL
  ),
  litros AS (
    SELECT
      SUM(CASE WHEN status IN ('aberta','em_producao') THEN litros ELSE 0 END) AS litros_programados,
      SUM(CASE WHEN status = 'em_producao' THEN litros ELSE 0 END) AS litros_em_producao,
      SUM(CASE WHEN status = 'finalizada' THEN litros ELSE 0 END) AS litros_produzidos,
      SUM(CASE WHEN status = 'finalizada' AND updated_at >= date_trunc('week', now()) THEN litros ELSE 0 END) AS producao_semana,
      SUM(CASE WHEN status = 'finalizada' AND updated_at >= date_trunc('month', now()) THEN litros ELSE 0 END) AS producao_mes
    FROM os
  ),
  pedidos AS (
    SELECT
      COUNT(*) FILTER (WHERE status::text = 'em_producao') AS pedidos_em_producao,
      COUNT(*) FILTER (WHERE status::text = 'aprovado' AND ready_for_production = false) AS aguardando_planejamento,
      COUNT(*) FILTER (WHERE status::text = 'aprovado' AND ready_for_production = true
                        AND NOT EXISTS (SELECT 1 FROM public.production_order_link pol WHERE pol.partner_order_id = po.id)) AS aguardando_producao,
      COUNT(*) FILTER (WHERE status::text = 'entregue') AS pedidos_entregues,
      SUM(CASE WHEN status::text = 'entregue' THEN
            (SELECT COALESCE(SUM(os2.volume_total_ml),0)/1000.0
               FROM public.ordens_servico os2 WHERE os2.partner_order_id = po.id)
          ELSE 0 END) AS litros_entregues
    FROM public.partner_orders po
  )
  SELECT jsonb_build_object(
    'litros_programados', COALESCE((SELECT litros_programados FROM litros), 0),
    'litros_em_producao', COALESCE((SELECT litros_em_producao FROM litros), 0),
    'litros_produzidos', COALESCE((SELECT litros_produzidos FROM litros), 0),
    'litros_entregues', COALESCE((SELECT litros_entregues FROM pedidos), 0),
    'producao_semana', COALESCE((SELECT producao_semana FROM litros), 0),
    'producao_mes', COALESCE((SELECT producao_mes FROM litros), 0),
    'pedidos_em_producao', COALESCE((SELECT pedidos_em_producao FROM pedidos), 0),
    'aguardando_planejamento', COALESCE((SELECT aguardando_planejamento FROM pedidos), 0),
    'aguardando_producao', COALESCE((SELECT aguardando_producao FROM pedidos), 0),
    'pedidos_entregues', COALESCE((SELECT pedidos_entregues FROM pedidos), 0)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.rpc_b2b_capacity_kpis() OWNER TO postgres;

--
-- Name: rpc_b2b_carteira_kpis(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_carteira_kpis(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  WITH base AS (
    SELECT ar.id, ar.issue_date, ari.original_amount, ari.received_amount, ari.due_date, ari.status, ari.paid_at
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type='B2B_ORDER'
  )
  SELECT jsonb_build_object(
    'carteira_total', COALESCE(SUM(original_amount),0),
    'carteira_recebida', COALESCE(SUM(received_amount),0),
    'carteira_vencida', COALESCE(SUM(original_amount - received_amount) FILTER (WHERE due_date < CURRENT_DATE AND status IN ('OPEN','PARTIAL','OVERDUE')),0),
    'carteira_aberto', COALESCE(SUM(original_amount - received_amount) FILTER (WHERE status IN ('OPEN','PARTIAL','OVERDUE')),0),
    'receita_mes', COALESCE(SUM(received_amount) FILTER (WHERE paid_at >= date_trunc('month',now())),0),
    'receita_ano', COALESCE(SUM(received_amount) FILTER (WHERE paid_at >= date_trunc('year',now())),0),
    'inadimplencia_pct', CASE WHEN SUM(original_amount) > 0 THEN ROUND((COALESCE(SUM(original_amount - received_amount) FILTER (WHERE due_date < CURRENT_DATE AND status IN ('OPEN','PARTIAL','OVERDUE')),0)/SUM(original_amount))*100,2) ELSE 0 END,
    'prazo_medio_recebimento', ROUND(COALESCE(AVG(EXTRACT(EPOCH FROM (paid_at - issue_date))/86400) FILTER (WHERE paid_at IS NOT NULL),0)::numeric,2),
    'ticket_medio', CASE WHEN COUNT(DISTINCT id) > 0 THEN ROUND(COALESCE(SUM(original_amount),0)/COUNT(DISTINCT id),2) ELSE 0 END
  ) INTO v
  FROM base
  WHERE (p_from IS NULL OR issue_date >= p_from) AND (p_to IS NULL OR issue_date <= p_to);
  RETURN v;
END;$$;


ALTER FUNCTION public.rpc_b2b_carteira_kpis(p_from date, p_to date) OWNER TO postgres;

--
-- Name: rpc_b2b_check_governance_block(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_check_governance_block(p_partner_id uuid, p_acao text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rule public.financial_governance_rules%ROWTYPE;
  v_pfs public.partner_financial_settings%ROWTYPE;
  v_aberto numeric := 0;
  v_vencido numeric := 0;
  v_score_level text := 'baixo';
  v_motivo text;
BEGIN
  SELECT * INTO v_rule FROM financial_governance_rules WHERE regra = p_acao AND ativo=true;
  IF NOT FOUND THEN RETURN jsonb_build_object('blocked',false); END IF;

  SELECT * INTO v_pfs FROM partner_financial_settings WHERE partner_id = p_partner_id;
  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0),
         COALESCE(SUM(ari.original_amount - ari.received_amount) FILTER (WHERE ari.due_date < CURRENT_DATE),0)
    INTO v_aberto, v_vencido
  FROM accounts_receivable ar
  JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
  WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id=p_partner_id
    AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  SELECT risk_level INTO v_score_level FROM partner_risk_scores WHERE partner_id = p_partner_id;

  IF v_rule.por_credito AND v_pfs.credit_limit IS NOT NULL AND v_pfs.credit_limit > 0 AND v_aberto >= v_pfs.credit_limit THEN
    v_motivo := 'credito_excedido';
  ELSIF v_rule.por_inadimplencia AND v_vencido > 0 THEN
    v_motivo := 'inadimplencia';
  ELSIF v_rule.por_score_critico AND COALESCE(v_score_level,'baixo') = 'critico' THEN
    v_motivo := 'score_critico';
  END IF;

  IF v_motivo IS NOT NULL THEN
    RETURN jsonb_build_object('blocked',true,'motivo',v_motivo);
  END IF;
  RETURN jsonb_build_object('blocked',false);
END;$$;


ALTER FUNCTION public.rpc_b2b_check_governance_block(p_partner_id uuid, p_acao text) OWNER TO postgres;

--
-- Name: rpc_b2b_credit_exposure(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_credit_exposure(p_partner_id uuid, p_new_order_amount numeric DEFAULT 0, p_exclude_order_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_uid uuid := auth.uid();
BEGIN
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, p_partner_id);
  IF p_new_order_amount IS NULL OR p_new_order_amount < 0 OR p_new_order_amount::text IN ('NaN','Infinity','-Infinity') THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;
  IF p_exclude_order_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.partner_orders po WHERE po.id=p_exclude_order_id AND po.partner_id=p_partner_id
  ) THEN
    RAISE EXCEPTION 'forbidden_order' USING ERRCODE = '42501';
  END IF;
  RETURN public.fn_b2b_credit_exposure(p_partner_id, p_new_order_amount, p_exclude_order_id);
END;
$$;


ALTER FUNCTION public.rpc_b2b_credit_exposure(p_partner_id uuid, p_new_order_amount numeric, p_exclude_order_id uuid) OWNER TO postgres;

--
-- Name: rpc_b2b_executive_alerts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_executive_alerts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  WITH credit AS (
    SELECT pa.id, pa.nome_fantasia, pa.razao_social, pfs.credit_limit,
      COALESCE((SELECT SUM(ari.original_amount - ari.received_amount)
        FROM accounts_receivable ar
        JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
        WHERE ar.origin_type='B2B_ORDER' AND ar.partner_id = pa.id
          AND ari.status IN ('OPEN','PARTIAL','OVERDUE')),0) AS aberto
    FROM partner_accounts pa
    LEFT JOIN partner_financial_settings pfs ON pfs.partner_id = pa.id
    WHERE pa.ativo = true AND pa.deleted_at IS NULL AND COALESCE(pfs.credit_limit,0) > 0
  ),
  classed AS (
    SELECT id, COALESCE(nome_fantasia, razao_social) AS nome, credit_limit, aberto,
      ROUND((aberto/credit_limit)*100,2) AS pct
    FROM credit
  )
  SELECT jsonb_build_object(
    'acima_80', (SELECT jsonb_agg(jsonb_build_object('partner_id',id,'nome',nome,'pct',pct,'aberto',aberto,'limite',credit_limit))
                 FROM classed WHERE pct >= 80 AND pct < 90),
    'acima_90', (SELECT jsonb_agg(jsonb_build_object('partner_id',id,'nome',nome,'pct',pct,'aberto',aberto,'limite',credit_limit))
                 FROM classed WHERE pct >= 90),
    'bloqueados', (SELECT jsonb_agg(jsonb_build_object('partner_id',po.partner_id,'numero',po.numero))
                   FROM partner_orders po WHERE po.status = 'aguardando_aprovacao_credito'),
    'com_vencidos', (SELECT jsonb_agg(jsonb_build_object('partner_id',prs.partner_id,'vencidos',prs.titulos_vencidos,'dias',prs.dias_medio_atraso))
                     FROM partner_risk_scores prs WHERE prs.titulos_vencidos > 0),
    'score_critico', (SELECT jsonb_agg(jsonb_build_object('partner_id',prs.partner_id,'score',prs.score))
                      FROM partner_risk_scores prs WHERE prs.risk_level = 'critico'),
    'receita_em_risco', (rpc_b2b_revenue_forecast(NULL)->>'em_risco')::numeric
  ) INTO v;
  RETURN v;
END;$$;


ALTER FUNCTION public.rpc_b2b_executive_alerts() OWNER TO postgres;

--
-- Name: rpc_b2b_executive_dashboard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_executive_dashboard() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb; kpis jsonb; fc jsonb;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  kpis := rpc_b2b_carteira_kpis(NULL,NULL);
  fc := rpc_b2b_revenue_forecast(NULL);

  WITH topp AS (
    SELECT pa.id, COALESCE(pa.nome_fantasia,pa.razao_social) AS nome, COALESCE(SUM(po.total),0) AS total
    FROM partner_orders po
    JOIN partner_accounts pa ON pa.id = po.partner_id
    WHERE po.status NOT IN ('cancelado','reprovado','rascunho')
      AND po.created_at >= date_trunc('year',now())
    GROUP BY pa.id, pa.nome_fantasia, pa.razao_social
    ORDER BY total DESC LIMIT 10
  ),
  topprod AS (
    SELECT pr.id, pr.nome, COALESCE(SUM(poi.subtotal),0) AS total, COALESCE(SUM(poi.quantidade),0) AS qtd
    FROM partner_order_items poi
    JOIN partner_orders po ON po.id = poi.order_id
    JOIN produtos pr ON pr.id = poi.product_id
    WHERE po.status NOT IN ('cancelado','reprovado','rascunho')
      AND po.created_at >= date_trunc('year',now())
    GROUP BY pr.id, pr.nome
    ORDER BY total DESC LIMIT 10
  )
  SELECT jsonb_build_object(
    'kpis', kpis,
    'forecast', fc,
    'parceiros_ativos', (SELECT COUNT(*) FROM partner_accounts WHERE ativo=true AND deleted_at IS NULL),
    'parceiros_bloqueados', (SELECT COUNT(DISTINCT partner_id) FROM partner_orders WHERE status='aguardando_aprovacao_credito'),
    'score_medio', (SELECT COALESCE(ROUND(AVG(score),2),0) FROM partner_risk_scores),
    'top_parceiros', (SELECT COALESCE(jsonb_agg(jsonb_build_object('partner_id',id,'nome',nome,'total',total)),'[]'::jsonb) FROM topp),
    'top_produtos', (SELECT COALESCE(jsonb_agg(jsonb_build_object('produto_id',id,'nome',nome,'total',total,'quantidade',qtd)),'[]'::jsonb) FROM topprod)
  ) INTO v;
  RETURN v;
END;$$;


ALTER FUNCTION public.rpc_b2b_executive_dashboard() OWNER TO postgres;

--
-- Name: rpc_b2b_financial_kpis(date, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_financial_kpis(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_partner_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_from date := COALESCE(p_from, date_trunc('month', CURRENT_DATE)::date);
  v_to date := COALESCE(p_to, CURRENT_DATE);
  v_result jsonb;
BEGIN
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'financeiro') OR has_role(v_uid,'gestor') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  WITH ar AS (
    SELECT a.*, i.due_date, i.original_amount, i.received_amount, i.status AS inst_status
    FROM public.accounts_receivable a
    JOIN public.accounts_receivable_installments i ON i.receivable_id = a.id
    WHERE a.origin_type='B2B_ORDER'
      AND a.created_at::date BETWEEN v_from AND v_to
      AND (p_partner_id IS NULL OR a.partner_id = p_partner_id)
  )
  SELECT jsonb_build_object(
    'total_a_receber', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL','OVERDUE') THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_recebido', COALESCE(SUM(received_amount),0),
    'total_vencido', COALESCE(SUM(CASE WHEN inst_status='OVERDUE' OR (inst_status IN ('OPEN','PARTIAL') AND due_date < CURRENT_DATE) THEN original_amount - COALESCE(received_amount,0) END),0),
    'total_em_aberto', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') THEN original_amount - COALESCE(received_amount,0) END),0),
    'ticket_medio', COALESCE(AVG(total_amount),0),
    'vencendo_7d', COALESCE(SUM(CASE WHEN inst_status IN ('OPEN','PARTIAL') AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+7 THEN original_amount - COALESCE(received_amount,0) END),0)
  ) INTO v_result FROM ar;

  v_result := v_result || jsonb_build_object(
    'pedidos_entregues_sem_cobranca', (
      SELECT COUNT(*) FROM public.partner_orders po
      WHERE po.status='entregue' AND po.receivable_generated=false
        AND (p_partner_id IS NULL OR po.partner_id = p_partner_id)
    ),
    'parceiros_inadimplentes', (
      SELECT COUNT(DISTINCT partner_id) FROM public.accounts_receivable a
      JOIN public.accounts_receivable_installments i ON i.receivable_id=a.id
      WHERE a.origin_type='B2B_ORDER' AND (i.status='OVERDUE' OR (i.status IN ('OPEN','PARTIAL') AND i.due_date < CURRENT_DATE))
    )
  );

  RETURN v_result;
END $$;


ALTER FUNCTION public.rpc_b2b_financial_kpis(p_from date, p_to date, p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_b2b_governance_kpis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_governance_kpis() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_concedido numeric := 0;
  v_total_utilizado numeric := 0;
  v_total_disponivel numeric := 0;
  v_bloqueados int := 0;
  v_vencidos numeric := 0;
  v_recebido_mes numeric := 0;
  v_inad_pct numeric := 0;
  v_receita numeric := 0;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  SELECT COALESCE(SUM(credit_limit),0) INTO v_total_concedido
    FROM public.partner_financial_settings WHERE active;

  SELECT COALESCE(SUM((ari.original_amount - ari.received_amount)),0) INTO v_total_utilizado
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE');

  v_total_disponivel := GREATEST(v_total_concedido - v_total_utilizado, 0);

  SELECT COUNT(DISTINCT partner_id) INTO v_bloqueados
    FROM public.partner_orders WHERE status = 'aguardando_aprovacao_credito';

  SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) INTO v_vencidos
    FROM public.accounts_receivable ar
    JOIN public.accounts_receivable_installments ari ON ari.receivable_id = ar.id
   WHERE ar.origin_type = 'B2B_ORDER' AND ar.status <> 'CANCELED'
     AND ari.status IN ('OPEN','PARTIAL','OVERDUE') AND ari.due_date < current_date;

  SELECT COALESCE(SUM(rp.amount_received),0) INTO v_recebido_mes
    FROM public.receivable_payments rp
    JOIN public.accounts_receivable_installments ari ON ari.id = rp.installment_id
    JOIN public.accounts_receivable ar ON ar.id = ari.receivable_id
   WHERE ar.origin_type = 'B2B_ORDER'
     AND date_trunc('month', rp.payment_date) = date_trunc('month', current_date);

  SELECT COALESCE(SUM(total),0) INTO v_receita
    FROM public.partner_orders
   WHERE status IN ('entregue','faturado')
     AND date_trunc('month', created_at) = date_trunc('month', current_date);

  v_inad_pct := CASE WHEN v_total_utilizado > 0
                     THEN ROUND((v_vencidos / v_total_utilizado) * 100, 2)
                     ELSE 0 END;

  RETURN jsonb_build_object(
    'credito_total_concedido', v_total_concedido,
    'credito_utilizado', v_total_utilizado,
    'credito_disponivel', v_total_disponivel,
    'parceiros_bloqueados', v_bloqueados,
    'titulos_vencidos', v_vencidos,
    'recebimentos_mes', v_recebido_mes,
    'inadimplencia_pct', v_inad_pct,
    'receita_b2b_mes', v_receita
  );
END;$$;


ALTER FUNCTION public.rpc_b2b_governance_kpis() OWNER TO postgres;

--
-- Name: rpc_b2b_integrity_check(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_integrity_check() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb;
begin
  if not public.has_role(auth.uid(), 'administrador'::public.app_role)
     and not public.has_role(auth.uid(), 'gestor'::public.app_role) then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'pedido_sem_parceiro',
      (select count(*) from public.partner_orders po
       where not exists (select 1 from public.partner_accounts pa where pa.id = po.partner_id)),
    'planejamento_sem_pedido',
      (select count(*) from public.production_planning pp
       where not exists (select 1 from public.partner_orders po where po.id = pp.partner_order_id)),
    'os_sem_planejamento',
      (select count(*) from public.ordens_servico os
       where os.origem = 'b2b' and os.partner_order_id is not null
         and not exists (select 1 from public.production_order_link pol where pol.ordem_servico_id = os.id)),
    'timeline_orfa',
      (select count(*) from public.production_timeline_events ev
       where not exists (select 1 from public.partner_orders po where po.id = ev.partner_order_id)),
    'os_orfa_b2b',
      (select count(*) from public.ordens_servico os
       where os.origem = 'b2b' and (os.partner_order_id is null or os.partner_order_item_id is null)),
    'itens_sem_produto',
      (select count(*) from public.partner_order_items poi
       where not exists (select 1 from public.produtos p where p.id = poi.product_id)),
    'links_invalidos',
      (select count(*) from public.production_order_link pol
       where not exists (select 1 from public.ordens_servico os where os.id = pol.ordem_servico_id))
  ) into v;
  return v;
end;
$$;


ALTER FUNCTION public.rpc_b2b_integrity_check() OWNER TO postgres;

--
-- Name: rpc_b2b_list_selectable_payment_plans(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_list_selectable_payment_plans() RETURNS TABLE(id uuid, code text, name text, description text, plan_type text, max_days integer, months_count numeric, installment_count integer, discount_percent numeric, monthly_interest_percent numeric, interest_type text, pricing_mode text, minimum_order_amount numeric, requires_credit_approval boolean, requires_guarantee boolean, requires_financial_approval boolean, is_default boolean, sort_order integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_admin boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authorized'; END IF;
  v_admin := public.has_role(v_uid,'administrador'::app_role)
          OR public.has_role(v_uid,'financeiro'::app_role)
          OR public.has_role(v_uid,'gestor_comercial'::app_role);
  IF NOT (v_admin OR public.has_role(v_uid,'parceiro_b2b'::app_role)) THEN
    RAISE EXCEPTION 'not_authorized';
  END IF;

  RETURN QUERY
  SELECT p.id, p.code, p.name, p.description, p.plan_type::text,
         p.max_days, p.months_count, p.installment_count,
         p.discount_percent, p.monthly_interest_percent,
         p.interest_type::text, p.pricing_mode::text, p.minimum_order_amount,
         p.requires_credit_approval, p.requires_guarantee, p.requires_financial_approval,
         p.is_default, p.sort_order
  FROM public.commercial_payment_plans p
  WHERE p.active = true
    AND p.superseded_by_id IS NULL
    AND p.valid_from <= now()
    AND (p.valid_until IS NULL OR p.valid_until > now())
    AND (
      v_admin
      OR EXISTS (
        SELECT 1
          FROM public.commercial_payment_plan_assignments a
          JOIN public.partner_users pu ON pu.partner_id = a.partner_id
         WHERE a.plan_id = p.id
           AND a.status = 'published'
           AND a.buyer_scope = 'partner'
           AND pu.user_id = v_uid
           AND a.valid_from <= CURRENT_DATE
           AND (a.valid_until IS NULL OR a.valid_until >= CURRENT_DATE)
      )
    )
  ORDER BY p.sort_order, p.name;
END
$$;


ALTER FUNCTION public.rpc_b2b_list_selectable_payment_plans() OWNER TO postgres;

