--
-- Name: rpc_b2b_partner_profitability(date, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_partner_profitability(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_partner_id uuid DEFAULT NULL::uuid) RETURNS TABLE(partner_id uuid, partner_name text, total_comprado numeric, total_recebido numeric, total_aberto numeric, ticket_medio numeric, qtd_pedidos integer, prazo_medio_pgto numeric, inadimplencia_pct numeric, risk_score integer, risk_level text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  -- H7O: autorização explícita (antes: filtro h7n_guarded devolvia 0 linhas).
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
       OR public.has_role(auth.uid(), 'gestor'::public.app_role)
       OR public.has_role(auth.uid(), 'financeiro'::public.app_role)
       OR public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
       OR public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
      HINT = 'H7O: rentabilidade B2B restrita a administrador/gestor/financeiro/gestor_comercial/administrativo.';
  END IF;

  RETURN QUERY
  WITH pedidos AS (
    SELECT po.partner_id, COUNT(*) AS qtd, SUM(po.total) AS total
    FROM partner_orders po
    WHERE po.status NOT IN ('cancelado','reprovado','rascunho')
      AND (p_from IS NULL OR po.created_at >= p_from)
      AND (p_to   IS NULL OR po.created_at <= (p_to + 1))
      AND (p_partner_id IS NULL OR po.partner_id = p_partner_id)
    GROUP BY po.partner_id
  ),
  recebidos AS (
    SELECT ar.partner_id,
      SUM(ari.received_amount) AS rec,
      SUM(ari.original_amount - ari.received_amount) FILTER (WHERE ari.status IN ('OPEN','PARTIAL','OVERDUE')) AS aberto,
      AVG(CASE WHEN ari.paid_at IS NOT NULL THEN EXTRACT(EPOCH FROM (ari.paid_at - ar.issue_date))/86400 END) AS prazo_med,
      SUM(ari.original_amount - ari.received_amount) FILTER (WHERE ari.due_date < CURRENT_DATE AND ari.status IN ('OPEN','PARTIAL','OVERDUE')) AS vencido
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type='B2B_ORDER'
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
    GROUP BY ar.partner_id
  )
  SELECT pa.id, COALESCE(pa.nome_fantasia, pa.razao_social),
    COALESCE(p.total,0),
    COALESCE(r.rec,0),
    COALESCE(r.aberto,0),
    CASE WHEN COALESCE(p.qtd,0) > 0 THEN ROUND(p.total/p.qtd,2) ELSE 0 END,
    COALESCE(p.qtd,0)::int,
    ROUND(COALESCE(r.prazo_med,0)::numeric,2),
    CASE WHEN COALESCE(p.total,0) > 0 THEN ROUND((COALESCE(r.vencido,0)/p.total)*100,2) ELSE 0 END,
    COALESCE(prs.score,0),
    COALESCE(prs.risk_level,'baixo')
  FROM partner_accounts pa
  LEFT JOIN pedidos p ON p.partner_id = pa.id
  LEFT JOIN recebidos r ON r.partner_id = pa.id
  LEFT JOIN partner_risk_scores prs ON prs.partner_id = pa.id
  WHERE pa.ativo = true AND pa.deleted_at IS NULL
    AND (p_partner_id IS NULL OR pa.id = p_partner_id)
    AND (p.qtd IS NOT NULL OR r.rec IS NOT NULL)
  ORDER BY COALESCE(p.total,0) DESC;
END
$$;


ALTER FUNCTION public.rpc_b2b_partner_profitability(p_from date, p_to date, p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_b2b_revenue_forecast(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_b2b_revenue_forecast(p_partner_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor'::public.app_role)
      or public.has_role(auth.uid(), 'financeiro'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or public.has_role(auth.uid(), 'administrativo'::public.app_role)) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  WITH conf AS (
    SELECT
      SUM(CASE WHEN ari.due_date <= CURRENT_DATE + 30 THEN ari.original_amount - ari.received_amount ELSE 0 END) AS c30,
      SUM(CASE WHEN ari.due_date <= CURRENT_DATE + 60 THEN ari.original_amount - ari.received_amount ELSE 0 END) AS c60,
      SUM(CASE WHEN ari.due_date <= CURRENT_DATE + 90 THEN ari.original_amount - ari.received_amount ELSE 0 END) AS c90
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    WHERE ar.origin_type='B2B_ORDER' AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
  ),
  proj AS (
    SELECT COALESCE(SUM(total),0) AS p30
    FROM partner_orders WHERE receivable_generated = false
      AND status IN ('aprovado','em_producao','produzido','aguardando_entrega','em_separacao','enviado','entregue')
      AND (p_partner_id IS NULL OR partner_id = p_partner_id)
  ),
  risk AS (
    SELECT COALESCE(SUM(ari.original_amount - ari.received_amount),0) AS r
    FROM accounts_receivable ar
    JOIN accounts_receivable_installments ari ON ari.receivable_id = ar.id
    LEFT JOIN partner_risk_scores prs ON prs.partner_id = ar.partner_id
    WHERE ar.origin_type='B2B_ORDER' AND ari.status IN ('OPEN','PARTIAL','OVERDUE')
      AND (ari.due_date < CURRENT_DATE OR COALESCE(prs.risk_level,'baixo')='critico')
      AND (p_partner_id IS NULL OR ar.partner_id = p_partner_id)
  )
  SELECT jsonb_build_object(
    'confirmada_30', COALESCE((SELECT c30 FROM conf),0),
    'confirmada_60', COALESCE((SELECT c60 FROM conf),0),
    'confirmada_90', COALESCE((SELECT c90 FROM conf),0),
    'projetada', COALESCE((SELECT p30 FROM proj),0),
    'em_risco', COALESCE((SELECT r FROM risk),0)
  ) INTO v;
  RETURN v;
END;$$;


ALTER FUNCTION public.rpc_b2b_revenue_forecast(p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_bi_esteira_resumo(timestamp with time zone, timestamp with time zone, uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_bi_esteira_resumo(p_data_inicio timestamp with time zone DEFAULT (now() - '30 days'::interval), p_data_fim timestamp with time zone DEFAULT now(), p_cliente_id uuid DEFAULT NULL::uuid, p_fazenda_id uuid DEFAULT NULL::uuid, p_produto_id uuid DEFAULT NULL::uuid, p_microrganismo_id uuid DEFAULT NULL::uuid, p_origem_os text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF NOT public.can_view_bi_operacional(v_uid) THEN
    RETURN jsonb_build_object(
      'total_os', 0, 'ok', false, 'reason', 'sem_permissao'
    );
  END IF;

  WITH base AS (
    SELECT m.*
    FROM public.mv_esteira_laboratorio m
    WHERE m.created_at >= p_data_inicio
      AND m.created_at <= p_data_fim
      AND (p_cliente_id IS NULL OR m.cliente_id = p_cliente_id)
      AND (p_fazenda_id IS NULL OR m.fazenda_id = p_fazenda_id)
      AND (p_produto_id IS NULL OR m.produto_id = p_produto_id)
      AND (p_microrganismo_id IS NULL OR m.microrganismo_id = p_microrganismo_id)
      AND (p_origem_os IS NULL OR m.origem_os = p_origem_os)
      AND (p_status IS NULL OR m.status_esteira_oficial = p_status)
      -- Escopo por consultor/técnico
      AND (
        public.has_role(v_uid, 'administrador') OR public.has_role(v_uid, 'gestor')
        OR public.has_role(v_uid, 'administrativo') OR public.has_role(v_uid, 'producao')
        OR public.has_role(v_uid, 'financeiro')
        OR (
          (public.has_role(v_uid, 'consultor_tecnico') OR public.has_role(v_uid, 'tecnico_agronomo'))
          AND m.cliente_id = ANY (public.get_cliente_ids_for_user(v_uid))
        )
      )
  )
  SELECT jsonb_build_object(
    'total_os', count(*),
    'os_abertas', count(*) FILTER (WHERE status_os NOT IN ('finalizada','cancelada')),
    'os_finalizadas', count(*) FILTER (WHERE status_os = 'finalizada'),
    'os_atrasadas', count(*) FILTER (WHERE atrasado = true),
    'aguardando_cq', count(*) FILTER (WHERE cq_resultado IS NULL AND lote_id IS NOT NULL),
    'cq_aprovado', count(*) FILTER (WHERE cq_resultado = 'aprovado'),
    'cq_reprovado', count(*) FILTER (WHERE cq_resultado = 'reprovado'),
    'envases_realizados', count(*) FILTER (WHERE envase_id IS NOT NULL),
    'entregas_realizadas', count(*) FILTER (WHERE entrega_id IS NOT NULL),
    'entregas_confirmadas', count(*) FILTER (WHERE entrega_confirmada = true),
    'pendencias_bloqueantes', count(*) FILTER (WHERE array_length(bloqueios, 1) > 0),
    'pode_finalizar', count(*) FILTER (WHERE pode_finalizar = true),
    'volume_solicitado_l', coalesce(sum(volume_solicitado_l), 0),
    'tempo_medio_os_ate_entrega_h', coalesce(avg(tempo_os_ate_entrega), 0),
    'tempo_medio_cq_ate_envase_h', coalesce(avg(tempo_cq_ate_envase), 0),
    'por_status', (
      SELECT jsonb_object_agg(coalesce(status_esteira_oficial,'sem_status'), qtd)
      FROM (SELECT status_esteira_oficial, count(*) AS qtd FROM base GROUP BY status_esteira_oficial) s
    ),
    'por_origem', (
      SELECT jsonb_object_agg(coalesce(origem_os,'sem_origem'), qtd)
      FROM (SELECT origem_os, count(*) AS qtd FROM base GROUP BY origem_os) s
    ),
    'ok', true
  ) INTO v_result FROM base;

  RETURN coalesce(v_result, jsonb_build_object('total_os', 0, 'ok', true));
END;
$$;


ALTER FUNCTION public.rpc_bi_esteira_resumo(p_data_inicio timestamp with time zone, p_data_fim timestamp with time zone, p_cliente_id uuid, p_fazenda_id uuid, p_produto_id uuid, p_microrganismo_id uuid, p_origem_os text, p_status text) OWNER TO postgres;

--
-- Name: rpc_bi_fluxo_visitas_resumo(timestamp with time zone, timestamp with time zone, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_bi_fluxo_visitas_resumo(p_data_inicio timestamp with time zone DEFAULT (now() - '30 days'::interval), p_data_fim timestamp with time zone DEFAULT now(), p_cliente_id uuid DEFAULT NULL::uuid, p_fazenda_id uuid DEFAULT NULL::uuid, p_consultor_id uuid DEFAULT NULL::uuid, p_status_solicitacao text DEFAULT NULL::text, p_status_visita text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_result jsonb;
BEGIN
  IF NOT public.can_view_bi_operacional(v_uid) THEN
    RETURN jsonb_build_object('total_visitas', 0, 'ok', false, 'reason', 'sem_permissao');
  END IF;

  WITH base AS (
    SELECT m.*
    FROM public.mv_fluxo_visita_tecnica m
    WHERE m.created_at >= p_data_inicio
      AND m.created_at <= p_data_fim
      AND (p_cliente_id IS NULL OR m.cliente_id = p_cliente_id)
      AND (p_fazenda_id IS NULL OR m.fazenda_id = p_fazenda_id)
      AND (p_consultor_id IS NULL OR m.consultor_id = p_consultor_id)
      AND (p_status_solicitacao IS NULL OR m.status_solicitacao = p_status_solicitacao)
      AND (p_status_visita IS NULL OR m.status_visita = p_status_visita)
      AND (
        public.has_role(v_uid, 'administrador') OR public.has_role(v_uid, 'gestor')
        OR public.has_role(v_uid, 'administrativo') OR public.has_role(v_uid, 'producao')
        OR public.has_role(v_uid, 'financeiro')
        OR (
          (public.has_role(v_uid, 'consultor_tecnico') OR public.has_role(v_uid, 'tecnico_agronomo'))
          AND (m.consultor_id = v_uid OR m.cliente_id = ANY (public.get_cliente_ids_for_user(v_uid)))
        )
      )
  )
  SELECT jsonb_build_object(
    'total_visitas', count(*),
    'solicitacoes_abertas', count(*) FILTER (WHERE status_solicitacao NOT IN ('concluida','cancelada','convertida_os')),
    'com_checkin', count(*) FILTER (WHERE possui_checkin = true),
    'com_diagnostico', count(*) FILTER (WHERE possui_diagnostico = true),
    'com_evidencias', count(*) FILTER (WHERE possui_evidencias = true),
    'com_recomendacao', count(*) FILTER (WHERE possui_recomendacao = true),
    'convertidas_em_os', count(*) FILTER (WHERE possui_os = true),
    'aprovadas', count(*) FILTER (WHERE status_aprovacao = 'aprovado'),
    'em_atraso', count(*) FILTER (WHERE array_length(bloqueios, 1) > 0),
    'dias_medios_em_aberto', coalesce(avg(dias_em_aberto), 0),
    'tempo_medio_solicitacao_ate_checkin_h', coalesce(avg(tempo_solicitacao_ate_checkin), 0),
    'por_status_solicitacao', (
      SELECT jsonb_object_agg(coalesce(status_solicitacao,'sem_status'), qtd)
      FROM (SELECT status_solicitacao, count(*) AS qtd FROM base GROUP BY status_solicitacao) s
    ),
    'por_status_visita', (
      SELECT jsonb_object_agg(coalesce(status_visita,'sem_status'), qtd)
      FROM (SELECT status_visita, count(*) AS qtd FROM base GROUP BY status_visita) s
    ),
    'por_consultor', (
      SELECT jsonb_object_agg(coalesce(consultor_nome, consultor_id::text, 'sem_consultor'), qtd)
      FROM (SELECT consultor_id, consultor_nome, count(*) AS qtd FROM base GROUP BY consultor_id, consultor_nome ORDER BY count(*) DESC LIMIT 20) s
    ),
    'ok', true
  ) INTO v_result FROM base;

  RETURN coalesce(v_result, jsonb_build_object('total_visitas', 0, 'ok', true));
END;
$$;


ALTER FUNCTION public.rpc_bi_fluxo_visitas_resumo(p_data_inicio timestamp with time zone, p_data_fim timestamp with time zone, p_cliente_id uuid, p_fazenda_id uuid, p_consultor_id uuid, p_status_solicitacao text, p_status_visita text) OWNER TO postgres;

--
-- Name: rpc_bi_visitas_por_cliente(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_bi_visitas_por_cliente(p_cliente_id uuid, p_data_inicio date DEFAULT NULL::date, p_data_fim date DEFAULT NULL::date) RETURNS SETOF public._src_vw_fluxo_visita_tecnica
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_data_inicio date := COALESCE(p_data_inicio, (current_date - interval '365 days')::date);
  v_data_fim    date := COALESCE(p_data_fim, current_date);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT v.*
    FROM public.vw_fluxo_visita_tecnica v
    WHERE v.cliente_id = p_cliente_id
      AND COALESCE(v.created_at, now())::date BETWEEN v_data_inicio AND v_data_fim;

EXCEPTION WHEN OTHERS THEN
  RETURN;
END;
$$;


ALTER FUNCTION public.rpc_bi_visitas_por_cliente(p_cliente_id uuid, p_data_inicio date, p_data_fim date) OWNER TO postgres;

