CREATE TABLE public.commercial_payment_plan_assignments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    plan_id uuid NOT NULL,
    buyer_scope text NOT NULL,
    partner_id uuid,
    customer_id uuid,
    status text DEFAULT 'draft'::text NOT NULL,
    valid_from date DEFAULT CURRENT_DATE NOT NULL,
    valid_until date,
    motivo text,
    submitted_by uuid,
    submitted_at timestamp with time zone,
    published_by uuid,
    published_at timestamp with time zone,
    archived_by uuid,
    archived_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT commercial_payment_plan_assignments_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'published'::text, 'archived'::text]))),
    CONSTRAINT cppa_buyer_scope_ck CHECK ((buyer_scope = ANY (ARRAY['partner'::text, 'producer'::text, 'default'::text]))),
    CONSTRAINT cppa_scope_target_ck CHECK ((((buyer_scope = 'partner'::text) AND (partner_id IS NOT NULL) AND (customer_id IS NULL)) OR ((buyer_scope = 'producer'::text) AND (customer_id IS NOT NULL) AND (partner_id IS NULL)) OR ((buyer_scope = 'default'::text) AND (partner_id IS NULL) AND (customer_id IS NULL)))),
    CONSTRAINT cppa_validity_ck CHECK (((valid_until IS NULL) OR (valid_until >= valid_from)))
);


