--
-- Name: commercial_condition_item_prices; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.commercial_condition_item_prices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_id uuid,
    plan_id uuid NOT NULL,
    buyer_scope text NOT NULL,
    partner_id uuid,
    customer_id uuid,
    product_id uuid,
    microrganismo_id uuid,
    unit_type text NOT NULL,
    volume_ml numeric,
    min_quantity numeric DEFAULT 0 NOT NULL,
    pricing_mode text NOT NULL,
    condition_price numeric,
    discount_percent numeric,
    currency text DEFAULT 'BRL'::text NOT NULL,
    valid_from date DEFAULT CURRENT_DATE NOT NULL,
    valid_until date,
    status text DEFAULT 'draft'::text NOT NULL,
    motivo text,
    is_exception boolean DEFAULT false NOT NULL,
    published_rule_id uuid,
    published_by uuid,
    published_at timestamp with time zone,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ccip_buyer_scope_ck CHECK ((buyer_scope = ANY (ARRAY['partner'::text, 'producer'::text, 'default'::text]))),
    CONSTRAINT ccip_item_ck CHECK ((((product_id IS NOT NULL) AND (microrganismo_id IS NULL)) OR ((product_id IS NULL) AND (microrganismo_id IS NOT NULL)))),
    CONSTRAINT ccip_mode_value_ck CHECK ((((pricing_mode = 'fixed_item_price'::text) AND (condition_price IS NOT NULL)) OR ((pricing_mode = 'discount_from_base'::text) AND (discount_percent IS NOT NULL)) OR (pricing_mode = 'quote_only'::text))),
    CONSTRAINT ccip_scope_target_ck CHECK ((((buyer_scope = 'partner'::text) AND (partner_id IS NOT NULL) AND (customer_id IS NULL)) OR ((buyer_scope = 'producer'::text) AND (customer_id IS NOT NULL) AND (partner_id IS NULL)) OR ((buyer_scope = 'default'::text) AND (partner_id IS NULL) AND (customer_id IS NULL)))),
    CONSTRAINT ccip_validity_ck CHECK (((valid_until IS NULL) OR (valid_until >= valid_from))),
    CONSTRAINT ccip_volume_ck CHECK (((unit_type <> 'unidade'::text) OR (volume_ml IS NOT NULL))),
    CONSTRAINT commercial_condition_item_prices_condition_price_check CHECK (((condition_price IS NULL) OR (condition_price >= (0)::numeric))),
    CONSTRAINT commercial_condition_item_prices_discount_percent_check CHECK (((discount_percent IS NULL) OR ((discount_percent >= (0)::numeric) AND (discount_percent <= (100)::numeric)))),
    CONSTRAINT commercial_condition_item_prices_min_quantity_check CHECK ((min_quantity >= (0)::numeric)),
    CONSTRAINT commercial_condition_item_prices_pricing_mode_check CHECK ((pricing_mode = ANY (ARRAY['fixed_item_price'::text, 'discount_from_base'::text, 'quote_only'::text]))),
    CONSTRAINT commercial_condition_item_prices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'pending_approval'::text, 'published'::text, 'archived'::text]))),
    CONSTRAINT commercial_condition_item_prices_unit_type_check CHECK ((unit_type = ANY (ARRAY['hectare'::text, 'dose'::text, 'litro'::text, 'unidade'::text])))
);


