--
-- Name: rpc_cc_publish_assignment(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_publish_assignment(p_id uuid, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_publish(auth.uid()) THEN RAISE EXCEPTION 'not_authorized_publish'; END IF;
  UPDATE public.commercial_payment_plan_assignments
     SET status='published', published_by=auth.uid(), published_at=now(), updated_by=auth.uid()
   WHERE id=p_id AND status IN ('draft','pending_approval');
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_transition'; END IF;
  PERFORM public.fn_cc_audit('assignment',p_id,'publish',NULL,NULL,p_motivo);
END $$;


ALTER FUNCTION public.rpc_cc_publish_assignment(p_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cc_publish_item_prices(uuid[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_publish_item_prices(p_ids uuid[], p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_rule uuid; v_count int := 0;
BEGIN
  IF NOT public.fn_cc_can_publish(auth.uid()) THEN RAISE EXCEPTION 'not_authorized_publish'; END IF;
  IF p_ids IS NULL OR array_length(p_ids,1) IS NULL THEN RAISE EXCEPTION 'no_items'; END IF;

  IF EXISTS(SELECT 1 FROM unnest(p_ids) x(id) WHERE x.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.commercial_condition_item_prices i WHERE i.id=x.id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id))) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  FOR r IN SELECT * FROM public.commercial_condition_item_prices
            WHERE id = ANY(p_ids) AND status IN ('draft','pending_approval') FOR UPDATE
  LOOP
    IF NOT platform_private.c2p1_assignment_allowed(r.buyer_scope,r.partner_id,r.customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF NOT platform_private.c2p1_item_allowed(r.assignment_id,r.plan_id,r.buyer_scope,r.partner_id,r.customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.plan_id=r.plan_id AND a.buyer_scope=r.buyer_scope AND a.partner_id IS NOT DISTINCT FROM r.partner_id AND a.customer_id IS NOT DISTINCT FROM r.customer_id AND (r.assignment_id IS NULL OR a.id=r.assignment_id) AND a.status='published' ORDER BY a.id FOR SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION 'assignment_not_published'; END IF;
    IF r.buyer_scope = 'default' THEN RAISE EXCEPTION 'default_scope_not_publishable'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.commercial_payment_plan_assignments a
                    WHERE (r.assignment_id IS NULL OR a.id=r.assignment_id) AND a.status='published' AND a.plan_id=r.plan_id
                      AND a.buyer_scope=r.buyer_scope
                      AND a.partner_id IS NOT DISTINCT FROM r.partner_id
                      AND a.customer_id IS NOT DISTINCT FROM r.customer_id) THEN
      RAISE EXCEPTION 'assignment_not_published';
    END IF;

    UPDATE public.commercial_price_rules
       SET active=false, updated_by=auth.uid(), updated_at=now()
     WHERE active
       AND plan_id = r.plan_id AND buyer_scope = r.buyer_scope
       AND partner_id IS NOT DISTINCT FROM r.partner_id
       AND customer_id IS NOT DISTINCT FROM r.customer_id
       AND product_id IS NOT DISTINCT FROM r.product_id
       AND microrganismo_id IS NOT DISTINCT FROM r.microrganismo_id
       AND unit_type = r.unit_type
       AND volume_ml IS NOT DISTINCT FROM r.volume_ml;

    INSERT INTO public.commercial_price_rules
      (buyer_scope,partner_id,customer_id,plan_id,product_id,microrganismo_id,unit_type,volume_ml,
       pricing_mode,condition_price,discount_percent,min_quantity,currency,valid_from,valid_until,active,motivo,
       created_by,updated_by)
    VALUES (r.buyer_scope,r.partner_id,r.customer_id,r.plan_id,r.product_id,r.microrganismo_id,
       r.unit_type,r.volume_ml,r.pricing_mode,
       CASE WHEN r.pricing_mode='fixed_item_price' THEN r.condition_price ELSE NULL END,
       CASE WHEN r.pricing_mode='discount_from_base' THEN r.discount_percent ELSE NULL END,
       COALESCE(r.min_quantity,0),
       COALESCE(r.currency,'BRL'),r.valid_from,r.valid_until,true,
       COALESCE(p_motivo, r.motivo), auth.uid(), auth.uid())
    RETURNING id INTO v_rule;

    UPDATE public.commercial_condition_item_prices
       SET status='published', published_by=auth.uid(), published_at=now(),
           published_rule_id=v_rule, updated_by=auth.uid()
     WHERE id = r.id;

    PERFORM public.fn_cc_audit('item_price', r.id, 'publish', to_jsonb(r),
      jsonb_build_object('price_rule_id', v_rule), p_motivo);
    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('published', v_count);
END $$;


ALTER FUNCTION public.rpc_cc_publish_item_prices(p_ids uuid[], p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cc_simulate_price(text, uuid, uuid, uuid, uuid, uuid, text, numeric, date, numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_simulate_price(p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_plan_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric DEFAULT NULL::numeric, p_ref_date date DEFAULT CURRENT_DATE, p_quantity numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_uid uuid := auth.uid(); v_org uuid;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
 v_org := public.h15_actor_organization();
 IF v_org IS NULL THEN RAISE EXCEPTION 'ACTIVE_TENANT_REQUIRED' USING ERRCODE='42501'; END IF;
 IF NOT public.fn_cc_can_prepare(v_uid) OR NOT public._saas_user_has_feature(v_uid,'catalogo_precos') THEN
  RAISE EXCEPTION 'not_authorized' USING ERRCODE='42501';
 END IF;
 IF COALESCE(p_buyer_scope,'partner') <> 'partner' OR p_customer_id IS NOT NULL THEN
  RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED' USING ERRCODE='P0001';
 END IF;
 -- Only commercial ownership proves internal A. CNPJ, tenant P and user links never authorize here.
 IF p_partner_id IS NULL OR NOT EXISTS (
  SELECT 1 FROM public.partner_accounts pa
  WHERE pa.id=p_partner_id AND pa.commercial_owner_organization_id=v_org
   AND pa.ativo IS TRUE AND pa.deleted_at IS NULL
   AND (pa.client_id IS NULL OR EXISTS (
    SELECT 1 FROM public.clientes c WHERE c.id=pa.client_id AND c.organization_id=v_org
   ))
 ) THEN RAISE EXCEPTION 'COMMERCIAL_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF p_quantity IS NOT NULL AND (p_quantity <= 0 OR p_quantity::text IN ('NaN','Infinity','-Infinity')) THEN
  RAISE EXCEPTION 'QUANTITY_INVALID' USING ERRCODE='22023';
 END IF;
 IF p_volume_ml IS NOT NULL AND (p_volume_ml <= 0 OR p_volume_ml::text IN ('NaN','Infinity','-Infinity')) THEN
  RAISE EXCEPTION 'VOLUME_INVALID' USING ERRCODE='22023';
 END IF;
 IF NOT platform_private.c2p1_assignment_allowed('partner',p_partner_id,NULL) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Read-only canonical resolver; no order, credit, receivable, snapshot or fiscal writes.
 RETURN public.fn_resolve_commercial_price('partner',p_partner_id,NULL,p_plan_id,
  p_product_id,p_microrganismo_id,p_unit_type,p_volume_ml,p_ref_date,p_quantity);
END $$;


ALTER FUNCTION public.rpc_cc_simulate_price(p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_plan_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_ref_date date, p_quantity numeric) OWNER TO postgres;

--
-- Name: rpc_cc_submit_assignment(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_submit_assignment(p_id uuid, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  PERFORM 1 FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  UPDATE public.commercial_payment_plan_assignments
     SET status='pending_approval', submitted_by=auth.uid(), submitted_at=now(), updated_by=auth.uid()
   WHERE id=p_id AND status='draft';
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid_transition'; END IF;
  PERFORM public.fn_cc_audit('assignment',p_id,'submit',NULL,NULL,p_motivo);
END $$;


ALTER FUNCTION public.rpc_cc_submit_assignment(p_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cc_upsert_assignment(uuid, uuid, text, uuid, uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_upsert_assignment(p_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_valid_from date, p_valid_until date, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_before jsonb;
BEGIN
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF NOT platform_private.c2p1_assignment_allowed(p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF p_id IS NULL THEN
    INSERT INTO public.commercial_payment_plan_assignments
      (plan_id,buyer_scope,partner_id,customer_id,valid_from,valid_until,motivo,created_by,updated_by)
    VALUES (p_plan_id,p_buyer_scope,p_partner_id,p_customer_id,
            COALESCE(p_valid_from,CURRENT_DATE),p_valid_until,p_motivo,auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('assignment',v_id,'create',NULL,
      to_jsonb((SELECT a FROM public.commercial_payment_plan_assignments a WHERE a.id=v_id)),p_motivo);
  ELSE
    SELECT to_jsonb(a) INTO v_before FROM public.commercial_payment_plan_assignments a WHERE a.id=p_id AND platform_private.c2p1_assignment_allowed(a.buyer_scope,a.partner_id,a.customer_id) FOR UPDATE;
    IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF (v_before->>'status') <> 'draft' THEN RAISE EXCEPTION 'assignment_not_editable'; END IF;
    UPDATE public.commercial_payment_plan_assignments
       SET plan_id=p_plan_id, buyer_scope=p_buyer_scope, partner_id=p_partner_id, customer_id=p_customer_id,
           valid_from=COALESCE(p_valid_from,valid_from), valid_until=p_valid_until,
           motivo=p_motivo, updated_by=auth.uid()
     WHERE id=p_id RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('assignment',v_id,'update',v_before,
      to_jsonb((SELECT a FROM public.commercial_payment_plan_assignments a WHERE a.id=v_id)),p_motivo);
  END IF;
  RETURN v_id;
END $$;


ALTER FUNCTION public.rpc_cc_upsert_assignment(p_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_valid_from date, p_valid_until date, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cc_upsert_item_price(uuid, uuid, uuid, text, uuid, uuid, uuid, uuid, text, numeric, numeric, text, numeric, numeric, date, date, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_upsert_item_price(p_id uuid, p_assignment_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_min_quantity numeric, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric, p_valid_from date, p_valid_until date, p_is_exception boolean, p_motivo text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_before jsonb;
BEGIN
 IF NOT platform_private.c2p1_item_allowed(p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  IF p_is_exception AND (p_motivo IS NULL OR length(btrim(p_motivo))=0) THEN
    RAISE EXCEPTION 'motivo_required_for_exception';
  END IF;
  PERFORM public.fn_cc_validate_item_input(p_plan_id, p_pricing_mode, p_condition_price, p_discount_percent);

  IF p_id IS NULL THEN
    INSERT INTO public.commercial_condition_item_prices
      (assignment_id,plan_id,buyer_scope,partner_id,customer_id,product_id,microrganismo_id,
       unit_type,volume_ml,min_quantity,pricing_mode,condition_price,discount_percent,
       valid_from,valid_until,is_exception,motivo,created_by,updated_by)
    VALUES (p_assignment_id,p_plan_id,p_buyer_scope,p_partner_id,p_customer_id,p_product_id,p_microrganismo_id,
       p_unit_type,p_volume_ml,COALESCE(p_min_quantity,0),p_pricing_mode,p_condition_price,p_discount_percent,
       COALESCE(p_valid_from,CURRENT_DATE),p_valid_until,COALESCE(p_is_exception,false),p_motivo,auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'create',NULL,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  ELSE
    SELECT to_jsonb(i) INTO v_before FROM public.commercial_condition_item_prices i WHERE i.id=p_id AND platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) FOR UPDATE;
    IF v_before IS NULL THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
    IF (v_before->>'status') NOT IN ('draft','pending_approval') THEN RAISE EXCEPTION 'item_price_not_editable'; END IF;
    UPDATE public.commercial_condition_item_prices
       SET assignment_id=p_assignment_id, plan_id=p_plan_id, buyer_scope=p_buyer_scope,
           partner_id=p_partner_id, customer_id=p_customer_id, product_id=p_product_id,
           microrganismo_id=p_microrganismo_id, unit_type=p_unit_type, volume_ml=p_volume_ml,
           min_quantity=COALESCE(p_min_quantity,0), pricing_mode=p_pricing_mode,
           condition_price=p_condition_price, discount_percent=p_discount_percent,
           valid_from=COALESCE(p_valid_from,valid_from), valid_until=p_valid_until,
           is_exception=COALESCE(p_is_exception,false), motivo=p_motivo, updated_by=auth.uid()
     WHERE id=p_id RETURNING id INTO v_id;
    PERFORM public.fn_cc_audit('item_price',v_id,'update',v_before,
      to_jsonb((SELECT i FROM public.commercial_condition_item_prices i WHERE i.id=v_id)),p_motivo);
  END IF;
  RETURN v_id;
END $$;


ALTER FUNCTION public.rpc_cc_upsert_item_price(p_id uuid, p_assignment_id uuid, p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid, p_product_id uuid, p_microrganismo_id uuid, p_unit_type text, p_volume_ml numeric, p_min_quantity numeric, p_pricing_mode text, p_condition_price numeric, p_discount_percent numeric, p_valid_from date, p_valid_until date, p_is_exception boolean, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cc_validate_matrix(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cc_validate_matrix(p_plan_id uuid, p_buyer_scope text, p_partner_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_missing jsonb; v_drafts int; v_quote int;
BEGIN
 IF NOT platform_private.c2p1_assignment_allowed(p_buyer_scope,p_partner_id,p_customer_id) THEN RAISE EXCEPTION 'C2P1_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF NOT public.fn_cc_can_prepare(auth.uid()) THEN RAISE EXCEPTION 'not_authorized'; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('tipo',tipo,'id',id,'nome',nome)),'[]'::jsonb) INTO v_missing
  FROM (
    SELECT 'produto' tipo, p.id, p.nome FROM public.produtos p
     WHERE COALESCE(p.ativo,true)
       AND NOT EXISTS (SELECT 1 FROM public.commercial_condition_item_prices i
            WHERE platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) AND i.plan_id=p_plan_id AND i.product_id=p.id AND i.buyer_scope=p_buyer_scope
              AND i.partner_id IS NOT DISTINCT FROM p_partner_id
              AND i.customer_id IS NOT DISTINCT FROM p_customer_id
              AND i.status IN ('draft','pending_approval','published'))
    UNION ALL
    SELECT 'microrganismo', m.id, m.nome FROM public.microrganismos m
     WHERE COALESCE(m.ativo,true)
       AND NOT EXISTS (SELECT 1 FROM public.commercial_condition_item_prices i
            WHERE platform_private.c2p1_item_allowed(i.assignment_id,i.plan_id,i.buyer_scope,i.partner_id,i.customer_id) AND i.plan_id=p_plan_id AND i.microrganismo_id=m.id AND i.buyer_scope=p_buyer_scope
              AND i.partner_id IS NOT DISTINCT FROM p_partner_id
              AND i.customer_id IS NOT DISTINCT FROM p_customer_id
              AND i.status IN ('draft','pending_approval','published'))
  ) s;
  SELECT count(*) FILTER (WHERE status='draft'), count(*) FILTER (WHERE pricing_mode='quote_only')
    INTO v_drafts, v_quote
  FROM public.commercial_condition_item_prices
   WHERE platform_private.c2p1_item_allowed(assignment_id,plan_id,buyer_scope,partner_id,customer_id) AND plan_id=p_plan_id AND buyer_scope=p_buyer_scope
     AND partner_id IS NOT DISTINCT FROM p_partner_id
     AND customer_id IS NOT DISTINCT FROM p_customer_id;
  RETURN jsonb_build_object('ok', jsonb_array_length(v_missing)=0,
    'missing_items', v_missing, 'draft_count', COALESCE(v_drafts,0), 'quote_only_count', COALESCE(v_quote,0));
END $$;


ALTER FUNCTION public.rpc_cc_validate_matrix(p_plan_id uuid, p_buyer_scope text, p_partner_id uuid, p_customer_id uuid) OWNER TO postgres;

--
-- Name: rpc_certificacao_catalogo(text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_certificacao_catalogo(p_functions text[] DEFAULT '{}'::text[], p_tables text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'functions', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'name', p.proname,
        'identity_args', pg_get_function_identity_arguments(p.oid),
        'owner', pg_get_userbyid(p.proowner),
        'security_definer', p.prosecdef,
        'config', COALESCE(array_to_string(p.proconfig, ','), ''),
        'acl', COALESCE(array_to_string(p.proacl::text[], ' | '), 'DEFAULT'),
        'anon_execute', has_function_privilege('anon', p.oid, 'EXECUTE'),
        'public_execute', p.proacl IS NULL OR EXISTS (
          SELECT 1 FROM unnest(p.proacl::text[]) a WHERE a LIKE '=%'
        ),
        'authenticated_execute', has_function_privilege('authenticated', p.oid, 'EXECUTE'),
        'md5', md5(pg_get_functiondef(p.oid))
      ))
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public' AND p.proname = ANY(p_functions)
    ), '[]'::jsonb),
    'triggers', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'table', c.relname,
        'trigger', t.tgname,
        'enabled', t.tgenabled
      ))
      FROM pg_trigger t
      JOIN pg_class c ON c.oid = t.tgrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND NOT t.tgisinternal AND c.relname = ANY(p_tables)
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION public.rpc_certificacao_catalogo(p_functions text[], p_tables text[]) OWNER TO postgres;

--
-- Name: rpc_check_monitoramento_and_notify(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_check_monitoramento_and_notify(_registro_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  caller_uid uuid := auth.uid();
  v_consultor uuid; v_cliente uuid; v_data_prox date; v_talhao_id uuid;
  v_talhao_nome text; v_cliente_nome text; v_reserved_id uuid; v_notif_id uuid;
  v_hoje_br date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_idem text;
BEGIN
  IF caller_uid IS NOT NULL AND NOT has_role(caller_uid, 'administrador'::app_role) THEN
    RAISE EXCEPTION 'Sem autorização' USING ERRCODE='42501';
  END IF;
  IF _registro_id IS NULL THEN RAISE EXCEPTION 'registro_id obrigatório' USING ERRCODE='22023'; END IF;

  SELECT r.consultor_responsavel, r.cliente_id, r.data_proxima_visita, r.talhao_id, t.nome, c.nome
    INTO v_consultor, v_cliente, v_data_prox, v_talhao_id, v_talhao_nome, v_cliente_nome
    FROM public.registros_consultor r
    LEFT JOIN public.talhoes t ON t.id = r.talhao_id
    LEFT JOIN public.clientes c ON c.id = r.cliente_id
   WHERE r.id = _registro_id
     AND r.necessidade_intervencao = 'monitorar'
     AND r.status = 'finalizado'
     AND r.data_proxima_visita IS NOT NULL
     AND r.data_proxima_visita <= v_hoje_br
   FOR UPDATE;

  IF v_consultor IS NULL THEN
    RETURN jsonb_build_object('created', false, 'reason', 'not_eligible');
  END IF;

  INSERT INTO public.monitoramento_avisos (registro_consultor_id, tipo, data_referencia)
  VALUES (_registro_id, 'vencido', v_hoje_br)
  ON CONFLICT (registro_consultor_id, tipo, data_referencia) DO NOTHING
  RETURNING id INTO v_reserved_id;

  IF v_reserved_id IS NULL THEN
    RETURN jsonb_build_object('created', false, 'reason', 'duplicate');
  END IF;

  v_idem := format('monit-venc-%s-%s', _registro_id, v_hoje_br);
  INSERT INTO public.notificacoes_operacionais
    (usuario_id, tipo, titulo, mensagem, link, source_type, source_id, idempotency_key)
  VALUES (
    v_consultor, 'alerta', 'Monitoramento Vencido',
    format('A reavaliação do talhão %s (%s) venceu em %s.',
           coalesce(v_talhao_nome,'—'), coalesce(v_cliente_nome,'—'), v_data_prox),
    format('/visita-tecnica/%s', _registro_id),
    'monitoramento_vencido', _registro_id, v_idem
  ) ON CONFLICT DO NOTHING RETURNING id INTO v_notif_id;

  IF v_notif_id IS NULL THEN
    SELECT id INTO v_notif_id FROM public.notificacoes_operacionais
     WHERE idempotency_key = v_idem LIMIT 1;
  END IF;
  IF v_notif_id IS NULL THEN
    RAISE EXCEPTION 'Reserva sem notificação; revertendo' USING ERRCODE='23514';
  END IF;

  RETURN jsonb_build_object('created', true, 'aviso_id', v_reserved_id, 'notification_id', v_notif_id,
    'consultor_id', v_consultor, 'talhao_id', v_talhao_id,
    'talhao_nome', v_talhao_nome, 'cliente_nome', v_cliente_nome);
END;
$$;


ALTER FUNCTION public.rpc_check_monitoramento_and_notify(_registro_id uuid) OWNER TO postgres;

--
-- Name: comunicacao_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.comunicacao_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    rule_id uuid,
    template_id uuid,
    template_chave text NOT NULL,
    template_versao integer NOT NULL,
    template_snapshot jsonb NOT NULL,
    canal public.comunicacao_canal NOT NULL,
    recipient_user_id uuid,
    recipient_cliente_id uuid,
    recipient_hash text,
    payload_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    status public.comunicacao_outbox_status DEFAULT 'pending'::public.comunicacao_outbox_status NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    lease_expires_at timestamp with time zone,
    provider_message_id text,
    error_code text,
    error_message text,
    sent_at timestamp with time zone,
    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    provider_delivery_status text,
    provider_status_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    provider_failed_at timestamp with time zone,
    CONSTRAINT comunicacao_outbox_attempts_chk CHECK (((attempts >= 0) AND (attempts <= 50))),
    CONSTRAINT comunicacao_outbox_error_chk CHECK (((error_message IS NULL) OR (length(error_message) <= 2000))),
    CONSTRAINT comunicacao_outbox_error_code_chk CHECK (((error_code IS NULL) OR (length(error_code) <= 80))),
    CONSTRAINT comunicacao_outbox_idem_chk CHECK (((length(idempotency_key) >= 8) AND (length(idempotency_key) <= 250))),
    CONSTRAINT comunicacao_outbox_max_chk CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT comunicacao_outbox_payload_obj CHECK (((jsonb_typeof(payload_snapshot) = 'object'::text) AND (length((payload_snapshot)::text) <= 8000))),
    CONSTRAINT comunicacao_outbox_provider_delivery_status_chk CHECK (((provider_delivery_status IS NULL) OR (provider_delivery_status = ANY (ARRAY['sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'deleted'::text])))),
    CONSTRAINT comunicacao_outbox_provider_id_chk CHECK (((provider_message_id IS NULL) OR (length(provider_message_id) <= 200))),
    CONSTRAINT comunicacao_outbox_recipient_chk CHECK (((recipient_user_id IS NOT NULL) OR (recipient_cliente_id IS NOT NULL) OR (recipient_hash IS NOT NULL))),
    CONSTRAINT comunicacao_outbox_snapshot_obj CHECK (((jsonb_typeof(template_snapshot) = 'object'::text) AND (length((template_snapshot)::text) <= 40000))),
    CONSTRAINT comunicacao_outbox_worker_chk CHECK (((locked_by IS NULL) OR ((length(locked_by) >= 1) AND (length(locked_by) <= 80))))
);


ALTER TABLE public.comunicacao_outbox OWNER TO postgres;

--
-- Name: rpc_claim_communication_outbox(integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_claim_communication_outbox(p_batch_size integer, p_worker_id text, p_lease_seconds integer DEFAULT 60) RETURNS SETOF public.comunicacao_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_batch int := GREATEST(1, LEAST(COALESCE(p_batch_size,10), 100));
  v_lease int := GREATEST(5, LEAST(COALESCE(p_lease_seconds,60), 900));
  v_worker text := NULLIF(trim(COALESCE(p_worker_id,'')), '');
  v_role text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims', true)::jsonb ->> 'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege';
  END IF;
  IF v_worker IS NULL OR length(v_worker) > 80 THEN
    RAISE EXCEPTION 'worker_id inválido';
  END IF;

  RETURN QUERY
  WITH candidatos AS (
    SELECT id FROM public.comunicacao_outbox
     WHERE ((status = 'pending' AND next_attempt_at <= now())
         OR (status = 'processing' AND lease_expires_at IS NOT NULL AND lease_expires_at < now()))
     ORDER BY next_attempt_at ASC
     LIMIT v_batch FOR UPDATE SKIP LOCKED
  ),
  updated AS (
    UPDATE public.comunicacao_outbox o
       SET status = 'processing', locked_at = now(), locked_by = v_worker,
           lease_expires_at = now() + make_interval(secs => v_lease),
           attempts = o.attempts + 1
      FROM candidatos c WHERE o.id = c.id RETURNING o.*
  )
  SELECT * FROM updated;
END$$;


ALTER FUNCTION public.rpc_claim_communication_outbox(p_batch_size integer, p_worker_id text, p_lease_seconds integer) OWNER TO postgres;

--
-- Name: rpc_cockpit_cancelar_reserva_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_cancelar_reserva_v1(p_item_id uuid, p_os_id uuid, p_origem text, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_item public.estoque_produto%ROWTYPE;
  v_main public.estoque_produto%ROWTYPE;
  v_modo text;
  v_motivo text := nullif(btrim(coalesce(p_motivo, '')), '');
BEGIN
  PERFORM public.fn_estoque_ctx_open(jsonb_build_object('acao','cancelamento_reserva','origem','rpc_cockpit_cancelar_reserva_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_item_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_PARAMS_INVALIDOS'; END IF;
  IF v_motivo IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_MOTIVO_OBRIGATORIO'; END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_reserva:' || p_item_id::text));

  SELECT * INTO v_item FROM public.estoque_produto WHERE id = p_item_id FOR UPDATE;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'COCKPIT_RESERVA_NAO_ENCONTRADA'; END IF;

  IF v_item.status::text = 'estornado' OR v_item.quantidade_reservada IS NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true,
      'message', 'Reserva já cancelada anteriormente.');
  END IF;
  IF v_item.status::text = 'expedido' THEN RAISE EXCEPTION 'COCKPIT_RESERVA_JA_EXPEDIDA'; END IF;

  -- coerência: a reserva precisa pertencer à MESMA OS/origem
  IF v_item.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_OS';
  END IF;
  IF coalesce(v_item.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_RESERVA_ORIGEM';
  END IF;

  -- override (cancelar reserva feita por outro operador) exige gestor
  IF v_item.reservado_por IS DISTINCT FROM v_uid AND NOT public.fn_cockpit_is_gestor() THEN
    RAISE EXCEPTION 'COCKPIT_RESERVA_OVERRIDE_SEM_ALCADA';
  END IF;

  -- saldo principal compatível (mesmo lote, envase, item e validade)
  SELECT * INTO v_main
    FROM public.estoque_produto
   WHERE lote_id = v_item.lote_id
     AND envase_id IS NOT DISTINCT FROM v_item.envase_id
     AND produto_id IS NOT DISTINCT FROM v_item.produto_id
     AND microrganismo_id IS NOT DISTINCT FROM v_item.microrganismo_id
     AND validade IS NOT DISTINCT FROM v_item.validade
     AND quantidade_reservada IS NULL
     AND status = 'disponivel'::public.status_estoque
     AND id <> v_item.id
   ORDER BY id LIMIT 1 FOR UPDATE;

  IF v_main.id IS NOT NULL THEN
    v_modo := 'estorno_para_saldo_principal';
    UPDATE public.estoque_produto
       SET quantidade = coalesce(v_main.quantidade,0) + coalesce(v_item.quantidade,0),
           volume_total = coalesce(v_main.volume_total,0) + coalesce(v_item.volume_total,0),
           updated_at = now()
     WHERE id = v_main.id;

    UPDATE public.estoque_produto
       SET status = 'estornado'::public.status_estoque, quantidade = 0, volume_total = 0,
           quantidade_reservada = 0, reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo || format(' — saldo devolvido ao registro %s', v_main.id),
           updated_at = now()
     WHERE id = v_item.id;

  ELSE
    v_modo := 'liberacao_no_proprio_registro';
    UPDATE public.estoque_produto
       SET status = 'disponivel'::public.status_estoque, quantidade_reservada = NULL,
           reservado_para_os_id = NULL, reservado_para_os_tipo = NULL,
           reservado_para_cliente_id = NULL, reservado_para_partner_id = NULL,
           reservado_para_partner_order_id = NULL,
           observacao_reserva = v_motivo, updated_at = now()
     WHERE id = v_item.id;

  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, v_item.lote_id, 'estoque_reservado', 'estoque_disponivel',
          'cancelar_reserva_v1', v_uid, format('Cancelamento transacional (%s). Motivo: %s', v_modo, v_motivo));

  RETURN jsonb_build_object('success', true, 'replay', false, 'modo', v_modo,
    'message', 'Reserva cancelada e saldo devolvido em transação única.');
END;
$$;


ALTER FUNCTION public.rpc_cockpit_cancelar_reserva_v1(p_item_id uuid, p_os_id uuid, p_origem text, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_cockpit_confirmar_entrega_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_confirmar_entrega_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS'; END IF;
  IF coalesce(btrim(p_recebedor->>'nome'), '') = '' THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_RECEBEDOR_OBRIGATORIO';
  END IF;
  RETURN public.fn_entrega_confirmar_engine_v1(p_entrega_id, p_os_id, p_origem, p_recebedor, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.rpc_cockpit_confirmar_entrega_v1(p_entrega_id uuid, p_os_id uuid, p_origem text, p_recebedor jsonb) OWNER TO postgres;

--
-- Name: rpc_cockpit_criar_entrega_v1(uuid, text, uuid, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_estoque_produto_id uuid, p_quantidade numeric, p_dados jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_est public.estoque_produto%ROWTYPE;
  v_existente record;
  v_id uuid;
  v_cliente_os uuid;
BEGIN
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_os_id IS NULL OR p_estoque_produto_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_PARAMS_INVALIDOS';
  END IF;
  IF coalesce(p_quantidade, 0) <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_INVALIDA';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('cockpit_criar_entrega:' || p_os_id::text || ':' || p_estoque_produto_id::text));

  SELECT * INTO v_est
  FROM public.estoque_produto
  WHERE id = p_estoque_produto_id
  FOR UPDATE;

  IF v_est.id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ESTOQUE_NAO_ENCONTRADO';
  END IF;

  IF v_origem = 'onfarm' THEN
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico_onfarm
    WHERE id = p_os_id;
  ELSE
    SELECT cliente_id INTO v_cliente_os
    FROM public.ordens_servico
    WHERE id = p_os_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_OS_NAO_ENCONTRADA';
  END IF;

  IF v_est.status::text NOT IN ('reservado', 'expedido') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_STATUS_ESTOQUE_INVALIDO';
  END IF;
  IF v_est.reservado_para_os_id IS DISTINCT FROM p_os_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ESTOQUE';
  END IF;
  IF coalesce(v_est.reservado_para_os_tipo, v_origem) IS DISTINCT FROM v_origem THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_ORIGEM';
  END IF;
  IF p_quantidade > coalesce(v_est.quantidade, 0) THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_QUANTIDADE_EXCEDE_RESERVA';
  END IF;
  IF v_est.reservado_para_cliente_id IS NOT NULL
     AND v_est.reservado_para_cliente_id IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;
  IF nullif(p_dados->>'cliente_id','') IS NOT NULL
     AND nullif(p_dados->>'cliente_id','')::uuid IS DISTINCT FROM v_cliente_os THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ENTREGA_CLIENTE';
  END IF;

  SELECT e.id, e.status::text AS status INTO v_existente
  FROM public.entregas e
  WHERE e.estoque_produto_id = p_estoque_produto_id
    AND e.status::text <> 'cancelada'
    AND (
      (v_origem = 'onfarm' AND e.ordem_servico_onfarm_id = p_os_id)
      OR (v_origem <> 'onfarm' AND e.ordem_servico_id = p_os_id)
    )
  ORDER BY e.created_at DESC
  LIMIT 1;

  IF v_existente.id IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'replay', true, 'entrega_id', v_existente.id, 'status', v_existente.status, 'message', 'Entrega ja registrada para este item da OS.');
  END IF;


  IF coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista') NOT IN ('motorista','retirada') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_MODALIDADE_INVALIDA';
  END IF;
  IF coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro') NOT IN ('cadastro','personalizado') THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_ENDERECO_ORIGEM_INVALIDA';
  END IF;
  IF v_est.volume_total IS NULL OR v_est.volume_total <= 0 OR v_est.volume_total::text IN ('NaN','Infinity','-Infinity')
     OR v_est.quantidade IS NULL OR v_est.quantidade <= 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENTREGA_VOLUME_ESTOQUE_INVALIDO';
  END IF;

  INSERT INTO public.entregas (
    ordem_servico_id, ordem_servico_onfarm_id, estoque_produto_id,
    lote_id, produto_id, quantidade_entregue, status, cliente_id,
    data_saida, motorista, veiculo
  ) VALUES (
    CASE WHEN v_origem = 'onfarm' THEN NULL ELSE p_os_id END,
    CASE WHEN v_origem = 'onfarm' THEN p_os_id ELSE NULL END,
    p_estoque_produto_id,
    v_est.lote_id,
    v_est.produto_id,
    p_quantidade,
    'separado'::public.status_entrega,
    v_cliente_os,
    nullif(p_dados->>'data_saida','')::date,
    nullif(p_dados->>'motorista',''),
    nullif(p_dados->>'veiculo','')
  ) RETURNING id INTO v_id;


  -- Only newly created delivery: preserve replay semantics and never overwrite existing history.
  UPDATE public.entregas SET
    volume_entregue_ml = round((v_est.volume_total / v_est.quantidade) * p_quantidade * 1000, 6),
    tipo_entrega = coalesce(nullif(p_dados->>'tipo_entrega',''), 'motorista'),
    endereco_origem = coalesce(nullif(p_dados->>'endereco_origem',''), 'cadastro'),
    grupo_entrega_id = nullif(p_dados->>'grupo_entrega_id','')::uuid,
    hora_saida_prevista = nullif(p_dados->>'hora_saida_prevista','')::time,
    data_chegada_prevista = nullif(p_dados->>'data_chegada_prevista','')::date,
    hora_chegada_prevista = nullif(p_dados->>'hora_chegada_prevista','')::time,
    motorista_telefone = nullif(p_dados->>'motorista_telefone',''),
    motorista_documento = nullif(p_dados->>'motorista_documento',''),
    veiculo_placa = nullif(p_dados->>'veiculo_placa',''),
    veiculo_tipo = nullif(p_dados->>'veiculo_tipo',''),
    destinatario_nome = nullif(p_dados->>'destinatario_nome',''),
    destinatario_telefone = nullif(p_dados->>'destinatario_telefone',''),
    destinatario_whatsapp = nullif(p_dados->>'destinatario_whatsapp',''),
    endereco_logradouro = nullif(p_dados->>'endereco_logradouro',''),
    endereco_numero = nullif(p_dados->>'endereco_numero',''),
    endereco_complemento = nullif(p_dados->>'endereco_complemento',''),
    endereco_bairro = nullif(p_dados->>'endereco_bairro',''),
    endereco_cidade = nullif(p_dados->>'endereco_cidade',''),
    endereco_uf = nullif(p_dados->>'endereco_uf',''),
    endereco_cep = nullif(p_dados->>'endereco_cep',''),
    endereco_referencia = nullif(p_dados->>'endereco_referencia','')
  WHERE id = v_id;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, etapa_nova, acao, usuario_id, observacao)
  VALUES
    (p_os_id, v_origem, 'entrega_criada', 'criar_entrega_v1', v_uid,
     format('Entrega %s criada (motor transacional).', v_id));

  RETURN jsonb_build_object('success', true, 'replay', false, 'entrega_id', v_id, 'status', 'separado', 'message', 'Entrega registrada. Confirme a entrega para concluir a OS.');
END;
$$;


ALTER FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_estoque_produto_id uuid, p_quantidade numeric, p_dados jsonb) OWNER TO postgres;

--
-- Name: rpc_cockpit_criar_entrega_v1(uuid, text, jsonb, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_request_key text, p_dados jsonb, p_os_observed timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $_$
DECLARE v_org uuid; v_actor uuid:=auth.uid(); v_os public.ordens_servico%ROWTYPE;
 v_item jsonb; v_id uuid; v_qty numeric; v_items jsonb:='[]'; v_fp text;
 v_prev platform_private.delivery_requests_20261030%ROWTYPE; v_batch jsonb; v_call jsonb;
 v_row public.estoque_produto%ROWTYPE; v_free jsonb:='[]'; v_fi integer:=0; v_dk text; v_dv text;
 v_result jsonb:='[]'; v_index integer:=0; v_ent uuid; v_reserved uuid; v_current timestamptz; v_original_client uuid;
BEGIN
 v_org:=platform_private.delivery_actor_20261030('group');
 IF p_origem IS DISTINCT FROM 'manual' OR p_os_id IS NULL THEN RAISE EXCEPTION 'DELIVERY_ORIGIN_CLOSED' USING ERRCODE='42501'; END IF;
 IF p_os_observed IS NULL THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_REQUIRED' USING ERRCODE='22023'; END IF;
 IF p_request_key IS NULL OR length(btrim(p_request_key))<8 OR length(p_request_key)>128 THEN RAISE EXCEPTION 'DELIVERY_REQUEST_INVALID' USING ERRCODE='22023'; END IF;
 IF p_dados IS NULL OR jsonb_typeof(p_dados)<>'object' OR EXISTS(SELECT 1 FROM jsonb_each(p_dados) WHERE key NOT IN ('data_saida','motorista','veiculo','tipo_entrega','endereco_origem',
   'motorista_telefone','motorista_documento','veiculo_placa','veiculo_tipo','hora_saida_prevista','data_chegada_prevista','hora_chegada_prevista',
   'destinatario_nome','destinatario_telefone','destinatario_whatsapp','endereco_logradouro','endereco_numero','endereco_complemento',
   'endereco_bairro','endereco_cidade','endereco_uf','endereco_cep','endereco_referencia') OR jsonb_typeof(value) NOT IN ('string','null')
   OR (jsonb_typeof(value)='string' AND length(value#>>'{}')>300)) THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END IF;
 FOR v_dk IN SELECT key FROM jsonb_each_text(p_dados) WHERE nullif(value,'') IS NOT NULL LOOP
  v_dv:=p_dados->>v_dk;
  IF v_dk IN ('data_saida','data_chegada_prevista') THEN
   IF v_dv !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END IF;
   BEGIN IF to_char(v_dv::date,'YYYY-MM-DD')<>v_dv THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END IF;
   EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END;
  ELSIF v_dk IN ('hora_saida_prevista','hora_chegada_prevista') THEN
   IF v_dv !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023'; END IF;
  ELSIF v_dk='tipo_entrega' AND v_dv NOT IN ('motorista','retirada') THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023';
  ELSIF v_dk='endereco_origem' AND v_dv NOT IN ('cadastro','personalizado') THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023';
  ELSIF btrim(v_dv)='' OR v_dv ~ '[[:cntrl:]]' THEN RAISE EXCEPTION 'DELIVERY_DATA_INVALID' USING ERRCODE='22023';
  END IF;
 END LOOP;
 IF p_itens IS NULL OR jsonb_typeof(p_itens)<>'array' THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_itens)=0 OR jsonb_array_length(p_itens)>100 THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO v_os FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org;
 IF NOT FOUND OR v_os.partner_order_id IS NOT NULL OR v_os.origem IS DISTINCT FROM 'agronomica' THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 v_original_client:=v_os.cliente_id;
 FOR v_item IN SELECT value FROM jsonb_array_elements(p_itens) LOOP
  IF jsonb_typeof(v_item)<>'object' OR NOT(v_item ? 'item_id' AND v_item ? 'quantidade' AND v_item ? 'observed_updated_at') OR v_item->>'observed_updated_at' IS NULL OR EXISTS(SELECT 1 FROM jsonb_each(v_item) WHERE key NOT IN ('item_id','quantidade','observed_updated_at')) THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
  v_id:=(v_item->>'item_id')::uuid; v_qty:=(v_item->>'quantidade')::numeric;
  IF v_id IS NULL OR v_qty IS NULL OR v_qty<=0 OR v_qty::text IN ('NaN','Infinity','-Infinity') OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) WHERE value->>'item_id'=v_id::text) THEN RAISE EXCEPTION 'DELIVERY_ITEMS_INVALID' USING ERRCODE='22023'; END IF;
  v_items:=v_items||jsonb_build_array(jsonb_build_object('item_id',v_id,'quantidade',v_qty,'observed_updated_at',(v_item->>'observed_updated_at')::timestamptz));
 END LOOP;
 SELECT jsonb_agg(value ORDER BY value->>'item_id') INTO v_items FROM jsonb_array_elements(v_items);
 v_fp:=md5(jsonb_build_object('actor',v_actor,'org',v_org,'os',p_os_id,'observed',p_os_observed,'origin','manual','items',v_items,'data',p_dados)::text);
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('delivery_request:'||jsonb_build_array(v_org,v_actor,'group',p_request_key)::text,0));
 IF platform_private.delivery_actor_20261030('group') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 -- Canonical global gate is acquired BEFORE every OS/stock row lock.
 PERFORM platform_private.delivery_gate_20261030(v_org,'group');
 SELECT * INTO v_os FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org FOR UPDATE;
 IF NOT FOUND OR v_os.partner_order_id IS NOT NULL OR v_os.origem IS DISTINCT FROM 'agronomica' THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT * INTO v_prev FROM platform_private.delivery_requests_20261030 WHERE request_key=p_request_key AND actor=v_actor AND organization_id=v_org AND action='group';
 IF FOUND THEN
  IF v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'DELIVERY_REPLAY_CONFLICT' USING ERRCODE='PT409'; END IF;
  -- Reference scope still binds the replay: client unchanged during the wait, still in tenant, and every receipt
  -- delivery belongs to this tenant/OS/client. Only the fresh-dispatch CAS/status/stock state is not required.
  IF v_os.cliente_id IS DISTINCT FROM v_original_client OR NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=v_os.cliente_id AND organization_id=v_org)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_prev.result->'itens') i LEFT JOIN public.entregas e ON e.id=(i.value->>'entrega_id')::uuid
   WHERE e.id IS NULL OR e.organization_id IS DISTINCT FROM v_org OR e.ordem_servico_id IS DISTINCT FROM p_os_id OR e.cliente_id IS DISTINCT FROM v_os.cliente_id)
  THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
  IF platform_private.delivery_actor_20261030('group') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF v_os.cliente_id IS DISTINCT FROM v_original_client OR v_os.updated_at IS DISTINCT FROM p_os_observed THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id AND organization_id=v_org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'DELIVERY_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  v_id:=(v_item->>'item_id')::uuid;
  SELECT * INTO v_row FROM public.estoque_produto WHERE id=v_id FOR UPDATE;
  IF v_row.status::text='reservado' THEN
   IF v_row.reservado_para_os_id IS DISTINCT FROM p_os_id OR v_row.reservado_para_os_tipo IS DISTINCT FROM 'manual'
    OR v_row.reservado_para_cliente_id IS DISTINCT FROM v_os.cliente_id OR v_row.reservado_para_partner_id IS NOT NULL
    OR v_row.reservado_para_partner_order_id IS NOT NULL OR v_row.quantidade_reservada IS DISTINCT FROM v_row.quantidade
    OR v_row.quantidade IS DISTINCT FROM (v_item->>'quantidade')::numeric THEN RAISE EXCEPTION 'DELIVERY_RESERVATION_NOT_OWNED' USING ERRCODE='PT409'; END IF;
   PERFORM platform_private.stock_motor_item(v_id,'expedicao',jsonb_build_object('os_id',p_os_id,'os_tipo','manual','cliente_id',v_os.cliente_id));
  ELSIF v_row.status::text='disponivel' THEN
   PERFORM platform_private.stock_motor_item(v_id,'reserva',jsonb_build_object('os_id',p_os_id,'os_tipo','manual','cliente_id',v_os.cliente_id));
   v_free:=v_free||jsonb_build_array(v_item-'observed_updated_at');
  ELSE RAISE EXCEPTION 'DELIVERY_STOCK_UNAVAILABLE' USING ERRCODE='PT409'; END IF;
  IF platform_private.delivery_actor_20261030('group') IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'DELIVERY_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
 END LOOP;
 PERFORM platform_private.delivery_gate_20261030(v_org,'group');
 SELECT * INTO v_prev FROM platform_private.delivery_requests_20261030 WHERE request_key=p_request_key AND actor=v_actor AND organization_id=v_org AND action='group';
 IF FOUND THEN
  IF v_prev.actor IS DISTINCT FROM v_actor OR v_prev.organization_id IS DISTINCT FROM v_org OR v_prev.action IS DISTINCT FROM 'group' OR v_prev.fingerprint IS DISTINCT FROM v_fp THEN RAISE EXCEPTION 'DELIVERY_REPLAY_CONFLICT' USING ERRCODE='PT409'; END IF;
  RETURN v_prev.result||jsonb_build_object('replay',true);
 END IF;
 IF v_os.updated_at IS DISTINCT FROM p_os_observed OR v_os.status::text<>'pronto_entrega' THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  SELECT updated_at INTO v_current FROM public.estoque_produto WHERE id=(v_item->>'item_id')::uuid;
  IF v_current IS DISTINCT FROM (v_item->>'observed_updated_at')::timestamptz THEN RAISE EXCEPTION 'DELIVERY_OBSERVED_CONFLICT' USING ERRCODE='PT409'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id AND status::text<>'cancelada' AND estoque_produto_id IN (SELECT (value->>'item_id')::uuid FROM jsonb_array_elements(v_items))) THEN RAISE EXCEPTION 'DELIVERY_EXISTING_UNOWNED' USING ERRCODE='PT409'; END IF;
 INSERT INTO platform_private.delivery_context_20261030(txid,actor,organization_id,action,target) VALUES(pg_catalog.txid_current(),v_actor,v_org,'group',p_os_id);
 IF jsonb_array_length(v_free)>0 THEN
 v_batch:=public.rpc_estoque_reservar_v1(p_os_id,'manual',v_free,'delivery-reserve:'||md5(jsonb_build_array(v_actor,v_org,p_request_key)::text),jsonb_build_object('cliente_id',v_os.cliente_id));
 IF v_batch->>'ok' IS DISTINCT FROM 'true' OR v_batch->>'replay' IS DISTINCT FROM 'false' OR jsonb_array_length(v_batch->'itens')<>jsonb_array_length(v_free) THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.stock_batch_requests WHERE request_key='delivery-reserve:'||md5(jsonb_build_array(v_actor,v_org,p_request_key)::text) AND result=v_batch) THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
 END IF;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_items) LOOP
  IF v_free @> jsonb_build_array(jsonb_build_object('item_id',v_item->'item_id')) THEN
   v_reserved:=(v_batch->'itens'->>v_fi)::uuid; v_fi:=v_fi+1;
  ELSE v_reserved:=(v_item->>'item_id')::uuid; END IF;
  v_qty:=(v_item->>'quantidade')::numeric;
  IF v_reserved IS NULL THEN RAISE EXCEPTION 'DELIVERY_RESERVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  PERFORM platform_private.delivery_gate_20261030(v_org,'group');
  UPDATE platform_private.delivery_context_20261030 SET item=v_reserved,delivery=NULL,mutation='create' WHERE txid=pg_catalog.txid_current();
  v_call:=public.rpc_cockpit_criar_entrega_v1(p_os_id,'manual',v_reserved,v_qty,p_dados||jsonb_build_object('cliente_id',v_os.cliente_id));
  IF v_call->>'success' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'DELIVERY_CREATE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  v_ent:=(v_call->>'entrega_id')::uuid;
  IF v_ent IS NULL OR NOT EXISTS(SELECT 1 FROM public.entregas WHERE id=v_ent AND organization_id=v_org AND ordem_servico_id=p_os_id AND estoque_produto_id=v_reserved AND quantidade_entregue=v_qty AND receivable_id IS NULL AND partner_order_id IS NULL) THEN RAISE EXCEPTION 'DELIVERY_CREATE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  v_call:=public.rpc_estoque_operar_v1('expedicao',v_reserved,v_qty,'delivery-exp:'||md5(jsonb_build_array(v_actor,v_org,p_request_key,v_index)::text),jsonb_build_object('referencia_tipo','entrega','referencia_id',v_ent,'os_id',p_os_id,'os_tipo','manual','cliente_id',v_os.cliente_id));
  IF v_call->>'ok' IS DISTINCT FROM 'true' OR v_call->>'replay' IS DISTINCT FROM 'false' OR NOT EXISTS(SELECT 1 FROM public.estoque_movimentacoes WHERE id=(v_call->>'movimentacao_id')::uuid AND estoque_produto_id=v_reserved AND referencia_id=v_ent AND referencia_tipo='entrega' AND acao='expedicao' AND usuario_id=v_actor) THEN RAISE EXCEPTION 'DELIVERY_MOVE_ACK_INVALID' USING ERRCODE='PT409'; END IF;
  PERFORM platform_private.delivery_gate_20261030(v_org,'group');
  v_result:=v_result||jsonb_build_array(jsonb_build_object('entrega_id',v_ent,'estoque_produto_id',v_reserved,'movimentacao_id',v_call->>'movimentacao_id'));
  v_index:=v_index+1;
 END LOOP;
 v_call:=jsonb_build_object('success',true,'replay',false,'organization_id',v_org,'os_id',p_os_id,'itens',v_result);
 INSERT INTO platform_private.delivery_requests_20261030(request_key,actor,organization_id,action,fingerprint,result) VALUES(p_request_key,v_actor,v_org,'group',v_fp,v_call);
 DELETE FROM platform_private.delivery_context_20261030 WHERE txid=pg_catalog.txid_current();
 RETURN v_call;
END $_$;


ALTER FUNCTION public.rpc_cockpit_criar_entrega_v1(p_os_id uuid, p_origem text, p_itens jsonb, p_request_key text, p_dados jsonb, p_os_observed timestamp with time zone) OWNER TO postgres;

--
-- Name: rpc_cockpit_gerar_lote_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_gerar_lote_v1(p_programacao_id uuid, p_os_id uuid, p_origem text, p_lote jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
 v_uid uuid:=auth.uid(); v_org uuid; v_origin text; v_os record;
 v_pp public.programacao_producao%ROWTYPE; v_lot public.lotes%ROWTYPE;
 v_key text; v_count integer; v_id uuid; v_codigo text; v_volume numeric;
 v_tanque text; v_resp text; v_obs text; v_try integer:=0; v_constraint text;
BEGIN
 PERFORM pg_catalog.set_config('lock_timeout','3s',true);
 -- Cadeia viva (Auth/JWT iat, perfil ativo, empresa ativa, readiness, SaaS, papel) ANTES de qualquer leitura.
 -- Não reutiliza fn_cockpit_assert_operador_origem: ele só testa papel global.
 v_org:=platform_private.h15_actor_organization();
 IF v_uid IS NULL OR v_org IS NULL OR public.technical_actor_ready(v_uid) IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE
 OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 BEGIN v_origin:=public.fn_cockpit_norm_origem(p_origem); EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END;
 IF v_origin<>'manual' THEN RETURN jsonb_build_object('success',false,'message','Somente OS manual neste recorte.'); END IF;
 IF p_programacao_id IS NULL OR p_os_id IS NULL THEN RAISE EXCEPTION 'COCKPIT_LOTE_PARAMS_INVALIDOS'; END IF;
 IF p_lote IS NULL OR jsonb_typeof(p_lote)<>'object' THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 -- Lista fechada: código, produto, microrganismo, tenant, custo e data nunca vêm do navegador.
 FOR v_key IN SELECT pg_catalog.jsonb_object_keys(p_lote) LOOP
  IF v_key='codigo_lote' THEN RAISE EXCEPTION 'COCKPIT_LOTE_CODIGO_NAO_ACEITO'; END IF;
  IF v_key NOT IN ('volume_produzido','responsavel_producao','tanque','observacoes_tecnicas') THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 END LOOP;
 -- Volume em mL (mesma unidade de programacao_producao.volume_necessario e ordens_servico.volume_total_ml).
 IF pg_catalog.jsonb_typeof(p_lote->'volume_produzido') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'COCKPIT_LOTE_VOLUME_INVALIDO'; END IF;
 v_volume:=(p_lote->>'volume_produzido')::numeric;
 IF NOT (v_volume>0 AND v_volume<=100000000 AND v_volume=pg_catalog.round(v_volume,3) AND v_volume::text NOT IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'COCKPIT_LOTE_VOLUME_INVALIDO'; END IF;
 FOREACH v_key IN ARRAY ARRAY['responsavel_producao','tanque','observacoes_tecnicas'] LOOP
  IF pg_catalog.jsonb_typeof(p_lote->v_key) NOT IN ('string','null') THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 END LOOP;
 v_resp:=nullif(pg_catalog.btrim(p_lote->>'responsavel_producao'),'');
 v_tanque:=nullif(pg_catalog.btrim(p_lote->>'tanque'),'');
 v_obs:=nullif(pg_catalog.btrim(p_lote->>'observacoes_tecnicas'),'');
 IF pg_catalog.length(v_resp)>200 OR pg_catalog.length(v_tanque)>60 OR pg_catalog.length(v_obs)>2000 THEN RAISE EXCEPTION 'COCKPIT_LOTE_PAYLOAD_INVALIDO'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os='manual') THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'COCKPIT_LOTE_ISOLATION_DENIED' USING ERRCODE='42501'; END IF;
 -- Mesmo conjunto de cercas revisado em rpc_programar_os_v1 (convites/onfarm/catálogo SaaS global).
 LOCK TABLE public.platform_org_admin_invites,public.ordens_servico_onfarm IN SHARE MODE;
 LOCK TABLE public.saas_plan_versions,public.saas_plan_version_features,public.saas_features,public.saas_modules IN SHARE MODE;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('cockpit_lote:'||p_programacao_id::text));
 SELECT o.organization_id,o.id,o.cliente_id,o.fazenda_id,o.talhao_id,o.produto_id,o.microrganismo_id,o.status::text status,o.partner_order_id,o.partner_order_item_id,o.origem
 INTO v_os FROM public.ordens_servico o WHERE o.id=p_os_id FOR UPDATE;
 IF v_os.id IS NULL OR v_os.organization_id IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=v_uid ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=v_uid ORDER BY role::text FOR SHARE;
 PERFORM 1 FROM public.organizations WHERE id=v_org FOR UPDATE;
 PERFORM 1 FROM public.organization_subscriptions WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.organization_feature_overrides WHERE organization_id=v_org ORDER BY id FOR SHARE;
 PERFORM 1 FROM public.clientes WHERE id=v_os.cliente_id FOR SHARE;
 PERFORM 1 FROM public.fazendas WHERE id=v_os.fazenda_id FOR SHARE;
 PERFORM 1 FROM public.talhoes WHERE id=v_os.talhao_id FOR SHARE;
 PERFORM 1 FROM public.produtos WHERE id=v_os.produto_id FOR SHARE;
 PERFORM 1 FROM public.microrganismos WHERE id=v_os.microrganismo_id FOR SHARE;
 PERFORM 1 FROM public.programacao_producao WHERE id=p_programacao_id OR ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.lotes WHERE programacao_id=p_programacao_id ORDER BY id FOR UPDATE;
 -- Revalidação após locks: revogação/troca de tenant/assinatura concorrente vence a requisição.
 IF public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE
 OR NOT EXISTS(SELECT 1 FROM private.h7n_esteira_laboratorio() s WHERE s.os_id=p_os_id AND s.origem_os='manual') THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=v_os.cliente_id AND c.organization_id=v_org)
 OR EXISTS(SELECT 1 FROM public.ordens_servico_onfarm WHERE id=p_os_id) THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF v_os.origem='b2b' OR v_os.partner_order_id IS NOT NULL OR v_os.partner_order_item_id IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','Lote B2B indisponível até validação dos efeitos associados.'); END IF;
 SELECT count(*) INTO v_count FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id;
 IF v_count<>1 THEN RETURN jsonb_build_object('success',false,'message','Programação existente não comprovada; revisão necessária.'); END IF;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=p_programacao_id;
 -- IDs divergentes, programação de outra OS ou de outro tenant: mesma negação, sem revelar existência.
 IF NOT ((v_pp.id IS NOT NULL AND v_pp.organization_id=v_org AND v_pp.ordem_servico_id=p_os_id AND v_pp.ordem_servico_onfarm_id IS NULL
 AND v_pp.produto_id IS NOT DISTINCT FROM v_os.produto_id AND v_pp.microrganismo_id IS NOT DISTINCT FROM v_os.microrganismo_id) IS TRUE) THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF ((v_pp.produto_id IS NOT NULL)::int+(v_pp.microrganismo_id IS NOT NULL)::int)<>1 THEN RAISE EXCEPTION 'COCKPIT_LOTE_ITEM_CANONICO_AUSENTE'; END IF;
 IF platform_private.lab_item_is_manufacturable(v_pp.produto_id,v_pp.microrganismo_id) IS NOT TRUE THEN
 RETURN jsonb_build_object('success',false,'message','Item não elegível ao laboratório biológico.'); END IF;
 IF v_pp.responsavel_id IS NOT NULL OR nullif(pg_catalog.btrim(v_pp.responsavel),'') IS NOT NULL THEN
 RETURN jsonb_build_object('success',false,'message','Responsável não nulo indisponível neste recorte.'); END IF;
 IF EXISTS(SELECT 1 FROM public.entregas WHERE ordem_servico_id=p_os_id) OR EXISTS(SELECT 1 FROM public.aplicacoes WHERE ordem_servico_id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','OS com entrega/aplicação já vinculada indisponível neste recorte.'); END IF;
 SELECT count(*) INTO v_count FROM public.lotes WHERE programacao_id=p_programacao_id;
 IF v_count>1 THEN RETURN jsonb_build_object('success',false,'message','Mais de um lote para a programação; revisão necessária.'); END IF;
 IF v_count=1 THEN
  SELECT * INTO v_lot FROM public.lotes WHERE programacao_id=p_programacao_id;
  -- Replay só é aceito quando o pedido e o lote/evento existentes coincidem; nenhum dado é alterado.
  IF v_os.status='programada' AND v_pp.status::text='aguardando' AND v_lot.organization_id=v_org AND v_lot.status::text='em_producao'
  AND v_lot.produto_id IS NOT DISTINCT FROM v_pp.produto_id AND v_lot.microrganismo_id IS NOT DISTINCT FROM v_pp.microrganismo_id
  AND v_lot.volume_produzido=v_volume AND v_lot.tanque IS NOT DISTINCT FROM v_tanque AND v_lot.responsavel_producao IS NOT DISTINCT FROM v_resp
  AND v_lot.observacoes_tecnicas IS NOT DISTINCT FROM v_obs AND NOT EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=v_lot.id)
  AND NOT EXISTS(SELECT 1 FROM public.envase WHERE lote_id=v_lot.id)
  AND NOT EXISTS(SELECT 1 FROM public.estoque_produto WHERE lote_id=v_lot.id)
  AND (SELECT count(*) FROM public.laboratorio_esteira_eventos WHERE lote_id=v_lot.id)=1
  AND EXISTS(SELECT 1 FROM public.laboratorio_esteira_eventos WHERE lote_id=v_lot.id AND acao='gerar_lote'
    AND os_id=p_os_id AND origem_os='manual' AND programacao_id=p_programacao_id AND usuario_id=v_uid AND etapa_nova='lote_gerado') THEN
   RETURN jsonb_build_object('success',true,'replay',true,'lote_id',v_lot.id,'codigo_lote',v_lot.codigo_lote,'message',pg_catalog.format('Lote %s já registrado com os mesmos dados.',v_lot.codigo_lote));
  END IF;
  RETURN jsonb_build_object('success',false,'message','Já existe lote com dados diferentes para esta programação; nada foi alterado.');
 END IF;
 -- Primeira geração: OS programada e programação aguardando; esta ação não avança OS/programação nem cria CQ/envase.
 IF v_os.status IS DISTINCT FROM 'programada' OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.data_programada IS NULL
 OR v_pp.volume_necessario IS NULL OR v_pp.volume_necessario<=0 OR v_pp.volume_necessario::text IN ('NaN','Infinity','-Infinity')
 OR v_pp.volume_necessario IS DISTINCT FROM (SELECT volume_total_ml FROM public.ordens_servico WHERE id=p_os_id) THEN
 RETURN jsonb_build_object('success',false,'message','A OS deve estar programada e a programação aguardando; esta ação não programa nem avança etapas.'); END IF;
 LOOP
  v_try:=v_try+1; v_id:=pg_catalog.gen_random_uuid(); v_codigo:=public.gerar_codigo_lote(EXTRACT(YEAR FROM now())::int);
  BEGIN
   INSERT INTO platform_private.authz_tickets(txid,scope,target) VALUES(pg_catalog.txid_current(),'manual_lot_insert_v1',v_id);
   INSERT INTO public.lotes(id,programacao_id,codigo_lote,produto_id,microrganismo_id,volume_produzido,data_producao,responsavel_producao,tanque,observacoes_tecnicas,organization_id)
   VALUES(v_id,p_programacao_id,v_codigo,v_pp.produto_id,v_pp.microrganismo_id,v_volume,CURRENT_DATE,v_resp,v_tanque,v_obs,v_org) RETURNING id INTO v_id;
   DELETE FROM platform_private.authz_tickets WHERE txid=pg_catalog.txid_current() AND scope='manual_lot_insert_v1' AND target=v_id;
   EXIT;
  EXCEPTION WHEN unique_violation THEN
   GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
   -- Concorrente fora deste RPC: falha fechada, sem replay presumido.
   IF v_constraint IS DISTINCT FROM 'lotes_codigo_lote_key' THEN RAISE EXCEPTION 'COCKPIT_LOTE_CONCORRENTE' USING ERRCODE='PT409'; END IF;
   IF v_try>=3 THEN RAISE EXCEPTION 'COCKPIT_LOTE_CODIGO_CONFLITO'; END IF;
  END;
 END LOOP;
 SELECT * INTO v_lot FROM public.lotes WHERE id=v_id;
 SELECT * INTO v_pp FROM public.programacao_producao WHERE id=p_programacao_id;
 IF (SELECT count(*) FROM public.lotes WHERE programacao_id=p_programacao_id)<>1 OR v_lot.organization_id IS DISTINCT FROM v_org
 OR v_lot.volume_produzido IS DISTINCT FROM v_volume OR v_lot.status::text IS DISTINCT FROM 'em_producao'
 OR v_pp.status::text IS DISTINCT FROM 'aguardando' OR v_pp.organization_id IS DISTINCT FROM v_org
 OR (SELECT status::text FROM public.ordens_servico WHERE id=p_os_id) IS DISTINCT FROM 'programada'
 OR EXISTS(SELECT 1 FROM public.controle_qualidade WHERE lote_id=v_id)
 OR public.technical_actor_ready(v_uid) IS NOT TRUE OR platform_private.h15_actor_organization() IS DISTINCT FROM v_org
 OR public._saas_user_has_feature(v_uid,'ordens_producao') IS NOT TRUE OR public._saas_user_has_feature(v_uid,'lotes_qualidade') IS NOT TRUE
 OR (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor') OR public.has_role(v_uid,'producao')) IS NOT TRUE THEN
 RAISE EXCEPTION 'COCKPIT_LOTE_POSTCONDITION_FAILED'; END IF;
 INSERT INTO public.laboratorio_esteira_eventos(os_id,origem_os,programacao_id,lote_id,etapa_nova,acao,usuario_id,observacao)
 VALUES(p_os_id,'manual',p_programacao_id,v_id,'lote_gerado','gerar_lote',v_uid,pg_catalog.format('Lote %s gerado (codigo canonico do servidor).',v_codigo));
 RETURN jsonb_build_object('success',true,'replay',false,'lote_id',v_id,'codigo_lote',v_codigo,'message',pg_catalog.format('Lote %s gerado com sucesso.',v_codigo));
END $$;


ALTER FUNCTION public.rpc_cockpit_gerar_lote_v1(p_programacao_id uuid, p_os_id uuid, p_origem text, p_lote jsonb) OWNER TO postgres;

--
-- Name: rpc_cockpit_listar_esteira_v1(text, text[], text[], text[], boolean, date, date, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_listar_esteira_v1(p_busca text DEFAULT NULL::text, p_stages text[] DEFAULT NULL::text[], p_origens text[] DEFAULT NULL::text[], p_prioridades text[] DEFAULT NULL::text[], p_atrasado boolean DEFAULT NULL::boolean, p_de date DEFAULT NULL::date, p_ate date DEFAULT NULL::date, p_incluir_finalizadas boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 WITH base AS (
 SELECT v.os_id,v.origem_os,v.numero_os,v.cliente_id,v.cliente_nome,v.fazenda_id,v.fazenda_nome,v.talhao_id,v.talhao_nome,
 v.produto_id,v.produto_nome,v.microrganismo_id,v.microrganismo_nome,v.partner_id,v.partner_numero,v.partner_nome,v.titular_nome,v.titular_tipo,
 v.prioridade,v.volume_solicitado_l,v.status_os,CASE WHEN v.status_os IN ('aberta','aprovada') THEN v.status_os ELSE v.status_esteira_oficial END status_esteira_oficial,public.fn_cockpit_stage(CASE WHEN v.status_os IN ('aberta','aprovada') THEN v.status_os ELSE v.status_esteira_oficial END) stage,
 v.programacao_id,v.data_programada,v.lote_id,v.codigo_lote,v.status_lote,v.cq_resultado,v.envase_id,v.estoque_id,v.estoque_reservado_id,
 v.entrega_id,v.entrega_status,v.atrasado,v.bloqueios,v.pode_finalizar,v.proxima_acao,v.created_at,
 pp.responsavel_id,pr.nome responsavel_nome
 FROM public.vw_esteira_laboratorio v
 LEFT JOIN public.programacao_producao pp ON pp.id=v.programacao_id AND pp.organization_id=platform_private.h15_actor_organization()
 LEFT JOIN public.profiles pr ON pr.user_id=pp.responsavel_id AND pr.organization_id=pp.organization_id AND pr.ativo IS TRUE
 WHERE (p_incluir_finalizadas IS TRUE OR v.status_os<>'finalizada')
 AND (p_origens IS NULL OR v.origem_os=ANY(p_origens))
 AND (p_prioridades IS NULL OR v.prioridade::text=ANY(p_prioridades))
 AND (p_atrasado IS NULL OR v.atrasado=p_atrasado)
 AND (p_de IS NULL OR v.created_at::date>=p_de) AND (p_ate IS NULL OR v.created_at::date<=p_ate)
 AND (p_stages IS NULL OR public.fn_cockpit_stage(CASE WHEN v.status_os IN ('aberta','aprovada') THEN v.status_os ELSE v.status_esteira_oficial END)=ANY(p_stages))
 AND (nullif(btrim(coalesce(p_busca,'')),'') IS NULL OR concat_ws(' ',v.numero_os,v.codigo_lote,v.cliente_nome,v.partner_nome,v.titular_nome,v.fazenda_nome,v.talhao_nome,v.produto_nome,v.microrganismo_nome,pr.nome) ILIKE '%'||btrim(p_busca)||'%')
 ) SELECT jsonb_build_object('total_count',(SELECT count(*) FROM base),'limit',greatest(1,least(coalesce(p_limit,50),200)),
 'offset',greatest(0,coalesce(p_offset,0)), 'items',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY t.atrasado DESC NULLS LAST,t.created_at DESC,t.origem_os,t.os_id)
 FROM (SELECT * FROM base ORDER BY atrasado DESC NULLS LAST,created_at DESC,origem_os,os_id
 LIMIT greatest(1,least(coalesce(p_limit,50),200)) OFFSET greatest(0,coalesce(p_offset,0))) t),'[]'::jsonb));
$$;


ALTER FUNCTION public.rpc_cockpit_listar_esteira_v1(p_busca text, p_stages text[], p_origens text[], p_prioridades text[], p_atrasado boolean, p_de date, p_ate date, p_incluir_finalizadas boolean, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: rpc_cockpit_metricas_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_metricas_v1() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT v.*, public.fn_cockpit_stage(v.status_esteira_oficial) AS stage
      FROM public.vw_esteira_laboratorio v
     WHERE v.status_os <> 'finalizada'
  ),
  sem_prog AS (
    SELECT count(*) AS n
      FROM public.ordens_servico os
     WHERE os.status::text = 'aberta'
       AND NOT EXISTS (
         SELECT 1 FROM public.programacao_producao pp
          WHERE pp.ordem_servico_id = os.id
       )
  ),
  sem_prog_onfarm AS (
    SELECT count(*) AS n
      FROM public.ordens_servico_onfarm os
     WHERE os.status::text = 'aberta'
       AND NOT EXISTS (
         SELECT 1 FROM public.programacao_producao pp
          WHERE pp.ordem_servico_onfarm_id = os.id
       )
  )
  SELECT jsonb_build_object(
    'total',              (SELECT count(*) FROM base),
    'demandas',           (SELECT count(*) FROM base WHERE stage IN ('aguardando','programada')),
    'producao',           (SELECT count(*) FROM base WHERE stage = 'em_producao'),
    'vol_producao',       (SELECT coalesce(sum(volume_solicitado_l),0) FROM base WHERE stage = 'em_producao'),
    'aguardando_cq',      (SELECT count(*) FROM base WHERE stage = 'aguardando_cq'),
    'vol_cq',             (SELECT coalesce(sum(volume_solicitado_l),0) FROM base WHERE stage = 'aguardando_cq'),
    'aprovados',          (SELECT count(*) FROM base WHERE status_lote::text = 'aprovado'),
    'reprovados',         (SELECT count(*) FROM base WHERE status_lote::text = 'reprovado'),
    'envase_pendente',    (SELECT count(*) FROM base WHERE stage = 'cq_aprovado'),
    'em_envase',          (SELECT count(*) FROM base WHERE stage = 'em_envase'),
    'estoque_disponivel', (SELECT count(*) FROM base WHERE stage = 'estoque_disponivel'),
    'estoque_reservado',  (SELECT count(*) FROM base WHERE stage = 'estoque_reservado'),
    'em_entrega',         (SELECT count(*) FROM base WHERE stage = 'em_entrega'),
    'entregues',          (SELECT count(*) FROM base WHERE stage = 'entregue'),
    'atrasadas',          (SELECT count(*) FROM base WHERE atrasado),
    'bloqueadas',         (SELECT count(*) FROM base WHERE coalesce(array_length(bloqueios,1),0) > 0),
    'os_sem_programacao', (SELECT n FROM sem_prog) + (SELECT n FROM sem_prog_onfarm)
  )
$$;


ALTER FUNCTION public.rpc_cockpit_metricas_v1() OWNER TO postgres;

--
-- Name: rpc_cockpit_metricas_v2(text, text[], text[], text[], boolean, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_metricas_v2(p_busca text DEFAULT NULL::text, p_stages text[] DEFAULT NULL::text[], p_origens text[] DEFAULT NULL::text[], p_prioridades text[] DEFAULT NULL::text[], p_atrasado boolean DEFAULT NULL::boolean, p_de date DEFAULT NULL::date, p_ate date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH base AS (
    SELECT v.*, public.fn_cockpit_stage(v.status_esteira_oficial) AS stage
      FROM public.vw_esteira_laboratorio v
      LEFT JOIN public.programacao_producao pp ON pp.id = v.programacao_id
      LEFT JOIN public.profiles pr ON pr.user_id = pp.responsavel_id
     WHERE v.status_os <> 'finalizada'
       AND (p_origens IS NULL OR v.origem_os = ANY (p_origens))
       AND (p_prioridades IS NULL OR v.prioridade::text = ANY (p_prioridades))
       AND (p_atrasado IS NULL OR v.atrasado = p_atrasado)
       AND (p_de IS NULL OR v.created_at::date >= p_de)
       AND (p_ate IS NULL OR v.created_at::date <= p_ate)
       AND (p_stages IS NULL OR public.fn_cockpit_stage(v.status_esteira_oficial) = ANY (p_stages))
       AND (
         nullif(btrim(coalesce(p_busca, '')), '') IS NULL
         OR concat_ws(' ', v.numero_os, v.codigo_lote, v.cliente_nome, v.partner_nome,
                      v.titular_nome, v.fazenda_nome, v.talhao_nome, v.produto_nome,
                      v.microrganismo_nome, pp.responsavel, pr.nome)
            ILIKE '%' || btrim(p_busca) || '%'
       )
  )
  SELECT jsonb_build_object(
    'escopo_filtrado',    true,
    'total',              (SELECT count(*) FROM base),
    'demandas',           (SELECT count(*) FROM base WHERE stage IN ('aguardando','programada')),
    'producao',           (SELECT count(*) FROM base WHERE stage = 'em_producao'),
    'vol_producao',       (SELECT coalesce(sum(volume_solicitado_l),0) FROM base WHERE stage = 'em_producao'),
    'aguardando_cq',      (SELECT count(*) FROM base WHERE stage = 'aguardando_cq'),
    'vol_cq',             (SELECT coalesce(sum(volume_solicitado_l),0) FROM base WHERE stage = 'aguardando_cq'),
    'aprovados',          (SELECT count(*) FROM base WHERE status_lote::text = 'aprovado'),
    'reprovados',         (SELECT count(*) FROM base WHERE status_lote::text = 'reprovado'),
    'envase_pendente',    (SELECT count(*) FROM base WHERE stage = 'cq_aprovado'),
    'em_envase',          (SELECT count(*) FROM base WHERE stage = 'em_envase'),
    'estoque_disponivel', (SELECT count(*) FROM base WHERE stage = 'estoque_disponivel'),
    'estoque_reservado',  (SELECT count(*) FROM base WHERE stage = 'estoque_reservado'),
    'em_entrega',         (SELECT count(*) FROM base WHERE stage = 'em_entrega'),
    'entregues',          (SELECT count(*) FROM base WHERE stage = 'entregue'),
    'atrasadas',          (SELECT count(*) FROM base WHERE atrasado),
    'bloqueadas',         (SELECT count(*) FROM base WHERE coalesce(array_length(bloqueios,1),0) > 0)
  )
$$;


ALTER FUNCTION public.rpc_cockpit_metricas_v2(p_busca text, p_stages text[], p_origens text[], p_prioridades text[], p_atrasado boolean, p_de date, p_ate date) OWNER TO postgres;

--
-- Name: rpc_cockpit_registrar_envase_v1(uuid, uuid, text, uuid, jsonb, date, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_cockpit_registrar_envase_v1(p_lote_id uuid, p_os_id uuid, p_origem text, p_programacao_id uuid, p_linhas jsonb, p_validade date, p_operador text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_permitir_parcial boolean DEFAULT false, p_motivo_parcial text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    SET lock_timeout TO '3s'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_origem text;
  v_ctx record;
  v_scope text;
  v_hash text; v_full_hash text; v_org uuid;
  v_row record;
  v_produzido_ml numeric := 0; v_envasado_ml numeric := 0; v_saldo_ml numeric := 0;
  v_total_ml numeric := 0; v_demanda_ml numeric := 0; v_reservado_ml numeric := 0;
  v_pendente_ml numeric := 0;
  v_linha jsonb; v_tipo text; v_qtd integer; v_unit_ml numeric;
  v_reservadas integer; v_livres integer;
  v_envase_id uuid; v_estoque_id uuid;
  v_produto_id uuid; v_micro_id uuid; v_cq_ok boolean; v_lote_status text;
  v_lote_prog uuid;
  v_env_ct int := 0; v_est_ct int := 0; v_res_ml numeric := 0; v_liv_ml numeric := 0;
  v_avanco jsonb; v_result jsonb; v_estado text;
BEGIN
  IF current_setting('transaction_isolation') <> 'read committed' THEN RAISE EXCEPTION 'ENVASE_ISOLATION_UNSUPPORTED' USING ERRCODE='0A000'; END IF;
  PERFORM platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'STOCK_GATE_UNAVAILABLE' USING ERRCODE='PT503'; END IF;
  PERFORM platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);
  PERFORM public.fn_estoque_ctx_force(jsonb_build_object('acao','entrada','origem','rpc_cockpit_registrar_envase_v1','usuario_id',auth.uid()::text));
  v_origem := public.fn_cockpit_assert_operador_origem(p_origem);

  IF p_lote_id IS NULL OR p_os_id IS NULL OR p_programacao_id IS NULL THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_PARAMS_INVALIDOS';
  END IF;
  IF p_validade IS NULL THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_OBRIGATORIA'; END IF;

  IF p_linhas IS NULL OR jsonb_typeof(p_linhas) <> 'array' OR jsonb_array_length(p_linhas) = 0 THEN
    RAISE EXCEPTION 'COCKPIT_ENVASE_SEM_LINHAS';
  END IF;

  IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) < 8 OR length(p_idempotency_key)>200 THEN RAISE EXCEPTION 'ENVASE_KEY_REQUIRED' USING ERRCODE='22023'; END IF;
  -- idempotência: LOCK primeiro, leitura definitiva depois (claim atômico)
  IF nullif(btrim(coalesce(p_idempotency_key, '')), '') IS NOT NULL THEN
    v_scope := 'registrar_envase_v1:' || v_uid::text || ':' || btrim(p_idempotency_key);
    v_hash  := encode(extensions.digest(jsonb_build_object(
                 'lote', p_lote_id, 'os', p_os_id, 'origem', v_origem,
                 'prog', p_programacao_id, 'linhas', p_linhas,
                 'validade', p_validade, 'parcial', p_permitir_parcial)::text, 'sha256'), 'hex');
    v_full_hash:=encode(extensions.digest(jsonb_build_object('args',jsonb_build_array(p_lote_id,p_os_id,v_origem,p_programacao_id,p_linhas,p_validade,p_operador,p_permitir_parcial,p_motivo_parcial),'actor',v_uid,'org',platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem))::text,'sha256'),'hex');
    PERFORM pg_advisory_xact_lock(hashtext(v_scope));
  PERFORM platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);

    SELECT * INTO v_row FROM public.cockpit_operacao_idempotencia
     WHERE idempotency_key = v_scope FOR UPDATE;
  PERFORM platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);

    IF v_row.idempotency_key IS NOT NULL THEN
      IF coalesce(v_row.payload_hash, '') <> v_hash THEN
        RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_CONFLICT';
      END IF;
      IF v_row.resultado IS NOT NULL THEN
        IF v_row.resultado->>'envase_release_fingerprint' IS NULL THEN RAISE EXCEPTION 'ENVASE_LEGACY_RECEIPT_REVIEW_REQUIRED' USING ERRCODE='PT409'; END IF;
        IF v_row.resultado->>'envase_release_fingerprint' IS DISTINCT FROM v_full_hash THEN RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_CONFLICT' USING ERRCODE='PT409'; END IF;
        PERFORM platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);
        RETURN (v_row.resultado-'envase_release_fingerprint') || jsonb_build_object('replay', true);
      END IF;
      RAISE EXCEPTION 'COCKPIT_IDEMPOTENCY_IN_PROGRESS';
    END IF;

    INSERT INTO public.cockpit_operacao_idempotencia
      (idempotency_key, operacao, usuario_id, payload_hash, alvo_id, status)
    VALUES (v_scope, 'registrar_envase_v1', v_uid, v_hash, p_lote_id, 'in_progress');
  END IF;

  IF p_validade <= current_date THEN RAISE EXCEPTION 'COCKPIT_ENVASE_VALIDADE_INVALIDA'; END IF;
  v_org:=platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem);
  -- Lock OS before programacao/lote; all fresh states checked after wait.
  PERFORM 1 FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org FOR UPDATE;
  IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org AND status::text IN ('em_cq','envase')) THEN RAISE EXCEPTION 'ENVASE_FRESH_STATE_DENIED' USING ERRCODE='PT409'; END IF;
  -- contexto canônico e coerência de vínculos

  -- lock determinístico: programação e lote
  PERFORM 1 FROM public.programacao_producao WHERE id = p_programacao_id FOR UPDATE;
  IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;

  SELECT coalesce(volume_produzido, 0), status::text, produto_id, microrganismo_id, programacao_id
    INTO v_produzido_ml, v_lote_status, v_produto_id, v_micro_id, v_lote_prog
    FROM public.lotes WHERE id = p_lote_id FOR UPDATE;
  IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_ctx FROM public.fn_cockpit_ctx_programacao(p_programacao_id);
  IF v_ctx.os_id <> p_os_id THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_PROGRAMACAO_OS'; END IF;
  IF v_ctx.origem <> v_origem THEN RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ORIGEM'; END IF;
  IF v_ctx.status_os IN ('cancelada','finalizada') THEN RAISE EXCEPTION 'COCKPIT_OS_ESTADO_TERMINAL'; END IF;
  PERFORM public.fn_cockpit_assert_b2b_liberado(v_ctx.partner_order_id);

  IF v_lote_status IS NULL THEN RAISE EXCEPTION 'COCKPIT_LOTE_NAO_ENCONTRADO'; END IF;
  IF v_lote_prog IS DISTINCT FROM p_programacao_id THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_LOTE_PROGRAMACAO';
  END IF;
  IF (v_produto_id IS DISTINCT FROM v_ctx.produto_id)
     AND (v_micro_id IS DISTINCT FROM v_ctx.microrganismo_id) THEN
    RAISE EXCEPTION 'COCKPIT_RELATION_MISMATCH_ITEM';
  END IF;
  IF v_lote_status = 'reprovado' THEN RAISE EXCEPTION 'COCKPIT_LOTE_REPROVADO_BLOQUEIA_ENVASE'; END IF;
  IF v_produzido_ml <= 0 OR v_produzido_ml::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'COCKPIT_LOTE_SEM_VOLUME_PRODUZIDO'; END IF;

  SELECT (resultado::text = 'aprovado') INTO v_cq_ok
    FROM public.controle_qualidade WHERE lote_id = p_lote_id
   ORDER BY created_at DESC, seq DESC LIMIT 1;
  IF coalesce(v_cq_ok, false) IS NOT TRUE THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXIGE_CQ_APROVADO'; END IF;

  IF v_lote_status IS DISTINCT FROM 'aprovado' THEN RAISE EXCEPTION 'ENVASE_APPROVED_LOT_REQUIRED' USING ERRCODE='PT409'; END IF;
  IF (SELECT count(*) FROM public.programacao_producao WHERE ordem_servico_id=p_os_id OR ordem_servico_onfarm_id=p_os_id)<>1
   OR (SELECT count(*) FROM public.lotes WHERE programacao_id=p_programacao_id)<>1
   OR EXISTS(SELECT 1 FROM public.production_order_link WHERE ordem_servico_id=p_os_id) THEN RAISE EXCEPTION 'ENVASE_ROOT_AMBIGUOUS' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.estoque_produto s WHERE s.reservado_para_os_id=p_os_id AND s.status::text<>'estornado' AND
   (NOT EXISTS(SELECT 1 FROM public.lotes sl WHERE sl.id=s.lote_id AND sl.organization_id=v_org) OR s.lote_id IS DISTINCT FROM p_lote_id OR s.produto_id IS DISTINCT FROM v_produto_id OR s.microrganismo_id IS DISTINCT FROM v_micro_id
    OR s.reservado_para_os_tipo IS DISTINCT FROM 'manual' OR s.reservado_para_cliente_id IS DISTINCT FROM v_ctx.cliente_id OR s.reservado_para_partner_order_id IS NOT NULL
    OR s.status::text IS DISTINCT FROM 'reservado' OR s.quantidade_reservada IS DISTINCT FROM s.quantidade OR s.volume_total<=0 OR s.volume_total::text IN ('NaN','Infinity','-Infinity'))) THEN
    RAISE EXCEPTION 'ENVASE_RESERVATION_LINEAGE_DENIED' USING ERRCODE='42501'; END IF;

  SELECT coalesce(sum(coalesce(volume_por_unidade,0) * coalesce(quantidade,0)), 0)
    INTO v_envasado_ml FROM public.envase WHERE lote_id = p_lote_id;
  v_saldo_ml := v_produzido_ml - v_envasado_ml;

  v_demanda_ml := coalesce(v_ctx.volume_necessario, 0);
  SELECT coalesce(sum(coalesce(volume_total,0)), 0) * 1000 INTO v_reservado_ml
    FROM public.estoque_produto
   WHERE reservado_para_os_id = p_os_id
     AND coalesce(reservado_para_os_tipo, v_origem) = v_origem
     AND status <> 'estornado'::public.status_estoque;
  v_pendente_ml := greatest(0, v_demanda_ml - v_reservado_ml);

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    IF jsonb_typeof(v_linha)<>'object' OR NOT (v_linha ? 'quantidade') OR coalesce(v_linha->>'quantidade','') !~ '^[0-9]+$' THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_qtd := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 ELSE NULL END;
    IF v_unit_ml IS NULL THEN RAISE EXCEPTION 'COCKPIT_EMBALAGEM_INVALIDA'; END IF;
    IF v_qtd <= 0 THEN RAISE EXCEPTION 'COCKPIT_QUANTIDADE_INVALIDA'; END IF;
    v_total_ml := v_total_ml + (v_unit_ml * v_qtd);
  END LOOP;

  IF v_total_ml > v_saldo_ml THEN RAISE EXCEPTION 'COCKPIT_ENVASE_EXCEDE_PRODUZIDO'; END IF;

  FOR v_linha IN SELECT * FROM jsonb_array_elements(p_linhas) LOOP
    v_tipo := v_linha->>'tipo_embalagem';
    v_qtd  := (v_linha->>'quantidade')::int;
    v_unit_ml := CASE v_tipo WHEN 'frasco_1L' THEN 1000 WHEN 'bombona_5L' THEN 5000
                             WHEN 'bombona_20L' THEN 20000 END;

    IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
    IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org AND status::text IN ('em_cq','envase')) THEN RAISE EXCEPTION 'ENVASE_FRESH_STATE_DENIED' USING ERRCODE='PT409'; END IF;
    SELECT (resultado::text='aprovado') INTO v_cq_ok FROM public.controle_qualidade WHERE lote_id=p_lote_id ORDER BY created_at DESC,seq DESC LIMIT 1 FOR SHARE;
    SELECT (resultado::text='aprovado') INTO v_cq_ok FROM public.controle_qualidade WHERE lote_id=p_lote_id ORDER BY created_at DESC,seq DESC LIMIT 1;
    IF coalesce(v_cq_ok,false) IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_FRESH_CQ_DENIED' USING ERRCODE='PT409'; END IF;
    v_envase_id:=gen_random_uuid();
    INSERT INTO platform_private.envase_insert_permits_v1(txid,actor,organization_id,action,target,lote,os,prog,payload) VALUES(txid_current(),v_uid,v_org,'envase',v_envase_id,p_lote_id,p_os_id,p_programacao_id,jsonb_build_object('id',v_envase_id,'lote_id',p_lote_id,'tipo_embalagem',v_tipo,'volume_por_unidade',v_unit_ml,'quantidade',v_qtd,'data_envase',current_date,'operador',nullif(p_operador,''),'organization_id',v_org,'etiqueta_gerada',false,'etiqueta_id',NULL,'etiqueta_gerada_em',NULL,'etiqueta_gerada_por',NULL));
    INSERT INTO public.envase (id,lote_id, tipo_embalagem, volume_por_unidade, quantidade, data_envase, operador, organization_id)
    VALUES (v_envase_id,p_lote_id, v_tipo::public.tipo_embalagem, v_unit_ml, v_qtd, current_date, nullif(p_operador, ''), v_org)
    RETURNING id INTO v_envase_id;
    v_env_ct := v_env_ct + 1;

    v_reservadas := CASE WHEN v_pendente_ml > 0
                         THEN least(v_qtd, floor(v_pendente_ml / v_unit_ml)::int) ELSE 0 END;
    v_livres := v_qtd - v_reservadas;
    v_pendente_ml := v_pendente_ml - (v_reservadas * v_unit_ml);

    IF v_reservadas > 0 THEN
      v_estoque_id:=gen_random_uuid();
      INSERT INTO platform_private.envase_insert_permits_v1(txid,actor,organization_id,action,target,lote,os,prog,payload) VALUES(txid_current(),v_uid,v_org,'estoque_produto',v_estoque_id,p_lote_id,p_os_id,p_programacao_id,jsonb_build_object('id',v_estoque_id,'produto_id',v_produto_id,'microrganismo_id',v_micro_id,'lote_id',p_lote_id,'envase_id',v_envase_id,'quantidade',v_reservadas,'volume_total',(v_unit_ml*v_reservadas)/1000.0,'validade',p_validade,'status','reservado','reservado_para_os_id',p_os_id,'reservado_para_os_tipo',v_origem,'reservado_para_cliente_id',v_ctx.cliente_id,'reservado_para_partner_id',NULL,'reservado_para_partner_order_id',v_ctx.partner_order_id,'quantidade_reservada',v_reservadas,'reservado_por',v_uid,'reservado_em',now(),'expedido_por',NULL,'expedido_em',NULL,'observacao_reserva',NULL));
      INSERT INTO public.estoque_produto (id,
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total,
        validade, status, reservado_para_os_id, reservado_para_os_tipo,
        reservado_para_cliente_id, reservado_para_partner_order_id,
        quantidade_reservada, reservado_por, reservado_em
      ) VALUES (
        v_estoque_id,v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_reservadas,
        (v_unit_ml * v_reservadas) / 1000.0, p_validade, 'reservado'::public.status_estoque,
        p_os_id, v_origem, v_ctx.cliente_id, v_ctx.partner_order_id,
        v_reservadas, v_uid, now()
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_res_ml := v_res_ml + (v_unit_ml * v_reservadas);

    END IF;

    IF v_livres > 0 THEN
      v_estoque_id:=gen_random_uuid();
      INSERT INTO platform_private.envase_insert_permits_v1(txid,actor,organization_id,action,target,lote,os,prog,payload) VALUES(txid_current(),v_uid,v_org,'estoque_produto',v_estoque_id,p_lote_id,p_os_id,p_programacao_id,jsonb_build_object('id',v_estoque_id,'produto_id',v_produto_id,'microrganismo_id',v_micro_id,'lote_id',p_lote_id,'envase_id',v_envase_id,'quantidade',v_livres,'volume_total',(v_unit_ml*v_livres)/1000.0,'validade',p_validade,'status','disponivel','reservado_para_os_id',NULL,'reservado_para_os_tipo',NULL,'reservado_para_cliente_id',NULL,'reservado_para_partner_id',NULL,'reservado_para_partner_order_id',NULL,'quantidade_reservada',NULL,'reservado_por',NULL,'reservado_em',NULL,'expedido_por',NULL,'expedido_em',NULL,'observacao_reserva',NULL));
      INSERT INTO public.estoque_produto (id,
        produto_id, microrganismo_id, lote_id, envase_id, quantidade, volume_total, validade, status
      ) VALUES (
        v_estoque_id,v_produto_id, v_micro_id, p_lote_id, v_envase_id, v_livres,
        (v_unit_ml * v_livres) / 1000.0, p_validade, 'disponivel'::public.status_estoque
      ) RETURNING id INTO v_estoque_id;
      v_est_ct := v_est_ct + 1;
      v_liv_ml := v_liv_ml + (v_unit_ml * v_livres);

    END IF;
  END LOOP;

    IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=p_os_id AND organization_id=v_org AND status::text IN ('em_cq','envase')) THEN RAISE EXCEPTION 'ENVASE_FRESH_STATE_DENIED' USING ERRCODE='PT409'; END IF;
    SELECT (resultado::text='aprovado') INTO v_cq_ok FROM public.controle_qualidade WHERE lote_id=p_lote_id ORDER BY created_at DESC,seq DESC LIMIT 1 FOR SHARE;
    SELECT (resultado::text='aprovado') INTO v_cq_ok FROM public.controle_qualidade WHERE lote_id=p_lote_id ORDER BY created_at DESC,seq DESC LIMIT 1;
    IF coalesce(v_cq_ok,false) IS NOT TRUE THEN RAISE EXCEPTION 'ENVASE_FRESH_CQ_DENIED' USING ERRCODE='PT409'; END IF;

  -- regra canônica de encerramento
  IF v_pendente_ml <= 0 THEN
    v_estado := 'completed';
  ELSIF p_permitir_parcial THEN
    IF NOT public.fn_cockpit_is_gestor() THEN RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_ALCADA'; END IF;
    IF nullif(btrim(coalesce(p_motivo_parcial, '')), '') IS NULL THEN
      RAISE EXCEPTION 'COCKPIT_ENVASE_PARCIAL_SEM_MOTIVO';
    END IF;
    v_estado := 'completed_override';
  ELSE
    v_estado := 'partial';
  END IF;

  INSERT INTO public.laboratorio_esteira_eventos
    (os_id, origem_os, programacao_id, lote_id, etapa_anterior, etapa_nova, acao, usuario_id, observacao)
  VALUES (p_os_id, v_origem, p_programacao_id, p_lote_id, 'em_envase',
          CASE WHEN v_estado = 'partial' THEN 'em_envase' ELSE 'estoque_gerado' END,
          'registrar_envase_v1', v_uid,
          format('Envase transacional [%s]: %s registros, %s entradas, reservado %s ml, livre %s ml, pendente %s ml. %s',
                 v_estado, v_env_ct, v_est_ct, v_res_ml, v_liv_ml, v_pendente_ml,
                 coalesce('Motivo: ' || nullif(btrim(coalesce(p_motivo_parcial, '')), ''), '')));

  IF v_estado <> 'partial' THEN
    v_avanco := platform_private.stock_envase_complete_v1(p_os_id, p_programacao_id, p_lote_id, v_estado);
  ELSE
    v_avanco := jsonb_build_object('success', false, 'motivo', 'COCKPIT_ENVASE_PARCIAL_NAO_AVANCA');
  END IF;

  IF EXISTS(SELECT 1 FROM platform_private.envase_insert_permits_v1 WHERE txid=txid_current()) THEN RAISE EXCEPTION 'ENVASE_PERMIT_NOT_CONSUMED' USING ERRCODE='42501'; END IF;
  v_result := jsonb_build_object(
    'success', true, 'replay', false, 'estado', v_estado,
    'envases', v_env_ct, 'entradas_estoque', v_est_ct,
    'volume_reservado_ml', v_res_ml, 'volume_livre_ml', v_liv_ml,
    'pendente_os_ml', v_pendente_ml, 'saldo_restante_ml', v_saldo_ml - v_total_ml,
    'avanco', v_avanco,
    'message', CASE WHEN v_estado = 'partial'
                    THEN 'Envase registrado — necessidade da OS ainda não coberta.'
                    ELSE 'Envase e estoque registrados em transação única.' END);

  IF platform_private.stock_envase_scope_v1(p_lote_id,p_programacao_id,p_os_id,p_origem) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'ENVASE_SCOPE_CHANGED' USING ERRCODE='42501'; END IF;
  IF v_scope IS NOT NULL THEN
    UPDATE public.cockpit_operacao_idempotencia
       SET resultado = v_result||jsonb_build_object('envase_release_fingerprint',v_full_hash), status = 'done', updated_at = now()
     WHERE idempotency_key = v_scope;
  END IF;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION public.rpc_cockpit_registrar_envase_v1(p_lote_id uuid, p_os_id uuid, p_origem text, p_programacao_id uuid, p_linhas jsonb, p_validade date, p_operador text, p_idempotency_key text, p_permitir_parcial boolean, p_motivo_parcial text) OWNER TO postgres;

