-- Name: rpc_create_portal_notification_secure(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_create_portal_notification_secure(p_cliente_id uuid, p_titulo text, p_mensagem text, p_tipo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ BEGIN RAISE EXCEPTION 'NOTIF_SOURCE_RECIPIENT_REQUIRED' USING ERRCODE='42501'; END $$;


ALTER FUNCTION public.rpc_create_portal_notification_secure(p_cliente_id uuid, p_titulo text, p_mensagem text, p_tipo text) OWNER TO postgres;

--
-- Name: rpc_create_portal_notification_secure(uuid, text, text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_create_portal_notification_secure(_cliente_id uuid, _tipo text, _titulo text, _mensagem text, _link text DEFAULT NULL::text, _source_type text DEFAULT NULL::text, _source_id uuid DEFAULT NULL::uuid, _idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  new_id uuid; existing_id uuid; caller_uid uuid := auth.uid();
  st text := lower(coalesce(_source_type,''));
  allowed_source_types text[] := ARRAY['registros_consultor','ordem_servico','aplicacao'];
  allowed_tipos public.tipo_notificacao_portal[] := ARRAY['informativo','alerta','entrega','recomendacao','aplicacao','sistema']::public.tipo_notificacao_portal[];
  is_admin_caller boolean := false; is_authorized boolean := false;
  v_rc_cli uuid; v_rc_owner uuid; v_rc_created_by uuid; v_rc_finalized_by uuid;
  v_os_cli uuid; v_apl_cli uuid; v_apl_resp uuid; v_apl_created_by uuid;
BEGIN
  IF caller_uid IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória' USING ERRCODE = '42501';
  END IF;
  IF _cliente_id IS NULL OR _tipo IS NULL OR _titulo IS NULL OR _mensagem IS NULL THEN
    RAISE EXCEPTION 'cliente_id, tipo, titulo e mensagem são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF (_source_type IS NULL) <> (_source_id IS NULL) THEN
    RAISE EXCEPTION 'source_type e source_id devem ser informados juntos' USING ERRCODE = '22023';
  END IF;
  IF _source_type IS NULL THEN
    RAISE EXCEPTION 'source_type/source_id são obrigatórios' USING ERRCODE = '22023';
  END IF;
  IF NOT (st = ANY(allowed_source_types)) THEN
    RAISE EXCEPTION 'source_type % fora da whitelist', _source_type USING ERRCODE = '22023';
  END IF;
  IF NOT (_tipo::public.tipo_notificacao_portal = ANY(allowed_tipos)) THEN
    RAISE EXCEPTION 'Tipo % não permitido', _tipo USING ERRCODE = '22023';
  END IF;
  IF char_length(_titulo) > 200 THEN RAISE EXCEPTION 'Título excede 200 caracteres' USING ERRCODE='22023'; END IF;
  IF char_length(_mensagem) > 2000 THEN RAISE EXCEPTION 'Mensagem excede 2000 caracteres' USING ERRCODE='22023'; END IF;
  IF _link IS NOT NULL AND _link !~ '^/[A-Za-z0-9_\-./?=&%#]{0,500}$' THEN
    RAISE EXCEPTION 'Link inválido' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = _cliente_id) THEN
    RAISE EXCEPTION 'Cliente inexistente' USING ERRCODE = '23503';
  END IF;

  is_admin_caller := has_role(caller_uid, 'administrador'::app_role);
  IF st = 'registros_consultor' THEN
    SELECT cliente_id, consultor_responsavel, created_by, finalized_by
      INTO v_rc_cli, v_rc_owner, v_rc_created_by, v_rc_finalized_by
      FROM public.registros_consultor WHERE id = _source_id;
    IF v_rc_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado' USING ERRCODE='23503'; END IF;
    IF v_rc_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller OR caller_uid = v_rc_owner OR caller_uid = v_rc_created_by OR caller_uid = v_rc_finalized_by
       OR EXISTS (SELECT 1 FROM public.registros_consultor_status_log sl
                   WHERE sl.registro_consultor_id = _source_id AND sl.changed_by = caller_uid)
    THEN is_authorized := true; END IF;
  ELSIF st = 'ordem_servico' THEN
    SELECT cliente_id INTO v_os_cli FROM public.ordens_servico WHERE id = _source_id;
    IF v_os_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado em ordens_servico' USING ERRCODE='23503'; END IF;
    IF v_os_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller THEN is_authorized := true; END IF;
  ELSIF st = 'aplicacao' THEN
    SELECT os.cliente_id, a.responsavel_id, a.created_by
      INTO v_apl_cli, v_apl_resp, v_apl_created_by
      FROM public.aplicacoes a JOIN public.ordens_servico os ON os.id = a.ordem_servico_id
     WHERE a.id = _source_id;
    IF v_apl_cli IS NULL THEN RAISE EXCEPTION 'source_id não encontrado em aplicacoes' USING ERRCODE='23503'; END IF;
    IF v_apl_cli <> _cliente_id THEN RAISE EXCEPTION 'source_id pertence a outro cliente' USING ERRCODE='42501'; END IF;
    IF is_admin_caller OR caller_uid = v_apl_resp OR caller_uid = v_apl_created_by THEN is_authorized := true; END IF;
  END IF;

  IF NOT is_authorized THEN
    RAISE EXCEPTION 'Sem vínculo/papel para notificar cliente por %', _source_type USING ERRCODE='42501';
  END IF;

  IF _idempotency_key IS NOT NULL THEN
    SELECT id INTO existing_id FROM public.portal_notificacoes
     WHERE idempotency_key = _idempotency_key LIMIT 1;
    IF existing_id IS NOT NULL THEN
      RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
    END IF;
  END IF;

  INSERT INTO public.portal_notificacoes
    (cliente_id, tipo, titulo, mensagem, link, created_by, source_type, source_id, idempotency_key)
  VALUES
    (_cliente_id, _tipo::public.tipo_notificacao_portal, _titulo, _mensagem,
     _link, caller_uid, _source_type, _source_id, _idempotency_key)
  RETURNING id INTO new_id;

  RETURN jsonb_build_object('created', true, 'duplicated', false, 'notification_id', new_id);
EXCEPTION WHEN unique_violation THEN
  SELECT id INTO existing_id FROM public.portal_notificacoes
   WHERE idempotency_key = _idempotency_key LIMIT 1;
  RETURN jsonb_build_object('created', false, 'duplicated', true, 'notification_id', existing_id);
END;
$_$;


ALTER FUNCTION public.rpc_create_portal_notification_secure(_cliente_id uuid, _tipo text, _titulo text, _mensagem text, _link text, _source_type text, _source_id uuid, _idempotency_key text) OWNER TO postgres;

--
-- Name: rpc_criar_alerta_climatico_v1(uuid, uuid, public.tipo_alerta, public.nivel_risco, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_criar_alerta_climatico_v1(p_fazenda_id uuid, p_talhao_id uuid, p_tipo_alerta public.tipo_alerta, p_nivel_risco public.nivel_risco, p_descricao text) RETURNS TABLE(id uuid, criado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '3s'
    AS $$
declare
  v_id uuid;
begin
  if not public.technical_actor_ready(auth.uid()) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if p_tipo_alerta is null or p_nivel_risco is null or p_fazenda_id is null or p_talhao_id is null or nullif(btrim(p_descricao), '') is null then
    raise exception 'INVALID_INPUT';
  end if;
  if length(p_descricao) > 2000 then raise exception 'DESCRIPTION_TOO_LONG'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;
  perform 1 from cf_user_guards_v1.state where singleton for update;
  if not found then raise exception 'monitoring_gate_unavailable' using errcode='55000'; end if;
  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_fazenda_id::text || ':' || p_talhao_id::text || ':' || p_tipo_alerta::text, 0
  ));

  if not public.technical_actor_ready(auth.uid()) or not (
    public.has_role(auth.uid(), 'administrador'::public.app_role)
    or public.has_role(auth.uid(), 'gestor'::public.app_role)
  ) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
  if not platform_private.monitoring_refs_in_actor_tenant(p_fazenda_id,p_talhao_id,null) then
    raise exception 'monitoring_reference_not_found' using errcode='PT404';
  end if;

  select a.id into v_id
  from public.alertas_agronomicos a
  where a.fazenda_id = p_fazenda_id
    and a.talhao_id = p_talhao_id
    and a.tipo_alerta = p_tipo_alerta
    and platform_private.monitoring_refs_in_actor_tenant(a.fazenda_id,a.talhao_id,a.registro_origem_id)
    and a.status <> 'encerrado'::public.status_alerta
  order by a.created_at desc
  limit 1;

  if v_id is not null then
    return query select v_id, false;
    return;
  end if;

  insert into public.alertas_agronomicos (
    fazenda_id, talhao_id, tipo_alerta, nivel_risco, descricao
  ) values (
    p_fazenda_id, p_talhao_id, p_tipo_alerta, p_nivel_risco, btrim(p_descricao)
  ) returning alertas_agronomicos.id into v_id;

  return query select v_id, true;
end;
$$;


ALTER FUNCTION public.rpc_criar_alerta_climatico_v1(p_fazenda_id uuid, p_talhao_id uuid, p_tipo_alerta public.tipo_alerta, p_nivel_risco public.nivel_risco, p_descricao text) OWNER TO postgres;

--
-- Name: rpc_criar_embalagens_pos_envase(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_criar_embalagens_pos_envase(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_qtd int := COALESCE((p_payload->>'quantidade_embalagens')::int, 0);
  v_lote uuid := (p_payload->>'lote_id')::uuid;
  v_volume numeric := (p_payload->>'volume')::numeric;
  v_unidade text := COALESCE(p_payload->>'unidade','L');
  v_gerar_et bool := COALESCE((p_payload->>'gerar_etiqueta_automaticamente')::bool, false);
  v_envase uuid := NULLIF(p_payload->>'envase_id','')::uuid;
  v_produto uuid := NULLIF(p_payload->>'produto_id','')::uuid;
  v_cliente uuid := NULLIF(p_payload->>'cliente_id','')::uuid;
  v_fazenda uuid := NULLIF(p_payload->>'fazenda_id','')::uuid;
  v_fab date; v_val date;
  v_codigo text; v_emb_id uuid; v_etq_id uuid;
  v_arr jsonb := '[]'::jsonb;
  v_meta jsonb;
  v_produto_warning bool := false;
  v_warnings jsonb := '[]'::jsonb;
  i int;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(gen_random_uuid()) THEN
    RAISE EXCEPTION 'sem permissão';
  END IF;
  IF v_lote IS NULL THEN RAISE EXCEPTION 'lote_id obrigatório'; END IF;
  IF v_volume IS NULL OR v_volume <= 0 THEN RAISE EXCEPTION 'volume inválido'; END IF;
  IF v_qtd < 1 OR v_qtd > 500 THEN RAISE EXCEPTION 'quantidade entre 1 e 500'; END IF;

  -- Valida referências reais (Fase 2.2)
  IF NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote) THEN
    RAISE EXCEPTION 'Lote informado não existe (%).', v_lote;
  END IF;
  IF v_envase IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.envase WHERE id = v_envase) THEN
    RAISE EXCEPTION 'Envase informado não existe (%).', v_envase;
  END IF;
  IF v_cliente IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.clientes WHERE id = v_cliente) THEN
    RAISE EXCEPTION 'Cliente informado não existe (%).', v_cliente;
  END IF;
  IF v_fazenda IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.fazendas WHERE id = v_fazenda) THEN
    RAISE EXCEPTION 'Fazenda informada não existe (%).', v_fazenda;
  END IF;

  -- Fallback de produto_id a partir do lote
  IF v_produto IS NULL THEN
    SELECT produto_id INTO v_produto FROM public.lotes WHERE id = v_lote;
  END IF;
  IF v_produto IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.produtos WHERE id = v_produto) THEN
    RAISE EXCEPTION 'Produto informado não existe (%).', v_produto;
  END IF;
  IF v_produto IS NULL THEN
    v_produto_warning := true;
    v_warnings := v_warnings || to_jsonb('produto_id_nao_identificado'::text);
  END IF;

  SELECT data_envase INTO v_fab FROM public.envase WHERE id = v_envase;
  IF v_fab IS NULL THEN v_fab := CURRENT_DATE; END IF;
  v_val := v_fab + INTERVAL '6 months';

  FOR i IN 1..v_qtd LOOP
    v_codigo := 'AR-EMB-' || lpad(nextval('public.estoque_embalagem_seq')::text, 6, '0');
    v_meta := jsonb_build_object();
    IF v_produto_warning THEN
      v_meta := v_meta || jsonb_build_object('produto_id_nao_identificado', true);
    END IF;

    INSERT INTO public.estoque_embalagens(
      codigo_embalagem, lote_id, produto_id, envase_id, envase_item_id, volume, unidade, quantidade,
      tipo_embalagem, local_estoque, cliente_id, fazenda_id, fabricado_em, validade_em,
      entrada_estoque_em, criado_por, metadata
    ) VALUES (
      v_codigo, v_lote, v_produto, v_envase,
      NULLIF(p_payload->>'envase_item_id','')::uuid,
      v_volume, v_unidade, 1,
      p_payload->>'tipo_embalagem',
      p_payload->>'local_estoque',
      v_cliente, v_fazenda,
      v_fab, v_val,
      now(), v_uid, v_meta
    ) RETURNING id INTO v_emb_id;

    INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_novo, user_id, metadata)
      VALUES (v_emb_id, 'entrada_estoque', 'em_estoque', v_uid, jsonb_build_object('codigo', v_codigo));

    v_etq_id := NULL;
    IF v_gerar_et THEN
      SELECT (public.rpc_gerar_etiqueta_produto(jsonb_build_object(
        'lote_id', v_lote, 'envase_id', v_envase,
        'produto_id', v_produto,
        'cliente_id', v_cliente,
        'fazenda_id', v_fazenda,
        'volume', v_volume, 'unidade', v_unidade,
        'quantidade_embalagens', 1
      )) ->> 'etiqueta_id')::uuid INTO v_etq_id;

      IF v_etq_id IS NULL THEN
        RAISE EXCEPTION 'Falha ao gerar etiqueta automática para a embalagem. Nenhuma embalagem foi criada. Tente novamente ou gere as embalagens sem etiqueta automática.';
      END IF;

      UPDATE public.estoque_embalagens SET etiqueta_id = v_etq_id WHERE id = v_emb_id;
      UPDATE public.produto_etiquetas SET embalagem_id = v_emb_id WHERE id = v_etq_id;
      INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
        VALUES (v_emb_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', v_etq_id));
      INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
        VALUES (v_etq_id, 'etiqueta_gerada', v_uid, jsonb_build_object('embalagem_id', v_emb_id));
    END IF;

    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
      VALUES ('estoque_embalagem', v_emb_id, 'EMB_CREATED', v_uid,
              jsonb_build_object('codigo', v_codigo, 'etiqueta_id', v_etq_id, 'produto_id', v_produto));

    v_arr := v_arr || jsonb_build_object('embalagem_id', v_emb_id, 'codigo_embalagem', v_codigo, 'etiqueta_id', v_etq_id);
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'total_embalagens', v_qtd,
    'embalagens', v_arr,
    'warnings', v_warnings
  );
END $$;


ALTER FUNCTION public.rpc_criar_embalagens_pos_envase(p_payload jsonb) OWNER TO postgres;

--
-- Name: rpc_criar_visita_idempotente(uuid, uuid, uuid, uuid, uuid, date, public.tipo_visita, text, text, text, uuid, text, public.categoria_problema_consultor, public.nivel_pressao, numeric, public.urgencia_consultor, text, text, text, numeric, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_criar_visita_idempotente(p_client_uuid uuid, p_cliente_id uuid, p_fazenda_id uuid, p_talhao_id uuid, p_cultura_id uuid DEFAULT NULL::uuid, p_data_vistoria date DEFAULT CURRENT_DATE, p_tipo_visita public.tipo_visita DEFAULT 'vistoria_inicial'::public.tipo_visita, p_objetivo_visita text DEFAULT NULL::text, p_safra text DEFAULT NULL::text, p_fase_fenologica text DEFAULT NULL::text, p_solicitacao_id uuid DEFAULT NULL::uuid, p_origem text DEFAULT 'visita_avulsa'::text, p_categoria_problema public.categoria_problema_consultor DEFAULT NULL::public.categoria_problema_consultor, p_nivel_pressao public.nivel_pressao DEFAULT NULL::public.nivel_pressao, p_percentual_area_afetada numeric DEFAULT NULL::numeric, p_urgencia public.urgencia_consultor DEFAULT NULL::public.urgencia_consultor, p_localizacao_na_area text DEFAULT NULL::text, p_observacoes_tecnicas text DEFAULT NULL::text, p_problema_principal text DEFAULT NULL::text, p_area_hectares numeric DEFAULT NULL::numeric, p_latitude numeric DEFAULT NULL::numeric, p_longitude numeric DEFAULT NULL::numeric, p_registro_origem_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_existing public.registros_consultor%ROWTYPE;
  v_new_id uuid;
  v_fazenda_cliente uuid;
  v_talhao_fazenda uuid;
  v_origem text := COALESCE(NULLIF(p_origem,''), 'visita_avulsa');
  v_natureza natureza_registro_consultor;
  v_cultura uuid := p_cultura_id;
  v_safra text := p_safra;
  v_missing text[] := ARRAY[]::text[];
  c_cultura_opcional constant text[] := ARRAY['ocorrencia_campo','solicitacao_produtor'];
BEGIN
  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthenticated');
  END IF;

  IF v_origem NOT IN ('ocorrencia_campo','solicitacao_produtor','agenda','retorno_monitoramento','visita_avulsa') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_origin');
  END IF;

  v_natureza := CASE WHEN v_origem = 'ocorrencia_campo' THEN 'ocorrencia'::natureza_registro_consultor
                     ELSE 'visita'::natureza_registro_consultor END;

  IF p_client_uuid IS NULL
     OR p_cliente_id IS NULL
     OR p_fazenda_id IS NULL
     OR p_talhao_id IS NULL
     OR p_data_vistoria IS NULL
     OR p_tipo_visita IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
  END IF;

  IF NOT public.technical_refs_in_actor_tenant(p_cliente_id,p_fazenda_id,p_talhao_id)
     OR NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor')
       OR ((public.has_role(v_uid,'consultor_tecnico') OR public.has_role(v_uid,'tecnico_agronomo'))
       AND public.technical_client_link(v_uid,p_cliente_id,ARRAY['execute','manage']))) THEN
    RETURN jsonb_build_object('ok',false,'error','technical_access_required');
  END IF;
  IF p_solicitacao_id IS NOT NULL AND NOT public.can_user_access_solicitacao(p_solicitacao_id) THEN
    RETURN jsonb_build_object('ok',false,'error','invalid_request');
  END IF;
  IF p_registro_origem_id IS NOT NULL AND NOT public.can_view_technical_visit(v_uid,p_registro_origem_id) THEN
    RETURN jsonb_build_object('ok',false,'error','invalid_request');
  END IF;
  SELECT * INTO v_existing
    FROM public.registros_consultor
    WHERE client_uuid = p_client_uuid
    LIMIT 1;

  IF FOUND THEN
    IF NOT public.can_manage_technical_visit(v_uid,v_existing.id)
       OR v_existing.cliente_id IS DISTINCT FROM p_cliente_id
       OR v_existing.fazenda_id IS DISTINCT FROM p_fazenda_id
       OR v_existing.talhao_id IS DISTINCT FROM p_talhao_id
       OR (v_existing.consultor_responsavel <> v_uid
       AND NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor'))) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
    END IF;

    RETURN jsonb_build_object(
      'ok', true, 'created', false, 'idempotent', true,
      'registro_id', v_existing.id,
      'client_uuid', v_existing.client_uuid,
      'status', v_existing.status::text,
      'origem', v_existing.origem_atendimento,
      'version', v_existing.version,
      'cultura_id', v_existing.cultura_id,
      'missing_fields', CASE WHEN v_existing.cultura_id IS NULL
                             THEN jsonb_build_array('cultura_id') ELSE '[]'::jsonb END,
      'next_step', CASE WHEN v_existing.cultura_id IS NULL THEN 'identificacao' ELSE 'continuar' END,
      'can_edit', v_existing.status IN ('rascunho','em_andamento','reprovado'),
      'next_route', '/app/visita/' || v_existing.id::text,
      'pdf_status', v_existing.pdf_status
    );
  END IF;

  IF NOT public.has_active_user_cliente_access(v_uid, p_cliente_id, ARRAY['execute','manage']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'technical_access_required');
  END IF;

  SELECT cliente_id INTO v_fazenda_cliente FROM public.fazendas WHERE id = p_fazenda_id;
  IF v_fazenda_cliente IS NULL OR v_fazenda_cliente <> p_cliente_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_farm');
  END IF;

  SELECT fazenda_id INTO v_talhao_fazenda FROM public.talhoes WHERE id = p_talhao_id;
  IF v_talhao_fazenda IS NULL OR v_talhao_fazenda <> p_fazenda_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_plot');
  END IF;

  IF v_cultura IS NULL THEN
    WITH cand AS (
      SELECT DISTINCT ts.cultura_id, ts.safra
        FROM public.talhao_safras ts
       WHERE ts.talhao_id = p_talhao_id
         AND ts.cultura_id IS NOT NULL
         AND COALESCE(ts.status,'ativa') IN ('ativa','em_andamento','plantada')
    )
    SELECT c.cultura_id, c.safra
      INTO v_cultura, v_safra
      FROM cand c
     WHERE (SELECT count(*) FROM cand) = 1;

    IF NOT FOUND THEN
      v_cultura := NULL;
      v_safra := p_safra;
    END IF;
  END IF;

  IF v_cultura IS NULL AND NOT (v_origem = ANY (c_cultura_opcional)) THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'invalid_request',
      'missing_fields', jsonb_build_array('cultura_id'),
      'next_step', 'identificacao'
    );
  END IF;

  IF v_cultura IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.culturas WHERE id = v_cultura) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_crop');
  END IF;

  IF p_solicitacao_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.portal_solicitacoes
        WHERE id = p_solicitacao_id AND cliente_id = p_cliente_id
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
    END IF;
  END IF;

  IF v_cultura IS NULL THEN
    v_missing := array_append(v_missing, 'cultura_id');
  END IF;

  INSERT INTO public.registros_consultor (
    client_uuid,
    cliente_id, fazenda_id, talhao_id, cultura_id,
    data_vistoria, tipo_visita, objetivo_visita, safra, fase_fenologica,
    solicitacao_id, registro_origem_id, origem_atendimento,
    categoria_problema, nivel_pressao, percentual_area_afetada, urgencia,
    localizacao_na_area, observacoes_tecnicas, problema_principal,
    area_hectares, latitude, longitude,
    consultor_responsavel, consultor_profile_id, created_by,
    natureza_registro, status, version, pdf_status
  ) VALUES (
    p_client_uuid,
    p_cliente_id, p_fazenda_id, p_talhao_id, v_cultura,
    p_data_vistoria, p_tipo_visita, p_objetivo_visita, v_safra, p_fase_fenologica,
    p_solicitacao_id, p_registro_origem_id, v_origem,
    p_categoria_problema, COALESCE(p_nivel_pressao,'medio'), p_percentual_area_afetada,
    COALESCE(p_urgencia,'media'),
    p_localizacao_na_area, p_observacoes_tecnicas, p_problema_principal,
    p_area_hectares, p_latitude, p_longitude,
    v_uid, (SELECT pr.id FROM public.profiles pr WHERE pr.user_id = v_uid LIMIT 1), v_uid,
    v_natureza, 'rascunho', 1, 'pending'
  )
  RETURNING id INTO v_new_id;

  RETURN jsonb_build_object(
    'ok', true, 'created', true, 'idempotent', false,
    'registro_id', v_new_id,
    'client_uuid', p_client_uuid,
    'status', 'rascunho',
    'origem', v_origem,
    'version', 1,
    'cultura_id', v_cultura,
    'missing_fields', to_jsonb(v_missing),
    'next_step', CASE WHEN array_length(v_missing,1) IS NULL THEN 'continuar' ELSE 'identificacao' END,
    'can_edit', true,
    'next_route', '/app/visita/' || v_new_id::text,
    'pdf_status', 'pending'
  );

EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO v_existing
      FROM public.registros_consultor WHERE client_uuid = p_client_uuid LIMIT 1;
    IF FOUND THEN
      IF NOT public.can_manage_technical_visit(v_uid,v_existing.id)
       OR v_existing.cliente_id IS DISTINCT FROM p_cliente_id
       OR v_existing.fazenda_id IS DISTINCT FROM p_fazenda_id
       OR v_existing.talhao_id IS DISTINCT FROM p_talhao_id
       OR (v_existing.consultor_responsavel <> v_uid
         AND NOT (public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor'))) THEN
        RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
      END IF;
      RETURN jsonb_build_object(
        'ok', true, 'created', false, 'idempotent', true,
        'registro_id', v_existing.id,
        'client_uuid', v_existing.client_uuid,
        'status', v_existing.status::text,
        'origem', v_existing.origem_atendimento,
        'version', v_existing.version,
        'cultura_id', v_existing.cultura_id,
        'missing_fields', CASE WHEN v_existing.cultura_id IS NULL
                               THEN jsonb_build_array('cultura_id') ELSE '[]'::jsonb END,
        'next_step', CASE WHEN v_existing.cultura_id IS NULL THEN 'identificacao' ELSE 'continuar' END,
        'can_edit', v_existing.status IN ('rascunho','em_andamento','reprovado'),
        'next_route', '/app/visita/' || v_existing.id::text,
        'pdf_status', v_existing.pdf_status
      );
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'idempotency_conflict');
END;
$$;


