--
-- Name: rpc_dashboard_geral_lab_resumo(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_dashboard_geral_lab_resumo() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  v_org := platform_private.current_user_organization_id();

  IF NOT EXISTS (
    SELECT 1
      FROM public.user_roles ur
     WHERE ur.user_id = v_uid
       AND ur.role IN ('administrador'::public.app_role, 'gestor'::public.app_role)
  ) THEN
    RAISE EXCEPTION 'Acesso negado' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'resumo', '{}'::jsonb,
    'dados_indisponiveis', jsonb_build_array(
      'os_aguardando','lotes_producao','cq_pendente','envases_pendentes',
      'insumos_criticos','entregas_pendentes'
    ),
    'gerado_em', now(),
    'organization_scoped', v_org IS NOT NULL
  );
END;
$$;


ALTER FUNCTION public.rpc_dashboard_geral_lab_resumo() OWNER TO postgres;

--
-- Name: rpc_defer_communication_delivery(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_defer_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text, p_delay_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_outbox%rowtype; v_role text; v_delay int; v_attempts int;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  v_delay := GREATEST(30, LEAST(3600, COALESCE(p_delay_seconds, 300)));
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing'; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro'; END IF;
  v_attempts := GREATEST(COALESCE(r.attempts,0) - 1, 0);
  UPDATE public.comunicacao_outbox
     SET status='pending', attempts=v_attempts,
         next_attempt_at=now() + make_interval(secs => v_delay),
         error_code='deferred',
         error_message=left(COALESCE(p_reason,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','deferred','retry_in_seconds',v_delay,'attempts',v_attempts);
END$$;


ALTER FUNCTION public.rpc_defer_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text, p_delay_seconds integer) OWNER TO postgres;

--
-- Name: rpc_delete_diagnostico_visita(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_delete_diagnostico_visita(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_registro_id uuid;
  v_status text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4: capacidade mínima de domínio (uniforme por identidade, sem leitura do recurso).
  IF NOT (
    public.has_role(v_uid, 'administrador'::app_role)
    OR public.has_role(v_uid, 'gestor'::app_role)
    OR public.has_role(v_uid, 'consultor_tecnico'::app_role)
    OR public.has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4-R: resolução ESCOPADA ao chamador — inexistente e alheio são indistinguíveis.
  SELECT r.id, r.status::text
    INTO v_registro_id, v_status
  FROM public.visita_diagnosticos d
  JOIN public.registros_consultor r ON r.id = d.registro_id
  WHERE d.id = p_id
    AND (
      COALESCE(public.can_manage_technical_visit(v_uid, r.id), false)
      OR COALESCE(r.created_by = v_uid, false)
      OR COALESCE(r.consultor_responsavel = v_uid, false)
      OR COALESCE(public.is_active_visit_participant(v_uid, r.id), false)
    );

  IF v_registro_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_status) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.visita_diagnosticos WHERE id = p_id;
END;
$$;


ALTER FUNCTION public.rpc_delete_diagnostico_visita(p_id uuid) OWNER TO postgres;

--
-- Name: rpc_delete_recomendacao_visita(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_delete_recomendacao_visita(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_registro_id uuid;
  v_status text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4: capacidade mínima de domínio (uniforme por identidade, sem leitura do recurso).
  IF NOT (
    public.has_role(v_uid, 'administrador'::app_role)
    OR public.has_role(v_uid, 'gestor'::app_role)
    OR public.has_role(v_uid, 'consultor_tecnico'::app_role)
    OR public.has_role(v_uid, 'tecnico_agronomo'::app_role)
  ) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L4-R: resolução ESCOPADA ao chamador — inexistente e alheio são indistinguíveis.
  SELECT r.id, r.status::text
    INTO v_registro_id, v_status
  FROM public.registros_consultor_recomendacoes rec
  JOIN public.registros_consultor r ON r.id = rec.registro_consultor_id
  WHERE rec.id = p_id
    AND (
      COALESCE(public.can_manage_technical_visit(v_uid, r.id), false)
      OR COALESCE(r.created_by = v_uid, false)
      OR COALESCE(r.consultor_responsavel = v_uid, false)
      OR COALESCE(public.is_active_visit_participant(v_uid, r.id), false)
    );

  IF v_registro_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT public.is_technical_visit_editable_status(v_status) THEN
    RAISE EXCEPTION 'visita_nao_editavel' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.registros_consultor_recomendacoes WHERE id = p_id;
END;
$$;


