--
-- Name: rpc_descartar_embalagem(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_descartar_embalagem(p_embalagem_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_st text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN RAISE EXCEPTION 'motivo obrigatório'; END IF;
  SELECT status INTO v_st FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st = 'entregue' THEN RAISE EXCEPTION 'embalagem já entregue'; END IF;
  UPDATE public.estoque_embalagens SET status='descartado', descartado_em=now(), descartado_por=v_uid, motivo_descarte=p_motivo WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, user_id, observacao)
    VALUES (p_embalagem_id, 'descarte', v_st, 'descartado', v_uid, p_motivo);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_DISCARDED', v_uid, p_motivo);
  RETURN jsonb_build_object('success', true);
END $$;


ALTER FUNCTION public.rpc_descartar_embalagem(p_embalagem_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_desvincular_etiqueta_entrega(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_desvincular_etiqueta_entrega(p_entrega_id uuid, p_etiqueta_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
    OR public.has_role(v_uid,'operador_onfarm'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;
  IF coalesce(length(trim(p_motivo)),0) < 3 THEN
    RAISE EXCEPTION 'Motivo obrigatório';
  END IF;

  UPDATE public.entrega_etiquetas
     SET ativo = false,
         desvinculado_em = now(),
         desvinculado_por = v_uid,
         motivo_desvinculacao = p_motivo
   WHERE entrega_id = p_entrega_id
     AND etiqueta_id = p_etiqueta_id
     AND ativo = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Vínculo não encontrado ou já desvinculado';
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, payload)
  VALUES (p_etiqueta_id, 'etiqueta_substituida', v_uid,
          jsonb_build_object('entrega_id', p_entrega_id, 'motivo', p_motivo, 'acao','desvinculada'));

  BEGIN
    INSERT INTO public.financial_audit_log(entity_type, entity_id, action, new_data, performed_by, reason)
    VALUES ('produto_etiqueta', p_etiqueta_id, 'LABEL_DELIVERY_UNLINKED',
            jsonb_build_object('entrega_id', p_entrega_id, 'motivo', p_motivo), v_uid, p_motivo);
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION public.rpc_desvincular_etiqueta_entrega(p_entrega_id uuid, p_etiqueta_id uuid, p_motivo text) OWNER TO postgres;

