    titulo text NOT NULL,
    tipo text NOT NULL,
    status text DEFAULT 'gerado'::text NOT NULL,
    periodo_inicio date,
    periodo_fim date,
    filtros jsonb DEFAULT '{}'::jsonb NOT NULL,
    resumo jsonb DEFAULT '{}'::jsonb NOT NULL,
    indicadores jsonb DEFAULT '{}'::jsonb NOT NULL,
