--
-- Name: rpc_fiscal_reserve_nfe_number_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_reserve_nfe_number_v1(p_invoice_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  inv public.fiscal_invoices%ROWTYPE;
  emit public.company_fiscal_settings%ROWTYPE;
  s public.fiscal_document_series%ROWTYPE;
  existing public.fiscal_number_reservations%ROWTYPE;
  n int; cnf text; key43 text; dv int; full_key text; cuf text;
BEGIN
  PERFORM public.h15_require_staff();
  PERFORM public.h15_require_invoice(p_invoice_id);

  IF NOT public.fn_fiscal_can_operate() THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: perfil sem permissao para reservar numeracao.';
  END IF;
  IF nullif(btrim(coalesce(p_idempotency_key,'')),'') IS NULL THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_KEY_REQUIRED: informe uma chave de idempotencia.';
  END IF;

  -- F3.1-R1: gate de ambiente avaliado ANTES de qualquer leitura/efeito, fail-closed.
  PERFORM public.fn_fiscal_assert_environment_homologation();
  IF p_invoice_id IS NULL THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: documento nao informado.';
  END IF;

  SELECT * INTO inv FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_INVOICE_NOT_FOUND: %', p_invoice_id; END IF;

  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
              WHERE r.idempotency_key = p_idempotency_key
                AND r.fiscal_invoice_id <> p_invoice_id) THEN
    RAISE EXCEPTION 'FISCAL_IDEMPOTENCY_SCOPE_MISMATCH: chave de idempotencia ja utilizada por outro documento fiscal.'
      USING HINT = 'Gere uma chave exclusiva por documento. Reservas nunca sao compartilhadas entre documentos.';
  END IF;

  SELECT * INTO existing FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) fiscal_number_reservations
   WHERE fiscal_invoice_id = p_invoice_id AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    RETURN jsonb_build_object('reservationId', existing.id, 'number', existing.number,
      'series', (SELECT series FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE id = existing.series_id),
      'accessKey', existing.access_key, 'checkDigit', existing.check_digit,
      'tpEmis', existing.tp_emis, 'status', existing.status, 'idempotentReplay', true);
  END IF;

  IF inv.status <> 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_INVOICE_NOT_DRAFT: reserva permitida apenas em rascunho (status=%)', inv.status;
  END IF;
  IF coalesce(inv.tp_emis,1) <> 1 THEN
    RAISE EXCEPTION 'FISCAL_TPEMIS_UNSUPPORTED: apenas emissao normal (tpEmis=1) esta habilitada nesta fase.';
  END IF;
  IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
             WHERE r.fiscal_invoice_id = p_invoice_id AND r.status = 'RESERVED') THEN
    RAISE EXCEPTION 'FISCAL_NUMBER_ALREADY_RESERVED: documento ja possui reserva ativa.';
  END IF;
  IF inv.tax_snapshot IS NULL OR NOT (inv.tax_snapshot ? 'engineVersion') THEN
    RAISE EXCEPTION 'FISCAL_CALCULATION_REQUIRED: calcule os tributos antes de reservar numeracao.';
  END IF;

  IF NOT ((public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'eligible')::boolean THEN
    RAISE EXCEPTION 'FISCAL_NOT_ELIGIBLE: %',
      (public.fn_fiscal_invoice_eligibility(inv.source_type, inv.source_id))->>'reasons';
  END IF;

  -- F3.1: devedor B2B x destinatario reavaliado na reserva.
  PERFORM public.fn_fiscal_assert_debtor_recipient(p_invoice_id);

  SELECT * INTO emit FROM (SELECT * FROM public.company_fiscal_settings WHERE id = (SELECT company_settings_id FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE id=p_invoice_id) AND public.h15_company_access(id)) company_fiscal_settings WHERE is_active ORDER BY updated_at DESC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_EMITTER_NOT_CONFIGURED: emitente nao cadastrado.'; END IF;
  IF coalesce(emit.nfe_environment_code,'2') = '1' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_BLOCKED: ambiente de producao (tpAmb=1) bloqueado na fase F3; teto READY_HOMOLOGATION.';
  END IF;
  IF emit.nfe_readiness_status <> 'READY_HOMOLOGATION' THEN
    RAISE EXCEPTION 'FISCAL_EMITTER_NOT_READY: emitente com pendencias %', emit.nfe_readiness_pendencies;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('fiscal_series:' || emit.id::text || ':' ||
          coalesce(emit.nfe_series_number,0)::text || ':' || coalesce(emit.nfe_environment_code,'2')));

  SELECT * INTO s FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series
   WHERE company_id = emit.id AND document_model = '55'
     AND series = emit.nfe_series_number AND environment_code = emit.nfe_environment_code
   FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.fiscal_document_series (company_id, series, environment_code, created_by)
    VALUES (emit.id, emit.nfe_series_number, emit.nfe_environment_code, auth.uid())
    RETURNING * INTO s;
    SELECT * INTO s FROM (SELECT * FROM public.fiscal_document_series WHERE public.h15_company_access(company_id)) fiscal_document_series WHERE id = s.id FOR UPDATE;
  END IF;
  IF s.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'FISCAL_SERIES_BLOCKED: serie % bloqueada.', s.series;
  END IF;

  n := s.current_number + 1;
  IF n > 999999999 THEN RAISE EXCEPTION 'FISCAL_SERIES_EXHAUSTED: serie % esgotada.', s.series; END IF;

  cnf := lpad(((get_byte(extensions.gen_random_bytes(4),0)::bigint << 24
              | get_byte(extensions.gen_random_bytes(4),0)::bigint << 16
              | get_byte(extensions.gen_random_bytes(4),0)::bigint << 8
              | get_byte(extensions.gen_random_bytes(4),0)::bigint) % 100000000)::text, 8, '0');

  cuf := public.fn_fiscal_uf_ibge_code(emit.state);
  key43 := cuf
        || to_char(coalesce(inv.issue_date, current_date), 'YYMM')
        || public.fn_fiscal_digits(emit.cnpj)
        || '55'
        || lpad(s.series::text, 3, '0')
        || lpad(n::text, 9, '0')
        || coalesce(inv.tp_emis,1)::text
        || cnf;
  dv := public.fn_fiscal_access_key_dv(key43);
  full_key := key43 || dv::text;

  UPDATE public.fiscal_document_series SET current_number = n, updated_at = now() WHERE id = s.id;

  INSERT INTO public.fiscal_number_reservations
    (series_id, number, cnf, access_key, check_digit, status, fiscal_invoice_id,
     idempotency_key, reserved_by, tp_emis)
  VALUES (s.id, n, cnf, full_key, dv, 'RESERVED', p_invoice_id,
          p_idempotency_key, auth.uid(), coalesce(inv.tp_emis,1));

  UPDATE public.fiscal_invoices
     SET series = s.series::text, invoice_number = n::text, access_key = full_key, updated_at = now()
   WHERE id = p_invoice_id;

  RETURN jsonb_build_object('number', n, 'series', s.series, 'accessKey', full_key,
                            'checkDigit', dv, 'tpEmis', coalesce(inv.tp_emis,1),
                            'status','RESERVED', 'idempotentReplay', false);
END $$;


ALTER FUNCTION public.rpc_fiscal_reserve_nfe_number_v1(p_invoice_id uuid, p_idempotency_key text) OWNER TO postgres;

--
-- Name: rpc_fiscal_rule_sod_override(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_rule_sod_override(p_scope text, p_target_id uuid, p_justification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id uuid;
BEGIN
  IF NOT public.has_role(auth.uid(),'administrador'::app_role) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN: somente administrador concede override de segregacao.';
  END IF;
  IF p_scope NOT IN ('TAX_RULE','OPERATION_POLICY') THEN
    RAISE EXCEPTION 'FISCAL_SOD_SCOPE_INVALID: %', p_scope;
  END IF;
  IF length(btrim(coalesce(p_justification,''))) < 40 THEN
    RAISE EXCEPTION 'FISCAL_SOD_JUSTIFICATION_REQUIRED: justificativa com pelo menos 40 caracteres.';
  END IF;
  INSERT INTO public.fiscal_rule_sod_overrides (scope, target_id, justification, granted_by)
  VALUES (p_scope, p_target_id, btrim(p_justification), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('overrideId', v_id, 'scope', p_scope, 'targetId', p_target_id);
END $$;


ALTER FUNCTION public.rpc_fiscal_rule_sod_override(p_scope text, p_target_id uuid, p_justification text) OWNER TO postgres;

--
-- Name: rpc_fiscal_sefaz_transmission_status_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_sefaz_transmission_status_v1(_invoice_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE v_items jsonb;
BEGIN
  PERFORM public.h15_require_staff();
  IF _invoice_id IS NOT NULL THEN PERFORM public.h15_require_invoice(_invoice_id); END IF;

  IF NOT public.fn_fiscal_can_read_internal(auth.uid()) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN';
  END IF;

  SELECT coalesce(jsonb_agg(x ORDER BY x->>'createdAt' DESC), '[]'::jsonb) INTO v_items
  FROM (
    SELECT jsonb_build_object(
      'transmissionId', t.id, 'service', t.service, 'state', t.state,
      'outcome', t.outcome,
      'invoiceId', t.fiscal_invoice_id, 'xmlRunId', t.xml_run_id,
      'eventId', t.fiscal_event_id,
      'environmentCode', t.environment_code, 'endpointHost', t.endpoint_host,
      'cStat', t.c_stat, 'xMotivo', t.x_motivo, 'chNFe', t.ch_nfe,
      'nProt', t.n_prot, 'nRec', t.n_rec, 'dhRecbto', t.dh_recbto,
      'errorCode', t.error_code, 'attempt', t.attempt,
      'correlationId', t.correlation_id,
      'createdAt', t.created_at, 'completedAt', t.completed_at) AS x
    FROM (SELECT * FROM public.fiscal_sefaz_transmissions WHERE public.h15_invoice_access(fiscal_invoice_id)) t
    WHERE (_invoice_id IS NULL OR t.fiscal_invoice_id = _invoice_id)
    ORDER BY t.created_at DESC
    LIMIT 50
  ) s;

  RETURN jsonb_build_object('ceiling', 'HOMOLOGATION', 'environmentCode', '2',
                            'items', v_items);
END $$;


ALTER FUNCTION public.rpc_fiscal_sefaz_transmission_status_v1(_invoice_id uuid) OWNER TO postgres;

--
-- Name: rpc_fiscal_sefaz_transmit_begin_v1(text, text, text, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_sefaz_transmit_begin_v1(_service text, _idempotency_key text, _request_fingerprint text, _endpoint_url text, _invoice_id uuid DEFAULT NULL::uuid, _xml_run_id uuid DEFAULT NULL::uuid, _actor uuid DEFAULT NULL::uuid, _event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_ref       text;
  v_prod      boolean;
  v_tpamb     text;
  v_host      text;
  v_run       public.fiscal_xml_runs;
  v_ev        record;
  v_invoice   uuid := _invoice_id;
  v_existing  public.fiscal_sefaz_transmissions;
  v_row       public.fiscal_sefaz_transmissions;
BEGIN
  IF coalesce(btrim(_idempotency_key), '') = '' OR length(_idempotency_key) > 200 THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_IDEMPOTENCY_INVALID';
  END IF;
  IF coalesce(btrim(_request_fingerprint), '') = '' THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_FINGERPRINT_REQUIRED';
  END IF;

  SELECT project_ref, production_emission_allowed INTO v_ref, v_prod
    FROM public.fiscal_environment_marker LIMIT 1;
  IF v_ref IS DISTINCT FROM 'swzpzcwiasxmjutrmvkm' OR coalesce(v_prod, true) THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  SELECT coalesce(nfe_environment_code, '') INTO v_tpamb
    FROM public.company_fiscal_settings WHERE is_active LIMIT 1;
  IF v_tpamb IS DISTINCT FROM '2' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  v_host := split_part(split_part(_endpoint_url, '://', 2), '/', 1);
  IF _endpoint_url NOT LIKE 'https://hnfe.fazenda.mg.gov.br/%'
     OR v_host <> 'hnfe.fazenda.mg.gov.br' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  -- H7G-001: na autorização, o invoice é DERIVADO do XML run. O parâmetro do
  -- chamador nunca é autoridade; divergência é bloqueio duro.
  IF _service = 'NFeAutorizacao4' THEN
    IF _xml_run_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_RUN_REQUIRED'; END IF;
    SELECT * INTO v_run FROM public.fiscal_xml_runs WHERE id = _xml_run_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SEFAZ_RUN_NOT_FOUND'; END IF;
    IF v_run.state IS DISTINCT FROM 'SIGNED' OR coalesce(v_run.signed_path, '') = '' THEN
      RAISE EXCEPTION 'SEFAZ_DOCUMENT_NOT_SIGNED';
    END IF;
    IF coalesce(v_run.environment_code, '') <> '2' THEN
      RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
    END IF;
    IF coalesce(v_run.access_key, '') !~ '^[0-9]{44}$' THEN
      RAISE EXCEPTION 'SEFAZ_ACCESS_KEY_INVALID';
    END IF;
    IF v_run.fiscal_invoice_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_RUN_INVOICE_MISSING'; END IF;
    IF _invoice_id IS NOT NULL AND _invoice_id IS DISTINCT FROM v_run.fiscal_invoice_id THEN
      RAISE EXCEPTION 'SEFAZ_INVOICE_RUN_MISMATCH';
    END IF;
    v_invoice := v_run.fiscal_invoice_id;
  END IF;

  -- H7G-002: no evento, invoice e chave vêm do evento fiscal canônico.
  IF _service = 'NFeRecepcaoEvento4' THEN
    IF _event_id IS NULL THEN RAISE EXCEPTION 'SEFAZ_EVENT_REQUIRED'; END IF;
    SELECT * INTO v_ev FROM public.v_fiscal_sefaz_event_state WHERE event_id = _event_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'SEFAZ_EVENT_NOT_FOUND'; END IF;
    IF v_ev.state <> 'SIGNED' THEN RAISE EXCEPTION 'SEFAZ_EVENT_NOT_SIGNED'; END IF;
    IF _invoice_id IS NOT NULL AND _invoice_id IS DISTINCT FROM v_ev.fiscal_invoice_id THEN
      RAISE EXCEPTION 'SEFAZ_EVENT_INVOICE_MISMATCH';
    END IF;
    v_invoice := v_ev.fiscal_invoice_id;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('fiscal_sefaz_tx:' || _idempotency_key, 0));

  SELECT * INTO v_existing FROM public.fiscal_sefaz_transmissions
   WHERE idempotency_key = _idempotency_key;

  IF FOUND THEN
    IF v_existing.request_fingerprint IS DISTINCT FROM _request_fingerprint THEN
      RAISE EXCEPTION 'FISCAL_TRANSMISSION_IDEMPOTENCY_MISMATCH';
    END IF;
    RETURN jsonb_build_object(
      'transmissionId', v_existing.id, 'state', v_existing.state,
      'outcome', v_existing.outcome,
      'service', v_existing.service, 'correlationId', v_existing.correlation_id,
      'invoiceId', v_existing.fiscal_invoice_id, 'eventId', v_existing.fiscal_event_id,
      'cStat', v_existing.c_stat, 'xMotivo', v_existing.x_motivo,
      'chNFe', v_existing.ch_nfe, 'nProt', v_existing.n_prot,
      'idempotentReplay', true);
  END IF;

  -- Documento já autorizado nunca é reenviado (invoice canônico).
  IF v_invoice IS NOT NULL AND _service IN ('NFeAutorizacao4','NFeRetAutorizacao4') THEN
    SELECT * INTO v_existing FROM public.fiscal_sefaz_transmissions
     WHERE fiscal_invoice_id = v_invoice
       AND state = 'SUCCEEDED'
       AND outcome = 'AUTHORIZED'
     ORDER BY created_at DESC LIMIT 1;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'transmissionId', v_existing.id, 'state', v_existing.state,
        'outcome', v_existing.outcome,
        'service', v_existing.service, 'correlationId', v_existing.correlation_id,
        'invoiceId', v_existing.fiscal_invoice_id,
        'cStat', v_existing.c_stat, 'xMotivo', v_existing.x_motivo,
        'chNFe', v_existing.ch_nfe, 'nProt', v_existing.n_prot,
        'alreadyAuthorized', true, 'idempotentReplay', true);
    END IF;
  END IF;

  INSERT INTO public.fiscal_sefaz_transmissions (
    fiscal_invoice_id, xml_run_id, fiscal_event_id, service, environment_code,
    endpoint_host, endpoint_url, idempotency_key, request_fingerprint,
    state, outcome, attempt, created_by)
  VALUES (v_invoice, _xml_run_id, _event_id, _service, '2',
          v_host, _endpoint_url, _idempotency_key, _request_fingerprint,
          'PENDING', 'PENDING', 1, _actor)
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'transmissionId', v_row.id, 'state', v_row.state, 'outcome', v_row.outcome,
    'service', v_row.service, 'correlationId', v_row.correlation_id,
    'invoiceId', v_row.fiscal_invoice_id, 'eventId', v_row.fiscal_event_id,
    'idempotentReplay', false);
END $_$;


ALTER FUNCTION public.rpc_fiscal_sefaz_transmit_begin_v1(_service text, _idempotency_key text, _request_fingerprint text, _endpoint_url text, _invoice_id uuid, _xml_run_id uuid, _actor uuid, _event_id uuid) OWNER TO postgres;

--
-- Name: rpc_fiscal_sefaz_transmit_record_v1(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_sefaz_transmit_record_v1(_transmission_id uuid, _state text, _patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row     public.fiscal_sefaz_transmissions;
  v_cur     public.fiscal_sefaz_transmissions;
  v_cstat   text;
  v_prot    text;
  v_outcome text;
  v_close_error text := NULL;
BEGIN
  IF _state NOT IN ('SENT','SUCCEEDED','FAILED','BLOCKED') THEN
    RAISE EXCEPTION 'FISCAL_TRANSMISSION_STATE_INVALID';
  END IF;

  SELECT * INTO v_cur FROM public.fiscal_sefaz_transmissions WHERE id = _transmission_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_TRANSMISSION_NOT_FOUND'; END IF;

  v_cstat := coalesce(_patch->>'protocolCStat', _patch->>'cStat', v_cur.c_stat);
  v_prot  := coalesce(_patch->>'nProt', v_cur.n_prot);

  IF _state IN ('FAILED','BLOCKED') THEN
    v_outcome := 'TRANSPORT_ERROR';
  ELSIF _state = 'SENT' THEN
    v_outcome := 'PENDING';
  ELSIF v_cstat IN ('100','150') AND v_prot IS NOT NULL THEN
    v_outcome := 'AUTHORIZED';
  ELSIF v_cstat IN ('135','136','155') THEN
    v_outcome := 'EVENT_REGISTERED';
  ELSIF v_cstat IN ('103','105','104','106','107','108','109','111','128') THEN
    v_outcome := CASE WHEN v_cur.service = 'NFeStatusServico4'
                      THEN 'SERVICE_INFO' ELSE 'PROCESSING' END;
  ELSE
    v_outcome := 'REJECTED';
  END IF;

  UPDATE public.fiscal_sefaz_transmissions SET
    state            = _state,
    outcome          = v_outcome,
    c_stat           = coalesce(_patch->>'cStat', c_stat),
    x_motivo         = coalesce(_patch->>'xMotivo', x_motivo),
    ch_nfe           = coalesce(_patch->>'chNFe', ch_nfe),
    n_prot           = coalesce(_patch->>'nProt', n_prot),
    n_rec            = coalesce(_patch->>'nRec', n_rec),
    ambiente_retorno = coalesce(_patch->>'tpAmb', ambiente_retorno),
    dh_recbto        = coalesce((_patch->>'dhRecbto')::timestamptz, dh_recbto),
    error_code       = coalesce(_patch->>'errorCode', error_code),
    response_summary = coalesce(_patch->'responseSummary', response_summary),
    completed_at     = CASE WHEN _state IN ('SUCCEEDED','FAILED','BLOCKED')
                            THEN now() ELSE completed_at END
  WHERE id = _transmission_id
  RETURNING * INTO v_row;

  IF v_row.ambiente_retorno IS NOT NULL AND v_row.ambiente_retorno <> '2' THEN
    RAISE EXCEPTION 'FISCAL_PRODUCTION_ENDPOINT_BLOCKED';
  END IF;

  IF v_row.service = 'NFeRecepcaoEvento4' AND v_row.fiscal_event_id IS NOT NULL
     AND _state = 'SUCCEEDED' AND v_cstat IS NOT NULL THEN
    BEGIN
      PERFORM public.rpc_fiscal_event_sefaz_reconcile_v1(
        v_row.fiscal_event_id, v_row.id, v_cstat,
        coalesce(_patch->>'xMotivo', ''), v_row.n_prot, v_row.dh_recbto);
    EXCEPTION WHEN OTHERS THEN
      v_close_error := 'FISCAL_EVENT_RECONCILIATION_PENDING';
    END;
  END IF;

  -- H13: o fechamento documental nao pode descartar o retorno ja recebido.
  IF v_row.outcome = 'AUTHORIZED' AND v_row.fiscal_invoice_id IS NOT NULL
     AND v_row.ch_nfe IS NOT NULL AND v_row.n_prot IS NOT NULL THEN
    BEGIN
      PERFORM public.rpc_fiscal_invoice_apply_authorization_v1(
        v_row.fiscal_invoice_id, v_row.ch_nfe, v_row.n_prot, v_row.dh_recbto,
        v_row.c_stat, v_row.x_motivo, v_row.id);
    EXCEPTION WHEN OTHERS THEN
      v_close_error := 'FISCAL_AUTHORIZATION_CLOSE_PENDING';
    END;
  END IF;

  IF v_close_error IS NOT NULL THEN
    UPDATE public.fiscal_sefaz_transmissions
       SET error_code = v_close_error
     WHERE id = _transmission_id
    RETURNING * INTO v_row;
  END IF;

  RETURN jsonb_build_object(
    'transmissionId', v_row.id, 'state', v_row.state, 'outcome', v_row.outcome,
    'cStat', v_row.c_stat, 'xMotivo', v_row.x_motivo,
    'chNFe', v_row.ch_nfe, 'nProt', v_row.n_prot, 'nRec', v_row.n_rec,
    'reconciliationPending', v_close_error IS NOT NULL,
    'reconciliationCode', v_close_error);
END $$;


ALTER FUNCTION public.rpc_fiscal_sefaz_transmit_record_v1(_transmission_id uuid, _state text, _patch jsonb) OWNER TO postgres;

--
-- Name: rpc_fiscal_service_ibs_cbs_get(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_service_ibs_cbs_get(p_service_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_cfg jsonb; v_rev text;
BEGIN
  IF NOT public._fiscal_rtc_can_read(v_uid) THEN
    RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT COALESCE(ibs_cbs_configuration,'{}'::jsonb), updated_at::text
    INTO v_cfg, v_rev
    FROM public.service_fiscal_profiles WHERE service_id = p_service_id LIMIT 1;
  RETURN jsonb_build_object(
    'configuration', COALESCE(v_cfg,'{}'::jsonb),
    'revision', COALESCE(v_rev,''),
    'exists', v_rev IS NOT NULL);
END; $$;


ALTER FUNCTION public.rpc_fiscal_service_ibs_cbs_get(p_service_id uuid) OWNER TO postgres;

--
-- Name: rpc_fiscal_service_ibs_cbs_save(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_fiscal_service_ibs_cbs_save(p_service_id uuid, payload jsonb, expected_revision text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_id uuid; v_stamp timestamptz; v_new text; v_count integer;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'FISCAL_UNAUTHENTICATED' USING ERRCODE='42501'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_GATE_UNAVAILABLE' USING ERRCODE='55000'; END IF;
 IF NOT (platform_private.platform_actor_access_ready(v_uid) AND public.is_platform_superadmin(v_uid)) THEN RAISE EXCEPTION 'FISCAL_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM public._fiscal_rtc_assert_payload(payload,'item');
 SELECT count(*) INTO v_count FROM public.service_fiscal_profiles WHERE service_id=p_service_id AND is_active IS TRUE;
 IF v_count=0 THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF v_count<>1 THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 SELECT id,updated_at INTO v_id,v_stamp FROM public.service_fiscal_profiles WHERE service_id=p_service_id AND is_active IS TRUE FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_ITEM_NOT_FOUND' USING ERRCODE='PT404'; END IF;
 IF expected_revision IS NULL OR expected_revision IS DISTINCT FROM v_stamp::text THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 UPDATE public.service_fiscal_profiles SET ibs_cbs_configuration=payload,updated_at=greatest(clock_timestamp(),v_stamp+interval '1 microsecond'),updated_by=v_uid
 WHERE id=v_id AND is_active IS TRUE AND updated_at=v_stamp RETURNING updated_at::text INTO v_new;
 IF NOT FOUND THEN RAISE EXCEPTION 'FISCAL_CONFLICT' USING ERRCODE='PT409'; END IF;
 RETURN jsonb_build_object('configuration',payload,'revision',v_new);
END; $$;


ALTER FUNCTION public.rpc_fiscal_service_ibs_cbs_save(p_service_id uuid, payload jsonb, expected_revision text) OWNER TO postgres;

