--
-- Name: rpc_listar_atendimentos_tecnicos_v1(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_listar_atendimentos_tecnicos_v1(p_aba text DEFAULT 'todos'::text, p_search text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_tech boolean;
  v_page integer := GREATEST(COALESCE(p_page,1),1);
  v_size integer := LEAST(GREATEST(COALESCE(p_page_size,20),1),100);
  v_aba text := lower(COALESCE(NULLIF(btrim(p_aba),''),'todos'));
  v_q text := NULLIF(btrim(COALESCE(p_search,'')),'');
  v_total bigint := 0;
  v_items jsonb := '[]'::jsonb;
  c_abas constant text[] := ARRAY['todos','demandas','ocorrencias','andamento','aguardando','monitoramento','concluidos'];
BEGIN
  IF NOT (v_aba = ANY (c_abas)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_tab',
      'items','[]'::jsonb,'total',0,'page',v_page,'page_size',v_size,'has_more',false);
  END IF;

  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error','unauthenticated',
      'items','[]'::jsonb,'total',0,'page',v_page,'page_size',v_size,'has_more',false);
  END IF;

  v_is_admin := public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor');
  v_is_tech := EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid AND ur.role IN ('tecnico_agronomo','consultor_tecnico')
  );

  IF NOT (v_is_admin OR v_is_tech) THEN
    RETURN jsonb_build_object('ok', false, 'error','forbidden',
      'items','[]'::jsonb,'total',0,'page',v_page,'page_size',v_size,'has_more',false);
  END IF;

  WITH base AS (
    SELECT
      'visita'::text AS kind,
      r.id,
      r.codigo_visita AS codigo,
      COALESCE(NULLIF(r.objetivo_visita,''), NULLIF(r.problema_principal,''), 'Atendimento técnico') AS titulo,
      r.status::text AS status,
      r.origem_atendimento AS origem,
      c.nome AS cliente_nome,
      f.nome AS fazenda_nome,
      t.nome AS talhao_nome,
      cu.nome AS cultura_nome,
      r.tipo_visita::text AS tipo,
      r.urgencia::text AS urgencia,
      pr.nome AS responsavel_nome,
      r.data_proxima_visita::timestamptz AS data_prevista,
      CASE
        WHEN r.status = 'rascunho' AND r.cultura_id IS NULL THEN 'Informar cultura'
        WHEN r.status IN ('rascunho','em_andamento') THEN 'Continuar preenchimento'
        WHEN r.status = 'enviado_aprovacao' THEN 'Aguardando aprovação'
        WHEN r.status = 'reprovado' THEN 'Revisar e reenviar'
        WHEN r.status IN ('aprovado','convertido_os') AND r.data_proxima_visita IS NOT NULL THEN 'Retorno programado'
        ELSE 'Sem ação pendente'
      END AS proxima_acao,
      COALESCE(r.data_vistoria::timestamptz, r.created_at) AS data_ref,
      (r.status IN ('rascunho','em_andamento','reprovado')
        AND public.can_manage_technical_visit(v_uid, r.id)) AS can_edit,
      '/app/visita/' || r.id::text AS next_route,
      CASE
        WHEN r.status IN ('rascunho','em_andamento') THEN 'andamento'
        WHEN r.status IN ('enviado_aprovacao','reprovado') THEN 'aguardando'
        WHEN r.status IN ('aprovado','convertido_os') AND r.data_proxima_visita IS NOT NULL THEN 'monitoramento'
        ELSE 'concluidos'
      END AS bucket
    FROM public.registros_consultor r
    LEFT JOIN public.clientes c  ON c.id = r.cliente_id
    LEFT JOIN public.fazendas f  ON f.id = r.fazenda_id
    LEFT JOIN public.talhoes  t  ON t.id = r.talhao_id
    LEFT JOIN public.culturas cu ON cu.id = r.cultura_id
    LEFT JOIN public.profiles pr ON pr.user_id = r.consultor_responsavel
    WHERE public.can_view_technical_visit(v_uid, r.id)
      AND (v_q IS NULL OR (
        COALESCE(r.codigo_visita,'') ILIKE '%'||v_q||'%'
        OR COALESCE(r.objetivo_visita,'') ILIKE '%'||v_q||'%'
        OR COALESCE(r.problema_principal,'') ILIKE '%'||v_q||'%'
        OR COALESCE(c.nome,'') ILIKE '%'||v_q||'%'
        OR COALESCE(f.nome,'') ILIKE '%'||v_q||'%'
      ))

    UNION ALL

    SELECT
      'demanda'::text,
      s.id,
      s.numero_solicitacao,
      COALESCE(NULLIF(s.descricao,''), s.tipo_demanda, 'Demanda do produtor'),
      s.status,
      'solicitacao_produtor',
      c.nome, f.nome, t.nome, NULL::text,
      s.tipo_demanda,
      s.urgencia,
      pr.nome,
      s.data_prevista_atendimento,
      'Abrir atendimento'::text,
      COALESCE(s.data_prevista_atendimento, s.created_at),
      true,
      '/app/atendimentos?demanda=' || s.id::text,
      'demandas'
    FROM public.portal_solicitacoes s
    LEFT JOIN public.clientes c  ON c.id = s.cliente_id
    LEFT JOIN public.fazendas f  ON f.id = s.fazenda_id
    LEFT JOIN public.talhoes  t  ON t.id = s.talhao_id
    LEFT JOIN public.profiles pr ON pr.user_id = s.consultor_atribuido
    WHERE s.status NOT IN ('concluida','cancelada')
      AND NOT EXISTS (SELECT 1 FROM public.registros_consultor r WHERE r.solicitacao_id = s.id AND public.can_view_technical_visit(v_uid,r.id))
      AND public.can_user_access_solicitacao(s.id)
      AND (v_is_admin OR (s.consultor_atribuido = v_uid AND public.technical_client_link(v_uid,s.cliente_id,ARRAY['execute','manage'])))
      AND (v_q IS NULL OR (
        COALESCE(s.numero_solicitacao,'') ILIKE '%'||v_q||'%'
        OR COALESCE(s.descricao,'') ILIKE '%'||v_q||'%'
        OR COALESCE(c.nome,'') ILIKE '%'||v_q||'%'
        OR COALESCE(f.nome,'') ILIKE '%'||v_q||'%'
      ))
  ),
  filtrado AS (
    SELECT * FROM base b
     WHERE v_aba = 'todos'
        OR (v_aba = 'ocorrencias' AND b.kind = 'visita' AND b.origem = 'ocorrencia_campo')
        OR (v_aba <> 'ocorrencias' AND v_aba = b.bucket)
  ),
  contagem AS (SELECT count(*) AS n FROM filtrado),
  pagina AS (
    SELECT * FROM filtrado ORDER BY data_ref DESC NULLS LAST LIMIT v_size OFFSET (v_page-1)*v_size
  )
  SELECT (SELECT n FROM contagem),
         COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY p.data_ref DESC NULLS LAST) FROM pagina p), '[]'::jsonb)
    INTO v_total, v_items;

  RETURN jsonb_build_object(
    'ok', true,
    'items', v_items,
    'total', v_total,
    'page', v_page,
    'page_size', v_size,
    'has_more', (v_page * v_size) < v_total
  );
END;
$$;


ALTER FUNCTION public.rpc_listar_atendimentos_tecnicos_v1(p_aba text, p_search text, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: rpc_listar_visitas_tecnicas_v1(text, text[], date, date, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_listar_visitas_tecnicas_v1(p_search text DEFAULT NULL::text, p_status text[] DEFAULT NULL::text[], p_de date DEFAULT NULL::date, p_ate date DEFAULT NULL::date, p_cliente_id uuid DEFAULT NULL::uuid, p_fazenda_id uuid DEFAULT NULL::uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_page integer := GREATEST(COALESCE(p_page, 1), 1);
  v_size integer := LEAST(GREATEST(COALESCE(p_page_size, 25), 1), 100);
  v_search text := NULLIF(btrim(COALESCE(p_search, '')), '');
  v_total bigint := 0;
  v_items jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  WITH base AS (
    SELECT r.*
      FROM public.registros_consultor r
     WHERE public.can_view_technical_visit(v_uid, r.id)
       AND (p_status IS NULL OR array_length(p_status, 1) IS NULL OR r.status::text = ANY (p_status))
       AND (p_cliente_id IS NULL OR r.cliente_id = p_cliente_id)
       AND (p_fazenda_id IS NULL OR r.fazenda_id = p_fazenda_id)
       AND (p_de IS NULL OR r.data_vistoria >= p_de)
       AND (p_ate IS NULL OR r.data_vistoria <= p_ate)
       AND (
         v_search IS NULL
         OR r.codigo_visita ILIKE '%' || v_search || '%'
         OR r.objetivo_visita ILIKE '%' || v_search || '%'
         OR r.problema_principal ILIKE '%' || v_search || '%'
         OR EXISTS (SELECT 1 FROM public.clientes c WHERE c.id = r.cliente_id AND c.nome ILIKE '%' || v_search || '%')
         OR EXISTS (SELECT 1 FROM public.fazendas f WHERE f.id = r.fazenda_id AND f.nome ILIKE '%' || v_search || '%')
       )
  ), counted AS (
    SELECT count(*) AS total FROM base
  ), pagina AS (
    SELECT b.* FROM base b
     ORDER BY b.data_vistoria DESC NULLS LAST, b.created_at DESC
     LIMIT v_size OFFSET (v_page - 1) * v_size
  )
  SELECT (SELECT total FROM counted),
         COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
             'id', p.id,
             'codigo_visita', p.codigo_visita,
             'status', p.status,
             'data_vistoria', p.data_vistoria,
             'tipo_visita', p.tipo_visita,
             'objetivo_visita', p.objetivo_visita,
             'problema_principal', p.problema_principal,
             'categoria_problema', p.categoria_problema,
             'nivel_pressao', p.nivel_pressao,
             'urgencia', p.urgencia,
             'risco_produtivo', p.risco_produtivo,
             'necessidade_intervencao', p.necessidade_intervencao,
             'created_at', p.created_at,
             'cliente_id', p.cliente_id,
             'cliente_nome', (SELECT c.nome FROM public.clientes c WHERE c.id = p.cliente_id),
             'fazenda_id', p.fazenda_id,
             'fazenda_nome', (SELECT f.nome FROM public.fazendas f WHERE f.id = p.fazenda_id),
             'talhao_nome', (SELECT t.nome FROM public.talhoes t WHERE t.id = p.talhao_id),
             'can_edit', (public.can_manage_technical_visit(v_uid, p.id)
                          AND public.is_technical_visit_editable_status(p.status::text))
           ))
           FROM pagina p
         ), '[]'::jsonb)
    INTO v_total, v_items;

  RETURN jsonb_build_object(
    'items', v_items,
    'total', v_total,
    'page', v_page,
    'page_size', v_size,
    'has_more', (v_page * v_size) < v_total
  );
END;
$$;


ALTER FUNCTION public.rpc_listar_visitas_tecnicas_v1(p_search text, p_status text[], p_de date, p_ate date, p_cliente_id uuid, p_fazenda_id uuid, p_page integer, p_page_size integer) OWNER TO postgres;

--
-- Name: rpc_marcar_etiqueta_impressa(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_marcar_etiqueta_impressa(p_etiqueta_id uuid, p_motivo text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_status text;
  v_count integer;
  v_new_status text;
  v_event text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF NOT (
    public.has_role(v_uid,'administrador'::app_role)
    OR public.has_role(v_uid,'gestor'::app_role)
    OR public.has_role(v_uid,'producao'::app_role)
    OR public.has_role(v_uid,'operador_onfarm'::app_role)
    OR public.has_role(v_uid,'administrativo'::app_role)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para imprimir etiqueta';
  END IF;

  SELECT status, quantidade_impressoes INTO v_status, v_count
    FROM public.produto_etiquetas WHERE id = p_etiqueta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada'; END IF;
  IF v_status = 'cancelada' THEN RAISE EXCEPTION 'Etiqueta cancelada não pode ser impressa'; END IF;

  IF v_status = 'gerada' THEN
    v_new_status := 'impressa'; v_event := 'etiqueta_impressa';
    UPDATE public.produto_etiquetas
      SET status='impressa', impressa_em=now(), impressa_por=v_uid,
          quantidade_impressoes = quantidade_impressoes + 1
      WHERE id = p_etiqueta_id;
  ELSE
    IF p_motivo IS NULL OR length(trim(p_motivo)) < 3 THEN
      RAISE EXCEPTION 'Motivo obrigatório para reimpressão (mínimo 3 caracteres)';
    END IF;
    v_new_status := 'reimpressa'; v_event := 'etiqueta_reimpressa';
    UPDATE public.produto_etiquetas
      SET status='reimpressa', ultima_reimpressao_em=now(), ultima_reimpressao_por=v_uid,
          motivo_ultima_reimpressao = trim(p_motivo),
          quantidade_impressoes = quantidade_impressoes + 1
      WHERE id = p_etiqueta_id;
  END IF;

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, descricao, user_id, metadata)
    VALUES (p_etiqueta_id, v_event, NULLIF(trim(COALESCE(p_motivo,'')),''), v_uid,
            jsonb_build_object('quantidade_total', v_count+1, 'motivo', NULLIF(trim(COALESCE(p_motivo,'')),'')));

  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, reason)
    VALUES ('produto_etiqueta', p_etiqueta_id, upper(v_event), v_uid, NULLIF(trim(COALESCE(p_motivo,'')),''));

  RETURN jsonb_build_object('success', true, 'status', v_new_status, 'quantidade_impressoes', v_count+1);
END;
$$;


ALTER FUNCTION public.rpc_marcar_etiqueta_impressa(p_etiqueta_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_marcar_notificacao_enviada(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_marcar_notificacao_enviada(p_notificacao_id uuid, p_provider text, p_provider_message_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_is_service boolean := (current_setting('request.jwt.claims', true)::jsonb ->> 'role') = 'service_role';
BEGIN
  IF NOT v_is_service THEN
    RAISE EXCEPTION 'permission_denied';
  END IF;
  UPDATE public.alertas_notificacoes
     SET status = 'enviado',
         enviado_em = now(),
         provider = p_provider,
         provider_message_id = p_provider_message_id,
         erro = NULL
   WHERE id = p_notificacao_id;
END $$;


