--
-- Name: rpc_message_set_status(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_message_set_status(p_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE org uuid:=public.h15_actor_organization(); ctx jsonb; resource record; internal boolean; BEGIN
IF org IS NULL OR NOT platform_private.platform_actor_access_ready(auth.uid()) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
internal:=platform_private.b2b_internal_commercial_actor(); IF NOT internal THEN ctx:=platform_private.b2b_commercial_context(); IF ctx IS NULL OR ctx->>'role'<>'parceiro_b2b' OR ctx->>'mode'<>'commercial_owner' THEN RAISE EXCEPTION 'b2b_messages_unavailable' USING ERRCODE='42501'; END IF; END IF;
SELECT m.id,po.partner_id,pa.commercial_owner_organization_id,po.cliente_id INTO resource FROM public.partner_order_messages m JOIN public.partner_orders po ON po.id=m.order_id JOIN public.partner_accounts pa ON pa.id=po.partner_id WHERE m.id=p_id AND pa.ativo IS TRUE AND pa.deleted_at IS NULL FOR UPDATE OF m,po,pa;
IF resource.id IS NULL OR resource.commercial_owner_organization_id IS DISTINCT FROM org OR (NOT internal AND resource.partner_id IS DISTINCT FROM (ctx->>'partner_id')::uuid) OR (resource.cliente_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.clientes c WHERE c.id=resource.cliente_id AND c.organization_id=org)) THEN RAISE EXCEPTION 'permission_denied' USING ERRCODE='42501'; END IF;
IF p_status IS NULL OR p_status NOT IN ('nao_lida','lida','respondida','encerrada') THEN RAISE EXCEPTION 'invalid_status' USING ERRCODE='22023'; END IF;
UPDATE public.partner_order_messages SET status=p_status,status_updated_at=now() WHERE id=resource.id; END $$;


ALTER FUNCTION public.rpc_message_set_status(p_id uuid, p_status text) OWNER TO postgres;

--
-- Name: rpc_microorganism_regulatory_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_microorganism_regulatory_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v jsonb;
BEGIN
  IF NOT public.fn_regulatory_can_read() THEN
    RAISE EXCEPTION 'REGULATORY_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  SELECT coalesce(jsonb_agg(x ORDER BY x->>'codigo'),'[]'::jsonb) INTO v FROM (
    SELECT jsonb_build_object(
      'microorganism_id', m.id,
      'codigo', m.codigo,
      'nome', m.nome,
      'tipo', m.tipo,
      'ativo', m.ativo,
      'concentracao_label', m.concentracao_label,
      'facts', f.facts,
      'checklist_total', coalesce((f.facts->>'checklist_total')::int, 0),
      'checklist_confirmed', coalesce((f.facts->>'checklist_confirmed')::int, 0),
      'checklist_pending', coalesce(jsonb_array_length(coalesce(f.facts->'checklist_pending','[]'::jsonb)),0),
      'progress_pct', CASE WHEN coalesce((f.facts->>'checklist_total')::int,0) = 0 THEN 0
                           ELSE round(100.0 * (coalesce((f.facts->>'checklist_total')::int,0)
                                - jsonb_array_length(coalesce(f.facts->'checklist_pending','[]'::jsonb)))
                                / coalesce((f.facts->>'checklist_total')::int,1)) END,
      'dossier_status', coalesce(f.facts->>'status','NONE'),
      'profile_status', r.profile_status,
      'fiscally_ready', coalesce(r.fiscally_ready,false),
      'technical_ready', coalesce(r.minimally_classified,false),
      'regulatory_ready', coalesce(r.regulatory_ready,false),
      'quarantined', coalesce(r.quarantined,false),
      'pendencies', coalesce(r.pendencies,'[]'::jsonb),
      'not_applicable', coalesce(r.not_applicable,'[]'::jsonb)) AS x
    FROM public.microrganismos m
    LEFT JOIN public.v_microorganism_fiscal_readiness r ON r.microorganism_id = m.id
    CROSS JOIN LATERAL (SELECT public.fn_microorganism_regulatory_facts(m.id) AS facts) f
    WHERE m.ativo
  ) s;
  RETURN v;
END $$;


ALTER FUNCTION public.rpc_microorganism_regulatory_overview() OWNER TO postgres;

