--
-- Name: rpc_partner_commercial_history(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_partner_commercial_history(p_partner_id uuid, p_from date DEFAULT ((now())::date - 365), p_to date DEFAULT (now())::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb; top jsonb;
BEGIN
  IF NOT (
    public.has_role(auth.uid(),'administrador')
    OR public.has_role(auth.uid(),'gestor_comercial')
    OR (public.has_role(auth.uid(),'parceiro_b2b') AND public.get_user_partner_id() = p_partner_id)
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT COALESCE(jsonb_agg(t), '[]'::jsonb) INTO top FROM (
    SELECT poi.produto_nome_snapshot AS produto,
           SUM(poi.quantidade) AS quantidade,
           SUM(poi.subtotal) AS valor
    FROM public.partner_order_items poi
    JOIN public.partner_orders po ON po.id = poi.order_id
    WHERE po.partner_id = p_partner_id
      AND po.created_at::date BETWEEN p_from AND p_to
    GROUP BY poi.produto_nome_snapshot
    ORDER BY SUM(poi.subtotal) DESC
    LIMIT 10
  ) t;

  SELECT jsonb_build_object(
    'qtd_pedidos', COUNT(*),
    'valor_acumulado', COALESCE(SUM(total),0),
    'ticket_medio', COALESCE(AVG(total),0),
    'ultima_compra', MAX(created_at),
    'top_produtos', top
  ) INTO r
  FROM public.partner_orders
  WHERE partner_id = p_partner_id
    AND created_at::date BETWEEN p_from AND p_to;
  RETURN r;
END $$;


ALTER FUNCTION public.rpc_partner_commercial_history(p_partner_id uuid, p_from date, p_to date) OWNER TO postgres;

--
-- Name: rpc_partner_dashboard(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_partner_dashboard(p_partner_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pid uuid;
  r jsonb;
BEGIN
  v_pid := COALESCE(p_partner_id, public.get_user_partner_id());
  IF v_pid IS NULL THEN RAISE EXCEPTION 'no partner'; END IF;
  IF NOT (
    public.has_role(auth.uid(),'administrador')
    OR public.has_role(auth.uid(),'gestor_comercial')
    OR (public.has_role(auth.uid(),'parceiro_b2b') AND public.get_user_partner_id() = v_pid)
  ) THEN RAISE EXCEPTION 'forbidden'; END IF;

  SELECT jsonb_build_object(
    'em_andamento', COUNT(*) FILTER (WHERE status IN ('aprovado','em_producao','produzido','aguardando_entrega','em_separacao','enviado')),
    'entregues', COUNT(*) FILTER (WHERE status IN ('entregue','faturado')),
    'aguardando_aprovacao', COUNT(*) FILTER (WHERE status IN ('solicitado','em_analise_comercial','aguardando_aprovacao_credito')),
    'aguardando_ajuste', COUNT(*) FILTER (WHERE status::text='aguardando_ajuste_comercial'),
    'favoritos_count', (SELECT COUNT(*) FROM public.partner_order_templates t WHERE t.partner_id = v_pid AND t.favorito),
    'ultimas_mensagens', COALESCE((
      SELECT jsonb_agg(row_to_json(m)) FROM (
        SELECT pm.id, pm.order_id, pm.autor_tipo, pm.mensagem, pm.created_at
        FROM public.partner_order_messages pm
        JOIN public.partner_orders po ON po.id = pm.order_id
        WHERE po.partner_id = v_pid
        ORDER BY pm.created_at DESC
        LIMIT 5
      ) m
    ), '[]'::jsonb)
  ) INTO r
  FROM public.partner_orders
  WHERE partner_id = v_pid;
  RETURN r;
END $$;


ALTER FUNCTION public.rpc_partner_dashboard(p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_partner_message_counters(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_partner_message_counters(p_partner_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_partner uuid := COALESCE(p_partner_id, get_user_partner_id());
BEGIN
  IF NOT (public.has_role(auth.uid(), 'administrador'::public.app_role)
      or public.has_role(auth.uid(), 'gestor_comercial'::public.app_role)
      or (public.get_user_partner_id() is not null
          and (p_partner_id is null or p_partner_id = public.get_user_partner_id()))) THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  RETURN (
    SELECT jsonb_build_object(
      'nao_lidas', COUNT(*) FILTER (WHERE m.status = 'nao_lida'),
      'pendentes', COUNT(*) FILTER (WHERE m.status IN ('nao_lida','lida')),
      'respondidas', COUNT(*) FILTER (WHERE m.status = 'respondida'),
      'encerradas', COUNT(*) FILTER (WHERE m.status = 'encerrada')
    )
    FROM public.partner_order_messages m
    JOIN public.partner_orders po ON po.id = m.order_id
    WHERE (v_partner IS NULL OR po.partner_id = v_partner)
  );
END $$;


ALTER FUNCTION public.rpc_partner_message_counters(p_partner_id uuid) OWNER TO postgres;

--
-- Name: rpc_planejamento_publicar_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_planejamento_publicar_v1(p_planning_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid:=auth.uid(); v_pl public.production_planning%ROWTYPE;
 v_prev public.production_planning_publications%ROWTYPE; v_result jsonb; v_count int;
BEGIN
 IF v_uid IS NULL THEN RAISE EXCEPTION 'nao_autenticado' USING ERRCODE='42501'; END IF;
 IF NOT(public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'producao') OR public.has_role(v_uid,'gestor')) THEN RAISE EXCEPTION 'permissao_negada' USING ERRCODE='42501'; END IF;
 IF p_planning_id IS NULL THEN RAISE EXCEPTION 'planejamento_invalido' USING ERRCODE='22023'; END IF;
 IF p_idempotency_key IS NULL OR length(btrim(p_idempotency_key))<8 THEN RAISE EXCEPTION 'chave_idempotencia_obrigatoria' USING ERRCODE='22023'; END IF;
 -- Nunca devolver recibo de origem interna bloqueada, nem em replay.
 -- Escopo antes de status/recibo: ID inexistente e cross-tenant dão a mesma negação.
 IF public.h15_actor_organization() IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 SELECT pl.* INTO v_pl FROM public.production_planning pl
 WHERE pl.id=p_planning_id AND platform_private.lab_partner_order_authorized(pl.partner_order_id) FOR UPDATE;
 IF v_pl.id IS NULL THEN RAISE EXCEPTION 'LAB_PARTNER_SCOPE_DENIED' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.partner_orders WHERE id=v_pl.partner_order_id AND internal_origin_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'B2B_INTERNAL_DOWNSTREAM_UNVERIFIED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('planejamento_publicar:'||p_planning_id::text));
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE idempotency_key=btrim(p_idempotency_key);
 IF FOUND THEN
  IF v_prev.planning_id<>p_planning_id THEN RAISE EXCEPTION 'chave_idempotencia_conflitante' USING ERRCODE='23505'; END IF;
  RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado);
 END IF;
 SELECT * INTO v_prev FROM public.production_planning_publications WHERE planning_id=p_planning_id;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'replay',true,'planning_id',v_prev.planning_id,'os_created',v_prev.os_created,'resultado',v_prev.resultado); END IF;
 v_result:=public.publish_planning_to_lab(p_planning_id); v_count:=coalesce((v_result->>'os_created')::int,0);
 INSERT INTO public.production_planning_publications(planning_id,partner_order_id,idempotency_key,os_created,resultado,performed_by)
 VALUES(p_planning_id,v_pl.partner_order_id,btrim(p_idempotency_key),v_count,v_result,v_uid);
 RETURN jsonb_build_object('ok',true,'replay',false,'planning_id',p_planning_id,'os_created',v_count,'resultado',v_result);
END $$;


ALTER FUNCTION public.rpc_planejamento_publicar_v1(p_planning_id uuid, p_idempotency_key text) OWNER TO postgres;

