--
-- Name: rpc_reprovar_visita(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reprovar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, true);
  IF v_reg.status::text <> 'enviado_aprovacao' THEN
    RAISE EXCEPTION 'status_invalido' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.registros_consultor
     SET status = 'reprovado', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
  RETURNING version INTO v_new_version;
  INSERT INTO public.aprovacoes_tecnicas
    (registro_consultor_id, status_aprovacao, comentario_gestor, aprovado_por, data_aprovacao)
  VALUES (p_registro_id, 'reprovado', p_motivo, auth.uid(), now());
  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES (p_registro_id, v_reg.status::text, 'reprovado', p_motivo, auth.uid(), now());
  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, auth.uid(), 'recomendacao_reprovada', 'Visita reprovada. Motivo: ' || p_motivo);
  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'reprovado');
END
$$;


ALTER FUNCTION public.rpc_reprovar_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_reservar_embalagem_entrega(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_reservar_embalagem_entrega(p_embalagem_id uuid, p_entrega_id uuid, p_entrega_item_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_st text; v_val date; v_ent_st text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT status, validade_em INTO v_st, v_val FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st IS NULL THEN RAISE EXCEPTION 'embalagem inexistente'; END IF;
  IF v_st <> 'em_estoque' THEN RAISE EXCEPTION 'embalagem não está em estoque (status=%)', v_st; END IF;
  IF v_val IS NOT NULL AND v_val < CURRENT_DATE THEN RAISE EXCEPTION 'embalagem vencida'; END IF;
  SELECT status::text INTO v_ent_st FROM public.entregas WHERE id = p_entrega_id;
  IF v_ent_st IS NULL THEN RAISE EXCEPTION 'entrega inexistente'; END IF;
  IF v_ent_st = 'cancelada' THEN RAISE EXCEPTION 'entrega cancelada'; END IF;
  UPDATE public.estoque_embalagens
     SET status='reservado', entrega_id=p_entrega_id, entrega_item_id=p_entrega_item_id,
         reservado_em=now(), reservado_por=v_uid
   WHERE id = p_embalagem_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, status_anterior, status_novo, entrega_id, entrega_item_id, user_id)
    VALUES (p_embalagem_id, 'reserva_entrega', v_st, 'reservado', p_entrega_id, p_entrega_item_id, v_uid);
  PERFORM public.rpc_recalcular_separacao_entrega(p_entrega_id);
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_RESERVED', v_uid, jsonb_build_object('entrega_id', p_entrega_id));
  RETURN jsonb_build_object('success', true);
END $$;


ALTER FUNCTION public.rpc_reservar_embalagem_entrega(p_embalagem_id uuid, p_entrega_id uuid, p_entrega_item_id uuid) OWNER TO postgres;

--
-- Name: rpc_resolve_commercial_prices(jsonb, uuid, date, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_resolve_commercial_prices(p_items jsonb, p_plan_id uuid, p_ref_date date DEFAULT CURRENT_DATE, p_buyer jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := auth.uid(); v_partner uuid; s record;
  v_item jsonb; v_res jsonb; v_out jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required' USING ERRCODE='42501'; END IF;
  IF COALESCE(p_buyer->>'buyer_scope','partner') <> 'partner' OR NULLIF(p_buyer->>'customer_id','') IS NOT NULL THEN
    RAISE EXCEPTION 'PRODUCER_DIRECT_NOT_ENABLED' USING ERRCODE='P0001';
  END IF;
  IF public.has_role(v_uid,'parceiro_b2b'::app_role) AND NOT public.is_platform_superadmin(v_uid) THEN
    -- parceiro: o partner_id do cliente é ignorado; usa o vínculo do servidor.
    SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
    v_partner := s.user_partner;
  ELSE
    v_partner := NULLIF(p_buyer->>'partner_id','')::uuid;
    IF v_partner IS NULL AND NOT public.is_platform_superadmin(v_uid) THEN
      SELECT * INTO s FROM platform_private.b2b_actor_scope(v_uid);
      v_partner := s.org_partner;
    END IF;
  END IF;
  IF v_partner IS NULL THEN RAISE EXCEPTION 'buyer_required' USING ERRCODE='42501'; END IF;
  PERFORM platform_private.assert_b2b_partner_scope(v_uid, v_partner);

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items,'[]'::jsonb)) LOOP
    v_res := public.fn_resolve_commercial_price('partner', v_partner, NULL, p_plan_id,
      NULLIF(v_item->>'product_id','')::uuid, NULLIF(v_item->>'microrganismo_id','')::uuid,
      v_item->>'unit_type', NULLIF(v_item->>'volume_ml','')::numeric,
      COALESCE(p_ref_date, current_date), NULLIF(v_item->>'quantity','')::numeric);
    v_out := v_out || jsonb_build_array(v_res || jsonb_build_object('item_ref', v_item->>'item_ref'));
  END LOOP;
  RETURN jsonb_build_object('buyer_scope','partner','plan_id',p_plan_id,
                            'ref_date',COALESCE(p_ref_date,current_date),'items',v_out);
END $$;


ALTER FUNCTION public.rpc_resolve_commercial_prices(p_items jsonb, p_plan_id uuid, p_ref_date date, p_buyer jsonb) OWNER TO postgres;

--
-- Name: rpc_resolve_outbox_address(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_resolve_outbox_address(p_outbox_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  r public.comunicacao_outbox%rowtype; v_role text; v_email text;
  v_phone_raw text; v_phone text; v_ok boolean; v_hash text; v_redacted text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status NOT IN ('processing') THEN
    RETURN jsonb_build_object('ok',false,'outcome','skipped','reason','not_processing'); END IF;
  v_ok := public._comunicacao_can_deliver(r.recipient_user_id, r.recipient_cliente_id, r.canal);
  IF NOT v_ok THEN
    RETURN jsonb_build_object('ok',false,'outcome','skipped','reason','opt_out_or_unverified'); END IF;
  IF r.canal = 'in_app' THEN
    RETURN jsonb_build_object('ok',true,'canal','in_app',
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id); END IF;
  IF r.canal = 'email' THEN
    IF r.recipient_user_id IS NOT NULL THEN
      SELECT lower(nullif(trim(email),'')) INTO v_email FROM public.profiles WHERE user_id = r.recipient_user_id;
    ELSE
      SELECT lower(nullif(trim(email),'')) INTO v_email FROM public.clientes WHERE id = r.recipient_cliente_id;
    END IF;
    IF v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
      RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','invalid_email'); END IF;
    v_hash := encode(extensions.digest(v_email,'sha256'),'hex');
    v_redacted := left(split_part(v_email,'@',1),2) || '***@' || split_part(v_email,'@',2);
    RETURN jsonb_build_object('ok',true,'canal','email','address',v_email,
      'address_hash',v_hash,'redacted',v_redacted,
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id);
  END IF;
  IF r.canal = 'whatsapp' THEN
    IF r.recipient_user_id IS NOT NULL THEN
      SELECT telefone INTO v_phone_raw FROM public.profiles WHERE user_id = r.recipient_user_id;
    ELSE
      SELECT COALESCE(telefone, (telefones)[1]) INTO v_phone_raw FROM public.clientes WHERE id = r.recipient_cliente_id;
    END IF;
    v_phone_raw := regexp_replace(COALESCE(v_phone_raw,''), '[^0-9]', '', 'g');
    IF length(v_phone_raw) IN (10,11) THEN v_phone := '+55' || v_phone_raw;
    ELSIF length(v_phone_raw) BETWEEN 12 AND 15 THEN v_phone := '+' || v_phone_raw;
    ELSE RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','invalid_phone'); END IF;
    v_hash := encode(extensions.digest(v_phone,'sha256'),'hex');
    v_redacted := left(v_phone,4) || repeat('*', GREATEST(0, length(v_phone)-6)) || right(v_phone,2);
    RETURN jsonb_build_object('ok',true,'canal','whatsapp','address',v_phone,
      'address_hash',v_hash,'redacted',v_redacted,
      'user_id',r.recipient_user_id,'cliente_id',r.recipient_cliente_id);
  END IF;
  RETURN jsonb_build_object('ok',false,'outcome','cancelled','reason','unsupported_canal');
END$_$;


ALTER FUNCTION public.rpc_resolve_outbox_address(p_outbox_id uuid) OWNER TO postgres;

--
-- Name: rpc_resolver_alerta_operacional(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_resolver_alerta_operacional(p_alerta_id uuid, p_observacao text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_alerta record;
  v_dentro_sla boolean;
BEGIN
  IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success',false,'error','unauthorized'); END IF;
  IF NOT public.can_user_access_alerta(p_alerta_id) THEN
    RETURN jsonb_build_object('success',false,'error','forbidden');
  END IF;

  SELECT * INTO v_alerta FROM public.alertas_operacionais WHERE id = p_alerta_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','alerta_nao_encontrado'); END IF;

  UPDATE public.alertas_operacionais
    SET status='resolvido', resolvido_por=auth.uid(), resolvido_em=now(), updated_at=now()
    WHERE id = p_alerta_id;

  INSERT INTO public.alertas_acoes(alerta_id, user_id, acao, observacao)
    VALUES (p_alerta_id, auth.uid(), 'resolver', p_observacao);

  IF v_alerta.sla_config_id IS NOT NULL THEN
    v_dentro_sla := v_alerta.sla_resolucao_em IS NULL OR now() <= v_alerta.sla_resolucao_em;
    INSERT INTO public.alertas_sla_eventos(alerta_id, config_id, evento, criado_por, responsavel_id)
      VALUES (p_alerta_id, v_alerta.sla_config_id,
        CASE WHEN v_dentro_sla THEN 'resolvido_dentro_sla' ELSE 'resolvido_fora_sla' END,
        auth.uid(), auth.uid());
  END IF;

  PERFORM public.rpc_recalcular_prioridade_alerta(p_alerta_id);
  RETURN jsonb_build_object('success',true);
END;
$$;


ALTER FUNCTION public.rpc_resolver_alerta_operacional(p_alerta_id uuid, p_observacao text) OWNER TO postgres;

--
-- Name: rpc_resumo_atendimentos_tecnicos_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_resumo_atendimentos_tecnicos_v1() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean;
  v_is_tech boolean;
  v_res jsonb;
BEGIN
  IF NOT public.technical_actor_ready(v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error','unauthenticated');
  END IF;

  v_is_admin := public.has_role(v_uid,'administrador') OR public.has_role(v_uid,'gestor');
  v_is_tech := EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_uid AND ur.role IN ('tecnico_agronomo','consultor_tecnico')
  );
  IF NOT (v_is_admin OR v_is_tech) THEN
    RETURN jsonb_build_object('ok', false, 'error','forbidden');
  END IF;

  WITH visitas AS (
    SELECT r.id, r.status::text AS status, r.origem_atendimento AS origem,
           r.data_proxima_visita, r.fazenda_id
      FROM public.registros_consultor r
     WHERE public.can_view_technical_visit(v_uid, r.id)
  ),
  demandas AS (
    SELECT s.id
      FROM public.portal_solicitacoes s
     WHERE s.status NOT IN ('concluida','cancelada')
       AND NOT EXISTS (SELECT 1 FROM public.registros_consultor r WHERE r.solicitacao_id = s.id AND public.can_view_technical_visit(v_uid,r.id))
       AND public.can_user_access_solicitacao(s.id)
      AND (v_is_admin OR (s.consultor_atribuido = v_uid AND public.technical_client_link(v_uid,s.cliente_id,ARRAY['execute','manage'])))
  )
  SELECT jsonb_build_object(
    'ok', true,
    'demandas', (SELECT count(*) FROM demandas),
    'em_andamento', (SELECT count(*) FROM visitas WHERE status IN ('rascunho','em_andamento')),
    'aguardando', (SELECT count(*) FROM visitas WHERE status IN ('enviado_aprovacao','reprovado')),
    'monitoramento', (SELECT count(*) FROM visitas WHERE status IN ('aprovado','convertido_os') AND data_proxima_visita IS NOT NULL),
    'ocorrencias', (SELECT count(*) FROM visitas WHERE origem = 'ocorrencia_campo'),
    'concluidos', (SELECT count(*) FROM visitas
                    WHERE status NOT IN ('rascunho','em_andamento','enviado_aprovacao','reprovado')
                      AND NOT (status IN ('aprovado','convertido_os') AND data_proxima_visita IS NOT NULL)),
    'todos', (SELECT count(*) FROM visitas) + (SELECT count(*) FROM demandas),
    'os_ativas', (SELECT count(*) FROM public.ordens_servico_onfarm os
                   WHERE os.status NOT IN ('finalizada','entregue','cancelada')
                     AND os.registro_consultor_id IN (SELECT id FROM visitas)),
    'fazendas', (SELECT count(*) FROM public.fazendas f WHERE public.technical_refs_in_actor_tenant(f.cliente_id,f.id,NULL) AND public.can_user_access_cliente(f.cliente_id) AND (v_is_admin OR public.technical_client_link(v_uid,f.cliente_id,ARRAY['read','execute','manage'])))
  ) INTO v_res;

  RETURN v_res;
END;
$$;


ALTER FUNCTION public.rpc_resumo_atendimentos_tecnicos_v1() OWNER TO postgres;

--
-- Name: rpc_salvar_aplicacao_v1(uuid, jsonb, uuid, jsonb, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_salvar_aplicacao_v1(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid DEFAULT NULL::uuid, p_evidencias jsonb DEFAULT '[]'::jsonb, p_evidencias_manter uuid[] DEFAULT '{}'::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
 u uuid:=auth.uid(); org uuid; client uuid; product uuid; os_org uuid;
 osid uuid; onid uuid; lot uuid; responsible uuid; phase text; canonical jsonb; os_status text;
 r platform_private.application_save_preparations%ROWTYPE;
 original public.aplicacoes%ROWTYPE; a public.aplicacoes%ROWTYPE;
 ev jsonb; e public.aplicacao_evidencias%ROWTYPE; obj storage.objects%ROWTYPE;
 kept uuid; k text; n numeric; lo numeric; hi numeric; root uuid; ver integer:=1;
 expected text; ev_id uuid; moment date; start_at timestamptz; end_at timestamptz;
 manifest jsonb; count_files integer; own_role boolean; name_responsible text;
BEGIN
 -- Never parse/replay a receipt before proving current actor readiness.
 IF u IS NULL THEN RAISE EXCEPTION 'application_auth_required' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.profiles WHERE user_id=u FOR SHARE;
 org:=public.h15_actor_organization();
 IF org IS NULL THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR SHARE;
 PERFORM 1 FROM public.user_roles WHERE user_id=u ORDER BY role FOR SHARE;
 PERFORM 1 FROM public.platform_org_admin_invites WHERE user_id=u FOR SHARE;
 IF p_aplicacao_id IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
 OR jsonb_typeof(p_evidencias) IS DISTINCT FROM 'array' OR p_evidencias_manter IS NULL
 OR octet_length(p_payload::text)>32768 OR octet_length(p_evidencias::text)>32768 THEN
 RAISE EXCEPTION 'application_payload_invalid' USING ERRCODE='22023'; END IF;
 phase:=p_payload->>'_phase';
 IF phase IS NULL OR phase NOT IN ('prepare','finalize') THEN RAISE EXCEPTION 'application_phase_required' USING ERRCODE='22023'; END IF;
 canonical:=p_payload-'_phase';
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(canonical) key WHERE key NOT IN (
 'ordem_servico_id','ordem_servico_onfarm_id','data_aplicacao','hora_inicio','hora_fim','responsavel_id','responsavel',
 'modo_aplicacao','produto_usado_id','lote_usado_id','dose_aplicada','dose_unidade','volume_calda_l_ha',
 'volume_total_aplicado_ml','area_aplicada_ha','equipamento','equipamento_modelo','bico_tipo','pressao_bar',
 'temperatura_c','umidade_pct','vento_kmh','condicoes_climaticas','latitude','longitude','resultado_inicial',
 'observacoes','created_by','motivo_retificacao')) THEN RAISE EXCEPTION 'application_unknown_field' USING ERRCODE='22023'; END IF;
 IF canonical->>'created_by' IS DISTINCT FROM u::text OR canonical->>'dose_unidade' IS DISTINCT FROM 'mL/ha'
 THEN RAISE EXCEPTION 'application_author_or_unit_invalid' USING ERRCODE='42501'; END IF;
 osid:=nullif(canonical->>'ordem_servico_id','')::uuid;
 onid:=nullif(canonical->>'ordem_servico_onfarm_id','')::uuid;
 IF num_nonnulls(osid,onid)<>1 THEN RAISE EXCEPTION 'application_origin_invalid' USING ERRCODE='22023'; END IF;
 -- Lock every persisted authority before receipt lookup. Locks prevent UPDATE/DELETE races;
 -- they do not invent membership, roles or a tenant for NULL legacy rows.
 IF osid IS NOT NULL THEN
 SELECT cliente_id,produto_id,organization_id,status::text INTO client,product,os_org,os_status FROM public.ordens_servico WHERE id=osid FOR SHARE;
 ELSE
 SELECT cliente_id,produto_id,status::text INTO client,product,os_status FROM public.ordens_servico_onfarm WHERE id=onid FOR SHARE;
 SELECT organization_id INTO os_org FROM public.clientes WHERE id=client;
 END IF;
 IF client IS NULL OR os_org IS DISTINCT FROM org OR product IS NULL THEN RAISE EXCEPTION 'application_origin_denied' USING ERRCODE='42501'; END IF;
 -- Same lifecycle as the canonical desktop form. Replay is reauthorized too.
 IF os_status IS NULL OR NOT (os_status IN ('entregue','pronto_entrega','envase')
 OR (p_rectify_id IS NOT NULL AND os_status='finalizada')) THEN RAISE EXCEPTION 'application_os_status_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.clientes WHERE id=client AND organization_id=org FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_client_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_clientes WHERE user_id=u AND cliente_id=client ORDER BY id FOR SHARE;
 IF public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_create_denied' USING ERRCODE='42501'; END IF;
 IF (public.has_role(u,'cliente_produtor') OR public.has_role(u,'consultor_tecnico') OR public.has_role(u,'tecnico_agronomo'))
 AND NOT (public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo'))
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_membership_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.produtos WHERE id=product AND ativo IS TRUE FOR SHARE;
 IF NOT FOUND OR nullif(canonical->>'produto_usado_id','')::uuid IS DISTINCT FROM product THEN RAISE EXCEPTION 'application_product_denied' USING ERRCODE='42501'; END IF;
 lot:=nullif(canonical->>'lote_usado_id','')::uuid;
 IF lot IS NOT NULL THEN
 PERFORM 1 FROM public.lotes WHERE id=lot AND produto_id=product AND organization_id=org AND status='aprovado' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_lot_denied' USING ERRCODE='42501'; END IF; END IF;
 responsible:=nullif(canonical->>'responsavel_id','')::uuid;
 SELECT nome INTO name_responsible FROM public.profiles WHERE user_id=responsible AND organization_id=org
 AND ativo IS TRUE AND senha_provisoria IS FALSE FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_roles WHERE user_id=responsible ORDER BY role FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=responsible AND role::text IN
 ('administrador','gestor','administrativo','consultor_tecnico','tecnico_agronomo','aplicador','operador_onfarm','cliente_produtor'))
 OR platform_private.platform_actor_access_ready(responsible) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 own_role:=public.has_role(u,'administrador') OR public.has_role(u,'gestor') OR public.has_role(u,'administrativo') OR public.has_role(u,'consultor_tecnico');
 IF NOT own_role AND responsible IS DISTINCT FROM u THEN RAISE EXCEPTION 'application_responsible_denied' USING ERRCODE='42501'; END IF;
 -- Preserve Storage1's applicator restriction; do not make RPC metadata a bypass.
 IF public.has_role(u,'aplicador') AND NOT own_role AND responsible IS DISTINCT FROM u
 AND NOT client=ANY(public.get_cliente_ids_for_user(u)) THEN RAISE EXCEPTION 'application_applicator_denied' USING ERRCODE='42501'; END IF;
 FOR k,lo,hi IN SELECT * FROM (VALUES
 ('dose_aplicada',0::numeric,NULL::numeric),('area_aplicada_ha',0::numeric,NULL::numeric),
 ('volume_calda_l_ha',0::numeric,NULL::numeric),('volume_total_aplicado_ml',0::numeric,NULL::numeric),
 ('pressao_bar',0::numeric,NULL::numeric),('temperatura_c',-50::numeric,70::numeric),('umidade_pct',0::numeric,100::numeric),
 ('vento_kmh',0::numeric,250::numeric),('latitude',-90::numeric,90::numeric),('longitude',-180::numeric,180::numeric)) bounds LOOP
 IF canonical->>k IS NULL THEN
 IF k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') THEN RAISE EXCEPTION 'application_numeric_required' USING ERRCODE='22023'; END IF;
 ELSE
 IF jsonb_typeof(canonical->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'application_numeric_invalid' USING ERRCODE='22023'; END IF;
 n:=(canonical->>k)::numeric;
 IF n::text IN ('NaN','Infinity','-Infinity') OR n<lo OR (hi IS NOT NULL AND n>hi)
 OR (k IN ('dose_aplicada','area_aplicada_ha','volume_total_aplicado_ml') AND n<=0) THEN RAISE EXCEPTION 'application_numeric_bounds' USING ERRCODE='22023'; END IF;
 END IF;
 END LOOP;
 IF (canonical->>'volume_total_aplicado_ml')::numeric IS DISTINCT FROM (canonical->>'dose_aplicada')::numeric*(canonical->>'area_aplicada_ha')::numeric
 THEN RAISE EXCEPTION 'application_total_invalid' USING ERRCODE='22023'; END IF;
 moment:=(canonical->>'data_aplicacao')::date;
 start_at:=nullif(canonical->>'hora_inicio','')::timestamptz; end_at:=nullif(canonical->>'hora_fim','')::timestamptz;
 IF moment IS NULL OR NOT isfinite(moment) OR (start_at IS NOT NULL AND NOT isfinite(start_at))
 OR (end_at IS NOT NULL AND (NOT isfinite(end_at) OR start_at IS NULL OR end_at<=start_at)) THEN RAISE EXCEPTION 'application_time_invalid' USING ERRCODE='22023'; END IF;
 IF p_rectify_id IS NULL AND cardinality(p_evidencias_manter)>0 THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 count_files:=jsonb_array_length(p_evidencias)+cardinality(p_evidencias_manter);
 IF count_files>20 OR cardinality(p_evidencias_manter)<>(SELECT count(DISTINCT x) FROM unnest(p_evidencias_manter)x)
 THEN RAISE EXCEPTION 'application_evidence_limit' USING ERRCODE='22023'; END IF;
 manifest:='[]'::jsonb;
 FOR ev IN SELECT value FROM jsonb_array_elements(p_evidencias) LOOP
 IF jsonb_typeof(ev) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(ev) key WHERE key NOT IN ('tipo','storage_path','legenda','mime','tamanho_bytes'))
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 expected:=CASE ev->>'mime' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp'
 WHEN 'image/heic' THEN 'heic' WHEN 'image/heif' THEN 'heif' WHEN 'application/pdf' THEN 'pdf'
 WHEN 'video/mp4' THEN 'mp4' WHEN 'video/webm' THEN 'webm' WHEN 'video/quicktime' THEN 'mov'
 WHEN 'audio/mpeg' THEN 'mp3' WHEN 'audio/mp4' THEN 'm4a' WHEN 'audio/wav' THEN 'wav' WHEN 'audio/ogg' THEN 'ogg' WHEN 'audio/webm' THEN 'webm' END;
 IF expected IS NULL OR public.storage1_path_strict(ev->>'storage_path') IS DISTINCT FROM true
 OR split_part(ev->>'storage_path','/',1) IS DISTINCT FROM client::text
 OR split_part(ev->>'storage_path','/',2) IS DISTINCT FROM p_aplicacao_id::text
 OR split_part(ev->>'storage_path','/',3) !~ ('^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.'||expected||'$')
 OR jsonb_typeof(ev->'tamanho_bytes') IS DISTINCT FROM 'number' OR (ev->>'tamanho_bytes')::numeric NOT BETWEEN 1 AND 10485760
 OR (ev->>'tamanho_bytes')::numeric<>trunc((ev->>'tamanho_bytes')::numeric)
 OR coalesce(char_length(ev->>'legenda'),0)>1000
 OR ev->>'tipo' IS DISTINCT FROM (CASE WHEN ev->>'mime' LIKE 'image/%' THEN 'foto' WHEN ev->>'mime' LIKE 'video/%' THEN 'video' WHEN ev->>'mime' LIKE 'audio/%' THEN 'audio' ELSE 'documento' END)
 THEN RAISE EXCEPTION 'application_evidence_invalid' USING ERRCODE='22023'; END IF;
 manifest:=manifest||jsonb_build_array(ev);
 END LOOP;
 IF jsonb_array_length(manifest)<>(SELECT count(DISTINCT value->>'storage_path') FROM jsonb_array_elements(manifest)) THEN RAISE EXCEPTION 'application_evidence_duplicate' USING ERRCODE='22023'; END IF;
 -- One writer per application; then one writer per original version. No global cache.
 PERFORM pg_advisory_xact_lock(hashtextextended('application-save:'||p_aplicacao_id::text,0));
 SELECT * INTO r FROM platform_private.application_save_preparations WHERE application_id=p_aplicacao_id FOR UPDATE;
 IF FOUND AND (r.actor_id IS DISTINCT FROM u OR r.organization_id IS DISTINCT FROM org OR r.payload IS DISTINCT FROM canonical
 OR r.rectify_id IS DISTINCT FROM p_rectify_id OR r.manifest IS DISTINCT FROM manifest OR r.keep_ids IS DISTINCT FROM p_evidencias_manter)
 THEN RAISE EXCEPTION 'application_receipt_mismatch' USING ERRCODE='42501'; END IF;
 IF p_rectify_id IS NOT NULL THEN
 SELECT * INTO original FROM public.aplicacoes WHERE id=p_rectify_id FOR UPDATE;
 IF NOT FOUND OR original.organization_id IS DISTINCT FROM org OR public.can_user_manage_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR public.can_user_access_aplicacao(p_rectify_id) IS DISTINCT FROM true
 OR original.ordem_servico_id IS DISTINCT FROM osid OR original.ordem_servico_onfarm_id IS DISTINCT FROM onid
 THEN RAISE EXCEPTION 'application_rectification_denied' USING ERRCODE='42501'; END IF;
 IF (r.application_id IS NULL OR r.committed_at IS NULL) AND original.is_latest IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_version_conflict' USING ERRCODE='PT409'; END IF;
 IF char_length(btrim(coalesce(canonical->>'motivo_retificacao',''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'application_reason_invalid' USING ERRCODE='22023'; END IF;
 root:=coalesce(original.parent_id,original.id); ver:=original.versao+1;
 END IF;
 -- Validate inherited objects through their immutable origin, never rewritten paths.
 FOREACH kept IN ARRAY p_evidencias_manter LOOP
 SELECT ae.* INTO e FROM public.aplicacao_evidencias ae JOIN public.aplicacao_evidencias_vinculos v ON v.evidencia_id=ae.id
 WHERE v.aplicacao_id=p_rectify_id AND ae.id=kept FOR SHARE OF ae,v;
 IF NOT FOUND OR e.aplicacao_id IS DISTINCT FROM e.versao_origem_id
 OR public.can_user_access_aplicacao(e.versao_origem_id) IS DISTINCT FROM true
 OR split_part(e.storage_path,'/',1) IS DISTINCT FROM client::text OR split_part(e.storage_path,'/',2) IS DISTINCT FROM e.versao_origem_id::text
 OR public.storage1_path_strict(e.storage_path) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_inheritance_denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=e.storage_path FOR SHARE;
 IF NOT FOUND OR obj.metadata->>'mimetype' IS DISTINCT FROM e.mime OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM e.tamanho_bytes
 THEN RAISE EXCEPTION 'application_inherited_object_invalid' USING ERRCODE='42501'; END IF;
 END LOOP;
 IF public.h15_actor_organization() IS DISTINCT FROM org OR public.can_user_create_aplicacao_for_cliente(client) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'application_actor_denied' USING ERRCODE='42501'; END IF;
 IF r.committed_at IS NOT NULL THEN
 SELECT * INTO a FROM public.aplicacoes WHERE id=p_aplicacao_id AND organization_id=org AND created_by=u;
 IF NOT FOUND OR public.can_user_access_aplicacao(p_aplicacao_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'application_replay_denied' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('success',true,'created',false,'id',a.id,'versao',a.versao,'phase','finalized'); END IF;
 IF r.application_id IS NOT NULL AND r.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'application_preparation_expired' USING ERRCODE='42501'; END IF;
 IF phase='prepare' THEN
 IF r.application_id IS NULL THEN
 IF EXISTS(SELECT 1 FROM public.aplicacoes WHERE id=p_aplicacao_id) THEN RAISE EXCEPTION 'application_identity_conflict' USING ERRCODE='42501'; END IF;
 INSERT INTO platform_private.application_save_preparations(application_id,actor_id,organization_id,client_id,payload,rectify_id,manifest,keep_ids,expires_at)
 VALUES(p_aplicacao_id,u,org,client,canonical,p_rectify_id,manifest,p_evidencias_manter,clock_timestamp()+interval '15 minutes'); END IF;
 RETURN jsonb_build_object('success',true,'id',p_aplicacao_id,'phase','prepared'); END IF;
 IF r.application_id IS NULL THEN RAISE EXCEPTION 'application_preparation_required' USING ERRCODE='42501'; END IF;
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 SELECT * INTO obj FROM storage.objects WHERE bucket_id='aplicacao-evidencias' AND name=ev->>'storage_path' FOR SHARE;
 IF NOT FOUND OR coalesce(obj.owner_id,obj.owner::text) IS DISTINCT FROM u::text
 OR obj.metadata->>'mimetype' IS DISTINCT FROM ev->>'mime' OR nullif(obj.metadata->>'size','')::bigint IS DISTINCT FROM (ev->>'tamanho_bytes')::bigint
 OR obj.version IS NULL THEN RAISE EXCEPTION 'application_object_denied' USING ERRCODE='42501'; END IF;
 END LOOP;
 -- Metadata and latest-version switch are a single transaction. No OS/communications effects.
 IF p_rectify_id IS NOT NULL THEN UPDATE public.aplicacoes SET is_latest=false WHERE id=p_rectify_id; END IF;
 INSERT INTO public.aplicacoes(id,organization_id,ordem_servico_id,ordem_servico_onfarm_id,data_aplicacao,hora_inicio,hora_fim,responsavel_id,responsavel,modo_aplicacao,produto_usado_id,lote_usado_id,dose_aplicada,volume_calda_l_ha,volume_total_aplicado_ml,area_aplicada_ha,equipamento,equipamento_modelo,bico_tipo,pressao_bar,temperatura_c,umidade_pct,vento_kmh,condicoes_climaticas,latitude,longitude,resultado_inicial,observacoes,created_by,parent_id,versao,motivo_retificacao,is_latest)
 VALUES(p_aplicacao_id,org,osid,onid,moment,start_at,end_at,responsible,name_responsible,nullif(btrim(canonical->>'modo_aplicacao'),''),product,lot,(canonical->>'dose_aplicada')::numeric,(canonical->>'volume_calda_l_ha')::numeric,(canonical->>'volume_total_aplicado_ml')::numeric,(canonical->>'area_aplicada_ha')::numeric,nullif(btrim(canonical->>'equipamento'),''),nullif(btrim(canonical->>'equipamento_modelo'),''),nullif(btrim(canonical->>'bico_tipo'),''),(canonical->>'pressao_bar')::numeric,(canonical->>'temperatura_c')::numeric,(canonical->>'umidade_pct')::numeric,(canonical->>'vento_kmh')::numeric,nullif(btrim(canonical->>'condicoes_climaticas'),''),(canonical->>'latitude')::numeric,(canonical->>'longitude')::numeric,nullif(canonical->>'resultado_inicial',''),nullif(btrim(canonical->>'observacoes'),''),u,root,ver,CASE WHEN p_rectify_id IS NULL THEN NULL ELSE btrim(canonical->>'motivo_retificacao') END,true);
 FOR ev IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 INSERT INTO public.aplicacao_evidencias(aplicacao_id,tipo,storage_path,legenda,mime,tamanho_bytes,created_by,versao_origem_id)
 VALUES(p_aplicacao_id,ev->>'tipo',ev->>'storage_path',nullif(btrim(ev->>'legenda'),''),ev->>'mime',(ev->>'tamanho_bytes')::bigint,u,p_aplicacao_id) RETURNING id INTO ev_id;
 INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,ev_id);
 END LOOP;
 FOREACH kept IN ARRAY p_evidencias_manter LOOP INSERT INTO public.aplicacao_evidencias_vinculos(aplicacao_id,evidencia_id) VALUES(p_aplicacao_id,kept); END LOOP;
 UPDATE platform_private.application_save_preparations SET committed_at=clock_timestamp() WHERE application_id=p_aplicacao_id;
 RETURN jsonb_build_object('success',true,'created',true,'id',p_aplicacao_id,'versao',ver,'phase','finalized');
END;
$_$;


ALTER FUNCTION public.rpc_salvar_aplicacao_v1(p_aplicacao_id uuid, p_payload jsonb, p_rectify_id uuid, p_evidencias jsonb, p_evidencias_manter uuid[]) OWNER TO postgres;

--
-- Name: rpc_salvar_campo_visita(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_salvar_campo_visita(p_registro_consultor_id uuid, p_client_uuid uuid, p_payload jsonb, p_versao integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    SET lock_timeout TO '3s'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_reg public.registros_consultor;
  v_existing public.visitas_campo;
  v_result public.visitas_campo;
  v_talhao uuid; v_cultura uuid; v_area numeric; v_estande numeric;
  v_fase text; v_unif text; v_obs text; v_extras jsonb;
  v_org uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;
  IF p_registro_consultor_id IS NULL THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  -- CAS mandatory. 0 = "no row yet" (initial insert contract); NULL/negative never matches.
  IF p_versao IS NULL OR p_versao < 0 THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  -- Fast denial; same message for inexistent and foreign visits (no existence oracle).
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- Payload shape (after authorization, before any lock).
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_talhao  := NULLIF(p_payload->>'talhao_id','')::uuid;
    v_cultura := NULLIF(p_payload->>'cultura_id','')::uuid;
    v_area    := NULLIF(p_payload->>'area_avaliada_ha','')::numeric;
    v_estande := NULLIF(p_payload->>'estande_plantas_ha','')::numeric;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END;
  v_fase := NULLIF(p_payload->>'fase_fenologica','');
  v_unif := NULLIF(p_payload->>'uniformidade','');
  v_obs  := NULLIF(p_payload->>'observacoes_campo','');
  v_extras := COALESCE(p_payload->'dados_extras', '{}'::jsonb);
  IF jsonb_typeof(v_extras) <> 'object'
     OR (v_area IS NOT NULL AND (v_area::text IN ('NaN','Infinity','-Infinity') OR v_area < 0))
     OR (v_estande IS NOT NULL AND (v_estande::text IN ('NaN','Infinity','-Infinity') OR v_estande < 0 OR v_estande <> trunc(v_estande) OR v_estande > 2147483647))
     OR (v_unif IS NOT NULL AND v_unif NOT IN ('baixa','media','alta')) THEN
    RAISE EXCEPTION 'payload_invalido' USING ERRCODE = '22023';
  END IF;

  -- 1) Canonical revocation gate BEFORE the parent row lock (same order as revocation writers).
  PERFORM 1 FROM cf_user_guards_v1.state WHERE singleton FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'gate_unavailable' USING ERRCODE = '55000';
  END IF;
  IF NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- 2) Parent lock, restricted to the ORIGINAL actor scope (admin/created_by/client execute|manage)
  --    intersected with the canonical tenant check. No role is added.
  SELECT r.* INTO v_reg FROM public.registros_consultor r
   WHERE r.id = p_registro_consultor_id
     AND COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     AND COALESCE((public.has_role(v_uid, 'administrador'::app_role)
       OR r.created_by = v_uid
       OR (r.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, r.cliente_id, ARRAY['execute','manage']))), false)
   FOR UPDATE;

  -- 3) Re-authorize after the row wait; never cached.
  IF v_reg.id IS NULL
     OR NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     OR NOT COALESCE((
       public.has_role(v_uid, 'administrador'::app_role)
       OR v_reg.created_by = v_uid
       OR (v_reg.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, v_reg.cliente_id, ARRAY['execute','manage']))
     ), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  IF NOT COALESCE(public.is_technical_visit_editable_status(v_reg.status::text), false) THEN
    RAISE EXCEPTION 'visita_locked' USING ERRCODE = 'PT409';
  END IF;
  IF v_reg.cliente_id IS NULL THEN
    RAISE EXCEPTION 'registro_sem_cliente' USING ERRCODE = 'P0002';
  END IF;

  -- 4) Child lock.
  SELECT * INTO v_existing FROM public.visitas_campo
   WHERE registro_consultor_id = p_registro_consultor_id FOR UPDATE;

  -- 5) Re-authorize again after the child wait (original scope + canonical tenant + status),
  --    re-reading the parent; nothing observed before this wait is trusted.
  SELECT r.* INTO v_reg FROM public.registros_consultor r WHERE r.id = p_registro_consultor_id;
  IF v_reg.id IS NULL
     OR NOT COALESCE(public.can_manage_technical_visit(v_uid, p_registro_consultor_id), false)
     OR NOT COALESCE((
       public.has_role(v_uid, 'administrador'::app_role)
       OR v_reg.created_by = v_uid
       OR (v_reg.cliente_id IS NOT NULL
           AND public.has_active_user_cliente_access(v_uid, v_reg.cliente_id, ARRAY['execute','manage']))
     ), false) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE(public.is_technical_visit_editable_status(v_reg.status::text), false) THEN
    RAISE EXCEPTION 'visita_locked' USING ERRCODE = 'PT409';
  END IF;
  -- Actor tenant (active profile) resolved after every wait; the visit's cliente must belong to it.
  SELECT p.organization_id INTO v_org FROM public.profiles p
   WHERE p.user_id = v_uid AND p.ativo = true AND p.organization_id IS NOT NULL;
  IF v_org IS NULL OR NOT EXISTS (
       SELECT 1 FROM public.clientes c WHERE c.id = v_reg.cliente_id AND c.organization_id = v_org) THEN
    RAISE EXCEPTION 'sem_permissao' USING ERRCODE = '42501';
  END IF;

  -- References. Talhão: same tenant on talhão AND fazenda, fazenda of the visit's cliente.
  -- New choices must be active; an already-saved reference may be kept unchanged while inactive,
  -- but only if it still satisfies tenant/cliente (validity is never relaxed, only activity).
  IF v_talhao IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.talhoes t JOIN public.fazendas f ON f.id = t.fazenda_id
        WHERE t.id = v_talhao AND f.cliente_id = v_reg.cliente_id
          AND t.organization_id = v_org AND f.organization_id = v_org
          AND ((COALESCE(t.ativo, false) AND COALESCE(f.ativo, false))
               OR v_talhao IS NOT DISTINCT FROM v_existing.talhao_id)) THEN
    RAISE EXCEPTION 'talhao_invalido' USING ERRCODE = '22023';
  END IF;
  -- Cultura: global catalogue; new choice must be active AND not hidden for the actor tenant
  -- (public.catalog_tenant_visibility, same source as catalog_tenant_selection_core).
  IF v_cultura IS NOT NULL AND v_cultura IS DISTINCT FROM v_existing.cultura_id AND NOT EXISTS (
       SELECT 1 FROM public.culturas c
        WHERE c.id = v_cultura AND COALESCE(c.ativo, false)
          AND NOT EXISTS (SELECT 1 FROM public.catalog_tenant_visibility v
                           WHERE v.organization_id = v_org AND v.entity_type = 'cultura'
                             AND v.cultura_id = c.id AND v.hidden)) THEN
    RAISE EXCEPTION 'cultura_invalida' USING ERRCODE = '22023';
  END IF;
  IF v_cultura IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.culturas c WHERE c.id = v_cultura) THEN
    RAISE EXCEPTION 'cultura_invalida' USING ERRCODE = '22023';
  END IF;

  IF v_existing.id IS NULL THEN
    IF p_versao <> 0 THEN
      RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
    END IF;
    INSERT INTO public.visitas_campo (
      registro_consultor_id, cliente_id, talhao_id, cultura_id,
      area_avaliada_ha, fase_fenologica, estande_plantas_ha, uniformidade,
      observacoes_campo, dados_extras, client_uuid, versao, created_by
    ) VALUES (
      p_registro_consultor_id, v_reg.cliente_id, v_talhao, v_cultura,
      v_area, v_fase, v_estande::integer, v_unif,
      v_obs, v_extras, p_client_uuid, 1, v_uid
    ) RETURNING * INTO v_result;
    RETURN jsonb_build_object('id', v_result.id, 'registro_consultor_id', v_result.registro_consultor_id,
      'versao', v_result.versao, 'client_uuid', v_result.client_uuid, 'replayed', false);
  END IF;

  IF p_versao = 0 THEN
    -- Idempotent replay of a lost initial-insert response: only same actor, same client_uuid,
    -- still version 1 and identical content. Authorization above already proved scope on this
    -- very visit, so nothing crosses tenants. Anything else is a business conflict.
    IF p_client_uuid IS NOT NULL AND v_existing.versao = 1
       AND v_existing.client_uuid = p_client_uuid AND v_existing.created_by = v_uid
       AND v_existing.talhao_id IS NOT DISTINCT FROM v_talhao
       AND v_existing.cultura_id IS NOT DISTINCT FROM v_cultura
       AND v_existing.area_avaliada_ha IS NOT DISTINCT FROM v_area
       AND v_existing.fase_fenologica IS NOT DISTINCT FROM v_fase
       AND v_existing.estande_plantas_ha IS NOT DISTINCT FROM v_estande::integer
       AND v_existing.uniformidade IS NOT DISTINCT FROM v_unif
       AND v_existing.observacoes_campo IS NOT DISTINCT FROM v_obs
       AND v_existing.dados_extras = v_extras THEN
      RETURN jsonb_build_object('id', v_existing.id, 'registro_consultor_id', v_existing.registro_consultor_id,
        'versao', v_existing.versao, 'client_uuid', v_existing.client_uuid, 'replayed', true);
    END IF;
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  IF v_existing.versao IS NULL OR p_versao <> v_existing.versao THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  UPDATE public.visitas_campo SET
    talhao_id = v_talhao, cultura_id = v_cultura, area_avaliada_ha = v_area,
    fase_fenologica = v_fase, estande_plantas_ha = v_estande::integer, uniformidade = v_unif,
    observacoes_campo = v_obs, dados_extras = v_extras,
    versao = v_existing.versao + 1, updated_at = now()
  WHERE id = v_existing.id AND versao = p_versao
  RETURNING * INTO v_result;
  IF v_result.id IS NULL THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'PT409';
  END IF;

  RETURN jsonb_build_object('id', v_result.id, 'registro_consultor_id', v_result.registro_consultor_id,
    'versao', v_result.versao, 'client_uuid', v_result.client_uuid, 'replayed', false);
END;
$$;


ALTER FUNCTION public.rpc_salvar_campo_visita(p_registro_consultor_id uuid, p_client_uuid uuid, p_payload jsonb, p_versao integer) OWNER TO postgres;

