--
-- Name: rpc_service_apply_provider_settings(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_apply_provider_settings(p_actor uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $_$
DECLARE
  v_row       public.communication_provider_settings%ROWTYPE;
  v_updates   jsonb := '{}'::jsonb;
  v_secret_ops jsonb := '[]'::jsonb;
  v_changed   text[] := ARRAY[]::text[];
  v_op        jsonb;
  v_slot      text;
  v_col       text;
  v_action    text;
  v_value     text;
  v_existing  uuid;
  v_new_id    uuid;
  v_name      text;
  v_effective_test_mode boolean;
  v_effective_email_on  boolean;
  v_effective_wa_on     boolean;
  v_effective_delivery_on boolean;
  v_effective_smtp_pw_configured boolean;
  v_effective_wa_tok_configured  boolean;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_actor IS NULL THEN
    RAISE EXCEPTION 'invalid_actor' USING ERRCODE = '22023';
  END IF;
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'invalid_payload' USING ERRCODE = '22023';
  END IF;

  v_updates    := coalesce(p_payload->'updates', '{}'::jsonb);
  v_secret_ops := coalesce(p_payload->'secret_ops', '[]'::jsonb);

  IF jsonb_typeof(v_updates) <> 'object' THEN
    RAISE EXCEPTION 'invalid_updates' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(v_secret_ops) <> 'array' THEN
    RAISE EXCEPTION 'invalid_secret_ops' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_row FROM public.communication_provider_settings WHERE id = 1 FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'settings_row_missing' USING ERRCODE = 'P0002';
  END IF;

  FOR v_op IN SELECT * FROM jsonb_array_elements(v_secret_ops) LOOP
    v_slot   := v_op->>'slot';
    v_action := v_op->>'action';
    v_value  := v_op->>'value';

    CASE v_slot
      WHEN 'smtp_password'         THEN v_col := 'secret_smtp_password';         v_name := 'comm_smtp_password';
      WHEN 'whatsapp_access_token' THEN v_col := 'secret_whatsapp_access_token'; v_name := 'comm_whatsapp_access_token';
      WHEN 'whatsapp_app_secret'   THEN v_col := 'secret_whatsapp_app_secret';   v_name := 'comm_whatsapp_app_secret';
      WHEN 'whatsapp_verify_token' THEN v_col := 'secret_whatsapp_verify_token'; v_name := 'comm_whatsapp_verify_token';
      ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
    END CASE;

    EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
      INTO v_existing;

    IF v_action = 'set' THEN
      IF v_value IS NULL OR length(v_value) = 0 THEN
        RAISE EXCEPTION 'empty_secret_value' USING ERRCODE = '22023';
      END IF;
      IF v_existing IS NOT NULL THEN
        PERFORM vault.update_secret(
          v_existing,
          v_value,
          v_name || '_' || extract(epoch from now())::bigint::text,
          ''
        );
        v_new_id := v_existing;
      ELSE
        v_new_id := vault.create_secret(
          v_value,
          v_name || '_' || extract(epoch from now())::bigint::text,
          ''
        );
      END IF;
      EXECUTE format('UPDATE public.communication_provider_settings SET %I = $1 WHERE id = 1', v_col)
        USING v_new_id;
      v_changed := array_append(v_changed, v_col);
    ELSIF v_action = 'clear' THEN
      IF v_existing IS NOT NULL THEN
        DELETE FROM vault.secrets WHERE id = v_existing;
        EXECUTE format('UPDATE public.communication_provider_settings SET %I = NULL WHERE id = 1', v_col);
      END IF;
      v_changed := array_append(v_changed, v_col);
    ELSE
      RAISE EXCEPTION 'invalid_secret_action' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
    VALUES (p_actor, 'secret_' || v_action, v_slot, ARRAY[v_col]);
  END LOOP;

  IF v_updates ? 'test_mode_enabled' THEN
    UPDATE public.communication_provider_settings SET test_mode_enabled = (v_updates->>'test_mode_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'test_mode_enabled');
  END IF;
  IF v_updates ? 'allowed_emails' THEN
    UPDATE public.communication_provider_settings
       SET allowed_emails = ARRAY(SELECT jsonb_array_elements_text(v_updates->'allowed_emails'))
     WHERE id = 1;
    v_changed := array_append(v_changed, 'allowed_emails');
  END IF;
  IF v_updates ? 'allowed_phones' THEN
    UPDATE public.communication_provider_settings
       SET allowed_phones = ARRAY(SELECT jsonb_array_elements_text(v_updates->'allowed_phones'))
     WHERE id = 1;
    v_changed := array_append(v_changed, 'allowed_phones');
  END IF;
  IF v_updates ? 'delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET delivery_enabled = (v_updates->>'delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'delivery_enabled');
  END IF;
  IF v_updates ? 'email_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET email_delivery_enabled = (v_updates->>'email_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'email_delivery_enabled');
  END IF;
  IF v_updates ? 'whatsapp_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET whatsapp_delivery_enabled = (v_updates->>'whatsapp_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_delivery_enabled');
  END IF;
  IF v_updates ? 'inapp_delivery_enabled' THEN
    UPDATE public.communication_provider_settings SET inapp_delivery_enabled = (v_updates->>'inapp_delivery_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'inapp_delivery_enabled');
  END IF;
  IF v_updates ? 'whatsapp_webhook_enabled' THEN
    UPDATE public.communication_provider_settings SET whatsapp_webhook_enabled = (v_updates->>'whatsapp_webhook_enabled')::boolean WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_webhook_enabled');
  END IF;
  IF v_updates ? 'smtp_host' THEN
    UPDATE public.communication_provider_settings SET smtp_host = NULLIF(v_updates->>'smtp_host','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_host');
  END IF;
  IF v_updates ? 'smtp_port' THEN
    UPDATE public.communication_provider_settings SET smtp_port = NULLIF(v_updates->>'smtp_port','')::integer WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_port');
  END IF;
  IF v_updates ? 'smtp_user' THEN
    UPDATE public.communication_provider_settings SET smtp_user = NULLIF(v_updates->>'smtp_user','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_user');
  END IF;
  IF v_updates ? 'smtp_from' THEN
    UPDATE public.communication_provider_settings SET smtp_from = NULLIF(v_updates->>'smtp_from','') WHERE id = 1;
    v_changed := array_append(v_changed, 'smtp_from');
  END IF;
  IF v_updates ? 'whatsapp_phone_number_id' THEN
    UPDATE public.communication_provider_settings SET whatsapp_phone_number_id = NULLIF(v_updates->>'whatsapp_phone_number_id','') WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_phone_number_id');
  END IF;
  IF v_updates ? 'whatsapp_api_version' THEN
    UPDATE public.communication_provider_settings SET whatsapp_api_version = NULLIF(v_updates->>'whatsapp_api_version','') WHERE id = 1;
    v_changed := array_append(v_changed, 'whatsapp_api_version');
  END IF;

  SELECT * INTO v_row FROM public.communication_provider_settings WHERE id = 1;
  v_effective_test_mode        := v_row.test_mode_enabled;
  v_effective_email_on         := v_row.email_delivery_enabled;
  v_effective_wa_on            := v_row.whatsapp_delivery_enabled;
  v_effective_delivery_on      := v_row.delivery_enabled;
  v_effective_smtp_pw_configured := v_row.secret_smtp_password  IS NOT NULL AND v_row.smtp_host IS NOT NULL AND v_row.smtp_port IS NOT NULL AND v_row.smtp_user IS NOT NULL AND v_row.smtp_from IS NOT NULL;
  v_effective_wa_tok_configured  := v_row.secret_whatsapp_access_token IS NOT NULL AND v_row.whatsapp_phone_number_id IS NOT NULL AND v_row.whatsapp_api_version IS NOT NULL;

  IF NOT v_effective_test_mode THEN
    IF v_effective_delivery_on AND v_effective_email_on AND NOT v_effective_smtp_pw_configured THEN
      RAISE EXCEPTION 'test_mode_off_requires_email_provider' USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_delivery_on AND v_effective_wa_on AND NOT v_effective_wa_tok_configured THEN
      RAISE EXCEPTION 'test_mode_off_requires_whatsapp_provider' USING ERRCODE = 'P0001';
    END IF;
  END IF;
  IF v_effective_delivery_on AND v_effective_email_on AND NOT v_effective_smtp_pw_configured THEN
    RAISE EXCEPTION 'email_enabled_requires_provider_configured' USING ERRCODE = 'P0001';
  END IF;
  IF v_effective_delivery_on AND v_effective_wa_on AND NOT v_effective_wa_tok_configured THEN
    RAISE EXCEPTION 'whatsapp_enabled_requires_provider_configured' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.communication_provider_settings
     SET updated_at = now(), updated_by = p_actor
   WHERE id = 1;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, changed_fields)
  VALUES (p_actor, 'apply', v_changed);

  RETURN jsonb_build_object('ok', true, 'changed_fields', to_jsonb(v_changed));
END;
$_$;


ALTER FUNCTION public.rpc_service_apply_provider_settings(p_actor uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: rpc_service_check_rate_limit(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_check_rate_limit(p_user uuid, p_action text, p_max integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_count integer;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_user IS NULL OR coalesce(p_action,'') = '' OR p_max <= 0 OR p_window_seconds <= 0 THEN
    RAISE EXCEPTION 'invalid_args' USING ERRCODE = '22023';
  END IF;

  v_window_start := date_trunc('second', now())
                    - (extract(epoch from now())::bigint % p_window_seconds) * interval '1 second';

  INSERT INTO public.communication_provider_settings_rate_limit(user_id, action, window_start, count)
  VALUES (p_user, p_action, v_window_start, 1)
  ON CONFLICT (user_id, action, window_start)
  DO UPDATE SET count = public.communication_provider_settings_rate_limit.count + 1
  RETURNING count INTO v_count;

  -- Housekeeping barato: apaga janelas antigas do próprio par (limita rows).
  DELETE FROM public.communication_provider_settings_rate_limit
   WHERE user_id = p_user AND action = p_action AND window_start < v_window_start;

  RETURN v_count <= p_max;
END;
$$;


ALTER FUNCTION public.rpc_service_check_rate_limit(p_user uuid, p_action text, p_max integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: rpc_service_clear_provider_secret(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_clear_provider_secret(p_slot text, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $_$
DECLARE
  v_col text;
  v_existing uuid;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  CASE p_slot
    WHEN 'smtp_password'          THEN v_col := 'secret_smtp_password';
    WHEN 'whatsapp_access_token'  THEN v_col := 'secret_whatsapp_access_token';
    WHEN 'whatsapp_app_secret'    THEN v_col := 'secret_whatsapp_app_secret';
    WHEN 'whatsapp_verify_token'  THEN v_col := 'secret_whatsapp_verify_token';
    ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
  END CASE;

  EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
    INTO v_existing;

  IF v_existing IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_existing;
    EXECUTE format(
      'UPDATE public.communication_provider_settings SET %I = NULL, updated_at = now(), updated_by = $1 WHERE id = 1',
      v_col
    ) USING p_actor;
  END IF;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
  VALUES (p_actor, 'clear_secret', p_slot, ARRAY[v_col]);
END;
$_$;


ALTER FUNCTION public.rpc_service_clear_provider_secret(p_slot text, p_actor uuid) OWNER TO postgres;

--
-- Name: rpc_service_load_provider_runtime_config(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_load_provider_runtime_config() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE
  cfg public.communication_provider_settings%ROWTYPE;
  smtp_pw text;
  wa_tok text;
  wa_app text;
  wa_vt  text;
  result jsonb;
BEGIN
  -- Fail-closed: apenas service_role pode ler os segredos.
  IF current_setting('request.jwt.claim.role', true) IS NOT NULL
     AND current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO cfg FROM public.communication_provider_settings WHERE id = 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('present', false);
  END IF;

  IF cfg.secret_smtp_password IS NOT NULL THEN
    SELECT decrypted_secret INTO smtp_pw FROM vault.decrypted_secrets WHERE id = cfg.secret_smtp_password;
  END IF;
  IF cfg.secret_whatsapp_access_token IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_tok FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_access_token;
  END IF;
  IF cfg.secret_whatsapp_app_secret IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_app FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_app_secret;
  END IF;
  IF cfg.secret_whatsapp_verify_token IS NOT NULL THEN
    SELECT decrypted_secret INTO wa_vt FROM vault.decrypted_secrets WHERE id = cfg.secret_whatsapp_verify_token;
  END IF;

  result := jsonb_build_object(
    'present', true,
    'test_mode_enabled', cfg.test_mode_enabled,
    'allowed_emails', to_jsonb(cfg.allowed_emails),
    'allowed_phones', to_jsonb(cfg.allowed_phones),
    'delivery_enabled', cfg.delivery_enabled,
    'email_delivery_enabled', cfg.email_delivery_enabled,
    'whatsapp_delivery_enabled', cfg.whatsapp_delivery_enabled,
    'inapp_delivery_enabled', cfg.inapp_delivery_enabled,
    'whatsapp_webhook_enabled', cfg.whatsapp_webhook_enabled,
    'smtp_host', cfg.smtp_host,
    'smtp_port', cfg.smtp_port,
    'smtp_user', cfg.smtp_user,
    'smtp_from', cfg.smtp_from,
    'smtp_password', smtp_pw,
    'whatsapp_phone_number_id', cfg.whatsapp_phone_number_id,
    'whatsapp_api_version', cfg.whatsapp_api_version,
    'whatsapp_access_token', wa_tok,
    'whatsapp_app_secret', wa_app,
    'whatsapp_verify_token', wa_vt
  );
  RETURN result;
END;
$$;


ALTER FUNCTION public.rpc_service_load_provider_runtime_config() OWNER TO postgres;

--
-- Name: rpc_service_record_smtp_diagnostic(uuid, text, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_record_smtp_diagnostic(p_actor uuid, p_action text, p_outcome text, p_safe_code text, p_stage text, p_latency_ms integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id bigint;
BEGIN
  IF p_actor IS NULL OR NOT public.is_platform_superadmin(p_actor) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('smtp_connection_test', 'smtp_connection_candidate_test', 'smtp_send_test') THEN
    RAISE EXCEPTION 'invalid_action' USING ERRCODE = '22023';
  END IF;
  IF p_outcome NOT IN ('success', 'failure', 'ambiguous', 'blocked') THEN
    RAISE EXCEPTION 'invalid_outcome' USING ERRCODE = '22023';
  END IF;
  IF p_stage NOT IN ('connect', 'greeting', 'ehlo', 'starttls', 'auth', 'quit', 'send', 'response', 'preflight', 'config') THEN
    RAISE EXCEPTION 'invalid_stage' USING ERRCODE = '22023';
  END IF;
  IF p_safe_code NOT IN (
    'smtp_connection_ok', 'smtp_connect_timeout', 'smtp_connect_failed',
    'smtp_dns_failed', 'smtp_tcp_refused', 'smtp_tcp_unreachable',
    'smtp_tls_certificate_failed', 'smtp_tls_handshake_failed', 'smtp_tls_failed',
    'smtp_greeting_failed', 'smtp_ehlo_failed',
    'smtp_starttls_unavailable', 'smtp_starttls_failed',
    'smtp_auth_unsupported', 'smtp_auth_failed', 'smtp_protocol_error',
    'smtp_port_blocked_by_edge_runtime', 'smtp_config_invalid',
    'smtp_send_accepted', 'smtp_send_ambiguous', 'smtp_send_failed',
    'smtp_not_ready', 'rate_limited', 'candidate_not_applicable'
  ) THEN
    RAISE EXCEPTION 'invalid_safe_code' USING ERRCODE = '22023';
  END IF;
  IF p_latency_ms IS NOT NULL AND (p_latency_ms < 0 OR p_latency_ms > 300000) THEN
    RAISE EXCEPTION 'invalid_latency' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.communication_provider_settings_audit(
    actor_id, action, changed_fields, outcome, safe_code, stage, latency_ms
  ) VALUES (
    p_actor, p_action, '{}'::text[], p_outcome, p_safe_code, p_stage, p_latency_ms
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION public.rpc_service_record_smtp_diagnostic(p_actor uuid, p_action text, p_outcome text, p_safe_code text, p_stage text, p_latency_ms integer) OWNER TO postgres;

--
-- Name: rpc_service_set_provider_secret(text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_service_set_provider_secret(p_slot text, p_value text, p_actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $_$
DECLARE
  v_col text;
  v_name text;
  v_existing uuid;
  v_new uuid;
BEGIN
  IF (SELECT current_user) NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_value IS NULL OR length(p_value) = 0 THEN
    RAISE EXCEPTION 'empty_value' USING ERRCODE = '22023';
  END IF;

  CASE p_slot
    WHEN 'smtp_password'          THEN v_col := 'secret_smtp_password';         v_name := 'comm_smtp_password';
    WHEN 'whatsapp_access_token'  THEN v_col := 'secret_whatsapp_access_token'; v_name := 'comm_whatsapp_access_token';
    WHEN 'whatsapp_app_secret'    THEN v_col := 'secret_whatsapp_app_secret';   v_name := 'comm_whatsapp_app_secret';
    WHEN 'whatsapp_verify_token'  THEN v_col := 'secret_whatsapp_verify_token'; v_name := 'comm_whatsapp_verify_token';
    ELSE RAISE EXCEPTION 'invalid_slot' USING ERRCODE = '22023';
  END CASE;

  EXECUTE format('SELECT %I FROM public.communication_provider_settings WHERE id = 1', v_col)
    INTO v_existing;

  IF v_existing IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing, p_value, v_name || '_' || extract(epoch from now())::bigint::text, NULL);
    v_new := v_existing;
  ELSE
    v_new := vault.create_secret(p_value, v_name || '_' || extract(epoch from now())::bigint::text, NULL);
  END IF;

  EXECUTE format(
    'UPDATE public.communication_provider_settings SET %I = $1, updated_at = now(), updated_by = $2 WHERE id = 1',
    v_col
  ) USING v_new, p_actor;

  INSERT INTO public.communication_provider_settings_audit(actor_id, action, secret_field, changed_fields)
  VALUES (p_actor, 'set_secret', p_slot, ARRAY[v_col]);
END;
$_$;


ALTER FUNCTION public.rpc_service_set_provider_secret(p_slot text, p_value text, p_actor uuid) OWNER TO postgres;

--
-- Name: rpc_set_communication_template_metadata(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_set_communication_template_metadata(p_template_id uuid, p_provider_template_name text, p_language_code text, p_parameter_mapping jsonb, p_provider_template_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  r public.comunicacao_templates%rowtype;
  v_mapping jsonb := COALESCE(p_parameter_mapping,'[]'::jsonb);
  v_len int; v_vars_len int; v_item jsonb; v_idx int; v_var text;
  v_seen_vars text[] := ARRAY[]::text[];
  v_seen_idx int[] := ARRAY[]::int[];
  v_ever_approved boolean; v_prev text; v_new text := p_provider_template_status;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE='insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.canal = 'whatsapp' THEN
    IF p_provider_template_name IS NULL OR length(trim(p_provider_template_name)) = 0 THEN
      RAISE EXCEPTION 'whatsapp: provider_template_name obrigatório'; END IF;
    IF length(p_provider_template_name) > 512 THEN RAISE EXCEPTION 'excede 512'; END IF;
    IF p_language_code IS NULL OR p_language_code !~ '^[a-z]{2}(_[A-Z]{2})?$' THEN
      RAISE EXCEPTION 'language_code inválido'; END IF;
    IF jsonb_typeof(v_mapping) <> 'array' THEN RAISE EXCEPTION 'mapping array'; END IF;
    v_len := jsonb_array_length(v_mapping);
    IF v_len > 64 THEN RAISE EXCEPTION 'mapping >64'; END IF;
    v_vars_len := COALESCE(array_length(r.variaveis, 1), 0);
    FOR i IN 0 .. v_len - 1 LOOP
      v_item := v_mapping -> i;
      IF jsonb_typeof(v_item) <> 'object' THEN RAISE EXCEPTION 'item % não objeto', i+1; END IF;
      IF jsonb_typeof(v_item->'index') <> 'number' THEN RAISE EXCEPTION 'index[%] inválido', i+1; END IF;
      v_idx := (v_item->>'index')::int;
      IF v_idx <= 0 OR v_idx > v_len THEN RAISE EXCEPTION 'index fora 1..N'; END IF;
      IF v_idx = ANY(v_seen_idx) THEN RAISE EXCEPTION 'index dup: %', v_idx; END IF;
      v_seen_idx := array_append(v_seen_idx, v_idx);
      IF jsonb_typeof(v_item->'variavel') <> 'string' THEN RAISE EXCEPTION 'variavel[%] inválida', i+1; END IF;
      v_var := v_item->>'variavel';
      IF length(v_var) = 0 THEN RAISE EXCEPTION 'variavel vazia'; END IF;
      IF v_var = ANY(v_seen_vars) THEN RAISE EXCEPTION 'variavel dup: %', v_var; END IF;
      IF v_vars_len > 0 AND NOT (v_var = ANY(r.variaveis)) THEN
        RAISE EXCEPTION 'variavel % não declarada', v_var; END IF;
      v_seen_vars := array_append(v_seen_vars, v_var);
    END LOOP;
    IF v_len > 0 THEN
      FOR i IN 1 .. v_len LOOP
        IF NOT (i = ANY(v_seen_idx)) THEN RAISE EXCEPTION 'falta index %', i; END IF;
      END LOOP;
    END IF;
    IF v_vars_len = 0 AND v_len <> 0 THEN RAISE EXCEPTION 'sem variaveis exige mapping=[]'; END IF;
    IF v_new IS NOT NULL AND v_new NOT IN ('draft','pending','approved','rejected','paused','disabled') THEN
      RAISE EXCEPTION 'status inválido'; END IF;
    IF v_new = 'approved' AND v_len <> v_vars_len THEN
      RAISE EXCEPTION 'approved exige mapping completo'; END IF;
    v_prev := r.provider_template_status;
    v_ever_approved := v_prev IN ('approved','paused','disabled');
    IF v_ever_approved AND p_provider_template_name IS DISTINCT FROM r.provider_template_name THEN
      RAISE EXCEPTION 'nome imutável após aprovação'; END IF;
    IF v_new IS NOT NULL AND v_new IS DISTINCT FROM COALESCE(v_prev,'draft') THEN
      IF NOT (
        (COALESCE(v_prev,'draft') IN ('draft') AND v_new IN ('draft','pending')) OR
        (v_prev = 'pending' AND v_new IN ('draft','pending','approved','rejected')) OR
        (v_prev = 'approved' AND v_new IN ('approved','paused','disabled')) OR
        (v_prev = 'paused' AND v_new IN ('approved','paused','disabled')) OR
        (v_prev = 'rejected' AND v_new IN ('draft','pending','rejected')) OR
        (v_prev = 'disabled' AND v_new IN ('disabled'))
      ) THEN RAISE EXCEPTION 'transição inválida % → %', COALESCE(v_prev,'draft'), v_new; END IF;
    END IF;
  ELSE
    IF p_provider_template_name IS NOT NULL OR p_language_code IS NOT NULL
       OR v_new IS NOT NULL OR jsonb_array_length(v_mapping) > 0 THEN
      RAISE EXCEPTION 'metadados WA não aceitos para canal %', r.canal; END IF;
  END IF;
  UPDATE public.comunicacao_templates
     SET provider_template_name = p_provider_template_name,
         language_code = p_language_code,
         parameter_mapping = v_mapping,
         provider_template_status = v_new,
         updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.set_metadata','comunicacao_templates', p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$_$;


ALTER FUNCTION public.rpc_set_communication_template_metadata(p_template_id uuid, p_provider_template_name text, p_language_code text, p_parameter_mapping jsonb, p_provider_template_status text) OWNER TO postgres;

