--
-- Name: rpc_skip_communication_delivery(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_skip_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_outbox%rowtype; v_role text;
BEGIN
  v_role := COALESCE(current_setting('request.jwt.claims',true)::jsonb->>'role', session_user);
  IF v_role IS NOT NULL AND v_role NOT IN ('service_role') AND current_user <> 'service_role' THEN
    RAISE EXCEPTION 'apenas service_role' USING ERRCODE='insufficient_privilege'; END IF;
  IF NULLIF(trim(COALESCE(p_worker_id,'')),'') IS NULL THEN RAISE EXCEPTION 'worker_id obrigatório'; END IF;
  SELECT * INTO r FROM public.comunicacao_outbox WHERE id = p_outbox_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'outbox não encontrado'; END IF;
  IF r.status <> 'processing' THEN RAISE EXCEPTION 'não estava em processing (status=%)', r.status; END IF;
  IF r.locked_by IS DISTINCT FROM p_worker_id THEN RAISE EXCEPTION 'lease de outro worker'; END IF;
  UPDATE public.comunicacao_outbox
     SET status='skipped', error_code='skipped',
         error_message=left(COALESCE(p_reason,''),2000),
         locked_at=NULL, locked_by=NULL, lease_expires_at=NULL
   WHERE id = p_outbox_id;
  RETURN jsonb_build_object('ok',true,'status','skipped');
END$$;


ALTER FUNCTION public.rpc_skip_communication_delivery(p_outbox_id uuid, p_worker_id text, p_reason text) OWNER TO postgres;

--
-- Name: rpc_solicitar_ajuste_visita(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_solicitar_ajuste_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reg public.registros_consultor%ROWTYPE;
  v_new_version integer;
BEGIN
  IF p_motivo IS NULL OR btrim(p_motivo) = '' THEN
    RAISE EXCEPTION 'motivo_obrigatorio' USING ERRCODE = 'P0001';
  END IF;
  v_reg := public._visita_lock_and_check(p_registro_id, p_expected_version, true);
  IF v_reg.status::text <> 'enviado_aprovacao' THEN
    RAISE EXCEPTION 'status_invalido' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.registros_consultor
     SET status = 'rascunho', version = COALESCE(version,1)+1, updated_at = now()
   WHERE id = p_registro_id
  RETURNING version INTO v_new_version;
  INSERT INTO public.aprovacoes_tecnicas
    (registro_consultor_id, status_aprovacao, comentario_gestor, aprovado_por, data_aprovacao)
  VALUES (p_registro_id, 'ajuste_solicitado', p_motivo, auth.uid(), now());
  INSERT INTO public.registros_consultor_status_log
    (registro_consultor_id, status_anterior, status_novo, motivo, changed_by, changed_at)
  VALUES (p_registro_id, v_reg.status::text, 'rascunho', p_motivo, auth.uid(), now());
  INSERT INTO public.visitas_logs (registro_consultor_id, usuario_id, acao, descricao)
  VALUES (p_registro_id, auth.uid(), 'ajuste_solicitado', 'Ajuste solicitado. Motivo: ' || p_motivo);
  RETURN jsonb_build_object('ok', true, 'version', v_new_version, 'status', 'rascunho');
END
$$;


ALTER FUNCTION public.rpc_solicitar_ajuste_visita(p_registro_id uuid, p_expected_version integer, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_substituir_etiqueta_produto(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_substituir_etiqueta_produto(p_etiqueta_id uuid, p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_old public.produto_etiquetas%ROWTYPE;
  v_res jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  IF p_motivo IS NULL OR length(trim(p_motivo)) < 5 THEN
    RAISE EXCEPTION 'Motivo obrigatório para substituição (mínimo 5 caracteres)';
  END IF;

  SELECT * INTO v_old FROM public.produto_etiquetas WHERE id = p_etiqueta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Etiqueta não encontrada'; END IF;
  IF v_old.status = 'cancelada' THEN RAISE EXCEPTION 'Etiqueta já cancelada'; END IF;
  IF v_old.substituida_por_id IS NOT NULL THEN RAISE EXCEPTION 'Etiqueta já substituída'; END IF;

  v_res := public.rpc_gerar_etiqueta_produto(jsonb_build_object(
    'lote_id', v_old.lote_id,
    'produto_id', v_old.produto_id,
    'envase_id', v_old.envase_id,
    'envase_item_id', v_old.envase_item_id,
    'estoque_item_id', v_old.estoque_item_id,
    'entrega_id', v_old.entrega_id,
    'entrega_item_id', v_old.entrega_item_id,
    'cliente_id', v_old.cliente_id,
    'fazenda_id', v_old.fazenda_id,
    'tipo_etiqueta', v_old.tipo_etiqueta,
    'volume', v_old.volume,
    'unidade', v_old.unidade,
    'quantidade_embalagens', v_old.quantidade_embalagens,
    'conservacao', v_old.conservacao,
    'uso_recomendado', v_old.uso_recomendado,
    'observacoes', v_old.observacoes,
    'substitui_etiqueta_id', v_old.id
  ));

  PERFORM public.rpc_cancelar_etiqueta_produto(p_etiqueta_id, 'Substituída: ' || trim(p_motivo));

  RETURN jsonb_build_object(
    'success', true,
    'etiqueta_anterior_id', p_etiqueta_id,
    'nova_etiqueta_id', v_res->>'etiqueta_id',
    'novo_codigo', v_res->>'codigo_etiqueta'
  );
END;
$$;


ALTER FUNCTION public.rpc_substituir_etiqueta_produto(p_etiqueta_id uuid, p_motivo text) OWNER TO postgres;

--
-- Name: rpc_update_communication_preferences(public.comunicacao_canal, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_update_communication_preferences(p_canal public.comunicacao_canal, p_enabled boolean, p_whatsapp_opt_in boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_prev public.comunicacao_preferencias%rowtype;
BEGIN
  IF v_uid IS NULL OR NOT COALESCE(platform_private.platform_actor_access_ready(v_uid), false) THEN
    RAISE EXCEPTION 'COMMUNICATION_PREFERENCES_ACTOR_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  v_org := platform_private.h15_actor_organization();
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'COMMUNICATION_PREFERENCES_ORGANIZATION_FORBIDDEN' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_prev FROM public.comunicacao_preferencias WHERE user_id = v_uid AND canal = p_canal;
  INSERT INTO public.comunicacao_preferencias(user_id, canal, enabled,
      whatsapp_opt_in_at, whatsapp_opt_out_at, source)
  VALUES (v_uid, p_canal, COALESCE(p_enabled,true),
      CASE WHEN p_whatsapp_opt_in IS TRUE THEN now() END,
      CASE WHEN p_whatsapp_opt_in IS FALSE THEN now() END,
      'user')
  ON CONFLICT (user_id, canal) WHERE user_id IS NOT NULL DO UPDATE
    SET enabled = EXCLUDED.enabled,
        whatsapp_opt_in_at = CASE WHEN p_whatsapp_opt_in IS TRUE THEN now()
                                   ELSE public.comunicacao_preferencias.whatsapp_opt_in_at END,
        whatsapp_opt_out_at = CASE WHEN p_whatsapp_opt_in IS FALSE THEN now()
                                   ELSE public.comunicacao_preferencias.whatsapp_opt_out_at END,
        updated_at = now();
  IF p_whatsapp_opt_in IS FALSE THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal, 'opt_out','user');
  ELSIF p_whatsapp_opt_in IS TRUE THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal, 'opt_in','user');
  END IF;
  IF v_prev.id IS NULL OR v_prev.enabled IS DISTINCT FROM COALESCE(p_enabled,true) THEN
    PERFORM public._comunicacao_write_consent(v_uid, NULL, p_canal,
      CASE WHEN COALESCE(p_enabled,true) THEN 'enabled_on' ELSE 'enabled_off' END, 'user');
  END IF;
  RETURN jsonb_build_object('ok',true);
END $$;


ALTER FUNCTION public.rpc_update_communication_preferences(p_canal public.comunicacao_canal, p_enabled boolean, p_whatsapp_opt_in boolean) OWNER TO postgres;

--
-- Name: rpc_update_communication_template(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_update_communication_template(p_template_id uuid, p_nome text, p_assunto text, p_corpo text, p_variaveis jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r public.comunicacao_templates%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO r FROM public.comunicacao_templates WHERE id = p_template_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'template não encontrado'; END IF;
  IF r.status = 'active' THEN
    RAISE EXCEPTION 'template ativo é imutável; crie nova versão';
  END IF;
  IF r.status = 'archived' THEN RAISE EXCEPTION 'template arquivado'; END IF;
  UPDATE public.comunicacao_templates
     SET nome = p_nome, assunto = p_assunto, corpo = p_corpo,
         variaveis = COALESCE(p_variaveis,'[]'::jsonb), updated_by = auth.uid()
   WHERE id = p_template_id;
  PERFORM public._comunicacao_write_audit('template.update','comunicacao_templates',p_template_id,
    to_jsonb(r), (SELECT to_jsonb(t) FROM public.comunicacao_templates t WHERE t.id = p_template_id));
  RETURN jsonb_build_object('ok',true);
END$$;


ALTER FUNCTION public.rpc_update_communication_template(p_template_id uuid, p_nome text, p_assunto text, p_corpo text, p_variaveis jsonb) OWNER TO postgres;

