--
-- Name: rpc_upsert_communication_rule(uuid, text, public.app_role, text, public.comunicacao_canal, text, integer, jsonb, integer, boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_upsert_communication_rule(p_rule_id uuid, p_event_key text, p_perfil public.app_role, p_estrategia text, p_canal public.comunicacao_canal, p_template_chave text, p_template_versao integer, p_condicoes jsonb, p_prioridade integer, p_enabled boolean, p_cooldown_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; prev public.comunicacao_regras%rowtype;
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_event_key NOT IN ('produto_pronto_retirada','produto_pronto_aplicacao','administrative_important_update') THEN
    RAISE EXCEPTION 'event_key não permitido: %', p_event_key;
  END IF;
  IF COALESCE(p_estrategia,'by_role') NOT IN ('by_role','source_participants','broadcast_role') THEN
    RAISE EXCEPTION 'estrategia inválida: %', p_estrategia;
  END IF;
  IF p_event_key IN ('produto_pronto_retirada','produto_pronto_aplicacao')
     AND COALESCE(p_estrategia,'by_role') = 'broadcast_role' THEN
    RAISE EXCEPTION 'broadcast_role não permitido para eventos de OS';
  END IF;
  IF p_event_key = 'administrative_important_update' THEN
    IF COALESCE(p_estrategia,'by_role') <> 'broadcast_role' THEN
      RAISE EXCEPTION 'administrative_important_update exige broadcast_role';
    END IF;
    IF p_perfil IS NULL THEN
      RAISE EXCEPTION 'administrative_important_update exige perfil (target_role)';
    END IF;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.comunicacao_templates
     WHERE chave = p_template_chave AND canal = p_canal
       AND (p_template_versao IS NULL OR versao = p_template_versao)
  ) THEN
    RAISE EXCEPTION 'template % (canal=%, versao=%) inexistente',
      p_template_chave, p_canal, COALESCE(p_template_versao::text,'active');
  END IF;

  IF p_rule_id IS NULL THEN
    INSERT INTO public.comunicacao_regras(event_key,perfil,estrategia,canal,template_chave,template_versao,
      condicoes,prioridade,enabled,cooldown_seconds,created_by,updated_by)
    VALUES (p_event_key,p_perfil,COALESCE(p_estrategia,'by_role'),p_canal,p_template_chave,p_template_versao,
      COALESCE(p_condicoes,'{}'::jsonb),COALESCE(p_prioridade,100),COALESCE(p_enabled,false),
      COALESCE(p_cooldown_seconds,0),auth.uid(),auth.uid())
    RETURNING id INTO v_id;
    PERFORM public._comunicacao_write_audit('rule.create','comunicacao_regras',v_id, NULL,
      (SELECT to_jsonb(r) FROM public.comunicacao_regras r WHERE r.id = v_id));
  ELSE
    SELECT * INTO prev FROM public.comunicacao_regras WHERE id = p_rule_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'regra não encontrada'; END IF;
    UPDATE public.comunicacao_regras
       SET event_key = p_event_key, perfil = p_perfil, estrategia = COALESCE(p_estrategia,'by_role'),
           canal = p_canal, template_chave = p_template_chave, template_versao = p_template_versao,
           condicoes = COALESCE(p_condicoes,'{}'::jsonb), prioridade = COALESCE(p_prioridade,100),
           enabled = COALESCE(p_enabled,false), cooldown_seconds = COALESCE(p_cooldown_seconds,0),
           updated_by = auth.uid(), updated_at = now()
     WHERE id = p_rule_id RETURNING id INTO v_id;
    PERFORM public._comunicacao_write_audit('rule.update','comunicacao_regras',v_id,
      to_jsonb(prev), (SELECT to_jsonb(r) FROM public.comunicacao_regras r WHERE r.id = v_id));
  END IF;
  RETURN jsonb_build_object('ok',true,'rule_id',v_id);
END$$;


ALTER FUNCTION public.rpc_upsert_communication_rule(p_rule_id uuid, p_event_key text, p_perfil public.app_role, p_estrategia text, p_canal public.comunicacao_canal, p_template_chave text, p_template_versao integer, p_condicoes jsonb, p_prioridade integer, p_enabled boolean, p_cooldown_seconds integer) OWNER TO postgres;

--
-- Name: rpc_upsert_diagnostico_visita(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_upsert_diagnostico_visita(p_registro_id uuid, p_client_uuid uuid, p_payload jsonb, p_expected_versao integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_existing public.visita_diagnosticos;
  v_new public.visita_diagnosticos;
  v_registro_version integer;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501';
  END IF;

  -- H9-D-L6: autorizacao de escopo ANTES de qualquer leitura da visita.
  -- Inexistente e alheio (editavel ou nao) retornam o MESMO erro.
  IF NOT public._visita_scope_ok(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_visita' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_visita_editavel(p_registro_id);
  IF NOT public.can_manage_technical_visit(v_uid, p_registro_id)
     AND NOT public.is_active_visit_participant(v_uid, p_registro_id) THEN
    RAISE EXCEPTION 'forbidden_visita' USING ERRCODE = '42501';
  END IF;
  IF p_client_uuid IS NULL THEN
    RAISE EXCEPTION 'client_uuid_obrigatorio' USING ERRCODE = '22004';
  END IF;

  SELECT * INTO v_existing
    FROM public.visita_diagnosticos
   WHERE registro_id = p_registro_id
     AND client_uuid = p_client_uuid
   FOR UPDATE;

  IF v_existing.id IS NOT NULL
     AND COALESCE(p_expected_versao, -1) < v_existing.versao THEN
    RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
  END IF;

  IF v_existing.id IS NULL THEN
    INSERT INTO public.visita_diagnosticos (
      registro_id, client_uuid, categoria, problema, descricao, severidade,
      incidencia, urgencia, risco, intervencao, localizacao, versao, created_by
    ) VALUES (
      p_registro_id, p_client_uuid,
      NULLIF(COALESCE(p_payload->>'categoria', p_payload->>'categoria_problema'),''), NULLIF(COALESCE(p_payload->>'problema', p_payload->>'problema_principal'),''),
      NULLIF(COALESCE(p_payload->>'descricao', p_payload->>'observacoes_tecnicas'),''), NULLIF(COALESCE(p_payload->>'severidade', p_payload->>'nivel_pressao'),''),
      NULLIF(COALESCE(p_payload->>'incidencia', p_payload->>'percentual_area_afetada'),'')::numeric,
      NULLIF(p_payload->>'urgencia',''), NULLIF(p_payload->>'risco',''),
      NULLIF(p_payload->>'intervencao',''), NULLIF(p_payload->>'localizacao',''),
      GREATEST(1, COALESCE(p_expected_versao, 1)), v_uid
    ) RETURNING * INTO v_new;
  ELSE
    UPDATE public.visita_diagnosticos SET
      categoria = NULLIF(COALESCE(p_payload->>'categoria', p_payload->>'categoria_problema'),''),
      problema = NULLIF(COALESCE(p_payload->>'problema', p_payload->>'problema_principal'),''),
      descricao = NULLIF(COALESCE(p_payload->>'descricao', p_payload->>'observacoes_tecnicas'),''),
      severidade = NULLIF(COALESCE(p_payload->>'severidade', p_payload->>'nivel_pressao'),''),
      incidencia = NULLIF(COALESCE(p_payload->>'incidencia', p_payload->>'percentual_area_afetada'),'')::numeric,
      urgencia = NULLIF(p_payload->>'urgencia',''),
      risco = NULLIF(p_payload->>'risco',''),
      intervencao = NULLIF(p_payload->>'intervencao',''),
      localizacao = NULLIF(p_payload->>'localizacao',''),
      versao = v_existing.versao + 1,
      updated_at = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_new;
  END IF;

  UPDATE public.registros_consultor
     SET problema_principal = COALESCE(NULLIF(COALESCE(p_payload->>'problema_principal', p_payload->>'problema'),''), problema_principal),
         categoria_problema = COALESCE(NULLIF(COALESCE(p_payload->>'categoria_problema', p_payload->>'categoria'),'')::public.categoria_problema_consultor, categoria_problema),
         nivel_pressao = COALESCE(NULLIF(COALESCE(p_payload->>'nivel_pressao', p_payload->>'severidade'),'')::public.nivel_pressao, nivel_pressao),
         percentual_area_afetada = COALESCE(NULLIF(COALESCE(p_payload->>'percentual_area_afetada', p_payload->>'incidencia'),'')::numeric, percentual_area_afetada),
         observacoes_tecnicas = COALESCE(NULLIF(COALESCE(p_payload->>'observacoes_tecnicas', p_payload->>'descricao'),''), observacoes_tecnicas),
         urgencia = COALESCE(NULLIF(p_payload->>'urgencia','')::public.urgencia_consultor, urgencia),
         version = COALESCE(version,1) + 1,
         updated_at = now()
   WHERE id = p_registro_id
   RETURNING version INTO v_registro_version;

  RETURN jsonb_build_object(
    'id', v_new.id,
    'versao', v_new.versao,
    'registro_version', v_registro_version,
    'client_uuid', v_new.client_uuid
  );
END
$$;


ALTER FUNCTION public.rpc_upsert_diagnostico_visita(p_registro_id uuid, p_client_uuid uuid, p_payload jsonb, p_expected_versao integer) OWNER TO postgres;

--
-- Name: rpc_upsert_fiscal_invoice_manual(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_upsert_fiscal_invoice_manual(p_receivable_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_ar  record;
  v_existing record;
  v_id uuid;
  v_status text;
  v_number text;
  v_series text;
  v_key text;
  v_issue date;
  v_type text;
  v_total numeric(14,2);
  v_delivery uuid;
  v_old jsonb;
  v_action text;
BEGIN
  PERFORM public.h15_require_staff();

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sessão inválida.' USING ERRCODE='insufficient_privilege';
  END IF;
  IF NOT is_financial_staff(v_uid) THEN
    RAISE EXCEPTION 'Sem permissão para alterar dados fiscais.' USING ERRCODE='insufficient_privilege';
  END IF;

  SELECT * INTO v_ar FROM accounts_receivable WHERE id = p_receivable_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Conta a receber não encontrada.'; END IF;

  v_status   := COALESCE(NULLIF(p_payload->>'status',''), 'PENDING');
  v_number   := NULLIF(p_payload->>'invoice_number','');
  v_series   := NULLIF(p_payload->>'series','');
  v_key      := NULLIF(btrim(coalesce(p_payload->>'access_key','')),'');
  v_issue    := NULLIF(p_payload->>'issue_date','')::date;
  v_type     := COALESCE(NULLIF(p_payload->>'invoice_type',''), 'NFE');
  v_total    := COALESCE((p_payload->>'total_amount')::numeric, v_ar.total_amount);
  v_delivery := NULLIF(p_payload->>'delivery_id','')::uuid;

  IF v_status NOT IN ('PENDING','ISSUED','CANCELED','ERROR') THEN
    RAISE EXCEPTION 'Status fiscal inválido: %', v_status USING ERRCODE='check_violation';
  END IF;

  -- H7B-005: nenhum registro manual assume "emitido" sem evidencia externa.
  IF v_status = 'ISSUED' THEN
    IF v_key IS NULL OR v_key !~ '^[0-9]{44}$' THEN
      RAISE EXCEPTION
        'FISCAL_MANUAL_EVIDENCE_REQUIRED: registro manual como emitido exige chave de acesso de 44 digitos do documento externo.'
        USING ERRCODE='check_violation';
    END IF;
    IF v_number IS NULL THEN
      RAISE EXCEPTION
        'FISCAL_MANUAL_EVIDENCE_REQUIRED: registro manual como emitido exige o numero do documento externo.'
        USING ERRCODE='check_violation';
    END IF;
  END IF;

  SELECT * INTO v_existing FROM (SELECT * FROM public.fiscal_invoices WHERE public.h15_company_access(company_settings_id)) fiscal_invoices WHERE receivable_id = p_receivable_id
   FOR UPDATE;

  IF FOUND THEN
    IF public.fn_fiscal_status_is_terminal(v_existing.normalized_status) THEN
      RAISE EXCEPTION
        'FISCAL_DOCUMENT_LOCKED: documento fiscal % esta em % e nao aceita registro manual.',
        v_existing.id, v_existing.normalized_status
        USING ERRCODE='insufficient_privilege';
    END IF;
    IF EXISTS (SELECT 1 FROM (SELECT * FROM public.fiscal_number_reservations WHERE public.h15_invoice_access(fiscal_invoice_id)) r
                WHERE r.fiscal_invoice_id = v_existing.id) THEN
      RAISE EXCEPTION
        'FISCAL_DOCUMENT_ENGINE_MANAGED: documento % pertence ao motor NF-e; use o fluxo de emissao.',
        v_existing.id
        USING ERRCODE='insufficient_privilege';
    END IF;

    v_old := to_jsonb(v_existing);
    UPDATE fiscal_invoices SET
      status = v_status,
      invoice_number = v_number,
      series = v_series,
      access_key = v_key,
      issue_date = v_issue,
      invoice_type = v_type,
      total_amount = v_total,
      delivery_id = COALESCE(v_delivery, v_existing.delivery_id),
      document_origin = 'MANUAL_RECORD',
      provider = COALESCE(v_existing.provider, 'NONE')
    WHERE id = v_existing.id
    RETURNING id INTO v_id;
    v_action := 'FISCAL_INVOICE_UPDATED';
  ELSE
    INSERT INTO fiscal_invoices(company_settings_id, 
      receivable_id, delivery_id, invoice_type, invoice_number, series, access_key,
      issue_date, total_amount, status, created_by, document_origin, provider
    ) VALUES (public.h15_active_company(), 
      p_receivable_id, v_delivery, v_type, v_number, v_series, v_key,
      v_issue, v_total, v_status, v_uid, 'MANUAL_RECORD', 'NONE'
    ) RETURNING id INTO v_id;
    v_action := 'FISCAL_INVOICE_CREATED';
  END IF;

  UPDATE accounts_receivable SET
    fiscal_invoice_status = CASE
      WHEN v_status = 'ISSUED' THEN 'ISSUED'
      WHEN v_status = 'CANCELED' THEN 'CANCELED'
      WHEN v_status = 'PENDING' THEN 'PENDING'
      ELSE accounts_receivable.fiscal_invoice_status
    END,
    fiscal_invoice_number = COALESCE(v_number, fiscal_invoice_number),
    fiscal_access_key     = COALESCE(v_key, fiscal_access_key),
    fiscal_issue_date     = COALESCE(v_issue, fiscal_issue_date)
  WHERE id = p_receivable_id;

  INSERT INTO financial_audit_log (entity_type, entity_id, action, old_data, new_data, performed_by)
  VALUES ('fiscal_invoices', v_id, v_action, v_old,
          jsonb_build_object('status', v_status, 'invoice_number', v_number,
                             'delivery_id', v_delivery,
                             'document_origin', 'MANUAL_RECORD'),
          v_uid);

  RETURN jsonb_build_object('invoice_id', v_id, 'status', v_status,
                            'document_origin', 'MANUAL_RECORD');
END;
$_$;


ALTER FUNCTION public.rpc_upsert_fiscal_invoice_manual(p_receivable_id uuid, p_payload jsonb) OWNER TO postgres;

--
-- Name: rpc_upsert_recomendacao_visita(uuid, uuid, jsonb, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_upsert_recomendacao_visita(p_registro_id uuid, p_client_uuid uuid, p_payload jsonb, p_expected_versao integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_existing public.registros_consultor_recomendacoes;
  v_new public.registros_consultor_recomendacoes;
  v_ok boolean;
  v_lock uuid;
  v_con text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '42501'; END IF;

  v_ok := COALESCE(public.can_manage_technical_visit(v_uid, p_registro_id), false)
       OR COALESCE(public.is_active_visit_participant(v_uid, p_registro_id), false);
  IF v_ok IS NOT TRUE THEN
    RAISE EXCEPTION 'forbidden_visita' USING ERRCODE = '42501';
  END IF;

  PERFORM public._assert_visita_editavel(p_registro_id);

  IF p_client_uuid IS NULL THEN RAISE EXCEPTION 'client_uuid_obrigatorio' USING ERRCODE = '22004'; END IF;

  -- Serializa gravacoes concorrentes: FOR UPDATE na recomendacao nao bloqueia
  -- a ausencia de linha, entao bloqueamos a visita pai (apos autorizacao).
  SELECT id INTO v_lock
    FROM public.registros_consultor
   WHERE id = p_registro_id
   FOR UPDATE;
  IF v_lock IS NULL THEN
    RAISE EXCEPTION 'registro_nao_encontrado' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_existing
    FROM public.registros_consultor_recomendacoes
   WHERE registro_consultor_id = p_registro_id
     AND client_uuid = p_client_uuid
   FOR UPDATE;

  IF v_existing.id IS NOT NULL THEN
    IF p_expected_versao IS NULL OR p_expected_versao <> v_existing.versao THEN
      RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
    END IF;
  ELSE
    IF COALESCE(p_expected_versao, 1) <> 1 THEN
      RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF v_existing.id IS NULL THEN
    BEGIN
      INSERT INTO public.registros_consultor_recomendacoes (
        registro_consultor_id, client_uuid, recomendacao_tecnica,
        objetivo_recomendacao, estrategia_manejo,
        microrganismo_id, produto_biologico_sugerido_id,
        dose_recomendada_valor, dose_recomendada_unidade,
        volume_calda, volume_total_recomendado,
        numero_aplicacoes, intervalo_aplicacoes,
        modo_aplicacao, momento_aplicacao,
        cuidados_operacionais, compatibilidade_observacoes,
        observacoes_finais, encaminhar_para_os,
        versao, created_by
      ) VALUES (
        p_registro_id, p_client_uuid,
        NULLIF(p_payload->>'recomendacao_tecnica',''),
        NULLIF(p_payload->>'objetivo_recomendacao','')::objetivo_recomendacao,
        NULLIF(btrim(p_payload->>'estrategia_manejo'),'')::estrategia_manejo,
        NULLIF((p_payload->>'microrganismo_id'),'')::uuid,
        NULLIF((p_payload->>'produto_biologico_sugerido_id'),'')::uuid,
        NULLIF((p_payload->>'dose_recomendada_valor'),'')::numeric,
        NULLIF(p_payload->>'dose_recomendada_unidade',''),
        NULLIF(p_payload->>'volume_calda',''),
        NULLIF((p_payload->>'volume_total_recomendado'),'')::numeric,
        NULLIF((p_payload->>'numero_aplicacoes'),'')::integer,
        NULLIF(p_payload->>'intervalo_aplicacoes',''),
        NULLIF(p_payload->>'modo_aplicacao','')::modo_aplicacao_consultor,
        NULLIF(p_payload->>'momento_aplicacao',''),
        NULLIF(p_payload->>'cuidados_operacionais',''),
        NULLIF(p_payload->>'compatibilidade_observacoes',''),
        NULLIF(p_payload->>'observacoes_finais',''),
        COALESCE((p_payload->>'encaminhar_para_os')::boolean, false),
        1,
        v_uid
      ) RETURNING * INTO v_new;
    EXCEPTION WHEN unique_violation THEN
      -- Somente a corrida no indice de idempotencia vira version_conflict.
      -- Qualquer outra unique_violation e relancada sem mascaramento.
      GET STACKED DIAGNOSTICS v_con = CONSTRAINT_NAME;
      IF v_con = 'uq_rec_registro_client_uuid' THEN
        RAISE EXCEPTION 'version_conflict' USING ERRCODE = 'P0001';
      END IF;
      RAISE;
    END;
  ELSE
    UPDATE public.registros_consultor_recomendacoes SET
      recomendacao_tecnica = NULLIF(p_payload->>'recomendacao_tecnica',''),
      objetivo_recomendacao = NULLIF(p_payload->>'objetivo_recomendacao','')::objetivo_recomendacao,
      estrategia_manejo = NULLIF(btrim(p_payload->>'estrategia_manejo'),'')::estrategia_manejo,
      microrganismo_id = NULLIF((p_payload->>'microrganismo_id'),'')::uuid,
      produto_biologico_sugerido_id = NULLIF((p_payload->>'produto_biologico_sugerido_id'),'')::uuid,
      dose_recomendada_valor = NULLIF((p_payload->>'dose_recomendada_valor'),'')::numeric,
      dose_recomendada_unidade = NULLIF(p_payload->>'dose_recomendada_unidade',''),
      volume_calda = NULLIF(p_payload->>'volume_calda',''),
      volume_total_recomendado = NULLIF((p_payload->>'volume_total_recomendado'),'')::numeric,
      numero_aplicacoes = NULLIF((p_payload->>'numero_aplicacoes'),'')::integer,
      intervalo_aplicacoes = NULLIF(p_payload->>'intervalo_aplicacoes',''),
      modo_aplicacao = NULLIF(p_payload->>'modo_aplicacao','')::modo_aplicacao_consultor,
      momento_aplicacao = NULLIF(p_payload->>'momento_aplicacao',''),
      cuidados_operacionais = NULLIF(p_payload->>'cuidados_operacionais',''),
      compatibilidade_observacoes = NULLIF(p_payload->>'compatibilidade_observacoes',''),
      observacoes_finais = NULLIF(p_payload->>'observacoes_finais',''),
      encaminhar_para_os = COALESCE((p_payload->>'encaminhar_para_os')::boolean, encaminhar_para_os),
      versao = v_existing.versao + 1,
      updated_at = now()
    WHERE id = v_existing.id
    RETURNING * INTO v_new;
  END IF;

  RETURN jsonb_build_object('id', v_new.id, 'versao', v_new.versao, 'client_uuid', v_new.client_uuid);
END;
$$;


ALTER FUNCTION public.rpc_upsert_recomendacao_visita(p_registro_id uuid, p_client_uuid uuid, p_payload jsonb, p_expected_versao integer) OWNER TO postgres;

--
-- Name: rpc_validar_comprovante_entrega(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_validar_comprovante_entrega(p_validation_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_comp public.entrega_comprovantes%ROWTYPE;
  v_msg text;
  v_allowed boolean;
  v_retry integer;
BEGIN
  -- H7O: rate-limit server-side (token/origem/global) antes de qualquer leitura — resposta idêntica
  -- para token existente ou inexistente (anti-enumeração).
  SELECT rl.allowed, rl.retry_after_seconds
    INTO v_allowed, v_retry
    FROM private.fn_public_validation_rate_check(p_validation_token) rl;
  IF NOT COALESCE(v_allowed, false) THEN
    RETURN jsonb_build_object(
      'valido', false,
      'mensagem', 'Muitas tentativas de validação. Aguarde alguns instantes e tente novamente.',
      'retry_after_seconds', COALESCE(v_retry, 60)
    );
  END IF;

  SELECT * INTO v_comp FROM public.entrega_comprovantes WHERE validation_token = p_validation_token;
  IF NOT FOUND OR NOT v_comp.validation_public_enabled THEN
    RETURN jsonb_build_object('valido', false, 'mensagem', 'Comprovante não encontrado ou indisponível.');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.entregas e WHERE e.id=v_comp.entrega_id AND e.status<>'cancelada') THEN
    RETURN jsonb_build_object('valido',false,'mensagem','Comprovante não encontrado ou indisponível.');
  END IF;
  IF v_comp.validation_expires_at IS NOT NULL AND v_comp.validation_expires_at < now() THEN
    RETURN jsonb_build_object('valido', false, 'mensagem', 'Comprovante expirado.');
  END IF;
  IF v_comp.status IN ('cancelado','rejeitado') THEN
    RETURN jsonb_build_object('valido', false, 'mensagem', 'Comprovante cancelado.');
  END IF;

  v_msg := CASE v_comp.assinatura_tipo
    WHEN 'dispensada' THEN 'Comprovante registrado com dispensa formal de assinatura no sistema AR Bio.'
    WHEN 'digital_tela' THEN 'Comprovante registrado com assinatura digital operacional no sistema AR Bio.'
    WHEN 'fisica_anexada' THEN 'Comprovante registrado com formulário físico assinado no sistema AR Bio.'
    ELSE 'Comprovante de entrega registrado no sistema AR Bio.'
  END;

  RETURN jsonb_build_object(
    'valido', true,
    'status', v_comp.status,
    'assinatura_tipo', v_comp.assinatura_tipo,
    'possui_ressalvas', COALESCE(v_comp.possui_ressalvas, false),
    'numero_formulario', v_comp.numero_formulario,
    'data_confirmacao', v_comp.confirmado_em,
    'data_assinatura', v_comp.data_assinatura,
    'validation_hash', v_comp.validation_hash,
    'mensagem', v_msg
  );
END $$;


ALTER FUNCTION public.rpc_validar_comprovante_entrega(p_validation_token uuid) OWNER TO postgres;

--
-- Name: rpc_validar_integridade_esteira(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_validar_integridade_esteira(p_origem text, p_os_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_integridade record;
BEGIN
    -- H7O: leitura de integridade da esteira restrita ao staff operacional.
    IF NOT public.is_operational_staff(auth.uid()) THEN
        RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501',
          HINT = 'H7O: validação de integridade da esteira restrita ao staff operacional.';
    END IF;

    SELECT * INTO v_integridade FROM vw_os_integridade_esteira WHERE os_id = p_os_id AND origem_os = p_origem;
    
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Dados de integridade não encontrados');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'pode_finalizar', v_integridade.pode_finalizar,
        'detalhes', jsonb_build_object(
            'tem_programacao', v_integridade.tem_programacao,
            'tem_lote', v_integridade.tem_lote,
            'cq_resultado', v_integridade.cq_resultado,
            'tem_envase', v_integridade.tem_envase,
            'tem_estoque', v_integridade.tem_estoque,
            'entrega_confirmada', v_integridade.entrega_confirmada,
            'entrega_status', v_integridade.entrega_status
        )
    );
END;
$$;


ALTER FUNCTION public.rpc_validar_integridade_esteira(p_origem text, p_os_id uuid) OWNER TO postgres;

--
-- Name: rpc_validar_integridade_esteira(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_validar_integridade_esteira(p_os_id uuid, p_origem_os text, p_acao_solicitada text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_integridade RECORD;
    v_permitido BOOLEAN := TRUE;
    v_bloqueios TEXT[] := ARRAY[]::TEXT[];
    v_status_esteira TEXT;
    v_pode_finalizar BOOLEAN;
    v_user_id UUID := auth.uid();
BEGIN
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('permitido', FALSE, 'bloqueios', ARRAY['Usuário não autenticado'], 'status_esteira_atual', 'erro_seguranca');
    END IF;

    SELECT * INTO v_integridade FROM public.vw_os_integridade_esteira WHERE os_id = p_os_id AND origem_os = p_origem_os;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('permitido', FALSE, 'bloqueios', ARRAY['Ordem de Serviço não encontrada'], 'status_esteira_atual', 'nao_encontrado');
    END IF;

    v_status_esteira := v_integridade.status_esteira_oficial;
    v_pode_finalizar := v_integridade.pode_finalizar;

    CASE p_acao_solicitada
        WHEN 'enviar_cq' THEN
            IF v_integridade.lote_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível enviar para CQ sem lote gerado.');
            END IF;
        WHEN 'enviar_envase' THEN
            IF v_integridade.cq_resultado IS DISTINCT FROM 'aprovado' THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível envasar sem CQ aprovado.');
            END IF;
        WHEN 'gerar_estoque' THEN
            IF v_integridade.envase_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível gerar estoque sem envase concluído.');
            END IF;
        WHEN 'criar_entrega' THEN
            IF v_integridade.estoque_id IS NULL THEN
                v_permitido := FALSE;
                v_bloqueios := array_append(v_bloqueios, 'Não é possível criar entrega sem estoque disponível.');
            END IF;
        WHEN 'finalizar_os' THEN
            IF NOT COALESCE(v_integridade.pode_finalizar, FALSE) THEN
                v_permitido := FALSE;
                v_bloqueios := COALESCE(v_integridade.bloqueios, ARRAY['Ordem não pode ser finalizada.']);
            END IF;
        ELSE
            NULL;
    END CASE;

    RETURN jsonb_build_object('permitido', v_permitido, 'bloqueios', v_bloqueios, 'status_esteira_atual', v_status_esteira, 'pode_finalizar', v_pode_finalizar);
END;
$$;


ALTER FUNCTION public.rpc_validar_integridade_esteira(p_os_id uuid, p_origem_os text, p_acao_solicitada text) OWNER TO postgres;

--
-- Name: rpc_validar_rastreio_produto(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_validar_rastreio_produto(p_trace_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row public.produto_etiquetas%ROWTYPE;
  v_msg text;
  v_status text;
  v_hits integer;
  v_limite constant integer := 60;
  v_rl_allowed boolean;
  v_rl_retry integer;
BEGIN
  -- H9-B1: rate-limit server-side (token/origem/global) ANTES de qualquer leitura ou escrita,
  -- alinhado ao padrão certificado em H7O para a validação pública de comprovante.
  SELECT rl.allowed, rl.retry_after_seconds
    INTO v_rl_allowed, v_rl_retry
    FROM private.fn_public_validation_rate_check(p_trace_token) rl;
  IF NOT COALESCE(v_rl_allowed, false) THEN
    RETURN jsonb_build_object(
      'valido', false,
      'status', 'rate_limited',
      'mensagem', 'Muitas consultas. Aguarde alguns instantes e tente novamente.',
      'retry_after_seconds', COALESCE(v_rl_retry, 60)
    );
  END IF;

  SELECT * INTO v_row FROM public.produto_etiquetas WHERE trace_token = p_trace_token;
  IF NOT FOUND THEN
    INSERT INTO public.produto_etiqueta_consultas(etiqueta_id, resultado) VALUES (NULL, 'nao_encontrada');
    RETURN jsonb_build_object('valido', false, 'mensagem', 'Etiqueta não encontrada ou indisponível.');
  END IF;

  -- rate limit por etiqueta/hora
  SELECT count(*) INTO v_hits
  FROM public.produto_etiqueta_consultas
  WHERE etiqueta_id = v_row.id AND janela_hora = date_trunc('hour', now());

  IF v_hits >= v_limite THEN
    INSERT INTO public.produto_etiqueta_consultas(etiqueta_id, resultado) VALUES (v_row.id, 'rate_limited');
    RETURN jsonb_build_object('valido', false, 'status', 'rate_limited',
      'mensagem', 'Muitas consultas para esta etiqueta. Tente novamente mais tarde.');
  END IF;

  IF NOT v_row.public_trace_enabled THEN
    INSERT INTO public.produto_etiqueta_consultas(etiqueta_id, resultado) VALUES (v_row.id, 'revogada');
    RETURN jsonb_build_object('valido', false, 'status', 'revogada',
      'mensagem', 'Rastreio público desabilitado para esta etiqueta.');
  END IF;

  IF v_row.trace_expires_at IS NOT NULL AND v_row.trace_expires_at < now() THEN
    INSERT INTO public.produto_etiqueta_consultas(etiqueta_id, resultado) VALUES (v_row.id, 'expirada');
    RETURN jsonb_build_object('valido', false, 'status', 'expirado', 'mensagem', 'Rastreio expirado.');
  END IF;

  IF v_row.status = 'cancelada' THEN
    v_status := CASE WHEN v_row.substituida_por_id IS NOT NULL THEN 'substituida' ELSE 'cancelada' END;
    v_msg := CASE WHEN v_row.substituida_por_id IS NOT NULL
                  THEN 'Etiqueta substituída por nova emissão. Confirme com a AR Bio.'
                  ELSE 'Etiqueta cancelada ou substituída. Confirme com a AR Bio.' END;
  ELSIF v_row.validade_em IS NOT NULL AND v_row.validade_em < CURRENT_DATE THEN
    v_status := 'vencido';
    v_msg := 'Produto com validade expirada. Confirme condições com a AR Bio.';
  ELSE
    v_status := 'ativo';
    v_msg := 'Produto registrado no sistema AR Bio.';
  END IF;

  INSERT INTO public.produto_etiqueta_consultas(etiqueta_id, resultado) VALUES (v_row.id, v_status);

  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, descricao, metadata)
    VALUES (v_row.id, 'qr_validado', 'Validação pública via QR Code', jsonb_build_object('status', v_status));

  IF v_status IN ('cancelada','substituida') THEN
    RETURN jsonb_build_object('valido', false, 'status', v_status, 'mensagem', v_msg,
                              'codigo_etiqueta', v_row.codigo_etiqueta);
  END IF;

  RETURN jsonb_build_object(
    'valido', true,
    'status', v_status,
    'codigo_etiqueta', v_row.codigo_etiqueta,
    'produto_nome', v_row.produto_nome,
    'lote_codigo', v_row.lote_codigo,
    'fabricado_em', v_row.fabricado_em,
    'validade_em', v_row.validade_em,
    'volume', v_row.volume,
    'unidade', v_row.unidade,
    'tipo_etiqueta', v_row.tipo_etiqueta,
    'mensagem', v_msg
  );
END;
$$;


ALTER FUNCTION public.rpc_validar_rastreio_produto(p_trace_token uuid) OWNER TO postgres;

--
-- Name: rpc_verify_communication_channel(uuid, uuid, public.comunicacao_canal, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_verify_communication_channel(p_user_id uuid, p_cliente_id uuid, p_canal public.comunicacao_canal, p_email_verificado boolean, p_telefone_verificado boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 RAISE EXCEPTION 'NOTIF3_GLOBAL_CONTRACT_UNAVAILABLE' USING ERRCODE='42501';
  IF NOT public.has_role(auth.uid(),'administrador') THEN
    RAISE EXCEPTION 'apenas administrador' USING ERRCODE='insufficient_privilege';
  END IF;
  IF (p_user_id IS NOT NULL) = (p_cliente_id IS NOT NULL) THEN
    RAISE EXCEPTION 'informe exatamente um: user_id ou cliente_id';
  END IF;
  IF p_user_id IS NOT NULL THEN
    INSERT INTO public.comunicacao_preferencias(user_id, canal, enabled,
       email_verificado, telefone_verificado, source)
    VALUES (p_user_id, p_canal, true,
       COALESCE(p_email_verificado,false), COALESCE(p_telefone_verificado,false), 'admin')
    ON CONFLICT (user_id, canal) WHERE user_id IS NOT NULL DO UPDATE
       SET email_verificado = COALESCE(p_email_verificado, public.comunicacao_preferencias.email_verificado),
           telefone_verificado = COALESCE(p_telefone_verificado, public.comunicacao_preferencias.telefone_verificado),
           updated_at = now();
  ELSE
    INSERT INTO public.comunicacao_preferencias(cliente_id, canal, enabled,
       email_verificado, telefone_verificado, source)
    VALUES (p_cliente_id, p_canal, true,
       COALESCE(p_email_verificado,false), COALESCE(p_telefone_verificado,false), 'admin')
    ON CONFLICT (cliente_id, canal) WHERE cliente_id IS NOT NULL DO UPDATE
       SET email_verificado = COALESCE(p_email_verificado, public.comunicacao_preferencias.email_verificado),
           telefone_verificado = COALESCE(p_telefone_verificado, public.comunicacao_preferencias.telefone_verificado),
           updated_at = now();
  END IF;
  IF p_email_verificado IS TRUE THEN
    PERFORM public._comunicacao_write_consent(p_user_id, p_cliente_id, p_canal, 'verified_email','admin');
  END IF;
  IF p_telefone_verificado IS TRUE THEN
    PERFORM public._comunicacao_write_consent(p_user_id, p_cliente_id, p_canal, 'verified_phone','admin');
  END IF;
  RETURN jsonb_build_object('ok',true);
END$$;


ALTER FUNCTION public.rpc_verify_communication_channel(p_user_id uuid, p_cliente_id uuid, p_canal public.comunicacao_canal, p_email_verificado boolean, p_telefone_verificado boolean) OWNER TO postgres;

--
-- Name: rpc_vincular_etiqueta_embalagem(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rpc_vincular_etiqueta_embalagem(p_embalagem_id uuid, p_etiqueta_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_st text; v_et_st text; v_dup uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF NOT public.can_user_manage_estoque_embalagem(p_embalagem_id) THEN RAISE EXCEPTION 'sem permissão'; END IF;
  SELECT status INTO v_st FROM public.estoque_embalagens WHERE id = p_embalagem_id;
  IF v_st IS NULL THEN RAISE EXCEPTION 'embalagem inexistente'; END IF;
  IF v_st IN ('cancelado','descartado','entregue') THEN RAISE EXCEPTION 'embalagem em status %', v_st; END IF;
  SELECT status INTO v_et_st FROM public.produto_etiquetas WHERE id = p_etiqueta_id;
  IF v_et_st IS NULL THEN RAISE EXCEPTION 'etiqueta inexistente'; END IF;
  IF v_et_st = 'cancelada' THEN RAISE EXCEPTION 'etiqueta cancelada'; END IF;
  SELECT id INTO v_dup FROM public.estoque_embalagens
    WHERE etiqueta_id = p_etiqueta_id AND id <> p_embalagem_id AND status NOT IN ('cancelado','descartado') LIMIT 1;
  IF v_dup IS NOT NULL THEN RAISE EXCEPTION 'etiqueta já vinculada a outra embalagem ativa'; END IF;
  UPDATE public.estoque_embalagens SET etiqueta_id = p_etiqueta_id WHERE id = p_embalagem_id;
  UPDATE public.produto_etiquetas SET embalagem_id = p_embalagem_id WHERE id = p_etiqueta_id;
  INSERT INTO public.estoque_embalagem_movimentacoes(embalagem_id, tipo_movimentacao, user_id, metadata)
    VALUES (p_embalagem_id, 'etiqueta_vinculada', v_uid, jsonb_build_object('etiqueta_id', p_etiqueta_id));
  INSERT INTO public.produto_etiqueta_eventos(etiqueta_id, evento, user_id, metadata)
    VALUES (p_etiqueta_id, 'etiqueta_substituida', v_uid, jsonb_build_object('embalagem_id', p_embalagem_id));
  INSERT INTO public.financial_audit_log(entity_type, entity_id, action, performed_by, new_data)
    VALUES ('estoque_embalagem', p_embalagem_id, 'EMB_LABEL_LINKED', v_uid, jsonb_build_object('etiqueta_id', p_etiqueta_id));
  RETURN jsonb_build_object('success', true);
END $$;


ALTER FUNCTION public.rpc_vincular_etiqueta_embalagem(p_embalagem_id uuid, p_etiqueta_id uuid) OWNER TO postgres;

