--
-- Name: saas_payment_outbox; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.saas_payment_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    topic text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'held'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    completed_at timestamp with time zone,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT saas_payment_outbox_attempt CHECK (((attempt_count >= 0) AND (attempt_count <= 20))),
    CONSTRAINT saas_payment_outbox_payload CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT saas_payment_outbox_status CHECK ((status = ANY (ARRAY['held'::text, 'pending'::text, 'processing'::text, 'completed'::text, 'failed'::text, 'dead_letter'::text])))
);


ALTER TABLE public.saas_payment_outbox OWNER TO postgres;

--
-- Name: saas_claim_payment_outbox_non_operational(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_claim_payment_outbox_non_operational(_worker_id text, _limit integer DEFAULT 20) RETURNS SETOF public.saas_payment_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF current_user<>'postgres' AND v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF _worker_id IS NULL OR length(btrim(_worker_id))<3 OR _limit<1 OR _limit>100 THEN RAISE EXCEPTION 'payment_invalid'; END IF;
  RETURN QUERY SELECT * FROM public.saas_payment_outbox WHERE false;
END;
$$;


ALTER FUNCTION public.saas_claim_payment_outbox_non_operational(_worker_id text, _limit integer) OWNER TO postgres;

--
-- Name: saas_feature_override_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_feature_override_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'saas_history_immutable: exceções não podem ser apagadas' USING ERRCODE='42501';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.organization_id IS DISTINCT FROM OLD.organization_id
    OR NEW.feature_id IS DISTINCT FROM OLD.feature_id
    OR NEW.mode IS DISTINCT FROM OLD.mode
    OR NEW.limit_value IS DISTINCT FROM OLD.limit_value
    OR NEW.starts_at IS DISTINCT FROM OLD.starts_at
    OR NEW.ends_at IS DISTINCT FROM OLD.ends_at
    OR NEW.reason IS DISTINCT FROM OLD.reason
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR OLD.ended_at IS NOT NULL
    OR NEW.ended_at IS NULL
    OR NEW.ended_by IS NULL
    OR NULLIF(btrim(NEW.end_reason), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'saas_history_immutable: somente encerramento auditado é permitido' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;


