-- Name: saas_plan_version_audit_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_plan_version_audit_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_plan uuid;
BEGIN
  SELECT plan_id INTO v_plan FROM public.saas_plan_versions WHERE id=NEW.plan_version_id;
  IF session_user='authenticator' AND (v_plan IS NULL OR NOT platform_private.has_ticket('saas_plan_version_audit',v_plan)) THEN
    RAISE EXCEPTION 'platform_forbidden: auditoria gravada fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.saas_plan_version_audit_guard() OWNER TO postgres;

--
-- Name: saas_plan_version_feature_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_plan_version_feature_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_plan uuid; v_status text;
BEGIN
  SELECT plan_id,status INTO v_plan,v_status FROM public.saas_plan_versions WHERE id=COALESCE(NEW.plan_version_id,OLD.plan_version_id);
  IF v_status <> 'DRAFT' THEN RAISE EXCEPTION 'saas_version_immutable: conteúdo publicado não pode ser alterado'; END IF;
  IF session_user='authenticator' AND NOT platform_private.has_ticket('saas_plan_version_write',v_plan) THEN
    RAISE EXCEPTION 'platform_forbidden: conteúdo alterado fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE(NEW,OLD);
END;
$$;


