    SET search_path TO ''
    AS $$
BEGIN
  IF session_user = 'authenticator' AND NOT platform_private.has_ticket('saas_plan_version_create', NEW.plan_id) THEN
    RAISE EXCEPTION 'platform_forbidden: versão criada fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.saas_plan_version_guard() OWNER TO postgres;

--
-- Name: saas_plan_version_no_mutation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_plan_version_no_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF OLD.status IN ('PUBLISHED','ARCHIVED') THEN
    IF OLD.status='PUBLISHED' AND NEW.status='ARCHIVED'
       AND platform_private.has_ticket('saas_plan_version_archive',OLD.plan_id) THEN RETURN NEW; END IF;
    -- Única alteração permitida em versão publicada: encerrar a vigência aberta
    -- desta versão exata, pela publicação da sucessora, sem tocar em outro campo.
    IF OLD.status='PUBLISHED' AND NEW.status='PUBLISHED'
       AND OLD.effective_to IS NULL AND NEW.effective_to IS NOT NULL
       AND NEW.effective_to > OLD.effective_from
       AND (to_jsonb(NEW) - 'effective_to' - 'updated_at') = (to_jsonb(OLD) - 'effective_to' - 'updated_at')
       AND platform_private.has_ticket('saas_plan_version_supersede',OLD.id) THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'saas_version_immutable: versão publicada não pode ser alterada';
  END IF;
  IF OLD.status='DRAFT' AND NOT platform_private.has_ticket('saas_plan_version_write',OLD.plan_id) THEN
    RAISE EXCEPTION 'platform_forbidden: rascunho alterado fora do fluxo autorizado' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END; $$;


ALTER FUNCTION public.saas_plan_version_no_mutation() OWNER TO postgres;

--
-- Name: saas_record_payment_retry_non_operational(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_record_payment_retry_non_operational(_event_id uuid, _error_code text, _next_retry_at timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_role text; v_old jsonb; v_new jsonb;
BEGIN
  v_role:=coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role','');
  IF current_user<>'postgres' AND v_role<>'service_role' THEN RAISE EXCEPTION 'platform_forbidden' USING ERRCODE='42501'; END IF;
  IF _error_code IS NULL OR length(_error_code)>80 OR _next_retry_at IS NULL OR _next_retry_at<=now() THEN RAISE EXCEPTION 'payment_invalid'; END IF;
  SELECT to_jsonb(e) INTO v_old FROM public.saas_payment_events e WHERE e.id=_event_id FOR UPDATE;
  IF v_old IS NULL THEN RAISE EXCEPTION 'payment_invalid'; END IF;
  UPDATE public.saas_payment_events SET attempt_count=attempt_count+1,processing_status=CASE WHEN attempt_count+1>=20 THEN 'dead_letter' ELSE 'failed' END,next_retry_at=CASE WHEN attempt_count+1>=20 THEN NULL ELSE _next_retry_at END,last_error_code=_error_code WHERE id=_event_id RETURNING to_jsonb(saas_payment_events.*) INTO v_new;
  INSERT INTO public.saas_payment_audit(event_id,action,old_values,new_values,reason,origin) VALUES(_event_id,'retry_recorded',v_old,v_new,'falha sanitizada registrada para nova tentativa','internal_non_operational');
  RETURN _event_id;
END;
$$;


ALTER FUNCTION public.saas_record_payment_retry_non_operational(_event_id uuid, _error_code text, _next_retry_at timestamp with time zone) OWNER TO postgres;

--
-- Name: saas_subscription_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.saas_subscription_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_old jsonb;
  v_new jsonb;
  v_reason text;
  v_action text;
  v_correlation uuid;
BEGIN
  v_new := to_jsonb(NEW);
  IF TG_OP = 'UPDATE' THEN
    v_old := to_jsonb(OLD);
    IF v_old = v_new THEN RETURN NEW; END IF;
  END IF;
  v_reason := nullif(current_setting('app.saas_change_reason', true), '');
  v_action := nullif(current_setting('app.saas_change_action', true), '');
  BEGIN
    v_correlation := nullif(current_setting('app.saas_correlation_id', true), '')::uuid;
  EXCEPTION WHEN invalid_text_representation THEN
    v_correlation := NULL;
  END;
  INSERT INTO public.organization_subscription_history(
    subscription_id, organization_id, actor_user_id, source, reason,
    old_values, new_values, action, correlation_id,
    previous_status, new_status, previous_plan_id, new_plan_id,
    previous_plan_version_id, new_plan_version_id,
    price_snapshot, currency_snapshot, billing_cycle_snapshot, limits_snapshot
  ) VALUES (
    NEW.id, NEW.organization_id, auth.uid(),
    CASE WHEN v_action = 'expire_trial' THEN 'system' ELSE 'rpc' END,
    COALESCE(v_reason, CASE WHEN TG_OP = 'INSERT' THEN 'subscription_created' ELSE 'subscription_updated' END),
    v_old, v_new, COALESCE(v_action, lower(TG_OP)), v_correlation,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END,
    NEW.status,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_id ELSE NULL END,
    NEW.plan_id,
    CASE WHEN TG_OP = 'UPDATE' THEN OLD.plan_version_id ELSE NULL END,
    NEW.plan_version_id,
    NEW.price_snapshot, NEW.currency_snapshot, NEW.billing_cycle_snapshot, NEW.limits_snapshot
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.saas_subscription_audit() OWNER TO postgres;

