--
-- Name: save_client_portal_branding(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_client_portal_branding(p_cliente_id uuid, p_marca_nome text, p_marca_logo_url text, p_marca_cor_primaria text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'nao autenticado';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_clientes uc
    WHERE uc.user_id = auth.uid()
      AND uc.cliente_id = p_cliente_id
      AND uc.is_active
      AND uc.revoked_at IS NULL
      AND (uc.valid_from IS NULL OR uc.valid_from <= now())
      AND (uc.valid_until IS NULL OR uc.valid_until >= now())
  ) THEN
    RAISE EXCEPTION 'sem vinculo ativo com este cliente';
  END IF;

  IF p_marca_logo_url IS NOT NULL
     AND p_marca_logo_url !~ ('/logos/clientes/' || p_cliente_id::text || '/') THEN
    RAISE EXCEPTION 'logo fora da pasta autorizada';
  END IF;

  UPDATE public.clientes
     SET marca_nome = NULLIF(btrim(coalesce(p_marca_nome, '')), ''),
         marca_logo_url = p_marca_logo_url,
         marca_cor_primaria = p_marca_cor_primaria
   WHERE id = p_cliente_id;
END $$;


ALTER FUNCTION public.save_client_portal_branding(p_cliente_id uuid, p_marca_nome text, p_marca_logo_url text, p_marca_cor_primaria text) OWNER TO postgres;

--
-- Name: save_partner_portal_branding(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_partner_portal_branding(p_partner_id uuid, p_marca_nome text, p_marca_logo_url text, p_marca_cor_primaria text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'nao autenticado';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.partner_users pu
      JOIN public.partner_accounts pa ON pa.id = pu.partner_id
     WHERE pu.user_id = auth.uid()
       AND pu.partner_id = p_partner_id
       AND pu.papel = 'gestor'
       AND coalesce(pa.ativo, true)
  ) THEN
    RAISE EXCEPTION 'apenas gestor de parceiro ativo pode alterar a identidade';
  END IF;

  IF p_marca_logo_url IS NOT NULL
     AND p_marca_logo_url !~ ('/logos/parceiros/' || p_partner_id::text || '/') THEN
    RAISE EXCEPTION 'logo fora da pasta autorizada';
  END IF;

  UPDATE public.partner_accounts
     SET marca_nome = NULLIF(btrim(coalesce(p_marca_nome, '')), ''),
         marca_logo_url = p_marca_logo_url,
         marca_cor_primaria = p_marca_cor_primaria
   WHERE id = p_partner_id;
END $$;


ALTER FUNCTION public.save_partner_portal_branding(p_partner_id uuid, p_marca_nome text, p_marca_logo_url text, p_marca_cor_primaria text) OWNER TO postgres;

--
-- Name: send_partner_simulation_to_manager_secure(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_sim partner_simulations%ROWTYPE;
  v_partner_id uuid;
  v_allowed boolean := false;
BEGIN

  IF NOT public.b2b_phase1_simulation_visible(p_simulation_id) THEN RAISE EXCEPTION 'b2b_phase1_scope_denied' USING ERRCODE='42501'; END IF;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Não autenticado'; END IF;
  SELECT * INTO v_sim FROM partner_simulations WHERE id = p_simulation_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Simulação não encontrada'; END IF;
  IF v_sim.status <> 'rascunho' THEN RAISE EXCEPTION 'Somente simulações em rascunho podem ser enviadas'; END IF;

  v_partner_id := get_user_partner_id();

  IF has_role(v_uid, 'administrador') OR has_role(v_uid, 'gestor_comercial') THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b_tecnico') AND v_sim.created_by = v_uid THEN v_allowed := true;
  ELSIF has_role(v_uid, 'parceiro_b2b') AND (v_sim.created_by = v_uid OR v_sim.partner_id = v_partner_id) THEN v_allowed := true;
  END IF;
  IF NOT v_allowed THEN RAISE EXCEPTION 'Sem permissão para enviar esta simulação'; END IF;

  UPDATE partner_simulations SET status = 'enviada_gestor', updated_at = now() WHERE id = p_simulation_id;

  INSERT INTO partner_audit_logs (partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (v_sim.partner_id, v_uid, 'simulation_sent_to_manager',
    jsonb_build_object('simulation_id', p_simulation_id, 'status', v_sim.status),
    jsonb_build_object('simulation_id', p_simulation_id, 'status', 'enviada_gestor'));

  PERFORM public.insert_partner_catalog_access_log_internal(
    'simulation_sent_to_manager', v_sim.partner_id, v_uid,
    v_sim.cliente_id, p_simulation_id, NULL, NULL, '{}'::jsonb);
END;
$$;


ALTER FUNCTION public.send_partner_simulation_to_manager_secure(p_simulation_id uuid) OWNER TO postgres;

