--
-- Name: storage1_application_allowed(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storage1_application_allowed(p_name text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
