--
-- Name: sync_catalogo_volumes_calc(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_catalogo_volumes_calc() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.volume_ml IS NOT NULL AND NEW.volume_ml > 0 AND NEW.preco_brl IS NOT NULL THEN
    NEW.preco_litro_brl := round(NEW.preco_brl / (NEW.volume_ml / 1000.0), 2);
    NEW.valor_dose_100ml_brl := round(NEW.preco_litro_brl / 10.0, 2);
  ELSE
    NEW.preco_litro_brl := NULL;
    NEW.valor_dose_100ml_brl := NULL;
  END IF;
  IF NEW.volume_ml IS NOT NULL AND NEW.volume_ml > 0 THEN
    NEW.doses_por_volume := round(NEW.volume_ml / 100.0, 4);
  ELSE
    NEW.doses_por_volume := NULL;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_catalogo_volumes_calc() OWNER TO postgres;

--
-- Name: sync_microorganism_pricing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_microorganism_pricing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  dose_changed boolean := false;
  litro_changed boolean := false;
BEGIN
  IF COALESCE(current_setting('arbio.catalogo_sync', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.valor_dose_brl IS NOT NULL AND NEW.valor_litro_brl IS NULL THEN
      NEW.valor_litro_brl := NEW.valor_dose_brl * 10;
    ELSIF NEW.valor_litro_brl IS NOT NULL AND NEW.valor_dose_brl IS NULL THEN
      NEW.valor_dose_brl := NEW.valor_litro_brl / 10;
    ELSIF NEW.valor_dose_brl IS NOT NULL AND NEW.valor_litro_brl IS NOT NULL THEN
      IF NEW.valor_litro_brl <> NEW.valor_dose_brl * 10 THEN
        NEW.valor_litro_brl := NEW.valor_dose_brl * 10;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  dose_changed := NEW.valor_dose_brl IS DISTINCT FROM OLD.valor_dose_brl;
  litro_changed := NEW.valor_litro_brl IS DISTINCT FROM OLD.valor_litro_brl;

  IF dose_changed AND NOT litro_changed THEN
    NEW.valor_litro_brl := CASE WHEN NEW.valor_dose_brl IS NULL THEN NULL ELSE NEW.valor_dose_brl * 10 END;
  ELSIF litro_changed AND NOT dose_changed THEN
    NEW.valor_dose_brl := CASE WHEN NEW.valor_litro_brl IS NULL THEN NULL ELSE NEW.valor_litro_brl / 10 END;
  ELSIF dose_changed AND litro_changed THEN
    NEW.valor_litro_brl := CASE WHEN NEW.valor_dose_brl IS NULL THEN NULL ELSE NEW.valor_dose_brl * 10 END;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_microorganism_pricing() OWNER TO postgres;

--
-- Name: sync_os_onfarm_downstream(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_os_onfarm_downstream() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prog_id uuid;
  v_lote_id uuid;
BEGIN
  IF (OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_prog_id FROM public.programacao_producao
   WHERE ordem_servico_onfarm_id = NEW.id ORDER BY created_at DESC LIMIT 1;

  IF v_prog_id IS NULL
     AND NEW.status::text IN ('aprovada','programada','em_producao','em_cq','envase','pronto_entrega','entregue','finalizada')
     AND NEW.produto_id IS NOT NULL THEN
    INSERT INTO public.programacao_producao
      (produto_id, volume_necessario, data_programada, status, ordem_servico_onfarm_id)
    VALUES
      (NEW.produto_id, NEW.volume_total_ml,
       COALESCE(NEW.data_recomendada, CURRENT_DATE), 'aguardando', NEW.id)
    RETURNING id INTO v_prog_id;
  END IF;

  IF v_prog_id IS NOT NULL THEN
    SELECT id INTO v_lote_id FROM public.lotes
      WHERE programacao_id = v_prog_id ORDER BY created_at DESC LIMIT 1;
  END IF;

  CASE NEW.status::text
    WHEN 'aprovada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando' WHERE id = v_prog_id;
      END IF;
    WHEN 'programada' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao
          SET status = 'aguardando',
              data_programada = COALESCE(NEW.data_recomendada, data_programada, CURRENT_DATE)
          WHERE id = v_prog_id;
      END IF;
    WHEN 'em_producao' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'em_producao' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NULL AND NEW.produto_id IS NOT NULL THEN
        INSERT INTO public.lotes (codigo_lote, produto_id, programacao_id, status, volume_produzido, data_producao)
        VALUES (public.gerar_codigo_lote(), NEW.produto_id, v_prog_id,
                'em_producao', NEW.volume_total_ml, CURRENT_DATE);
      END IF;
    WHEN 'em_cq' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aguardando_cq' WHERE id = v_prog_id;
      END IF;
      IF v_lote_id IS NOT NULL THEN
        UPDATE public.lotes SET status = 'aguardando_cq' WHERE id = v_lote_id;
      END IF;
    WHEN 'envase' THEN
      IF v_prog_id IS NOT NULL THEN
        UPDATE public.programacao_producao SET status = 'aprovado' WHERE id = v_prog_id;
      END IF;
    ELSE
      NULL;
  END CASE;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_os_onfarm_downstream() OWNER TO postgres;

--
-- Name: sync_product_pricing(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_product_pricing() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  dose_changed boolean := false;
  litro_changed boolean := false;
  ha_changed boolean := false;
  doseha_changed boolean := false;
BEGIN
  -- H3c: durante a sincronizacao canonica (catalogo_volumes -> mestre) os
  -- valores ja chegam prontos; nao reprocessar.
  IF COALESCE(current_setting('arbio.catalogo_sync', true), 'off') = 'on' THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.valor_dose_brl IS NULL AND NEW.valor_litro_brl IS NOT NULL THEN
      NEW.valor_dose_brl := NEW.valor_litro_brl / 10;
    END IF;
    IF NEW.valor_dose_brl IS NULL AND NEW.valor_ha_brl IS NOT NULL
       AND NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 THEN
      NEW.valor_dose_brl := NEW.valor_ha_brl / (NEW.dose_ml_ha / 100.0);
    END IF;
    IF NEW.valor_dose_brl IS NOT NULL THEN
      NEW.valor_litro_brl := NEW.valor_dose_brl * 10;
      IF NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 THEN
        NEW.valor_ha_brl := (NEW.dose_ml_ha / 100.0) * NEW.valor_dose_brl;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  dose_changed    := NEW.valor_dose_brl IS DISTINCT FROM OLD.valor_dose_brl;
  litro_changed   := NEW.valor_litro_brl IS DISTINCT FROM OLD.valor_litro_brl;
  ha_changed      := NEW.valor_ha_brl IS DISTINCT FROM OLD.valor_ha_brl;
  doseha_changed  := NEW.dose_ml_ha IS DISTINCT FROM OLD.dose_ml_ha;

  IF dose_changed THEN
    NEW.valor_litro_brl := CASE WHEN NEW.valor_dose_brl IS NULL THEN NULL ELSE NEW.valor_dose_brl * 10 END;
    IF NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 AND NEW.valor_dose_brl IS NOT NULL THEN
      NEW.valor_ha_brl := (NEW.dose_ml_ha / 100.0) * NEW.valor_dose_brl;
    END IF;
  ELSIF litro_changed THEN
    NEW.valor_dose_brl := CASE WHEN NEW.valor_litro_brl IS NULL THEN NULL ELSE NEW.valor_litro_brl / 10 END;
    IF NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 AND NEW.valor_dose_brl IS NOT NULL THEN
      NEW.valor_ha_brl := (NEW.dose_ml_ha / 100.0) * NEW.valor_dose_brl;
    END IF;
  ELSIF ha_changed AND NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 AND NEW.valor_ha_brl IS NOT NULL THEN
    NEW.valor_dose_brl := NEW.valor_ha_brl / (NEW.dose_ml_ha / 100.0);
    NEW.valor_litro_brl := NEW.valor_dose_brl * 10;
  ELSIF doseha_changed AND NEW.valor_dose_brl IS NOT NULL AND NEW.dose_ml_ha IS NOT NULL AND NEW.dose_ml_ha > 0 THEN
    NEW.valor_ha_brl := (NEW.dose_ml_ha / 100.0) * NEW.valor_dose_brl;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_product_pricing() OWNER TO postgres;

--
-- Name: sync_puc_to_ptc_fn(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_puc_to_ptc_fn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.assignment_type = 'tecnico'
     AND (NEW.user_role = 'parceiro_b2b_tecnico' OR public.has_role(NEW.user_id, 'parceiro_b2b_tecnico'::app_role))
  THEN
    INSERT INTO public.partner_technician_clients (partner_id, technician_user_id, cliente_id, assigned_by, active, notes)
    VALUES (NEW.partner_id, NEW.user_id, NEW.cliente_id, NEW.assigned_by, NEW.active, NEW.notes)
    ON CONFLICT (partner_id, technician_user_id, cliente_id)
    DO UPDATE SET active = EXCLUDED.active, updated_at = now(), notes = EXCLUDED.notes;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sync_puc_to_ptc_fn() OWNER TO postgres;

--
-- Name: sync_talhao_safra_atual(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_talhao_safra_atual() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next_id uuid;
  v_next_cultura uuid;
BEGIN
  IF TG_OP IN ('INSERT', 'UPDATE') AND NEW.status = 'em_andamento' THEN
    UPDATE public.talhoes
      SET safra_atual_id = NEW.id,
          cultura_id = NEW.cultura_id
      WHERE id = NEW.talhao_id;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.status = 'em_andamento' AND NEW.status <> 'em_andamento' THEN
    SELECT id, cultura_id INTO v_next_id, v_next_cultura
      FROM public.talhao_safras
      WHERE talhao_id = NEW.talhao_id AND status = 'em_andamento' AND id <> NEW.id
      ORDER BY data_plantio DESC LIMIT 1;
    UPDATE public.talhoes
      SET safra_atual_id = v_next_id,
          cultura_id = COALESCE(v_next_cultura, cultura_id)
      WHERE id = NEW.talhao_id;
  END IF;

  IF TG_OP = 'DELETE' AND OLD.status = 'em_andamento' THEN
    SELECT id, cultura_id INTO v_next_id, v_next_cultura
      FROM public.talhao_safras
      WHERE talhao_id = OLD.talhao_id AND status = 'em_andamento' AND id <> OLD.id
      ORDER BY data_plantio DESC LIMIT 1;
    UPDATE public.talhoes
      SET safra_atual_id = v_next_id
      WHERE id = OLD.talhao_id;
    RETURN OLD;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.sync_talhao_safra_atual() OWNER TO postgres;

--
-- Name: sync_user_cliente_principal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sync_user_cliente_principal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_users uuid[] := '{}';
  v_principal uuid;
  v_marked uuid;
BEGIN
  -- Reconcilia TODOS os usuários afetados: NEW e OLD (UPDATE de user_id
  -- reconcilia o usuário antigo e o novo; nenhum dado é reatribuído).
  -- Coleta por evento: cada trigger statement só executa o branch cuja
  -- transition table existe (plpgsql planeja cada statement na 1ª execução).
  IF TG_OP = 'INSERT' THEN
    FOR v_user IN SELECT DISTINCT n.user_id FROM new_rows n LOOP
      v_users := v_users || v_user;
    END LOOP;
  ELSIF TG_OP = 'DELETE' THEN
    FOR v_user IN SELECT DISTINCT o.user_id FROM old_rows o LOOP
      v_users := v_users || v_user;
    END LOOP;
  ELSE
    FOR v_user IN
      SELECT n.user_id FROM new_rows n
      UNION
      SELECT o.user_id FROM old_rows o
    LOOP
      v_users := v_users || v_user;
    END LOOP;
  END IF;

  FOREACH v_user IN ARRAY v_users LOOP
    -- 1) Rebaixa principais não vigentes (inativo, revogado, futuro, expirado).
    --    Só emite UPDATE quando há trabalho: é o que encerra a recursão.
    IF EXISTS (
      SELECT 1 FROM public.user_clientes
       WHERE user_id = v_user AND principal = true
         AND NOT (is_active AND revoked_at IS NULL
                  AND valid_from <= now()
                  AND (valid_until IS NULL OR valid_until >= now()))
    ) THEN
      UPDATE public.user_clientes
         SET principal = false
       WHERE user_id = v_user
         AND principal = true
         AND NOT (is_active AND revoked_at IS NULL
                  AND valid_from <= now()
                  AND (valid_until IS NULL OR valid_until >= now()));
    END IF;

    -- 2) Principal explicitamente marcado e vigente neste comando vence;
    --    desempate determinístico (created_at, id) se houver mais de um
    IF TG_OP = 'DELETE' THEN
      v_marked := NULL;
    ELSE
      SELECT uc.id INTO v_marked
        FROM new_rows n
        JOIN public.user_clientes uc ON uc.id = n.id
       WHERE n.user_id = v_user AND n.principal
         AND uc.is_active AND uc.revoked_at IS NULL
         AND uc.valid_from <= now()
         AND (uc.valid_until IS NULL OR uc.valid_until >= now())
       ORDER BY uc.created_at ASC, uc.id ASC
       LIMIT 1;
    END IF;
    IF v_marked IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.user_clientes
                    WHERE user_id = v_user AND id <> v_marked AND principal = true) THEN
      UPDATE public.user_clientes
         SET principal = false
       WHERE user_id = v_user
         AND id <> v_marked
         AND principal = true;
    END IF;

    -- 3) Garante exatamente um principal vigente (mais antigo; desempate por id)
    IF NOT EXISTS (
      SELECT 1 FROM public.user_clientes
       WHERE user_id = v_user AND principal = true
         AND is_active AND revoked_at IS NULL
         AND valid_from <= now()
         AND (valid_until IS NULL OR valid_until >= now())
    ) AND EXISTS (
      SELECT 1 FROM public.user_clientes
       WHERE user_id = v_user
         AND is_active AND revoked_at IS NULL
         AND valid_from <= now()
         AND (valid_until IS NULL OR valid_until >= now())
    ) THEN
      UPDATE public.user_clientes
         SET principal = true
       WHERE id = (
         SELECT id FROM public.user_clientes
          WHERE user_id = v_user
            AND is_active AND revoked_at IS NULL
            AND valid_from <= now()
            AND (valid_until IS NULL OR valid_until >= now())
          ORDER BY created_at ASC, id ASC
          LIMIT 1
       );
    END IF;

    -- 4) profiles.cliente_id SOMENTE com principal vigente (ou NULL);
    --    nunca aponta para vínculo histórico/revogado
    SELECT cliente_id INTO v_principal
      FROM public.user_clientes
     WHERE user_id = v_user AND principal = true
       AND is_active AND revoked_at IS NULL
       AND valid_from <= now()
       AND (valid_until IS NULL OR valid_until >= now())
     LIMIT 1;

    IF EXISTS (SELECT 1 FROM public.profiles
                WHERE user_id = v_user AND cliente_id IS DISTINCT FROM v_principal) THEN
      UPDATE public.profiles
         SET cliente_id = v_principal
       WHERE user_id = v_user
         AND cliente_id IS DISTINCT FROM v_principal;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION public.sync_user_cliente_principal() OWNER TO postgres;

--
-- Name: technical_actor_ready(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_actor_ready(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 SELECT CASE WHEN p_user IS NULL OR p_user IS DISTINCT FROM auth.uid()
   OR COALESCE((auth.jwt()->>'iat') ~ '^[0-9]{1,10}$',false) IS FALSE THEN false
 ELSE CASE WHEN (auth.jwt()->>'iat')::bigint <= 0 THEN false
 ELSE platform_private.h15_actor_organization() IS NOT NULL
 AND platform_private.platform_actor_access_ready(p_user) END END;
$_$;


ALTER FUNCTION public.technical_actor_ready(p_user uuid) OWNER TO postgres;

--
-- Name: technical_attachment_download_snapshot(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_attachment_download_snapshot(_name text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
 WITH actor AS MATERIALIZED (
   SELECT auth.uid() AS uid, public.h15_actor_organization() AS org
   WHERE auth.uid() IS NOT NULL AND public.technical_actor_ready(auth.uid())
     AND public.storage1_path_strict(_name)
     AND _name ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/(foto|audio|documento)/[A-Za-z0-9_.-]+$'
     AND public.storage1_consultor_allowed(_name, 'select')
 ), roles AS MATERIALIZED (
   SELECT jsonb_agg(ur.role::text ORDER BY ur.role::text) AS value
   FROM public.user_roles ur JOIN actor a ON ur.user_id = a.uid
 ), docs AS MATERIALIZED (
   SELECT f.id, f.arquivo_path, r.id AS visit, r.cliente_id AS client, a.uid, a.org
   FROM public.registros_consultor_arquivos f
   JOIN public.registros_consultor r ON r.id = f.registro_consultor_id
   JOIN public.clientes c ON c.id = r.cliente_id
   JOIN actor a ON a.org = c.organization_id
   WHERE f.arquivo_path = _name
     AND split_part(_name, '/', 1) = a.org::text
     AND split_part(_name, '/', 2) = r.id::text
     AND public.technical_refs_in_actor_tenant(r.cliente_id, r.fazenda_id, r.talhao_id)
     AND public.technical_child_read_scope(r.id)
 )
 SELECT CASE WHEN (SELECT count(*) FROM docs) = 1
   AND jsonb_array_length(coalesce((SELECT value FROM roles), '[]'::jsonb)) > 0
 THEN (SELECT jsonb_build_object('actor', uid, 'tenant', org, 'roles', (SELECT value FROM roles),
   'document', id, 'visit', visit, 'client', client, 'path', arquivo_path,
   'size', NULL, 'mime', NULL) FROM docs) ELSE NULL END;
$_$;


ALTER FUNCTION public.technical_attachment_download_snapshot(_name text) OWNER TO postgres;

--
-- Name: technical_child_read_scope(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_child_read_scope(p_registro_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.can_view_technical_visit(auth.uid(),p_registro_id)
 OR (public.technical_actor_ready(auth.uid()) AND public.has_role(auth.uid(),'cliente_produtor')
 AND EXISTS (SELECT 1 FROM public.registros_consultor r
 WHERE r.id=p_registro_id
 AND public.technical_refs_in_actor_tenant(r.cliente_id,r.fazenda_id,r.talhao_id)
 AND r.cliente_id=ANY(public.get_cliente_ids_for_user(auth.uid()))
 AND r.status::text IN ('aprovado','finalizado','convertido_os')));
$$;


ALTER FUNCTION public.technical_child_read_scope(p_registro_id uuid) OWNER TO postgres;

--
-- Name: technical_client_link(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_client_link(p_user uuid, p_cliente uuid, p_levels text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.technical_actor_ready(p_user) AND EXISTS (
 SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p_user AND uc.cliente_id=p_cliente
 AND uc.is_active IS TRUE AND uc.revoked_at IS NULL
 AND (uc.valid_from IS NULL OR uc.valid_from<=now()) AND (uc.valid_until IS NULL OR uc.valid_until>=now())
 AND uc.access_level::text=ANY(p_levels));
$$;


ALTER FUNCTION public.technical_client_link(p_user uuid, p_cliente uuid, p_levels text[]) OWNER TO postgres;

--
-- Name: technical_refs_in_actor_tenant(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.technical_refs_in_actor_tenant(p_cliente uuid, p_fazenda uuid, p_talhao uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 SELECT public.technical_actor_ready(auth.uid())
 AND EXISTS (SELECT 1 FROM public.clientes c WHERE c.id=p_cliente AND c.organization_id=platform_private.h15_actor_organization())
 AND (p_fazenda IS NULL OR EXISTS (SELECT 1 FROM public.fazendas f WHERE f.id=p_fazenda AND f.cliente_id=p_cliente AND f.organization_id=platform_private.h15_actor_organization()))
 AND (p_talhao IS NULL OR (p_fazenda IS NOT NULL AND EXISTS (SELECT 1 FROM public.talhoes t WHERE t.id=p_talhao AND t.fazenda_id=p_fazenda AND t.organization_id=platform_private.h15_actor_organization())));
$$;


ALTER FUNCTION public.technical_refs_in_actor_tenant(p_cliente uuid, p_fazenda uuid, p_talhao uuid) OWNER TO postgres;

--
-- Name: tenant_admin_list_users(text, public.app_role, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tenant_admin_list_users(p_search text DEFAULT NULL::text, p_role public.app_role DEFAULT NULL::public.app_role, p_active boolean DEFAULT NULL::boolean, p_offset integer DEFAULT 0, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
DECLARE v_org uuid; v_total integer; v_items jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'administrador'::public.app_role) OR public.is_platform_superadmin(auth.uid()) THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 SELECT organization_id INTO v_org FROM public.profiles WHERE user_id=auth.uid() AND ativo=true;
 IF v_org IS NULL THEN RAISE EXCEPTION 'tenant_users_forbidden' USING ERRCODE='42501'; END IF;
 IF p_offset<0 OR p_limit<1 OR p_limit>100 THEN RAISE EXCEPTION 'tenant_users_invalid_pagination' USING ERRCODE='22023'; END IF;
 SELECT count(*) INTO v_total FROM public.profiles p WHERE p.organization_id=v_org AND (p_active IS NULL OR p.ativo=p_active) AND (NULLIF(btrim(p_search),'') IS NULL OR p.nome ILIKE '%'||btrim(p_search)||'%' OR p.email ILIKE '%'||btrim(p_search)||'%') AND (p_role IS NULL OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p.user_id AND ur.role=p_role)) AND NOT public.is_platform_superadmin(p.user_id);
 SELECT COALESCE(jsonb_agg(row_data ORDER BY created_at DESC,user_id),'[]'::jsonb) INTO v_items FROM (SELECT p.user_id,p.nome,p.email,p.telefone,p.cpf_cnpj,p.ativo,p.created_at,p.updated_at,p.cargo,p.crea,p.especialidade,COALESCE((SELECT jsonb_agg(ur.role ORDER BY ur.role::text) FROM public.user_roles ur WHERE ur.user_id=p.user_id),'[]'::jsonb) roles,EXISTS(SELECT 1 FROM public.user_clientes uc WHERE uc.user_id=p.user_id) has_client_links,EXISTS(SELECT 1 FROM public.partner_users pu WHERE pu.user_id=p.user_id) has_partner_link FROM public.profiles p WHERE p.organization_id=v_org AND (p_active IS NULL OR p.ativo=p_active) AND (NULLIF(btrim(p_search),'') IS NULL OR p.nome ILIKE '%'||btrim(p_search)||'%' OR p.email ILIKE '%'||btrim(p_search)||'%') AND (p_role IS NULL OR EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=p.user_id AND ur.role=p_role)) AND NOT public.is_platform_superadmin(p.user_id) ORDER BY p.created_at DESC,p.user_id OFFSET p_offset LIMIT p_limit) row_data;
 RETURN jsonb_build_object('items',v_items,'total',v_total,'organization_id',v_org);
END;
$$;


ALTER FUNCTION public.tenant_admin_list_users(p_search text, p_role public.app_role, p_active boolean, p_offset integer, p_limit integer) OWNER TO postgres;

--
-- Name: tenant_admin_set_user_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tenant_admin_set_user_active(p_user_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE v_count integer; v_admin_count integer;
BEGIN
 IF NOT platform_private.is_tenant_admin_for_user(p_user_id) THEN RAISE EXCEPTION 'user_status_forbidden' USING ERRCODE='42501'; END IF;
 IF p_user_id=auth.uid() AND p_active=false THEN RAISE EXCEPTION 'user_status_self_deactivation' USING ERRCODE='42501'; END IF;
 IF p_active=false AND public.has_role(p_user_id,'administrador'::public.app_role) THEN SELECT count(*) INTO v_admin_count FROM public.profiles p JOIN public.user_roles ur ON ur.user_id=p.user_id WHERE p.organization_id=platform_private.current_user_organization_id() AND p.ativo=true AND ur.role='administrador'::public.app_role; IF v_admin_count<=1 THEN RAISE EXCEPTION 'user_last_active_admin' USING ERRCODE='PT409'; END IF; END IF;
 UPDATE public.profiles SET ativo=p_active WHERE user_id=p_user_id; GET DIAGNOSTICS v_count=ROW_COUNT;
 IF v_count<>1 THEN RAISE EXCEPTION 'user_status_not_found' USING ERRCODE='P0002'; END IF;
 RETURN jsonb_build_object('success',true,'user_id',p_user_id,'active',p_active);
END; $$;


ALTER FUNCTION public.tenant_admin_set_user_active(p_user_id uuid, p_active boolean) OWNER TO postgres;

