--
-- Name: tg_entrega_reconc_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_entrega_reconc_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'entrega_reconciliacao_imutavel: delete proibido';
  END IF;
  IF NEW.entrega_id IS DISTINCT FROM OLD.entrega_id
     OR NEW.termo_id IS DISTINCT FROM OLD.termo_id
     OR NEW.itens_aceitos IS DISTINCT FROM OLD.itens_aceitos
     OR NEW.itens_recusados IS DISTINCT FROM OLD.itens_recusados
     OR NEW.quantidade_aceita IS DISTINCT FROM OLD.quantidade_aceita
     OR NEW.resumo IS DISTINCT FROM OLD.resumo
     OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint THEN
    RAISE EXCEPTION 'entrega_reconciliacao_imutavel: campos congelados';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_entrega_reconc_immutability() OWNER TO postgres;

--
-- Name: tg_entrega_termos_immutability(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_entrega_termos_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'rascunho' THEN
      RAISE EXCEPTION 'termo_imutavel: documento % nao pode ser excluido', OLD.id
        USING ERRCODE = 'raise_exception';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('assinado','cancelado','substituido') THEN
    IF NEW.snapshot IS DISTINCT FROM OLD.snapshot
       OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
       OR NEW.versao IS DISTINCT FROM OLD.versao
       OR NEW.template_versao IS DISTINCT FROM OLD.template_versao
       OR NEW.entrega_id IS DISTINCT FROM OLD.entrega_id
       OR NEW.recebedor_nome IS DISTINCT FROM OLD.recebedor_nome
       OR NEW.recebedor_documento IS DISTINCT FROM OLD.recebedor_documento
       OR NEW.assinatura_hash IS DISTINCT FROM OLD.assinatura_hash
       OR NEW.assinado_em IS DISTINCT FROM OLD.assinado_em
       OR NEW.assinado_por IS DISTINCT FROM OLD.assinado_por
       OR NEW.cobertura IS DISTINCT FROM OLD.cobertura THEN
      RAISE EXCEPTION 'termo_imutavel: documento assinado nao pode ser alterado'
        USING ERRCODE = 'raise_exception';
    END IF;
    -- PDF só pode ser gravado uma vez por versão
    IF OLD.pdf_path IS NOT NULL AND NEW.pdf_path IS DISTINCT FROM OLD.pdf_path THEN
      RAISE EXCEPTION 'termo_pdf_imutavel: ja existe PDF ativo para esta versao'
        USING ERRCODE = 'raise_exception';
    END IF;
    IF OLD.status <> 'assinado' AND NEW.status <> OLD.status THEN
      RAISE EXCEPTION 'termo_estado_terminal: transicao % -> % proibida', OLD.status, NEW.status
        USING ERRCODE = 'raise_exception';
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_entrega_termos_immutability() OWNER TO postgres;

--
-- Name: tg_fiscal_certificates_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_certificates_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_action text;
  v_old    jsonb;
  v_new    jsonb;
BEGIN
  v_action := TG_OP;
  IF TG_OP = 'INSERT' THEN
    v_old := '{}'::jsonb;
    v_new := jsonb_build_object(
      'source_type', NEW.source_type,
      'environment', NEW.environment,
      'status',      NEW.status,
      'display_name',NEW.display_name,
      'fingerprint_sha256', NEW.fingerprint_sha256,
      'valid_until', NEW.valid_until,
      'is_active',   NEW.is_active
    );
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := jsonb_build_object('status', OLD.status, 'is_active', OLD.is_active, 'valid_until', OLD.valid_until);
    v_new := jsonb_build_object('status', NEW.status, 'is_active', NEW.is_active, 'valid_until', NEW.valid_until);
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.fiscal_audit_log (
    table_name, record_id, action, changed_by, old_values, new_values
  ) VALUES (
    'fiscal_certificates', COALESCE(NEW.id, OLD.id), v_action, auth.uid(), v_old, v_new
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tg_fiscal_certificates_audit() OWNER TO postgres;

--
-- Name: tg_fiscal_cfs_audit(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_cfs_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_new   jsonb;
  v_old   jsonb;
BEGIN
  BEGIN
    v_actor := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_actor := NULL;
  END;

  IF TG_OP = 'INSERT' THEN
    v_new := jsonb_build_object(
      'id',                     NEW.id,
      'configuration_status',   NEW.configuration_status,
      'fiscal_environment',     NEW.fiscal_environment,
      'nfe_provider',           NEW.nfe_provider,
      'nfse_provider',          NEW.nfse_provider,
      'nfe_enabled',            NEW.nfe_enabled,
      'nfse_enabled',           NEW.nfse_enabled,
      'production_enabled',     NEW.production_enabled,
      'configuration_version',  NEW.configuration_version,
      'last_validation_status', NEW.last_validation_status,
      'nfe_config_field_count',  public.jsonb_object_keys_count(NEW.nfe_configuration),
      'nfse_config_field_count', public.jsonb_object_keys_count(NEW.nfse_configuration),
      'has_nfe_credential_ref',  (NEW.nfe_credential_ref  IS NOT NULL),
      'has_nfse_credential_ref', (NEW.nfse_credential_ref IS NOT NULL),
      'has_certificate_ref',     (NEW.certificate_ref     IS NOT NULL),
      'has_webhook_ref',         (NEW.webhook_ref         IS NOT NULL),
      'has_configuration_notes', (NEW.configuration_notes IS NOT NULL)
    );
    INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', v_actor, v_new);
    RETURN NEW;

  ELSIF TG_OP = 'UPDATE' THEN
    v_old := jsonb_build_object(
      'id',                     OLD.id,
      'configuration_status',   OLD.configuration_status,
      'fiscal_environment',     OLD.fiscal_environment,
      'nfe_provider',           OLD.nfe_provider,
      'nfse_provider',          OLD.nfse_provider,
      'nfe_enabled',            OLD.nfe_enabled,
      'nfse_enabled',           OLD.nfse_enabled,
      'production_enabled',     OLD.production_enabled,
      'configuration_version',  OLD.configuration_version,
      'last_validation_status', OLD.last_validation_status,
      'nfe_config_field_count',  public.jsonb_object_keys_count(OLD.nfe_configuration),
      'nfse_config_field_count', public.jsonb_object_keys_count(OLD.nfse_configuration),
      'has_nfe_credential_ref',  (OLD.nfe_credential_ref  IS NOT NULL),
      'has_nfse_credential_ref', (OLD.nfse_credential_ref IS NOT NULL),
      'has_certificate_ref',     (OLD.certificate_ref     IS NOT NULL),
      'has_webhook_ref',         (OLD.webhook_ref         IS NOT NULL),
      'has_configuration_notes', (OLD.configuration_notes IS NOT NULL)
    );
    v_new := jsonb_build_object(
      'id',                     NEW.id,
      'configuration_status',   NEW.configuration_status,
      'fiscal_environment',     NEW.fiscal_environment,
      'nfe_provider',           NEW.nfe_provider,
      'nfse_provider',          NEW.nfse_provider,
      'nfe_enabled',            NEW.nfe_enabled,
      'nfse_enabled',           NEW.nfse_enabled,
      'production_enabled',     NEW.production_enabled,
      'configuration_version',  NEW.configuration_version,
      'last_validation_status', NEW.last_validation_status,
      'nfe_config_field_count',  public.jsonb_object_keys_count(NEW.nfe_configuration),
      'nfse_config_field_count', public.jsonb_object_keys_count(NEW.nfse_configuration),
      'has_nfe_credential_ref',  (NEW.nfe_credential_ref  IS NOT NULL),
      'has_nfse_credential_ref', (NEW.nfse_credential_ref IS NOT NULL),
      'has_certificate_ref',     (NEW.certificate_ref     IS NOT NULL),
      'has_webhook_ref',         (NEW.webhook_ref         IS NOT NULL),
      'has_configuration_notes', (NEW.configuration_notes IS NOT NULL)
    );
    INSERT INTO public.fiscal_audit_log (table_name, record_id, action, changed_by, old_values, new_values)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', v_actor, v_old, v_new);
    RETURN NEW;
  END IF;

  -- DELETE não é auditado por este trigger (policy nega DELETE nesta tabela).
  RETURN NULL;
END;
$$;


ALTER FUNCTION public.tg_fiscal_cfs_audit() OWNER TO postgres;

--
-- Name: tg_fiscal_emitter_refresh_readiness(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_emitter_refresh_readiness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.nfe_readiness_pendencies := public.fn_fiscal_emitter_pendencies_row(NEW);
  NEW.nfe_readiness_status := CASE
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.nfe_readiness_pendencies) e WHERE e->>'severity'='BLOCK') THEN 'NOT_READY'
    WHEN jsonb_array_length(NEW.nfe_readiness_pendencies) > 0 THEN 'PARTIAL'
    ELSE 'READY_HOMOLOGATION' END;  -- teto absoluto da F3
  NEW.nfe_readiness_checked_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_fiscal_emitter_refresh_readiness() OWNER TO postgres;

--
-- Name: tg_fiscal_homologation_evidence_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_homologation_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.sefaz_homologation_at IS DISTINCT FROM OLD.sefaz_homologation_at)
     OR (NEW.sefaz_homologation_evidence IS DISTINCT FROM OLD.sefaz_homologation_evidence) THEN
    IF coalesce(current_setting('fiscal.homologation_ctx', true), '') <> 'controlled-rpc' THEN
      RAISE EXCEPTION 'FISCAL_HOMOLOGATION_EVIDENCE_IMMUTABLE: prova de homologacao SEFAZ nao pode ser alterada por UPDATE direto.'
        USING HINT = 'A transicao ocorrera somente por RPC controlada e auditada em fase posterior.';
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_fiscal_homologation_evidence_guard() OWNER TO postgres;

--
-- Name: tg_fiscal_invoice_sync_normalized_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_invoice_sync_normalized_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_norm text;
BEGIN
  v_norm := upper(btrim(coalesce(NEW.status, '')));
  v_norm := CASE v_norm
    WHEN 'PENDING'   THEN 'DRAFT'
    WHEN 'RASCUNHO'  THEN 'DRAFT'
    WHEN 'ISSUED'    THEN 'AUTHORIZED'   -- H7-003: emitida == autorizada
    WHEN 'EMITIDA'   THEN 'AUTHORIZED'
    WHEN 'AUTORIZADA' THEN 'AUTHORIZED'
    WHEN 'CANCELADA' THEN 'CANCELED'
    WHEN 'REJEITADA' THEN 'REJECTED'
    WHEN 'ERRO'      THEN 'ERROR'
    ELSE v_norm
  END;
  IF v_norm NOT IN ('LEGACY_RECORDED','DRAFT','VALIDATING','READY','QUEUED','PROCESSING',
                    'AUTHORIZED','REJECTED','ERROR','CANCEL_REQUESTED','CANCELED','SUBSTITUTED') THEN
    v_norm := COALESCE(NEW.normalized_status, 'DRAFT');
  END IF;
  NEW.normalized_status := v_norm;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tg_fiscal_invoice_sync_normalized_status() OWNER TO postgres;

--
-- Name: tg_fiscal_operation_policy_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_operation_policy_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.policy_status = 'PUBLISHED' THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao pode ser excluida (id=%)', OLD.id;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'PUBLISHED' THEN
    IF (OLD.cfop, OLD.nature_operation, OLD.direction, OLD.origin_uf, OLD.destination_uf,
        OLD.crt, OLD.ncm_prefix, OLD.final_consumer, OLD.taxpayer_indicator,
        OLD.valid_from, OLD.valid_until, OLD.source_id, OLD.legal_basis)
       IS DISTINCT FROM
       (NEW.cfop, NEW.nature_operation, NEW.direction, NEW.origin_uf, NEW.destination_uf,
        NEW.crt, NEW.ncm_prefix, NEW.final_consumer, NEW.taxpayer_indicator,
        NEW.valid_from, NEW.valid_until, NEW.source_id, NEW.legal_basis) THEN
      RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada e imutavel; crie nova vigencia (id=%)', OLD.id;
    END IF;
  END IF;
  IF OLD.policy_status = 'PUBLISHED' AND NEW.policy_status = 'DRAFT' THEN
    RAISE EXCEPTION 'FISCAL_POLICY_IMMUTABLE: politica publicada nao retorna a DRAFT (id=%)', OLD.id;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_fiscal_operation_policy_immutable() OWNER TO postgres;

--
-- Name: tg_fiscal_recipient_refresh_readiness(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_recipient_refresh_readiness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.nfe_readiness_pendencies := public.fn_fiscal_recipient_pendencies_row(NEW);
  NEW.nfe_readiness_status := CASE
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.nfe_readiness_pendencies) e WHERE e->>'severity'='BLOCK') THEN 'NOT_READY'
    WHEN jsonb_array_length(NEW.nfe_readiness_pendencies) > 0 THEN 'PARTIAL'
    ELSE 'READY' END;
  NEW.nfe_readiness_checked_at := now();
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_fiscal_recipient_refresh_readiness() OWNER TO postgres;

--
-- Name: tg_fiscal_reservation_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_reservation_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'FISCAL_RESERVATION_IMMUTABLE: reservas de numeracao nao podem ser excluidas.';
  END IF;
  IF NEW.series_id IS DISTINCT FROM OLD.series_id
     OR NEW.number IS DISTINCT FROM OLD.number
     OR NEW.cnf IS DISTINCT FROM OLD.cnf
     OR NEW.access_key IS DISTINCT FROM OLD.access_key
     OR NEW.check_digit IS DISTINCT FROM OLD.check_digit
     OR NEW.fiscal_invoice_id IS DISTINCT FROM OLD.fiscal_invoice_id
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.tp_emis IS DISTINCT FROM OLD.tp_emis THEN
    RAISE EXCEPTION 'FISCAL_RESERVATION_IMMUTABLE: numero, chave de acesso e vinculo do documento sao imutaveis.';
  END IF;
  IF OLD.status = 'RELEASED' AND NEW.status <> 'RELEASED' THEN
    RAISE EXCEPTION 'FISCAL_RESERVATION_IMMUTABLE: reserva liberada nao retorna ao estado reservado.';
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION public.tg_fiscal_reservation_immutable() OWNER TO postgres;

--
-- Name: tg_fiscal_tax_rule_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_tax_rule_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao pode ser excluida (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    RETURN OLD;
  END IF;

  -- H7-101: máquina de estados fechada. Nenhum caminho reabilita histórico.
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    IF NOT (
         (OLD.status = 'DRAFT'     AND NEW.status IN ('PUBLISHED'))
      OR (OLD.status = 'PUBLISHED' AND NEW.status = 'SUPERSEDED')
    ) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_STATUS_TRANSITION_FORBIDDEN: % -> % nao permitido (rule_key=% v=%)',
        OLD.status, NEW.status, OLD.rule_key, OLD.version
        USING HINT = 'Regra arquivada nunca volta a vigorar. Crie nova versao DRAFT e publique via rpc_fiscal_tax_rule_publish.';
    END IF;
    -- Publicação só pelo fluxo canônico (fonte oficial + SoD + aprovador).
    IF NEW.status = 'PUBLISHED' AND (NEW.published_by IS NULL OR NEW.published_at IS NULL) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_PUBLISH_CHANNEL: publicacao exige rpc_fiscal_tax_rule_publish (autoria/aprovacao obrigatorias).';
    END IF;
  END IF;

  -- H7-101: conteúdo de versão publicada OU arquivada é imutável.
  IF OLD.status IN ('PUBLISHED','SUPERSEDED') THEN
    IF OLD.status = 'PUBLISHED' AND NEW.status = 'DRAFT' THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: versao publicada nao retorna a DRAFT (rule_key=% v=%)', OLD.rule_key, OLD.version;
    END IF;
    IF (OLD.tax_kind, OLD.calc_mode, OLD.crt, OLD.origin_uf, OLD.destination_uf, OLD.ncm_prefix,
        OLD.product_category, OLD.final_consumer, OLD.taxpayer_indicator, OLD.cst, OLD.csosn,
        OLD.rate, OLD.base_reduction_pct, OLD.deferral_pct, OLD.mva_pct, OLD.fcp_rate,
        OLD.difal_dest_share_pct, OLD.legal_basis, OLD.source_id, OLD.valid_from, OLD.valid_until, OLD.version)
       IS DISTINCT FROM
       (NEW.tax_kind, NEW.calc_mode, NEW.crt, NEW.origin_uf, NEW.destination_uf, NEW.ncm_prefix,
        NEW.product_category, NEW.final_consumer, NEW.taxpayer_indicator, NEW.cst, NEW.csosn,
        NEW.rate, NEW.base_reduction_pct, NEW.deferral_pct, NEW.mva_pct, NEW.fcp_rate,
        NEW.difal_dest_share_pct, NEW.legal_basis, NEW.source_id, NEW.valid_from, NEW.valid_until, NEW.version) THEN
      RAISE EXCEPTION 'FISCAL_TAX_RULE_IMMUTABLE: conteudo de versao % e imutavel; crie nova versao (rule_key=% v=%)',
        OLD.status, OLD.rule_key, OLD.version;
    END IF;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END
$$;


ALTER FUNCTION public.tg_fiscal_tax_rule_immutable() OWNER TO postgres;

--
-- Name: tg_fiscal_xml_runs_immutable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tg_fiscal_xml_runs_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: execucoes de XML sao append-only; DELETE proibido.';
  END IF;

  IF coalesce(current_setting('app.fiscal_xml_engine', true),'off') <> 'on' THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: atualize execucoes apenas via rpc_fiscal_xml_record_v1.';
  END IF;

  IF NEW.id <> OLD.id
     OR NEW.fiscal_invoice_id <> OLD.fiscal_invoice_id
     OR NEW.idempotency_key <> OLD.idempotency_key
     OR NEW.run_version <> OLD.run_version
     OR NEW.payload_sha256 <> OLD.payload_sha256
     OR NEW.payload::text <> OLD.payload::text
     OR NEW.access_key <> OLD.access_key
     OR NEW.environment_code <> OLD.environment_code
     OR NEW.engine_version <> OLD.engine_version
     OR NEW.prepared_at <> OLD.prepared_at
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.previous_run_id IS DISTINCT FROM OLD.previous_run_id THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: campos congelados nao podem ser alterados.';
  END IF;

  IF OLD.unsigned_sha256 IS NOT NULL AND NEW.unsigned_sha256 IS DISTINCT FROM OLD.unsigned_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_sha256 IS NOT NULL AND NEW.signed_sha256 IS DISTINCT FROM OLD.signed_sha256 THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: hash do XML assinado ja registrado.';
  END IF;
  IF OLD.unsigned_path IS NOT NULL AND NEW.unsigned_path IS DISTINCT FROM OLD.unsigned_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML nao assinado ja registrado.';
  END IF;
  IF OLD.signed_path IS NOT NULL AND NEW.signed_path IS DISTINCT FROM OLD.signed_path THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_IMMUTABLE: caminho do XML assinado ja registrado.';
  END IF;

  IF OLD.state IN ('SIGNED','FAILED') AND NEW.state <> OLD.state THEN
    RAISE EXCEPTION 'FISCAL_XML_RUN_TERMINAL: execucao % ja esta em estado terminal %.', OLD.id, OLD.state;
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.tg_fiscal_xml_runs_immutable() OWNER TO postgres;

