--
-- Name: update_microorganism_b2b_description(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_microorganism_b2b_description(p_profile_id uuid, p_explicacao_b2b text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_b2b boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT (
    has_role(v_uid, 'administrador'::app_role)
    OR has_role(v_uid, 'gestor'::app_role)
    OR has_role(v_uid, 'gestor_comercial'::app_role)
  ) THEN
    RAISE EXCEPTION 'permission denied';
  END IF;

  IF has_role(v_uid, 'gestor_comercial'::app_role)
     AND NOT (has_role(v_uid, 'administrador'::app_role) OR has_role(v_uid, 'gestor'::app_role)) THEN
    SELECT m.b2b_enabled INTO v_b2b
    FROM public.microorganism_technical_profiles tp
    JOIN public.microrganismos m ON m.id = tp.microrganismo_id
    WHERE tp.id = p_profile_id;
    IF NOT COALESCE(v_b2b, false) THEN
      RAISE EXCEPTION 'microrganismo não habilitado para B2B';
    END IF;
  END IF;

  UPDATE public.microorganism_technical_profiles
  SET explicacao_b2b = p_explicacao_b2b,
      updated_by = v_uid,
      updated_at = now()
  WHERE id = p_profile_id;
END;
$$;


ALTER FUNCTION public.update_microorganism_b2b_description(p_profile_id uuid, p_explicacao_b2b text) OWNER TO postgres;

--
-- Name: update_partner_order_notes(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_partner_order_notes(p_order_id uuid, p_commercial_notes text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_pid uuid; v_prev text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  SELECT partner_id, commercial_notes INTO v_pid, v_prev
    FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  UPDATE public.partner_orders
     SET commercial_notes = NULLIF(p_commercial_notes,''), updated_at = now()
   WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'commercial_notes_updated',
          jsonb_build_object('commercial_notes', v_prev),
          jsonb_build_object('commercial_notes', p_commercial_notes));
END;
$$;


ALTER FUNCTION public.update_partner_order_notes(p_order_id uuid, p_commercial_notes text) OWNER TO postgres;

--
-- Name: update_partner_order_status(uuid, public.partner_order_status, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.update_partner_order_status(p_order_id uuid, p_status public.partner_order_status, p_motivo text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_prev partner_order_status;
  v_pid uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF NOT (has_role(v_uid,'administrador') OR has_role(v_uid,'gestor_comercial')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT status, partner_id INTO v_prev, v_pid FROM public.partner_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;

  IF v_prev = p_status THEN RETURN; END IF;

  -- estados terminais não retornam por esta via
  IF v_prev IN ('reprovado','cancelado','reprovado_sem_itens') THEN
    RAISE EXCEPTION 'order_terminal_status: %', v_prev USING ERRCODE = 'check_violation';
  END IF;

  -- etapas operacionais/financeiras exigem aprovação prévia
  IF public.fn_b2b_status_is_operational(p_status)
     AND NOT public.fn_b2b_status_is_approved_or_later(v_prev) THEN
    RAISE EXCEPTION 'status_requires_approved_order: % -> %', v_prev, p_status
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.partner_orders SET status = p_status, updated_at = now() WHERE id = p_order_id;

  INSERT INTO public.partner_order_audit_logs(order_id, partner_id, usuario_id, acao, dados_anteriores, dados_novos)
  VALUES (p_order_id, v_pid, v_uid, 'status_changed',
          jsonb_build_object('status', v_prev),
          jsonb_build_object('status', p_status, 'motivo', p_motivo));
END;
$$;


ALTER FUNCTION public.update_partner_order_status(p_order_id uuid, p_status public.partner_order_status, p_motivo text) OWNER TO postgres;

