    CONSTRAINT mnc_approved_evidence_chk CHECK (((status <> 'APPROVED'::text) OR ((source_id IS NOT NULL) AND (length(btrim(COALESCE(official_description, ''::text))) >= 10) AND (NULLIF(btrim(COALESCE(table_version, ''::text)), ''::text) IS NOT NULL) AND (table_reference_date IS NOT NULL)))),
