    CONSTRAINT mrd_mapa_status_chk CHECK (((mapa_status IS NULL) OR (mapa_status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'EXPIRED'::text, 'IN_PROCESS'::text, 'NOT_APPLICABLE'::text])))),
