    CONSTRAINT mrd_review_status_chk CHECK (((technical_review_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text])) AND (regulatory_review_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text])) AND (fiscal_review_status = ANY (ARRAY['PENDING'::text, 'APPROVED'::text, 'REJECTED'::text])))),
    CONSTRAINT mrd_sod_override_chk CHECK (((NOT sod_override_active) OR ((sod_override_by IS NOT NULL) AND (sod_override_at IS NOT NULL) AND (length(btrim(COALESCE(sod_override_reason, ''::text))) >= 40)))),
    CONSTRAINT mrd_soft_delete_chk CHECK (((deleted_at IS NULL) = (deleted_by IS NULL))),
    CONSTRAINT mrd_status_chk CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PENDING_REVIEW'::text, 'VALIDATED'::text, 'BLOCKED'::text]))),
