    protocolo_nome text,
    lote_codigo text NOT NULL,
    volume numeric,
    unidade text,
    quantidade_embalagens integer,
    cepas text[],
    composicao_resumida text,
    fabricado_em date,
    validade_em date,
    conservacao text,
    uso_recomendado text,
    observacoes text,
    trace_token uuid DEFAULT gen_random_uuid() NOT NULL,
    trace_hash text,
    trace_url text,
    qr_code_payload text,
    qr_code_path text,
    qr_code_generated_at timestamp with time zone,
    public_trace_enabled boolean DEFAULT true NOT NULL,
    trace_expires_at timestamp with time zone,
    gerada_por uuid,
    impressa_por uuid,
    ultima_reimpressao_por uuid,
