    substituida_por_id uuid,
    CONSTRAINT produto_etiquetas_status_chk CHECK ((status = ANY (ARRAY['gerada'::text, 'impressa'::text, 'reimpressa'::text, 'cancelada'::text, 'substituida'::text]))),
    CONSTRAINT produto_etiquetas_tipo_chk CHECK ((tipo_etiqueta = ANY (ARRAY['principal'::text, 'reduzida'::text, 'caixa'::text, 'transporte'::text, 'amostra'::text, 'interna'::text])))
);


