    installment_id uuid NOT NULL,
    payment_date date DEFAULT CURRENT_DATE NOT NULL,
    amount_received numeric(14,2) NOT NULL,
    payment_method_id uuid NOT NULL,
    bank_account_id uuid,
    discount_amount numeric(14,2) DEFAULT 0 NOT NULL,
    interest_amount numeric(14,2) DEFAULT 0 NOT NULL,
    penalty_amount numeric(14,2) DEFAULT 0 NOT NULL,
    notes text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    is_reversal boolean DEFAULT false NOT NULL,
    reversed_payment_id uuid,
    reversal_reason text,
    idempotency_key text,
    request_fingerprint text,
    organization_id uuid,
    CONSTRAINT receivable_payments_amount_sign_check CHECK ((((COALESCE(is_reversal, false) = false) AND (amount_received > (0)::numeric)) OR ((is_reversal = true) AND (amount_received < (0)::numeric)))),
    CONSTRAINT receivable_payments_reversal_consistency_check CHECK ((((COALESCE(is_reversal, false) = false) AND (reversed_payment_id IS NULL)) OR ((is_reversal = true) AND (reversed_payment_id IS NOT NULL))))
);


ALTER TABLE public.receivable_payments OWNER TO postgres;

