--
-- Name: recurring_financial_templates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.recurring_financial_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    type text NOT NULL,
    name text NOT NULL,
    customer_id uuid,
    supplier_id uuid,
    supplier_name text,
    category_id uuid NOT NULL,
    cost_center_id uuid,
    amount numeric(14,2) NOT NULL,
    installment_count integer DEFAULT 1 NOT NULL,
    recurrence_frequency text NOT NULL,
    due_day integer,
    start_date date NOT NULL,
    end_date date,
    next_generation_date date NOT NULL,
    active boolean DEFAULT true NOT NULL,
    auto_generate boolean DEFAULT true NOT NULL,
    payment_method_id uuid,
    bank_account_id uuid,
    notes text,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    description text NOT NULL,
    paused_at timestamp with time zone,
    fiscal_invoice_required boolean DEFAULT false,
    adjustment_type text,
    adjustment_value numeric(10,4),
    adjustment_index_name text,
    last_adjustment_date date,
    next_adjustment_date date,
    organization_id uuid DEFAULT platform_private.h15_actor_organization(),
    CONSTRAINT chk_recurring_customer_required CHECK (((type <> 'RECEIVABLE'::text) OR (customer_id IS NOT NULL))),
    CONSTRAINT chk_recurring_end_after_start CHECK (((end_date IS NULL) OR (end_date >= start_date))),
    CONSTRAINT recurring_financial_templates_adjustment_type_check CHECK ((adjustment_type = ANY (ARRAY['PERCENTAGE'::text, 'INDEX'::text, 'FIXED'::text]))),
    CONSTRAINT recurring_financial_templates_amount_check CHECK ((amount >= (0)::numeric)),
    CONSTRAINT recurring_financial_templates_due_day_check CHECK (((due_day >= 1) AND (due_day <= 31))),
    CONSTRAINT recurring_financial_templates_installment_count_check CHECK ((installment_count >= 1)),
    CONSTRAINT recurring_financial_templates_recurrence_frequency_check CHECK ((recurrence_frequency = ANY (ARRAY['WEEKLY'::text, 'MONTHLY'::text, 'BIMONTHLY'::text, 'QUARTERLY'::text, 'SEMIANNUAL'::text, 'ANNUAL'::text]))),
    CONSTRAINT recurring_financial_templates_type_check CHECK ((type = ANY (ARRAY['RECEIVABLE'::text, 'PAYABLE'::text])))
);


ALTER TABLE public.recurring_financial_templates OWNER TO postgres;

