    archive_reason text,
    CONSTRAINT saas_plan_versions_archive_shape CHECK (((status <> 'ARCHIVED'::text) OR ((archived_at IS NOT NULL) AND (archived_by IS NOT NULL) AND (length(btrim(archive_reason)) >= 5)))),
    CONSTRAINT saas_plan_versions_currency_format CHECK (((currency IS NULL) OR (currency ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT saas_plan_versions_cycle_valid CHECK (((billing_cycle IS NULL) OR (billing_cycle = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'semiannual'::text, 'annual'::text, 'custom'::text])))),
    CONSTRAINT saas_plan_versions_features_array CHECK ((jsonb_typeof(features_snapshot) = 'array'::text)),
    CONSTRAINT saas_plan_versions_limits_object CHECK ((jsonb_typeof(limits_snapshot) = 'object'::text)),
    CONSTRAINT saas_plan_versions_number_positive CHECK ((version_number > 0)),
    CONSTRAINT saas_plan_versions_period_valid CHECK (((effective_to IS NULL) OR (effective_to > effective_from))),
    CONSTRAINT saas_plan_versions_price_nonnegative CHECK (((price_amount IS NULL) OR (price_amount >= (0)::numeric))),
    CONSTRAINT saas_plan_versions_publication_reason_length CHECK (((publication_reason IS NULL) OR ((char_length(btrim(publication_reason)) >= 2) AND (char_length(btrim(publication_reason)) <= 500)))),
    CONSTRAINT saas_plan_versions_publish_shape CHECK (((status = 'DRAFT'::text) OR ((price_amount IS NOT NULL) AND (currency IS NOT NULL) AND (billing_cycle IS NOT NULL) AND (trial_days IS NOT NULL) AND (effective_from IS NOT NULL) AND (published_at IS NOT NULL) AND (jsonb_typeof(limits_snapshot) = 'object'::text) AND (jsonb_array_length(features_snapshot) > 0)))),
    CONSTRAINT saas_plan_versions_revision_positive CHECK ((revision > 0)),
    CONSTRAINT saas_plan_versions_status_valid CHECK ((status = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text]))),
    CONSTRAINT saas_plan_versions_trial_days_valid CHECK (((trial_days IS NULL) OR ((trial_days >= 1) AND (trial_days <= 365))))
);


ALTER TABLE public.saas_plan_versions OWNER TO postgres;

