--
-- Name: v_fiscal_certificate_readiness; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fiscal_certificate_readiness AS
 SELECT id AS certificate_id,
    company_settings_id,
    source_type,
    environment,
    status,
    display_name,
    subject_name,
    issuer_name,
    valid_from,
    valid_until,
    fingerprint_sha256,
    is_active,
    revoked_at,
        CASE
            WHEN (valid_until IS NULL) THEN NULL::integer
            ELSE GREATEST(0, (EXTRACT(day FROM (valid_until - now())))::integer)
        END AS days_until_expiration
   FROM public.fiscal_certificates fc;


ALTER VIEW public.v_fiscal_certificate_readiness OWNER TO postgres;

--
-- Name: v_fiscal_company_readiness; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fiscal_company_readiness AS
 SELECT id,
    configuration_status,
    nfe_enabled,
    nfse_enabled,
    production_enabled,
    fiscal_environment,
    fiscal_provider,
    ((((((((((((((((((cnpj IS NOT NULL))::integer + ((legal_name IS NOT NULL))::integer) + ((trade_name IS NOT NULL))::integer) + ((fiscal_email IS NOT NULL))::integer) + ((tax_regime IS NOT NULL))::integer) + ((crt IS NOT NULL))::integer) + ((primary_cnae IS NOT NULL))::integer) + ((municipal_registration IS NOT NULL))::integer) + ((state_registration IS NOT NULL))::integer) + ((municipality_ibge_code IS NOT NULL))::integer) + ((postal_code IS NOT NULL))::integer) + ((street IS NOT NULL))::integer) + ((number IS NOT NULL))::integer) + ((neighborhood IS NOT NULL))::integer) + ((city IS NOT NULL))::integer) + ((state IS NOT NULL))::integer) + ((country_code IS NOT NULL))::integer) AS filled_score,
    17 AS max_score,
    (accounting_validated_at IS NOT NULL) AS accounting_validated,
    nfe_provider,
    nfse_provider,
    configuration_version,
    last_validation_status,
    last_validation_at,
    public.jsonb_object_keys_count(nfe_configuration) AS nfe_configuration_field_count,
    public.jsonb_object_keys_count(nfse_configuration) AS nfse_configuration_field_count
   FROM public.company_fiscal_settings
  WHERE (is_active = true);


ALTER VIEW public.v_fiscal_company_readiness OWNER TO postgres;

--
-- Name: v_fiscal_document_reconciliation_pending; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fiscal_document_reconciliation_pending AS
 SELECT id AS fiscal_invoice_id,
    receivable_id,
    reconciliation_status,
