    status,
    normalized_status
   FROM public.fiscal_invoices
  WHERE ((reconciliation_status = ANY (ARRAY['PENDING'::text, 'DIVERGENT'::text, 'REQUIRES_REVIEW'::text])) AND (platform_private.has_role(auth.uid(), 'administrador'::public.app_role) OR platform_private.has_role(auth.uid(), 'gestor'::public.app_role) OR platform_private.has_role(auth.uid(), 'financeiro'::public.app_role)));


ALTER VIEW public.v_fiscal_document_reconciliation_pending OWNER TO postgres;

