ALTER VIEW public.v_fiscal_nfe_rule_coverage OWNER TO postgres;

--
-- Name: v_fiscal_sefaz_event_state; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_fiscal_sefaz_event_state AS
 SELECT p.id AS event_id,
    p.fiscal_invoice_id,
    p.event_type,
    p.sefaz_event_code,
    p.sefaz_seq_evento,
    p.sefaz_access_key,
    p.sefaz_reason,
    p.idempotency_key,
    p.payload_fingerprint,
    p.performed_by,
    p.created_at,
    s.signed_xml_path,
    s.signed_xml_sha256,
    r.sefaz_c_stat,
    r.sefaz_n_prot,
        CASE
            WHEN (r.event_type = 'SEFAZ_EVENT_REGISTERED'::text) THEN 'REGISTERED'::text
            WHEN (r.event_type = 'SEFAZ_EVENT_REJECTED'::text) THEN 'REJECTED'::text
            WHEN (s.id IS NOT NULL) THEN 'SIGNED'::text
            ELSE 'PREPARED'::text
        END AS state
   FROM ((public.fiscal_events p
     LEFT JOIN LATERAL ( SELECT e.id,
            e.fiscal_invoice_id,
            e.event_type,
            e.status_before,
            e.status_after,
            e.event_source,
            e.provider_event_id,
            e.request_snapshot,
            e.response_snapshot,
            e.error_code,
            e.error_message,
            e.performed_by,
            e.created_at,
            e.notes,
            e.idempotency_key,
            e.payload_fingerprint,
            e.related_event_id,
            e.sefaz_event_code,
            e.sefaz_seq_evento,
            e.sefaz_access_key,
            e.sefaz_reason,
            e.signed_xml_path,
            e.signed_xml_sha256,
            e.sefaz_c_stat,
            e.sefaz_n_prot,
            e.sefaz_transmission_id
           FROM public.fiscal_events e
          WHERE ((e.related_event_id = p.id) AND (e.event_type = 'SEFAZ_EVENT_SIGNED'::text))
          ORDER BY e.created_at DESC
         LIMIT 1) s ON (true))
     LEFT JOIN LATERAL ( SELECT e.id,
            e.fiscal_invoice_id,
            e.event_type,
            e.status_before,
            e.status_after,
            e.event_source,
            e.provider_event_id,
            e.request_snapshot,
            e.response_snapshot,
            e.error_code,
            e.error_message,
            e.performed_by,
            e.created_at,
            e.notes,
            e.idempotency_key,
            e.payload_fingerprint,
            e.related_event_id,
            e.sefaz_event_code,
            e.sefaz_seq_evento,
            e.sefaz_access_key,
            e.sefaz_reason,
            e.signed_xml_path,
            e.signed_xml_sha256,
            e.sefaz_c_stat,
            e.sefaz_n_prot,
            e.sefaz_transmission_id
           FROM public.fiscal_events e
          WHERE ((e.related_event_id = p.id) AND (e.event_type = ANY (ARRAY['SEFAZ_EVENT_REGISTERED'::text, 'SEFAZ_EVENT_REJECTED'::text])))
          ORDER BY e.created_at DESC
         LIMIT 1) r ON (true))
  WHERE (p.event_type = ANY (ARRAY['SEFAZ_CANCELLATION_PREPARED'::text, 'SEFAZ_CORRECTION_PREPARED'::text]));


ALTER VIEW public.v_fiscal_sefaz_event_state OWNER TO postgres;

--
-- Name: v_microorganism_fiscal_readiness; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_microorganism_fiscal_readiness AS
 SELECT m.id AS microorganism_id,
    m.codigo,
    m.nome,
    m.ativo,
    sel.id AS profile_id,
    sel.profile_status,
    sel.is_active AS profile_is_active,
    ((g.gate ->> 'ready'::text))::boolean AS fiscally_ready,
    ((g.gate ->> 'technical_ready'::text))::boolean AS minimally_classified,
    ((g.gate ->> 'regulatory_ready'::text))::boolean AS regulatory_ready,
    (sel.accounting_validated_at IS NOT NULL) AS accounting_validated,
    ((g.gate ->> 'quarantined'::text))::boolean AS quarantined,
    (reg.facts -> 'dossier_id'::text) AS dossier_id,
    (reg.facts ->> 'status'::text) AS dossier_status,
    (g.gate -> 'pendencies'::text) AS pendencies,
    (g.gate -> 'not_applicable'::text) AS not_applicable,
    g.gate
   FROM (((public.microrganismos m
     LEFT JOIN LATERAL ( SELECT mfp.id,
            mfp.microorganism_id,
            mfp.is_active,
            mfp.fiscal_description,
            mfp.commercial_unit,
            mfp.taxable_unit,
            mfp.ncm,
            mfp.cest,
            mfp.origin_code,
            mfp.cfop_in_state,
            mfp.cfop_interstate,
            mfp.icms_cst,
            mfp.icms_csosn,
            mfp.pis_cst,
            mfp.cofins_cst,
            mfp.ipi_cst,
            mfp.gtin,
            mfp.taxable_gtin,
            mfp.tax_benefit_code,
            mfp.profile_status,
            mfp.accounting_notes,
            mfp.accounting_validated_at,
            mfp.accounting_validated_by,
            mfp.created_at,
            mfp.updated_at,
            mfp.created_by,
            mfp.updated_by
           FROM public.microorganism_fiscal_profiles mfp
          WHERE (mfp.microorganism_id = m.id)
          ORDER BY (mfp.is_active AND (mfp.profile_status = 'VALIDATED'::text)) DESC, mfp.is_active DESC, mfp.updated_at DESC NULLS LAST, mfp.created_at DESC NULLS LAST, mfp.id DESC
         LIMIT 1) sel ON (true))
     CROSS JOIN LATERAL ( SELECT public.fn_microorganism_regulatory_facts(m.id) AS facts) reg)
     CROSS JOIN LATERAL ( SELECT public.fn_fiscal_item_profile_gate_eval('MICROORGANISM'::text, public.fn_fiscal_company_crt(), sel.is_active, sel.profile_status, sel.accounting_validated_at, sel.accounting_notes, sel.fiscal_description, sel.commercial_unit, sel.taxable_unit, sel.ncm, sel.origin_code, sel.cfop_in_state, sel.cfop_interstate, sel.icms_cst, sel.icms_csosn, sel.pis_cst, sel.cofins_cst, reg.facts) AS gate) g);


ALTER VIEW public.v_microorganism_fiscal_readiness OWNER TO postgres;

--
-- Name: v_product_fiscal_readiness; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_product_fiscal_readiness AS
 SELECT sel.product_id,
    sel.id AS profile_id,
    sel.profile_status,
    sel.is_active AS profile_is_active,
    ((g.gate ->> 'technical_ready'::text))::boolean AS minimally_classified,
    (sel.accounting_validated_at IS NOT NULL) AS accounting_validated,
    ((g.gate ->> 'quarantined'::text))::boolean AS quarantined,
    ((g.gate ->> 'ready'::text))::boolean AS fiscally_ready,
    (g.gate -> 'pendencies'::text) AS pendencies,
    g.gate
   FROM (( SELECT DISTINCT ON (p.product_id) p.id,
            p.product_id,
            p.is_active,
            p.fiscal_description,
            p.commercial_unit,
            p.taxable_unit,
            p.ncm,
            p.cest,
            p.origin_code,
            p.cfop_in_state,
            p.cfop_interstate,
            p.icms_cst,
            p.icms_csosn,
            p.pis_cst,
            p.cofins_cst,
            p.ipi_cst,
            p.gtin,
            p.taxable_gtin,
            p.tax_benefit_code,
            p.approximate_tax_source,
            p.profile_status,
            p.accounting_notes,
            p.accounting_validated_at,
            p.accounting_validated_by,
            p.created_at,
            p.updated_at,
            p.created_by,
            p.updated_by,
            p.ibs_cbs_configuration
           FROM public.product_fiscal_profiles p
          ORDER BY p.product_id, (p.is_active AND (p.profile_status = 'VALIDATED'::text)) DESC, p.is_active DESC, p.updated_at DESC NULLS LAST, p.created_at DESC NULLS LAST, p.id DESC) sel
     CROSS JOIN LATERAL ( SELECT public.fn_fiscal_item_profile_gate_eval('PRODUCT'::text, public.fn_fiscal_company_crt(), sel.is_active, sel.profile_status, sel.accounting_validated_at, sel.accounting_notes, sel.fiscal_description, sel.commercial_unit, sel.taxable_unit, sel.ncm, sel.origin_code, sel.cfop_in_state, sel.cfop_interstate, sel.icms_cst, sel.icms_csosn, sel.pis_cst, sel.cofins_cst, NULL::jsonb) AS gate) g);


ALTER VIEW public.v_product_fiscal_readiness OWNER TO postgres;

--
-- Name: v_service_fiscal_readiness; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_service_fiscal_readiness AS
 SELECT id,
    service_id,
    source_reference,
    profile_status,
    ((lc116_item IS NOT NULL) AND (cnae IS NOT NULL)) AS minimally_classified,
    (accounting_validated_at IS NOT NULL) AS accounting_validated
   FROM public.service_fiscal_profiles
  WHERE (is_active = true);


