--
-- Name: vw_bi_commercial_campaigns; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_bi_commercial_campaigns AS
 SELECT id,
    nome,
    data_inicio,
    data_fim,
    ativa,
    ( SELECT count(*) AS count
           FROM public.commercial_campaign_partners cp
          WHERE (cp.campaign_id = c.id)) AS qtd_parceiros,
    ( SELECT count(*) AS count
           FROM public.commercial_campaign_products cpp
          WHERE (cpp.campaign_id = c.id)) AS qtd_produtos
   FROM public.commercial_campaigns c;


