--
-- Name: vw_bi_commercial_engagement; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_bi_commercial_engagement AS
 SELECT pa.id AS partner_id,
    pa.razao_social,
    pa.partner_type,
    pa.commercial_region,
    pem.ultima_compra,
    pem.dias_sem_compra,
    pem.pedidos_30d,
    pem.pedidos_90d
   FROM (public.partner_accounts pa
     LEFT JOIN public.partner_engagement_metrics pem ON ((pem.partner_id = pa.id)));


ALTER VIEW public.vw_bi_commercial_engagement OWNER TO postgres;

--
-- Name: vw_bi_commercial_revenue; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_bi_commercial_revenue AS
 SELECT (date_trunc('month'::text, po.created_at))::date AS mes,
    pa.id AS partner_id,
    pa.razao_social,
    pa.commercial_region,
    pa.partner_type,
    count(po.id) AS qtd_pedidos,
    COALESCE(sum(po.total), (0)::numeric) AS receita_total,
    COALESCE(sum(po.total) FILTER (WHERE ((po.status)::text = ANY (ARRAY['aprovado'::text, 'em_producao'::text, 'pronto_entrega'::text, 'entregue'::text, 'faturado'::text]))), (0)::numeric) AS receita_aprovada,
    COALESCE(sum(po.total) FILTER (WHERE ((po.status)::text = 'faturado'::text)), (0)::numeric) AS receita_faturada
   FROM (public.partner_orders po
     JOIN public.partner_accounts pa ON ((pa.id = po.partner_id)))
  GROUP BY ((date_trunc('month'::text, po.created_at))::date), pa.id, pa.razao_social, pa.commercial_region, pa.partner_type;


ALTER VIEW public.vw_bi_commercial_revenue OWNER TO postgres;

--
-- Name: vw_bi_estoque_produto; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_bi_estoque_produto AS
 SELECT ep.id,
    ep.produto_id,
    l.microrganismo_id,
    p.nome AS nome_produto,
    m.nome AS nome_microrganismo,
    COALESCE(ep.volume_total, (0)::numeric) AS volume_total,
    round((COALESCE(ep.volume_total, (0)::numeric) / 1000.0), 4) AS volume_total_l,
    ep.updated_at
   FROM (((public.estoque_produto ep
     LEFT JOIN public.produtos p ON ((ep.produto_id = p.id)))
     LEFT JOIN public.lotes l ON ((ep.lote_id = l.id)))
     LEFT JOIN public.microrganismos m ON ((l.microrganismo_id = m.id)));


ALTER VIEW public.vw_bi_estoque_produto OWNER TO postgres;

