--
-- Name: vw_partner_commercial_metrics; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_partner_commercial_metrics AS
 SELECT pa.id AS partner_id,
    pa.razao_social,
    count(po.id) AS qtd_pedidos,
    COALESCE(sum(po.total), (0)::numeric) AS total_comprado,
    COALESCE(sum(po.total) FILTER (WHERE ((po.status)::text = ANY (ARRAY['aprovado'::text, 'em_producao'::text, 'pronto_entrega'::text, 'entregue'::text, 'faturado'::text]))), (0)::numeric) AS total_aprovado,
    COALESCE(sum(po.total) FILTER (WHERE ((po.status)::text = 'entregue'::text)), (0)::numeric) AS total_entregue,
    COALESCE(sum(po.total) FILTER (WHERE ((po.status)::text = 'faturado'::text)), (0)::numeric) AS total_faturado,
        CASE
            WHEN (count(po.id) > 0) THEN round((sum(po.total) / (count(po.id))::numeric), 2)
            ELSE (0)::numeric
        END AS ticket_medio,
    max(po.created_at) AS ultima_compra
   FROM (public.partner_accounts pa
     LEFT JOIN public.partner_orders po ON ((po.partner_id = pa.id)))
  GROUP BY pa.id, pa.razao_social;


ALTER VIEW public.vw_partner_commercial_metrics OWNER TO postgres;

