--
-- Name: catalogo_volumes Cliente produtor read volumes aprovados; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Cliente produtor read volumes aprovados" ON public.catalogo_volumes FOR SELECT TO authenticated USING ((platform_private.has_role(( SELECT auth.uid() AS uid), 'cliente_produtor'::public.app_role) AND (ativo = true) AND (((produto_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (public.produtos p
     JOIN public.product_technical_profiles ptp ON ((ptp.produto_id = p.id)))
  WHERE ((p.id = catalogo_volumes.produto_id) AND (p.ativo = true) AND (ptp.status_validacao = 'aprovado'::text))))) OR ((microrganismo_id IS NOT NULL) AND (EXISTS ( SELECT 1
   FROM (public.microrganismos m
     JOIN public.microorganism_technical_profiles mtp ON ((mtp.microrganismo_id = m.id)))
  WHERE ((m.id = catalogo_volumes.microrganismo_id) AND (m.ativo = true) AND (mtp.status_validacao = 'aprovado'::text))))))));


