-- Name: accounts_receivable ar_b2b_readers; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ar_b2b_readers ON public.accounts_receivable FOR SELECT TO authenticated USING (((origin_type = 'B2B_ORDER'::text) AND (platform_private.has_role(( SELECT auth.uid() AS uid), 'gestor_comercial'::public.app_role) OR platform_private.has_role(( SELECT auth.uid() AS uid), 'administrativo'::public.app_role))));


--
-- Name: accounts_receivable ar_partner_select_own_b2b; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ar_partner_select_own_b2b ON public.accounts_receivable FOR SELECT TO authenticated USING (((origin_type = 'B2B_ORDER'::text) AND platform_private.has_role(( SELECT auth.uid() AS uid), 'parceiro_b2b'::public.app_role) AND (partner_id = ( SELECT ((platform_private.b2b_commercial_context() ->> 'partner_id'::text))::uuid AS uuid))));


--
-- Name: accounts_receivable ar_producer_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ar_producer_read ON public.accounts_receivable FOR SELECT TO authenticated USING ((platform_private.has_role(( SELECT auth.uid() AS uid), 'cliente_produtor'::public.app_role) AND (customer_id = ANY (public.get_cliente_ids_for_user(( SELECT auth.uid() AS uid)))) AND (partner_id IS NULL) AND (origin_type IS DISTINCT FROM 'B2B_ORDER'::text)));


--
-- Name: accounts_receivable_installments ari_b2b_readers; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ari_b2b_readers ON public.accounts_receivable_installments FOR SELECT TO authenticated USING (((platform_private.has_role(( SELECT auth.uid() AS uid), 'gestor_comercial'::public.app_role) OR platform_private.has_role(( SELECT auth.uid() AS uid), 'administrativo'::public.app_role)) AND (EXISTS ( SELECT 1
   FROM public.accounts_receivable ar
  WHERE ((ar.id = accounts_receivable_installments.receivable_id) AND (ar.origin_type = 'B2B_ORDER'::text))))));


--
-- Name: accounts_receivable_installments ari_partner_select_own_b2b; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY ari_partner_select_own_b2b ON public.accounts_receivable_installments FOR SELECT TO authenticated USING ((platform_private.has_role(( SELECT auth.uid() AS uid), 'parceiro_b2b'::public.app_role) AND (EXISTS ( SELECT 1
   FROM public.accounts_receivable ar
  WHERE ((ar.id = accounts_receivable_installments.receivable_id) AND (ar.origin_type = 'B2B_ORDER'::text) AND (ar.partner_id = ( SELECT ((platform_private.b2b_commercial_context() ->> 'partner_id'::text))::uuid AS uuid)))))));


--
-- Name: accounts_receivable_installments ari_producer_read; Type: POLICY; Schema: public; Owner: postgres
--

