-- Name: partner_simulations partner_simulations_insert; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY partner_simulations_insert ON public.partner_simulations FOR INSERT WITH CHECK (((platform_private.has_role(( SELECT auth.uid() AS uid), 'parceiro_b2b_tecnico'::public.app_role) AND (created_by = ( SELECT auth.uid() AS uid)) AND (partner_id = public.get_user_partner_id()) AND (status <> 'convertida_pedido'::text) AND ((cliente_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.partner_user_clients puc
  WHERE ((puc.cliente_id = partner_simulations.cliente_id) AND (puc.user_id = ( SELECT auth.uid() AS uid)) AND (puc.partner_id = partner_simulations.partner_id) AND (puc.active = true)))) OR (EXISTS ( SELECT 1
   FROM public.partner_technician_clients ptc
  WHERE ((ptc.cliente_id = partner_simulations.cliente_id) AND (ptc.technician_user_id = ( SELECT auth.uid() AS uid)) AND (ptc.partner_id = partner_simulations.partner_id) AND (ptc.active = true)))))) OR (platform_private.has_role(( SELECT auth.uid() AS uid), 'parceiro_b2b'::public.app_role) AND (partner_id = public.get_user_partner_id()) AND ((cliente_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.partner_clients pc
  WHERE ((pc.partner_id = partner_simulations.partner_id) AND (pc.cliente_id = partner_simulations.cliente_id) AND (pc.active = true)))))) OR platform_private.has_role(( SELECT auth.uid() AS uid), 'administrador'::public.app_role) OR platform_private.has_role(( SELECT auth.uid() AS uid), 'gestor_comercial'::public.app_role)));


